function useLastCallback<T extends AnyFunction>(callback?: T) {
  const ref = useStateRef(callback);

  // No need for ref dependency
  // eslint-disable-next-line react-hooks-static-deps/exhaustive-deps
  return useCallback((...args: Parameters<T>) => ref.current?.(...args), []) as T;
}

function selectTabThreadParam<T extends GlobalState, K extends keyof TabThread>(
  global: T,
  chatId: string,
  threadId: ThreadId,
  key: K,
  ...[tabId = getCurrentTabId()]: TabArgs<T>
) {
  return selectTabState(global, tabId).tabThreads[chatId]?.[threadId]?.[key];
}

function selectThreadInfo<T extends GlobalState>(global: T, chatId: string, threadId: ThreadId) {
  return selectThread(global, chatId, threadId)?.threadInfo;
}

function selectThreadReadState<T extends GlobalState>(global: T, chatId: string, threadId: ThreadId) {
  return selectThread(global, chatId, threadId)?.readState;
}

function selectThreadLocalStateParam<T extends GlobalState, K extends keyof ThreadLocalState>(
  global: T,
  chatId: string,
  threadId: ThreadId,
  key: K,
) {
  return selectThreadLocalState(global, chatId, threadId)?.[key];
}

function selectThread<T extends GlobalState>(
  global: T,
  chatId: string,
  threadId: ThreadId,
) {
  const messageInfo = global.messages.byChatId[chatId];
  if (!messageInfo) {
    return undefined;
  }

  const thread = messageInfo.threadsById[threadId];
  if (!thread) {
    return undefined;
  }

  return thread;
}

function selectThreadLocalState<T extends GlobalState>(
  global: T,
  chatId: string,
  threadId: ThreadId,
) {
  return selectThread(global, chatId, threadId)?.localState;
}

function selectThreadMessagesCount(global: GlobalState, chatId: string, threadId: ThreadId) {
  const chat = selectChat(global, chatId);
  const threadInfo = selectThreadInfo(global, chatId, threadId);
  if (!chat || !threadInfo || threadInfo.messagesCount === undefined) return undefined;
  // In forum topics first message is ignored, but not in General
  if (chat.isForum && threadId !== GENERAL_TOPIC_ID) return Math.max(threadInfo.messagesCount - 1, 0);
  return threadInfo.messagesCount;
}

function selectThreadByMessage<T extends GlobalState>(global: T, message: ApiMessage) {
  const threadId = selectThreadIdFromMessage(global, message);
  if (!threadId || threadId === MAIN_THREAD_ID) {
    return undefined;
  }

  return selectThread(global, message.chatId, threadId);
}

function selectScrollOffset<T extends GlobalState>(
