  return result;
}

async function resolveBusinessChatLink({ slug }: { slug: string }) {
  const result = await invokeRequest(new GramJs.account.ResolveBusinessChatLink({
    slug,
  }), {
    shouldIgnoreErrors: true,
  });
  if (!result) return undefined;

  const chatLink = buildApiChatLink(result);

  return {
    chatLink,
  };
}

function toggleSponsoredMessages({
  enabled,
