}

async function fetchSavedMusicIds() {
  const result = await invokeRequest(new GramJs.account.GetSavedMusicIds({
    hash: DEFAULT_PRIMITIVES.BIGINT,
  }));
  if (!(result instanceof GramJs.account.SavedMusicIds)) {
    return undefined;
  }

  return result.ids.map(String);
}

function saveMusic({ audio, shouldRemove }: { audio: ApiAudio; shouldRemove?: boolean }) {
  const id = buildInputDocument(audio);
  if (!id) return undefined;

  return invokeRequest(new GramJs.account.SaveMusic({
    id,
    unsave: shouldRemove || undefined,
  }), {
    shouldReturnTrue: true,
  });
}

function useContentWidth(
  targetRef: ElementRef<HTMLElement>,
  contentRef: ElementRef<HTMLElement>,
  deps: readonly unknown[],
) {
  const isFirstRunRef = useRef(true);

  useEffect(() => {
    requestMeasure(() => {
      const target = targetRef.current;
      const content = contentRef.current;
      if (!target || !content) return;

      const { paddingLeft, paddingRight } = getComputedStyle(target);
      const width = content.scrollWidth + parseFloat(paddingLeft) + parseFloat(paddingRight) + WIDTH_OVERSHOOT;

      requestMutation(() => {
        if (!isFirstRunRef.current) {
          setExtraStyles(target, { width: `${width}px` });
          return;
        }

        isFirstRunRef.current = false;
        setExtraStyles(target, { width: `${width}px`, transition: 'none' });
        requestNextMutation(() => {
          setExtraStyles(target, { width: `${width}px`, transition: '' });
        });
      });
    });
    // eslint-disable-next-line react-hooks-static-deps/exhaustive-deps
  }, deps);
}

