  if (action instanceof GramJs.MessageActionStarGiftUnique) {
    const {
      upgrade, transferred, saved, refunded, gift, canExportAt, transferStars, fromId, peer, savedId,
      resaleAmount, prepaidUpgrade, dropOriginalDetailsStars, fromOffer, canCraftAt,
    } = action;

    const starGift = buildApiStarGift(gift);
    if (starGift.type !== 'starGiftUnique') return UNSUPPORTED_ACTION;

    return {
      mediaType: 'action',
      type: 'starGiftUnique',
      isUpgrade: upgrade,
      isTransferred: transferred,
      isSaved: saved,
      isRefunded: refunded,
      isPrepaidUpgrade: prepaidUpgrade,
      isFromOffer: fromOffer,
      gift: starGift,
      canExportAt,
      transferStars: toJSNumber(transferStars),
      fromId: fromId && getApiChatIdFromMtpPeer(fromId),
      peerId: peer && getApiChatIdFromMtpPeer(peer),
      savedId: savedId !== undefined ? buildApiPeerId(savedId, 'user') : undefined,
      resaleAmount: resaleAmount ? buildApiCurrencyAmount(resaleAmount) : undefined,
      dropOriginalDetailsStars: dropOriginalDetailsStars !== undefined
        ? toJSNumber(dropOriginalDetailsStars)
        : undefined,
      canCraftAt,
    };
  }
  if (action instanceof GramJs.MessageActionPaidMessagesPrice) {
    const {
      stars, broadcastMessagesAllowed,
    } = action;
    return {
      mediaType: 'action',
      type: 'paidMessagesPrice',
      isAllowedInChannel: broadcastMessagesAllowed,
      stars: toJSNumber(stars),
    };
  }
  if (action instanceof GramJs.MessageActionPaidMessagesRefunded) {
    const {
      stars, count,
    } = action;
    return {
      mediaType: 'action',
      type: 'paidMessagesRefunded',
      stars: toJSNumber(stars),
      count,
    };
  }
  if (action instanceof GramJs.MessageActionSuggestedPostApproval) {
    const {
      rejected, balanceTooLow, rejectComment, scheduleDate, price,
    } = action;
    return {
      mediaType: 'action',
      type: 'suggestedPostApproval',
      isRejected: Boolean(rejected),
      isBalanceTooLow: Boolean(balanceTooLow),
      rejectComment,
      scheduleDate,
      amount: price ? buildApiCurrencyAmount(price) : undefined,
    };
  }
  if (action instanceof GramJs.MessageActionSuggestedPostSuccess) {
    const { price } = action;
    return {
      mediaType: 'action',
      type: 'suggestedPostSuccess',
      amount: buildApiCurrencyAmount(price),
    };
  }
  if (action instanceof GramJs.MessageActionSuggestedPostRefund) {
    const { payerInitiated } = action;
    return {
      mediaType: 'action',
      type: 'suggestedPostRefund',
      payerInitiated: Boolean(payerInitiated),
    };
  }
  if (action instanceof GramJs.MessageActionTodoCompletions) {
    const {
      completed, incompleted,
    } = action;
    return {
      mediaType: 'action',
      type: 'todoCompletions',
      completedIds: completed,
      incompletedIds: incompleted,
    };
  }
  if (action instanceof GramJs.MessageActionTodoAppendTasks) {
    const { list } = action;
    return {
      mediaType: 'action',
      type: 'todoAppendTasks',
      items: list.map(buildTodoItem),
    };
  }
  if (action instanceof GramJs.MessageActionPollAppendAnswer) {
    const answer = buildPollAnswer(action.answer);
    if (!answer) return UNSUPPORTED_ACTION;

    return {
      mediaType: 'action',
      type: 'pollAppendAnswer',
      answer,
    };
  }
  if (action instanceof GramJs.MessageActionPollDeleteAnswer) {
    const answer = buildPollAnswer(action.answer);
    if (!answer) return UNSUPPORTED_ACTION;

    return {
      mediaType: 'action',
      type: 'pollDeleteAnswer',
      answer,
    };
  }
  if (action instanceof GramJs.MessageActionStarGiftPurchaseOffer) {
    const {
      accepted, declined, gift, price, expiresAt,
    } = action;

    const starGift = buildApiStarGift(gift);
    if (starGift.type !== 'starGiftUnique') return UNSUPPORTED_ACTION;

    return {
      mediaType: 'action',
      type: 'starGiftPurchaseOffer',
      isAccepted: accepted,
      isDeclined: declined,
      gift: starGift,
      price: buildApiCurrencyAmount(price),
      expiresAt,
    };
  }
  if (action instanceof GramJs.MessageActionStarGiftPurchaseOfferDeclined) {
    const { expired, gift, price } = action;

    const starGift = buildApiStarGift(gift);
    if (starGift.type !== 'starGiftUnique') return UNSUPPORTED_ACTION;

    return {
      mediaType: 'action',
      type: 'starGiftPurchaseOfferDeclined',
      isExpired: expired,
      gift: starGift,
      price: buildApiCurrencyAmount(price),
    };
  }
  if (action instanceof GramJs.MessageActionNewCreatorPending) {
    const { newCreatorId } = action;
    return {
      mediaType: 'action',
      type: 'newCreatorPending',
      newCreatorId: buildApiPeerId(newCreatorId, 'user'),
    };
  }
  if (action instanceof GramJs.MessageActionChangeCreator) {
    const { newCreatorId } = action;
    return {
      mediaType: 'action',
      type: 'changeCreator',
      newCreatorId: buildApiPeerId(newCreatorId, 'user'),
    };
  }
  if (action instanceof GramJs.MessageActionNoForwardsToggle) {
    const { prevValue, newValue } = action;
    return {
      mediaType: 'action',
      type: 'noForwardsToggle',
      prevValue: Boolean(prevValue),
      newValue: Boolean(newValue),
    };
  }
  if (action instanceof GramJs.MessageActionNoForwardsRequest) {
    const { expired, prevValue, newValue } = action;
    return {
      mediaType: 'action',
      type: 'noForwardsRequest',
      isExpired: expired,
      prevValue: Boolean(prevValue),
      newValue: Boolean(newValue),
    };
  }

  return UNSUPPORTED_ACTION;
}

function buildApiPhoneCallDiscardReason(reason: GramJs.TypePhoneCallDiscardReason): ApiPhoneCallDiscardReason {
  if (reason instanceof GramJs.PhoneCallDiscardReasonBusy) {
    return 'busy';
  }
  if (reason instanceof GramJs.PhoneCallDiscardReasonHangup) {
    return 'hangup';
  }
  if (reason instanceof GramJs.PhoneCallDiscardReasonMissed) {
    return 'missed';
  }

  return 'disconnect';
}

function createMockedMessageMedia(media: MockMessageMedia, mockData: MockTypes): Api.TypeMessageMedia {
  if (media.type === 'document') {
    return new Api.MessageMediaDocument({
      document: createMockedDocument(media.id, mockData),
    });
  }

  if (media.type === 'photo') {
    return new Api.MessageMediaPhoto({
      photo: createMockedPhoto(media.id, mockData),
    });
  }

  throw Error(`Unsupported media: ${String(media.type)}`);
}

