function isValidSmartGlocalTokenizeUrl(tokenizeUrl: string) {
  if (tokenizeUrl !== tokenizeUrl.trim()) {
    return false;
  }

  let parsedUrl: URL;
  try {
    parsedUrl = new URL(tokenizeUrl);
  } catch {
    return false;
  }

  const { protocol, hostname, pathname, port, username, password } = parsedUrl;
  const isSmartGlocalHost = hostname === SMART_GLOCAL_DOMAIN || hostname.endsWith(`.${SMART_GLOCAL_DOMAIN}`);

  return protocol === 'https:'
    && isSmartGlocalHost
    && pathname === SMART_GLOCAL_TOKENIZE_PATH
    && !port
    && !username
    && !password;
}

async function sendStripeCredentials<T extends GlobalState>(
  global: T,
  data: ApiCredentials['data'],
  publishableKey: string,
  ...[tabId = getCurrentTabId()]: TabArgs<T>
) {
  const body = new URLSearchParams({
    'card[number]': data.cardNumber,
    'card[exp_month]': data.expiryMonth,
    'card[exp_year]': data.expiryYear,
    'card[cvc]': data.cvv,
    'card[name]': data.cardholder,
    'card[address_zip]': data.zip,
    'card[address_country]': data.country,
  });

  const response = await fetch('https://api.stripe.com/v1/tokens', {
    method: 'POST',
    credentials: 'same-origin',
    headers: {
      'Content-Type': 'application/x-www-form-urlencoded',
      Authorization: `Bearer ${publishableKey}`,
    },
    body,
  });
  const result = await response.json();
  if (result.error) {
    const error = getStripeError(result.error);
    global = getGlobal();
    global = updateTabState(global, {
      payment: {
        ...selectTabState(global, tabId).payment,
        status: 'failed',
        error: {
          ...error,
        },
      },
    }, tabId);
    setGlobal(global);
    return;
  }
  global = getGlobal();
  global = setStripeCardInfo(global, {
    type: result.type,
    id: result.id,
  }, tabId);
  global = setPaymentStep(global, PaymentStep.Checkout, tabId);
  setGlobal(global);
}

async function sendSmartGlocalCredentials<T extends GlobalState>(
  global: T,
  data: ApiCredentials['data'],
  publicToken: string,
  ...[tabId = getCurrentTabId()]: TabArgs<T>
) {
  const params = {
    card: {
      number: data.cardNumber.replace(/\D+/g, ''),
      expiration_month: data.expiryMonth,
      expiration_year: data.expiryYear,
      security_code: data.cvv.replace(/\D+/g, ''),
    },
  };

  const tokenizeUrl = selectTabState(global, tabId).payment.form?.nativeParams.tokenizeUrl;

  let url;
  if (DEBUG_PAYMENT_SMART_GLOCAL) {
    url = 'https://tgb-playground.smart-glocal.com/cds/v1/tokenize/card';
  } else {
    url = 'https://tgb.smart-glocal.com/cds/v1/tokenize/card';
  }

  if (tokenizeUrl && isValidSmartGlocalTokenizeUrl(tokenizeUrl)) {
    url = tokenizeUrl;
  }

  const response = await fetch(url, {
    method: 'POST',
    headers: {
      Accept: 'application/json',
      'Content-Type': 'application/json',
      'X-PUBLIC-TOKEN': publicToken,
    },
    body: JSON.stringify(params),
  });
  const result = await response.json();

  if (result.status !== 'ok') {
    // TODO после получения документации сделать аналог getStripeError(result.error);
    const error = { descriptionKey: { key: 'ErrorUnexpected' } satisfies RegularLangFnParameters };
    global = getGlobal();
    global = updateTabState(global, {
      payment: {
        ...selectTabState(global, tabId).payment,
        status: 'failed',
        error: {
          ...error,
        },
      },
    }, tabId);
    setGlobal(global);
    return;
  }

  global = getGlobal();
  global = setSmartGlocalCardInfo(global, {
    type: 'card',
    token: result.data.token,
  }, tabId);
  global = setPaymentStep(global, PaymentStep.Checkout, tabId);
  setGlobal(global);
}

async function validateRequestedInfo<T extends GlobalState>(
  global: T, inputInvoice: ApiRequestInputInvoice, requestInfo: any, shouldSave?: boolean,
  ...[tabId = getCurrentTabId()]: TabArgs<T>
) {
  const result = await callApi('validateRequestedInfo', {
    inputInvoice, requestInfo, shouldSave,
  });
  if (!result) {
    return;
  }

  const { id, shippingOptions } = result;
  global = getGlobal();

  global = setRequestInfoId(global, id, tabId);
  if (shippingOptions?.length) {
    global = updateShippingOptions(global, shippingOptions, tabId);
    global = setPaymentStep(global, PaymentStep.Shipping, tabId);
  } else {
    global = setPaymentStep(global, PaymentStep.Checkout, tabId);
  }
  setGlobal(global);
}

async function payInputStarInvoice<T extends GlobalState>(
  global: T, inputInvoice: ApiInputInvoice, price: number,
  ...[tabId = getCurrentTabId()]: TabArgs<T>
) {
  const actions = getActions();
  const isTon = inputInvoice.type === 'stargiftResale' && inputInvoice.currency === TON_CURRENCY_CODE;
  const balance = isTon ? global.ton?.balance : global.stars?.balance;
  const currency = isTon ? TON_CURRENCY_CODE : STARS_CURRENCY_CODE;

  if (balance === undefined) return;

  if (balance.amount < price) {
    actions.openStarsBalanceModal({ currency, tabId });
    return;
  }

  const requestInputInvoice = getRequestInputInvoice(global, inputInvoice);
  if (!requestInputInvoice) {
    return;
  }

  global = updateTabState(global, {
    isPaymentFormLoading: true,
  }, tabId);
  setGlobal(global);

  const theme = extractCurrentThemeParams();
  const form = await callApi('getPaymentForm', requestInputInvoice, theme);

  if (!form) {
    return;
  }

  global = getGlobal();

  global = updateTabState(global, {
    isPaymentFormLoading: false,
  }, tabId);
  setGlobal(global);

  if ('error' in form) {
    handlePaymentFormError(form.error, tabId);
    return;
  }

  const formPrice = form.invoice.totalAmount;
  if (formPrice !== price) {
    actions.openPriceConfirmModal({
      originalAmount: price,
      newAmount: formPrice,
      currency,
      directInfo: {
        inputInvoice,
        formId: form.formId,
      },
      tabId,
    });
    return;
  }

  actions.sendStarPaymentForm({
    directInfo: {
      inputInvoice,
      formId: form.formId,
    },
    tabId,
  });
}

function handlePaymentFormError(error: string, tabId: number) {
  if (error === 'SLUG_INVALID') {
    getActions().showNotification({
      message: {
        key: 'PaymentInvoiceNotFound',
      },
      tabId,
    });
    return;
  }

  getActions().showDialog({ data: { type: 'error', message: error, hasErrorKey: true }, tabId });
}

async function init(invokeReq: typeof invokeRequest) {
  invoke = invokeReq;

  await loadRemoteState();
  isInited = true;

  scheduleGetDifference();
}

function applyState(state: State) {
  localDb.commonBoxState.seq = state.seq;
  localDb.commonBoxState.date = state.date;
  localDb.commonBoxState.pts = state.pts;
  localDb.commonBoxState.qts = state.qts;
}

function processUpdate(update: Update, isFromDifference?: boolean, shouldOnlySave?: boolean) {
  if (update instanceof UpdateConnectionState) {
    if (update.state === UpdateConnectionState.connected && isInited) {
      scheduleGetDifference();
    }

    updater(update);
    return;
  }

  if (update instanceof UpdateServerTimeOffset) {
    updater(update);
    return;
  }

  if (update instanceof UpdateSessionGap) {
    if (isInited) scheduleGetDifference();
    return;
  }

  if (localDb.commonBoxState.seq === undefined) {
    // Drop updates received before first sync
    return;
  }

  if (update instanceof GramJs.Updates || update instanceof GramJs.UpdatesCombined) {
    if (isFromDifference) {
      (update as SeqUpdate)._isFromDifference = true;
    }

    saveSeqUpdate(update, shouldOnlySave);
    return;
  }

  if ('pts' in update) {
    if (update instanceof GramJs.UpdateChannelTooLong) {
      scheduleChannelDifference(getUpdateChannelId(update), 'gapRecovery', 0);
      return;
    }
    if (isFromDifference) {
      (update as PtsUpdate)._isFromDifference = true;
    }
    savePtsUpdate(update, shouldOnlySave);
    return;
  }

  updater(update);
}

function updateChannelState(channelId: string, pts: number) {
  const channel = localDb.chats[channelId];
  if (!(channel instanceof GramJs.Channel)) {
    if (DEBUG) {
      // eslint-disable-next-line no-console
      console.error(`[UpdateManager] Channel ${channelId} not found in localDb`);
    }
    return;
  }

  const currentState = localDb.channelPtsById[channelId];

  if (currentState && currentState < pts) {
    scheduleGetChannelDifference(channelId);
    return;
  }

  localDb.channelPtsById[channelId] = pts;
}

function applyUpdate(updateObject: SeqUpdate | PtsUpdate) {
  if ('seq' in updateObject && updateObject.seq) {
    localDb.commonBoxState.seq = updateObject.seq;
    localDb.commonBoxState.date = updateObject.date;
  }

  if ('qts' in updateObject) {
    localDb.commonBoxState.qts = updateObject.qts;
  }

  if ('pts' in updateObject) {
    const channelId = getUpdateChannelId(updateObject);
    if (channelId !== COMMON_BOX_QUEUE_ID) {
      localDb.channelPtsById[channelId] = updateObject.pts;
    } else {
      localDb.commonBoxState.pts = updateObject.pts;
    }
  }

  if (updateObject instanceof GramJs.UpdatesCombined || updateObject instanceof GramJs.Updates) {
    processAndUpdateEntities(updateObject);
    const entities = (updateObject.users as Entity[]).concat(updateObject.chats);

    updateObject.updates.forEach((update) => {
      if (entities) {
        (update as any)._entities = entities;
      }

      processUpdate(update);
    });
  } else {
    updater(updateObject);
  }
}

function saveSeqUpdate(update: GramJs.Updates | GramJs.UpdatesCombined, shouldOnlySave?: boolean) {
  SEQ_QUEUE.add(update);

  if (!shouldOnlySave) popSeqQueue();
}

function savePtsUpdate(update: PtsUpdate, shouldOnlySave?: boolean) {
  const channelId = getUpdateChannelId(update);

  const ptsQueue = PTS_QUEUE.get(channelId) || new SortedQueue<PtsUpdate>(ptsComparator);
  ptsQueue.add(update);

  PTS_QUEUE.set(channelId, ptsQueue);

  if (!shouldOnlySave) popPtsQueue(channelId);
}

function popSeqQueue() {
  if (!SEQ_QUEUE.size) return;

  const update = SEQ_QUEUE.pop()!;
  const localSeq = localDb.commonBoxState.seq;
  const seqStart = 'seqStart' in update ? update.seqStart : update.seq;

  if (seqStart === 0 || (update._isFromDifference && seqStart >= localSeq + 1)) {
    applyUpdate(update);
  } else if (seqStart === localSeq + 1) {
    clearTimeout(seqTimeout);
    seqTimeout = undefined;

    applyUpdate(update);
  } else if (seqStart > localSeq + 1) {
    SEQ_QUEUE.add(update); // Return update to queue
    scheduleGetDifference();
    return; // Prevent endless loop
  }

  popSeqQueue();
}

function popPtsQueue(channelId: string) {
  const ptsQueue = PTS_QUEUE.get(channelId);
  if (!ptsQueue?.size) return;

  const update = ptsQueue.pop()!;
  const localPts = channelId === COMMON_BOX_QUEUE_ID ? localDb.commonBoxState.pts : localDb.channelPtsById[channelId];
  const pts = update.pts;
  const ptsCount = getPtsCount(update);

  // Sometimes server sends updates for channels that are opened in other clients. We ignore them
  if (localPts === undefined) {
    if (DEBUG) {
      // Uncomment to debug missing updates

      // console.error('[UpdateManager] Got pts update without local state', channelId);
    }
    return;
  }

  if (update._isFromDifference && pts >= localPts + ptsCount) {
    applyUpdate(update);
  } else if (pts === localPts + ptsCount) {
    clearScheduledChannelDifference(channelId, 'gapRecovery');
    scheduleShortpollFromNow(channelId);

    applyUpdate(update);
  } else if (pts > localPts + ptsCount) {
    ptsQueue.add(update); // Return update to queue
    if (channelId === COMMON_BOX_QUEUE_ID) {
      scheduleGetDifference();
    } else {
      scheduleGetChannelDifference(channelId);
    }
    return; // Prevent endless loop
  }

  popPtsQueue(channelId);
}

function scheduleGetChannelDifference(channelId: string) {
  scheduleChannelDifference(channelId, 'gapRecovery', UPDATE_WAIT_TIMEOUT);
}

function requestChannelDifference(channelId: string) {
  scheduleChannelDifference(channelId, 'gapRecovery', 0);
}

function setOpenedChannelIds(channelIds: string[]) {
  const nextOpenedChannelIds = new Set(channelIds);

  OPENED_CHANNEL_IDS.forEach((channelId) => {
    if (nextOpenedChannelIds.has(channelId)) {
      return;
    }

    getOrCreateChannelScheduler(channelId).isShortpollEligible = false;
    clearScheduledChannelDifference(channelId, 'shortpoll');
  });

  channelIds.forEach((channelId) => {
    const scheduler = getOrCreateChannelScheduler(channelId);
    const wasOpened = OPENED_CHANNEL_IDS.has(channelId);

    scheduler.isShortpollEligible = true;

    if (!wasOpened) {
      if (scheduler.shortpollTimeoutMs !== undefined) {
        restartShortpollFromNow(channelId);
      } else {
        scheduleChannelDifference(channelId, 'shortpoll', INITIAL_SHORTPOLL_TIMEOUT_MS);
      }
    }
  });

  OPENED_CHANNEL_IDS.clear();
  channelIds.forEach((channelId) => {
    OPENED_CHANNEL_IDS.add(channelId);
  });
}

function getOrCreateChannelScheduler(channelId: string) {
  const current = CHANNEL_SCHEDULERS.get(channelId);
  if (current) {
    return current;
  }

  const scheduler: ChannelScheduler = {
    isInFlight: false,
  };
  CHANNEL_SCHEDULERS.set(channelId, scheduler);
  return scheduler;
}

function scheduleChannelDifference(channelId: string, reason: ChannelDifferenceReason, timeoutMs: number) {
  const scheduler = getOrCreateChannelScheduler(channelId);
  const deadline = Date.now() + timeoutMs;
  if (scheduler.deadline !== undefined && scheduler.deadline <= deadline) {
    return;
  }

  clearScheduledChannelDifference(channelId);

  scheduler.reason = reason;
  scheduler.deadline = deadline;
  scheduler.timeout = setTimeout(() => {
    scheduler.timeout = undefined;
    scheduler.deadline = undefined;
    if (scheduler.isInFlight) {
      scheduleChannelDifference(channelId, reason, UPDATE_WAIT_TIMEOUT);
      return;
    }

    void runChannelDifference(channelId, reason);
  }, timeoutMs);
}

function clearScheduledChannelDifference(channelId: string, reason?: ChannelDifferenceReason) {
  const scheduler = CHANNEL_SCHEDULERS.get(channelId);
  if (!scheduler?.timeout || (reason && scheduler.reason !== reason)) {
    return;
  }

  clearTimeout(scheduler.timeout);
  scheduler.timeout = undefined;
  scheduler.deadline = undefined;
  scheduler.reason = undefined;
}

function scheduleShortpollFromNow(channelId: string) {
  const scheduler = CHANNEL_SCHEDULERS.get(channelId);
  if (!scheduler?.isShortpollEligible || scheduler.shortpollTimeoutMs === undefined) {
    return;
  }

  scheduleChannelDifference(channelId, 'shortpoll', scheduler.shortpollTimeoutMs);
}

function restartShortpollFromNow(channelId: string) {
  const scheduler = CHANNEL_SCHEDULERS.get(channelId);
  if (!scheduler?.isShortpollEligible || scheduler.shortpollTimeoutMs === undefined || scheduler.isInFlight) {
    return;
  }

  if (scheduler.reason === 'shortpoll') {
    clearScheduledChannelDifference(channelId);
  }

  scheduleChannelDifference(channelId, 'shortpoll', scheduler.shortpollTimeoutMs);
}

function scheduleGetDifference() {
  if (seqTimeout) return;

  seqTimeout = setTimeout(async () => {
    await getDifference();
    seqTimeout = undefined;
  }, UPDATE_WAIT_TIMEOUT);
}

function getUpdateChannelId(update: Update) {
  if ('channelId' in update && 'pts' in update) {
    return buildApiPeerId(update.channelId, 'channel');
  }

  if (update instanceof GramJs.UpdateNewChannelMessage || update instanceof GramJs.UpdateEditChannelMessage) {
    const peer = update.message.peerId as GramJs.PeerChannel;
    return buildApiPeerId(peer.channelId, 'channel');
  }

  return COMMON_BOX_QUEUE_ID;
}

async function getDifference() {
  if (!isInited) {
    throw new Error('UpdatesManager not initialized');
  }

  if (!localDb.commonBoxState?.date) {
    forceSync();
    return;
  }

  sendApiUpdate({
    '@type': 'updateFetchingDifference',
    isFetching: true,
  });

  const response = await invoke(new GramJs.updates.GetDifference({
    pts: localDb.commonBoxState.pts,
    date: localDb.commonBoxState.date,
    qts: localDb.commonBoxState.qts,
  }));

  if (!response || response instanceof GramJs.updates.DifferenceTooLong) {
    forceSync();
    return;
  }

  if (response instanceof GramJs.updates.DifferenceEmpty) {
    localDb.commonBoxState.seq = response.seq;
    localDb.commonBoxState.date = response.date;
    sendApiUpdate({
      '@type': 'updateFetchingDifference',
      isFetching: false,
    });
    return;
  }

  processDifference(response);

  const newState = response instanceof GramJs.updates.DifferenceSlice ? response.intermediateState : response.state;
  applyState(newState);

  if (response instanceof GramJs.updates.DifferenceSlice) {
    getDifference();
    return;
  }

  sendApiUpdate({
    '@type': 'updateFetchingDifference',
    isFetching: false,
  });
}

async function runChannelDifference(channelId: string, reason: ChannelDifferenceReason) {
  const scheduler = getOrCreateChannelScheduler(channelId);
  if (scheduler.isInFlight) {
    return;
  }

  scheduler.isInFlight = true;
  scheduler.reason = reason;

  try {
    await requestChannelDifferenceInternal(channelId, reason);
  } finally {
    scheduler.isInFlight = false;
  }
}

async function requestChannelDifferenceInternal(channelId: string, reason: ChannelDifferenceReason): Promise<void> {
  const channel = localDb.chats[channelId];
  if (
    !channel
    || !(channel instanceof GramJs.Channel)
    || !channel.accessHash
    || localDb.channelPtsById[channelId] === undefined
  ) {
    if (DEBUG) {
      // eslint-disable-next-line no-console
      console.error('[UpdateManager] Channel for difference not found', channelId, channel);
    }
    return;
  }

  const limit = reason === 'shortpoll' ? SHORTPOLL_CHANNEL_DIFFERENCE_LIMIT : CATCH_UP_CHANNEL_DIFFERENCE_LIMIT;
  let response: GramJs.updates.TypeChannelDifference;

  try {
    const result = await invoke(new GramJs.updates.GetChannelDifference({
      channel: buildInputChannel(channelId, channel.accessHash.toString()),
      pts: localDb.channelPtsById[channelId],
      filter: new GramJs.ChannelMessagesFilterEmpty(),
      limit,
    }), {
      shouldThrow: true,
    });
    if (!result) {
      return;
    }

    response = result;
  } catch (err) {
    handleChannelDifferenceError(channelId, reason, err);
    return;
  }

  if (response instanceof GramJs.updates.ChannelDifferenceTooLong) {
    forceSync();
    return;
  }

  localDb.channelPtsById[channelId] = response.pts;
  updateChannelShortpollTimeout(channelId, response);

  if (response instanceof GramJs.updates.ChannelDifferenceEmpty) {
    if (response.final) {
      scheduleShortpollIfEligible(channelId);
    }

    popPtsQueue(channelId); // Continue processing updates in queue
    return;
  }

  processDifference(response, channelId);

  if (!response.final) {
    await requestChannelDifferenceInternal(channelId, 'gapRecovery');
    return;
  }

  scheduleShortpollIfEligible(channelId);
}

function updateChannelShortpollTimeout(channelId: string, response: GramJs.updates.TypeChannelDifference) {
  const scheduler = getOrCreateChannelScheduler(channelId);
  scheduler.shortpollTimeoutMs = ('timeout' in response && response.timeout)
    ? response.timeout * 1000
    : SHORTPOLL_DEFAULT_TIMEOUT_MS;
}

function scheduleShortpollIfEligible(channelId: string) {
  const scheduler = getOrCreateChannelScheduler(channelId);
  if (!scheduler.isShortpollEligible) {
    return;
  }

  scheduleShortpollFromNow(channelId);
}

function handleChannelDifferenceError(channelId: string, reason: ChannelDifferenceReason, err: unknown) {
  if (DEBUG) {
    // eslint-disable-next-line no-console
    console.warn('[UpdatesManager] Failed to get ChannelDifference', channelId, err);
  }

  const scheduler = getOrCreateChannelScheduler(channelId);
  const errorMessage = err instanceof RPCError ? err.errorMessage : undefined;

  if (errorMessage && TERMINAL_CHANNEL_DIFFERENCE_ERRORS.has(errorMessage)) {
    scheduler.isShortpollEligible = false;
    clearScheduledChannelDifference(channelId);
    return;
  }

  scheduleChannelDifference(channelId, reason, CHANNEL_DIFFERENCE_RETRY_TIMEOUT_MS);
}

function forceSync() {
  reset();

  sendApiUpdate({
    '@type': 'requestSync',
  });

  loadRemoteState();
}

function reset() {
  PTS_QUEUE.clear();
  SEQ_QUEUE.clear();

  clearTimeout(seqTimeout);
  seqTimeout = undefined;

  CHANNEL_SCHEDULERS.forEach(({ timeout }) => {
    if (!timeout) {
      return;
    }

    clearTimeout(timeout);
  });
  CHANNEL_SCHEDULERS.clear();
  OPENED_CHANNEL_IDS.clear();

  localDb.commonBoxState = {};

  Object.keys(localDb.channelPtsById).forEach((channelId) => {
    localDb.channelPtsById[channelId] = 0;
  });

  isInited = false;
}

function processAffectedHistory(
  chat: ApiChat, affected: GramJs.messages.AffectedMessages | GramJs.messages.AffectedHistory,
) {
  const isChannel = chat.type === 'chatTypeChannel' || chat.type === 'chatTypeSuperGroup';
  const channeId = isChannel ? buildMtpPeerId(chat.id, 'channel') : undefined;
  const update = buildLocalUpdatePts(affected.pts, affected.ptsCount, channeId);

  processUpdate(update);
}

async function loadRemoteState() {
  const remoteState = await invoke(new GramJs.updates.GetState());
  if (!remoteState) return;

  applyState(remoteState);

  isInited = true;
}

function processDifference(
  difference: GramJs.updates.Difference | GramJs.updates.DifferenceSlice | GramJs.updates.ChannelDifference,
  channelId?: string,
) {
  difference.newMessages.forEach((message) => {
    updater(new GramJs.UpdateNewMessage({
      message,
      pts: 0,
      ptsCount: 0,
    }));
  });

  processAndUpdateEntities(difference);

  // Ignore `pts`/`seq` holes when applying updates from difference
  // BUT, if we got an `UpdateChannelTooLong`, make sure to process other updates after receiving `ChannelDifference`
  const channelTooLongIds = new Set<string>();

  difference.otherUpdates.forEach((update) => {
    const updateChannelId = getUpdateChannelId(update);

    if (update instanceof GramJs.UpdateChannelTooLong) {
      channelTooLongIds.add(getUpdateChannelId(update));
    }

    const shouldApplyImmediately = !channelTooLongIds.has(updateChannelId);
    processUpdate(update, shouldApplyImmediately, !shouldApplyImmediately);
  });

  // Continue processing updates in queues
  if (channelId) {
    popPtsQueue(channelId);
  } else {
    popSeqQueue();
  }
}

function getPtsCount(update: PtsUpdate) {
  return 'ptsCount' in update ? update.ptsCount : 0;
}

function seqComparator(a: SeqUpdate, b: SeqUpdate) {
  const seqA = 'seqStart' in a ? a.seqStart : a.seq;
  const seqB = 'seqStart' in b ? b.seqStart : b.seq;

  return seqA - seqB;
}

function ptsComparator(a: PtsUpdate, b: PtsUpdate) {
  const diff = a.pts - b.pts;
  if (diff !== 0) {
    return diff;
  }

  return getPtsCount(b) - getPtsCount(a);
}

function abortChatRequests(chatId: string, threadId?: ThreadId) {
  callApi('abortChatRequests', { chatId, threadId });
}

function abortChatRequestsForCurrentChat<T extends GlobalState>(
  global: T, newChatId?: string, newThreadId?: ThreadId,
  ...[tabId = getCurrentTabId()]: TabArgs<T>
) {
  const currentMessageList = selectCurrentMessageList(global, tabId);
  const currentChatId = currentMessageList?.chatId;
  const currentThreadId = currentMessageList?.threadId;

  if (currentChatId && (currentChatId !== newChatId || currentThreadId !== newThreadId)) {
    const [isChatOpened, isThreadOpened] = Object.values(global.byTabId)
      .reduce(([accHasChatOpened, accHasThreadOpened], { id: otherTabId }) => {
        if (otherTabId === tabId || (accHasChatOpened && accHasThreadOpened)) {
          return [accHasChatOpened, accHasThreadOpened];
        }

        const otherMessageList = selectCurrentMessageList(global, otherTabId);
        const isSameChat = otherMessageList?.chatId === currentChatId;
        const isSameThread = isSameChat && otherMessageList?.threadId === currentThreadId;

        return [accHasChatOpened || isSameChat, accHasThreadOpened || isSameThread];
      }, [currentChatId === newChatId, false]);

    const shouldAbortChatRequests = !isChatOpened || !isThreadOpened;

    if (shouldAbortChatRequests) {
      abortChatRequests(currentChatId, isChatOpened ? currentThreadId : undefined);
    }
  }
}

async function checkFutureCreatorAndOpenModal(
  chat: ApiChat,
  shouldSkipOwnershipCheck: boolean | undefined,
  tabId: number,
): Promise<boolean> {
  if (shouldSkipOwnershipCheck || !chat.isOwner) {
    return false;
  }

  const futureCreator = await callApi('fetchFutureCreatorAfterLeave', { chat });
  if (!futureCreator) {
    return false;
  }

  const global = getGlobal();
  const hasPassword = global.settings.byKey.hasPassword;
  const actions = getActions();
  if (!hasPassword) {
    actions.openTwoFaCheckModal({ tabId });
    return true;
  }

  actions.openLeaveGroupModal({ chatId: chat.id, nextOwnerId: futureCreator.id, tabId });
  return true;
}

function cleanupAfterLeave(chatId: string, tabId: number) {
  let global = getGlobal();
  global = leaveChat(global, chatId);
  setGlobal(global);

  if (selectCurrentMessageList(global, tabId)?.chatId === chatId) {
    getActions().openChat({ id: undefined, tabId });
  }

  global = getGlobal();
  const chatMessages = selectChatMessages(global, chatId);
  if (!chatMessages) {
    return;
  }

  const localMessageIds = Object.keys(chatMessages).map(Number).filter(isLocalMessageId);
  if (!localMessageIds.length) {
    return;
  }

  global = deleteChatMessages(global, chatId, localMessageIds);
  setGlobal(global);
}

async function loadChats(
  listType: ChatListType,
  isFullDraftSync?: boolean,
  shouldIgnorePagination?: boolean,
) {
  let global = getGlobal();
  const globalBeforeLoad = global;
  const lastLocalServiceMessageId = selectLastServiceNotification(global)?.id;

  const params = !shouldIgnorePagination ? selectChatListLoadingParameters(global, listType) : {};
  const offsetPeer = params.nextOffsetPeerId ? selectPeer(global, params.nextOffsetPeerId) : undefined;
  const offsetDate = params.nextOffsetDate;
  const offsetId = params.nextOffsetId;

  const isFirstBatch = !shouldIgnorePagination && !offsetPeer && !offsetDate && !offsetId;
  const shouldReplaceStaleState = listType === 'active' && isFirstBatch;
  const isAccountFreeze = selectIsCurrentUserFrozen(global);
  const currentUser = selectUser(global, global.currentUserId!)!;

  const result = listType === 'saved' ? await callApi('fetchSavedChats', {
    parentPeer: currentUser,
    limit: CHAT_LIST_LOAD_SLICE,
    offsetDate,
    offsetId,
    offsetPeer,
    withPinned: isFirstBatch && !isAccountFreeze,
  }) : await callApi('fetchChats', {
    limit: CHAT_LIST_LOAD_SLICE,
    offsetDate,
    offsetId,
    offsetPeer,
    archived: listType === 'archived',
    withPinned: isFirstBatch && !isAccountFreeze,
    lastLocalServiceMessageId,
  });

  if (!result) {
    return;
  }

  const { chatIds } = result;

  global = getGlobal();

  const newChats = buildCollectionByKey(result.chats, 'id');

  global = updateUsers(global, buildCollectionByKey(result.users, 'id'));
  global = updateChats(global, newChats);
  if (isFirstBatch) {
    global = replaceChatListIds(global, listType, chatIds);
  } else {
    global = addChatListIds(global, listType, chatIds);
  }

  if (shouldReplaceStaleState) {
    global = replaceUserStatuses(global, result.userStatusesById);
    global = replaceNotifyExceptions(global, result.notifyExceptionById);
  } else {
    global = addUserStatuses(global, result.userStatusesById);
    global = addNotifyExceptions(global, result.notifyExceptionById);
  }

  global = updateChatListSecondaryInfo(global, listType, result);
  global = updateChatsLastMessageId(global, result.lastMessageByChatId, listType);

  if (!shouldIgnorePagination) {
    global = replaceChatListLoadingParameters(
      global, listType, result.nextOffsetId, result.nextOffsetPeerId, result.nextOffsetDate,
    );
  }

  if (isFullDraftSync) {
    result.threadInfos.forEach((threadInfo) => {
      global = updateThreadInfo(global, threadInfo);
    });
    if (result.threadReadStatesById) {
      global = updateMainThreadReadStates(global, result.threadReadStatesById);
    }
  }

  if (listType === 'active' || listType === 'archived') {
    const idsToUpdateDraft = isFullDraftSync ? result.chatIds : Object.keys(result.draftsById);

    idsToUpdateDraft.forEach((chatId) => {
      const draft = result.draftsById[chatId];
      const thread = selectThread(global, chatId, MAIN_THREAD_ID);
      if (!isFullDraftSync && !draft && !thread) return;

      const initialDraft = selectDraft(globalBeforeLoad, chatId, MAIN_THREAD_ID);
      const currentDraft = selectDraft(global, chatId, MAIN_THREAD_ID);
      const shouldKeepLocalDraft = currentDraft?.isLocal;
      if (shouldKeepLocalDraft || shouldKeepCurrentDraft(currentDraft, initialDraft, draft)) return;

      global = replaceThreadLocalStateParam(
        global, chatId, MAIN_THREAD_ID, 'draft', draft,
      );
    });
  }

  if (
    (result.isFullyLoaded || chatIds.length === 0 || chatIds.length === result.totalChatCount)
    && !global.chats.isFullyLoaded[listType]
  ) {
    global = {
      ...global,
      chats: {
        ...global.chats,
        isFullyLoaded: {
          ...global.chats.isFullyLoaded,
          [listType]: true,
        },
      },
    };
  }

  setGlobal(global);

  return {
    messages: result.messages,
  };
}

function shouldKeepCurrentDraft(
  currentDraft: ApiDraft | undefined,
  initialDraft: ApiDraft | undefined,
  loadedDraft: ApiDraft | undefined,
) {
  if (currentDraft === initialDraft) return false;
  if (!currentDraft || currentDraft.isLocal) return true;

  return Boolean(currentDraft.date && (!loadedDraft?.date || currentDraft.date >= loadedDraft.date));
}

async function loadFullChat<T extends GlobalState>(
  global: T, actions: RequiredGlobalActions, chat: ApiChat,
) {
  if (selectIsCurrentUserFrozen(global)) return undefined;
  const result = await callApi('fetchFullChat', chat);
  if (!result) {
    return undefined;
  }

  const {
    chats, userStatusesById, fullInfo, groupCall, membersCount, isForumAsMessages,
  } = result;

  global = getGlobal();
  global = updateChats(global, buildCollectionByKey(chats, 'id'));

  if (userStatusesById) {
    global = addUserStatuses(global, userStatusesById);
  }

  if (groupCall) {
    const existingGroupCall = selectGroupCall(global, groupCall.id!);
    global = updateGroupCall(
      global,
      groupCall.id!,
      omit(groupCall, ['connectionState', 'isLoaded']),
      undefined,
      existingGroupCall ? undefined : groupCall.participantsCount,
    );
  }

  if (membersCount !== undefined) {
    global = updateChat(global, chat.id, { membersCount });
  }
  if (chat.isForum) {
    global = updateChat(global, chat.id, { isForumAsMessages });
  }
  global = replaceChatFullInfo(global, chat.id, fullInfo);
  setGlobal(global);

  const stickerSet = fullInfo.stickerSet;
  const localSet = stickerSet && selectStickerSet(global, stickerSet);
  if (stickerSet && !localSet) {
    actions.loadStickers({
      stickerSetInfo: {
        id: stickerSet.id,
        accessHash: stickerSet.accessHash,
      },
    });
  }

  const emojiSet = fullInfo.emojiSet;
  const localEmojiSet = emojiSet && selectStickerSet(global, emojiSet);
  if (emojiSet && !localEmojiSet) {
    actions.loadStickers({
      stickerSetInfo: {
        id: emojiSet.id,
        accessHash: emojiSet.accessHash,
      },
    });
  }

  return result;
}

async function migrateChat<T extends GlobalState>(
  global: T, actions: RequiredGlobalActions, chat: ApiChat,
  ...[tabId = getCurrentTabId()]: TabArgs<T>
): Promise<ApiChat | undefined> {
  try {
    const supergroup = await callApi('migrateChat', chat);

    return supergroup;
  } catch (error) {
    if ((error as ApiError).message === 'CHANNELS_TOO_MUCH') {
      actions.openLimitReachedModal({ limit: 'channels', tabId });
    } else {
      actions.showDialog({ data: { type: 'error', ...(error as ApiError), hasErrorKey: true }, tabId });
    }

    return undefined;
  }
}

async function fetchChatByUsername<T extends GlobalState>(
  global: T,
  username: string,
  referrer?: string,
) {
  global = getGlobal();
  const localChat = !referrer ? selectChatByUsername(global, username) : undefined;
  if (localChat && !localChat.isMin) {
    return localChat;
  }

  const { chat, user } = await callApi('getChatByUsername', username, referrer) || {};
  if (!chat) {
    return undefined;
  }

  global = getGlobal();
  global = updateChat(global, chat.id, chat);
  if (user) {
    global = updateUser(global, user.id, user);
  }

  setGlobal(global);

  return chat;
}

async function checkWebAppExists<T extends GlobalState>(
  global: T, botName: string, appName: string,
) {
  if (!botName || !appName) return false;
  global = getGlobal();
  const chatByUsername = await fetchChatByUsername(global, botName);
  global = getGlobal();
  const bot = chatByUsername && selectUser(global, chatByUsername.id);
  const botApp = bot && await callApi('fetchBotApp', {
    bot,
    appName,
  });
  return Boolean(botApp);
}

async function fetchChatByPhoneNumber<T extends GlobalState>(global: T, phoneNumber: string) {
  global = getGlobal();
  const localUser = selectUserByPhoneNumber(global, phoneNumber);
  if (localUser && !localUser.isMin) {
    return selectChat(global, localUser.id);
  }

  const { chat, user } = await callApi('getChatByPhoneNumber', phoneNumber) || {};
  if (!chat) {
    return undefined;
  }

  global = getGlobal();
  global = updateChat(global, chat.id, chat);

  if (user) {
    global = updateUser(global, user.id, user);
  }
  setGlobal(global);

  return chat;
}

async function getAttachBotOrNotify<T extends GlobalState>(
  global: T, actions: RequiredGlobalActions, username: string,
  ...[tabId = getCurrentTabId()]: TabArgs<T>
) {
  const chat = await fetchChatByUsername(global, username);
  if (!chat) return undefined;

  global = getGlobal();
  const user = selectUser(global, chat.id);
  if (!user) return undefined;

  const isBot = isUserBot(user);
  if (!isBot) return undefined;
  const result = await callApi('loadAttachBot', {
    bot: user,
  });

  global = getGlobal();
  if (!result) {
    actions.showNotification({
      message: langProvider.oldTranslate('WebApp.AddToAttachmentUnavailableError'),
      tabId,
    });

    return undefined;
  }
  setGlobal(global);

  return result.bot;
}

async function openChatByUsername<T extends GlobalState>(
  global: T,
  actions: RequiredGlobalActions,
  params: {
    username: string;
    threadId?: ThreadId;
    channelPostId?: number;
    startParam?: string;
    ref?: string;
    startAttach?: string;
    attach?: string;
    text?: string;
    timestamp?: number;
    linkContext?: LinkContext;
    isDirect?: boolean;
  },
  ...[tabId = getCurrentTabId()]: TabArgs<T>
) {
  const {
    username, threadId, channelPostId, startParam, ref, startAttach, attach, text, timestamp,
    linkContext, isDirect,
  } = params;
  const currentChat = selectCurrentChat(global, tabId);

  // Attach in the current chat
  if (startAttach !== undefined && !attach) {
    const bot = await getAttachBotOrNotify(global, actions, username, tabId);

    if (!bot) return;

    actions.callAttachBot({
      bot,
      chatId: currentChat?.id || bot.id,
      startParam: startAttach,
      tabId,
    });

    return;
  }

  const localChat = selectChatByUsername(global, username);
  const localDirectChat = isDirect && localChat?.linkedMonoforumId && !localChat.isMonoforum
    ? selectChat(global, localChat.linkedMonoforumId) : undefined;

  const isCurrentChat = !isDirect
    ? currentChat?.usernames?.some((c) => c.username === username)
    : localDirectChat?.id === currentChat?.id;

  if (!isCurrentChat) {
    // Open temporary empty chat to make the click response feel faster
    actions.openChat({ id: TMP_CHAT_ID, tabId });
  }

  const starRefStartPrefixes = global.appConfig.starRefStartPrefixes;
  let referrer = ref;
  if (startParam && starRefStartPrefixes?.length) {
    const prefix = starRefStartPrefixes.find((p) => startParam.startsWith(p));
    if (prefix) {
      referrer = startParam.slice(prefix.length);
    }
  }

  const chat = await fetchChatByUsername(global, username, referrer);
  if (!chat) {
    if (!isCurrentChat) {
      actions.openPreviousChat({ tabId });
      actions.showNotification({ message: 'User does not exist', tabId });
    }

    return;
  }

  const monoforumChat = isDirect && !chat.isMonoforum && chat.linkedMonoforumId
    ? selectChat(global, chat.linkedMonoforumId) : undefined;

  const targetChat = (isDirect && monoforumChat) || chat;

  openChatWithParams(global, actions, targetChat, {
    isCurrentChat,
    threadId,
    messageId: channelPostId,
    startParam,
    referrer,
    startAttach,
    attach,
    text,
    timestamp,
    linkContext,
  }, tabId);
}

async function openChatWithParams<T extends GlobalState>(
  global: T,
  actions: RequiredGlobalActions,
  chat: ApiChat,
  params: {
    isCurrentChat?: boolean;
    threadId?: ThreadId;
    messageId?: number;
    startParam?: string;
    referrer?: string;
    startAttach?: string;
    attach?: string;
    text?: string;
    timestamp?: number;
    linkContext?: LinkContext;
  },
  ...[tabId = getCurrentTabId()]: TabArgs<T>
) {
  const {
    isCurrentChat, threadId, messageId, startParam, referrer, startAttach, attach, text, timestamp,
    linkContext,
  } = params;

  if (messageId) {
    let isTopicProcessed = false;
    // In forums, link to a topic start message should open the topic
    if (chat.isForum && !threadId) {
      let topic = selectTopics(global, chat.id)?.[messageId];
      if (!topic) {
        const topicResult = await callApi('fetchTopicById', { chat, topicId: messageId });
        topic = topicResult?.topic.topic;
      }

      if (topic) {
        actions.openThread({
          chatId: chat.id, threadId: topic.id, tabId,
        });
        isTopicProcessed = true;
      }
    }

    if (!isTopicProcessed) {
      actions.focusMessage({
        chatId: chat.id, threadId, messageId, timestamp, tabId,
        replyMessageId: linkContext?.type === 'message' ? linkContext.messageId : undefined,
      });
    }
  } else if (!isCurrentChat) {
    actions.openThread({ chatId: chat.id, threadId: threadId ?? MAIN_THREAD_ID, tabId });
  }

  if (startParam && !referrer) {
    actions.startBot({ botId: chat.id, param: startParam, tabId });
  }

  if (attach) {
    global = getGlobal();
    openAttachMenuFromLink(global, actions, chat.id, attach, startAttach, tabId);
  }

  if (text) {
    actions.openChatWithDraft({ chatId: chat.id, text: { text }, tabId });
  }

  if (messageId && timestamp) {
    actions.openMediaFromTimestamp({
      chatId: chat.id, threadId, messageId, timestamp, tabId,
    });
  }
}

async function openAttachMenuFromLink<T extends GlobalState>(
  global: T,
  actions: RequiredGlobalActions,
  chatId: string,
  attach: string,
  startAttach?: string | boolean,
  ...[tabId = getCurrentTabId()]: TabArgs<T>
) {
  global = getGlobal();
  const bot = await getAttachBotOrNotify(global, actions, attach, tabId);
  if (!bot) return;

  actions.callAttachBot({
    bot,
    chatId,
    ...(typeof startAttach === 'string' && { startParam: startAttach }),
    tabId,
  });
}

async function ensureIsSuperGroup<T extends GlobalState>(
  global: T,
  actions: RequiredGlobalActions,
  chatId: string,
  ...[tabId = getCurrentTabId()]: TabArgs<T>
) {
  const chat = selectChat(global, chatId);
  if (!chat || !isChatBasicGroup(chat)) {
    return chat;
  }

  const newChat = await migrateChat(global, actions, chat, tabId);
  if (!newChat) {
    return undefined;
  }

  actions.loadFullChat({ chatId: newChat.id });
  actions.openChat({ id: newChat.id, tabId });

  return newChat;
}

function stopScrollInertia(element: HTMLElement) {
  element.style.display = 'none';
  forceReflow(element);
  element.style.display = '';
}

class MTProtoState {
  private readonly authKey?: AuthKey;

  private _log: any;

  timeOffset: number;

  private hasSynchronizedServerTime = false;

  private currentServerSalt?: bigint;

  private serverSalts: ServerSalt[];

  private id: bigint;

  _sequence: number;

  _isCall: boolean;

  _isOutgoing: boolean;

  private _lastMsgId: bigint;

  private remoteMsgIds: bigint[];

  private remoteMessages: Map<bigint, RemoteMessage>;

  private readonly replayedMessages = new WeakSet<TLMessage>();

  /**
   *
   `telethon.network.mtprotosender.MTProtoSender` needs to hold a state
   in order to be able to encrypt and decrypt incoming/outgoing messages,
   as well as generating the message IDs. Instances of this class hold
   together all the required information.

   It doesn't make sense to use `telethon.sessions.abstract.Session` for
   the sender because the sender should *not* be concerned about storing
   this information to disk, as one may create as many senders as they
   desire to any other data center, or some CDN. Using the same session
   for all these is not a good idea as each need their own authkey, and
   the concept of "copying" sessions with the unnecessary entities or
   updates state for these connections doesn't make sense.

   While it would be possible to have a `MTProtoPlainState` that does no
   encryption so that it was usable through the `MTProtoLayer` and thus
   avoid the need for a `MTProtoPlainSender`, the `MTProtoLayer` is more
   focused to efficiency and this state is also more advanced (since it
   supports gzipping and invoking after other message IDs). There are too
   many methods that would be needed to make it convenient to use for the
   authentication process, at which point the `MTProtoPlainSender` is better
   * @param authKey
   * @param loggers
   * @param isCall
   * @param isOutgoing
   */
  constructor(authKey?: AuthKey, loggers?: Logger, isCall = false, isOutgoing = false) {
    this.authKey = authKey;
    this._log = loggers;
    this._isCall = isCall;
    this._isOutgoing = isOutgoing;
    this.timeOffset = 0;
    this.serverSalts = [];

    this.id = 0n;
    this._sequence = 0;
    this._lastMsgId = 0n;
    this.remoteMsgIds = [];
    this.remoteMessages = new Map();
    this.reset();
  }

  /**
   * Resets the state
   */
  reset() {
    // Session IDs can be random on every connection
    this.id = generateRandomLong(true);
    this._sequence = 0;
    this._lastMsgId = 0n;
    this.remoteMsgIds = [];
    this.remoteMessages.clear();
  }

  resetForNewAuthKey() {
    this.hasSynchronizedServerTime = false;
    this.currentServerSalt = undefined;
    this.serverSalts = [];
    this.reset();
  }

  getServerTime() {
    return Math.floor(Date.now() / 1000) + this.timeOffset;
  }

  getIncomingMessageState(msgId: bigint, isAcknowledged: boolean) {
    if ((msgId & 1n) !== SERVER_MSG_ID_PARITY) return MESSAGE_STATE_UNKNOWN;

    const remoteMessage = this.remoteMessages.get(msgId);
    if (remoteMessage) {
      // https://core.telegram.org/mtproto/service_messages_about_messages#informational-message-regarding-status-of-messages
      return MESSAGE_STATE_RECEIVED
        + (remoteMessage.isContentRelated
          ? (isAcknowledged ? MESSAGE_STATE_ACKNOWLEDGED : 0)
          : MESSAGE_STATE_NO_ACK_REQUIRED);
    }

    const retainedFloor = this.remoteMsgIds[0];
    if (retainedFloor === undefined || msgId < retainedFloor) return MESSAGE_STATE_UNKNOWN;
    if (msgId > this.remoteMsgIds[this.remoteMsgIds.length - 1]) return MESSAGE_STATE_TOO_NEW;

    return MESSAGE_STATE_NOT_RECEIVED;
  }

  setServerSalt(salt: bigint, shouldResetFutureSalts?: boolean) {
    const serverTime = this.getServerTime();
    const previousSalt = this.currentServerSalt;
    const knownSalt = !shouldResetFutureSalts && this.serverSalts.find((serverSalt) => (
      serverSalt.salt === salt
      && serverSalt.validSince <= serverTime
      && (serverSalt.validUntil === undefined || serverTime < serverSalt.validUntil)
    ));
    if (previousSalt === salt && knownSalt) return;

    const retainedSalts = shouldResetFutureSalts ? [] : this.serverSalts.filter((serverSalt) => (
      (serverSalt.validUntil === undefined || serverSalt.validUntil > serverTime)
      && serverSalt.salt !== salt
      && serverSalt.salt !== previousSalt
    ));
    if (previousSalt !== undefined && previousSalt !== salt) {
      const previousEntry = this.serverSalts.find(({ salt: storedSalt }) => (
        storedSalt === previousSalt
      ));
      retainedSalts.push({
        salt: previousSalt,
        validSince: previousEntry?.validSince ?? serverTime,
        validUntil: previousEntry?.validUntil ?? serverTime + SERVER_SALT_GRACE_PERIOD,
      });
    }

    this.currentServerSalt = salt;
    this.serverSalts = [
      ...retainedSalts,
      knownSalt && (knownSalt.validUntil === undefined || knownSalt.validUntil > serverTime) ? knownSalt : {
        salt,
        validSince: serverTime,
      },
    ]
      .sort((firstSalt, secondSalt) => firstSalt.validSince - secondSalt.validSince)
      .slice(-MAX_STORED_SERVER_SALTS);
  }

  setFutureSalts(salts: readonly Api.TypeFutureSalt[]) {
    if (salts.length > MAX_FUTURE_SERVER_SALTS || salts.some(({ validSince, validUntil }) => (
      !Number.isInteger(validSince)
      || !Number.isInteger(validUntil)
      || validSince >= validUntil
    ))) {
      return false;
    }

    const serverTime = this.getServerTime();
    const futureSalts = salts
      .map(({ salt, validSince, validUntil }) => ({ salt, validSince, validUntil }))
      .sort((firstSalt, secondSalt) => firstSalt.validSince - secondSalt.validSince);
    const retainedSalts = this.serverSalts.filter(({ salt, validUntil }) => (
      (validUntil === undefined || validUntil > serverTime)
      && !futureSalts.some(({ salt: futureSalt }) => futureSalt === salt)
    ));
    this.serverSalts = [...retainedSalts, ...futureSalts]
      .sort((firstSalt, secondSalt) => firstSalt.validSince - secondSalt.validSince)
      .slice(-MAX_STORED_SERVER_SALTS);

    this.selectServerSalt(serverTime);
    return true;
  }

  consumeMessageReplay(message: TLMessage) {
    return this.replayedMessages.delete(message);
  }

  /**
   * Updates the message ID to a new one,
   * used when the time offset changed.
   * @param message
   */
  updateMessageId(message: TLMessage) {
    message.msgId = this._getNewMsgId();
  }

  /**
   * Calculate the key based on Telegram guidelines, specifying whether it's the client or not
   */
  async _calcKey(
    authKey: Uint8Array, msgKey: Uint8Array, client: boolean,
  ): Promise<{ key: Uint8Array; iv: Uint8Array }> {
    const x = this._isCall
      ? (128 + (this._isOutgoing !== client ? 8 : 0))
      : (client ? 0 : 8);
    const [sha256a, sha256b] = await Promise.all([
      sha256(concat(msgKey, authKey.slice(x, x + 36))),
      sha256(concat(authKey.slice(x + 40, x + 76), msgKey)),
    ]);
    const key = concat(sha256a.slice(0, 8), sha256b.slice(8, 24), sha256a.slice(24, 32));
    if (this._isCall) {
      const iv = concat(sha256b.slice(0, 4), sha256a.slice(8, 16), sha256b.slice(24, 28));

      return {
        key,
        iv,
      };
    }
    const iv = concat(sha256b.slice(0, 8), sha256a.slice(8, 24), sha256b.slice(24, 32));
    return {
      key,
      iv,
    };
  }

  /**
   * Writes a message containing the given data into buffer.
   * Returns the message metadata.
   * @param buffer
   * @param data
   * @param contentRelated
   * @param afterId
   */
  writeDataAsMessage(
    buffer: BinaryWriter, data: Uint8Array, contentRelated: boolean, afterId?: bigint,
  ): { msgId: bigint; seqNo: number } {
    const msgId = this._getNewMsgId();
    const seqNo = this._getSeqNo(contentRelated);
    let body;
    if (afterId === undefined) {
      body = GZIPPacked.gzipIfNeeded(contentRelated, data);
    } else {
      // Invoke query expects a query with a getBytes func
      body = GZIPPacked.gzipIfNeeded(contentRelated, new Api.InvokeAfterMsg({
        msgId: afterId,
        query: {
          getBytes() {
            return data;
          },
        },
      }).getBytes());
    }
    const s = new Uint8Array(4);
    writeInt32LE(s, seqNo);
    const b = new Uint8Array(4);
    writeInt32LE(b, body.length);
    const m = toSignedLittleBuffer(msgId, 8);
    buffer.write(concat(m, s, b));
    buffer.write(body);
    return { msgId, seqNo };
  }

  /**
   * Encrypts the given message data using the current authorization key
   * following MTProto 2.0 guidelines core.telegram.org/mtproto/description.
   * @param data
   */
  async encryptMessageData(data: Uint8Array): Promise<Uint8Array> {
    if (!this.authKey) {
      throw new Error('Auth key unset');
    }

    await this.authKey.waitForKey();
    const authKey = this.authKey.getKey();
    if (!authKey) {
      throw new Error('Auth key unset');
    }

    if (this.authKey.keyId === undefined) {
      throw new Error('Unset params');
    }

    if (this._isCall) {
      const x = 128 + (this._isOutgoing ? 0 : 8);
      const lengthStart = data.length;

      data = new Uint8Array(data);
      if (lengthStart % 4 !== 0) {
        data = concat(data, new Uint8Array(4 - (lengthStart % 4)).fill(0x20));
      }

      const msgKeyLarge = await sha256(concat(authKey
        .slice(88 + x, 88 + x + 32), data));

      const msgKey = msgKeyLarge.slice(8, 24);

      const {
        iv,
        key,
      } = await this._calcKey(authKey, msgKey, true);

      data = new CTR(key, iv).encrypt(data);
      // data = data.slice(0, lengthStart)
      return concat(msgKey, data);
    } else {
      const s = toSignedLittleBuffer(this.getServerSalt(), 8);
      const i = toSignedLittleBuffer(this.id, 8);
      data = concat(s, i, data);
      const padding = generateRandomBytes(mod(-(data.length + 12), 16) + 12);
      // Being substr(what, offset, length); x = 0 for client
      // "msg_key_large = SHA256(substr(auth_key, 88+x, 32) + pt + padding)"
      const msgKeyLarge = await sha256(concat(authKey
        .slice(88, 88 + 32), data, padding));
      // "msg_key = substr (msg_key_large, 8, 16)"
      const msgKey = msgKeyLarge.slice(8, 24);

      const {
        iv,
        key,
      } = await this._calcKey(authKey, msgKey, true);

      const keyId = readBufferFromBigInt(this.authKey.keyId, 8);
      return concat(keyId, msgKey, new IGE(key, iv).encryptIge(concat(data, padding)));
    }
  }

  /**
   * Inverse of `encrypt_message_data` for incoming server messages.
   * @param body
   */
  async decryptMessageData(
    body: Uint8Array,
    canSkipTimeValidation?: CanSkipTimeValidation,
  ) {
    const receivedAt = Math.floor(Date.now() / 1000);

    if (!this.authKey) {
      throw new Error('Auth key unset');
    }

    if (this._isCall && body.length < 8) {
      throw new InvalidBufferError(body);
    }
    if (!this._isCall && body.length === 4) {
      throw new InvalidBufferError(body);
    }
    if (!this._isCall && (body.length < ENCRYPTED_MESSAGE_EXTERNAL_HEADER_LENGTH
      || (body.length - ENCRYPTED_MESSAGE_EXTERNAL_HEADER_LENGTH) % 16 !== 0)) {
      throw new SecurityError();
    }
    let hasInvalidEncryptedPacket = false;
    if (!this._isCall) {
      const keyId = readBigIntFromBuffer(body.slice(0, 8));
      hasInvalidEncryptedPacket = keyId !== this.authKey.keyId;
    }
    const authKey = this.authKey.getKey();
    if (!authKey) {
      throw new SecurityError('Unset AuthKey');
    }
    const msgKey = this._isCall ? body.slice(0, 16) : body.slice(8, 24);

    const x = this._isCall ? 128 + (this._isOutgoing ? 8 : 0) : 0;
    const {
      iv,
      key,
    } = await this._calcKey(authKey, msgKey, false);

    if (this._isCall) {
      body = body.slice(16);
      const lengthStart = body.length;

      body = concat(body, new Uint8Array(4 - (lengthStart % 4)));

      body = new CTR(key, iv).decrypt(body);

      body = body.slice(0, lengthStart);
    } else {
      try {
        body = new IGE(key, iv).decryptIge(body.slice(ENCRYPTED_MESSAGE_EXTERNAL_HEADER_LENGTH));
      } catch {
        throw new SecurityError();
      }
    }

    const ourKey = this._isCall
      ? await sha256(concat(authKey
        .slice(88 + x, 88 + x + 32), body))
      : await sha256(concat(authKey
        .slice(96, 96 + 32), body));

    if (!this._isCall) {
      // https://core.telegram.org/mtproto/security_guidelines#checking-sha256-hash-value-of-msg-key
      // Complete the hash check even when an earlier packet check failed
      hasInvalidEncryptedPacket = !compareBuffersConstantTime(msgKey, ourKey.slice(8, 24))
        || hasInvalidEncryptedPacket;
    }
    if (!this._isCall && body.length < ENCRYPTED_MESSAGE_HEADER_LENGTH) {
      throw new SecurityError();
    }
    const reader = new BinaryReader(body);

    if (this._isCall) {
      // Seq
      reader.readInt(false);
      return reader.read(body.length - 4);
    } else {
      const serverSalt = reader.readLong();
      const serverId = reader.readLong();
      hasInvalidEncryptedPacket = serverId !== this.id || hasInvalidEncryptedPacket;

      const remoteMsgId = reader.readLong();
      const remoteSequence = reader.readInt();
      const messageBodyLength = reader.readInt();
      const remainingPlaintextLength = body.length - ENCRYPTED_MESSAGE_HEADER_LENGTH;
      const paddingLength = remainingPlaintextLength - messageBodyLength;

      // https://core.telegram.org/mtproto/security_guidelines#checking-message-length
      if (messageBodyLength < 0 || messageBodyLength % TL_ALIGNMENT !== 0
        || messageBodyLength > remainingPlaintextLength
        || paddingLength < MIN_ENCRYPTED_MESSAGE_PADDING
        || paddingLength > MAX_ENCRYPTED_MESSAGE_PADDING) {
        hasInvalidEncryptedPacket = true;
      }

      if (hasInvalidEncryptedPacket) throw new SecurityError();

      const messageReader = reader.createSubReader(messageBodyLength);
      const obj = messageReader.tgReadObject();
      if (messageReader.tellPosition() !== messageBodyLength) {
        throw new SecurityError();
      }
      const message = new TLMessage(remoteMsgId, remoteSequence, obj);
      this.validateIncomingMessages(
        message, receivedAt, canSkipTimeValidation,
      );
      if (this.currentServerSalt === undefined) {
        this.setServerSalt(serverSalt);
      }

      return message;
    }
  }

  private validateIncomingMessages(
    message: TLMessage,
    receivedAt: number,
    canSkipTimeValidation?: CanSkipTimeValidation,
  ) {
    const incomingMessages: TLMessage[] = [];
    this.collectIncomingMessages(message, incomingMessages);
    const canSkipPacketTimeValidation = this.canSkipMessageTimeValidation(message, canSkipTimeValidation);

    const retainedFloor = this.remoteMsgIds[0];
    if (this._lastMsgId !== 0n) {
      if ((message.msgId & 1n) !== SERVER_MSG_ID_PARITY) {
        throw new SecurityError();
      }
      if (this.remoteMessages.has(message.msgId)) {
        this.replayedMessages.add(message);
        return;
      }
      if (retainedFloor !== undefined && message.msgId < retainedFloor) {
        throw new SecurityError('Server message is older than retained history');
      }

      this.synchronizeServerTime(message.msgId, receivedAt);
    }

    let previousIncomingMsgId: bigint | undefined;
    let areIncomingMessagesOrdered = true;
    let newMessageCount = 0;

    // https://core.telegram.org/mtproto/security_guidelines#checking-msg-id
    for (const incomingMessage of incomingMessages) {
      const { msgId, seqNo } = incomingMessage;

      if ((msgId & 1n) !== SERVER_MSG_ID_PARITY) {
        throw new SecurityError();
      }
      if (this.remoteMessages.has(msgId)) {
        this.replayedMessages.add(incomingMessage);
        continue;
      }
      if (retainedFloor !== undefined && msgId < retainedFloor) {
        throw new SecurityError('Server message is older than retained history');
      }
      if (seqNo < 0) {
        throw new SecurityError();
      }
      if (this.hasTooManyMessageIds(incomingMessage.obj)) {
        throw new SecurityError();
      }
      if (this.isMessageSequenceInvalid(incomingMessage)) {
        throw new SecurityError();
      }
      if (this.isMessageTimeInvalid(msgId, receivedAt) && !canSkipPacketTimeValidation) {
        throw new SecurityError();
      }

      if (previousIncomingMsgId !== undefined && previousIncomingMsgId >= msgId) {
        areIncomingMessagesOrdered = false;
      }
      previousIncomingMsgId = msgId;
      incomingMessages[newMessageCount++] = incomingMessage;
    }
    incomingMessages.length = newMessageCount;

    if (!areIncomingMessagesOrdered) {
      incomingMessages.sort(({ msgId: firstMsgId }, { msgId: secondMsgId }) => (
        firstMsgId < secondMsgId ? -1 : (firstMsgId > secondMsgId ? 1 : 0)
      ));
    }

    // https://core.telegram.org/mtproto/description#message-sequence-number-msg-seqno
    for (let index = 0; index < incomingMessages.length; index++) {
      const incomingMessage = incomingMessages[index];
      const previousIncomingMessage = incomingMessages[index - 1];
      if (previousIncomingMessage?.msgId === incomingMessage.msgId) {
        throw new SecurityError();
      }

      const insertionIndex = this.getRemoteMessageInsertionIndex(incomingMessage.msgId);
      const previousRemoteMsgId = this.remoteMsgIds[insertionIndex - 1];
      const nextRemoteMsgId = this.remoteMsgIds[insertionIndex];
      let previousSeqNo = previousRemoteMsgId === undefined
        ? undefined
        : this.remoteMessages.get(previousRemoteMsgId)!.seqNo;
      if (previousIncomingMessage
        && (previousRemoteMsgId === undefined || previousIncomingMessage.msgId > previousRemoteMsgId)) {
        previousSeqNo = previousIncomingMessage.seqNo;
      }
      const nextIncomingMessage = incomingMessages[index + 1];
      let nextSeqNo = nextRemoteMsgId === undefined
        ? undefined
        : this.remoteMessages.get(nextRemoteMsgId)!.seqNo;
      if (nextIncomingMessage
        && (nextRemoteMsgId === undefined || nextIncomingMessage.msgId < nextRemoteMsgId)) {
        nextSeqNo = nextIncomingMessage.seqNo;
      }
      const hasInvalidPreviousSequence = previousSeqNo !== undefined
        && this.isMessageSequenceOrderInvalid(previousSeqNo, incomingMessage.seqNo);
      const hasInvalidNextSequence = nextSeqNo !== undefined
        && this.isMessageSequenceOrderInvalid(incomingMessage.seqNo, nextSeqNo);
      if (hasInvalidPreviousSequence || hasInvalidNextSequence) {
        throw new SecurityError();
      }
    }

    this.rememberIncomingMessages(incomingMessages);
  }

  private getRemoteMessageInsertionIndex(msgId: bigint) {
    let startIndex = 0;
    let endIndex = this.remoteMsgIds.length;
    while (startIndex < endIndex) {
      const middleIndex = (startIndex + endIndex) >> 1;
      if (this.remoteMsgIds[middleIndex] < msgId) {
        startIndex = middleIndex + 1;
      } else {
        endIndex = middleIndex;
      }
    }
    return startIndex;
  }

  private isMessageSequenceOrderInvalid(previousSeqNo: number, nextSeqNo: number) {
    return previousSeqNo > nextSeqNo
      || (previousSeqNo === nextSeqNo && (previousSeqNo & 1) === 1);
  }

  private rememberIncomingMessages(incomingMessages: TLMessage[]) {
    const previousLength = this.remoteMsgIds.length;
    this.remoteMsgIds.length += incomingMessages.length;

    let previousIndex = previousLength - 1;
    let incomingIndex = incomingMessages.length - 1;
    let targetIndex = this.remoteMsgIds.length - 1;
    while (incomingIndex >= 0) {
      const incomingMsgId = incomingMessages[incomingIndex].msgId;
      if (previousIndex >= 0 && this.remoteMsgIds[previousIndex] > incomingMsgId) {
        this.remoteMsgIds[targetIndex--] = this.remoteMsgIds[previousIndex--];
      } else {
        this.remoteMsgIds[targetIndex--] = incomingMsgId;
        incomingIndex--;
      }
    }

    for (const incomingMessage of incomingMessages) {
      this.remoteMessages.set(incomingMessage.msgId, {
        isContentRelated: incomingMessage.isContentRelated,
        seqNo: incomingMessage.seqNo,
      });
    }

    if (this.remoteMsgIds.length <= MAX_BUFFERED_REMOTE_MESSAGES) return;

    const discardedCount = this.remoteMsgIds.length - REMOTE_MESSAGE_HISTORY_SIZE;

    for (let index = 0; index < discardedCount; index++) {
      this.remoteMessages.delete(this.remoteMsgIds[index]);
    }
    this.remoteMsgIds.copyWithin(0, discardedCount);
    this.remoteMsgIds.length = REMOTE_MESSAGE_HISTORY_SIZE;
  }

  private hasTooManyMessageIds(obj: unknown) {
    return (obj instanceof Api.MsgsAck
      || obj instanceof Api.MsgsStateReq
      || obj instanceof Api.MsgResendReq)
    && obj.msgIds.length > MAX_MESSAGE_IDS;
  }

  private isMessageSequenceInvalid(message: TLMessage) {
    // https://core.telegram.org/mtproto/service_messages#new-session-creation-notification
    if (message.obj.CONSTRUCTOR_ID === Api.NewSessionCreated.CONSTRUCTOR_ID) {
      return !message.isContentRelated;
    }

    // https://core.telegram.org/mtproto/description#content-related-message
    return message.isContentRelated
      && FORBIDDEN_CONTENT_RELATED_CONSTRUCTOR_IDS.has(message.obj.CONSTRUCTOR_ID);
  }

  private collectIncomingMessages(
    message: TLMessage,
    incomingMessages: TLMessage[],
    containerMsgId?: bigint,
  ) {
    this.unwrapGzipPacked(message);

    // https://core.telegram.org/mtproto/service_messages#simple-container
    if (containerMsgId !== undefined && message.msgId >= containerMsgId) {
      throw new SecurityError();
    }

    if (message.obj instanceof MessageContainer) {
      if (containerMsgId !== undefined) {
        throw new SecurityError();
      }

      for (const innerMessage of message.obj.messages) {
        this.collectIncomingMessages(innerMessage, incomingMessages, message.msgId);
      }
    }

    incomingMessages.push(message);
  }

  private unwrapGzipPacked(message: TLMessage) {
    while (message.obj instanceof GZIPPacked) {
      const { data } = message.obj;
      const reader = new BinaryReader(data);
      const obj = reader.tgReadObject();

      // https://core.telegram.org/api/invoking#decompressing-data
      if (obj instanceof MessageContainer || reader.tellPosition() !== data.length) {
        throw new SecurityError();
      }
      message.obj = obj;
    }
  }

  private isMessageTimeInvalid(msgId: bigint, receivedAt: number) {
    const remoteTime = Number(msgId >> 32n);
    const timeDelta = receivedAt + this.timeOffset - remoteTime;
    return timeDelta > MAX_INCOMING_MESSAGE_AGE
      || timeDelta < -MAX_INCOMING_MESSAGE_FUTURE_OFFSET;
  }

  private synchronizeServerTime(msgId: bigint, receivedAt: number) {
    const timeOffset = Number(msgId >> 32n) - receivedAt;
    if (this.hasSynchronizedServerTime && timeOffset <= this.timeOffset) return;

    this.timeOffset = timeOffset;
    this.hasSynchronizedServerTime = true;
  }

  private canSkipMessageTimeValidation(
    message: TLMessage,
    canSkipTimeValidation?: CanSkipTimeValidation,
  ): boolean {
    if (!canSkipTimeValidation) return false;
    if (message.obj instanceof MessageContainer) {
      return message.obj.messages.some((innerMessage) => (
        this.canSkipMessageTimeValidation(innerMessage, canSkipTimeValidation)
      ));
    }

    // https://core.telegram.org/mtproto/service_messages_about_messages#notice-of-ignored-error-message
    const {
      CONSTRUCTOR_ID: constructorId, badMsgId, badMsgSeqno, errorCode,
    } = message.obj;
    const isApplicableBadServerSalt = constructorId === Api.BadServerSalt.CONSTRUCTOR_ID
      && errorCode === BAD_SERVER_SALT_ERROR_CODE;
    const isApplicableBadMsg = constructorId === Api.BadMsgNotification.CONSTRUCTOR_ID
      && INVALID_TIME_ERROR_CODES.has(errorCode);
    if (!isApplicableBadServerSalt && !isApplicableBadMsg) return false;

    return canSkipTimeValidation(badMsgId, badMsgSeqno);
  }

  private getServerSalt() {
    this.selectServerSalt(this.getServerTime());
    return this.currentServerSalt ?? 0n;
  }

  private selectServerSalt(serverTime: number) {
    for (let i = this.serverSalts.length - 1; i >= 0; i--) {
      const serverSalt = this.serverSalts[i];
      if (serverSalt.validSince <= serverTime
        && (serverSalt.validUntil === undefined || serverTime < serverSalt.validUntil)) {
        const previousSalt = this.currentServerSalt;
        if (previousSalt !== undefined && previousSalt !== serverSalt.salt) {
          const previousEntry = this.serverSalts.find(({ salt }) => salt === previousSalt);
          this.serverSalts = [
            ...this.serverSalts.filter(({ salt, validUntil }) => (
              (validUntil === undefined || validUntil > serverTime)
              && salt !== previousSalt
            )),
            {
              salt: previousSalt,
              validSince: previousEntry?.validSince ?? serverTime,
              validUntil: previousEntry?.validUntil ?? serverTime + SERVER_SALT_GRACE_PERIOD,
            },
          ]
            .sort((firstSalt, secondSalt) => firstSalt.validSince - secondSalt.validSince)
            .slice(-MAX_STORED_SERVER_SALTS);
        }
        this.currentServerSalt = serverSalt.salt;
        return;
      }
    }
  }

  /**
   * Generates a new unique message ID based on the current
   * time (in ms) since epoch, applying a known time offset.
   * @private
   */
  _getNewMsgId() {
    let newMsgId = this.getTimeBasedMessageId();
    if (this._lastMsgId >= newMsgId) {
      newMsgId = this._lastMsgId + MESSAGE_ID_ALIGNMENT;
    }
    if ((newMsgId & MESSAGE_ID_LOW_MASK) === 0n) newMsgId += MESSAGE_ID_ALIGNMENT;

    this._lastMsgId = newMsgId;
    return newMsgId;
  }

  /**
   * Updates the time offset to the correct
   * one given a known valid message ID.
   * @param correctMsgId {bigint}
   */
  updateTimeOffset(correctMsgId: bigint) {
    const bad = this.getTimeBasedMessageId();
    const old = this.timeOffset;
    let isSessionReset = false;
    const now = Math.floor(Date.now() / 1000);
    const correct = Number(correctMsgId >> 32n);
    this.timeOffset = correct - now;
    this.hasSynchronizedServerTime = true;

    if (this.timeOffset !== old) {
      const nextMsgId = this._lastMsgId + MESSAGE_ID_ALIGNMENT;
      const latestAllowedMsgId = this.getTimeBasedMessageId()
        + BigInt(MAX_INCOMING_MESSAGE_FUTURE_OFFSET) * MESSAGE_ID_SCALE;

      // https://core.telegram.org/mtproto/description#message-identifier-msg-id
      // Keep monotonicity unless the corrected clock would make the next ID invalid
      if (this.timeOffset < old && nextMsgId > latestAllowedMsgId) {
        this.reset();
        isSessionReset = true;
      }

      this._log.debug(
        // eslint-disable-next-line @stylistic/max-len
        `Updated time offset (old offset ${old}, bad ${bad.toString()}, good ${correctMsgId.toString()}, new ${this.timeOffset})`,
      );
    }

    return { timeOffset: this.timeOffset, isSessionReset };
  }

  private getTimeBasedMessageId() {
    const timestampMilliseconds = BigInt(Date.now())
      + BigInt(this.timeOffset) * MILLISECONDS_PER_SECOND;
    const messageId = timestampMilliseconds * MESSAGE_ID_SCALE / MILLISECONDS_PER_SECOND;
    return messageId - messageId % MESSAGE_ID_ALIGNMENT;
  }

  /**
   * Generates the next sequence number depending on whether
   * it should be for a content-related query or not.
   * @param contentRelated
   * @private
   */
  _getSeqNo(contentRelated: boolean) {
    if (contentRelated) {
      const result = this._sequence * 2 + 1;
      this._sequence += 1;
      return result;
    } else {
      return this._sequence * 2;
    }
  }
}

constructor(authKey?: AuthKey, loggers?: Logger, isCall = false, isOutgoing = false) {
    this.authKey = authKey;
    this._log = loggers;
    this._isCall = isCall;
    this._isOutgoing = isOutgoing;
    this.timeOffset = 0;
    this.serverSalts = [];

    this.id = 0n;
    this._sequence = 0;
    this._lastMsgId = 0n;
    this.remoteMsgIds = [];
    this.remoteMessages = new Map();
    this.reset();
  }

reset() {
    // Session IDs can be random on every connection
    this.id = generateRandomLong(true);
    this._sequence = 0;
    this._lastMsgId = 0n;
    this.remoteMsgIds = [];
    this.remoteMessages.clear();
  }

resetForNewAuthKey() {
    this.hasSynchronizedServerTime = false;
    this.currentServerSalt = undefined;
    this.serverSalts = [];
    this.reset();
  }

getServerTime() {
    return Math.floor(Date.now() / 1000) + this.timeOffset;
  }

getIncomingMessageState(msgId: bigint, isAcknowledged: boolean) {
    if ((msgId & 1n) !== SERVER_MSG_ID_PARITY) return MESSAGE_STATE_UNKNOWN;

    const remoteMessage = this.remoteMessages.get(msgId);
    if (remoteMessage) {
      // https://core.telegram.org/mtproto/service_messages_about_messages#informational-message-regarding-status-of-messages
      return MESSAGE_STATE_RECEIVED
        + (remoteMessage.isContentRelated
          ? (isAcknowledged ? MESSAGE_STATE_ACKNOWLEDGED : 0)
          : MESSAGE_STATE_NO_ACK_REQUIRED);
    }

    const retainedFloor = this.remoteMsgIds[0];
    if (retainedFloor === undefined || msgId < retainedFloor) return MESSAGE_STATE_UNKNOWN;
    if (msgId > this.remoteMsgIds[this.remoteMsgIds.length - 1]) return MESSAGE_STATE_TOO_NEW;

    return MESSAGE_STATE_NOT_RECEIVED;
  }

setServerSalt(salt: bigint, shouldResetFutureSalts?: boolean) {
    const serverTime = this.getServerTime();
    const previousSalt = this.currentServerSalt;
    const knownSalt = !shouldResetFutureSalts && this.serverSalts.find((serverSalt) => (
      serverSalt.salt === salt
      && serverSalt.validSince <= serverTime
      && (serverSalt.validUntil === undefined || serverTime < serverSalt.validUntil)
    ));
    if (previousSalt === salt && knownSalt) return;

    const retainedSalts = shouldResetFutureSalts ? [] : this.serverSalts.filter((serverSalt) => (
      (serverSalt.validUntil === undefined || serverSalt.validUntil > serverTime)
      && serverSalt.salt !== salt
      && serverSalt.salt !== previousSalt
    ));
    if (previousSalt !== undefined && previousSalt !== salt) {
      const previousEntry = this.serverSalts.find(({ salt: storedSalt }) => (
        storedSalt === previousSalt
      ));
      retainedSalts.push({
        salt: previousSalt,
        validSince: previousEntry?.validSince ?? serverTime,
        validUntil: previousEntry?.validUntil ?? serverTime + SERVER_SALT_GRACE_PERIOD,
      });
    }

    this.currentServerSalt = salt;
    this.serverSalts = [
      ...retainedSalts,
      knownSalt && (knownSalt.validUntil === undefined || knownSalt.validUntil > serverTime) ? knownSalt : {
        salt,
        validSince: serverTime,
      },
    ]
      .sort((firstSalt, secondSalt) => firstSalt.validSince - secondSalt.validSince)
      .slice(-MAX_STORED_SERVER_SALTS);
  }

setFutureSalts(salts: readonly Api.TypeFutureSalt[]) {
    if (salts.length > MAX_FUTURE_SERVER_SALTS || salts.some(({ validSince, validUntil }) => (
      !Number.isInteger(validSince)
      || !Number.isInteger(validUntil)
      || validSince >= validUntil
    ))) {
      return false;
    }

    const serverTime = this.getServerTime();
    const futureSalts = salts
      .map(({ salt, validSince, validUntil }) => ({ salt, validSince, validUntil }))
      .sort((firstSalt, secondSalt) => firstSalt.validSince - secondSalt.validSince);
    const retainedSalts = this.serverSalts.filter(({ salt, validUntil }) => (
      (validUntil === undefined || validUntil > serverTime)
      && !futureSalts.some(({ salt: futureSalt }) => futureSalt === salt)
    ));
    this.serverSalts = [...retainedSalts, ...futureSalts]
      .sort((firstSalt, secondSalt) => firstSalt.validSince - secondSalt.validSince)
      .slice(-MAX_STORED_SERVER_SALTS);

    this.selectServerSalt(serverTime);
    return true;
  }

consumeMessageReplay(message: TLMessage) {
    return this.replayedMessages.delete(message);
  }

updateMessageId(message: TLMessage) {
    message.msgId = this._getNewMsgId();
  }

async _calcKey(
    authKey: Uint8Array, msgKey: Uint8Array, client: boolean,
  ): Promise<{ key: Uint8Array; iv: Uint8Array }> {
    const x = this._isCall
      ? (128 + (this._isOutgoing !== client ? 8 : 0))
      : (client ? 0 : 8);
    const [sha256a, sha256b] = await Promise.all([
      sha256(concat(msgKey, authKey.slice(x, x + 36))),
      sha256(concat(authKey.slice(x + 40, x + 76), msgKey)),
    ]);
    const key = concat(sha256a.slice(0, 8), sha256b.slice(8, 24), sha256a.slice(24, 32));
    if (this._isCall) {
      const iv = concat(sha256b.slice(0, 4), sha256a.slice(8, 16), sha256b.slice(24, 28));

      return {
        key,
        iv,
      };
    }
    const iv = concat(sha256b.slice(0, 8), sha256a.slice(8, 24), sha256b.slice(24, 32));
    return {
      key,
      iv,
    };
  }

writeDataAsMessage(
    buffer: BinaryWriter, data: Uint8Array, contentRelated: boolean, afterId?: bigint,
  ): { msgId: bigint; seqNo: number } {
    const msgId = this._getNewMsgId();
    const seqNo = this._getSeqNo(contentRelated);
    let body;
    if (afterId === undefined) {
      body = GZIPPacked.gzipIfNeeded(contentRelated, data);
    } else {
      // Invoke query expects a query with a getBytes func
      body = GZIPPacked.gzipIfNeeded(contentRelated, new Api.InvokeAfterMsg({
        msgId: afterId,
        query: {
          getBytes() {
            return data;
          },
        },
      }).getBytes());
    }
    const s = new Uint8Array(4);
    writeInt32LE(s, seqNo);
    const b = new Uint8Array(4);
    writeInt32LE(b, body.length);
    const m = toSignedLittleBuffer(msgId, 8);
    buffer.write(concat(m, s, b));
    buffer.write(body);
    return { msgId, seqNo };
  }

getBytes() {
            return data;
          }

async encryptMessageData(data: Uint8Array): Promise<Uint8Array> {
    if (!this.authKey) {
      throw new Error('Auth key unset');
    }

    await this.authKey.waitForKey();
    const authKey = this.authKey.getKey();
    if (!authKey) {
      throw new Error('Auth key unset');
    }

    if (this.authKey.keyId === undefined) {
      throw new Error('Unset params');
    }

    if (this._isCall) {
      const x = 128 + (this._isOutgoing ? 0 : 8);
      const lengthStart = data.length;

      data = new Uint8Array(data);
      if (lengthStart % 4 !== 0) {
        data = concat(data, new Uint8Array(4 - (lengthStart % 4)).fill(0x20));
      }

      const msgKeyLarge = await sha256(concat(authKey
        .slice(88 + x, 88 + x + 32), data));

      const msgKey = msgKeyLarge.slice(8, 24);

      const {
        iv,
        key,
      } = await this._calcKey(authKey, msgKey, true);

      data = new CTR(key, iv).encrypt(data);
      // data = data.slice(0, lengthStart)
      return concat(msgKey, data);
    } else {
      const s = toSignedLittleBuffer(this.getServerSalt(), 8);
      const i = toSignedLittleBuffer(this.id, 8);
      data = concat(s, i, data);
      const padding = generateRandomBytes(mod(-(data.length + 12), 16) + 12);
      // Being substr(what, offset, length); x = 0 for client
      // "msg_key_large = SHA256(substr(auth_key, 88+x, 32) + pt + padding)"
      const msgKeyLarge = await sha256(concat(authKey
        .slice(88, 88 + 32), data, padding));
      // "msg_key = substr (msg_key_large, 8, 16)"
      const msgKey = msgKeyLarge.slice(8, 24);

      const {
        iv,
        key,
      } = await this._calcKey(authKey, msgKey, true);

      const keyId = readBufferFromBigInt(this.authKey.keyId, 8);
      return concat(keyId, msgKey, new IGE(key, iv).encryptIge(concat(data, padding)));
    }
  }

async decryptMessageData(
    body: Uint8Array,
    canSkipTimeValidation?: CanSkipTimeValidation,
  ) {
    const receivedAt = Math.floor(Date.now() / 1000);

    if (!this.authKey) {
      throw new Error('Auth key unset');
    }

    if (this._isCall && body.length < 8) {
      throw new InvalidBufferError(body);
    }
    if (!this._isCall && body.length === 4) {
      throw new InvalidBufferError(body);
    }
    if (!this._isCall && (body.length < ENCRYPTED_MESSAGE_EXTERNAL_HEADER_LENGTH
      || (body.length - ENCRYPTED_MESSAGE_EXTERNAL_HEADER_LENGTH) % 16 !== 0)) {
      throw new SecurityError();
    }
    let hasInvalidEncryptedPacket = false;
    if (!this._isCall) {
      const keyId = readBigIntFromBuffer(body.slice(0, 8));
      hasInvalidEncryptedPacket = keyId !== this.authKey.keyId;
    }
    const authKey = this.authKey.getKey();
    if (!authKey) {
      throw new SecurityError('Unset AuthKey');
    }
    const msgKey = this._isCall ? body.slice(0, 16) : body.slice(8, 24);

    const x = this._isCall ? 128 + (this._isOutgoing ? 8 : 0) : 0;
    const {
      iv,
      key,
    } = await this._calcKey(authKey, msgKey, false);

    if (this._isCall) {
      body = body.slice(16);
      const lengthStart = body.length;

      body = concat(body, new Uint8Array(4 - (lengthStart % 4)));

      body = new CTR(key, iv).decrypt(body);

      body = body.slice(0, lengthStart);
    } else {
      try {
        body = new IGE(key, iv).decryptIge(body.slice(ENCRYPTED_MESSAGE_EXTERNAL_HEADER_LENGTH));
      } catch {
        throw new SecurityError();
      }
    }

    const ourKey = this._isCall
      ? await sha256(concat(authKey
        .slice(88 + x, 88 + x + 32), body))
      : await sha256(concat(authKey
        .slice(96, 96 + 32), body));

    if (!this._isCall) {
      // https://core.telegram.org/mtproto/security_guidelines#checking-sha256-hash-value-of-msg-key
      // Complete the hash check even when an earlier packet check failed
      hasInvalidEncryptedPacket = !compareBuffersConstantTime(msgKey, ourKey.slice(8, 24))
        || hasInvalidEncryptedPacket;
    }
    if (!this._isCall && body.length < ENCRYPTED_MESSAGE_HEADER_LENGTH) {
      throw new SecurityError();
    }
    const reader = new BinaryReader(body);

    if (this._isCall) {
      // Seq
      reader.readInt(false);
      return reader.read(body.length - 4);
    } else {
      const serverSalt = reader.readLong();
      const serverId = reader.readLong();
      hasInvalidEncryptedPacket = serverId !== this.id || hasInvalidEncryptedPacket;

      const remoteMsgId = reader.readLong();
      const remoteSequence = reader.readInt();
      const messageBodyLength = reader.readInt();
      const remainingPlaintextLength = body.length - ENCRYPTED_MESSAGE_HEADER_LENGTH;
      const paddingLength = remainingPlaintextLength - messageBodyLength;

      // https://core.telegram.org/mtproto/security_guidelines#checking-message-length
      if (messageBodyLength < 0 || messageBodyLength % TL_ALIGNMENT !== 0
        || messageBodyLength > remainingPlaintextLength
        || paddingLength < MIN_ENCRYPTED_MESSAGE_PADDING
        || paddingLength > MAX_ENCRYPTED_MESSAGE_PADDING) {
        hasInvalidEncryptedPacket = true;
      }

      if (hasInvalidEncryptedPacket) throw new SecurityError();

      const messageReader = reader.createSubReader(messageBodyLength);
      const obj = messageReader.tgReadObject();
      if (messageReader.tellPosition() !== messageBodyLength) {
        throw new SecurityError();
      }
      const message = new TLMessage(remoteMsgId, remoteSequence, obj);
      this.validateIncomingMessages(
        message, receivedAt, canSkipTimeValidation,
      );
      if (this.currentServerSalt === undefined) {
        this.setServerSalt(serverSalt);
      }

      return message;
    }
  }

private validateIncomingMessages(
    message: TLMessage,
    receivedAt: number,
    canSkipTimeValidation?: CanSkipTimeValidation,
  ) {
    const incomingMessages: TLMessage[] = [];
    this.collectIncomingMessages(message, incomingMessages);
    const canSkipPacketTimeValidation = this.canSkipMessageTimeValidation(message, canSkipTimeValidation);

    const retainedFloor = this.remoteMsgIds[0];
    if (this._lastMsgId !== 0n) {
      if ((message.msgId & 1n) !== SERVER_MSG_ID_PARITY) {
        throw new SecurityError();
      }
      if (this.remoteMessages.has(message.msgId)) {
        this.replayedMessages.add(message);
        return;
      }
      if (retainedFloor !== undefined && message.msgId < retainedFloor) {
        throw new SecurityError('Server message is older than retained history');
      }

      this.synchronizeServerTime(message.msgId, receivedAt);
    }

    let previousIncomingMsgId: bigint | undefined;
    let areIncomingMessagesOrdered = true;
    let newMessageCount = 0;

    // https://core.telegram.org/mtproto/security_guidelines#checking-msg-id
    for (const incomingMessage of incomingMessages) {
      const { msgId, seqNo } = incomingMessage;

      if ((msgId & 1n) !== SERVER_MSG_ID_PARITY) {
        throw new SecurityError();
      }
      if (this.remoteMessages.has(msgId)) {
        this.replayedMessages.add(incomingMessage);
        continue;
      }
      if (retainedFloor !== undefined && msgId < retainedFloor) {
        throw new SecurityError('Server message is older than retained history');
      }
      if (seqNo < 0) {
        throw new SecurityError();
      }
      if (this.hasTooManyMessageIds(incomingMessage.obj)) {
        throw new SecurityError();
      }
      if (this.isMessageSequenceInvalid(incomingMessage)) {
        throw new SecurityError();
      }
      if (this.isMessageTimeInvalid(msgId, receivedAt) && !canSkipPacketTimeValidation) {
        throw new SecurityError();
      }

      if (previousIncomingMsgId !== undefined && previousIncomingMsgId >= msgId) {
        areIncomingMessagesOrdered = false;
      }
      previousIncomingMsgId = msgId;
      incomingMessages[newMessageCount++] = incomingMessage;
    }
    incomingMessages.length = newMessageCount;

    if (!areIncomingMessagesOrdered) {
      incomingMessages.sort(({ msgId: firstMsgId }, { msgId: secondMsgId }) => (
        firstMsgId < secondMsgId ? -1 : (firstMsgId > secondMsgId ? 1 : 0)
      ));
    }

    // https://core.telegram.org/mtproto/description#message-sequence-number-msg-seqno
    for (let index = 0; index < incomingMessages.length; index++) {
      const incomingMessage = incomingMessages[index];
      const previousIncomingMessage = incomingMessages[index - 1];
      if (previousIncomingMessage?.msgId === incomingMessage.msgId) {
        throw new SecurityError();
      }

      const insertionIndex = this.getRemoteMessageInsertionIndex(incomingMessage.msgId);
      const previousRemoteMsgId = this.remoteMsgIds[insertionIndex - 1];
      const nextRemoteMsgId = this.remoteMsgIds[insertionIndex];
      let previousSeqNo = previousRemoteMsgId === undefined
        ? undefined
        : this.remoteMessages.get(previousRemoteMsgId)!.seqNo;
      if (previousIncomingMessage
        && (previousRemoteMsgId === undefined || previousIncomingMessage.msgId > previousRemoteMsgId)) {
        previousSeqNo = previousIncomingMessage.seqNo;
      }
      const nextIncomingMessage = incomingMessages[index + 1];
      let nextSeqNo = nextRemoteMsgId === undefined
        ? undefined
        : this.remoteMessages.get(nextRemoteMsgId)!.seqNo;
      if (nextIncomingMessage
        && (nextRemoteMsgId === undefined || nextIncomingMessage.msgId < nextRemoteMsgId)) {
        nextSeqNo = nextIncomingMessage.seqNo;
      }
      const hasInvalidPreviousSequence = previousSeqNo !== undefined
        && this.isMessageSequenceOrderInvalid(previousSeqNo, incomingMessage.seqNo);
      const hasInvalidNextSequence = nextSeqNo !== undefined
        && this.isMessageSequenceOrderInvalid(incomingMessage.seqNo, nextSeqNo);
      if (hasInvalidPreviousSequence || hasInvalidNextSequence) {
        throw new SecurityError();
      }
    }

    this.rememberIncomingMessages(incomingMessages);
  }

private getRemoteMessageInsertionIndex(msgId: bigint) {
    let startIndex = 0;
    let endIndex = this.remoteMsgIds.length;
    while (startIndex < endIndex) {
      const middleIndex = (startIndex + endIndex) >> 1;
      if (this.remoteMsgIds[middleIndex] < msgId) {
        startIndex = middleIndex + 1;
      } else {
        endIndex = middleIndex;
      }
    }
    return startIndex;
  }

private isMessageSequenceOrderInvalid(previousSeqNo: number, nextSeqNo: number) {
    return previousSeqNo > nextSeqNo
      || (previousSeqNo === nextSeqNo && (previousSeqNo & 1) === 1);
  }

private rememberIncomingMessages(incomingMessages: TLMessage[]) {
    const previousLength = this.remoteMsgIds.length;
    this.remoteMsgIds.length += incomingMessages.length;

    let previousIndex = previousLength - 1;
    let incomingIndex = incomingMessages.length - 1;
    let targetIndex = this.remoteMsgIds.length - 1;
    while (incomingIndex >= 0) {
      const incomingMsgId = incomingMessages[incomingIndex].msgId;
      if (previousIndex >= 0 && this.remoteMsgIds[previousIndex] > incomingMsgId) {
        this.remoteMsgIds[targetIndex--] = this.remoteMsgIds[previousIndex--];
      } else {
        this.remoteMsgIds[targetIndex--] = incomingMsgId;
        incomingIndex--;
      }
    }

    for (const incomingMessage of incomingMessages) {
      this.remoteMessages.set(incomingMessage.msgId, {
        isContentRelated: incomingMessage.isContentRelated,
        seqNo: incomingMessage.seqNo,
      });
    }

    if (this.remoteMsgIds.length <= MAX_BUFFERED_REMOTE_MESSAGES) return;

    const discardedCount = this.remoteMsgIds.length - REMOTE_MESSAGE_HISTORY_SIZE;

    for (let index = 0; index < discardedCount; index++) {
      this.remoteMessages.delete(this.remoteMsgIds[index]);
    }
    this.remoteMsgIds.copyWithin(0, discardedCount);
    this.remoteMsgIds.length = REMOTE_MESSAGE_HISTORY_SIZE;
  }

private hasTooManyMessageIds(obj: unknown) {
    return (obj instanceof Api.MsgsAck
      || obj instanceof Api.MsgsStateReq
      || obj instanceof Api.MsgResendReq)
    && obj.msgIds.length > MAX_MESSAGE_IDS;
  }

private isMessageSequenceInvalid(message: TLMessage) {
    // https://core.telegram.org/mtproto/service_messages#new-session-creation-notification
    if (message.obj.CONSTRUCTOR_ID === Api.NewSessionCreated.CONSTRUCTOR_ID) {
      return !message.isContentRelated;
    }

    // https://core.telegram.org/mtproto/description#content-related-message
    return message.isContentRelated
      && FORBIDDEN_CONTENT_RELATED_CONSTRUCTOR_IDS.has(message.obj.CONSTRUCTOR_ID);
  }

private collectIncomingMessages(
    message: TLMessage,
    incomingMessages: TLMessage[],
    containerMsgId?: bigint,
  ) {
    this.unwrapGzipPacked(message);

    // https://core.telegram.org/mtproto/service_messages#simple-container
    if (containerMsgId !== undefined && message.msgId >= containerMsgId) {
      throw new SecurityError();
    }

    if (message.obj instanceof MessageContainer) {
      if (containerMsgId !== undefined) {
        throw new SecurityError();
      }

      for (const innerMessage of message.obj.messages) {
        this.collectIncomingMessages(innerMessage, incomingMessages, message.msgId);
      }
    }

    incomingMessages.push(message);
  }

private unwrapGzipPacked(message: TLMessage) {
    while (message.obj instanceof GZIPPacked) {
      const { data } = message.obj;
      const reader = new BinaryReader(data);
      const obj = reader.tgReadObject();

      // https://core.telegram.org/api/invoking#decompressing-data
      if (obj instanceof MessageContainer || reader.tellPosition() !== data.length) {
        throw new SecurityError();
      }
      message.obj = obj;
    }
  }

private isMessageTimeInvalid(msgId: bigint, receivedAt: number) {
    const remoteTime = Number(msgId >> 32n);
    const timeDelta = receivedAt + this.timeOffset - remoteTime;
    return timeDelta > MAX_INCOMING_MESSAGE_AGE
      || timeDelta < -MAX_INCOMING_MESSAGE_FUTURE_OFFSET;
  }

private synchronizeServerTime(msgId: bigint, receivedAt: number) {
    const timeOffset = Number(msgId >> 32n) - receivedAt;
    if (this.hasSynchronizedServerTime && timeOffset <= this.timeOffset) return;

    this.timeOffset = timeOffset;
    this.hasSynchronizedServerTime = true;
  }

private canSkipMessageTimeValidation(
    message: TLMessage,
    canSkipTimeValidation?: CanSkipTimeValidation,
  ): boolean {
    if (!canSkipTimeValidation) return false;
    if (message.obj instanceof MessageContainer) {
      return message.obj.messages.some((innerMessage) => (
        this.canSkipMessageTimeValidation(innerMessage, canSkipTimeValidation)
      ));
    }

    // https://core.telegram.org/mtproto/service_messages_about_messages#notice-of-ignored-error-message
    const {
      CONSTRUCTOR_ID: constructorId, badMsgId, badMsgSeqno, errorCode,
    } = message.obj;
    const isApplicableBadServerSalt = constructorId === Api.BadServerSalt.CONSTRUCTOR_ID
      && errorCode === BAD_SERVER_SALT_ERROR_CODE;
    const isApplicableBadMsg = constructorId === Api.BadMsgNotification.CONSTRUCTOR_ID
      && INVALID_TIME_ERROR_CODES.has(errorCode);
    if (!isApplicableBadServerSalt && !isApplicableBadMsg) return false;

    return canSkipTimeValidation(badMsgId, badMsgSeqno);
  }

private getServerSalt() {
    this.selectServerSalt(this.getServerTime());
    return this.currentServerSalt ?? 0n;
  }

private selectServerSalt(serverTime: number) {
    for (let i = this.serverSalts.length - 1; i >= 0; i--) {
      const serverSalt = this.serverSalts[i];
      if (serverSalt.validSince <= serverTime
        && (serverSalt.validUntil === undefined || serverTime < serverSalt.validUntil)) {
        const previousSalt = this.currentServerSalt;
        if (previousSalt !== undefined && previousSalt !== serverSalt.salt) {
          const previousEntry = this.serverSalts.find(({ salt }) => salt === previousSalt);
          this.serverSalts = [
            ...this.serverSalts.filter(({ salt, validUntil }) => (
              (validUntil === undefined || validUntil > serverTime)
              && salt !== previousSalt
            )),
            {
              salt: previousSalt,
              validSince: previousEntry?.validSince ?? serverTime,
              validUntil: previousEntry?.validUntil ?? serverTime + SERVER_SALT_GRACE_PERIOD,
            },
          ]
            .sort((firstSalt, secondSalt) => firstSalt.validSince - secondSalt.validSince)
            .slice(-MAX_STORED_SERVER_SALTS);
        }
        this.currentServerSalt = serverSalt.salt;
        return;
      }
    }
  }

_getNewMsgId() {
    let newMsgId = this.getTimeBasedMessageId();
    if (this._lastMsgId >= newMsgId) {
      newMsgId = this._lastMsgId + MESSAGE_ID_ALIGNMENT;
    }
    if ((newMsgId & MESSAGE_ID_LOW_MASK) === 0n) newMsgId += MESSAGE_ID_ALIGNMENT;

    this._lastMsgId = newMsgId;
    return newMsgId;
  }

updateTimeOffset(correctMsgId: bigint) {
    const bad = this.getTimeBasedMessageId();
    const old = this.timeOffset;
    let isSessionReset = false;
    const now = Math.floor(Date.now() / 1000);
    const correct = Number(correctMsgId >> 32n);
    this.timeOffset = correct - now;
    this.hasSynchronizedServerTime = true;

    if (this.timeOffset !== old) {
      const nextMsgId = this._lastMsgId + MESSAGE_ID_ALIGNMENT;
      const latestAllowedMsgId = this.getTimeBasedMessageId()
        + BigInt(MAX_INCOMING_MESSAGE_FUTURE_OFFSET) * MESSAGE_ID_SCALE;

      // https://core.telegram.org/mtproto/description#message-identifier-msg-id
      // Keep monotonicity unless the corrected clock would make the next ID invalid
      if (this.timeOffset < old && nextMsgId > latestAllowedMsgId) {
        this.reset();
        isSessionReset = true;
      }

      this._log.debug(
        // eslint-disable-next-line @stylistic/max-len
        `Updated time offset (old offset ${old}, bad ${bad.toString()}, good ${correctMsgId.toString()}, new ${this.timeOffset})`,
      );
    }

    return { timeOffset: this.timeOffset, isSessionReset };
  }

private getTimeBasedMessageId() {
    const timestampMilliseconds = BigInt(Date.now())
      + BigInt(this.timeOffset) * MILLISECONDS_PER_SECOND;
    const messageId = timestampMilliseconds * MESSAGE_ID_SCALE / MILLISECONDS_PER_SECOND;
    return messageId - messageId % MESSAGE_ID_ALIGNMENT;
  }

_getSeqNo(contentRelated: boolean) {
    if (contentRelated) {
      const result = this._sequence * 2 + 1;
      this._sequence += 1;
      return result;
    } else {
      return this._sequence * 2;
    }
  }

function renderSessions(sessionHashes: string[]) {
    return (
      <>
        <IslandTitle dir={lang.isRtl ? 'rtl' : undefined}>
          {lang('WebSessionsTitle')}
        </IslandTitle>
        <Island>
          {sessionHashes.map(renderSession)}
        </Island>
      </>
    );
  }

