class Counter {
  public counter: Uint8Array;

  constructor(initialValue: Uint8Array) {
    this.counter = new Uint8Array(initialValue);
  }

  increment() {
    for (let i = 15; i >= 0; i--) {
      if (this.counter[i] === 255) {
        this.counter[i] = 0;
      } else {
        this.counter[i]++;
        break;
      }
    }
  }
}

