      return ref.current && !ref.current.contains(event.target as Node);
    });

    if (clickedOutside) callback(event);
  });

  useEffect(() => {
    document.addEventListener('click', handleClickOutside);
    return () => {
      document.removeEventListener('click', handleClickOutside);
    };
  }, [handleClickOutside]);
}

