pub fn set_tray_autostart_state(app: &AppHandle, is_enabled: bool) {
  if let Ok(mut state) = AUTOSTART_STATE.lock() {
    *state = is_enabled;
  }

  if let Err(err) = rebuild_menu(app) {
    log::error!("Failed to rebuild tray menu: {:?}", err);
  }
}

