  }

  addDocumentToLocalDb(addSavedMusicRepairInfo(document, peerId));

  return buildApiAudioFromDocument(document);
}

function useCollapsibleLines<T extends HTMLElement, C extends HTMLElement>(
  ref: ElementRef<T>,
  maxLinesBeforeCollapse: number,
  {
    cutoutRef,
    isDisabled,
    noInitialCollapse,
    recalculationKey,
    isCollapsed: isCollapsedControlled,
    onCollapseChange,
  }: UseCollapsibleLinesOptions<C> = {},
) {
  const isFirstRenderRef = useRef(true);
  const cutoutHeightRef = useRef<number | undefined>();
  const fullHeightRef = useRef<number | undefined>();
  const shouldInitiallyCollapse = isCollapsedControlled ?? !noInitialCollapse;
  const [isCollapsible, setIsCollapsible] = useState(!isDisabled && shouldInitiallyCollapse);
  const [isCollapsedUncontrolled, setIsCollapsedUncontrolled] = useState(isCollapsible);
  const isCollapsed = isCollapsedControlled ?? isCollapsedUncontrolled;
  const shouldKeepExpandedHeightAuto = recalculationKey !== undefined;

  const setIsCollapsed = useLastCallback<StateHookSetter<boolean>>((newValue) => {
    const isNextCollapsed = typeof newValue === 'function' ? newValue(isCollapsed) : newValue;
    if (isNextCollapsed === isCollapsed) return;

    if (isCollapsedControlled === undefined) {
      setIsCollapsedUncontrolled(isNextCollapsed);
    }
    onCollapseChange?.(isNextCollapsed);
  });

  useLayoutEffect(() => {
    const element = (cutoutRef || ref).current;
    const shouldUseStyleInExpand = !cutoutRef && !shouldKeepExpandedHeightAuto;

    if (!element || isFirstRenderRef.current) return;

    requestMutation(() => {
      if (isDisabled) {
        element.style.maxHeight = '';
        return;
      }

      element.style.maxHeight = isCollapsed ? `${cutoutHeightRef.current}px` :
        shouldUseStyleInExpand ? `${fullHeightRef.current}px` : ``;
    });
  }, [cutoutRef, isCollapsed, isDisabled, ref, shouldKeepExpandedHeightAuto]);

  const recalculateTextLines = useLastCallback(() => {
    if (isDisabled || !ref.current) {
      return;
    }
    const element = ref.current;

    const { lineHeight, totalLines } = calcTextLineHeightAndCount(element);
    fullHeightRef.current = element.scrollHeight;
    if (totalLines > maxLinesBeforeCollapse) {
      cutoutHeightRef.current = lineHeight * maxLinesBeforeCollapse;
      setIsCollapsible(true);
    } else {
      setIsCollapsible(false);
      setIsCollapsed(false);
    }
  });

  const debouncedRecalcTextLines = useDebouncedCallback(
    () => requestMeasure(recalculateTextLines),
    [recalculateTextLines],
    WINDOW_RESIZE_LINE_RECALC_DEBOUNCE,
  );

  useLayoutEffect(() => {
    if (!isDisabled && isFirstRenderRef.current) {
      requestForcedReflow(() => {
        recalculateTextLines();

        return () => {
          isFirstRenderRef.current = false;
          const element = (cutoutRef || ref).current;
          if (!element) return;
          element.style.maxHeight = isCollapsed && cutoutHeightRef.current ?
            `${cutoutHeightRef.current}px` :
            shouldKeepExpandedHeightAuto ? '' : `${fullHeightRef.current}px`;
        };
      });
    }
  }, [
    cutoutRef, isCollapsed, isDisabled, recalculateTextLines, ref, shouldKeepExpandedHeightAuto,
  ]);

  useEffect(() => {
    if (isDisabled || isFirstRenderRef.current || recalculationKey === undefined) return;

    requestMeasure(recalculateTextLines);
  }, [isDisabled, recalculateTextLines, recalculationKey]);

  // Parent resize is triggered on every collapse/expand, so we do recalculation only on window resize to save resources
  const { width: windowWidth } = useWindowSize();
  useEffect(() => {
    if (!isDisabled) {
      if (isFirstRenderRef.current) return;

      debouncedRecalcTextLines();
    } else {
      setIsCollapsible(false);
      setIsCollapsed(false);
    }
  }, [debouncedRecalcTextLines, isDisabled, windowWidth]);

  return {
    isCollapsed,
    isCollapsible,
    setIsCollapsed,
  };
}

function buildApiPageDocument(document: GramJs.TypeDocument): ApiPageDocument | undefined {
  if (!(document instanceof GramJs.Document)) {
    return undefined;
  }

  return buildStickerFromDocument(document)
    || buildApiVideoFromDocument(document)
    || buildApiAudioFromDocument(document)
    || buildApiDocument(document);
}

function buildApiVideoFromDocument(document: GramJs.Document, altDocuments?: GramJs.TypeDocument[], params?: {
  isSpoiler?: boolean;
  timestamp?: number;
}): ApiVideo | undefined {
  if (document instanceof GramJs.DocumentEmpty) {
    return undefined;
  }

  const altVideos = altDocuments && buildAltVideosFromDocuments(altDocuments);

  const { isSpoiler, timestamp } = params || {};

  const {
    id, mimeType, thumbs, size, videoThumbs, attributes,
  } = document;

  if (mimeType === VIDEO_WEBM_TYPE && !(self as any).isWebmSupported) {
    return undefined;
  }

  const videoAttr = attributes
    .find((a): a is GramJs.DocumentAttributeVideo => a instanceof GramJs.DocumentAttributeVideo);

  if (!videoAttr) {
    return undefined;
  }

  const gifAttr = attributes
    .find((a): a is GramJs.DocumentAttributeAnimated => a instanceof GramJs.DocumentAttributeAnimated);

  const hasVideoPreview = videoThumbs?.some((thumb) => thumb instanceof GramJs.VideoSize && thumb.type === 'v');
  const previewPhotoSizes = thumbs && buildApiPhotoPreviewSizes(thumbs);

  const {
    duration,
    w: width,
    h: height,
    supportsStreaming = false,
    roundMessage: isRound = false,
    nosound,
  } = videoAttr;

  const waveform = isRound ? generateWaveform(duration) : undefined;
  const storyboardInfo = altDocuments && buildStoryboardInfoFromDocuments(altDocuments);

  return {
    mediaType: 'video',
    id: String(id),
    mimeType,
    duration,
    fileName: buildApiDocumentFileName(document, 'video'),
    width,
    height,
    supportsStreaming,
    isRound,
    isGif: Boolean(gifAttr),
    thumbnail: buildApiThumbnailFromStripped(thumbs),
    size: toJSNumber(size),
    isSpoiler,
    timestamp,
    hasVideoPreview,
    previewPhotoSizes,
    waveform,
    noSound: nosound,
    altVideos,
    storyboardInfo,
  };
}

function buildApiAudioFromDocument(
  document: GramJs.Document,
  shouldIncludeVoice = false,
): ApiAudio | undefined {
  if (document instanceof GramJs.DocumentEmpty) {
    return undefined;
  }

  const audioAttribute = document.attributes
    .find((attr): attr is GramJs.DocumentAttributeAudio => (
      attr instanceof GramJs.DocumentAttributeAudio
    ));

  if (!audioAttribute || (!shouldIncludeVoice && audioAttribute.voice)) {
    return undefined;
  }

  const thumbnailSizes = document.thumbs && document.thumbs
    .filter((thumb): thumb is GramJs.PhotoSize => thumb instanceof GramJs.PhotoSize)
    .map((thumb) => buildApiPhotoSize(thumb));

  return {
    mediaType: 'audio',
    id: String(document.id),
    fileName: buildApiDocumentFileName(document, 'audio'),
    thumbnailSizes,
    size: toJSNumber(document.size),
    ...pick(document, ['mimeType']),
    ...pick(audioAttribute, ['duration', 'performer', 'title']),
  };
}

function buildApiVoiceFromDocument(document: GramJs.Document): ApiVoice | undefined {
  const audioAttribute = document.attributes
    .find((attr): attr is GramJs.DocumentAttributeAudio => (
      attr instanceof GramJs.DocumentAttributeAudio
    ));

  if (!audioAttribute || !audioAttribute.voice) {
    return undefined;
  }

  const { duration, waveform } = audioAttribute;

  return {
    mediaType: 'voice',
    id: String(document.id),
    size: toJSNumber(document.size),
    duration,
    waveform: waveform ? Array.from(waveform) : undefined,
  };
}

function buildApiDocument(document: GramJs.TypeDocument): ApiDocument | undefined {
  if (!(document instanceof GramJs.Document)) {
    return undefined;
  }

  const {
    id, size, mimeType, date, thumbs, attributes,
  } = document;

  const photoSize = thumbs && thumbs.find((s): s is GramJs.PhotoSize => s instanceof GramJs.PhotoSize);
  let thumbnail = thumbs && buildApiThumbnailFromStripped(thumbs);
  if (!thumbnail && thumbs && photoSize) {
    const photoPath = thumbs.find((s): s is GramJs.PhotoPathSize => s instanceof GramJs.PhotoPathSize);
    if (photoPath) {
      thumbnail = buildApiThumbnailFromPath(photoPath, photoSize);
    }
  }
  const previewPhotoSizes = thumbs && buildApiPhotoPreviewSizes(thumbs);

  let innerMediaType: ApiDocument['innerMediaType'] | undefined;
  let mediaSize: ApiDocument['mediaSize'] | undefined;
  if (photoSize) {
    mediaSize = {
      width: photoSize.w,
      height: photoSize.h,
    };

    if (SUPPORTED_PHOTO_CONTENT_TYPES.has(mimeType)) {
      innerMediaType = 'photo';

      const imageAttribute = attributes
        .find((a): a is GramJs.DocumentAttributeImageSize => a instanceof GramJs.DocumentAttributeImageSize);

      if (imageAttribute) {
        const { w: width, h: height } = imageAttribute;
        mediaSize = {
          width,
          height,
          fromDocumentAttribute: true,
        };
      }
    } else if (SUPPORTED_VIDEO_CONTENT_TYPES.has(mimeType)) {
      innerMediaType = 'video';
      const videoAttribute = attributes
        .find((a): a is GramJs.DocumentAttributeVideo => a instanceof GramJs.DocumentAttributeVideo);

      if (videoAttribute) {
        const { w: width, h: height } = videoAttribute;
        mediaSize = {
          width,
          height,
        };
      }
    }
  }

  return {
    mediaType: 'document',
    id: String(id),
    size: toJSNumber(size),
    mimeType,
    timestamp: date,
    fileName: buildApiDocumentFileName(document),
    thumbnail,
    innerMediaType,
    mediaSize,
    previewPhotoSizes,
  };
}

function buildAltVideosFromDocuments(altDocuments: GramJs.TypeDocument[], params?: {
  isSpoiler?: boolean;
}): ApiVideo[] | undefined {
  const altVideos = altDocuments.filter((d): d is GramJs.Document => (
    d instanceof GramJs.Document && d.mimeType.startsWith('video')
  )).map((alt) => buildApiVideoFromDocument(alt, undefined, params))
    .filter(Boolean);
  if (!altVideos.length) {
    return undefined;
  }

  return altVideos;
}

function buildStoryboardInfoFromDocuments(documents: GramJs.TypeDocument[]): StoryboardInfo | undefined {
  const storyboardMtpFile = documents.find((d): d is GramJs.Document => (
    d instanceof GramJs.Document && d.mimeType === STORYBOARD_MIME
  ));
  const storyboardMapMtpFile = documents.find((d): d is GramJs.Document => (
    d instanceof GramJs.Document && d.mimeType === STORYBOARD_MAP_MIME
  ));

  const storyboardFile = storyboardMtpFile && buildApiDocument(storyboardMtpFile);
  const storyboardMapFile = storyboardMapMtpFile && buildApiDocument(storyboardMapMtpFile);

  const sizeAttribute = storyboardMapMtpFile?.attributes.find((a): a is GramJs.DocumentAttributeImageSize => (
    a instanceof GramJs.DocumentAttributeImageSize
  ));

  const frameSize = sizeAttribute && { width: sizeAttribute.w, height: sizeAttribute.h };

  if (!storyboardFile || !storyboardMapFile || !frameSize) {
    return undefined;
  }

  return {
    storyboardFile,
    storyboardMapFile,
    frameSize,
  };
}

function buildApiDocumentFileName(document: GramJs.Document, defaultBase = 'file') {
  const { mimeType, attributes } = document;
  const filenameAttribute = attributes
    .find((a): a is GramJs.DocumentAttributeFilename => a instanceof GramJs.DocumentAttributeFilename);

  if (filenameAttribute) {
    return filenameAttribute.fileName;
  }

  const extension = mimeType.split('/')[1];

  return `${defaultBase}${String(document.id)}.${extension}`;
}

function useForumPanelRender(isForumPanelOpen = false) {
  const shouldRenderForumPanelRef = useRef(isForumPanelOpen);
  const isAnimationStartedRef = useRef(false);
  const forceUpdate = useForceUpdate();

  useSyncEffect(() => {
    if (isForumPanelOpen) {
      shouldRenderForumPanelRef.current = true;
    }
  }, [isForumPanelOpen]);

  const handleForumPanelAnimationEnd = useLastCallback(() => {
    shouldRenderForumPanelRef.current = false;
    isAnimationStartedRef.current = false;
    forceUpdate();
  });

  const handleForumPanelAnimationStart = useLastCallback(() => {
    isAnimationStartedRef.current = true;
    forceUpdate();
  });

  return {
    shouldRenderForumPanel: shouldRenderForumPanelRef.current,
    isAnimationStarted: isAnimationStartedRef.current,
    handleForumPanelAnimationEnd,
    handleForumPanelAnimationStart,
  };
}

function buildApiStory(peerId: string, story: GramJs.TypeStoryItem): ApiTypeStory {
  if (story instanceof GramJs.StoryItemDeleted) {
    return {
      id: story.id,
      peerId,
      isDeleted: true,
    };
  }

  if (story instanceof GramJs.StoryItemSkipped) {
    const {
      id, date, expireDate, closeFriends,
    } = story;

    return {
      id,
      peerId,
      ...(closeFriends && { isForCloseFriends: true }),
      date,
      expireDate,
    };
  }

  const {
    edited, pinned, expireDate, id, date, caption,
    entities, media, privacy, views,
    public: isPublic, noforwards, closeFriends, contacts, selectedContacts,
    mediaAreas, sentReaction, out, fwdFrom, fromId,
  } = story;

  const content: MediaContent = {
    ...buildMessageMediaContent(media),
  };

  if (caption) {
    content.text = buildMessageTextContent(caption, entities);
  }

  const reaction = sentReaction && buildApiReaction(sentReaction);

  return omitUndefined<ApiStory>({
    id,
    peerId,
    date,
    expireDate,
    content,
    isPublic,
    isEdited: edited,
    isInProfile: pinned,
    isForContacts: contacts,
    isForSelectedContacts: selectedContacts,
    isForCloseFriends: closeFriends,
    noForwards: noforwards,
    views: views && buildApiStoryViews(views),
    isOut: out,
    visibility: privacy && buildPrivacyRules(privacy),
    mediaAreas: mediaAreas?.map(buildApiMediaArea).filter(Boolean),
    sentReaction: reaction,
    forwardInfo: fwdFrom && buildApiStoryForwardInfo(fwdFrom),
    fromId: fromId && getApiChatIdFromMtpPeer(fromId),
  });
}

function buildApiStoryViews(views: GramJs.TypeStoryViews): ApiStoryViews {
  return omitUndefined<ApiStoryViews>({
    hasViewers: views.hasViewers,
    viewsCount: views.viewsCount,
    forwardsCount: views.forwardsCount,
    reactionsCount: views.reactionsCount,
    reactions: views.reactions?.map(buildReactionCount).filter(Boolean),
    recentViewerIds: views.recentViewers?.map((viewerId) => buildApiPeerId(viewerId, 'user')),
  });
}

function buildApiStoryView(view: GramJs.TypeStoryView): ApiTypeStoryView | undefined {
  const {
    blockedMyStoriesFrom, blocked,
  } = view;

  if (view instanceof GramJs.StoryView) {
    return omitUndefined<ApiStoryView>({
      type: 'user',
      peerId: buildApiPeerId(view.userId, 'user'),
      date: view.date,
      reaction: view.reaction && buildApiReaction(view.reaction),
      areStoriesBlocked: blocked || blockedMyStoriesFrom,
      isUserBlocked: blocked,
    });
  }

  if (view instanceof GramJs.StoryViewPublicForward) {
    const message = buildApiMessage(view.message);
    if (!message) return undefined;
    return {
      type: 'forward',
      peerId: message.chatId,
      messageId: message.id,
      message,
      date: message.date,
      areStoriesBlocked: blocked || blockedMyStoriesFrom,
      isUserBlocked: blocked,
    };
  }

  if (view instanceof GramJs.StoryViewPublicRepost) {
    const peerId = getApiChatIdFromMtpPeer(view.peerId);
    const story = buildApiStory(peerId, view.story);
    if (!('content' in story)) return undefined;

    return {
      type: 'repost',
      peerId,
      storyId: view.story.id,
      date: story.date,
      story,
      areStoriesBlocked: blocked || blockedMyStoriesFrom,
      isUserBlocked: blocked,
    };
  }

  return undefined;
}

function buildApiStealthMode(stealthMode: GramJs.TypeStoriesStealthMode): ApiStealthMode {
  return {
    activeUntil: stealthMode.activeUntilDate,
    cooldownUntil: stealthMode.cooldownUntilDate,
  };
}

function buildApiMediaAreaCoordinates(coordinates: GramJs.TypeMediaAreaCoordinates): ApiMediaAreaCoordinates {
  const {
    x, y, w, h, rotation, radius,
  } = coordinates;

  return {
    x,
    y,
    width: w,
    height: h,
    rotation,
    radius,
  };
}

function buildApiMediaArea(area: GramJs.TypeMediaArea): ApiMediaArea | undefined {
  const coordinates = buildApiMediaAreaCoordinates(area.coordinates);
  if (area instanceof GramJs.MediaAreaVenue) {
    const { geo, title } = area;
    const point = buildGeoPoint(geo);

    if (!point) return undefined;

    return {
      type: 'venue',
      coordinates,
      geo: point,
      title,
    };
  }

  if (area instanceof GramJs.MediaAreaGeoPoint) {
    const { geo } = area;
    const point = buildGeoPoint(geo);

    if (!point) return undefined;

    return {
      type: 'geoPoint',
      coordinates,
      geo: point,
    };
  }

  if (area instanceof GramJs.MediaAreaSuggestedReaction) {
    const {
      reaction, dark, flipped,
    } = area;

    const apiReaction = buildApiReaction(reaction);
    if (!apiReaction) {
      return undefined;
    }

    return {
      type: 'suggestedReaction',
      coordinates,
      reaction: apiReaction,
      ...(dark && { isDark: true }),
      ...(flipped && { isFlipped: true }),
    };
  }

  if (area instanceof GramJs.MediaAreaChannelPost) {
    const { channelId, msgId } = area;

    return {
      type: 'channelPost',
      coordinates,
      channelId: buildApiPeerId(channelId, 'channel'),
      messageId: msgId,
    };
  }

  if (area instanceof GramJs.MediaAreaUrl) {
    const { url } = area;

    return {
      type: 'url',
      coordinates,
      url,
    };
  }

  if (area instanceof GramJs.MediaAreaWeather) {
    const {
      emoji, temperatureC, color,
    } = area;

    return {
      type: 'weather',
      coordinates,
      emoji,
      temperatureC,
      color,
    };
  }

  if (area instanceof GramJs.MediaAreaStarGift) {
    const { slug } = area;

    return {
      type: 'uniqueGift',
      coordinates,
      slug,
    };
  }

  return undefined;
}

function buildApiPeerStories(peerStories: GramJs.PeerStories) {
