function getMediaViewerItem({
  message, avatarOwner, profilePhotos, standaloneMedia, pageMedia, mediaIndex, sponsoredMessage,
}: {
  message?: ApiMessage;
  avatarOwner?: ApiPeer;
  profilePhotos?: ApiPeerPhotos;
  standaloneMedia?: MediaViewerMedia[];
  pageMedia?: MediaViewerPageMedia;
  sponsoredMessage?: ApiSponsoredMessage;
  mediaIndex?: number;
}): MediaViewerItem | undefined {
  if (avatarOwner && profilePhotos) {
    return {
      type: 'avatar',
      avatarOwner,
      profilePhotos,
      mediaIndex: mediaIndex!,
    };
  }

  if (standaloneMedia) {
    return {
      type: 'standalone',
      media: standaloneMedia,
      mediaIndex: mediaIndex!,
    };
  }

  if (pageMedia) {
    return {
      type: 'pageBlock',
      pageMedia,
      mediaIndex: mediaIndex!,
    };
  }

  if (message) {
    return {
      type: 'message',
      message,
      mediaIndex,
    };
  }

  if (sponsoredMessage) {
    return {
      type: 'sponsoredMessage',
      message: sponsoredMessage,
      mediaIndex,
    };
  }

  return undefined;
}

function selectViewableMedia(
  global: GlobalState, origin?: MediaViewerOrigin, params?: MediaViewerItem,
): ViewableMedia | undefined {
  if (!params) return undefined;

  if (params.type === 'standalone') {
    const media = params.media[params.mediaIndex];
    return {
      media,
      isSingle: params.media.length === 1,
    };
  }

  if (params.type === 'pageBlock') {
    const block = params.pageMedia.blocks[params.mediaIndex];
    if (!block) {
      return undefined;
    }

    return {
      media: getPageMediaBlockMedia(block),
      isSingle: params.pageMedia.blocks.length === 1,
      caption: block.caption,
    };
  }

  if (params.type === 'avatar') {
    const avatar = params.profilePhotos?.photos[params.mediaIndex];
    if (avatar) {
      return {
        media: avatar,
      };
    }
    return undefined;
  }

  const {
    action, document, photo, video, paidMedia,
  } = getMessageContent(params.message);

  if (action?.type === 'chatEditPhoto' || action?.type === 'suggestProfilePhoto') {
    return {
      media: action.photo!,
      isSingle: true,
    };
  }

  if (document && (isDocumentPhoto(document) || isDocumentVideo(document))) {
    return {
      media: document,
    };
  }

  const webPage = selectWebPageFromMessage(global, params.message);
  if (webPage?.webpageType === 'full') {
    const { photo: webPagePhoto, video: webPageVideo, document: webPageDocument } = webPage;
    const isDocumentMedia = webPageDocument && (isDocumentPhoto(webPageDocument) || isDocumentVideo(webPageDocument));
    const mediaDocument = isDocumentMedia ? webPageDocument : undefined;
    const media = webPageVideo || mediaDocument || webPagePhoto;
    if (media) {
      return {
        media,
        isSingle: true,
      };
    }
  }

  if (paidMedia) {
    const extendedMedia = paidMedia.extendedMedia[params.mediaIndex || 0];
    if (!('mediaType' in extendedMedia)) {
      const { photo: extendedPhoto, video: extendedVideo } = extendedMedia;
      return {
        media: (extendedPhoto || extendedVideo)!,
      };
    }
  }

  const media = video || photo;

  if (media) {
    return {
      media,
    };
  }

  return undefined;
}

function useThrottledResolver<T>(
  resolver: () => T,
  deps: any[],
  msOrSchedulerFn: number | Scheduler,
  noFirst = false,
) {
  return useThrottledCallback((setValue: (newValue: T) => void) => {
    setValue(resolver());
    // eslint-disable-next-line react-hooks-static-deps/exhaustive-deps
  }, deps, msOrSchedulerFn, noFirst);
}

function useThrottledSignal<T>(
  getValue: Signal<T>,
  ms: number,
  noFirst = false,
): Signal<T> {
  const throttledResolver = useThrottledResolver(() => getValue(), [getValue], ms, noFirst);

  return useDerivedSignal(
    throttledResolver, [throttledResolver, getValue], true,
  );
}

function useDebouncedResolver<T>(
  resolver: () => T,
  deps: any[],
  ms: number,
  noFirst = false,
  noLast = false,
) {
  return useDebouncedCallback((setValue: (newValue: T) => void) => {
    setValue(resolver());
    // eslint-disable-next-line react-hooks-static-deps/exhaustive-deps
  }, deps, ms, noFirst, noLast);
}

function useDebouncedSignal<T>(
  getValue: Signal<T>,
  ms: number,
  noFirst = false,
  noLast = false,
): Signal<T> {
  const debouncedResolver = useDebouncedResolver(() => getValue(), [getValue], ms, noFirst, noLast);

  return useDerivedSignal(
    debouncedResolver, [debouncedResolver, getValue], true,
  );
}

function isPriorityPlaybackActive() {
