function useResizeObserver(
  ref: ElementRef<HTMLElement> | undefined,
  onResize: (entry: ResizeObserverEntry) => void,
  isDisabled = false,
) {
  const onResizeRef = useStateRef(onResize);

  useEffect(() => {
    const el = ref?.current;
    if (!el || isDisabled) {
      return undefined;
    }

    const callback: ResizeObserverCallback = ([entry]) => {
      // Ignore updates when element is not properly mounted (`display: none`)
      if (entry.contentRect.width === 0 && entry.contentRect.height === 0) {
        return;
      }

      onResizeRef.current(entry);
    };

    let [observer, callbackManager] = elementObserverMap.get(el) || [undefined, undefined];
    if (!observer) {
      callbackManager = createCallbackManager();
      observer = new ResizeObserver(callbackManager.runCallbacks);
      elementObserverMap.set(el, [observer, callbackManager]);
      observer.observe(el);
    }
    callbackManager!.addCallback(callback);

    return () => {
      callbackManager!.removeCallback(callback);
      if (!callbackManager!.hasCallbacks()) {
        observer.unobserve(el);
        observer.disconnect();
        elementObserverMap.delete(el);
      }
    };
  }, [isDisabled, onResizeRef, ref]);
}

function deepDiff<T>(value1: T, value2: T): Partial<T> | typeof EQUAL | typeof DELETE_ALL_CHILDREN {
  if (value1 === value2) {
    return EQUAL;
  }

  const type1 = typeof value1;
  const type2 = typeof value2;

  if (type1 !== type2) {
    return value2;
  }

  if (Array.isArray(value1) && Array.isArray(value2) && areSortedArraysDeepEqual(value1, value2)) {
    return EQUAL;
  }

  if (!isLiteralObject(value1) || !isLiteralObject(value2)) {
    return value2;
  }

  const object1 = value1 as AnyLiteral;
  const object2 = value2 as AnyLiteral;
  const keys1 = Object.keys(object1);
  const keys2 = Object.keys(object2);

  if (!keys2.length) {
    return !keys1.length ? EQUAL : DELETE_ALL_CHILDREN;
  }

  const allKeys = unique(keys1.concat(keys2));

  const diff = allKeys.reduce((acc: any, key) => {
    const subValue1 = object1[key];
    const subValue2 = object2[key];

    if (!object2.hasOwnProperty(key)) {
      acc[key] = DELETE;
      return acc;
    }

    if (!object1.hasOwnProperty(key)) {
      acc[key] = subValue2;
      return acc;
    }

    const subDiff = deepDiff(subValue1, subValue2);
    if (subDiff !== EQUAL) {
      acc[key] = subDiff;
    }

    return acc;
  }, {});

  if (Object.keys(diff).length === 0) {
    return EQUAL;
  }

  return diff;
}

function areSortedArraysDeepEqual<T extends Array<any>>(array1: T, array2: T) {
  if (array1.length !== array2.length) {
    return false;
  }

  return array1.every((item, i) => deepDiff(item, array2[i]) === EQUAL);
}

function selectTopicsInfo<T extends GlobalState>(global: T, chatId: string): TopicsInfo | undefined {
  return global.chats.topicsInfoById[chatId];
}

function selectTopics<T extends GlobalState>(global: T, chatId: string) {
  return selectTopicsInfo(global, chatId)?.topicsById;
}

function selectTopic<T extends GlobalState>(global: T, chatId: string, threadId: ThreadId) {
  return selectTopicsInfo(global, chatId)?.topicsById?.[threadId];
}

function selectTopicFromMessage<T extends GlobalState>(global: T, message: ApiMessage) {
  const { chatId } = message;
  const chat = selectChat(global, chatId);
  if (!chat?.isForum) return undefined;

  const threadId = selectThreadIdFromMessage(global, message);
  return selectTopic(global, chatId, threadId);
}

interface CropState {
  cropperX: number;
  cropperY: number;
  cropperWidth: number;
  cropperHeight: number;
  aspectRatio: AspectRatio;
  rotation: number;
  quarterTurns: number;
  flipH: boolean;
}

function getTotalRotation(state: CropState): number {
  return state.rotation - state.quarterTurns * 90;
}

interface AspectRatioOption {
  value: AspectRatio;
  labelKey?: 'Free' | 'Original' | 'Square';
  label?: string;
  ratio?: number;
}

interface CropAction {
  type: 'crop';
  previousState: CropState;
}

function computeCenteredCrop(effW: number, effH: number, ratioValue: number | undefined) {
  let width: number;
  let height: number;

  if (!ratioValue) {
    width = effW;
    height = effH;
  } else if (effW / effH > ratioValue) {
    height = effH;
    width = effH * ratioValue;
  } else {
    width = effW;
    height = effW / ratioValue;
  }

  return {
    cropperX: (effW - width) / 2,
    cropperY: (effH - height) / 2,
    cropperWidth: width,
    cropperHeight: height,
  };
}

interface UseCropperOptions {
  imageRef: React.RefObject<HTMLImageElement | undefined>;
  displaySize: { width: number; height: number };
  getDisplayScale: () => number;
  getDisplayCoordinates: (e: React.MouseEvent | React.TouchEvent | MouseEvent | TouchEvent) => { x: number; y: number };
  onAction: (action: CropAction) => void;
  cropState: CropState;
  setCropState: (value: CropState | ((prev: CropState) => CropState)) => void;
}

function useCropper({
  imageRef,
  displaySize,
  getDisplayScale,
  getDisplayCoordinates,
  onAction,
  cropState,
  setCropState,
}: UseCropperOptions) {
  const cropperDragStartRef = useRef<{
    startX: number;
    startY: number;
    cropperX: number;
    cropperY: number;
    cropperWidth: number;
    cropperHeight: number;
  }>();

  const cropStateRef = useRef<CropState>(DEFAULT_CROP_STATE);
  cropStateRef.current = cropState;

  const getAspectRatioValue = useLastCallback((ratio: AspectRatio): number | undefined => {
    if (ratio === 'free') return undefined;
    if (ratio === 'original' && imageRef.current) {
      const { width: effW, height: effH } = getEffectiveDimensions(
        imageRef.current.width, imageRef.current.height, cropStateRef.current.quarterTurns,
      );
      return effW / effH;
    }
    const option = ASPECT_RATIOS.find((r) => r.value === ratio);
    return option?.ratio;
  });

  const setupDragListeners = (
    onMove: (ev: MouseEvent | TouchEvent) => void,
    onUp: () => void,
  ) => {
    const handleUp = () => {
      onUp();
      document.removeEventListener('mousemove', onMove);
      document.removeEventListener('touchmove', onMove);
      document.removeEventListener('mouseup', handleUp);
      document.removeEventListener('touchend', handleUp);
    };

    document.addEventListener('mousemove', onMove);
    document.addEventListener('touchmove', onMove);
    document.addEventListener('mouseup', handleUp);
    document.addEventListener('touchend', handleUp);
  };

  const handleCropperDragStart = useLastCallback((e: React.MouseEvent | React.TouchEvent) => {
    const img = imageRef.current;
    if (!img || displaySize.width === 0) return;

    e.preventDefault();
    e.stopPropagation();

    const { x, y } = getDisplayCoordinates(e);
    const displayScale = getDisplayScale();

    cropperDragStartRef.current = {
      startX: x,
      startY: y,
      cropperX: cropState.cropperX,
      cropperY: cropState.cropperY,
      cropperWidth: cropState.cropperWidth,
      cropperHeight: cropState.cropperHeight,
    };

    const handleMove = (ev: MouseEvent | TouchEvent) => {
      if (!cropperDragStartRef.current) return;

      const coords = getDisplayCoordinates(ev);
      const displayDeltaX = coords.x - cropperDragStartRef.current.startX;
      const displayDeltaY = coords.y - cropperDragStartRef.current.startY;

      const imageDeltaX = displayDeltaX / displayScale;
      const imageDeltaY = displayDeltaY / displayScale;

      const newCropperX = cropperDragStartRef.current.cropperX + imageDeltaX;
      const newCropperY = cropperDragStartRef.current.cropperY + imageDeltaY;

      const { width: effW, height: effH } = getEffectiveDimensions(
        img.width, img.height, cropStateRef.current.quarterTurns,
      );
      const constrainedX = clamp(newCropperX, 0, effW - cropperDragStartRef.current.cropperWidth);
      const constrainedY = clamp(newCropperY, 0, effH - cropperDragStartRef.current.cropperHeight);

      setCropState((prev) => ({
        ...prev,
        cropperX: constrainedX,
        cropperY: constrainedY,
      }));
    };

    const handleUp = () => {
      if (cropperDragStartRef.current) {
        const startState = cropperDragStartRef.current;
        if (startState.cropperX !== cropStateRef.current.cropperX
          || startState.cropperY !== cropStateRef.current.cropperY) {
          const previousState: CropState = {
            ...cropStateRef.current,
            cropperX: startState.cropperX,
            cropperY: startState.cropperY,
            cropperWidth: startState.cropperWidth,
            cropperHeight: startState.cropperHeight,
          };
          onAction({ type: 'crop', previousState });
        }
      }
      cropperDragStartRef.current = undefined;
    };

    setupDragListeners(handleMove, handleUp);
  });

  const handleCornerResizeStart = useLastCallback((e: React.MouseEvent | React.TouchEvent, handle: ResizeHandle) => {
    const img = imageRef.current;
    if (!img || displaySize.width === 0) return;

    e.preventDefault();
    e.stopPropagation();

    const { x, y } = getDisplayCoordinates(e);
    const displayScale = getDisplayScale();

    cropperDragStartRef.current = {
      startX: x,
      startY: y,
      cropperX: cropState.cropperX,
      cropperY: cropState.cropperY,
      cropperWidth: cropState.cropperWidth,
      cropperHeight: cropState.cropperHeight,
    };

    const handleMove = (ev: MouseEvent | TouchEvent) => {
      if (!cropperDragStartRef.current) return;

      const coords = getDisplayCoordinates(ev);
      const displayDeltaX = coords.x - cropperDragStartRef.current.startX;
      const displayDeltaY = coords.y - cropperDragStartRef.current.startY;

      const imageDeltaX = displayDeltaX / displayScale;
      const imageDeltaY = displayDeltaY / displayScale;

      const startState = cropperDragStartRef.current;
      const { width: effW, height: effH } = getEffectiveDimensions(
        img.width, img.height, cropStateRef.current.quarterTurns,
      );
      let newX = startState.cropperX;
      let newY = startState.cropperY;
      let newWidth = startState.cropperWidth;
      let newHeight = startState.cropperHeight;

      const ratioValue = getAspectRatioValue(cropStateRef.current.aspectRatio);

      if (handle === 'topLeft') {
        newX = startState.cropperX + imageDeltaX;
        newY = startState.cropperY + imageDeltaY;
        newWidth = startState.cropperWidth - imageDeltaX;
        newHeight = startState.cropperHeight - imageDeltaY;
      } else if (handle === 'topRight') {
        newY = startState.cropperY + imageDeltaY;
        newWidth = startState.cropperWidth + imageDeltaX;
        newHeight = startState.cropperHeight - imageDeltaY;
      } else if (handle === 'bottomLeft') {
        newX = startState.cropperX + imageDeltaX;
        newWidth = startState.cropperWidth - imageDeltaX;
        newHeight = startState.cropperHeight + imageDeltaY;
      } else if (handle === 'bottomRight') {
        newWidth = startState.cropperWidth + imageDeltaX;
        newHeight = startState.cropperHeight + imageDeltaY;
      }

      if (ratioValue) {
        const currentRatio = newWidth / newHeight;
        if (currentRatio > ratioValue) {
          const adjustedWidth = newHeight * ratioValue;
          if (handle === 'topLeft' || handle === 'bottomLeft') {
            newX += (newWidth - adjustedWidth);
          }
          newWidth = adjustedWidth;
        } else {
          const adjustedHeight = newWidth / ratioValue;
          if (handle === 'topLeft' || handle === 'topRight') {
            newY += (newHeight - adjustedHeight);
          }
          newHeight = adjustedHeight;
        }
      }

      if (newWidth < MIN_CROP_SIZE) {
        if (handle === 'topLeft' || handle === 'bottomLeft') {
          newX -= (MIN_CROP_SIZE - newWidth);
        }
        newWidth = MIN_CROP_SIZE;
        if (ratioValue) newHeight = MIN_CROP_SIZE / ratioValue;
      }
      if (newHeight < MIN_CROP_SIZE) {
        if (handle === 'topLeft' || handle === 'topRight') {
          newY -= (MIN_CROP_SIZE - newHeight);
        }
        newHeight = MIN_CROP_SIZE;
        if (ratioValue) newWidth = MIN_CROP_SIZE * ratioValue;
      }

      // Clamp to image bounds, keeping the opposite edge fixed
      const rightEdge = newX + newWidth;
      const bottomEdge = newY + newHeight;

      if (handle === 'topLeft' || handle === 'bottomLeft') {
        newX = Math.max(0, newX);
        newWidth = rightEdge - newX;
      } else {
        newWidth = Math.min(newWidth, effW - newX);
      }

      if (handle === 'topLeft' || handle === 'topRight') {
        newY = Math.max(0, newY);
        newHeight = bottomEdge - newY;
      } else {
        newHeight = Math.min(newHeight, effH - newY);
      }

      setCropState((prev) => ({
        ...prev,
        cropperX: newX,
        cropperY: newY,
        cropperWidth: newWidth,
        cropperHeight: newHeight,
      }));
    };

    const handleUp = () => {
      if (cropperDragStartRef.current) {
        const startState = cropperDragStartRef.current;
        if (startState.cropperX !== cropStateRef.current.cropperX
          || startState.cropperY !== cropStateRef.current.cropperY
          || startState.cropperWidth !== cropStateRef.current.cropperWidth
          || startState.cropperHeight !== cropStateRef.current.cropperHeight) {
          const previousState: CropState = {
            ...cropStateRef.current,
            cropperX: startState.cropperX,
            cropperY: startState.cropperY,
            cropperWidth: startState.cropperWidth,
            cropperHeight: startState.cropperHeight,
          };
          onAction({ type: 'crop', previousState });
        }
      }
      cropperDragStartRef.current = undefined;
    };

    setupDragListeners(handleMove, handleUp);
  });

  const handleAspectRatioChange = useLastCallback((newRatio: AspectRatio) => {
    const img = imageRef.current;
    if (!img) return;

    const previousState = { ...cropStateRef.current };
    const { width: effW, height: effH } = getEffectiveDimensions(
      img.width, img.height, cropStateRef.current.quarterTurns,
    );

    setCropState({
      ...cropStateRef.current,
      aspectRatio: newRatio,
      ...computeCenteredCrop(effW, effH, getAspectRatioValue(newRatio)),
    });
    onAction({ type: 'crop', previousState });
  });

  const initCropState = useLastCallback((width: number, height: number) => {
    setCropState({
      aspectRatio: 'free',
      cropperX: 0,
      cropperY: 0,
      cropperWidth: width,
      cropperHeight: height,
      rotation: 0,
      quarterTurns: 0,
      flipH: false,
    });
  });

  const getCroppedRegion = useLastCallback(() => {
    const { cropperX, cropperY, cropperWidth, cropperHeight } = cropStateRef.current;
    return {
      x: cropperX,
      y: cropperY,
      width: cropperWidth,
      height: cropperHeight,
    };
  });

  const rotationStartStateRef = useRef<CropState | undefined>();

  const handleRotationChange = useLastCallback((value: number) => {
    const img = imageRef.current;
    if (!img) return;

    if (!rotationStartStateRef.current) {
      rotationStartStateRef.current = { ...cropStateRef.current };
    }

    const { width: effW, height: effH } = getEffectiveDimensions(
      img.width, img.height, cropStateRef.current.quarterTurns,
    );

    setCropState({
      ...cropStateRef.current,
      rotation: clamp(value, MIN_ROTATION, MAX_ROTATION),
      ...computeCenteredCrop(effW, effH, getAspectRatioValue(cropStateRef.current.aspectRatio)),
    });
  });

  const handleRotationChangeEnd = useLastCallback(() => {
    if (rotationStartStateRef.current) {
      onAction({ type: 'crop', previousState: rotationStartStateRef.current });
      rotationStartStateRef.current = undefined;
    }
  });

  const handleQuarterRotate = useLastCallback(() => {
    const img = imageRef.current;
    if (!img) return;

    const previousState = { ...cropStateRef.current };
    const newQuarterTurns = (cropStateRef.current.quarterTurns + 1) % 4;
    const { width: newEffW, height: newEffH } = getEffectiveDimensions(
      img.width, img.height, newQuarterTurns,
    );

    setCropState({
      ...cropStateRef.current,
      quarterTurns: newQuarterTurns,
      rotation: 0,
      ...computeCenteredCrop(newEffW, newEffH, getAspectRatioValue(cropStateRef.current.aspectRatio)),
    });
    onAction({ type: 'crop', previousState });
  });

  const handleFlip = useLastCallback(() => {
    const img = imageRef.current;
    if (!img) return;

    const previousState = { ...cropStateRef.current };
    const { width: effW } = getEffectiveDimensions(
      img.width, img.height, cropStateRef.current.quarterTurns,
    );

    setCropState({
      ...cropStateRef.current,
      flipH: !cropStateRef.current.flipH,
      cropperX: effW - cropStateRef.current.cropperX - cropStateRef.current.cropperWidth,
    });
    onAction({ type: 'crop', previousState });
  });

  return {
    getCroppedRegion,
    initCropState,
    handleCropperDragStart,
    handleCornerResizeStart,
    handleAspectRatioChange,
    handleRotationChange,
    handleRotationChangeEnd,
    handleQuarterRotate,
    handleFlip,
  };
}

interface PaneState {
  element?: HTMLElement;
  height: number;
  isOpen?: boolean;
  isSpacer?: boolean;
  isPending?: boolean;
  key?: string;
}

function useHeaderPane<RefType extends HTMLElement = HTMLDivElement>({
  ref: providedRef,
  isOpen,
  isPending,
  isDisabled,
  withResizeObserver,
  measureKey,
  onStateChange,
}: {
  ref?: ElementRef<RefType>;
  isOpen?: boolean;
  isPending?: boolean;
  isDisabled?: boolean;
  withResizeObserver?: boolean;
  measureKey?: string;
  onStateChange?: (state: PaneState) => void;
}) {
  const [shouldRenderTail, setShouldRenderTail] = useState(isOpen);
  const shouldRender = (isOpen && !isDisabled) || shouldRenderTail;
  const localRef = useRef<RefType>();
  const ref = providedRef || localRef;

  const lastHeightRef = useRef(0);

  const reset = useLastCallback(() => {
    setShouldRenderTail(true);
    onStateChange?.({
      element: undefined,
      height: 0,
      isOpen: false,
      key: measureKey,
    });
  });

  useEffect(() => {
    if (isDisabled) {
      reset();
    }
  }, [isDisabled]);

  useEffect(() => {
    if (isOpen) {
      setShouldRenderTail(true);
    }
  }, [isOpen]);

  useUnmountCleanup(reset);

  useTimeout(() => {
    if (isOpen) return;
    setShouldRenderTail(false);
    onStateChange?.({
      height: 0,
      isOpen: false,
      isPending,
      key: measureKey,
    });
  }, !isOpen ? CLOSE_DURATION : undefined);

  // Should be `useCallback` to trigger effect on deps change
  const handleUpdate = useCallback(() => {
    if (isDisabled) return;
    const element = ref.current;

    if (!isOpen) {
      onStateChange?.({
        element,
        height: 0,
        isOpen: false,
        isPending,
        key: measureKey,
      });
      return;
    }
    if (!element || !shouldRender) return;

    requestForcedReflow(() => {
      const currentHeight = element.offsetHeight;
      lastHeightRef.current = currentHeight;
      return () => {
        onStateChange?.({
          element,
          height: currentHeight,
          isOpen,
          key: measureKey,
        });
      };
    });
  }, [isOpen, isPending, shouldRender, isDisabled, ref, onStateChange, measureKey]);

  const handleResize = useThrottledCallback(() => {
    const element = ref.current;
    if (!element) return;

    const newHeight = element.offsetHeight;
    if (newHeight === lastHeightRef.current) {
      return;
    }

    handleUpdate();
  }, [handleUpdate, ref], RESIZE_THROTTLE, true);

  useLayoutEffect(handleUpdate, [handleUpdate, measureKey]);

  useResizeObserver(ref, handleResize, !withResizeObserver || !shouldRender);

  return {
    shouldRender,
    ref,
  };
}

function commitInMutatePhase(cb: NoneToVoidFunction) {
  if (getPhase() === 'mutate') {
    cb();
  } else {
    requestMutation(cb);
  }
}

function applyAnimationState({
  list,
  noTransition = false,
  snapEntrancesOnly = false,
  gapPx = PANE_GAP_REM * REM,
}: {
  list: PaneState[];
  noTransition?: boolean;
  snapEntrancesOnly?: boolean;
  gapPx?: number;
}) {
  let cumulativeHeight = 0;
  for (let i = 0; i < list.length; i++) {
    const state = list[i];
    const element = state.element;
    if (!element) {
      if (state.isSpacer) cumulativeHeight += state.height;
      continue;
    }

    const shiftPx = `${cumulativeHeight}px`;

    const isEntrance = !element.dataset.isPanelOpen && state.isOpen && !noTransition;

    const token = String(++placementCounter);
    element.dataset.placementToken = token;

    const apply = () => {
      setExtraStyles(element, {
        transform: `translateY(${state.isOpen ? shiftPx : `calc(${shiftPx} - 100% - ${gapPx}px)`})`,
        opacity: '1',
        zIndex: String(-i),
        transition: noTransition ? 'none' : '',
      });
    };

    const applyDeferred = () => {
      if (element.dataset.placementToken !== token) return;
      apply();
    };

    if (isEntrance && snapEntrancesOnly) {
      setExtraStyles(element, {
        transform: `translateY(${shiftPx})`,
        opacity: '1',
        zIndex: String(-i),
        transition: 'none',
      });
      element.dataset.isPanelOpen = 'true';
    } else if (isEntrance) {
      setExtraStyles(element, {
        transform: `translateY(calc(${shiftPx} - 100%))`,
        opacity: '1',
        zIndex: String(-i),
        transition: 'none',
      });
      element.dataset.isPanelOpen = 'true';
      requestNextMutation(applyDeferred);
    } else if (state.isOpen) {
      element.dataset.isPanelOpen = 'true';
      apply();
    } else {
      delete element.dataset.isPanelOpen;
      apply();
    }

    cumulativeHeight += state.height;
    if (state.height > 0) cumulativeHeight += gapPx;
  }
}

function transitionIslandVisual({
  container,
  toHeight,
  shouldGlide,
  hiddenClassName,
  suppressRowAnimationsUntilRef,
  noAutoUnhide,
  noFade,
  isCanceled,
}: {
  container: HTMLElement;
  toHeight: number;
  shouldGlide: boolean;
  hiddenClassName: string;
  suppressRowAnimationsUntilRef?: { current: number };
  noAutoUnhide?: boolean;
  noFade?: boolean;
  isCanceled?: () => boolean;
}) {
  const isHiddenNow = container.classList.contains(hiddenClassName);
  if (toHeight === 0) {
    setExtraStyles(container, { '--island-height-transition': '0s' });
    if (noFade) {
      toggleIslandHiddenInstantly(container, hiddenClassName, true);
    } else {
      addExtraClass(container, hiddenClassName);
    }
  } else if (isHiddenNow) {
    if (suppressRowAnimationsUntilRef) {
      suppressRowAnimationsUntilRef.current = performance.now() + ROW_ANIMATION_SUPPRESS_MS;
    }
    setExtraStyles(container, {
      '--island-height-transition': '0s',
      height: `${toHeight}px`,
    });
    if (!noAutoUnhide) {
      if (noFade) {
        toggleIslandHiddenInstantly(container, hiddenClassName, false);
      } else {
        requestNextMutation(() => {
          if (isCanceled?.()) return;
          removeExtraClass(container, hiddenClassName);
        });
      }
    }
  } else {
    setExtraStyles(container, {
      '--island-height-transition': shouldGlide ? 'var(--slide-transition)' : '0s',
      height: `${toHeight}px`,
    });
  }
}

function toggleIslandHiddenInstantly(container: HTMLElement, hiddenClassName: string, isHidden: boolean) {
  setExtraStyles(container, { transition: 'none' });
  toggleExtraClass(container, hiddenClassName, isHidden);
  requestForcedReflow(() => {
    void container.offsetWidth;
    return () => {
      setExtraStyles(container, { transition: '' });
    };
  });
}

