    },
  }, tabId);
}

function updateWebApp<T extends GlobalState>(
  global: T, key: string, webAppUpdate: Partial<WebApp>,
  ...[tabId = getCurrentTabId()]: TabArgs<T>
): T {
  const currentTabState = selectTabState(global, tabId);
  const browser = selectTabBrowserState(currentTabState);
  const openedTabs = browser.openedTabs;

  const originalTab = openedTabs[key];

  if (!originalTab || originalTab.type !== 'webApp') return global;

  const updatedValue = {
    ...originalTab.webApp,
    ...webAppUpdate,
  };

  const updatedWebAppKey = getBrowserWebAppTabKey(updatedValue);
  if (!updatedWebAppKey) return global;

  const updatedOpenedTabs = {
    ...openedTabs,
  };
  delete updatedOpenedTabs[key];
  updatedOpenedTabs[updatedWebAppKey] = {
    type: 'webApp',
    webApp: updatedValue,
  };

  global = updateTabState(global, {
    browser: {
      ...browser,
      activeTabKey: browser.activeTabKey === key ? updatedWebAppKey : browser.activeTabKey,
      openedTabs: updatedOpenedTabs,
      openedOrderedKeys: browser.openedOrderedKeys.map((tabKey) => (tabKey === key ? updatedWebAppKey : tabKey)),
      sessionKeys: browser.sessionKeys.map((tabKey) => (tabKey === key ? updatedWebAppKey : tabKey)),
    },
  }, tabId);

  return global;
}

function activateBrowserTabIfOpen<T extends GlobalState>(
  global: T, tabKey: string,
  ...[tabId = getCurrentTabId()]: TabArgs<T>
): T {
  const currentTabState = selectTabState(global, tabId);
  const browser = selectTabBrowserState(currentTabState);

  if (!browser.openedTabs[tabKey]) {
    return global;
  }

  global = updateTabState(global, {
    browser: {
      ...browser,
      isMoreAppsTabActive: false,
      activeTabKey: tabKey,
      modalState: 'maximized',
    },
  }, tabId);

  return global;
}

function addBrowserTabToOpenList<T extends GlobalState>(
  global: T, tab: BrowserTab,
  makeActive: boolean = true, openModalIfNotOpen: boolean = true,
  ...[tabId = getCurrentTabId()]: TabArgs<T>
): T {
  const currentTabState = selectTabState(global, tabId);
  const browser = selectTabBrowserState(currentTabState);

  const key = getBrowserTabKey(tab);

  if (!key) return global;
  const newOpenedKeys = [...browser.openedOrderedKeys];
  if (!newOpenedKeys.includes(key)) newOpenedKeys.push(key);

  const newSessionKeys = [...browser.sessionKeys];
  if (!newSessionKeys.includes(key)) newSessionKeys.push(key);

  global = updateTabState(global, {
    browser: {
      ...browser,
      activeTabKey: makeActive ? key : browser.activeTabKey,
      isMoreAppsTabActive: false,
      isModalOpen: openModalIfNotOpen || browser.isModalOpen,
      modalState: 'maximized',
      openedTabs: {
        ...browser.openedTabs,
        [key]: tab,
      },
      openedOrderedKeys: newOpenedKeys,
      sessionKeys: newSessionKeys,
    },
  }, tabId);

  return global;
}

function removeBrowserTabFromOpenList<T extends GlobalState>(
  global: T, key: string, skipClosingConfirmation?: boolean,
  ...[tabId = getCurrentTabId()]: TabArgs<T>
): T {
  const currentTabState = selectTabState(global, tabId);
  const browser = selectTabBrowserState(currentTabState);
  const { openedTabs, openedOrderedKeys, activeTabKey } = browser;
  const tab = openedTabs[key];
  if (!tab) return global;

  if (tab.type === 'webApp' && !skipClosingConfirmation && tab.webApp.shouldConfirmClosing) {
    return updateWebApp(global, key, { isCloseModalOpen: true }, tabId);
  }

  const updatedOpenedTabs = { ...openedTabs };
  delete updatedOpenedTabs[key];
  const newOpenedKeys = openedOrderedKeys.filter((tabKey) => tabKey !== key);
  const newSessionKeys = browser.sessionKeys.filter((tabKey) => updatedOpenedTabs[tabKey]);
  const isRemovedTabActive = activeTabKey === key;

  global = updateTabState(global, {
    browser: {
      ...browser,
      activeTabKey: getNextActiveTabKey(browser.activeTabKey, isRemovedTabActive, newOpenedKeys),
      openedTabs: updatedOpenedTabs,
      openedOrderedKeys: newOpenedKeys,
      sessionKeys: newSessionKeys,
    },
  }, tabId);

  return global;
}

function clearOpenedBrowserTabs<T extends GlobalState>(
  global: T, force?: boolean,
  ...[tabId = getCurrentTabId()]: TabArgs<T>
): T {
  const currentTabState = selectTabState(global, tabId);
  const browser = selectTabBrowserState(currentTabState);

  if (force) {
    return clearAllOpenedBrowserTabs(global, browser, tabId);
  }

  const tabsNotAllowedToClose = Object.fromEntries(
    Object.entries(browser.openedTabs).filter(([, tab]) => {
      return tab.type === 'webApp' && tab.webApp.shouldConfirmClosing;
    }),
  ) as Record<string, BrowserTab>;

  const tabsNotAllowedToCloseEntries = Object.entries(tabsNotAllowedToClose);
  const hasNotAllowedToCloseTabs = tabsNotAllowedToCloseEntries.length > 0;

  if (!hasNotAllowedToCloseTabs) {
    return clearAllOpenedBrowserTabs(global, browser, tabId);
  }

  const currentActiveWebApp = selectActiveWebApp(global, tabId);

  const newActiveWebApp = currentActiveWebApp?.shouldConfirmClosing
    ? currentActiveWebApp : findFirstWebApp(tabsNotAllowedToCloseEntries);

  const newActiveWebAppKey = newActiveWebApp && getBrowserWebAppTabKey(newActiveWebApp);

  if (newActiveWebAppKey) {
    tabsNotAllowedToClose[newActiveWebAppKey] = {
      type: 'webApp',
      webApp: {
        ...newActiveWebApp,
        isCloseModalOpen: true,
      },
    };
  }
  const newOpenedKeys = browser.openedOrderedKeys.filter((tabKey) => tabsNotAllowedToClose[tabKey]);
  const newSessionKeys = browser.sessionKeys.filter((tabKey) => tabsNotAllowedToClose[tabKey]);

  return updateTabState(global, {
    browser: {
      ...browser,
      activeTabKey: newActiveWebAppKey,
      isMoreAppsTabActive: false,
      openedTabs: tabsNotAllowedToClose,
      openedOrderedKeys: newOpenedKeys,
      sessionKeys: newSessionKeys,
    },
  }, tabId);
}

function hasOpenedBrowserTabs<T extends GlobalState>(
  global: T, ...[tabId = getCurrentTabId()]: TabArgs<T>
): boolean {
  return Object.keys(selectTabBrowserState(selectTabState(global, tabId)).openedTabs).length > 0;
}

function hasBrowserTabsRequiringCloseConfirmation<T extends GlobalState>(
  global: T, ...[tabId = getCurrentTabId()]: TabArgs<T>
): boolean {
  return Object.values(selectTabBrowserState(selectTabState(global, tabId)).openedTabs).some((tab) => {
    return tab.type === 'webApp' && Boolean(tab.webApp.shouldConfirmClosing);
  });
}

function replaceBrowserModalState<T extends GlobalState>(
  global: T, modalState: BrowserModalStateType,
  ...[tabId = getCurrentTabId()]: TabArgs<T>
): T {
  const currentTabState = selectTabState(global, tabId);
  const browser = selectTabBrowserState(currentTabState);
  return updateTabState(global, {
    browser: {
      ...browser,
      modalState,
    },
  }, tabId);
}

function replaceIsBrowserModalOpen<T extends GlobalState>(
  global: T, value: boolean,
  ...[tabId = getCurrentTabId()]: TabArgs<T>
): T {
  const currentTabState = selectTabState(global, tabId);
  const browser = selectTabBrowserState(currentTabState);
  return updateTabState(global, {
    browser: {
      ...browser,
      isModalOpen: value,
    },
  }, tabId);
}

function clearAllOpenedBrowserTabs<T extends GlobalState>(
  global: T, browser: BrowserState, tabId: number,
): T {
  return updateTabState(global, {
    browser: {
      ...browser,
      activeTabKey: undefined,
      isMoreAppsTabActive: false,
      openedTabs: {},
      openedOrderedKeys: [],
      sessionKeys: [],
    },
  }, tabId);
}

function findFirstWebApp(entries: [string, BrowserTab][]) {
  const entry = entries.find(([, tab]) => tab.type === 'webApp');
  const tab = entry?.[1];
  return tab?.type === 'webApp' ? tab.webApp : undefined;
}

function getNextActiveTabKey(
  activeTabKey: string | undefined, isRemovedTabActive: boolean, openedOrderedKeys: string[],
) {
  if (!isRemovedTabActive) return activeTabKey;

  return openedOrderedKeys.length ? openedOrderedKeys[openedOrderedKeys.length - 1] : undefined;
}

function useThrottledCallback<T extends AnyToVoidFunction>(
  fn: T,
  deps: any[],
  msOrSchedulerFn: number | Scheduler,
  noFirst = false,
) {
  // eslint-disable-next-line react-hooks-static-deps/exhaustive-deps
  const fnMemo = useCallback(fn, deps);

  return useMemo(() => {
    if (typeof msOrSchedulerFn === 'number') {
      return throttle(fnMemo, msOrSchedulerFn, !noFirst);
    } else {
      return throttleWith(msOrSchedulerFn, fnMemo);
    }
  }, [fnMemo, msOrSchedulerFn, noFirst]);
}

function getUserFirstOrLastName(user?: ApiUser) {
  if (!user) {
    return undefined;
  }

  switch (user.type) {
    case 'userTypeBot':
      return user.firstName;
    case 'userTypeRegular': {
      return user.firstName || user.lastName;
    }

    case 'userTypeDeleted':
    case 'userTypeUnknown': {
      return 'Deleted';
    }

    default:
      return undefined;
  }
}

function getUserFullName(user?: ApiUser) {
  if (!user) {
    return undefined;
  }

  if (isDeletedUser(user)) {
    return 'Deleted Account';
  }

  switch (user.type) {
    case 'userTypeBot':
    case 'userTypeRegular': {
      if (user.firstName && user.lastName) {
        return `${user.firstName} ${user.lastName}`;
      }

      if (user.firstName) {
        return user.firstName;
      }

      if (user.lastName) {
        return user.lastName;
      }

      if (user.phoneNumber) {
        return `+${formatPhoneNumber(user.phoneNumber)}`;
      }

      break;
    }
  }

  return undefined;
}

function getUserStatus(
  lang: OldLangFn, user: ApiUser, userStatus: ApiUserStatus | undefined,
) {
  if (user.id === SERVICE_NOTIFICATIONS_USER_ID) {
    return lang('ServiceNotifications');
  }

  if (user.isSupport) {
    return lang('SupportStatus');
  }

  if (user.type && user.type === 'userTypeBot') {
    if (user.botActiveUsers) {
      return lang('BotUsers', user.botActiveUsers, 'i');
    }
    return lang('Bot');
  }

  if (!userStatus) {
    return '';
  }

  switch (userStatus.type) {
    case 'userStatusEmpty': {
      return lang('ALongTimeAgo');
    }

    case 'userStatusLastMonth': {
      return lang('WithinAMonth');
    }

    case 'userStatusLastWeek': {
      return lang('WithinAWeek');
    }

    case 'userStatusOffline': {
      const { wasOnline } = userStatus;

      if (!wasOnline) return lang('LastSeen.Offline');

      const serverTimeOffset = getServerTimeOffset();
      const now = new Date(Date.now() + serverTimeOffset * 1000);
      const wasOnlineDate = new Date(wasOnline * 1000);

      if (wasOnlineDate >= now) {
        return lang('LastSeen.JustNow');
      }

      const diff = new Date(now.getTime() - wasOnlineDate.getTime());

      // within a minute
      if (diff.getTime() / 1000 < 60) {
        return lang('LastSeen.JustNow');
      }

      // within an hour
      if (diff.getTime() / 1000 < 60 * 60) {
        const minutes = Math.floor(diff.getTime() / 1000 / 60);
        return lang('LastSeen.MinutesAgo', minutes);
      }

      // today
      const today = new Date();
      today.setHours(0, 0, 0, 0);
      const serverToday = new Date(today.getTime() + serverTimeOffset * 1000);
      if (wasOnlineDate > serverToday) {
        // up to 6 hours ago
        if (diff.getTime() / 1000 < 6 * 60 * 60) {
          const hours = Math.floor(diff.getTime() / 1000 / 60 / 60);
          return lang('LastSeen.HoursAgo', hours);
        }

        // other
        return lang('LastSeen.TodayAt', formatTime(lang, wasOnlineDate));
      }

      // yesterday
      const yesterday = new Date();
      yesterday.setDate(now.getDate() - 1);
      yesterday.setHours(0, 0, 0, 0);
      const serverYesterday = new Date(yesterday.getTime() + serverTimeOffset * 1000);
      if (wasOnlineDate > serverYesterday) {
        return lang('LastSeen.YesterdayAt', formatTime(lang, wasOnlineDate));
      }

      return lang('LastSeen.AtDate', formatFullDate(lang, wasOnlineDate));
    }

    case 'userStatusOnline': {
      return lang('Online');
    }

    case 'userStatusRecently': {
      return lang('Lately');
    }

    default:
      return undefined;
  }
}

function isUserOnline(user: ApiUser, userStatus?: ApiUserStatus, withSelfOnline = false) {
  const { id, type } = user;

  if (!userStatus) {
    return false;
  }

  if (id === SERVICE_NOTIFICATIONS_USER_ID) {
    return false;
  }

  if (user.isSelf && !withSelfOnline) {
    return false;
  }

  return userStatus.type === 'userStatusOnline' && type !== 'userTypeBot';
}

function isDeletedUser(user: ApiUser) {
  return (user.type === 'userTypeDeleted' || user.type === 'userTypeUnknown')
    && user.id !== SERVICE_NOTIFICATIONS_USER_ID;
}

function isUserBot(user: ApiUser) {
  return user.type === 'userTypeBot';
}

function getCanAddContact(user: ApiUser) {
  return !user.isSelf && !user.isContact && !isUserBot(user) && user.id !== ANONYMOUS_USER_ID;
}

function sortUserIds(
  userIds: string[],
  usersById: Record<string, ApiUser>,
  userStatusesById: Record<string, ApiUserStatus>,
  priorityIds?: string[],
) {
  return orderBy(userIds, (id) => {
    const now = getServerTime();

    if (priorityIds && priorityIds.includes(id)) {
      // Assuming that online status expiration date can't be as far as two days from now,
      // this should place prioritized on top of the list.
      // Then we subtract index of `id` in `priorityIds` to preserve selected order
      return now + (48 * 60 * 60) - (priorityIds.length - priorityIds.indexOf(id));
    }

    const user = usersById[id];
    const userStatus = userStatusesById[id];
    if (!user || !userStatus) {
      return 0;
    }

    if (userStatus.type === 'userStatusOnline') {
      return userStatus.expires;
    } else if (userStatus.type === 'userStatusOffline' && userStatus.wasOnline) {
      return userStatus.wasOnline;
    }

    switch (userStatus.type) {
      case 'userStatusRecently':
        return now - DAY;
      case 'userStatusLastWeek':
        return now - DAY * 7;
      case 'userStatusLastMonth':
        return now - DAY * 7 * 30;
      default:
        return 0;
    }
  }, 'desc');
}

function getMainUsername(userOrChat: ApiPeer) {
  return userOrChat.usernames?.find((u) => u.isActive)?.username;
