function usePaidMessageConfirmation(
  starsForAllMessages: number,
  isStarsBalanceModeOpen: boolean,
  starsBalance: number,
  shouldDelayConfirmHandler?: boolean,
) {
  const {
    shouldPaidMessageAutoApprove,
  } = getGlobal().settings.byKey;

  const [shouldAutoApprove, setShouldAutoApprove] = useState(Boolean(shouldPaidMessageAutoApprove));
  const [isWaitingStarsTopup, setIsWaitingStarsTopup] = useState(false);
  const confirmPaymentHandlerRef = useRef<NoneToVoidFunction | undefined>(undefined);

  const closeConfirmDialog = useLastCallback(() => {
    getActions().closePaymentMessageConfirmDialogOpen();
  });

  useEffect(() => {
    if (isWaitingStarsTopup && !isStarsBalanceModeOpen) {
      setIsWaitingStarsTopup(false);

      if (starsBalance > starsForAllMessages) {
        confirmPaymentHandlerRef?.current?.();
      }
    }
  }, [isWaitingStarsTopup, isStarsBalanceModeOpen, starsBalance, starsForAllMessages]);

  const handleStarsTopup = useLastCallback(() => {
    getActions().openStarsBalanceModal({
      topup: {
        balanceNeeded: starsForAllMessages,
        purpose: PAID_MESSAGES_PURPOSE,
      },
    });
    setIsWaitingStarsTopup(true);
  });

  const dialogHandler = useLastCallback(() => {
    if (starsForAllMessages > starsBalance) {
      handleStarsTopup();
    } else if (shouldDelayConfirmHandler) {
      setTimeout(() => {
        confirmPaymentHandlerRef?.current?.();
      }, 250);
    } else {
      confirmPaymentHandlerRef?.current?.();
    }

    getActions().closePaymentMessageConfirmDialogOpen();
    if (shouldAutoApprove) getActions().setPaidMessageAutoApprove();
  });

  const handleWithConfirmation = useLastCallback(<T extends (...args: any[]) => void>(
    handler: T,
    ...args: Parameters<T>
  ) => {
    if (starsForAllMessages) {
      confirmPaymentHandlerRef.current = () => handler(...args);
      if (!shouldPaidMessageAutoApprove) {
        getActions().openPaymentMessageConfirmDialogOpen();
        return;
      }

      if (starsForAllMessages > starsBalance) {
        handleStarsTopup();
        return;
      }
    }

    handler(...args);
  });

  return {
    closeConfirmDialog,
    handleWithConfirmation,
    dialogHandler,
    shouldAutoApprove,
    setAutoApprove: setShouldAutoApprove,
  };
}

function useStoryPreloader(peerId?: string | string[], aroundStoryId?: number) {
  useEffect(() => {
    if (peerId === undefined) return;

    const preloadHashes = async (mediaHashes: Array<MediaHash>) => {
      await canPreload;
      mediaHashes.forEach(({ hash, format, isStream }) => {
        if (isStream) {
          preloadStream(hash);
          return;
        }
        mediaLoader.fetch(
          hash,
          format,
        )
          .then((result) => {
            if (!result) return;

            if (format === ApiMediaFormat.Progressive) {
              preloadProgressive(result);
            }
            if (format === ApiMediaFormat.BlobUrl) {
              preloadImage(result);
            }
          });
      });
    };

    const peerIds = Array.isArray(peerId) ? peerId : [peerId];

    peerIds.forEach((id) => {
      const storyId = aroundStoryId || getGlobal().stories.byPeerId[id]?.orderedIds?.[0];
      if (!storyId) return;
      preloadHashes(getPreloadMediaHashes(id, storyId));
    });
  }, [aroundStoryId, peerId]);
}

function findIdsAroundCurrentId<T>(ids: T[], currentId: T, aroundAmount: number): T[] {
  const currentIndex = ids.indexOf(currentId);
  const start = Math.max(currentIndex - aroundAmount, 0);
  const end = Math.min(currentIndex + aroundAmount, ids.length);
  return ids.slice(start, end);
}

function getPreloadMediaHashes(peerId: string, storyId: number) {
  const peerStories = selectPeerStories(getGlobal(), peerId);
  if (!peerStories || !peerStories.orderedIds?.length) {
    return [];
  }

  const preloadIds = findIdsAroundCurrentId(peerStories.orderedIds, storyId, PEER_STORIES_FOR_PRELOAD);

  const mediaHashes: Array<MediaHash> = [];
  preloadIds.forEach((currentStoryId) => {
    if (preloadedStories[peerId]?.has(currentStoryId)) {
      return;
    }

    const story = peerStories.byId[currentStoryId];
    if (!story || !('content' in story)) {
      return;
    }

    const isVideo = Boolean(story.content.video);

    // Media
    mediaHashes.push({
      hash: getStoryMediaHash(story, 'full'),
      format: isVideo ? ApiMediaFormat.Progressive : ApiMediaFormat.BlobUrl,
      isStream: isVideo && checkIfStreamingSupported(PRIMARY_VIDEO_MIME),
    });
    // Thumbnail
    mediaHashes.push({ hash: getStoryMediaHash(story), format: ApiMediaFormat.BlobUrl });
    if (story.content.video?.altVideos) {
      mediaHashes.push({
        hash: getStoryMediaHash(story, 'full', true)!,
        format: ApiMediaFormat.Progressive,
      });
    }

    preloadedStories[peerId] = (preloadedStories[peerId] || new Set()).add(currentStoryId);
  });

  return mediaHashes;
}

function preloadProgressive(url: string) {
  const head = document.head;
  const video = document.createElement('video');
  video.preload = 'auto';
  video.src = url;
  video.muted = true;
  video.autoplay = true;
  video.disableRemotePlayback = true;
  video.style.display = 'none';
  head.appendChild(video);
  video.load();
  setTimeout(() => {
    unloadVideo(video);
    head.removeChild(video);
  }, PROGRESSIVE_PRELOAD_DURATION);
}

async function preloadStream(hash: string) {
  const loader = makeProgressiveLoader(getProgressiveUrl(hash));
  let cachedSize = 0;
  for await (const chunk of loader) {
    cachedSize += chunk.byteLength;
    if (cachedSize >= STREAM_PRELOAD_SIZE) {
      break;
    }
  }
}

