function validateFiles(files: File[] | FileList | null): File[] | undefined {
  if (!files?.length) {
    return undefined;
  }
  return Array.from(files).map(fixMovMime).filter((file) => file.size);
}

function fixMovMime(file: File) {
  const ext = file.name.split('.').pop()!;
  if (!file.type && ext.toLowerCase() === 'mov') {
    return new File([file], file.name, { type: 'video/quicktime' });
  }
  return file;
}

function prepareSlotMachine(stickers: ApiSticker[], value: number) {
  const isLocal = value === -1;

  const leftSlot = (value - 1) & 0b11;
  const middleSlot = ((value - 1) >> 2) & 0b11;
  const rightSlot = ((value - 1) >> 4) & 0b11;

  const bg = stickers[0];
  const frameWin = stickers[1];
  const frameStart = stickers[2];

  const leftWin = stickers[3];
  const leftResult = !isLocal ? stickers[4 + SLOT_MAP[leftSlot]] : undefined;
  const leftSpin = stickers[8];

  const middleWin = stickers[9];
  const middleResult = !isLocal ? stickers[10 + SLOT_MAP[middleSlot]] : undefined;
  const middleSpin = stickers[14];

  const rightWin = stickers[15];
  const rightResult = !isLocal ? stickers[16 + SLOT_MAP[rightSlot]] : undefined;
  const rightSpin = stickers[20];

  return {
    background: bg,
    frameWin,
    frameStart,
    leftWin,
    leftResult,
    leftSpin,
    middleWin,
    middleResult,
    middleSpin,
    rightWin,
    rightResult,
    rightSpin,
  };
}

function handlePrevMonth(e: React.MouseEvent) {
    setCurrentMonthAndYear((d) => {
      const dateCopy = new Date(d);
      if (e.shiftKey) {
        dateCopy.setFullYear(dateCopy.getFullYear() - 1);
        if (dateCopy < minDate) {
          return new Date(minDate.getFullYear(), minDate.getMonth(), 1);
        }
      } else {
        dateCopy.setMonth(dateCopy.getMonth() - 1);
      }
      return dateCopy;
    });
  }

function handleNextMonth(e: React.MouseEvent) {
    setCurrentMonthAndYear((d) => {
      const dateCopy = new Date(d);
      if (e.shiftKey) {
        dateCopy.setFullYear(dateCopy.getFullYear() + 1);
        if (dateCopy > maxDate) {
          return new Date(maxDate.getFullYear(), maxDate.getMonth(), 1);
        }
      } else {
        dateCopy.setMonth(dateCopy.getMonth() + 1);
      }
      return dateCopy;
    });
  }

