function useMultiClick(amount: number, callback: NoneToVoidFunction) {
  const currentAmountRef = useRef(0);
  const timeoutRef = useRef<number>();
  const handleClick = useCallback(() => {
    currentAmountRef.current++;
    if (currentAmountRef.current === amount) {
      currentAmountRef.current = 0;
      callback();
      return;
    }

    if (timeoutRef.current) {
      clearTimeout(timeoutRef.current);
    }

    timeoutRef.current = setTimeout(() => {
      currentAmountRef.current = 0;
    }, CLICK_TIMEOUT);
  }, [amount, callback]);

  return handleClick;
}

function useVideoCleanup(
  videoRef: ElementRef<HTMLVideoElement>, handlers?: Record<string, AnyFunction>,
) {
  const handlersRef = useStateRef(handlers);

  useLayoutEffect(() => {
    const videoEl = videoRef.current;
    if (!videoEl) return undefined;

    return () => {
      // eslint-disable-next-line react-hooks-static-deps/exhaustive-deps
      const handlers2 = handlersRef.current;
      if (handlers2) {
        Object.entries(handlers2).forEach(([key, value]) => {
          videoEl.removeEventListener(resolveEventType(key, videoEl), value, false);
        });
      }

      // It may be slow (specifically on iOS), so we postpone it after unmounting
      onFullyIdle(() => {
        unloadVideo(videoEl);
      });
    };
  }, [handlersRef, videoRef]);
}

async function fetchJoinedCommunities() {
