function rehash() {
  const data = readFileSync(API_TL_PATH, 'utf8');

  const lines = data.split('\n');
  // eslint-disable-next-line no-console
  console.log(`Read ${lines.length} lines`);

  const resultLines = [];

  for (const line of lines) {
    // Skip comments and namespaces
    if (line.startsWith('//') || !line.endsWith(';') || !line.includes('=')) {
      resultLines.push(line);
      continue;
    }

    const hash = getHash(line);

    const params = line.split(' ');
    const name = params[0].split('#')[0];
    const rehashed = [`${name}#${hash}`, ...params.slice(1)].join(' ');

    resultLines.push(rehashed);
  }
  // eslint-disable-next-line no-console
  console.log(`Writing ${resultLines.length} lines`);

  writeFileSync(API_TL_PATH, resultLines.join('\n'));
}

function getHash(line) {
  line = line.replace(/;/g, '');
  const split = line.split(' ');
  const cleaned = [];
  cleaned.push(split[0].split('#')[0]); // Drop current hash
  for (let i = 1; i < split.length; i++) {
    let param = split[i];
    if (param.includes('?true')) continue; // Skip optional boolean flags
    param = param.replace(/bytes(?![:>])/, 'string'); // Bytes are strings, but not in Vector
    cleaned.push(param.replace(/[<>(){}]/g, ' ')); // Drop parenthesis
  }

  // Join and clean spaces
  const cleanedLine = cleaned.join(' ')
    .replace(/\s{2,}/g, ' ')
    .trim();
  return crc32(cleanedLine);
}

function crc32(str) {
  let crc = -1;
  for (let i = 0, iTop = str.length; i < iTop; i++) {
    crc = (crc >>> 8) ^ b_table[(crc ^ str.charCodeAt(i)) & 0xFF];
  }
  return ((crc ^ (-1)) >>> 0).toString(16);
}

function prepareForRegExp(html: string) {
  return html
    .replace(RE_SPACE, ' ')
    .replace(RE_BR, '\n')
    .replace(RE_CLEAN_HTML, '')
    .replace(RE_EXTRA_NEW_LINE, '');
}

function openSystemFilesDialog(accept = '*', callback: (e: Event) => void, noMultiple = false) {
  if (!fileSelector) {
    fileSelector = document.createElement('input');
    fileSelector.setAttribute('type', 'file');
  }

  fileSelector.setAttribute('accept', accept);

  if (noMultiple) {
    fileSelector.removeAttribute('multiple');
  } else {
    fileSelector.setAttribute('multiple', 'multiple');
  }

  // eslint-disable-next-line no-null/no-null
  fileSelector.onchange = null;
  fileSelector.value = '';
  fileSelector.onchange = callback;

  fileSelector.click();
}

