function areDeepEqual<T>(value1: T, value2: T): boolean {
  const type1 = typeof value1;
  const type2 = typeof value2;
  if (type1 !== type2) {
    return false;
  }

  // eslint-disable-next-line no-null/no-null
  if (type1 !== 'object' || value1 === null || value2 === null) {
    return value1 === value2;
  }

  const isArray1 = Array.isArray(value1);
  const isArray2 = Array.isArray(value2);

  if (isArray1 !== isArray2) {
    return false;
  }

  if (isArray1) {
    const array1 = value1 as any[];
    const array2 = value2 as any[];

    if (array1.length !== array2.length) {
      return false;
    }

    return array1.every((member1, i) => areDeepEqual(member1, array2[i]));
  }

  const object1 = value1 as AnyLiteral;
  const object2 = value2 as AnyLiteral;
  const keys1 = Object.keys(object1);

  return keys1.length === Object.keys(object2).length
    && keys1.every((key1) => areDeepEqual(object1[key1], object2[key1]));
}

async function respondWithCacheNetworkFirst(e: FetchEvent) {
  const remote = await withTimeout(() => fetch(e.request), TIMEOUT);
  if (!remote?.ok) {
    return respondWithCache(e);
  }

  const toCache = remote.clone();
  self.caches.open(ASSET_CACHE_NAME).then((cache) => {
    return cache?.put(e.request, toCache);
  });

  return remote;
}

async function respondWithCache(e: FetchEvent) {
  const cacheResult = await withTimeout(async () => {
    const cache = await self.caches.open(ASSET_CACHE_NAME);
    const cached = await cache.match(e.request);

    return { cache, cached };
  }, TIMEOUT);

  const { cache, cached } = cacheResult || {};

  if (cache && cached) {
    if (cached.ok) {
      return cached;
    } else {
      await cache.delete(e.request);
    }
  }

  const remote = await fetch(e.request);

  if (remote.ok && cache) {
    cache.put(e.request, remote.clone());
  }

  return remote;
}

async function withTimeout<T>(cb: () => Promise<T>, timeout: number) {
  let isResolved = false;

  try {
    return await Promise.race([
      pause(timeout).then(() => (isResolved ? undefined : Promise.reject(new Error('TIMEOUT')))),
      cb(),
    ]);
  } catch (err) {
    // eslint-disable-next-line no-console
    console.error(err);
    return undefined;
  } finally {
    isResolved = true;
  }
}

function clearAssetCache() {
  return self.caches.delete(ASSET_CACHE_NAME);
}

interface UseCanvasRendererOptions {
  canvasRef: React.RefObject<HTMLCanvasElement | undefined>;
  imageRef: React.RefObject<HTMLImageElement | undefined>;
  mode: 'crop' | 'draw';
  cropState: CropState;
  drawActions: DrawAction[];
  currentDrawAction?: DrawAction;
}

function useCanvasRenderer({
  canvasRef,
  imageRef,
  mode,
  cropState,
  drawActions,
  currentDrawAction,
}: UseCanvasRendererOptions) {
  const [canvasSize, setCanvasSize] = useState({ width: 0, height: 0 });

  const renderCanvas = useLastCallback(() => {
    const canvas = canvasRef.current;
    const img = imageRef.current;
    if (!canvas || !img) return;

    const crop = {
      x: cropState.cropperX, y: cropState.cropperY,
      width: cropState.cropperWidth, height: cropState.cropperHeight,
    };
    const ctx = canvas.getContext('2d');
    if (!ctx) return;

    const rotation = getTotalRotation(cropState);
    const { flipH } = cropState;

    if (mode === 'crop') {
      const { width: effW, height: effH } = getEffectiveDimensions(
        img.width, img.height, cropState.quarterTurns,
      );
      const zoom = computeRotationZoom(effW, effH, cropState.rotation);

      if (canvasSize.width !== effW || canvasSize.height !== effH) {
        setCanvasSize({ width: effW, height: effH });
        return;
      }

      renderImageToCanvas(ctx, img, crop, effW, effH, true, rotation, flipH, cropState.quarterTurns, zoom);

      const hasTransforms = rotation !== 0 || flipH || cropState.quarterTurns !== 0 || zoom !== 1;
      if (hasTransforms) {
        ctx.save();
        applyCanvasTransform(ctx, img, rotation, flipH, cropState.quarterTurns, zoom);
        renderActionsToCanvas(ctx, drawActions, 0, 0, undefined, img.width, img.height);
        ctx.restore();
      } else {
        renderActionsToCanvas(ctx, drawActions);
      }
    } else {
      if (crop.width <= 0 || crop.height <= 0) return;

      const targetWidth = Math.round(crop.width);
      const targetHeight = Math.round(crop.height);

      if (canvasSize.width !== targetWidth || canvasSize.height !== targetHeight) {
        setCanvasSize({ width: targetWidth, height: targetHeight });
        return;
      }

      const { width: effW, height: effH } = getEffectiveDimensions(
        img.width, img.height, cropState.quarterTurns,
      );
      const zoom = computeRotationZoom(effW, effH, cropState.rotation);
      const hasTransforms = rotation !== 0 || flipH || cropState.quarterTurns !== 0 || zoom !== 1;

      // Create temp canvas at effective dimensions
      const tempCanvas = document.createElement('canvas');
      tempCanvas.width = effW;
      tempCanvas.height = effH;
      const tempCtx = tempCanvas.getContext('2d')!;

      if (hasTransforms) {
        tempCtx.save();
        applyCanvasTransform(tempCtx, img, rotation, flipH, cropState.quarterTurns, zoom);
      }

      // Draw image and actions (in image coords, transformed to effective space)
      tempCtx.drawImage(img, 0, 0);
      renderActionsToCanvas(tempCtx, drawActions, 0, 0, currentDrawAction, img.width, img.height);

      if (hasTransforms) {
        tempCtx.restore();
      }

      // Crop from effective space
      ctx.drawImage(tempCanvas, crop.x, crop.y, crop.width, crop.height, 0, 0, targetWidth, targetHeight);
    }
  });

  // Throttle re-renders to one per animation frame
  const scheduleRender = useMemo(() => throttleWith(fastRaf, renderCanvas), [renderCanvas]);

  // Re-render canvas when dependencies change
  useEffect(() => {
    scheduleRender();
  }, [drawActions, currentDrawAction, canvasSize, mode, cropState, scheduleRender]);

  // Animation loop for arrow spreading effect
  const animationFrameRef = useRef<number>();
  useEffect(() => {
    const hasAnimatingArrow = () => drawActions.some((action) => {
      return action.tool === 'arrow' && action.completedAt
        && (Date.now() - action.completedAt) < ARROW_ANIMATION_DURATION;
    });

    if (!hasAnimatingArrow()) return undefined;

    const animate = () => {
      renderCanvas();
      if (hasAnimatingArrow()) {
        animationFrameRef.current = requestAnimationFrame(animate);
      }
    };

    animationFrameRef.current = requestAnimationFrame(animate);

    return () => {
      if (animationFrameRef.current) {
        cancelAnimationFrame(animationFrameRef.current);
      }
    };
  }, [drawActions, renderCanvas]);

  const resetCanvasSize = useLastCallback(() => {
    setCanvasSize({ width: 0, height: 0 });
  });

  return {
    canvasSize,
    renderCanvas,
    resetCanvasSize,
  };
}

function getMinutes(seconds: number, roundDown?: boolean) {
  const roundFunc = roundDown ? Math.floor : Math.ceil;
  return roundFunc(seconds / MINUTE);
}

function getHours(seconds: number, roundDown?: boolean) {
  const roundFunc = roundDown ? Math.floor : Math.ceil;
  return roundFunc(seconds / HOUR);
}

function getDays(seconds: number, roundDown?: boolean) {
  const roundFunc = roundDown ? Math.floor : Math.ceil;
  return roundFunc(seconds / DAY);
}

function getSeconds(hours: number, minutes: number, seconds: number) {
  return hours * HOUR + minutes * MINUTE + seconds;
}

function getDocumentIdFromLocation(location: Api.TypeInputFileLocation): number {
  if (location instanceof Api.InputDocumentFileLocation) {
    return toJSNumber(location.id);
  }

  if (location instanceof Api.InputPhotoFileLocation) {
    return toJSNumber(location.id);
  }

  throw new Error(`Unsupported input file location type ${location.className}`);
}

function checkPrimeAndGood(primeBytes: Uint8Array, g: number) {
  const goodPrime = new Uint8Array([
