function createTestUiSlice(pluginName: string) {
  const capturedErrors: CapturedError[] = [];
  const showNotification = vi.fn();

  const reporter: TgPluginReporter = {
    log: () => {},
    logError: (action, error) => {
      capturedErrors.push({ action, error });
    },
    wrap: (callback) => (...args) => {
      try {
        callback(...args);
      } catch (error) {
        capturedErrors.push({ action: 'callback failed', error });
      }
    },
  };

  const runtime: TgPluginRuntime = {
    isPluginEnabled: () => true,
    setPluginEnabled: () => {},
    createPluginReporter: () => {
      throw new Error('the ui slice never creates a reporter');
    },
    subscribeApiUpdates: () => () => {},
    subscribeToStoreChanges: () => {},
    getActions: () => {
      throw new Error('the ui slice never dispatches actions');
    },
    getCurrentTabId: () => 0,
    mainThreadId: 0,
    getActiveMessageList: () => undefined,
    getActiveChatId: () => {
      throw new Error('the ui slice never reads the store');
    },
    getCurrentUserId: () => {
      throw new Error('the ui slice never reads the store');
    },
    getChat: () => {
      throw new Error('the ui slice never reads the store');
    },
    getLocalizedString: () => {
      throw new Error('the ui slice never translates');
    },
    showNotification,
  };

  const context = createPluginContext(pluginName, reporter);

  return {
    context,
    ui: createUiSlice(context, runtime),
    capturedErrors,
    showNotification,
  };
}

function handleTouchStart(event: TouchEvent) {
  const x = event.touches[0].pageX;

  if (x <= SAFARI_EDGE_BACK_GESTURE_LIMIT || x >= window.innerWidth - SAFARI_EDGE_BACK_GESTURE_LIMIT) {
    isSafariGestureAnimation = true;
  }
}

function handleTouchEnd() {
  if (!isSafariGestureAnimation) {
    return;
  }

  setTimeout(() => {
    isSafariGestureAnimation = false;
  }, SAFARI_EDGE_BACK_GESTURE_DURATION);
}

function applyDeferredHistoryOperations() {
  const goOperations = deferredHistoryOperations.filter((op) => op.type === 'go');
  const stateOperations = deferredHistoryOperations.filter((op) => op.type !== 'go');
  const goCount = goOperations.reduce((acc, op) => acc + op.delta, 0);

  deferredHistoryOperations = [];

  if (goCount) {
    window.history.go(goCount);

    // If we have some `state` operations after the `go` operations, we need to wait until the popstate event
    // so the order of operations is correctly preserved
    if (stateOperations.length) {
      deferredPopstateOperations.push(...stateOperations);
      return;
    }
  }

  processStateOperations(stateOperations);
}

function processStateOperations(stateOperations: HistoryOperationState[]) {
  stateOperations.forEach((op) => window.history[op.type](op.data, '', op.hash));
}

function deferHistoryOperation(historyOperation: HistoryOperation) {
  if (!deferredHistoryOperations.length) {
    requestMeasure(applyDeferredHistoryOperations);
  }

  deferredHistoryOperations.push(historyOperation);
}

function resetHistory() {
  historyCursor = 0;
  historyState = [{
    index: 0,
    onBack: () => window.history.back(),
  }];

  window.history.replaceState({ index: 0, historyUniqueSessionId }, '', PATH_BASE);
}

function ensureHistoryInitialized() {
  if (isHistoryInitialized) {
    return;
  }

  isHistoryInitialized = true;
  resetHistory();
}

function cleanupClosed(alreadyClosedCount = 1) {
  let countClosed = alreadyClosedCount;
  for (let i = historyCursor - 1; i > 0; i--) {
    if (!historyState[i].isClosed) break;
    countClosed++;
  }
  if (countClosed) {
    isAlteringHistory = true;
    deferHistoryOperation({
      type: 'go',
      delta: -countClosed,
    });
  }
  return countClosed;
}

function cleanupTrashedState() {
  // Navigation to previous page reload, state of which was trashed by reload
  let isAnimationDisabled = false;
  for (let i = historyState.length - 1; i > 0; i--) {
    if (historyState[i].isClosed) {
      continue;
    }
    // TODO[history]: probably we should not call this inside the loop
    if (!isAnimationDisabled && isSafariGestureAnimation) {
      getActions().disableHistoryAnimations();
      isAnimationDisabled = true;
    }
    historyState[i].onBack?.();
  }

  resetHistory();
}

function useHistoryBack({
  isActive,
  shouldBeReplaced,
  shouldResetUrlHash,
  hash,
  onBack,
}: {
  isActive?: boolean;
  shouldBeReplaced?: boolean;
  hash?: string;
  shouldResetUrlHash?: boolean;
  onBack: VoidFunction;
}) {
  ensureHistoryInitialized();

  const lastOnBack = useLastCallback(onBack);

  // Active index of the record
  const indexRef = useRef<number>();
  const wasReplacedRef = useRef(false);

  const isFirstRenderRef = useRef(true);

  const pushState = useCallback((forceReplace = false) => {
    // Check if the old state should be replaced
    const shouldReplace = forceReplace || historyState[historyCursor].shouldBeReplaced;
    indexRef.current = shouldReplace ? historyCursor : ++historyCursor;

    historyCursor = indexRef.current;

    // Mark the previous record as replaced so effectBack doesn't perform back operation on the new record
    const previousRecord = historyState[indexRef.current];
    if (previousRecord && !previousRecord.isClosed) {
      previousRecord.markReplaced?.();
    }

    historyState[indexRef.current] = {
      index: indexRef.current,
      onBack: lastOnBack,
      shouldBeReplaced,
      markReplaced: () => {
        wasReplacedRef.current = true;
      },
    };

    deferHistoryOperation({
      type: shouldReplace ? 'replaceState' : 'pushState',
      data: {
        index: indexRef.current,
        historyUniqueSessionId,
      },
      // Space is a hack to make the browser completely remove the hash
      hash: hash ? `#${hash}` : (shouldResetUrlHash ? ' ' : undefined),
    });
  }, [hash, shouldBeReplaced, shouldResetUrlHash]);

  const processBack = useCallback(() => {
    // Only process back on open records
    if (indexRef.current && historyState[indexRef.current] && !wasReplacedRef.current) {
      historyState[indexRef.current].isClosed = true;
      wasReplacedRef.current = true;
      if (indexRef.current === historyCursor && !shouldBeReplaced) {
        historyCursor -= cleanupClosed();
      }
    }
  }, [shouldBeReplaced]);

  // Process back navigation when element is unmounted
  useEffectOnce(() => {
    isFirstRenderRef.current = false;
    return () => {
      if (!isActive || wasReplacedRef.current) return;
      processBack();
    };
  });

  useSyncEffect(([prevIsActive]) => {
    if (prevIsActive === isActive) return;
    if (isFirstRenderRef.current && !isActive) return;

    if (isActive) {
      pushState();
    } else {
      processBack();
    }
  }, [isActive, processBack, pushState]);
}

function detectCardType(cardNumber: string): number {
  cardNumber = cardNumber.replace(/\s/g, '');
  if (VISA.test(cardNumber)) {
    return CardType.Visa;
  }
  if (MIR.test(cardNumber)) {
    return CardType.Mir;
  }
  if (MASTERCARD1.test(cardNumber) || MASTERCARD2.test(cardNumber)) {
    return CardType.Mastercard;
  }
  return CardType.Default;
}

function detectCardTypeText(cardNumber: string): string {
  const cardType = detectCardType(cardNumber);
  return cards[cardType] || '';
}

function requestSharedCanvasCoordsRecalculation(
  ...sharedCanvasRefs: Array<ElementRef<HTMLCanvasElement> | undefined>
) {
  sharedCanvasRefs.forEach((sharedCanvasRef) => {
    const canvas = sharedCanvasRef?.current;
    if (canvas) {
      PENDING_SHARED_CANVAS_RECALCULATIONS.add(canvas);
    }
  });

  if (PENDING_SHARED_CANVAS_RECALCULATIONS.size) {
    SCHEDULE_SHARED_CANVAS_RECALCULATION();
  }
}

function useCoordsInSharedCanvas(
  containerRef: ElementRef<HTMLDivElement>,
  sharedCanvasRef?: ElementRef<HTMLCanvasElement>,
) {
  const [coords, setCoords] = useState<SharedCanvasCoords>();
  const sharedCanvasContainerRef = useMemo<ElementRef<HTMLElement>>(() => ({
    get current() {
      return sharedCanvasRef?.current?.parentElement || undefined;
    },
  }), [sharedCanvasRef]);

  const recalculate = useLastCallback((canvasMetrics?: SharedCanvasMetrics) => {
    const container = containerRef.current;
    const canvas = sharedCanvasRef?.current;
    if (!container || !canvas) {
      return;
    }

    const metrics = canvasMetrics || measureSharedCanvas(canvas);
    if (!metrics) {
      return;
    }
    if (!canvasMetrics) {
      requestSharedCanvasSizeUpdate(canvas, metrics);
    }

    const target = container.classList.contains('sticker-set-cover') || container.classList.contains('sticker-reaction')
      ? container
      : container.querySelector('img');
    if (!target) {
      return;
    }

    const { left, top } = getOffsetToContainer(target, metrics.parent);
    const x = round((left - metrics.left) / metrics.renderedWidth, 4) || 0;
    const y = round((top - metrics.top) / metrics.renderedHeight, 4) || 0;
    setCoords((currentCoords) => (
      currentCoords?.x === x
      && currentCoords.y === y
      && currentCoords.canvasWidth === metrics.width
      && currentCoords.canvasHeight === metrics.height
        ? currentCoords
        : { x, y, canvasWidth: metrics.width, canvasHeight: metrics.height }
    ));
  });

  useEffect(() => {
    if (sharedCanvasRef?.current) {
      requestSharedCanvasCoordsRecalculation(sharedCanvasRef);
    }
  }, [sharedCanvasRef]);
  useEffect(() => {
    const canvas = sharedCanvasRef?.current;
    if (!canvas) {
      return undefined;
    }

    let manager = SHARED_CANVAS_RECALCULATION_MANAGERS.get(canvas);
    if (!manager) {
      manager = createCallbackManager();
      SHARED_CANVAS_RECALCULATION_MANAGERS.set(canvas, manager);
    }

    const removeCallback = manager.addCallback(recalculate);
    return () => {
      removeCallback();
      if (!manager.hasCallbacks()) {
        SHARED_CANVAS_RECALCULATION_MANAGERS.delete(canvas);
      }
    };
  }, [recalculate, sharedCanvasRef]);

  const throttledRequestRecalculation = useThrottledCallback(
    () => requestSharedCanvasCoordsRecalculation(sharedCanvasRef),
    [sharedCanvasRef],
    THROTTLE_MS,
  );
  useResizeObserver(sharedCanvasContainerRef, throttledRequestRecalculation);
  useSharedIntersectionObserver(sharedCanvasRef, throttledRequestRecalculation);

  return useMemo(() => (coords ? { x: coords.x, y: coords.y } : undefined), [coords]);
}

get current() {
      return sharedCanvasRef?.current?.parentElement || undefined;
    }

function flushSharedCanvasCoordsRecalculations() {
  const canvases = Array.from(PENDING_SHARED_CANVAS_RECALCULATIONS);
  PENDING_SHARED_CANVAS_RECALCULATIONS.clear();

  canvases.forEach((canvas) => {
    const manager = SHARED_CANVAS_RECALCULATION_MANAGERS.get(canvas);
    if (!manager) {
      return;
    }

    runSharedCanvasCoordsRecalculations(canvas, manager);
  });
}

function runSharedCanvasCoordsRecalculations(
  canvas: HTMLCanvasElement,
  manager: CallbackManager<(metrics: SharedCanvasMetrics) => void>,
) {
  const metrics = measureSharedCanvas(canvas);
  if (!metrics) {
    return;
  }

  if (requestSharedCanvasSizeUpdate(canvas, metrics)) {
    requestMeasure(() => runSharedCanvasCoordsRecalculations(canvas, manager));
    return;
  }

  manager.runCallbacks(metrics);
}

function measureSharedCanvas(canvas?: HTMLCanvasElement): SharedCanvasMetrics | undefined {
  if (!canvas) {
    return undefined;
  }

  const parent = canvas.parentElement;
  const renderedWidth = canvas.offsetWidth;
  const renderedHeight = canvas.offsetHeight;
  const width = parent?.clientWidth;
  const height = parent?.clientHeight;
  if (!parent || !renderedWidth || !renderedHeight || !width || !height) {
    return undefined;
  }

  return {
    parent,
    ...getOffsetToContainer(canvas, parent),
    renderedWidth,
    renderedHeight,
    width,
    height,
    sizeFactor: canvas.width / renderedWidth,
  };
}

function requestSharedCanvasSizeUpdate(
  canvas: HTMLCanvasElement,
  { width, height, sizeFactor }: SharedCanvasMetrics,
) {
  const cssWidth = `${width}px`;
  const cssHeight = `${height}px`;
  if (canvas.style.width === cssWidth && canvas.style.height === cssHeight) {
    return false;
  }

  requestMutation(() => {
    canvas.style.width = cssWidth;
    canvas.style.height = cssHeight;
    canvas.width = Math.round(width * sizeFactor);
    canvas.height = Math.round(height * sizeFactor);
  });

  return true;
}

interface DefaultOptions {
  logger: Logger;
  retries: number;
  retriesToFallback: number;
  retryMainConnectionDelay: number;
  delay: number;
  dcId: number;
  senderIndex?: number;
  timeOffset?: number;
  autoReconnect: boolean;
  shouldForceHttpTransport: boolean;
  shouldAllowHttpTransport: boolean;
  connectTimeout: number;
  authKeyCallback: any;
  updateCallback?: any;
  autoReconnectCallback?: any;
  isMainSender?: boolean;
  isExported?: boolean;
  senderCallback?: any;
  onConnectionBreak?: CallableFunction;
  getShouldDebugExportedSenders?: () => boolean;
}

class MTProtoSender {
  static DEFAULT_OPTIONS: Partial<DefaultOptions> = {
    logger: undefined,
    retries: Infinity,
    retriesToFallback: 1,
    delay: 2000,
    retryMainConnectionDelay: 10000,
    shouldForceHttpTransport: false,
    shouldAllowHttpTransport: false,
    autoReconnect: true,
    connectTimeout: undefined,
    authKeyCallback: undefined,
    updateCallback: undefined,
    autoReconnectCallback: undefined,
    isMainSender: undefined,
    onConnectionBreak: undefined,
    isExported: undefined,
    getShouldDebugExportedSenders: undefined,
  };

  _connection?: Connection;

  _fallbackConnection?: Connection;

  private _shouldForceHttpTransport: boolean;

  private _shouldAllowHttpTransport: boolean;

  private _retriesToFallback: number;

  private readonly _log: Logger;

  _dcId: number;

  _senderIndex: number;

  private readonly _retries: number;

  private readonly _delay: number;

  private _retryMainConnectionDelay: number;

  private _isFallback: boolean;

  private _shouldUseFallbackOnReconnect: boolean;

  private readonly _authKeyCallback: any;

  public _updateCallback: (
    update: Update,
  ) => void;

  private readonly _autoReconnectCallback?: any;

  private readonly _isMainSender: boolean;

  private readonly _isExported: boolean;

  private _sendQueue: MessagePacker;

  private _sendQueueLongPoll: MessagePacker;

  private isSendingLongPoll?: boolean;

  private readonly _pendingAck: Set<bigint>;

  private readonly _lastAcks: any[];

  private readonly _acknowledgedMsgIds: Set<bigint>;

  private readonly _recentSentMessages: Map<bigint, SentMessage>;

  private readonly _sentMessageIdsByState: Map<RequestState, bigint>;

  private readonly _sentMessageIdsByContainer: Map<bigint, Set<bigint>>;

  private _lastSessionFirstMsgId?: bigint;

  private _lastSessionUniqueId?: bigint;

  _pendingState: PendingState;

  _userConnected: boolean;

  isReconnecting: boolean;

  _disconnected: boolean;

  private _sendLoopHandle: any;

  private _recvLoopHandle: any;

  private _longPollLoopHandle: any;

  private _isReconnectingToMain = false;

  private futureServerSaltRefreshTimer?: ReturnType<typeof setTimeout>;

  private futureServerSaltRequest?: Promise<Api.TypeFutureSalts | undefined>;

  private hasHandledHttpAuthKeyError = false;

  readonly authKey: AuthKey;

  private readonly _state: MTProtoState;

  _getShouldDebugExportedSenders?: () => boolean;

  private readonly _handlers: Record<number, (message: TLMessage) => void | Promise<void>>;

  private readonly _onConnectionBreak?: CallableFunction;

  userDisconnected: boolean;

  isConnecting = false;

  _authenticated = false;

  /**
   * @param authKey
   * @param opts
   */
  constructor(authKey: AuthKey, opts: DefaultOptions) {
    const args = { ...MTProtoSender.DEFAULT_OPTIONS, ...opts };
    this._connection = undefined;
    this._fallbackConnection = undefined;
    this._shouldForceHttpTransport = args.shouldForceHttpTransport;
    this._shouldAllowHttpTransport = args.shouldAllowHttpTransport;
    this._log = args.logger;
    this._dcId = args.dcId;
    this._senderIndex = args.senderIndex || 0;
    this._retries = args.retries;
    this._retriesToFallback = args.retriesToFallback;
    this._delay = args.delay;
    this._retryMainConnectionDelay = args.retryMainConnectionDelay;
    this._authKeyCallback = args.authKeyCallback;
    this._updateCallback = args.updateCallback;
    this._autoReconnectCallback = args.autoReconnectCallback;
    this._isMainSender = Boolean(args.isMainSender);
    this._isExported = Boolean(args.isExported);
    this._onConnectionBreak = args.onConnectionBreak;
    this._isFallback = false;
    this._shouldUseFallbackOnReconnect = false;
    this._getShouldDebugExportedSenders = args.getShouldDebugExportedSenders;

    /**
     * whether we disconnected ourself or telegram did it.
     */
    this.userDisconnected = false;

    /**
     * Whether the user has explicitly connected or disconnected.
     *
     * If a disconnection happens for any other reason and it
     * was *not* user action then the pending messages won't
     * be cleared but on explicit user disconnection all the
     * pending futures should be cancelled.
     */
    this._userConnected = false;
    this.isReconnecting = false;
    this._disconnected = true;

    /**
     * We need to join the loops upon disconnection
     */
    this._sendLoopHandle = undefined;
    this._longPollLoopHandle = undefined;
    this._recvLoopHandle = undefined;

    /**
     * Preserving the references of the AuthKey and state is important
     */
    this.authKey = authKey || new AuthKey();
    this._state = new MTProtoState(this.authKey, this._log);
    this._state.timeOffset = args.timeOffset ?? 0;

    /**
     * Outgoing messages are put in a queue and sent in a batch.
     * Note that here we're also storing their ``_RequestState``.
     */
    this._sendQueue = new MessagePacker(this._state, this._log);
    this._sendQueueLongPoll = new MessagePacker(this._state, this._log);

    /**
     * Sent states are remembered until a response is received.
     */
    this._pendingState = new PendingState();

    /**
     * Responses must be acknowledged, and we can also batch these.
     */
    this._pendingAck = new Set();

    /**
     * Similar to pending_messages but only for the last acknowledges.
     * These can't go in pending_messages because no acknowledge for them
     * is received, but we may still need to resend their state on bad salts.
     */
    this._lastAcks = [];
    this._acknowledgedMsgIds = new Set();
    this._recentSentMessages = new Map();
    this._sentMessageIdsByState = new Map();
    this._sentMessageIdsByContainer = new Map();

    /**
     * Jump table from response ID to method that handles it
     */

    this._handlers = {
      [RPCResult.CONSTRUCTOR_ID]: this._handleRPCResult.bind(this),
      [MessageContainer.CONSTRUCTOR_ID]: this._handleContainer.bind(this),
      [GZIPPacked.CONSTRUCTOR_ID]: this._handleGzipPacked.bind(this),
      [Api.Pong.CONSTRUCTOR_ID]: this._handlePong.bind(this),
      [Api.BadServerSalt.CONSTRUCTOR_ID]: this._handleBadServerSalt.bind(this),
      [Api.BadMsgNotification.CONSTRUCTOR_ID]: this._handleBadNotification.bind(this),
      [Api.MsgDetailedInfo.CONSTRUCTOR_ID]: this._handleDetailedInfo.bind(this),
      [Api.MsgNewDetailedInfo.CONSTRUCTOR_ID]: this._handleNewDetailedInfo.bind(this),
      [Api.NewSessionCreated.CONSTRUCTOR_ID]: this._handleNewSessionCreated.bind(this),
      [Api.MsgsAck.CONSTRUCTOR_ID]: this._handleAck.bind(this),
      [Api.FutureSalts.CONSTRUCTOR_ID]: this._handleFutureSalts.bind(this),
      [Api.MsgsStateReq.CONSTRUCTOR_ID]: this._handleStateReq.bind(this),
      [Api.MsgResendReq.CONSTRUCTOR_ID]: this._handleResendReq.bind(this),
      [Api.MsgsStateInfo.CONSTRUCTOR_ID]: this._handleStateInfo.bind(this),
      [Api.MsgsAllInfo.CONSTRUCTOR_ID]: this._handleMsgAll.bind(this),
    };
  }

  // Public API

  logWithIndexCallback(level: 'debug' | 'log' | 'warn' | 'error') {
    return (...args: unknown[]) => {
      if (!this._getShouldDebugExportedSenders
        || !this._getShouldDebugExportedSenders()) return;
      // eslint-disable-next-line no-console
      console[level](`[${this._isExported ? `idx=${this._senderIndex} ` : 'M '}dcId=${this._dcId}]`, ...args);
    };
  }

  logWithIndex = {
    debug: this.logWithIndexCallback('debug'),
    log: this.logWithIndexCallback('log'),
    warn: this.logWithIndexCallback('warn'),
    error: this.logWithIndexCallback('error'),
  };

  getConnection(): Connection | undefined {
    return this._isFallback ? this._fallbackConnection : this._connection;
  }

  /**
   * Connects to the specified given connection using the given auth key.
   * @param connection
   * @param [force]
   * @param fallbackConnection
   * @param shouldUseFallback
   * @returns {Promise<boolean>}
   */
  async connect(
    connection: Connection,
    force: boolean,
    fallbackConnection?: Connection,
    shouldUseFallback?: boolean,
  ) {
    this.userDisconnected = false;

    if (this._userConnected && !force) {
      this._log.info('User is already connected!');
      return false;
    }
    this.isConnecting = true;
    this._isFallback = Boolean((this._shouldForceHttpTransport || shouldUseFallback)
      && this._shouldAllowHttpTransport);
    this._connection = connection;
    this._fallbackConnection = fallbackConnection;
    let hasConnected = false;
    let connectionError: unknown;

    for (let attempt = 0; attempt < this._retries + this._retriesToFallback; attempt++) {
      const hasAuthKey = Boolean(this.authKey.getKey());
      try {
        if (attempt >= this._retriesToFallback && this._shouldAllowHttpTransport) {
          this._isFallback = true;
          this.logWithIndex.warn('Using fallback connection');
          this._log.warn('Using fallback connection');
        }
        this.logWithIndex.warn('Connecting...');
        await this._connect(this.getConnection()!);
        this.logWithIndex.warn('Connected!');
        if (!this._isExported) {
          this._updateCallback?.(new UpdateConnectionState(UpdateConnectionState.connected));
        }
        hasConnected = true;
        break;
      } catch (err) {
        connectionError = err;
        if (this.shouldResetHttpAuthKey(err, hasAuthKey)) {
          if (!this._isExported) this._handleBadAuthKey();
          break;
        }
        if (!this._isExported && attempt === 0) {
          this._updateCallback?.(new UpdateConnectionState(UpdateConnectionState.disconnected));
        }
        this._log.error(`${this._isFallback ? 'HTTP' : 'WebSocket'} connection failed attempt: ${attempt + 1}`);
        // eslint-disable-next-line no-console
        console.error(err);
        await sleep(this._delay);
      }
    }
    this.isConnecting = false;
    if (!hasConnected) {
      throw connectionError instanceof Error ? connectionError : new Error('Connection failed');
    }

    if (this._isFallback && !this._shouldForceHttpTransport) {
      void this.tryReconnectToMain();
    }

    return true;
  }

  async tryReconnectToMain() {
    if (this._isReconnectingToMain || !this.canRetryMainConnection()) return;

    this._isReconnectingToMain = true;
    let attempt = 0;

    try {
      while (this.canRetryMainConnection()) {
        const delayMultiplier = MAIN_CONNECTION_RETRY_DELAY_MULTIPLIERS[
          Math.min(attempt, MAIN_CONNECTION_RETRY_DELAY_MULTIPLIERS.length - 1)
        ];
        const retryDelay = Math.min(
          this._retryMainConnectionDelay * delayMultiplier,
          MAX_MAIN_CONNECTION_RETRY_DELAY,
        );
        this._log.debug(`Trying to reconnect to main connection in ${retryDelay}ms`);
        await sleep(retryDelay);

        if (!this.canRetryMainConnection()) return;

        try {
          await this._connection!.connect();
          this.isReconnecting = true;
          if (this._fallbackConnection) this._disconnect(this._fallbackConnection);
          await this.connect(this._connection!, true, this._fallbackConnection);
          this.isReconnecting = false;

          if (this._isFallback) {
            this._log.error('Failed to reconnect to main connection');
            attempt++;
            continue;
          }

          this._log.info('Reconnected to main connection');
          this.logWithIndex.warn('Reconnected to main connection');
          return;
        } catch {
          this.isReconnecting = false;
          this._isFallback = true;
          this._log.error('Failed to reconnect to main connection');
          attempt++;
        }
      }
    } finally {
      this._isReconnectingToMain = false;
    }
  }

  private canRetryMainConnection() {
    return !this.userDisconnected && !this.isConnecting && this._isFallback && !this.isReconnecting
      && !this._shouldForceHttpTransport && !this._isExported;
  }

  isConnected() {
    return this._userConnected;
  }

  /**
   * Cleanly disconnects the instance from the network, cancels
   * all pending requests, and closes the send and receive loops.
   */
  disconnect() {
    this.userDisconnected = true;
    this.logWithIndex.warn('Disconnecting...');
    const connection = this.getConnection();
    if (!connection) return;
    this._disconnect(connection);
  }

  destroy() {
    this._sendQueue.clear();
  }

  /**
   *
   This method enqueues the given request to be sent. Its send
   state will be saved until a response arrives, and a ``Future``
   that will be resolved when the response arrives will be returned:

   .. code-block:: javascript

   async def method():
   # Sending (enqueued for the send loop)
   future = sender.send(request)
   # Receiving (waits for the receive loop to read the result)
   result = await future

   Designed like this because Telegram may send the response at
   any point, and it can send other items while one waits for it.
   Once the response for this future arrives, it is set with the
   received result, quite similar to how a ``receive()`` call
   would otherwise work.

   Since the receiving part is "built in" the future, it's
   impossible to await receive a result that was never sent.
   * @param request
   * @param abortSignal
   * @param isLongPoll
   * @returns {RequestState}
   */
  send<T extends CallableRequest>(request: T, abortSignal?: AbortSignal, isLongPoll = false) {
    const states = this._splitMessageIdRequest(request)
      .map((splitRequest) => new RequestState(splitRequest, abortSignal));
    for (let index = 1; index < states.length; index++) {
      void states[index].promise!.catch(() => undefined);
    }
    if (!isLongPoll) {
      this.logWithIndex.debug(`Send ${request.className}`);
      this._sendQueue.extend(states);
    } else {
      this._sendQueueLongPoll.extend(states);
    }
    return states[0].promise as RequestState<T>['promise'];
  }

  private _splitMessageIdRequest(request: CallableRequest) {
    if (!(request instanceof Api.MsgsAck
      || request instanceof Api.MsgsStateReq
      || request instanceof Api.MsgResendReq)
    || request.msgIds.length <= MAX_MESSAGE_IDS) return [request];

    const requests: CallableRequest[] = [];
    for (let index = 0; index < request.msgIds.length; index += MAX_MESSAGE_IDS) {
      const msgIds = request.msgIds.slice(index, index + MAX_MESSAGE_IDS);
      if (request instanceof Api.MsgsAck) {
        requests.push(new Api.MsgsAck({ msgIds }));
      } else if (request instanceof Api.MsgsStateReq) {
        requests.push(new Api.MsgsStateReq({ msgIds }));
      } else {
        requests.push(new Api.MsgResendReq({ msgIds }));
      }
    }

    return requests;
  }

  addStateToQueue(state: RequestState) {
    this._sendQueue.append(state);
  }

  async sendBeacon(request: CallableRequest) {
    if (!this._userConnected || !(this._fallbackConnection instanceof HttpConnection)) {
      throw new Error('Cannot send requests while disconnected');
    }
    const state = new RequestState(request, undefined);
    const data = this._sendQueue.getBeacon(state);
    if (!data) return;
    const encryptedData = await this._state.encryptMessageData(data);

    postMessage({
      payloads: [{
        type: 'sendBeacon',
        data: encryptedData,
        url: this._fallbackConnection.href,
      }],
    });
  }

  /**
   * Performs the actual connection, retrying, generating the
   * authorization key if necessary, and starting the send and
   * receive loops.
   * @returns {Promise<void>}
   * @private
   */
  async _connect(connection: Connection) {
    const wasReconnecting = this.isReconnecting;
    const shouldCheckHttpConnection = connection instanceof HttpConnection && Boolean(this.authKey.getKey());

    if (!connection.isConnected()) {
      this._log.info('Connecting to {0}...'.replace('{0}', connection._ip));
      await connection.connect();
      this._log.debug('Connection success!');
    }

    if (!this.authKey.getKey()) {
      const plain = new MtProtoPlainSender(connection, this._log);
      this._log.debug('New auth_key attempt ...');
      const res = await doAuthentication(plain, this._log, connection._dcId, connection._isTestServer);
      this._log.debug('Generated new auth_key successfully');
      await this.authKey.setKey(res.authKey);

      this._state.resetForNewAuthKey();
      this._state.timeOffset = res.timeOffset;
      this._state.setServerSalt(res.serverSalt);

      if (!this._isExported) {
        this._updateCallback?.(new UpdateServerTimeOffset(this._state.timeOffset));
      }

      /**
       * This is *EXTREMELY* important since we don't control
       * external references to the authorization key, we must
       * notify whenever we change it. This is crucial when we
       * switch to different data centers.
       */
      if (this._authKeyCallback) {
        await this._authKeyCallback(this.authKey, this._dcId);
      }
    } else {
      this._authenticated = true;
      this._log.debug('Already have an auth key ...');
    }

    if (shouldCheckHttpConnection) {
      const httpConnectionCheck = new RequestState(new Api.Ping({ pingId: generateRandomLong() }));
      const resolveHttpConnectionCheck = httpConnectionCheck.resolve!;
      let hasReceivedPong = false;
      httpConnectionCheck.resolve = (pong) => {
        hasReceivedPong = true;
        resolveHttpConnectionCheck(pong);
      };
      const pingData = this._sendQueue.getBeacon(httpConnectionCheck)!;
      this._rememberSentMessage(httpConnectionCheck);

      try {
        await connection.send(await this._state.encryptMessageData(pingData));
        const response = await connection.recv();
        const message = await this.decryptMessageData(response);
        this._pendingState.set(httpConnectionCheck.msgId!, httpConnectionCheck);
        await this._processMessage(message);
        if (message.obj instanceof Api.Pong && !hasReceivedPong) {
          throw new Error('HTTP connection check did not receive a matching pong');
        }
      } catch (err) {
        this._pendingState.delete(httpConnectionCheck.msgId!);
        this._deleteSentMessage(httpConnectionCheck.msgId!);
        connection.disconnect();
        throw err;
      }
    }

    this._userConnected = true;
    this.isReconnecting = false;

    if (!this._sendLoopHandle) {
      this._log.debug('Starting send loop');
      this._sendLoopHandle = this._sendLoop();
    } else if (wasReconnecting) {
      this.retryPendingStates();
    }

    if (!this._recvLoopHandle) {
      this._log.debug('Starting receive loop');
      this._recvLoopHandle = this._recvLoop();
    }

    if (!this._longPollLoopHandle && connection.shouldLongPoll) {
      this._log.debug('Starting long-poll loop');
      this._longPollLoopHandle = this._longPollLoop();
    }

    this.scheduleFutureServerSaltRefresh(SERVER_SALT_REQUEST_RETRY_DELAY);

    // _disconnected only completes after manual disconnection
    // or errors after which the sender cannot continue such
    // as failing to reconnect or any unexpected error.

    this._log.info('Connection to %s complete!'.replace('%s', connection.toString()));
  }

  private async decryptMessageData(body: Uint8Array) {
    const previousTimeOffset = this._state.timeOffset;
    const message = await this._state.decryptMessageData(
      body, this._hasRecentSentMessage.bind(this),
    ) as TLMessage;

    if (!this._isExported && this._state.timeOffset !== previousTimeOffset) {
      this._updateCallback?.(new UpdateServerTimeOffset(this._state.timeOffset));
    }

    return message;
  }

  private requestFutureServerSalts() {
    if (!this._userConnected || this.futureServerSaltRequest) return;

    const request = this.send(new Api.GetFutureSalts({ num: MAX_FUTURE_SERVER_SALTS }))!;
    this.futureServerSaltRequest = request;
    void request
      .then((futureSalts) => {
        if (this.futureServerSaltRequest !== request) return;
        if (!futureSalts?.salts.length) {
          this.scheduleFutureServerSaltRefresh(SERVER_SALT_REQUEST_RETRY_DELAY);
          return;
        }

        const latestValidUntil = futureSalts.salts.reduce((latest, { validUntil }) => (
          Math.max(latest, validUntil)
        ), 0);
        const serverTime = this._state.getServerTime();
        const refreshDelay = Math.max(
          (latestValidUntil - serverTime - SERVER_SALT_REFRESH_MARGIN) * MILLISECONDS_PER_SECOND,
          SERVER_SALT_REQUEST_RETRY_DELAY,
        );
        this.scheduleFutureServerSaltRefresh(refreshDelay);
      })
      .catch((err: unknown) => {
        if (this.futureServerSaltRequest !== request) return;
        this._log.warn(`Failed to request future server salts: ${String(err)}`);
        this.scheduleFutureServerSaltRefresh(SERVER_SALT_REQUEST_RETRY_DELAY);
      })
      .finally(() => {
        if (this.futureServerSaltRequest === request) this.futureServerSaltRequest = undefined;
      });
  }

  private scheduleFutureServerSaltRefresh(delay: number) {
    if (!this._userConnected) return;
    if (this.futureServerSaltRefreshTimer) clearTimeout(this.futureServerSaltRefreshTimer);

    this.futureServerSaltRefreshTimer = setTimeout(() => {
      this.futureServerSaltRefreshTimer = undefined;
      this.requestFutureServerSalts();
    }, delay);
  }

  _disconnect(connection: Connection) {
    if (!this._isExported) {
      this._updateCallback?.(new UpdateConnectionState(UpdateConnectionState.disconnected));
    }

    if (connection === undefined) {
      this._log.info('Not disconnecting (already have no connection)');
      return;
    }

    this._log.info('Disconnecting from %s...'.replace('%s', connection.toString()));
    this._userConnected = false;
    this.futureServerSaltRequest = undefined;
    if (this.futureServerSaltRefreshTimer) {
      clearTimeout(this.futureServerSaltRefreshTimer);
      this.futureServerSaltRefreshTimer = undefined;
    }
    this._log.debug('Closing current connection...');
    this.logWithIndex.warn('Disconnecting');
    connection.disconnect();
  }

  async _longPollLoop() {
    while (this._userConnected && !this.isReconnecting && this._isFallback
      && this.getConnection()!.shouldLongPoll) {
      await this._sendQueueLongPoll.wait();

      const res = this._sendQueueLongPoll.get();

      if (this.isReconnecting || !this._isFallback) {
        this._longPollLoopHandle = undefined;
        return;
      }

      if (!res) {
        continue;
      }
      let { data } = res;
      const { batch } = res;
      this._log.debug(`Encrypting ${batch.length} message(s) in ${data.length} bytes for sending`);

      for (const state of batch) this._rememberSentMessage(state);

      data = await this._state.encryptMessageData(data);

      try {
        await this._fallbackConnection?.send(data);
      } catch (e: any) {
        this._log.info('Connection closed while sending data');
        // eslint-disable-next-line no-console
        console.error(e);
        this._longPollLoopHandle = undefined;
        this.isSendingLongPoll = false;
        if (!this.userDisconnected) {
          this.handleConnectionError(e);
        }
        return;
      }

      this.isSendingLongPoll = false;
      this.checkLongPoll();
    }

    this._longPollLoopHandle = undefined;
  }

  /**
   * This loop is responsible for popping items off the send
   * queue, encrypting them, and sending them over the network.
   * Besides `connect`, only this method ever sends data.
   * @returns {Promise<void>}
   * @private
   */
  async _sendLoop() {
    this.retryPendingStates();

    while (this._userConnected && !this.isReconnecting) {
      const appendAcks = () => {
        if (this._pendingAck.size) {
          const msgIds = Array.from(this._pendingAck);
          this._pendingAck.clear();

          // https://core.telegram.org/mtproto/service_messages_about_messages#acknowledgment-of-receipt
          for (let index = 0; index < msgIds.length; index += MAX_MESSAGE_IDS) {
            const ack = new RequestState(new Api.MsgsAck({
              msgIds: msgIds.slice(index, index + MAX_MESSAGE_IDS),
            }));
            this._sendQueue.append(ack);
            this._lastAcks.push(ack);
            if (this._lastAcks.length >= 10) this._lastAcks.shift();
          }
        }
      };

      appendAcks();

      this.logWithIndex.debug(`Waiting for messages to send... ${this.isReconnecting}`);
      this._log.debug(`Waiting for messages to send... ${this.isReconnecting}`);
      // TODO Wait for the connection send queue to be empty?
      // This means that while it's not empty we can wait for
      // more messages to be added to the send queue.
      await this._sendQueue.wait();

      // If we've had new ACKs appended while waiting for messages to send, add them to queue
      appendAcks();

      const hasQueuedMessages = this._sendQueue.values().some(Boolean);
      if (!hasQueuedMessages) {
        // Consume explicit empty queue markers before waiting again
        this._sendQueue.get();
        continue;
      }

      if (this._isFallback) {
        // We don't long-poll on main loop, instead we have a separate loop for that
        this.send(new Api.HttpWait({
          maxDelay: 0,
          waitAfter: 0,
          maxWait: 0,
        }));
      }

      const res = this._sendQueue.get();

      this.logWithIndex.debug(`Got ${res?.batch.length} message(s) to send`);

      if (!res) {
        continue;
      }

      let { data } = res;
      const { batch } = res;

      for (const state of batch) {
        if (!Array.isArray(state)) {
          this._rememberSentMessage(state);
          if (this._shouldTrackPendingState(state)) {
            this._pendingState.set(state.msgId!, state);
          }
        } else {
          for (const s of state) {
            this._rememberSentMessage(s);
            if (this._shouldTrackPendingState(s)) {
              this._pendingState.set(s.msgId, s);
            }
          }
        }
      }

      if (this.isReconnecting) {
        this.logWithIndex.debug('Reconnecting :(');
        this._sendLoopHandle = undefined;
        return;
      }

      this._log.debug(`Encrypting ${batch.length} message(s) in ${data.length} bytes for sending`);
      this.logWithIndex.debug('Sending', batch.map((m) => m.request.className));
      const connection = this.getConnection();

      data = await this._state.encryptMessageData(data);

      if (this.isReconnecting) {
        this.logWithIndex.debug('Reconnecting :(');
        this._sendLoopHandle = undefined;
        return;
      }

      if (!connection || connection !== this.getConnection()) {
        this.retryPendingStates();
        continue;
      }

      try {
        await connection.send(data);
        for (const state of batch) {
          if (Array.isArray(state)) {
            state.forEach(this._rememberSentAcknowledgments.bind(this));
          } else {
            this._rememberSentAcknowledgments(state);
          }
        }
      } catch (e: any) {
        this.logWithIndex.debug(`Connection closed while sending data ${e}`);
        this._log.info('Connection closed while sending data');
        // eslint-disable-next-line no-console
        console.error(e);
        this._sendLoopHandle = undefined;
        if (!this.userDisconnected) {
          this.handleConnectionError(e);
        }
        return;
      } finally {
        for (const state of batch) {
          if (!Array.isArray(state)) {
            if (state.request.className === 'HttpWait') {
              state.resolve?.();
            }
          } else {
            for (const s of state) {
              if (s.request.className === 'HttpWait') {
                state.resolve?.();
              }
            }
          }
        }

        this.logWithIndex.debug('Encrypted messages put in a queue to be sent');
        this._log.debug('Encrypted messages put in a queue to be sent');
      }
    }

    this._sendLoopHandle = undefined;
  }

  async _recvLoop() {
    let body;
    let message;

    while (this._userConnected && !this.isReconnecting) {
      this._log.debug('Receiving items from the network...');
      this.logWithIndex.debug('Receiving items from the network...');
      try {
        body = await this.getConnection()!.recv();
      } catch (e: any) {
        // this._log.info('Connection closed while receiving data');
        /** when the server disconnects us we want to reconnect */
        if (!this.userDisconnected) {
          this._log.warn('Connection closed while receiving data');
          // eslint-disable-next-line no-console
          console.error(e);
          this.handleConnectionError(e);
        }
        this._recvLoopHandle = undefined;
        return;
      }

      if (body.length === TRANSPORT_CODE_LENGTH && body.every((byte) => byte === 0)) {
        void this.checkLongPoll();
        continue;
      }

      try {
        // TODO: Handle `DecryptedDataBlock` in calls like a regular `TLMessage` rather than `Uint8Array`
        message = await this.decryptMessageData(body);
      } catch (e: any) {
        this.logWithIndex.debug(`Error while receiving items from the network ${e.toString()}`);
        if (e instanceof TypeNotFoundError) {
          // Received object which we don't know how to deserialize
          this._log.info(`Type ${e.invalidConstructorId} not found, remaining data ${e.remaining.length} bytes`);
          continue;
        } else if (e instanceof SecurityError) {
          // https://core.telegram.org/mtproto/security_guidelines#behavior-in-case-of-mismatch
          this.handleSecurityError();
          this._recvLoopHandle = undefined;
          return;
        } else if (e instanceof InvalidBufferError) {
          // 404 means that the server has "forgotten" our auth key and we need to create a new one.
          if (e.code === 404) {
            this._handleBadAuthKey();
          } else {
            // this happens sometimes when telegram is having some internal issues.
            // reconnecting should be enough usually
            // since the data we sent and received is probably wrong now.
            this._log.warn(`Invalid buffer ${e.code} for dc ${this._dcId}`);
            this.reconnect();
          }
          this._recvLoopHandle = undefined;
          return;
        } else {
          this._log.error('Unhandled error while receiving data');
          // eslint-disable-next-line no-console
          console.error(e);
          this.reconnect();
          this._recvLoopHandle = undefined;
          return;
        }
      }
      try {
        await this._processMessage(message);
      } catch (e: any) {
        // `RPCError` errors except for 'AUTH_KEY_UNREGISTERED' should be handled by the client
        if (e instanceof SecurityError) {
          this.handleSecurityError();
          this._recvLoopHandle = undefined;
          return;
        } else if (e instanceof RPCError) {
          if (e.errorMessage === 'AUTH_KEY_UNREGISTERED'
            || e.errorMessage === 'SESSION_REVOKED'
            || e.errorMessage === 'USER_DEACTIVATED') {
            // 'AUTH_KEY_UNREGISTERED' for the main sender is thrown when unauthorized and should be ignored
            this._handleBadAuthKey(true);
          }
        } else {
          this._log.error('Unhandled error while receiving data');
          // eslint-disable-next-line no-console
          console.error(e);
        }
      }

      void this.checkLongPoll();
    }

    this._recvLoopHandle = undefined;
  }

  checkLongPoll() {
    if (this.isSendingLongPoll || !this._isFallback) return;

    this.isSendingLongPoll = true;
    this.send(new Api.HttpWait({
      maxDelay: LONGPOLL_MAX_DELAY,
      waitAfter: LONGPOLL_WAIT_AFTER,
      maxWait: LONGPOLL_MAX_WAIT,
    }), undefined, true);
  }

  private handleConnectionError(error: unknown) {
    if (!this.shouldResetHttpAuthKey(error)) {
      this.reconnect();
      return;
    }

    if (this.hasHandledHttpAuthKeyError) return;
    this.hasHandledHttpAuthKeyError = true;
    this._handleBadAuthKey();
  }

  private shouldResetHttpAuthKey(error: unknown, hadAuthKey?: boolean) {
    return error instanceof HttpStreamError && error.status === 404
      && (hadAuthKey ?? Boolean(this.authKey.getKey()))
      && (this._isExported ? Boolean(this._onConnectionBreak) : this._isMainSender);
  }

  _handleBadAuthKey(shouldSkipForMain?: boolean) {
    if (shouldSkipForMain && this._isMainSender) {
      return;
    }

    this._log.warn(`Broken authorization key for dc ${this._dcId}, resetting...`);

    if (this._isMainSender && !this._isExported) {
      this._updateCallback?.(new UpdateConnectionState(UpdateConnectionState.broken));
    } else if (this._isExported && this._onConnectionBreak) {
      this._onConnectionBreak(this._dcId);
    }
  }

  // Response Handlers

  /**
   * Adds the given message to the list of messages that must be
   * acknowledged and dispatches control to different ``_handle_*``
   * method based on its type.
   * @param message
   * @returns {Promise<void>}
   * @private
   */
  async _processMessage(message: TLMessage) {
    this.logWithIndex.debug(`Process message ${message.obj.className}`);

    // https://core.telegram.org/mtproto/description#message-sequence-number-msg-seqno
    if (message.isContentRelated) this._pendingAck.add(message.msgId);

    if (this.getConnection()!.shouldLongPoll) {
      this._sendQueue.setReady?.(true);
    }

    if (this._state.consumeMessageReplay(message)) return;

    let handler = this._handlers[message.obj.CONSTRUCTOR_ID];
    if (!handler) {
      handler = this._handleUpdate.bind(this);
    }

    await handler(message);
  }

  /**
   * Pops the states known to match the given ID from pending messages.
   * This method should be used when the response isn't specific.
   * @param msgId
   * @returns {*[]}
   * @private
   */
  _popStates(msgId: bigint) {
    const state = this._pendingState.getAndDelete(msgId);
    const states = state ? [state] : [];

    if (!state) {
      for (const pendingState of this._pendingState.values()) {
        if (pendingState.containerId === msgId) {
          states.push(this._pendingState.getAndDelete(pendingState.msgId!)!);
        }
      }
    }

    for (const ack of this._lastAcks) {
      if ((ack.msgId === msgId || ack.containerId === msgId) && !states.includes(ack)) {
        states.push(ack);
      }
    }

    return states;
  }

  private _hasRecentSentMessage(msgId: bigint, seqNo?: number) {
    const sentMessage = this._findSentMessage(msgId);
    return Boolean(sentMessage
      && (seqNo === undefined || this._getSentMessageSeqNo(sentMessage) === seqNo));
  }

  private _shouldTrackPendingState(state: RequestState) {
    return (state.request.classType === 'request' && state.request.className !== 'HttpWait')
      || state.request instanceof Api.MsgsStateReq;
  }

  private _rememberSentAcknowledgments(state: RequestState) {
    let msgIds: bigint[] | undefined;
    if (state.request instanceof Api.MsgsAck) {
      msgIds = state.request.msgIds;
    } else if (state.request instanceof Api.MsgsStateInfo) {
      msgIds = [state.request.reqMsgId];
      if (state.acknowledgedMsgIds) msgIds.push(...state.acknowledgedMsgIds);
    }
    if (!msgIds) return;

    for (const msgId of msgIds) this._acknowledgedMsgIds.add(msgId);
    while (this._acknowledgedMsgIds.size > MAX_RECENT_ACKNOWLEDGED_MESSAGES) {
      this._acknowledgedMsgIds.delete(this._acknowledgedMsgIds.values().next().value!);
    }
  }

  private _rememberSentMessage(state: RequestState) {
    this._forgetSentState(state);
    const message: SentMessage = {
      msgId: state.msgId!,
      seqNo: state.seqNo!,
      sentAt: Date.now(),
      state,
      containerId: state.containerId,
      containerSeqNo: state.containerSeqNo,
    };
    this._recentSentMessages.set(message.msgId, message);
    this._sentMessageIdsByState.set(state, message.msgId);
    if (message.containerId !== undefined) {
      let containerMessageIds = this._sentMessageIdsByContainer.get(message.containerId);
      if (!containerMessageIds) {
        containerMessageIds = new Set();
        this._sentMessageIdsByContainer.set(message.containerId, containerMessageIds);
      }
      containerMessageIds.add(message.msgId);
    }

    if (this._recentSentMessages.size > MAX_RECENT_SENT_MESSAGES) {
      const oldestMessage = this._recentSentMessages.values().next().value!;
      if (oldestMessage.containerId !== undefined) {
        this._forgetSentMessage(oldestMessage.containerId, true);
      } else {
        this._deleteSentMessage(oldestMessage.msgId);
      }
    }
  }

  private _findSentMessage(msgId: bigint): SentMessageReference | undefined {
    this._pruneRecentSentMessages();
    const message = this._recentSentMessages.get(msgId);
    if (message) return { message, isContainer: false };

    const sentMessageId = this._sentMessageIdsByContainer.get(msgId)?.values().next().value;
    const containerMessage = sentMessageId !== undefined
      ? this._recentSentMessages.get(sentMessageId)
      : undefined;
    if (!containerMessage) return undefined;

    return { message: containerMessage, isContainer: true };
  }

  private _pruneRecentSentMessages() {
    const expiredBefore = Date.now() - RECENT_SENT_MESSAGE_TTL;
    for (const [msgId, { sentAt }] of this._recentSentMessages) {
      if (sentAt < expiredBefore) this._deleteSentMessage(msgId);
    }
  }

  private _forgetSentMessage(msgId: bigint, isContainer: boolean) {
    if (!isContainer) {
      this._deleteSentMessage(msgId);
      return;
    }

    const sentMessageIds = this._sentMessageIdsByContainer.get(msgId);
    if (!sentMessageIds) return;

    for (const sentMsgId of sentMessageIds) {
      this._deleteSentMessage(sentMsgId);
    }
  }

  private _forgetSentState(state: RequestState) {
    const msgId = this._sentMessageIdsByState.get(state);
    if (msgId !== undefined) this._deleteSentMessage(msgId);
  }

  private _deleteSentMessage(msgId: bigint) {
    const sentMessage = this._recentSentMessages.get(msgId);
    if (!sentMessage) return;

    this._recentSentMessages.delete(msgId);
    if (this._sentMessageIdsByState.get(sentMessage.state) === msgId) {
      this._sentMessageIdsByState.delete(sentMessage.state);
    }

    const { containerId } = sentMessage;
    if (containerId === undefined) return;

    const sentMessageIds = this._sentMessageIdsByContainer.get(containerId);
    sentMessageIds?.delete(msgId);
    if (!sentMessageIds?.size) this._sentMessageIdsByContainer.delete(containerId);
  }

  /**
   * Handles the result for Remote Procedure Calls:
   * rpc_result#f35c6d01 req_msg_id:long result:bytes = RpcResult;
   * This is where the future results for sent requests are set.
   * @param message
   * @returns {Promise<void>}
   * @private
   */
  _handleRPCResult(message: TLMessage) {
    const result = message.obj;
    const state = this._pendingState.getAndDelete(result.reqMsgId);
    this._log.debug(`Handling RPC result for message ${result.reqMsgId}`);

    if (!state) {
      // TODO We should not get responses to things we never sent
      // However receiving a File() with empty bytes is "common".
      // See #658, #759 and #958. They seem to happen in a container
      // which contain the real response right after.
      try {
        const reader = new BinaryReader(result.body);
        if (!(reader.tgReadObject() instanceof Api.upload.File)) {
          throw new TypeNotFoundError(0, new Uint8Array(0));
        }
      } catch (e) {
        if (e instanceof TypeNotFoundError) {
          this._log.info(`Received response without parent request: ${result.body}`);
          return;
        } else if (this._isFallback) {
          // If we're using HTTP transport, there might be a chance that the response comes through
          // multiple times if didn't send acknowledgment in time, so we should just ignore it
          return;
        }

        throw e;
      }
      return;
    }

    this._forgetSentMessage(result.reqMsgId, false);

    if (result.error) {
      const error = RPCMessageToError(result.error, state.request);
      state.reject?.(error);
      throw error;
    } else {
      try {
        const reader = new BinaryReader(result.body);
        const read = state.request.readResult(reader);
        this.logWithIndex.debug('Handling RPC result', read);
        state.resolve?.(read);
      } catch (err: any) {
        state.reject?.(err);
        throw err;
      }
    }
  }

  /**
   * Processes the inner messages of a container with many of them:
   * msg_container#73f1f8dc messages:vector<%Message> = MessageContainer;
   * @param message
   * @returns {Promise<void>}
   * @private
   */
  async _handleContainer(message: TLMessage) {
    this._log.debug('Handling container');
    for (const innerMessage of message.obj.messages) {
      await this._processMessage(innerMessage);
    }
  }

  /**
   * Unpacks the data from a gzipped object and processes it:
   * gzip_packed#3072cfa1 packed_data:bytes = Object;
   * @param message
   * @returns {Promise<void>}
   * @private
   */
  async _handleGzipPacked(message: TLMessage) {
    this._log.debug('Handling gzipped data');
    const { data } = message.obj;
    const reader = new BinaryReader(data);
    const obj = reader.tgReadObject();
    if (obj instanceof MessageContainer || reader.tellPosition() !== data.length) {
      throw new SecurityError();
    }
    message.obj = obj;
    await this._processMessage(message);
  }

  _handleUpdate(message: TLMessage) {
    if (message.obj.SUBCLASS_OF_ID !== 0x8af52aac) {
      // crc32(b'Updates')
      this._log.warn(`Note: ${message.obj.className} is not an update, not dispatching it`);
      return;
    }
    this._log.debug(`Handling update ${message.obj.className}`);
    if (!this._isExported) {
      this._updateCallback?.(message.obj);
    }
  }

  /**
   * Handles pong results, which don't come inside a ``RPCResult``
   * but are still sent through a request:
   * pong#347773c5 msg_id:long ping_id:long = Pong;
   * @param message
   * @returns {Promise<void>}
   * @private
   */
  _handlePong(message: TLMessage) {
    const pong = message.obj;
    const state = this._pendingState.get(pong.msgId);
    const isPing = state?.request instanceof Api.Ping
      || state?.request instanceof Api.PingDelayDisconnect;

    // https://core.telegram.org/mtproto/service_messages#ping-messages-ping-pong
    if (!state || !isPing || state.request.pingId !== pong.pingId) return;

    this._pendingState.delete(pong.msgId);
    this._deleteSentMessage(pong.msgId);

    this._log.debug(`Handling pong for message ${pong.msgId}`);
    state.resolve?.(pong);
  }

  /**
   * Corrects the currently used server salt to use the right value
   * before enqueuing the rejected message to be re-sent:
   * bad_server_salt#edab447b bad_msg_id:long bad_msg_seqno:int
   * error_code:int new_server_salt:long = BadMsgNotification;
   * @param message
   * @returns {Promise<void>}
   * @private
   */
  _handleBadServerSalt(message: TLMessage) {
    const badSalt = message.obj;
    const sentMessage = this._findSentMessage(badSalt.badMsgId);
    if (badSalt.errorCode !== BAD_SERVER_SALT_ERROR_CODE
      || !sentMessage
      || this._getSentMessageSeqNo(sentMessage) !== badSalt.badMsgSeqno) return;

    // https://core.telegram.org/mtproto/service_messages_about_messages#notice-of-ignored-error-message
    this._forgetSentMessage(badSalt.badMsgId, sentMessage.isContainer);
    this._log.debug(`Handling bad salt for message ${badSalt.badMsgId}`);
    const states = this._popStates(badSalt.badMsgId);
    this._state.setServerSalt(badSalt.newServerSalt, true);
    this._sendQueue.extend(states);
    this.futureServerSaltRequest = undefined;
    this.requestFutureServerSalts();
    this._log.debug(`${states.length} message(s) will be resent`);
  }

  /**
   * Adjusts the current state to be correct based on the
   * received bad message notification whenever possible:
   * bad_msg_notification#a7eff811 bad_msg_id:long bad_msg_seqno:int
   * error_code:int = BadMsgNotification;
   * @param message
   * @returns {Promise<void>}
   * @private
   */
  _handleBadNotification(message: TLMessage) {
    const badMsg = message.obj;
    const sentMessage = this._findSentMessage(badMsg.badMsgId);
    if (!sentMessage
      || !this._isBadNotificationApplicable(badMsg, message.msgId, sentMessage)) return;

    this._forgetSentMessage(badMsg.badMsgId, sentMessage.isContainer);
    const states = this._popStates(badMsg.badMsgId);
    this._log.debug(`Handling bad msg ${jsonStringifyWithBigInt(badMsg)}`);
    if (INVALID_TIME_ERROR_CODES.has(badMsg.errorCode)) {
      // Sent msg_id too low or too high (respectively).
      // Use the current msg_id to determine the right time offset.
      const { timeOffset: newTimeOffset, isSessionReset } = this._state.updateTimeOffset(message.msgId);
      const shouldResetSession = badMsg.errorCode === MESSAGE_ID_TOO_HIGH_ERROR_CODE;
      if (shouldResetSession && !isSessionReset) this._state.reset();
      if (shouldResetSession || isSessionReset) {
        this._resetSessionTracking();

        if (this._isFallback) {
          this.getConnection()?.disconnect();
          this.reconnect();
        }
      }

      if (!this._isExported) {
        this._updateCallback?.(new UpdateServerTimeOffset(newTimeOffset));
      }

      this._log.info(`System clock is wrong, set time offset to ${newTimeOffset}s`);
    } else if (badMsg.errorCode === 32) {
      // msg_seqno too low, so just pump it up by some "large" amount
      // TODO A better fix would be to start with a new fresh session ID
      this._state._sequence += 64;
    } else if (badMsg.errorCode === 33) {
      // msg_seqno too high never seems to happen but just in case
      this._state._sequence -= 16;
    } else {
      for (const state of states) {
        state.reject?.(new BadMessageError(state.request, badMsg.errorCode));
      }

      return;
    }
    // Messages are to be re-sent once we've corrected the issue
    this._sendQueue.extend(states);
    this._log.debug(`${states.length} messages will be resent due to bad msg`);
  }

  private _isBadNotificationApplicable(
    badMsg: Api.BadMsgNotification,
    notificationMsgId: bigint,
    sentMessage: SentMessageReference,
  ) {
    const { errorCode, badMsgId, badMsgSeqno } = badMsg;
    const sentSeqNo = this._getSentMessageSeqNo(sentMessage);
    if (!BAD_MESSAGE_ERROR_CODES.has(errorCode) || sentSeqNo !== badMsgSeqno) return false;
    if (errorCode === 16) return badMsgId < notificationMsgId; // Message ID is too low
    if (errorCode === MESSAGE_ID_TOO_HIGH_ERROR_CODE) return badMsgId > notificationMsgId;
    if (errorCode === 18) return (badMsgId & 3n) !== 0n; // Message ID has invalid low bits
    if (errorCode === 19 || errorCode === 64) return sentMessage.isContainer; // Duplicate ID or invalid container
    if (errorCode === 34) return (sentSeqNo & 1) === 1; // Even sequence number expected
    if (errorCode === 35) return (sentSeqNo & 1) === 0; // Odd sequence number expected

    return true;
  }

  private _getSentMessageSeqNo({ message, isContainer }: SentMessageReference) {
    return isContainer ? message.containerSeqNo! : message.seqNo;
  }

  /**
   * Updates the current status with the received detailed information:
   * msg_detailed_info#276d3ec6 msg_id:long answer_msg_id:long
   * bytes:int status:int = MsgDetailedInfo;
   * @param message
   * @returns {Promise<void>}
   * @private
   */
  _handleDetailedInfo(message: TLMessage) {
    const { answerMsgId } = message.obj;
    this._pendingAck.add(answerMsgId);
    this._log.debug(`Handling detailed info for message ${answerMsgId}`);
  }

  /**
   * Updates the current status with the received detailed information:
   * msg_new_detailed_info#809db6df answer_msg_id:long
   * bytes:int status:int = MsgDetailedInfo;
   * @param message
   * @returns {Promise<void>}
   * @private
   */
  _handleNewDetailedInfo(message: TLMessage) {
    const { answerMsgId } = message.obj;
    this._pendingAck.add(answerMsgId);
    this._log.debug(`Handling new detailed info for message ${answerMsgId}`);
  }

  /**
   * Updates the current status with the received session information:
   * new_session_created#9ec20908 first_msg_id:long unique_id:long
   * server_salt:long = NewSession;
   * @param message
   * @returns {Promise<void>}
   * @private
   */
  _handleNewSessionCreated(message: TLMessage) {
    const { firstMsgId, uniqueId, serverSalt } = message.obj;
    this._log.debug('Handling new session created');
    this._state.setServerSalt(serverSalt);

    if (firstMsgId === this._lastSessionFirstMsgId && uniqueId === this._lastSessionUniqueId) return;
    this._lastSessionFirstMsgId = firstMsgId;
    this._lastSessionUniqueId = uniqueId;

    // https://core.telegram.org/mtproto/service_messages#new-session-creation-notification
    if (!this._isExported) this._updateCallback?.(new UpdateSessionGap(firstMsgId, uniqueId));
  }

  /**
   * Handles a server acknowledge about our messages. Normally these can be ignored
  */
  _handleAck() { }

  /**
   * Handles future salt results, which don't come inside a
   * ``rpc_result`` but are still sent through a request:
   *     future_salts#ae500895 req_msg_id:long now:int
   *     salts:vector<future_salt> = FutureSalts;
   * @param message
   * @returns {Promise<void>}
   * @private
   */
  _handleFutureSalts(message: TLMessage) {
    const futureSalts = message.obj;
    const state = this._pendingState.get(futureSalts.reqMsgId);

    // https://core.telegram.org/mtproto/service_messages#request-for-several-future-salts
    if (!(state?.request instanceof Api.GetFutureSalts)
      || state.request.num < 1
      || state.request.num > MAX_FUTURE_SERVER_SALTS
      || futureSalts.salts.length > state.request.num) return;

    if (state.promise !== this.futureServerSaltRequest) {
      this._pendingState.delete(futureSalts.reqMsgId);
      this._forgetSentMessage(futureSalts.reqMsgId, false);
      state.resolve?.();
      return;
    }

    if (!this._state.setFutureSalts(futureSalts.salts)) return;

    this._pendingState.delete(futureSalts.reqMsgId);
    this._forgetSentMessage(futureSalts.reqMsgId, false);
    this._log.debug(`Handling future salts for message ${futureSalts.reqMsgId.toString()}`);
    state.resolve?.(futureSalts);
  }

  _handleStateReq(message: TLMessage) {
    this._sendStateInfo(message.msgId, message.obj.msgIds);
  }

  _handleResendReq(message: TLMessage) {
    const states: RequestState[] = [];
    const knownStates = new Set<RequestState>();
    let hasUnknownMessages = false;

    for (const msgId of message.obj.msgIds) {
      if (!this._collectResendStates(msgId, states, knownStates)) {
        hasUnknownMessages = true;
      }
    }

    if (hasUnknownMessages) this._sendStateInfo(message.msgId, message.obj.msgIds);

    // https://core.telegram.org/mtproto/service_messages_about_messages#explicit-request-to-re-send-messages
    this._resendStates(states);
  }

  _handleStateInfo(message: TLMessage) {
    const stateInfo: Api.MsgsStateInfo = message.obj;
    const state = this._pendingState.get(stateInfo.reqMsgId);
    const statusCodes = stateInfo.info;
    if (!(state?.request instanceof Api.MsgsStateReq)
      || statusCodes.length !== state.request.msgIds.length
      || statusCodes.some((statusCode) => {
        const baseStatus = statusCode & 7;
        return baseStatus < 1 || baseStatus > 4;
      })) return;

    this._pendingState.delete(stateInfo.reqMsgId);
    this._forgetSentMessage(stateInfo.reqMsgId, false);

    const states: RequestState[] = [];
    const knownStates = new Set<RequestState>();
    statusCodes.forEach((statusCode, index) => {
      const baseStatus = statusCode & 7;
      if (baseStatus !== MESSAGE_STATE_RECEIVED
        && !(statusCode & MESSAGE_STATE_RECEIVED_ELSEWHERE)) {
        this._collectResendStates(state.request.msgIds[index], states, knownStates);
      }
    });
    // https://core.telegram.org/mtproto/service_messages_about_messages#informational-message-regarding-status-of-messages
    this._resendStates(states);
    state.resolve?.();
  }

  private _sendStateInfo(reqMsgId: bigint, msgIds: bigint[]) {
    const acknowledgedMsgIds: bigint[] = [];
    const info = Uint8Array.from(msgIds, (msgId) => {
      const status = this._state.getIncomingMessageState(
        msgId, this._acknowledgedMsgIds.has(msgId),
      );
      if ((status & 7) === MESSAGE_STATE_RECEIVED && !(status & MESSAGE_STATE_NO_ACK_REQUIRED)) {
        acknowledgedMsgIds.push(msgId);
      }
      return status;
    });
    const state = new RequestState(new Api.MsgsStateInfo({ reqMsgId, info }));
    state.acknowledgedMsgIds = acknowledgedMsgIds;
    this._sendQueue.append(state);
  }

  private _collectResendStates(
    msgId: bigint, states: RequestState[], knownStates: Set<RequestState>,
  ) {
    const sentMessage = (msgId & 3n) === 0n ? this._findSentMessage(msgId) : undefined;
    if (!sentMessage) return false;

    const messages = sentMessage.isContainer
      ? Array.from(this._sentMessageIdsByContainer.get(msgId) ?? [], (sentMsgId) => (
        this._recentSentMessages.get(sentMsgId)!
      ))
      : [sentMessage.message];
    for (const { state } of messages) {
      if (knownStates.has(state)) continue;
      knownStates.add(state);
      states.push(state);
    }
    return true;
  }

  private _resendStates(states: RequestState[]) {
    for (const state of states) {
      this._pendingState.delete(state.msgId!);
      this._forgetSentState(state);
    }
    this._sendQueue.extend(states);
  }

  /**
   * Handles :tl:`MsgsAllInfo` by doing nothing (yet).
   * used as part of the telegram protocol https://core.telegram.org/mtproto/service_messages_about_messages
   * This message does not require an acknowledgment.
   * @param message
   * @returns {Promise<void>}
   * @private
   */

  _handleMsgAll(message: TLMessage) {
  }

  private handleSecurityError() {
    this._log.warn('Invalid encrypted packet');
    if (!this._isFallback && this._shouldAllowHttpTransport) {
      this._shouldUseFallbackOnReconnect = true;
    }
    this.reconnect();
  }

  reconnect() {
    if (this._userConnected && !this.isReconnecting) {
      this.isReconnecting = true;
      // TODO Should we set this?
      // this._user_connected = false
      // we want to wait a second between each reconnect try to not flood the server with reconnects
      // in case of internal server issues.
      sleep(1000)
        .then(() => {
          this.logWithIndex.log('Reconnecting...');
          this._log.info('Started reconnecting');
          this._reconnect();
        });
    }
  }

  async _reconnect() {
    if (this.userDisconnected) {
      this.isReconnecting = false;
      this._shouldUseFallbackOnReconnect = false;
      return;
    }

    const shouldUseFallback = this._shouldUseFallbackOnReconnect;
    this._shouldUseFallbackOnReconnect = false;
    const currentConnection = this._connection!;
    const currentFallbackConnection = this._fallbackConnection;
    this._log.debug('Closing current connection...');
    try {
      this.logWithIndex.warn('[Reconnect] Closing current connection...');
      if (currentConnection) this._disconnect(currentConnection);
      if (currentFallbackConnection) this._disconnect(currentFallbackConnection);
    } catch (err: any) {
      this._log.warn(err);
    }

    this._sendQueue.append(undefined);
    this._state.reset();
    this._pendingAck.clear();
    this._acknowledgedMsgIds.clear();
    this._recentSentMessages.clear();
    this._sentMessageIdsByState.clear();
    this._sentMessageIdsByContainer.clear();
    this._lastAcks.length = 0;
    this._lastSessionFirstMsgId = undefined;
    this._lastSessionUniqueId = undefined;

    // For some reason reusing existing connection caused stuck requests
    // @ts-expect-error -- Hacky way to create new class instance
    const newConnection = new currentConnection.constructor({
      ip: currentConnection._ip,
      port: currentConnection._port,
      dcId: currentConnection._dcId,
      loggers: currentConnection._log,
      isTestServer: currentConnection._isTestServer,
      isPremium: currentConnection._isPremium,
    });
    // @ts-expect-error -- Hacky way to create new class instance
    const newFallbackConnection = new this._fallbackConnection.constructor({
      ip: currentConnection._ip,
      port: currentConnection._port,
      dcId: currentConnection._dcId,
      loggers: currentConnection._log,
      isTestServer: currentConnection._isTestServer,
      isPremium: currentConnection._isPremium,
    });
    try {
      await this.connect(newConnection, true, newFallbackConnection, shouldUseFallback);
    } catch {
      return;
    } finally {
      this.isReconnecting = false;
    }

    if (this._autoReconnectCallback) {
      await this._autoReconnectCallback();
    }
  }

  private retryPendingStates() {
    const pendingStates = this._pendingState.values();
    if (!pendingStates.length) return;

    this._sendQueue.prepend(pendingStates);
    this._pendingState.clear();
  }

  private _resetSessionTracking() {
    this.retryPendingStates();
    this._pendingAck.clear();
    this._acknowledgedMsgIds.clear();
    this._recentSentMessages.clear();
    this._sentMessageIdsByState.clear();
    this._sentMessageIdsByContainer.clear();
    this._lastAcks.length = 0;
    this._lastSessionFirstMsgId = undefined;
    this._lastSessionUniqueId = undefined;
  }
}

constructor(authKey: AuthKey, opts: DefaultOptions) {
    const args = { ...MTProtoSender.DEFAULT_OPTIONS, ...opts };
    this._connection = undefined;
    this._fallbackConnection = undefined;
    this._shouldForceHttpTransport = args.shouldForceHttpTransport;
    this._shouldAllowHttpTransport = args.shouldAllowHttpTransport;
    this._log = args.logger;
    this._dcId = args.dcId;
    this._senderIndex = args.senderIndex || 0;
    this._retries = args.retries;
    this._retriesToFallback = args.retriesToFallback;
    this._delay = args.delay;
    this._retryMainConnectionDelay = args.retryMainConnectionDelay;
    this._authKeyCallback = args.authKeyCallback;
    this._updateCallback = args.updateCallback;
    this._autoReconnectCallback = args.autoReconnectCallback;
    this._isMainSender = Boolean(args.isMainSender);
    this._isExported = Boolean(args.isExported);
    this._onConnectionBreak = args.onConnectionBreak;
    this._isFallback = false;
    this._shouldUseFallbackOnReconnect = false;
    this._getShouldDebugExportedSenders = args.getShouldDebugExportedSenders;

    /**
     * whether we disconnected ourself or telegram did it.
     */
    this.userDisconnected = false;

    /**
     * Whether the user has explicitly connected or disconnected.
     *
     * If a disconnection happens for any other reason and it
     * was *not* user action then the pending messages won't
     * be cleared but on explicit user disconnection all the
     * pending futures should be cancelled.
     */
    this._userConnected = false;
    this.isReconnecting = false;
    this._disconnected = true;

    /**
     * We need to join the loops upon disconnection
     */
    this._sendLoopHandle = undefined;
    this._longPollLoopHandle = undefined;
    this._recvLoopHandle = undefined;

    /**
     * Preserving the references of the AuthKey and state is important
     */
    this.authKey = authKey || new AuthKey();
    this._state = new MTProtoState(this.authKey, this._log);
    this._state.timeOffset = args.timeOffset ?? 0;

    /**
     * Outgoing messages are put in a queue and sent in a batch.
     * Note that here we're also storing their ``_RequestState``.
     */
    this._sendQueue = new MessagePacker(this._state, this._log);
    this._sendQueueLongPoll = new MessagePacker(this._state, this._log);

    /**
     * Sent states are remembered until a response is received.
     */
    this._pendingState = new PendingState();

    /**
     * Responses must be acknowledged, and we can also batch these.
     */
    this._pendingAck = new Set();

    /**
     * Similar to pending_messages but only for the last acknowledges.
     * These can't go in pending_messages because no acknowledge for them
     * is received, but we may still need to resend their state on bad salts.
     */
    this._lastAcks = [];
    this._acknowledgedMsgIds = new Set();
    this._recentSentMessages = new Map();
    this._sentMessageIdsByState = new Map();
    this._sentMessageIdsByContainer = new Map();

    /**
     * Jump table from response ID to method that handles it
     */

    this._handlers = {
      [RPCResult.CONSTRUCTOR_ID]: this._handleRPCResult.bind(this),
      [MessageContainer.CONSTRUCTOR_ID]: this._handleContainer.bind(this),
      [GZIPPacked.CONSTRUCTOR_ID]: this._handleGzipPacked.bind(this),
      [Api.Pong.CONSTRUCTOR_ID]: this._handlePong.bind(this),
      [Api.BadServerSalt.CONSTRUCTOR_ID]: this._handleBadServerSalt.bind(this),
      [Api.BadMsgNotification.CONSTRUCTOR_ID]: this._handleBadNotification.bind(this),
      [Api.MsgDetailedInfo.CONSTRUCTOR_ID]: this._handleDetailedInfo.bind(this),
      [Api.MsgNewDetailedInfo.CONSTRUCTOR_ID]: this._handleNewDetailedInfo.bind(this),
      [Api.NewSessionCreated.CONSTRUCTOR_ID]: this._handleNewSessionCreated.bind(this),
      [Api.MsgsAck.CONSTRUCTOR_ID]: this._handleAck.bind(this),
      [Api.FutureSalts.CONSTRUCTOR_ID]: this._handleFutureSalts.bind(this),
      [Api.MsgsStateReq.CONSTRUCTOR_ID]: this._handleStateReq.bind(this),
      [Api.MsgResendReq.CONSTRUCTOR_ID]: this._handleResendReq.bind(this),
      [Api.MsgsStateInfo.CONSTRUCTOR_ID]: this._handleStateInfo.bind(this),
      [Api.MsgsAllInfo.CONSTRUCTOR_ID]: this._handleMsgAll.bind(this),
    };
  }

logWithIndexCallback(level: 'debug' | 'log' | 'warn' | 'error') {
    return (...args: unknown[]) => {
      if (!this._getShouldDebugExportedSenders
        || !this._getShouldDebugExportedSenders()) return;
      // eslint-disable-next-line no-console
      console[level](`[${this._isExported ? `idx=${this._senderIndex} ` : 'M '}dcId=${this._dcId}]`, ...args);
    };
  }

getConnection(): Connection | undefined {
    return this._isFallback ? this._fallbackConnection : this._connection;
  }

async connect(
    connection: Connection,
    force: boolean,
    fallbackConnection?: Connection,
    shouldUseFallback?: boolean,
  ) {
    this.userDisconnected = false;

    if (this._userConnected && !force) {
      this._log.info('User is already connected!');
      return false;
    }
    this.isConnecting = true;
    this._isFallback = Boolean((this._shouldForceHttpTransport || shouldUseFallback)
      && this._shouldAllowHttpTransport);
    this._connection = connection;
    this._fallbackConnection = fallbackConnection;
    let hasConnected = false;
    let connectionError: unknown;

    for (let attempt = 0; attempt < this._retries + this._retriesToFallback; attempt++) {
      const hasAuthKey = Boolean(this.authKey.getKey());
      try {
        if (attempt >= this._retriesToFallback && this._shouldAllowHttpTransport) {
          this._isFallback = true;
          this.logWithIndex.warn('Using fallback connection');
          this._log.warn('Using fallback connection');
        }
        this.logWithIndex.warn('Connecting...');
        await this._connect(this.getConnection()!);
        this.logWithIndex.warn('Connected!');
        if (!this._isExported) {
          this._updateCallback?.(new UpdateConnectionState(UpdateConnectionState.connected));
        }
        hasConnected = true;
        break;
      } catch (err) {
        connectionError = err;
        if (this.shouldResetHttpAuthKey(err, hasAuthKey)) {
          if (!this._isExported) this._handleBadAuthKey();
          break;
        }
        if (!this._isExported && attempt === 0) {
          this._updateCallback?.(new UpdateConnectionState(UpdateConnectionState.disconnected));
        }
        this._log.error(`${this._isFallback ? 'HTTP' : 'WebSocket'} connection failed attempt: ${attempt + 1}`);
        // eslint-disable-next-line no-console
        console.error(err);
        await sleep(this._delay);
      }
    }
    this.isConnecting = false;
    if (!hasConnected) {
      throw connectionError instanceof Error ? connectionError : new Error('Connection failed');
    }

    if (this._isFallback && !this._shouldForceHttpTransport) {
      void this.tryReconnectToMain();
    }

    return true;
  }

async tryReconnectToMain() {
    if (this._isReconnectingToMain || !this.canRetryMainConnection()) return;

    this._isReconnectingToMain = true;
    let attempt = 0;

    try {
      while (this.canRetryMainConnection()) {
        const delayMultiplier = MAIN_CONNECTION_RETRY_DELAY_MULTIPLIERS[
          Math.min(attempt, MAIN_CONNECTION_RETRY_DELAY_MULTIPLIERS.length - 1)
        ];
        const retryDelay = Math.min(
          this._retryMainConnectionDelay * delayMultiplier,
          MAX_MAIN_CONNECTION_RETRY_DELAY,
        );
        this._log.debug(`Trying to reconnect to main connection in ${retryDelay}ms`);
        await sleep(retryDelay);

        if (!this.canRetryMainConnection()) return;

        try {
          await this._connection!.connect();
          this.isReconnecting = true;
          if (this._fallbackConnection) this._disconnect(this._fallbackConnection);
          await this.connect(this._connection!, true, this._fallbackConnection);
          this.isReconnecting = false;

          if (this._isFallback) {
            this._log.error('Failed to reconnect to main connection');
            attempt++;
            continue;
          }

          this._log.info('Reconnected to main connection');
          this.logWithIndex.warn('Reconnected to main connection');
          return;
        } catch {
          this.isReconnecting = false;
          this._isFallback = true;
          this._log.error('Failed to reconnect to main connection');
          attempt++;
        }
      }
    } finally {
      this._isReconnectingToMain = false;
    }
  }

private canRetryMainConnection() {
    return !this.userDisconnected && !this.isConnecting && this._isFallback && !this.isReconnecting
      && !this._shouldForceHttpTransport && !this._isExported;
  }

isConnected() {
    return this._userConnected;
  }

disconnect() {
    this.userDisconnected = true;
    this.logWithIndex.warn('Disconnecting...');
    const connection = this.getConnection();
    if (!connection) return;
    this._disconnect(connection);
  }

destroy() {
    this._sendQueue.clear();
  }

send<T extends CallableRequest>(request: T, abortSignal?: AbortSignal, isLongPoll = false) {
    const states = this._splitMessageIdRequest(request)
      .map((splitRequest) => new RequestState(splitRequest, abortSignal));
    for (let index = 1; index < states.length; index++) {
      void states[index].promise!.catch(() => undefined);
    }
    if (!isLongPoll) {
      this.logWithIndex.debug(`Send ${request.className}`);
      this._sendQueue.extend(states);
    } else {
      this._sendQueueLongPoll.extend(states);
    }
    return states[0].promise as RequestState<T>['promise'];
  }

private _splitMessageIdRequest(request: CallableRequest) {
    if (!(request instanceof Api.MsgsAck
      || request instanceof Api.MsgsStateReq
      || request instanceof Api.MsgResendReq)
    || request.msgIds.length <= MAX_MESSAGE_IDS) return [request];

    const requests: CallableRequest[] = [];
    for (let index = 0; index < request.msgIds.length; index += MAX_MESSAGE_IDS) {
      const msgIds = request.msgIds.slice(index, index + MAX_MESSAGE_IDS);
      if (request instanceof Api.MsgsAck) {
        requests.push(new Api.MsgsAck({ msgIds }));
      } else if (request instanceof Api.MsgsStateReq) {
        requests.push(new Api.MsgsStateReq({ msgIds }));
      } else {
        requests.push(new Api.MsgResendReq({ msgIds }));
      }
    }

    return requests;
  }

addStateToQueue(state: RequestState) {
    this._sendQueue.append(state);
  }

async sendBeacon(request: CallableRequest) {
    if (!this._userConnected || !(this._fallbackConnection instanceof HttpConnection)) {
      throw new Error('Cannot send requests while disconnected');
    }
    const state = new RequestState(request, undefined);
    const data = this._sendQueue.getBeacon(state);
    if (!data) return;
    const encryptedData = await this._state.encryptMessageData(data);

    postMessage({
      payloads: [{
        type: 'sendBeacon',
        data: encryptedData,
        url: this._fallbackConnection.href,
      }],
    });
  }

async _connect(connection: Connection) {
    const wasReconnecting = this.isReconnecting;
    const shouldCheckHttpConnection = connection instanceof HttpConnection && Boolean(this.authKey.getKey());

    if (!connection.isConnected()) {
      this._log.info('Connecting to {0}...'.replace('{0}', connection._ip));
      await connection.connect();
      this._log.debug('Connection success!');
    }

    if (!this.authKey.getKey()) {
      const plain = new MtProtoPlainSender(connection, this._log);
      this._log.debug('New auth_key attempt ...');
      const res = await doAuthentication(plain, this._log, connection._dcId, connection._isTestServer);
      this._log.debug('Generated new auth_key successfully');
      await this.authKey.setKey(res.authKey);

      this._state.resetForNewAuthKey();
      this._state.timeOffset = res.timeOffset;
      this._state.setServerSalt(res.serverSalt);

      if (!this._isExported) {
        this._updateCallback?.(new UpdateServerTimeOffset(this._state.timeOffset));
      }

      /**
       * This is *EXTREMELY* important since we don't control
       * external references to the authorization key, we must
       * notify whenever we change it. This is crucial when we
       * switch to different data centers.
       */
      if (this._authKeyCallback) {
        await this._authKeyCallback(this.authKey, this._dcId);
      }
    } else {
      this._authenticated = true;
      this._log.debug('Already have an auth key ...');
    }

    if (shouldCheckHttpConnection) {
      const httpConnectionCheck = new RequestState(new Api.Ping({ pingId: generateRandomLong() }));
      const resolveHttpConnectionCheck = httpConnectionCheck.resolve!;
      let hasReceivedPong = false;
      httpConnectionCheck.resolve = (pong) => {
        hasReceivedPong = true;
        resolveHttpConnectionCheck(pong);
      };
      const pingData = this._sendQueue.getBeacon(httpConnectionCheck)!;
      this._rememberSentMessage(httpConnectionCheck);

      try {
        await connection.send(await this._state.encryptMessageData(pingData));
        const response = await connection.recv();
        const message = await this.decryptMessageData(response);
        this._pendingState.set(httpConnectionCheck.msgId!, httpConnectionCheck);
        await this._processMessage(message);
        if (message.obj instanceof Api.Pong && !hasReceivedPong) {
          throw new Error('HTTP connection check did not receive a matching pong');
        }
      } catch (err) {
        this._pendingState.delete(httpConnectionCheck.msgId!);
        this._deleteSentMessage(httpConnectionCheck.msgId!);
        connection.disconnect();
        throw err;
      }
    }

    this._userConnected = true;
    this.isReconnecting = false;

    if (!this._sendLoopHandle) {
      this._log.debug('Starting send loop');
      this._sendLoopHandle = this._sendLoop();
    } else if (wasReconnecting) {
      this.retryPendingStates();
    }

    if (!this._recvLoopHandle) {
      this._log.debug('Starting receive loop');
      this._recvLoopHandle = this._recvLoop();
    }

    if (!this._longPollLoopHandle && connection.shouldLongPoll) {
      this._log.debug('Starting long-poll loop');
      this._longPollLoopHandle = this._longPollLoop();
    }

    this.scheduleFutureServerSaltRefresh(SERVER_SALT_REQUEST_RETRY_DELAY);

    // _disconnected only completes after manual disconnection
    // or errors after which the sender cannot continue such
    // as failing to reconnect or any unexpected error.

    this._log.info('Connection to %s complete!'.replace('%s', connection.toString()));
  }

private async decryptMessageData(body: Uint8Array) {
    const previousTimeOffset = this._state.timeOffset;
    const message = await this._state.decryptMessageData(
      body, this._hasRecentSentMessage.bind(this),
    ) as TLMessage;

    if (!this._isExported && this._state.timeOffset !== previousTimeOffset) {
      this._updateCallback?.(new UpdateServerTimeOffset(this._state.timeOffset));
    }

    return message;
  }

private requestFutureServerSalts() {
    if (!this._userConnected || this.futureServerSaltRequest) return;

    const request = this.send(new Api.GetFutureSalts({ num: MAX_FUTURE_SERVER_SALTS }))!;
    this.futureServerSaltRequest = request;
    void request
      .then((futureSalts) => {
        if (this.futureServerSaltRequest !== request) return;
        if (!futureSalts?.salts.length) {
          this.scheduleFutureServerSaltRefresh(SERVER_SALT_REQUEST_RETRY_DELAY);
          return;
        }

        const latestValidUntil = futureSalts.salts.reduce((latest, { validUntil }) => (
          Math.max(latest, validUntil)
        ), 0);
        const serverTime = this._state.getServerTime();
        const refreshDelay = Math.max(
          (latestValidUntil - serverTime - SERVER_SALT_REFRESH_MARGIN) * MILLISECONDS_PER_SECOND,
          SERVER_SALT_REQUEST_RETRY_DELAY,
        );
        this.scheduleFutureServerSaltRefresh(refreshDelay);
      })
      .catch((err: unknown) => {
        if (this.futureServerSaltRequest !== request) return;
        this._log.warn(`Failed to request future server salts: ${String(err)}`);
        this.scheduleFutureServerSaltRefresh(SERVER_SALT_REQUEST_RETRY_DELAY);
      })
      .finally(() => {
        if (this.futureServerSaltRequest === request) this.futureServerSaltRequest = undefined;
      });
  }

private scheduleFutureServerSaltRefresh(delay: number) {
    if (!this._userConnected) return;
    if (this.futureServerSaltRefreshTimer) clearTimeout(this.futureServerSaltRefreshTimer);

    this.futureServerSaltRefreshTimer = setTimeout(() => {
      this.futureServerSaltRefreshTimer = undefined;
      this.requestFutureServerSalts();
    }, delay);
  }

_disconnect(connection: Connection) {
    if (!this._isExported) {
      this._updateCallback?.(new UpdateConnectionState(UpdateConnectionState.disconnected));
    }

    if (connection === undefined) {
      this._log.info('Not disconnecting (already have no connection)');
      return;
    }

    this._log.info('Disconnecting from %s...'.replace('%s', connection.toString()));
    this._userConnected = false;
    this.futureServerSaltRequest = undefined;
    if (this.futureServerSaltRefreshTimer) {
      clearTimeout(this.futureServerSaltRefreshTimer);
      this.futureServerSaltRefreshTimer = undefined;
    }
    this._log.debug('Closing current connection...');
    this.logWithIndex.warn('Disconnecting');
    connection.disconnect();
  }

async _longPollLoop() {
    while (this._userConnected && !this.isReconnecting && this._isFallback
      && this.getConnection()!.shouldLongPoll) {
      await this._sendQueueLongPoll.wait();

      const res = this._sendQueueLongPoll.get();

      if (this.isReconnecting || !this._isFallback) {
        this._longPollLoopHandle = undefined;
        return;
      }

      if (!res) {
        continue;
      }
      let { data } = res;
      const { batch } = res;
      this._log.debug(`Encrypting ${batch.length} message(s) in ${data.length} bytes for sending`);

      for (const state of batch) this._rememberSentMessage(state);

      data = await this._state.encryptMessageData(data);

      try {
        await this._fallbackConnection?.send(data);
      } catch (e: any) {
        this._log.info('Connection closed while sending data');
        // eslint-disable-next-line no-console
        console.error(e);
        this._longPollLoopHandle = undefined;
        this.isSendingLongPoll = false;
        if (!this.userDisconnected) {
          this.handleConnectionError(e);
        }
        return;
      }

      this.isSendingLongPoll = false;
      this.checkLongPoll();
    }

    this._longPollLoopHandle = undefined;
  }

async _sendLoop() {
    this.retryPendingStates();

    while (this._userConnected && !this.isReconnecting) {
      const appendAcks = () => {
        if (this._pendingAck.size) {
          const msgIds = Array.from(this._pendingAck);
          this._pendingAck.clear();

          // https://core.telegram.org/mtproto/service_messages_about_messages#acknowledgment-of-receipt
          for (let index = 0; index < msgIds.length; index += MAX_MESSAGE_IDS) {
            const ack = new RequestState(new Api.MsgsAck({
              msgIds: msgIds.slice(index, index + MAX_MESSAGE_IDS),
            }));
            this._sendQueue.append(ack);
            this._lastAcks.push(ack);
            if (this._lastAcks.length >= 10) this._lastAcks.shift();
          }
        }
      };

      appendAcks();

      this.logWithIndex.debug(`Waiting for messages to send... ${this.isReconnecting}`);
      this._log.debug(`Waiting for messages to send... ${this.isReconnecting}`);
      // TODO Wait for the connection send queue to be empty?
      // This means that while it's not empty we can wait for
      // more messages to be added to the send queue.
      await this._sendQueue.wait();

      // If we've had new ACKs appended while waiting for messages to send, add them to queue
      appendAcks();

      const hasQueuedMessages = this._sendQueue.values().some(Boolean);
      if (!hasQueuedMessages) {
        // Consume explicit empty queue markers before waiting again
        this._sendQueue.get();
        continue;
      }

      if (this._isFallback) {
        // We don't long-poll on main loop, instead we have a separate loop for that
        this.send(new Api.HttpWait({
          maxDelay: 0,
          waitAfter: 0,
          maxWait: 0,
        }));
      }

      const res = this._sendQueue.get();

      this.logWithIndex.debug(`Got ${res?.batch.length} message(s) to send`);

      if (!res) {
        continue;
      }

      let { data } = res;
      const { batch } = res;

      for (const state of batch) {
        if (!Array.isArray(state)) {
          this._rememberSentMessage(state);
          if (this._shouldTrackPendingState(state)) {
            this._pendingState.set(state.msgId!, state);
          }
        } else {
          for (const s of state) {
            this._rememberSentMessage(s);
            if (this._shouldTrackPendingState(s)) {
              this._pendingState.set(s.msgId, s);
            }
          }
        }
      }

      if (this.isReconnecting) {
        this.logWithIndex.debug('Reconnecting :(');
        this._sendLoopHandle = undefined;
        return;
      }

      this._log.debug(`Encrypting ${batch.length} message(s) in ${data.length} bytes for sending`);
      this.logWithIndex.debug('Sending', batch.map((m) => m.request.className));
      const connection = this.getConnection();

      data = await this._state.encryptMessageData(data);

      if (this.isReconnecting) {
        this.logWithIndex.debug('Reconnecting :(');
        this._sendLoopHandle = undefined;
        return;
      }

      if (!connection || connection !== this.getConnection()) {
        this.retryPendingStates();
        continue;
      }

      try {
        await connection.send(data);
        for (const state of batch) {
          if (Array.isArray(state)) {
            state.forEach(this._rememberSentAcknowledgments.bind(this));
          } else {
            this._rememberSentAcknowledgments(state);
          }
        }
      } catch (e: any) {
        this.logWithIndex.debug(`Connection closed while sending data ${e}`);
        this._log.info('Connection closed while sending data');
        // eslint-disable-next-line no-console
        console.error(e);
        this._sendLoopHandle = undefined;
        if (!this.userDisconnected) {
          this.handleConnectionError(e);
        }
        return;
      } finally {
        for (const state of batch) {
          if (!Array.isArray(state)) {
            if (state.request.className === 'HttpWait') {
              state.resolve?.();
            }
          } else {
            for (const s of state) {
              if (s.request.className === 'HttpWait') {
                state.resolve?.();
              }
            }
          }
        }

        this.logWithIndex.debug('Encrypted messages put in a queue to be sent');
        this._log.debug('Encrypted messages put in a queue to be sent');
      }
    }

    this._sendLoopHandle = undefined;
  }

async _recvLoop() {
    let body;
    let message;

    while (this._userConnected && !this.isReconnecting) {
      this._log.debug('Receiving items from the network...');
      this.logWithIndex.debug('Receiving items from the network...');
      try {
        body = await this.getConnection()!.recv();
      } catch (e: any) {
        // this._log.info('Connection closed while receiving data');
        /** when the server disconnects us we want to reconnect */
        if (!this.userDisconnected) {
          this._log.warn('Connection closed while receiving data');
          // eslint-disable-next-line no-console
          console.error(e);
          this.handleConnectionError(e);
        }
        this._recvLoopHandle = undefined;
        return;
      }

      if (body.length === TRANSPORT_CODE_LENGTH && body.every((byte) => byte === 0)) {
        void this.checkLongPoll();
        continue;
      }

      try {
        // TODO: Handle `DecryptedDataBlock` in calls like a regular `TLMessage` rather than `Uint8Array`
        message = await this.decryptMessageData(body);
      } catch (e: any) {
        this.logWithIndex.debug(`Error while receiving items from the network ${e.toString()}`);
        if (e instanceof TypeNotFoundError) {
          // Received object which we don't know how to deserialize
          this._log.info(`Type ${e.invalidConstructorId} not found, remaining data ${e.remaining.length} bytes`);
          continue;
        } else if (e instanceof SecurityError) {
          // https://core.telegram.org/mtproto/security_guidelines#behavior-in-case-of-mismatch
          this.handleSecurityError();
          this._recvLoopHandle = undefined;
          return;
        } else if (e instanceof InvalidBufferError) {
          // 404 means that the server has "forgotten" our auth key and we need to create a new one.
          if (e.code === 404) {
            this._handleBadAuthKey();
          } else {
            // this happens sometimes when telegram is having some internal issues.
            // reconnecting should be enough usually
            // since the data we sent and received is probably wrong now.
            this._log.warn(`Invalid buffer ${e.code} for dc ${this._dcId}`);
            this.reconnect();
          }
          this._recvLoopHandle = undefined;
          return;
        } else {
          this._log.error('Unhandled error while receiving data');
          // eslint-disable-next-line no-console
          console.error(e);
          this.reconnect();
          this._recvLoopHandle = undefined;
          return;
        }
      }
      try {
        await this._processMessage(message);
      } catch (e: any) {
        // `RPCError` errors except for 'AUTH_KEY_UNREGISTERED' should be handled by the client
        if (e instanceof SecurityError) {
          this.handleSecurityError();
          this._recvLoopHandle = undefined;
          return;
        } else if (e instanceof RPCError) {
          if (e.errorMessage === 'AUTH_KEY_UNREGISTERED'
            || e.errorMessage === 'SESSION_REVOKED'
            || e.errorMessage === 'USER_DEACTIVATED') {
            // 'AUTH_KEY_UNREGISTERED' for the main sender is thrown when unauthorized and should be ignored
            this._handleBadAuthKey(true);
          }
        } else {
          this._log.error('Unhandled error while receiving data');
          // eslint-disable-next-line no-console
          console.error(e);
        }
      }

      void this.checkLongPoll();
    }

    this._recvLoopHandle = undefined;
  }

checkLongPoll() {
    if (this.isSendingLongPoll || !this._isFallback) return;

    this.isSendingLongPoll = true;
    this.send(new Api.HttpWait({
      maxDelay: LONGPOLL_MAX_DELAY,
      waitAfter: LONGPOLL_WAIT_AFTER,
      maxWait: LONGPOLL_MAX_WAIT,
    }), undefined, true);
  }

private handleConnectionError(error: unknown) {
    if (!this.shouldResetHttpAuthKey(error)) {
      this.reconnect();
      return;
    }

    if (this.hasHandledHttpAuthKeyError) return;
    this.hasHandledHttpAuthKeyError = true;
    this._handleBadAuthKey();
  }

private shouldResetHttpAuthKey(error: unknown, hadAuthKey?: boolean) {
    return error instanceof HttpStreamError && error.status === 404
      && (hadAuthKey ?? Boolean(this.authKey.getKey()))
      && (this._isExported ? Boolean(this._onConnectionBreak) : this._isMainSender);
  }

_handleBadAuthKey(shouldSkipForMain?: boolean) {
    if (shouldSkipForMain && this._isMainSender) {
      return;
    }

    this._log.warn(`Broken authorization key for dc ${this._dcId}, resetting...`);

    if (this._isMainSender && !this._isExported) {
      this._updateCallback?.(new UpdateConnectionState(UpdateConnectionState.broken));
    } else if (this._isExported && this._onConnectionBreak) {
      this._onConnectionBreak(this._dcId);
    }
  }

async _processMessage(message: TLMessage) {
    this.logWithIndex.debug(`Process message ${message.obj.className}`);

    // https://core.telegram.org/mtproto/description#message-sequence-number-msg-seqno
    if (message.isContentRelated) this._pendingAck.add(message.msgId);

    if (this.getConnection()!.shouldLongPoll) {
      this._sendQueue.setReady?.(true);
    }

    if (this._state.consumeMessageReplay(message)) return;

    let handler = this._handlers[message.obj.CONSTRUCTOR_ID];
    if (!handler) {
      handler = this._handleUpdate.bind(this);
    }

    await handler(message);
  }

_popStates(msgId: bigint) {
    const state = this._pendingState.getAndDelete(msgId);
    const states = state ? [state] : [];

    if (!state) {
      for (const pendingState of this._pendingState.values()) {
        if (pendingState.containerId === msgId) {
          states.push(this._pendingState.getAndDelete(pendingState.msgId!)!);
        }
      }
    }

    for (const ack of this._lastAcks) {
      if ((ack.msgId === msgId || ack.containerId === msgId) && !states.includes(ack)) {
        states.push(ack);
      }
    }

    return states;
  }

private _hasRecentSentMessage(msgId: bigint, seqNo?: number) {
    const sentMessage = this._findSentMessage(msgId);
    return Boolean(sentMessage
      && (seqNo === undefined || this._getSentMessageSeqNo(sentMessage) === seqNo));
  }

private _shouldTrackPendingState(state: RequestState) {
    return (state.request.classType === 'request' && state.request.className !== 'HttpWait')
      || state.request instanceof Api.MsgsStateReq;
  }

private _rememberSentAcknowledgments(state: RequestState) {
    let msgIds: bigint[] | undefined;
    if (state.request instanceof Api.MsgsAck) {
      msgIds = state.request.msgIds;
    } else if (state.request instanceof Api.MsgsStateInfo) {
      msgIds = [state.request.reqMsgId];
      if (state.acknowledgedMsgIds) msgIds.push(...state.acknowledgedMsgIds);
    }
    if (!msgIds) return;

    for (const msgId of msgIds) this._acknowledgedMsgIds.add(msgId);
    while (this._acknowledgedMsgIds.size > MAX_RECENT_ACKNOWLEDGED_MESSAGES) {
      this._acknowledgedMsgIds.delete(this._acknowledgedMsgIds.values().next().value!);
    }
  }

private _rememberSentMessage(state: RequestState) {
    this._forgetSentState(state);
    const message: SentMessage = {
      msgId: state.msgId!,
      seqNo: state.seqNo!,
      sentAt: Date.now(),
      state,
      containerId: state.containerId,
      containerSeqNo: state.containerSeqNo,
    };
    this._recentSentMessages.set(message.msgId, message);
    this._sentMessageIdsByState.set(state, message.msgId);
    if (message.containerId !== undefined) {
      let containerMessageIds = this._sentMessageIdsByContainer.get(message.containerId);
      if (!containerMessageIds) {
        containerMessageIds = new Set();
        this._sentMessageIdsByContainer.set(message.containerId, containerMessageIds);
      }
      containerMessageIds.add(message.msgId);
    }

    if (this._recentSentMessages.size > MAX_RECENT_SENT_MESSAGES) {
      const oldestMessage = this._recentSentMessages.values().next().value!;
      if (oldestMessage.containerId !== undefined) {
        this._forgetSentMessage(oldestMessage.containerId, true);
      } else {
        this._deleteSentMessage(oldestMessage.msgId);
      }
    }
  }

private _findSentMessage(msgId: bigint): SentMessageReference | undefined {
    this._pruneRecentSentMessages();
    const message = this._recentSentMessages.get(msgId);
    if (message) return { message, isContainer: false };

    const sentMessageId = this._sentMessageIdsByContainer.get(msgId)?.values().next().value;
    const containerMessage = sentMessageId !== undefined
      ? this._recentSentMessages.get(sentMessageId)
      : undefined;
    if (!containerMessage) return undefined;

    return { message: containerMessage, isContainer: true };
  }

private _pruneRecentSentMessages() {
    const expiredBefore = Date.now() - RECENT_SENT_MESSAGE_TTL;
    for (const [msgId, { sentAt }] of this._recentSentMessages) {
      if (sentAt < expiredBefore) this._deleteSentMessage(msgId);
    }
  }

private _forgetSentMessage(msgId: bigint, isContainer: boolean) {
    if (!isContainer) {
      this._deleteSentMessage(msgId);
      return;
    }

    const sentMessageIds = this._sentMessageIdsByContainer.get(msgId);
    if (!sentMessageIds) return;

    for (const sentMsgId of sentMessageIds) {
      this._deleteSentMessage(sentMsgId);
    }
  }

private _forgetSentState(state: RequestState) {
    const msgId = this._sentMessageIdsByState.get(state);
    if (msgId !== undefined) this._deleteSentMessage(msgId);
  }

private _deleteSentMessage(msgId: bigint) {
    const sentMessage = this._recentSentMessages.get(msgId);
    if (!sentMessage) return;

    this._recentSentMessages.delete(msgId);
    if (this._sentMessageIdsByState.get(sentMessage.state) === msgId) {
      this._sentMessageIdsByState.delete(sentMessage.state);
    }

    const { containerId } = sentMessage;
    if (containerId === undefined) return;

    const sentMessageIds = this._sentMessageIdsByContainer.get(containerId);
    sentMessageIds?.delete(msgId);
    if (!sentMessageIds?.size) this._sentMessageIdsByContainer.delete(containerId);
  }

_handleRPCResult(message: TLMessage) {
    const result = message.obj;
    const state = this._pendingState.getAndDelete(result.reqMsgId);
    this._log.debug(`Handling RPC result for message ${result.reqMsgId}`);

    if (!state) {
      // TODO We should not get responses to things we never sent
      // However receiving a File() with empty bytes is "common".
      // See #658, #759 and #958. They seem to happen in a container
      // which contain the real response right after.
      try {
        const reader = new BinaryReader(result.body);
        if (!(reader.tgReadObject() instanceof Api.upload.File)) {
          throw new TypeNotFoundError(0, new Uint8Array(0));
        }
      } catch (e) {
        if (e instanceof TypeNotFoundError) {
          this._log.info(`Received response without parent request: ${result.body}`);
          return;
        } else if (this._isFallback) {
          // If we're using HTTP transport, there might be a chance that the response comes through
          // multiple times if didn't send acknowledgment in time, so we should just ignore it
          return;
        }

        throw e;
      }
      return;
    }

    this._forgetSentMessage(result.reqMsgId, false);

    if (result.error) {
      const error = RPCMessageToError(result.error, state.request);
      state.reject?.(error);
      throw error;
    } else {
      try {
        const reader = new BinaryReader(result.body);
        const read = state.request.readResult(reader);
        this.logWithIndex.debug('Handling RPC result', read);
        state.resolve?.(read);
      } catch (err: any) {
        state.reject?.(err);
        throw err;
      }
    }
  }

async _handleContainer(message: TLMessage) {
    this._log.debug('Handling container');
    for (const innerMessage of message.obj.messages) {
      await this._processMessage(innerMessage);
    }
  }

async _handleGzipPacked(message: TLMessage) {
    this._log.debug('Handling gzipped data');
    const { data } = message.obj;
    const reader = new BinaryReader(data);
    const obj = reader.tgReadObject();
    if (obj instanceof MessageContainer || reader.tellPosition() !== data.length) {
      throw new SecurityError();
    }
    message.obj = obj;
    await this._processMessage(message);
  }

_handleUpdate(message: TLMessage) {
    if (message.obj.SUBCLASS_OF_ID !== 0x8af52aac) {
      // crc32(b'Updates')
      this._log.warn(`Note: ${message.obj.className} is not an update, not dispatching it`);
      return;
    }
    this._log.debug(`Handling update ${message.obj.className}`);
    if (!this._isExported) {
      this._updateCallback?.(message.obj);
    }
  }

_handlePong(message: TLMessage) {
    const pong = message.obj;
    const state = this._pendingState.get(pong.msgId);
    const isPing = state?.request instanceof Api.Ping
      || state?.request instanceof Api.PingDelayDisconnect;

    // https://core.telegram.org/mtproto/service_messages#ping-messages-ping-pong
    if (!state || !isPing || state.request.pingId !== pong.pingId) return;

    this._pendingState.delete(pong.msgId);
    this._deleteSentMessage(pong.msgId);

    this._log.debug(`Handling pong for message ${pong.msgId}`);
    state.resolve?.(pong);
  }

_handleBadServerSalt(message: TLMessage) {
    const badSalt = message.obj;
    const sentMessage = this._findSentMessage(badSalt.badMsgId);
    if (badSalt.errorCode !== BAD_SERVER_SALT_ERROR_CODE
      || !sentMessage
      || this._getSentMessageSeqNo(sentMessage) !== badSalt.badMsgSeqno) return;

    // https://core.telegram.org/mtproto/service_messages_about_messages#notice-of-ignored-error-message
    this._forgetSentMessage(badSalt.badMsgId, sentMessage.isContainer);
    this._log.debug(`Handling bad salt for message ${badSalt.badMsgId}`);
    const states = this._popStates(badSalt.badMsgId);
    this._state.setServerSalt(badSalt.newServerSalt, true);
    this._sendQueue.extend(states);
    this.futureServerSaltRequest = undefined;
    this.requestFutureServerSalts();
    this._log.debug(`${states.length} message(s) will be resent`);
  }

_handleBadNotification(message: TLMessage) {
    const badMsg = message.obj;
    const sentMessage = this._findSentMessage(badMsg.badMsgId);
    if (!sentMessage
      || !this._isBadNotificationApplicable(badMsg, message.msgId, sentMessage)) return;

    this._forgetSentMessage(badMsg.badMsgId, sentMessage.isContainer);
    const states = this._popStates(badMsg.badMsgId);
    this._log.debug(`Handling bad msg ${jsonStringifyWithBigInt(badMsg)}`);
    if (INVALID_TIME_ERROR_CODES.has(badMsg.errorCode)) {
      // Sent msg_id too low or too high (respectively).
      // Use the current msg_id to determine the right time offset.
      const { timeOffset: newTimeOffset, isSessionReset } = this._state.updateTimeOffset(message.msgId);
      const shouldResetSession = badMsg.errorCode === MESSAGE_ID_TOO_HIGH_ERROR_CODE;
      if (shouldResetSession && !isSessionReset) this._state.reset();
      if (shouldResetSession || isSessionReset) {
        this._resetSessionTracking();

        if (this._isFallback) {
          this.getConnection()?.disconnect();
          this.reconnect();
        }
      }

      if (!this._isExported) {
        this._updateCallback?.(new UpdateServerTimeOffset(newTimeOffset));
      }

      this._log.info(`System clock is wrong, set time offset to ${newTimeOffset}s`);
    } else if (badMsg.errorCode === 32) {
      // msg_seqno too low, so just pump it up by some "large" amount
      // TODO A better fix would be to start with a new fresh session ID
      this._state._sequence += 64;
    } else if (badMsg.errorCode === 33) {
      // msg_seqno too high never seems to happen but just in case
      this._state._sequence -= 16;
    } else {
      for (const state of states) {
        state.reject?.(new BadMessageError(state.request, badMsg.errorCode));
      }

      return;
    }
    // Messages are to be re-sent once we've corrected the issue
    this._sendQueue.extend(states);
    this._log.debug(`${states.length} messages will be resent due to bad msg`);
  }

private _isBadNotificationApplicable(
    badMsg: Api.BadMsgNotification,
    notificationMsgId: bigint,
    sentMessage: SentMessageReference,
  ) {
    const { errorCode, badMsgId, badMsgSeqno } = badMsg;
    const sentSeqNo = this._getSentMessageSeqNo(sentMessage);
    if (!BAD_MESSAGE_ERROR_CODES.has(errorCode) || sentSeqNo !== badMsgSeqno) return false;
    if (errorCode === 16) return badMsgId < notificationMsgId; // Message ID is too low
    if (errorCode === MESSAGE_ID_TOO_HIGH_ERROR_CODE) return badMsgId > notificationMsgId;
    if (errorCode === 18) return (badMsgId & 3n) !== 0n; // Message ID has invalid low bits
    if (errorCode === 19 || errorCode === 64) return sentMessage.isContainer; // Duplicate ID or invalid container
    if (errorCode === 34) return (sentSeqNo & 1) === 1; // Even sequence number expected
    if (errorCode === 35) return (sentSeqNo & 1) === 0; // Odd sequence number expected

    return true;
  }

private _getSentMessageSeqNo({ message, isContainer }: SentMessageReference) {
    return isContainer ? message.containerSeqNo! : message.seqNo;
  }

_handleDetailedInfo(message: TLMessage) {
    const { answerMsgId } = message.obj;
    this._pendingAck.add(answerMsgId);
    this._log.debug(`Handling detailed info for message ${answerMsgId}`);
  }

_handleNewDetailedInfo(message: TLMessage) {
    const { answerMsgId } = message.obj;
    this._pendingAck.add(answerMsgId);
    this._log.debug(`Handling new detailed info for message ${answerMsgId}`);
  }

_handleNewSessionCreated(message: TLMessage) {
    const { firstMsgId, uniqueId, serverSalt } = message.obj;
    this._log.debug('Handling new session created');
    this._state.setServerSalt(serverSalt);

    if (firstMsgId === this._lastSessionFirstMsgId && uniqueId === this._lastSessionUniqueId) return;
    this._lastSessionFirstMsgId = firstMsgId;
    this._lastSessionUniqueId = uniqueId;

    // https://core.telegram.org/mtproto/service_messages#new-session-creation-notification
    if (!this._isExported) this._updateCallback?.(new UpdateSessionGap(firstMsgId, uniqueId));
  }

_handleFutureSalts(message: TLMessage) {
    const futureSalts = message.obj;
    const state = this._pendingState.get(futureSalts.reqMsgId);

    // https://core.telegram.org/mtproto/service_messages#request-for-several-future-salts
    if (!(state?.request instanceof Api.GetFutureSalts)
      || state.request.num < 1
      || state.request.num > MAX_FUTURE_SERVER_SALTS
      || futureSalts.salts.length > state.request.num) return;

    if (state.promise !== this.futureServerSaltRequest) {
      this._pendingState.delete(futureSalts.reqMsgId);
      this._forgetSentMessage(futureSalts.reqMsgId, false);
      state.resolve?.();
      return;
    }

    if (!this._state.setFutureSalts(futureSalts.salts)) return;

    this._pendingState.delete(futureSalts.reqMsgId);
    this._forgetSentMessage(futureSalts.reqMsgId, false);
    this._log.debug(`Handling future salts for message ${futureSalts.reqMsgId.toString()}`);
    state.resolve?.(futureSalts);
  }

_handleStateReq(message: TLMessage) {
    this._sendStateInfo(message.msgId, message.obj.msgIds);
  }

_handleResendReq(message: TLMessage) {
    const states: RequestState[] = [];
    const knownStates = new Set<RequestState>();
    let hasUnknownMessages = false;

    for (const msgId of message.obj.msgIds) {
      if (!this._collectResendStates(msgId, states, knownStates)) {
        hasUnknownMessages = true;
      }
    }

    if (hasUnknownMessages) this._sendStateInfo(message.msgId, message.obj.msgIds);

    // https://core.telegram.org/mtproto/service_messages_about_messages#explicit-request-to-re-send-messages
    this._resendStates(states);
  }

_handleStateInfo(message: TLMessage) {
    const stateInfo: Api.MsgsStateInfo = message.obj;
    const state = this._pendingState.get(stateInfo.reqMsgId);
    const statusCodes = stateInfo.info;
    if (!(state?.request instanceof Api.MsgsStateReq)
      || statusCodes.length !== state.request.msgIds.length
      || statusCodes.some((statusCode) => {
        const baseStatus = statusCode & 7;
        return baseStatus < 1 || baseStatus > 4;
      })) return;

    this._pendingState.delete(stateInfo.reqMsgId);
    this._forgetSentMessage(stateInfo.reqMsgId, false);

    const states: RequestState[] = [];
    const knownStates = new Set<RequestState>();
    statusCodes.forEach((statusCode, index) => {
      const baseStatus = statusCode & 7;
      if (baseStatus !== MESSAGE_STATE_RECEIVED
        && !(statusCode & MESSAGE_STATE_RECEIVED_ELSEWHERE)) {
        this._collectResendStates(state.request.msgIds[index], states, knownStates);
      }
    });
    // https://core.telegram.org/mtproto/service_messages_about_messages#informational-message-regarding-status-of-messages
    this._resendStates(states);
    state.resolve?.();
  }

private _sendStateInfo(reqMsgId: bigint, msgIds: bigint[]) {
    const acknowledgedMsgIds: bigint[] = [];
    const info = Uint8Array.from(msgIds, (msgId) => {
      const status = this._state.getIncomingMessageState(
        msgId, this._acknowledgedMsgIds.has(msgId),
      );
      if ((status & 7) === MESSAGE_STATE_RECEIVED && !(status & MESSAGE_STATE_NO_ACK_REQUIRED)) {
        acknowledgedMsgIds.push(msgId);
      }
      return status;
    });
    const state = new RequestState(new Api.MsgsStateInfo({ reqMsgId, info }));
    state.acknowledgedMsgIds = acknowledgedMsgIds;
    this._sendQueue.append(state);
  }

private _collectResendStates(
    msgId: bigint, states: RequestState[], knownStates: Set<RequestState>,
  ) {
    const sentMessage = (msgId & 3n) === 0n ? this._findSentMessage(msgId) : undefined;
    if (!sentMessage) return false;

    const messages = sentMessage.isContainer
      ? Array.from(this._sentMessageIdsByContainer.get(msgId) ?? [], (sentMsgId) => (
        this._recentSentMessages.get(sentMsgId)!
      ))
      : [sentMessage.message];
    for (const { state } of messages) {
      if (knownStates.has(state)) continue;
      knownStates.add(state);
      states.push(state);
    }
    return true;
  }

private _resendStates(states: RequestState[]) {
    for (const state of states) {
      this._pendingState.delete(state.msgId!);
      this._forgetSentState(state);
    }
    this._sendQueue.extend(states);
  }

private handleSecurityError() {
    this._log.warn('Invalid encrypted packet');
    if (!this._isFallback && this._shouldAllowHttpTransport) {
      this._shouldUseFallbackOnReconnect = true;
    }
    this.reconnect();
  }

reconnect() {
    if (this._userConnected && !this.isReconnecting) {
      this.isReconnecting = true;
      // TODO Should we set this?
      // this._user_connected = false
      // we want to wait a second between each reconnect try to not flood the server with reconnects
      // in case of internal server issues.
      sleep(1000)
        .then(() => {
          this.logWithIndex.log('Reconnecting...');
          this._log.info('Started reconnecting');
          this._reconnect();
        });
    }
  }

async _reconnect() {
    if (this.userDisconnected) {
      this.isReconnecting = false;
      this._shouldUseFallbackOnReconnect = false;
      return;
    }

    const shouldUseFallback = this._shouldUseFallbackOnReconnect;
    this._shouldUseFallbackOnReconnect = false;
    const currentConnection = this._connection!;
    const currentFallbackConnection = this._fallbackConnection;
    this._log.debug('Closing current connection...');
    try {
      this.logWithIndex.warn('[Reconnect] Closing current connection...');
      if (currentConnection) this._disconnect(currentConnection);
      if (currentFallbackConnection) this._disconnect(currentFallbackConnection);
    } catch (err: any) {
      this._log.warn(err);
    }

    this._sendQueue.append(undefined);
    this._state.reset();
    this._pendingAck.clear();
    this._acknowledgedMsgIds.clear();
    this._recentSentMessages.clear();
    this._sentMessageIdsByState.clear();
    this._sentMessageIdsByContainer.clear();
    this._lastAcks.length = 0;
    this._lastSessionFirstMsgId = undefined;
    this._lastSessionUniqueId = undefined;

    // For some reason reusing existing connection caused stuck requests
    // @ts-expect-error -- Hacky way to create new class instance
    const newConnection = new currentConnection.constructor({
      ip: currentConnection._ip,
      port: currentConnection._port,
      dcId: currentConnection._dcId,
      loggers: currentConnection._log,
      isTestServer: currentConnection._isTestServer,
      isPremium: currentConnection._isPremium,
    });
    // @ts-expect-error -- Hacky way to create new class instance
    const newFallbackConnection = new this._fallbackConnection.constructor({
      ip: currentConnection._ip,
      port: currentConnection._port,
      dcId: currentConnection._dcId,
      loggers: currentConnection._log,
      isTestServer: currentConnection._isTestServer,
      isPremium: currentConnection._isPremium,
    });
    try {
      await this.connect(newConnection, true, newFallbackConnection, shouldUseFallback);
    } catch {
      return;
    } finally {
      this.isReconnecting = false;
    }

    if (this._autoReconnectCallback) {
      await this._autoReconnectCallback();
    }
  }

private retryPendingStates() {
    const pendingStates = this._pendingState.values();
    if (!pendingStates.length) return;

    this._sendQueue.prepend(pendingStates);
    this._pendingState.clear();
  }

private _resetSessionTracking() {
    this.retryPendingStates();
    this._pendingAck.clear();
    this._acknowledgedMsgIds.clear();
    this._recentSentMessages.clear();
    this._sentMessageIdsByState.clear();
    this._sentMessageIdsByContainer.clear();
    this._lastAcks.length = 0;
    this._lastSessionFirstMsgId = undefined;
    this._lastSessionUniqueId = undefined;
  }

function useDebouncedCallback<T extends AnyToVoidFunction>(
  fn: T,
  deps: any[],
  ms: number,
  noFirst = false,
  noLast = false,
) {
  // eslint-disable-next-line react-hooks-static-deps/exhaustive-deps
  const fnMemo = useCallback(fn, deps);

  return useMemo(() => {
    return debounce(fnMemo, ms, !noFirst, !noLast);
  }, [fnMemo, ms, noFirst, noLast]);
}

function hasRank(member?: ApiChatMember): boolean {
  return Boolean(member && (member.rank || member.isOwner || member.isAdmin));
}

function useThumbnail(media?: MediaContainer | ApiThumbnail) {
  const isMediaContainer = media && 'content' in media;
  const global = getGlobal();
  const thumbDataUri = isMediaContainer ? selectMessageMediaThumbDataUri(global, media) : media?.dataUri;

  // TODO Find a way to update thumbnail on theme change
  const theme = selectTheme(global);

  const dataUri = useMemo(() => {
    const uri = thumbDataUri;
    if (!uri || theme !== 'dark') return uri;

    return uri.replace('<svg', '<svg fill="white"');
  }, [thumbDataUri, theme]);

  return dataUri;
}

function runForAllTabs(global: GlobalState, callback: TabCallback) {
  Object.values(global.byTabId).forEach(({ id: tabId }) => callback(tabId));
}

function runForFocusedTabs(global: GlobalState, callback: TabCallback) {
  Object.values(global.byTabId).forEach(({ id: tabId, isBlurred }) => {
    if (!isBlurred) callback(tabId);
  });
}

function buildCollectionByKey<T extends AnyLiteral>(collection: T[], key: keyof T) {
  return collection.reduce((byKey: CollectionByKey<T>, member: T) => {
    byKey[member[key]] = member;

    return byKey;
  }, {});
}

function buildCollectionByCallback<T, K extends number | string, R>(
  collection: T[],
  callback: (member: T) => [K, R],
) {
  return collection.reduce((byKey: Record<K, R>, member: T) => {
    const [key, value] = callback(member);
    byKey[key] = value;

    return byKey;
  }, {} as Record<K, R>);
}

function mapValues<R, M>(
  byKey: CollectionByKey<M>,
  callback: (member: M, key: string, index: number, originalByKey: CollectionByKey<M>) => R,
): CollectionByKey<R> {
  return Object.keys(byKey).reduce((newByKey: CollectionByKey<R>, key, index) => {
    newByKey[key] = callback(byKey[key], key, index, byKey);
    return newByKey;
  }, {});
}

function mapTruthyValues<R, M>(
  byKey: CollectionByKey<M>,
  callback: (member: M, key: string, index: number, originalByKey: CollectionByKey<M>) => R | Falsy,
): CollectionByKey<R> {
  return Object.keys(byKey).reduce((newByKey: CollectionByKey<R>, key, index) => {
    const value = callback(byKey[key], key, index, byKey);
    if (value) {
      newByKey[key] = value;
    }
    return newByKey;
  }, {});
}

function pick<T, K extends keyof T>(object: T, keys: K[]) {
  return keys.reduce((result, key) => {
    result[key] = object[key];
    return result;
  }, {} as Pick<T, K>);
}

function pickTruthy<T, K extends keyof T>(object: T, keys: K[]) {
  return keys.reduce((result, key) => {
    if (object[key]) {
      result[key] = object[key];
    }

    return result;
  }, {} as Pick<T, K>);
}

function omit<T extends object, K extends keyof T>(object: T, keys: K[]): Omit<T, K> {
  const stringKeys = new Set(keys.map(String));
  const savedKeys = Object.keys(object)
    .filter((key) => !stringKeys.has(key)) as Array<Exclude<keyof T, K>>;

  return pick(object, savedKeys);
}

function omitUndefined<T extends object>(object: T): T {
  return Object.keys(object).reduce((result, stringKey) => {
    const key = stringKey as keyof T;
    if (object[key] !== undefined) {
      result[key] = object[key];
    }
    return result;
  }, {} as T);
}

function orderBy<T>(
  collection: T[],
  orderRule: (keyof T) | OrderCallback<T> | ((keyof T) | OrderCallback<T>)[],
  mode: OrderDirection | [OrderDirection, OrderDirection] = 'asc',
): T[] {
  function compareValues(a: T, b: T, currentOrderRule: (keyof T) | OrderCallback<T>, isAsc: boolean) {
    const aValue = (typeof currentOrderRule === 'function' ? currentOrderRule(a) : a[currentOrderRule]) || 0;
    const bValue = (typeof currentOrderRule === 'function' ? currentOrderRule(b) : b[currentOrderRule]) || 0;

    // @ts-expect-error Rely on the JS to handle the comparison
    return isAsc ? aValue - bValue : bValue - aValue;
  }

  if (Array.isArray(orderRule)) {
    const [mode1, mode2] = Array.isArray(mode) ? mode : [mode, mode];
    const [orderRule1, orderRule2] = orderRule;
    const isAsc1 = mode1 === 'asc';
    const isAsc2 = mode2 === 'asc';

    return collection.sort((a, b) => {
      return compareValues(a, b, orderRule1, isAsc1) || compareValues(a, b, orderRule2, isAsc2);
    });
  }

  const isAsc = mode === 'asc';
  return collection.sort((a, b) => {
    return compareValues(a, b, orderRule, isAsc);
  });
}

function compareValues(a: T, b: T, currentOrderRule: (keyof T) | OrderCallback<T>, isAsc: boolean) {
    const aValue = (typeof currentOrderRule === 'function' ? currentOrderRule(a) : a[currentOrderRule]) || 0;
    const bValue = (typeof currentOrderRule === 'function' ? currentOrderRule(b) : b[currentOrderRule]) || 0;

    // @ts-expect-error Rely on the JS to handle the comparison
    return isAsc ? aValue - bValue : bValue - aValue;
  }

function shuffle<T>(array: readonly T[]): T[] {
  const shuffled = [...array];

  for (let i = shuffled.length - 1; i > 0; i -= 1) {
    const randomIndex = Math.floor(Math.random() * (i + 1));
    [shuffled[i], shuffled[randomIndex]] = [shuffled[randomIndex], shuffled[i]];
  }

  return shuffled;
}

function unique<T>(array: T[]): T[] {
  return Array.from(new Set(array));
}

function uniqueByField<T>(array: T[], field: keyof T): T[] {
  return [...new Map(array.map((item) => [item[field], item])).values()];
}

function compact<T>(array: (T | Falsy)[]): T[] {
  return array.filter(Boolean);
}

function areSortedArraysEqual(array1: any[], array2: any[]) {
  if (array1.length !== array2.length) {
    return false;
  }

  return array1.every((item, i) => item === array2[i]);
}

function areSortedArraysIntersecting(array1: any[], array2: any[]) {
  return array1[0] <= array2[array2.length - 1] && array1[array1.length - 1] >= array2[0];
}

function isInsideSortedArrayRange(value: any, array: any[]) {
  return array[0] <= value && value <= array[array.length - 1];
}

function findIntersectionWithSet<T>(array: T[], set: Set<T>): T[] {
  return array.filter((a) => set.has(a));
}

function excludeSortedArray<T>(base: T[], toExclude: T[]) {
  if (!base?.length) return base;

  const result: T[] = [];

  let excludeIndex = 0;

  for (let i = 0; i < base.length; i++) {
    if (toExclude[excludeIndex] === base[i]) {
      excludeIndex += 1;
    } else {
      result.push(base[i]);
    }
  }

  return result;
}

function split<T>(array: T[], chunkSize: number) {
  const result: T[][] = [];
  for (let i = 0; i < array.length; i += chunkSize) {
    result.push(array.slice(i, i + chunkSize));
  }

  return result;
}

function partition<T>(
  array: T[], filter: (value: T, index: number, array: T[]) => boolean | undefined,
): [T[], T[]] {
  const pass: T[] = [];
  const fail: T[] = [];

  array.forEach((e, idx, arr) => (filter(e, idx, arr) ? pass : fail).push(e));

  return [pass, fail];
}

function cloneDeep<T>(value: T): T {
  if (!isObject(value)) {
    return value;
  }

  if (Array.isArray(value)) {
    return value.map(cloneDeep) as typeof value;
  }

  return Object.keys(value).reduce((acc, key) => {
    acc[key as keyof T] = cloneDeep(value[key as keyof T]);
    return acc;
  }, {} as T);
}

function isLiteralObject(value: any): value is AnyLiteral {
  return isObject(value) && !Array.isArray(value);
}

function isObject(value: any): value is object {
  // eslint-disable-next-line no-null/no-null
  return typeof value === 'object' && value !== null;
}

function findLast<T>(array: Array<T>, predicate: (value: T, index: number, obj: T[]) => boolean): T | undefined {
  let cursor = array.length;

  while (cursor--) {
    if (predicate(array[cursor], cursor, array)) {
      return array[cursor];
    }
  }

  return undefined;
}

function compareFields<T>(a: T, b: T) {
  return Number(b) - Number(a);
}

async function loadAndReplaceMessages<T extends GlobalState>(global: T, actions: RequiredGlobalActions) {
  let areMessagesLoaded = false;

  global = getGlobal();

  let wasReset = false;
  const preservedTabThreadsByTabId = preserveCurrentTabThreads(global);

  const currentTabId = getCurrentTabId();
  const tabs = Object.values(global.byTabId)
    .sort(({ id: leftId }, { id: rightId }) => {
      if (leftId === currentTabId) return -1;
      if (rightId === currentTabId) return 1;
      return 0;
    });

  for (const { id: tabId } of tabs) {
    global = getGlobal();
    const { chatId: currentChatId, threadId: currentThreadId } = selectCurrentMessageList(global, tabId) || {};
    const activeThreadId = currentThreadId || MAIN_THREAD_ID;
    const currentChat = currentChatId ? global.chats.byId[currentChatId] : undefined;
    const currentViewportIds = currentChatId
      ? selectViewportIds(global, currentChatId, activeThreadId, tabId)
      : undefined;
    const isSavedDialog = currentChatId
      ? getIsSavedDialog(currentChatId, activeThreadId, global.currentUserId)
      : false;
    if (currentChatId && currentChat) {
      const discussionChat = resolveDiscussionChat(global, currentChatId, activeThreadId);
      const [result, resultDiscussion, refreshedViewportMessages] = await Promise.all([
        loadTopMessages(
          global,
          currentChatId,
          activeThreadId,
          currentViewportIds,
        ),
        discussionChat
          ? callApi('fetchDiscussionMessage', {
            chat: discussionChat.chat,
            messageId: discussionChat.messageId,
          }) : undefined,
        currentViewportIds?.length && !isSavedDialog
          ? callApi('fetchMessagesById', {
            chat: currentChat,
            messageIds: currentViewportIds,
          }).catch(() => undefined)
          : undefined,
      ]);
      global = getGlobal();
      const { chatId: newCurrentChatId } = selectCurrentMessageList(global, tabId) || {};

      if (result && newCurrentChatId === currentChatId) {
        const currentChatMessages = selectChatMessages(global, currentChatId);
        const localMessages = currentChatId === SERVICE_NOTIFICATIONS_USER_ID
          ? global.serviceNotifications.filter(({ isDeleted }) => !isDeleted).map(({ message }) => message)
          : [];
        const topics = selectTopics(global, currentChatId);
        const topicLastMessages = topics ? Object.values(topics)
          .map(({ id }) => {
            const topicThreadInfo = selectThreadInfo(global, currentChatId, id);
            return topicThreadInfo?.lastMessageId ? currentChatMessages[topicThreadInfo.lastMessageId] : undefined;
          }).filter(Boolean) : [];

        const resultMessageIds = result.messages.map(({ id }) => id);
        const messagesThreads = pick(global.messages.byChatId[currentChatId].threadsById, resultMessageIds);

        const isDiscussionStartLoaded = !result.messages.length
          || result.messages.some(({ id }) => id === resultDiscussion?.firstMessageId);
        const threadStartMessages = (isDiscussionStartLoaded && resultDiscussion?.topMessages) || [];
        const refreshedViewportIds = refreshedViewportMessages?.map(({ id }) => id) || [];
        const allMessages = threadStartMessages.concat(result.messages, refreshedViewportMessages || [], localMessages);
        const allMessagesWithTopicLastMessages = allMessages.concat(topicLastMessages);
        const byId = buildCollectionByKey(allMessagesWithTopicLastMessages, 'id');
        const listedIds = unique(refreshedViewportIds.concat(allMessages.map(({ id }) => id)));

        if (!wasReset) {
          global = resetMessages(global, preserveThreads(global));

          Object.values(global.byTabId).forEach(({ id: otherTabId }) => {
            global = updateTabState(global, {
              tabThreads: preservedTabThreadsByTabId[otherTabId] || {},
            }, otherTabId);
          });
          wasReset = true;
        }

        global = replaceChatMessages(global, currentChatId, {
          ...selectChatMessages(global, currentChatId),
          ...byId,
        });
        if (resultDiscussion) {
          global = updateThreadInfo(global, resultDiscussion.threadInfo);
          global = updateThreadReadState(global, currentChatId, activeThreadId, resultDiscussion.threadReadState);
          global = replaceThreadLocalStateParam(
            global, currentChatId, activeThreadId, 'firstMessageId', resultDiscussion.firstMessageId,
          );
          global = addChatMessagesById(global, currentChatId, buildCollectionByKey(resultDiscussion.topMessages, 'id'));
        }
        global = updateListedIds(global, currentChatId, activeThreadId, listedIds);

        Object.entries(messagesThreads).forEach(([id, thread]) => {
          if (!thread?.threadInfo) return;
          global = updateThreadInfo(global, thread.threadInfo);
        });

        Object.values(global.byTabId).forEach(({ id: otherTabId }) => {
          const { chatId: otherChatId, threadId: otherThreadId } = selectCurrentMessageList(global, otherTabId) || {};
          if (otherChatId === currentChatId && otherThreadId === activeThreadId) {
            const preservedViewportIds = preservedTabThreadsByTabId[otherTabId]
              ?.[currentChatId]?.[activeThreadId]?.viewportIds;
            const mergedMessagesById = selectChatMessages(global, currentChatId) || {};
            const nextViewportIds = preservedViewportIds?.filter((id) => Boolean(mergedMessagesById[id]));

            global = safeReplaceViewportIds(
              global,
              currentChatId,
              activeThreadId,
              nextViewportIds?.length ? nextViewportIds : listedIds,
              otherTabId,
            );
          }
        });
        global = updateChats(global, buildCollectionByKey(result.chats, 'id'));
        global = updateUsers(global, buildCollectionByKey(result.users, 'id'));

        areMessagesLoaded = true;
      }
    }

    setGlobal(global);

    if (currentChat?.isForum) {
      actions.loadTopics({ chatId: currentChatId!, force: true });
      if (currentThreadId && currentThreadId !== MAIN_THREAD_ID) {
        actions.loadTopicById({
          chatId: currentChatId!, topicId: Number(currentThreadId), shouldCloseChatOnError: true,
        });
      }
    }
  }

  global = getGlobal();

  if (!areMessagesLoaded) {
    global = resetMessages(global, preserveThreads(global));

    Object.values(global.byTabId).forEach(({ id: otherTabId }) => {
      global = updateTabState(global, {
        tabThreads: preservedTabThreadsByTabId[otherTabId] || {},
      }, otherTabId);
    });
  }

  setGlobal(global);

  Object.values(global.byTabId).forEach(({ id: tabId }) => {
    const { chatId: audioChatId, messageId: audioMessageId } = selectTabState(global, tabId).audioPlayer;
    if (audioChatId && audioMessageId && !selectChatMessage(global, audioChatId, audioMessageId)) {
      actions.closeAudioPlayer({ tabId });
    }
  });
}

function resetMessages<T extends GlobalState>(
  global: T,
  preservedByChatId: GlobalState['messages']['byChatId'] = {},
) {
  return {
    ...global,
    messages: {
      ...global.messages,
      byChatId: preservedByChatId,
    },
  };
}

function preserveCurrentTabThreads<T extends GlobalState>(global: T) {
  return Object.values(global.byTabId).reduce<Record<number, GlobalState['byTabId'][number]['tabThreads']>>(
    (acc, { id: tabId }) => {
      const currentMessageList = selectCurrentMessageList(global, tabId);
      if (!currentMessageList) {
        return acc;
      }

      const { chatId, threadId = MAIN_THREAD_ID } = currentMessageList;
      const currentTabThread = selectTabState(global, tabId).tabThreads[chatId]?.[threadId];

      if (!currentTabThread) {
        return acc;
      }

      acc[tabId] = {
        [chatId]: {
          [threadId]: currentTabThread,
        },
      };

      return acc;
    },
    {},
  );
}

function preserveCurrentThreads<T extends GlobalState>(global: T) {
  return Object.values(global.byTabId).reduce<GlobalState['messages']['byChatId']>((acc, { id: tabId }) => {
    const currentMessageList = selectCurrentMessageList(global, tabId);
    if (!currentMessageList) {
      return acc;
    }

    const { chatId, threadId = MAIN_THREAD_ID } = currentMessageList;
    const currentThread = global.messages.byChatId[chatId]?.threadsById[threadId];
    if (!currentThread) {
      return acc;
    }

    const pinnedMessagesById = pickTruthy(
      global.messages.byChatId[chatId].byId, currentThread.localState?.pinnedIds || [],
    );

    acc[chatId] = {
      byId: {
        ...acc[chatId]?.byId,
        ...pinnedMessagesById,
      },
      ephemeralById: global.messages.byChatId[chatId]?.ephemeralById || {},
      summaryById: {},
      threadsById: {
        ...acc[chatId]?.threadsById,
        [threadId]: {
          ...currentThread,
          localState: {
            ...currentThread.localState,
            listedIds: undefined,
            outlyingLists: undefined,
          },
        },
      },
    };

    return acc;
  }, {});
}

function preserveThreads<T extends GlobalState>(global: T) {
  const preservedByChatId = preserveCurrentThreads(global);

  Object.entries(global.messages.byChatId).forEach(([chatId, messages]) => {
    Object.entries(messages.threadsById).forEach(([stringThreadId, thread]) => {
      const threadId = Number(stringThreadId);
      if (preservedByChatId[chatId]?.threadsById[threadId]) return;

      const { draft, editingId, editingDraft } = thread.localState;
      const hasLocalComposerState = Boolean(draft || editingId || editingDraft);
      if (threadId !== MAIN_THREAD_ID && !hasLocalComposerState) return;

      preservedByChatId[chatId] = {
        byId: { ...preservedByChatId[chatId]?.byId },
        ephemeralById: messages.ephemeralById,
        summaryById: {},
        threadsById: {
          ...preservedByChatId[chatId]?.threadsById,
          [threadId]: {
            ...thread,
            localState: omitUndefined({ draft, editingId, editingDraft }),
          },
        },
      };
    });
  });

  return preservedByChatId;
}

function resolveDiscussionChat<T extends GlobalState>(
  global: T,
  chatId: string,
  threadId: ThreadId,
) {
  if (threadId === MAIN_THREAD_ID) return undefined;

  const chat = selectChat(global, chatId);
  if (!chat || chat.isForum || getIsSavedDialog(chatId, threadId, global.currentUserId)) return undefined;

  const threadInfo = selectThreadInfo(global, chatId, threadId);
  if (threadInfo?.isCommentsInfo === false && threadInfo.fromChannelId) {
    const originChannel = selectChat(global, threadInfo.fromChannelId);
    if (originChannel && threadInfo.fromMessageId) {
      return { chat: originChannel, messageId: threadInfo.fromMessageId };
    }
  }

  return { chat, messageId: Number(threadId) };
}

function loadTopMessages<T extends GlobalState>(
  global: T,
  chatId: string,
  threadId: ThreadId,
  viewportIds?: number[],
) {
  const currentUserId = global.currentUserId!;
  const isSavedDialog = getIsSavedDialog(chatId, threadId, currentUserId);
  const realChatId = isSavedDialog ? String(threadId) : chatId;

  const chat = selectChat(global, realChatId);
  if (!chat) return undefined;

  const readState = selectThreadReadState(global, chatId, threadId);
  const viewportAnchorId = viewportIds?.[0];
  const shouldRestoreViewport = Boolean(viewportAnchorId && !getIsSavedDialog(chatId, threadId, currentUserId));

  return callApi('fetchMessages', {
    chat,
    threadId,
    offsetId: shouldRestoreViewport ? viewportAnchorId
      : (!isSavedDialog ? readState?.lastReadInboxMessageId : undefined),
    addOffset: shouldRestoreViewport ? -(MESSAGE_LIST_SLICE + 1) : -(Math.round(MESSAGE_LIST_SLICE / 2) + 1),
    limit: shouldRestoreViewport ? (MESSAGE_LIST_SLICE + 1) : MESSAGE_LIST_SLICE,
    isSavedDialog,
  });
}

class TelegramClient {
  private invokeMiddleware?: <A, R>(mockClient: TelegramClient, request: Api.Request<A, R>)
  => Promise<R | undefined | 'pass'>;

  public mockData: MockTypes = {
    users: [],
    chats: [],
    channels: [],
    dialogFilters: [],
    dialogs: {
      active: [],
      archived: [],
    },
    messages: {},
    availableReactions: [],
    documents: [],
    topPeers: [],
  };

  private _log: Logger;

  constructor() {
    this._log = new Logger();
  }

  private callbacks: {
    callback: any;
    eventBuilder: any;
  }[] = [];

  addEventHandler(callback: any, eventBuilder: any) {
    this.callbacks.push({
      callback,
      eventBuilder,
    });
  }

  async loadScenario(scenario = 'default'): Promise<void> {
    try {
      const invokeMiddleware = await import(/* @vite-ignore */ `./__invokeMiddlewares__/${scenario}`);

      this.invokeMiddleware = invokeMiddleware.default;
    } catch (e) {
      // Ignore and use the default logic
    }
    return import(`./__mocks__/${scenario}.json`).then(async (mockData) => {
      this.mockData = mockData as MockTypes;
      await Promise.all(this.mockData.documents.map(async (l, i) => {
        const response = await import(/* @vite-ignore */ `./__data__/${l.url}`).then((module) => fetch(module.default));
        const bytes = await response.arrayBuffer();
        this.mockData.documents[i].size = BigInt(bytes.byteLength);
        this.mockData.documents[i].bytes = new Uint8Array(bytes);
      }));

      this.callbacks.forEach(({ eventBuilder, callback }) => (callback(
        eventBuilder.build(new UpdateConnectionState(UpdateConnectionState.connected)),
      )));
    }).catch(() => this.loadScenario());
  }

  fireUpdate(update: Api.TypeUpdate) {
    this.callbacks.forEach(({ eventBuilder, callback }) => (callback(eventBuilder.build(update))));
  }

  getUser(id: string) {
    return createMockedUser(id, this.mockData);
  }

  getDialogs(type: 'active' | 'archived' = 'active') {
    return this.mockData.dialogs[type].map((dialog) => createMockedDialog(dialog.id, this.mockData));
  }

  start({
    mockScenario,
  }: {
    mockScenario: string;
  }) {
    return this.loadScenario(mockScenario);
  }

  async invoke<A, R>(request: Api.Request<A, R>) {
    if (this.invokeMiddleware) {
      const a = await this.invokeMiddleware(this, request);
      if (a !== 'pass') {
        return a;
      }
    }

    if (this.mockData.appConfig && request instanceof Api.help.GetAppConfig) {
      return createMockedJSON(this.mockData.appConfig);
    }

    if (request instanceof Api.messages.GetDiscussionMessage) {
      const peerId = getIdFromInputPeer(request.peer);
      if (!peerId) return undefined;

      return new Api.messages.DiscussionMessage({
        messages: this.getMessagesFrom(peerId).filter((l) => l.id === request.msgId),
        unreadCount: 0,
        chats: [],
        users: [],
      });
    }

    if (request instanceof Api.messages.GetReplies) {
      const peerId = getIdFromInputPeer(request.peer);
      if (!peerId) return undefined;

      const messages = this.mockData.messages[peerId].filter((message) => message.replyToTopId === request.msgId);
      return new Api.messages.Messages({
        messages: messages.map((message) => createMockedMessage(peerId, message.id, this.mockData)),
        chats: [],
        users: [],
        topics: [],
      });
    }

    if (request instanceof Api.contacts.GetTopPeers) {
      return new Api.contacts.TopPeers({
        categories: [new Api.TopPeerCategoryPeers({
          category: request.botsInline
            ? new Api.TopPeerCategoryBotsInline()
            : request.botsApp
              ? new Api.TopPeerCategoryBotsApp()
              : request.botsGuestchat
                ? new Api.TopPeerCategoryBotsGuestChat()
                : new Api.TopPeerCategoryCorrespondents(),
          count: this.mockData.topPeers.length,
          peers: this.mockData.topPeers.map((id) => {
            return new Api.TopPeer({
              peer: createMockedTypePeer(id, this.mockData),
              rating: 100,
            });
          }),
        })],
        chats: [],
        users: this.getUsers(),
      });
    }

    if (request instanceof Api.messages.GetForumTopics) {
      const peerId = getIdFromInputPeer(request.peer);
      if (!peerId) return undefined;

      const topics = this.getChannel(peerId)?.forumTopics;

      if (!topics) return undefined;

      const hasGeneralTopic = topics.some((l) => l.id === GENERAL_TOPIC_ID);
      const offsetTopicId = request.offsetTopic;
      const limit = request.limit;
      return new Api.messages.ForumTopics({
        topics: topics
          .sort((a, b) => b.id - a.id)
          .map((topic) => {
            return createMockedForumTopic(peerId, topic.id, this.mockData);
          }).filter((topic) => {
            if (offsetTopicId) {
              return topic.id < offsetTopicId;
            }
            return true;
          }).slice(0, limit),
        users: [],
        chats: [],
        messages: [],
        pts: 0,
        count: topics.length - (hasGeneralTopic ? 1 : 0),
      });
    }

    if (request instanceof Api.users.GetFullUser) {
      return new Api.users.UserFull({
        fullUser: new Api.UserFull({
          about: 'lol',
          settings: new Api.PeerSettings({}),
          notifySettings: new Api.PeerNotifySettings({}),
          id: 1n,
          commonChatsCount: 0,
        }),
        chats: [],
        users: [],
      });
    }

    if (request instanceof Api.messages.GetAvailableReactions) {
      return new Api.messages.AvailableReactions({
        reactions: this.mockData.availableReactions.map((reaction) => {
          return createMockedAvailableReaction(reaction, this.mockData);
        }),
        hash: 1,
      });
    }

    if (request instanceof Api.messages.GetHistory) {
      const peerId = getIdFromInputPeer(request.peer);
      if (!peerId) return undefined;

      return new Api.messages.Messages({
        messages: this.getMessagesFrom(peerId),
        chats: [],
        users: [],
        topics: [],
      });
    }

    if (request instanceof Api.upload.GetFile) {
      const fileId = getDocumentIdFromLocation(request.location);
      if (fileId === undefined) return undefined;

      return new Api.upload.File({
        type: new Api.storage.FileUnknown(),
        mtime: 0,
        bytes: new Uint8Array(this.mockData.documents.find((i) => i.id === fileId)!.bytes),
      });
    }

    if (request instanceof Api.messages.GetDialogFilters) {
      return [
        new Api.DialogFilterDefault(),
        ...this.mockData.dialogFilters
          .map((dialogFilter) => createMockedDialogFilter(dialogFilter.id, this.mockData)),
      ];
    }

    if (request instanceof Api.messages.GetPinnedDialogs) {
      return new Api.messages.PeerDialogs({
        dialogs: [],
        chats: [],
        messages: [],
        users: [],
        state: new Api.updates.State({
          pts: 0,
          qts: 0,
          date: 0,
          seq: 0,
          unreadCount: 0,
        }),
      });
    }

    if (request instanceof Api.messages.GetDialogs) {
      if (request.folderId || !(request.offsetPeer instanceof Api.InputPeerEmpty)) {
        return new Api.messages.Dialogs({
          dialogs: [],
          users: [],
          chats: [],
          messages: [],
        });
      }

      return new Api.messages.Dialogs({
        dialogs: this.getDialogs(),
        messages: this.getAllMessages(),
        chats: this.getChatsAndChannels(),
        users: this.getUsers(),
      });
    }
    return undefined;
  }

  public getSender() {
    return new MockSender(this);
  }

