      gl.uniform2f(locations.uniforms.spawnCenter, system.centerX * dpr, system.centerY * dpr);

      // Bind attributes for this system
      gl.bindBuffer(gl.ARRAY_BUFFER, system.buffers.startPosition);
      gl.enableVertexAttribArray(locations.attributes.startPosition);
      gl.vertexAttribPointer(locations.attributes.startPosition, 2, gl.FLOAT, false, 0, 0);

      gl.bindBuffer(gl.ARRAY_BUFFER, system.buffers.velocity);
      gl.enableVertexAttribArray(locations.attributes.velocity);
      gl.vertexAttribPointer(locations.attributes.velocity, 2, gl.FLOAT, false, 0, 0);

      gl.bindBuffer(gl.ARRAY_BUFFER, system.buffers.startTime);
      gl.enableVertexAttribArray(locations.attributes.startTime);
      gl.vertexAttribPointer(locations.attributes.startTime, 1, gl.FLOAT, false, 0, 0);

      gl.bindBuffer(gl.ARRAY_BUFFER, system.buffers.lifetime);
      gl.enableVertexAttribArray(locations.attributes.lifetime);
      gl.vertexAttribPointer(locations.attributes.lifetime, 1, gl.FLOAT, false, 0, 0);

      gl.bindBuffer(gl.ARRAY_BUFFER, system.buffers.size);
      gl.enableVertexAttribArray(locations.attributes.size);
      gl.vertexAttribPointer(locations.attributes.size, 1, gl.FLOAT, false, 0, 0);

      gl.bindBuffer(gl.ARRAY_BUFFER, system.buffers.baseOpacity);
      gl.enableVertexAttribArray(locations.attributes.baseOpacity);
      gl.vertexAttribPointer(locations.attributes.baseOpacity, 1, gl.FLOAT, false, 0, 0);

      gl.bindBuffer(gl.ARRAY_BUFFER, system.buffers.color);
      gl.enableVertexAttribArray(locations.attributes.color);
      gl.vertexAttribPointer(locations.attributes.color, 3, gl.FLOAT, false, 0, 0);

      // Draw particles for this system
      gl.drawArrays(gl.POINTS, 0, system.config.particleCount);
    });

    animationId = requestAnimationFrame(render);
  }

function addSystem(options: Partial<ParticleConfig>) {
    const id = generateUniqueId();
    const config: Required<ParticleConfig> = { ...DEFAULT_CONFIG, ...options };

    const buffers: Buffers = {
      startPosition: gl.createBuffer(),
      velocity: gl.createBuffer(),
      startTime: gl.createBuffer(),
      lifetime: gl.createBuffer(),
      size: gl.createBuffer(),
      baseOpacity: gl.createBuffer(),
      color: gl.createBuffer(),
    };

    const system: ParticleSystem = {
      id,
      config,
      buffers,
      startTime: performance.now(),
      seed: Math.floor(Math.random() * 1000000),
      centerX: config.width / 2 + config.centerShift[0],
      centerY: config.height / 2 + config.centerShift[1],
      avgDistance: (config.width / 2 + config.height / 2) / 2,
    };

    systems.set(id, system);

    initParticleData(system);
    initCanvas();

    if (config.selfDestroyTime) {
      system.selfDestroyTimeout = window.setTimeout(() => {
        removeSystem(id);
      }, config.selfDestroyTime * 1000);
    }

    if (systems.size === 1) {
      initWebGLState();

      unsubscribeFromIsInBackground = getIsInBackground.subscribe(() => {
        const isActive = !getIsInBackground();
        if (isActive && !animationId) {
          animationId = requestAnimationFrame(render);
        } else if (!isActive && animationId) {
          cancelAnimationFrame(animationId);
          animationId = undefined;
        }
      });

      animationId = requestAnimationFrame(render);
    }

    return () => removeSystem(id);
  }

function removeSystem(id: string): void {
    const system = systems.get(id);
    if (!system) return;

    if (system.selfDestroyTimeout) {
      clearTimeout(system.selfDestroyTimeout);
    }

    Object.values(system.buffers).forEach((buffer) => {
      if (buffer) gl.deleteBuffer(buffer);
    });

    systems.delete(id);

    if (systems.size === 0) {
      destroy();
    }
  }

function destroy(): void {
    if (animationId !== undefined) {
      cancelAnimationFrame(animationId);
      animationId = undefined;
    }

    unsubscribeFromIsInBackground?.();

    systems.clear();

    gl.deleteProgram(program);
    gl.deleteShader(vertexShader!);
    gl.deleteShader(fragmentShader!);

    canvasManagers.delete(canvas);
  }

function createShader(gl: WebGLRenderingContext, type: number, source: string): WebGLShader | undefined {
  const shader = gl.createShader(type);
  if (!shader) return undefined;

  gl.shaderSource(shader, source);
  gl.compileShader(shader);

  if (!gl.getShaderParameter(shader, gl.COMPILE_STATUS)) {
    gl.deleteShader(shader);
    return undefined;
  }

  return shader;
}

function createProgram(gl: WebGLRenderingContext,
  vertexShader: WebGLShader,
  fragmentShader: WebGLShader): WebGLProgram | undefined {
  const program = gl.createProgram();
  if (!program) return undefined;

  gl.attachShader(program, vertexShader);
  gl.attachShader(program, fragmentShader);
  gl.linkProgram(program);

  if (!gl.getProgramParameter(program, gl.LINK_STATUS)) {
    gl.deleteProgram(program);
    return undefined;
  }

  return program;
}

class SeededRandom {
  private seed: number;

  constructor(seed: number) {
    this.seed = seed;
  }

  next(): number {
    this.seed = (this.seed * 9301 + 49297) % 233280;
    return this.seed / 233280;
  }

  nextBetween(min: number, max: number): number {
    return min + (max - min) * this.next();
  }
}

constructor(seed: number) {
    this.seed = seed;
  }

next(): number {
    this.seed = (this.seed * 9301 + 49297) % 233280;
    return this.seed / 233280;
  }

nextBetween(min: number, max: number): number {
    return min + (max - min) * this.next();
  }

function getRotations(): Float32Array {
  if (!rotationsCache) {
    const ROTATION_COUNT = 18; // n = [0..17]
    const ROTATION_ANGLE_DEGREES = 220;

    rotationsCache = new Float32Array(ROTATION_COUNT * 4); // mat2 = 4 floats

    for (let i = 0; i < ROTATION_COUNT; i++) {
      const angle = (ROTATION_ANGLE_DEGREES * Math.PI / 180) * i;
      const cos = Math.cos(angle);
      const sin = Math.sin(angle);

      // mat2 in column-major order: [cos, sin, -sin, cos]
      rotationsCache[i * 4] = cos;
      rotationsCache[i * 4 + 1] = sin;
      rotationsCache[i * 4 + 2] = -sin;
      rotationsCache[i * 4 + 3] = cos;
    }
  }

  return rotationsCache;
}

function resolveColor(colorDefinition: Color | ColorPair, rng: SeededRandom): Color {
  if (colorDefinition instanceof Color) return colorDefinition;

  const [color1, color2] = colorDefinition;
  const [red1, green1, blue1] = color1.coords;
  const [red2, green2, blue2] = color2.coords;

  return new Color('srgb', [
    rng.nextBetween(red1 || 0, red2 || 0),
    rng.nextBetween(green1 || 0, green2 || 0),
    rng.nextBetween(blue1 || 0, blue2 || 0),
  ]);
}

function handleError(err: Error) {
  // eslint-disable-next-line no-console
  console.error(err);
  if (DEBUG) {
    throttleError(err);
  }
}

function handleErrorEvent(e: ErrorEvent | PromiseRejectionEvent) {
  if (e instanceof ErrorEvent) {
    // https://stackoverflow.com/questions/49384120/resizeobserver-loop-limit-exceeded
    if (e.message === 'ResizeObserver loop limit exceeded') {
      return;
    }

    // Flood wait errors
    if (e.message.includes('A wait of')) {
      return;
    }
  }

  e.preventDefault();
  handleError(e instanceof ErrorEvent ? (e.error || e.message) : e.reason);
}

function getErrorMessage(err: Error) {
  return `${DEBUG_ALERT_MSG}

${(err?.message) || err}
${err?.stack}`;
}

function processAndUpdateEntities(response?: GramJs.AnyRequest['__response']) {
  if (!response || typeof response !== 'object') return;
  if (!('users' in response || 'chats' in response || 'messages' in response)) return;

  let userById: Record<string, ApiUser> | undefined;
  let chatById: Record<string, ApiChat> | undefined;
  const threadInfos: ApiThreadInfo[] | undefined = [];
  const polls: ApiMessagePoll[] | undefined = [];
  const webPages: ApiWebPage[] | undefined = [];

  if ('users' in response && Array.isArray(response.users) && TYPE_USER.has(response.users[0]?.className)) {
    const users = response.users.map((user: GramJs.TypeUser) => {
      if (user instanceof GramJs.User) {
        addUserToLocalDb(user);
      }
      return buildApiUser(user);
    }).filter(Boolean);
    userById = buildCollectionByKey(users, 'id');
  }

  if ('chats' in response && Array.isArray(response.chats) && TYPE_CHAT.has(response.chats[0]?.className)) {
    const chats = response.chats.map((chat: GramJs.TypeChat) => {
      if (chat instanceof GramJs.Chat || chat instanceof GramJs.Channel || chat instanceof GramJs.Community) {
        addChatToLocalDb(chat);
      }
      return buildApiChatFromPreview(chat);
    }).filter(Boolean);
    chatById = buildCollectionByKey(chats, 'id');
  }

  if ('messages' in response && Array.isArray(response.messages) && TYPE_MESSAGE.has(response.messages[0]?.className)) {
    response.messages.forEach((message: GramJs.TypeMessage) => {
      addMessageToLocalDb(message);

      const threadInfo = buildApiThreadInfoFromMessage(message);
      if (threadInfo) {
        threadInfos.push(threadInfo);
      }

      if ('media' in message && message.media) {
        const poll = buildMessagePollFromMedia(message.media);
        if (poll) {
          polls.push(poll);
        }

        const mediaWebPages = buildWebPagesFromMedia(message.media);
        if (mediaWebPages) {
          webPages.push(...mediaWebPages);
        }
      }
    });
  }

  if (!userById && !chatById && !threadInfos?.length && !polls?.length && !webPages?.length) return;

  sendImmediateApiUpdate({
    '@type': 'updateEntities',
    users: userById,
    chats: chatById,
    threadInfos: threadInfos?.length ? threadInfos : undefined,
    polls: polls?.length ? polls : undefined,
    webPages: webPages?.length ? webPages : undefined,
  });
}

function processMessageAndUpdateThreadInfo(message: GramJs.TypeMessage) {
  addMessageToLocalDb(message);
  const threadInfo = buildApiThreadInfoFromMessage(message);
  if (!threadInfo) return;
  sendImmediateApiUpdate({
    '@type': 'updateThreadInfo',
    threadInfo,
  });
}

function forceReflow(element: HTMLElement) {
  // eslint-disable-next-line @typescript-eslint/no-unused-expressions
  element.offsetWidth;
}

function canVoteInPollAsSubscriber(isRestrictedToSubscribers?: true, isChatNotJoined?: boolean) {
  return !isRestrictedToSubscribers || !isChatNotJoined;
}

function canVoteInPollCountry(phoneCountryIso2?: string, allowedCountryCodes?: string[]) {
  if (!allowedCountryCodes?.length || !phoneCountryIso2) {
    return true;
  }

  const phoneCountryCode = phoneCountryIso2.toUpperCase();

  return allowedCountryCodes.some((countryCode) => countryCode.toUpperCase() === phoneCountryCode);
}

function getPollSubscriberRestrictionMessage(
  channel?: string,
  isRestrictedToSubscribers?: true,
): LangFnParameters | undefined {
  return isRestrictedToSubscribers && channel
    ? {
      key: 'PollSubscriberRestriction',
      variables: { channel },
    }
    : undefined;
}

function getPollCountryRestrictionMessage(
  lang: LangFn,
  countryCodes?: string[],
): LangFnParameters | undefined {
  const countries = getPollCountryRestrictionCountries(lang, countryCodes);

  return countries
    ? {
      key: 'PollCountryRestriction',
      variables: { countries },
      options: { withNodes: true, withMarkdown: true },
    }
    : undefined;
}

function getPollCountryRestrictionCountries(lang: LangFn, countryCodes?: string[]) {
  if (!countryCodes?.length) {
    return undefined;
  }

  const countryNames: string[] = [];

  countryCodes.forEach((countryCode) => {
    const countryName = getCountryName(lang, countryCode);

    if (countryName) {
      countryNames.push(countryName);
    }
  });

  return countryNames.length ? lang.conjunction(countryNames) : undefined;
}

function getCountryName(lang: LangFn, countryCode: string) {
  const normalizedCountryCode = countryCode.toUpperCase();

  return normalizedCountryCode ? lang.region(normalizedCountryCode) || normalizedCountryCode : undefined;
}

function useStickerPickerObservers(
  containerRef: ElementRef<HTMLDivElement>,
  headerRef: ElementRef<HTMLDivElement>,
  idPrefix: string,
  isHidden?: boolean,
) {
  const stickerSetIntersectionsRef = useRef<boolean[]>([]);

  const [activeSetIndex, setActiveSetIndex] = useState<number>(0);

  const {
    observe: observeIntersectionForSet,
    freeze: freezeForSet,
    unfreeze: unfreezeForSet,
  } = useIntersectionObserver({
    rootRef: containerRef,
    throttleMs: STICKER_INTERSECTION_THROTTLE,
  }, (entries) => {
    const stickerSetIntersections = stickerSetIntersectionsRef.current;

    entries.forEach((entry) => {
      const index = Number(entry.target.id.replace(`${idPrefix}-`, ''));
      stickerSetIntersections[index] = entry.isIntersecting;
    });

    if (isAnimatingScroll(containerRef.current)) {
      return;
    }

    const minIntersectingIndex = stickerSetIntersections.reduce((lowestIndex, isIntersecting, index) => {
      return isIntersecting && index < lowestIndex ? index : lowestIndex;
    }, Infinity);

    if (minIntersectingIndex === Infinity) {
      return;
    }

    setActiveSetIndex(minIntersectingIndex);
  });

  const {
    observe: observeIntersectionForShowingItems,
    freeze: freezeForShowingItems,
    unfreeze: unfreezeForShowingItems,
  } = useIntersectionObserver({
    rootRef: containerRef,
    throttleMs: STICKER_INTERSECTION_THROTTLE,
    margin: STICKER_SHOWING_MARGIN,
  });

  const {
    observe: observeIntersectionForPlayingItems,
  } = useIntersectionObserver({
    rootRef: containerRef,
    throttleMs: STICKER_INTERSECTION_THROTTLE,
    margin: STICKER_INTERSECTION_MARGIN,
  });

  const {
    observe: observeIntersectionForCovers,
  } = useIntersectionObserver({
    rootRef: headerRef,
    throttleMs: STICKER_INTERSECTION_THROTTLE,
    margin: COVERS_INTERSECTION_MARGIN,
  });

  useSyncEffect(() => {
    if (isHidden) {
      freezeForSet();
      freezeForShowingItems();
    } else {
      const timeout = window.setTimeout(() => {
        unfreezeForShowingItems();
        unfreezeForSet();
      }, UNFREEZE_DELAY);

      return () => {
        clearTimeout(timeout);
      };
    }
    return undefined;
  }, [freezeForSet, freezeForShowingItems, isHidden, unfreezeForSet, unfreezeForShowingItems]);

  const selectStickerSet = useLastCallback((index: number) => {
    setActiveSetIndex((currentIndex) => {
      const stickerSetEl = document.getElementById(`${idPrefix}-${index}`)!;
      const isClose = Math.abs(currentIndex - index) === 1;

      animateScroll({
        container: containerRef.current!,
        element: stickerSetEl,
        position: 'start',
        margin: FOCUS_MARGIN,
        maxDistance: isClose ? SCROLL_MAX_DISTANCE_WHEN_CLOSE : SCROLL_MAX_DISTANCE_WHEN_FAR,
        noHeavyAnimation: true,
      });

      return index;
    });
  });

  return {
    activeSetIndex,
    observeIntersectionForSet,
    observeIntersectionForShowingItems,
    observeIntersectionForPlayingItems,
    observeIntersectionForCovers,
    selectStickerSet,
  };
}

function concat(...buffers: Uint8Array[]): Uint8Array<ArrayBuffer> {
  const totalLength = buffers.reduce((acc, buffer) => acc + buffer.length, 0);
  const result = new Uint8Array(totalLength);
  let offset = 0;
  for (const buffer of buffers) {
    result.set(buffer, offset);
    offset += buffer.length;
  }
  return result;
}

function copy(buffer: Uint8Array): Uint8Array {
  return new Uint8Array(buffer);
}

function buffersEqual(buffer1: Uint8Array, buffer2: Uint8Array): boolean {
  if (buffer1.length !== buffer2.length) {
    return false;
  }
  for (let i = 0; i < buffer1.length; i++) {
    if (buffer1[i] !== buffer2[i]) {
      return false;
    }
  }
  return true;
}

function compareBuffersConstantTime(buffer1: Uint8Array, buffer2: Uint8Array): boolean {
  if (buffer1.length !== buffer2.length) {
    return false;
  }

  let difference = 0;
  for (let byteIndex = 0; byteIndex < buffer1.length; byteIndex++) {
    difference |= buffer1[byteIndex] ^ buffer2[byteIndex];
  }

  return difference === 0;
}

function readInt32LE(buffer: Uint8Array, offset = 0) {
  checkBounds(buffer, offset, 4);

  return buffer[offset]
    | (buffer[offset + 1] << 8)
    | (buffer[offset + 2] << 16)
    | (buffer[offset + 3] << 24);
}

function readUint32LE(buffer: Uint8Array, offset = 0) {
  checkBounds(buffer, offset, 4);

  return (buffer[offset]
    | (buffer[offset + 1] << 8)
    | (buffer[offset + 2] << 16))
  + buffer[offset + 3] * 0x1000000;
}

function readUint32BE(buffer: Uint8Array, offset = 0) {
  checkBounds(buffer, offset, 4);

  return buffer[offset] * 0x1000000
    + ((buffer[offset + 1] << 16)
      | (buffer[offset + 2] << 8)
      | buffer[offset + 3]);
}

function writeInt32LE(buffer: Uint8Array, value: number, offset = 0) {
  checkBounds(buffer, offset, 4);

  buffer[offset] = value & 0xFF;
  buffer[offset + 1] = value >>> 8;
  buffer[offset + 2] = value >>> 16;
  buffer[offset + 3] = value >>> 24;
}

function writeUint32LE(buffer: Uint8Array, value: number, offset = 0) {
  checkBounds(buffer, offset, 4);

  buffer[offset] = value & 0xFF;
  buffer[offset + 1] = value >>> 8;
  buffer[offset + 2] = value >>> 16;
  buffer[offset + 3] = value >>> 24;
}

function writeUint32BE(buffer: Uint8Array, value: number, offset = 0) {
  checkBounds(buffer, offset, 4);

  buffer[offset] = value >>> 24;
  buffer[offset + 1] = value >>> 16;
  buffer[offset + 2] = value >>> 8;
  buffer[offset + 3] = value & 0xFF;
}

function readBigUint64LE(buffer: Uint8Array, offset = 0) {
  checkBounds(buffer, offset, 8);

  const low = buffer[offset]
    + buffer[offset + 1] * 0x100
    + buffer[offset + 2] * 0x10000
    + buffer[offset + 3] * 0x1000000;
  const high = buffer[offset + 4]
    + buffer[offset + 5] * 0x100
    + buffer[offset + 6] * 0x10000
    + buffer[offset + 7] * 0x1000000;

  return BigInt(low) + (BigInt(high) << 32n);
}

function readBigUint64BE(buffer: Uint8Array, offset = 0) {
  checkBounds(buffer, offset, 8);

  const high = buffer[offset] * 0x1000000
    + buffer[offset + 1] * 0x10000
    + buffer[offset + 2] * 0x100
    + buffer[offset + 3];
  const low = buffer[offset + 4] * 0x1000000
    + buffer[offset + 5] * 0x10000
    + buffer[offset + 6] * 0x100
    + buffer[offset + 7];

  return BigInt(low) + (BigInt(high) << 32n);
}

function writeBigInt64LE(buffer: Uint8Array, value: bigint, offset = 0) {
  checkBounds(buffer, offset, 8);

  const unsignedValue = BigInt.asUintN(64, value);
  const low = Number(unsignedValue & 0xFFFFFFFFn);
  const high = Number((unsignedValue >> 32n) & 0xFFFFFFFFn);

  buffer[offset] = low & 0xFF;
  buffer[offset + 1] = low >>> 8;
  buffer[offset + 2] = low >>> 16;
  buffer[offset + 3] = low >>> 24;
  buffer[offset + 4] = high & 0xFF;
  buffer[offset + 5] = high >>> 8;
  buffer[offset + 6] = high >>> 16;
  buffer[offset + 7] = high >>> 24;
}

function bufferFromHex(hex: string): Uint8Array<ArrayBuffer> {
  if (typeof Uint8Array.fromHex === 'function') {
    return Uint8Array.fromHex(hex);
  }

  if (hex.length % 2 !== 0) {
    throw new SyntaxError('Hex string length must be a multiple of 2');
  }

  const bytes = new Uint8Array(hex.length / 2);
  for (let i = 0; i < bytes.length; i++) {
    const high = HEX_VALUES[hex.charCodeAt(i * 2)] ?? -1;
    const low = HEX_VALUES[hex.charCodeAt(i * 2 + 1)] ?? -1;
    if (high === -1 || low === -1) {
      throw new SyntaxError('Invalid hex character');
    }

    bytes[i] = (high << 4) | low;
  }

  return bytes;
}

function bufferToHex(buffer: Uint8Array): string {
  let hex = '';
  for (let i = 0; i < buffer.length; i++) {
    hex += buffer[i].toString(16).padStart(2, '0');
  }
  return hex;
}

function bufferFromBase64(base64: string): Uint8Array<ArrayBuffer> {
  if (typeof Uint8Array.fromBase64 === 'function') {
    return Uint8Array.fromBase64(base64);
  }

  // TODO: Drop in 2028 when method is Baseline Widely Available
  const paddingLength = base64.length - base64.replace(/=+$/, '').length;
  if (paddingLength > 2) {
    throw new SyntaxError('Invalid base64 padding');
  }

  const normalizedBase64 = base64.slice(0, base64.length - paddingLength);
  const expectedPadding = (4 - (normalizedBase64.length % 4)) % 4;
  if (paddingLength && paddingLength !== expectedPadding) {
    throw new SyntaxError('Invalid base64 padding');
  }
  if (normalizedBase64.length % 4 === 1) {
    throw new SyntaxError('Invalid base64 length');
  }

  const bytes = new Uint8Array(Math.floor((normalizedBase64.length * 3) / 4));
  let byteIndex = 0;
  let buffer = 0;
  let bits = 0;

  for (let i = 0; i < normalizedBase64.length; i++) {
    const char = normalizedBase64[i];
    const value = BASE64_VALUES[normalizedBase64.charCodeAt(i)] ?? -1;
    if (value === -1) {
      throw new SyntaxError(`Invalid base64 character: ${char}`);
    }

    buffer = (buffer << 6) | value;
    bits += 6;

    if (bits >= 8) {
      bits -= 8;
      bytes[byteIndex++] = (buffer >> bits) & 0xFF;
    }
  }

  if (bits && (buffer & ((1 << bits) - 1)) !== 0) {
    throw new SyntaxError('Invalid base64 overflow bits');
  }
  if (byteIndex !== bytes.length) {
    throw new SyntaxError('Invalid base64 partial byte');
  }

  return bytes;
}

function bufferFromUtf8(value: string): Uint8Array<ArrayBuffer> {
  return textEncoder.encode(value);
}

function bufferToUtf8(bytes: Uint8Array): string {
  return textDecoder.decode(bytes);
}

function checkBounds(buffer: Uint8Array, offset: number, byteLength: number) {
  if (!Number.isInteger(offset) || offset < 0 || offset + byteLength > buffer.length) {
    throw new RangeError('Offset is outside the bounds of the buffer');
  }
}

function buildHexValues() {
  const values = new Int8Array(128).fill(-1);

  // Add `0-9`
  for (let charCode = 48; charCode <= 57; charCode++) {
    values[charCode] = charCode - 48;
  }
  // Add `A-F` and `a-f`
  for (let i = 0; i < 6; i++) {
    values[65 + i] = i + 10;
    values[97 + i] = i + 10;
  }
  return values;
}

function buildBase64Values() {
  const values = new Int8Array(128).fill(-1);

  // Add `A-Z`
  for (let charCode = 65; charCode <= 90; charCode++) {
    values[charCode] = charCode - 65;
  }
  // Add `a-z`
  for (let charCode = 97; charCode <= 122; charCode++) {
    values[charCode] = charCode - 97 + 26;
  }
  // Add `0-9`
  for (let charCode = 48; charCode <= 57; charCode++) {
    values[charCode] = charCode - 48 + 52;
  }
  // Add `+` and `/`
  values[43] = 62;
  values[47] = 63;

  return values;
}

function resetInitialLocationHash() {
  isAlreadyParsed = false;
  messageHash = undefined;
  parsedInitialLocationHash = undefined;
  initialLocationHash = '';
}

function resetLocationHash() {
  window.location.hash = '';
}

function parseLocationHash(currentUserId?: string) {
  parseInitialLocationHash();

  if (!messageHash) return undefined;

  const parts = messageHash.split('_');
  let chatId: string | undefined;
  let type: string | undefined;
  let threadId: string | undefined;
  if (parts.length === 1) {
    chatId = parts[0];
  } else if (parts.length === 2) {
    const isType = ['thread', 'pinned', 'scheduled'].includes(parts[1]);
    chatId = parts[0];
    type = isType ? parts[1] : 'thread';
    threadId = !isType ? parts[1] : undefined;
  } else if (parts.length >= 3) {
    [chatId, threadId, type] = parts;
  }
  if (!chatId?.match(/^-?\d+$/)) return undefined;

  const isType = ['thread', 'pinned', 'scheduled'].includes(type!);

  const castedThreadId = (chatId === currentUserId ? threadId : Number(threadId)) || MAIN_THREAD_ID;

  return {
    chatId,
    type: type && isType ? (type as MessageListType) : 'thread',
    threadId: castedThreadId,
  };
}

function parseInitialLocationHash() {
  if (parsedInitialLocationHash) return parsedInitialLocationHash;

  if (isAlreadyParsed) return undefined;

  const locationHash = getInitialLocationHash();
  if (!locationHash) return undefined;

  let parsedHash = locationHash.replace(/^#/, '');
  if (parsedHash.includes('?')) {
    [messageHash, parsedHash] = parsedHash.split('?');
    if (!IS_MOCKED_CLIENT) {
      window.location.hash = messageHash;
    }
  } else if (parsedHash.includes('=')) {
    if (!IS_MOCKED_CLIENT) {
      window.location.hash = '';
    }
  }

  parsedInitialLocationHash = parsedHash.includes('=') ? parsedHash.split('&').reduce((acc, cur) => {
    const [key, value] = cur.split('=');
    acc[key] = value;
    return acc;
  }, {} as Record<string, string>) : undefined;
  isAlreadyParsed = true;
  if (!parsedInitialLocationHash) {
    messageHash = parsedHash;
  }

  return parsedInitialLocationHash;
}

function clearWebTokenAuth() {
  if (!parsedInitialLocationHash) return;

  delete parsedInitialLocationHash.tgWebAuthToken;
}

function getInitialLocationHash() {
  return initialLocationHash;
}

function updater(update: Update) {
  if (update instanceof UpdateServerTimeOffset) {
    setServerTimeOffset(update.timeOffset);

    sendApiUpdate({
      '@type': 'updateServerTimeOffset',
      serverTimeOffset: update.timeOffset,
    });
  } else if (update instanceof UpdateConnectionState) {
    let connectionState: ApiUpdateConnectionStateType;

    switch (update.state) {
      case UpdateConnectionState.disconnected:
        connectionState = 'connectionStateConnecting';
        break;
      case UpdateConnectionState.broken:
        connectionState = 'connectionStateBroken';
        break;
      case UpdateConnectionState.connected:
      default:
        connectionState = 'connectionStateReady';
        break;
    }

    sendApiUpdate({
      '@type': 'updateConnectionState',
      connectionState,
    });

    // Ephemeral messages
  } else if (
    update instanceof GramJs.UpdateNewEphemeralMessage
    || update instanceof GramJs.UpdateEditEphemeralMessage
  ) {
    const ephemeralMessage = update.message;
    const { media, replyMarkup } = ephemeralMessage;
    const message = buildApiEphemeralMessage(ephemeralMessage);
    const webPages = media ? buildWebPagesFromMedia(media) : undefined;
    if (update instanceof GramJs.UpdateNewEphemeralMessage) {
      const shouldForceReply = replyMarkup instanceof GramJs.ReplyKeyboardForceReply
        && !replyMarkup.selective;
      sendApiUpdate({
        '@type': 'newEphemeralMessage',
        message,
        webPages,
        shouldForceReply,
      });
    } else {
      sendApiUpdate({
        '@type': 'updateEphemeralMessage',
        message,
        webPages,
      });
    }
  } else if (update instanceof GramJs.UpdateDeleteEphemeralMessages) {
    sendApiUpdate({
      '@type': 'deleteEphemeralMessages',
      chatId: getApiChatIdFromMtpPeer(update.peer),
      messageIds: update.ids.map(getEphemeralMessageId),
    });
    // Messages
  } else if (
    update instanceof GramJs.UpdateNewMessage
    || update instanceof GramJs.UpdateNewScheduledMessage
    || update instanceof GramJs.UpdateNewChannelMessage
    || update instanceof GramJs.UpdateShortChatMessage
    || update instanceof GramJs.UpdateShortMessage
  ) {
    let message: ApiMessage | undefined;
    let poll: ApiMessagePoll | undefined;
    let webPages: ApiWebPage[] | undefined;
    let shouldForceReply: boolean | undefined;

    if (update instanceof GramJs.UpdateShortChatMessage) {
      message = buildApiMessageFromShortChat(update);
    } else if (update instanceof GramJs.UpdateShortMessage) {
      message = buildApiMessageFromShort(update);
    } else {
      const mtpMessage = update.message;
      // TODO Remove if proven not reproducing
      if (mtpMessage instanceof GramJs.MessageEmpty) {
        if (DEBUG) {
          // eslint-disable-next-line no-console
          console.error('Unexpected update:', update.className, update);
        }

        return;
      }

      processMessageAndUpdateThreadInfo(mtpMessage);

      message = buildApiMessage(mtpMessage)!;

      if (mtpMessage instanceof GramJs.Message && mtpMessage.media) {
        const { media } = mtpMessage;
        poll = buildMessagePollFromMedia(media);
        webPages = buildWebPagesFromMedia(media);
      }

      shouldForceReply = 'replyMarkup' in update.message
        && update.message?.replyMarkup instanceof GramJs.ReplyKeyboardForceReply
        && (!update.message.replyMarkup.selective || message.isMentioned);
    }

    if (update instanceof GramJs.UpdateNewScheduledMessage) {
      sendApiUpdate({
        '@type': 'updateScheduledMessage',
        id: message.id,
        chatId: message.chatId,
        message,
        poll,
        webPages,
        isFromNew: true,
        isFull: true,
      });
    } else {
      sendApiUpdate({
        '@type': 'updateMessage',
        id: message.id,
        chatId: message.chatId,
        message,
        shouldForceReply,
        poll,
        webPages,
        isFromNew: true,
        isFull: true,
      });
    }

    // Some updates to a Chat/Channel don't have a dedicated update class.
    // We can get info on some updates from Service Messages.
    if (update.message instanceof GramJs.MessageService) {
      const { action } = update.message;

      if (action instanceof GramJs.MessageActionChatEditTitle) {
        sendApiUpdate({
          '@type': 'updateChat',
          id: message.chatId,
          chat: {
            title: action.title,
          },
        });
      } else if (action instanceof GramJs.MessageActionChatEditPhoto) {
        const apiPhoto = action.photo instanceof GramJs.Photo && buildApiPhoto(action.photo);
        if (!apiPhoto) return;

        const photo = buildChatPhotoForLocalDb(action.photo);

        const localDbChatId = resolveMessageApiChatId(update.message)!;
        const localDbChat = localDb.chats[localDbChatId];
        if (localDbChat && !(localDbChat instanceof GramJs.CommunityForbidden)) {
          localDbChat.photo = photo;
        }
        addPhotoToLocalDb(action.photo);

        sendApiUpdate({
          '@type': 'updateNewProfilePhoto',
          peerId: message.chatId,
          photo: apiPhoto,
        });
      } else if (action instanceof GramJs.MessageActionChatDeletePhoto) {
        const localDbChatId = resolveMessageApiChatId(update.message)!;
        const localDbChat = localDb.chats[localDbChatId];
        if (localDbChat && !(localDbChat instanceof GramJs.CommunityForbidden)) {
          localDbChat.photo = new GramJs.ChatPhotoEmpty();
        }

        sendApiUpdate({
          '@type': 'updateDeleteProfilePhoto',
          peerId: message.chatId,
        });
      } else if (action instanceof GramJs.MessageActionChangeCommunity) {
        sendApiUpdate({
          '@type': 'updateChat',
          id: message.chatId,
          chat: {
            linkedCommunityId: action.communityId !== undefined
              ? buildApiPeerId(action.communityId, 'channel')
              : undefined,
          },
        });
      } else if (action instanceof GramJs.MessageActionChatDeleteUser) {
        if (update._entities && update._entities.some((e): e is GramJs.User => (
          e instanceof GramJs.User && Boolean(e.self) && e.id === action.userId
        ))) {
          sendApiUpdate({
            '@type': 'updateChat',
            id: message.chatId,
            chat: {
              isForbidden: true,
              isNotJoined: true,
            },
          });
        }
      } else if (action instanceof GramJs.MessageActionChatJoinedByLink) {
        const { fromId } = update.message;
        if (fromId instanceof GramJs.PeerUser && update._entities?.some((e): e is GramJs.User => (
          e instanceof GramJs.User && Boolean(e.self) && e.id === fromId.userId
        ))) {
          sendApiUpdate({
            '@type': 'updateChatJoin',
            id: message.chatId,
          });
        }
      } else if (action instanceof GramJs.MessageActionChatAddUser) {
        if (update._entities && update._entities.some((e): e is GramJs.User => (
          e instanceof GramJs.User && Boolean(e.self) && action.users.includes(e.id)
        ))) {
          sendApiUpdate({
            '@type': 'updateChatJoin',
            id: message.chatId,
          });
        }
      } else if (action instanceof GramJs.MessageActionGroupCall) {
        const groupCall = action.call instanceof GramJs.InputGroupCall ? action.call : undefined;
        if (!action.duration && groupCall) {
          sendApiUpdate({
            '@type': 'updateGroupCallChatId',
            chatId: message.chatId,
            call: {
              id: groupCall.id.toString(),
              accessHash: groupCall.accessHash.toString(),
            },
          });
        }
      } else if (action instanceof GramJs.MessageActionTopicEdit) {
        const replyTo = update.message.replyTo instanceof GramJs.MessageReplyHeader
          ? update.message.replyTo
          : undefined;
        const {
          replyToMsgId, replyToTopId, forumTopic: isTopicReply,
        } = replyTo || {};
        const topicId = !isTopicReply ? GENERAL_TOPIC_ID : replyToTopId || replyToMsgId || GENERAL_TOPIC_ID;

        sendApiUpdate({
          '@type': 'updateTopic',
          chatId: getApiChatIdFromMtpPeer(update.message.peerId),
          topicId,
        });
      } else if (action instanceof GramJs.MessageActionTopicCreate) {
        sendApiUpdate({
          '@type': 'updateTopics',
          chatId: getApiChatIdFromMtpPeer(update.message.peerId),
        });
      }
    }
  } else if (update instanceof GramJs.UpdateQuickReplyMessage) {
    const message = buildApiMessage(update.message);
    if (!message) return;

    const media = update.message instanceof GramJs.Message ? update.message.media : undefined;
    const poll = media ? buildMessagePollFromMedia(media) : undefined;
    const webPages = media ? buildWebPagesFromMedia(media) : undefined;

    sendApiUpdate({
      '@type': 'updateQuickReplyMessage',
      id: message.id,
      message,
      poll,
      webPages,
    });
  } else if (update instanceof GramJs.UpdateDeleteQuickReplyMessages) {
    sendApiUpdate({
      '@type': 'deleteQuickReplyMessages',
      quickReplyId: update.shortcutId,
      messageIds: update.messages,
    });
  } else if (update instanceof GramJs.UpdateQuickReplies) {
    const quickReplies = update.quickReplies.map(buildApiQuickReply);
    sendApiUpdate({
      '@type': 'updateQuickReplies',
      quickReplies,
    });
  } else if (update instanceof GramJs.UpdateNewQuickReply) {
    const quickReply = buildApiQuickReply(update.quickReply);
    sendApiUpdate({
      '@type': 'updateQuickReplies',
      quickReplies: [quickReply],
    });
  } else if (update instanceof GramJs.UpdateDeleteQuickReply) {
    sendApiUpdate({
      '@type': 'deleteQuickReply',
      quickReplyId: update.shortcutId,
    });
  } else if (
    update instanceof GramJs.UpdateEditMessage
    || update instanceof GramJs.UpdateEditChannelMessage
  ) {
    const mtpMessage = update.message;
    // TODO Remove if proven not reproducing
    if (mtpMessage instanceof GramJs.MessageEmpty) {
      if (DEBUG) {
        // eslint-disable-next-line no-console
        console.error('Unexpected update:', update.className, update);
      }

      return;
    }

    processMessageAndUpdateThreadInfo(mtpMessage);

    // Workaround for a weird server behavior when own message is marked as incoming
    const message = omit(buildApiMessage(mtpMessage)!, ['isOutgoing']) as ApiMessage;

    const media = mtpMessage instanceof GramJs.Message ? mtpMessage.media : undefined;
    const poll = media ? buildMessagePollFromMedia(media) : undefined;

    const webPages = media ? buildWebPagesFromMedia(media) : undefined;

    sendApiUpdate({
      '@type': 'updateMessage',
      id: message.id,
      chatId: message.chatId,
      message,
      poll,
      webPages,
      isFull: true,
    });
  } else if (update instanceof GramJs.UpdateMessageReactions) {
    sendApiUpdate({
      '@type': 'updateMessageReactions',
      id: update.msgId,
      threadId: update.topMsgId,
      chatId: getApiChatIdFromMtpPeer(update.peer),
      reactions: buildMessageReactions(update.reactions),
    });
  } else if (update instanceof GramJs.UpdateMessageExtendedMedia) {
    const chatId = getApiChatIdFromMtpPeer(update.peer);
    const isBought = update.extendedMedia[0] instanceof GramJs.MessageExtendedMedia;
    if (isBought) {
      const boughtMedia = buildBoughtMediaContent(update.extendedMedia);

      if (!boughtMedia?.length) return;

      sendApiUpdate({
        '@type': 'updateMessageExtendedMedia',
        id: update.msgId,
        chatId,
        isBought,
        extendedMedia: boughtMedia,
      });
      return;
    }

    const previewMedia = !isBought ? update.extendedMedia
      .filter((m): m is GramJs.MessageExtendedMediaPreview => m instanceof GramJs.MessageExtendedMediaPreview)
      .map((m) => buildApiMessageExtendedMediaPreview(m))
      .filter(Boolean) : undefined;

    if (!previewMedia?.length) return;

    sendApiUpdate({
      '@type': 'updateMessageExtendedMedia',
      id: update.msgId,
      chatId,
      extendedMedia: previewMedia,
    });
  } else if (update instanceof GramJs.UpdateDeleteMessages) {
    sendApiUpdate({
      '@type': 'deleteMessages',
      ids: update.messages,
    });
  } else if (update instanceof GramJs.UpdateDeleteScheduledMessages) {
    sendApiUpdate({
      '@type': 'deleteScheduledMessages',
      ids: update.messages,
      newIds: update.sentMessages,
      chatId: getApiChatIdFromMtpPeer(update.peer),
    });
  } else if (update instanceof GramJs.UpdateDeleteChannelMessages) {
    const chatId = buildApiPeerId(update.channelId, 'channel');

    sendApiUpdate({
      '@type': 'deleteMessages',
      ids: update.messages,
      chatId,
    });
  } else if (update instanceof GramJs.UpdateServiceNotification) {
    if (update.popup) {
      sendApiUpdate({
        '@type': 'error',
        error: {
          message: update.message,
          entities: update.entities.map(buildApiMessageEntity),
        },
      });
    } else {
      const currentDate = Date.now() / 1000 + getServerTimeOffset();
      const message = buildApiMessageFromNotification(update, currentDate);

      processMessageAndUpdateThreadInfo(buildMessageFromUpdate(message.id, message.chatId, update));

      sendApiUpdate({
        '@type': 'updateServiceNotification',
        message,
      });
    }
  } else if (update instanceof GramJs.UpdateReadMessagesContents) {
    sendApiUpdate({
      '@type': 'updateCommonBoxMessages',
      ids: update.messages,
      messageUpdate: {
        hasUnreadMention: false,
        isMediaUnread: false,
      },
    });
  } else if (update instanceof GramJs.UpdateChannelReadMessagesContents) {
    sendApiUpdate({
      '@type': 'updateChannelMessages',
      channelId: buildApiPeerId(update.channelId, 'channel'),
      ids: update.messages,
      messageUpdate: {
        hasUnreadMention: false,
        isMediaUnread: false,
      },
    });
  } else if (update instanceof GramJs.UpdateMessagePoll) {
    const {
      pollId, poll, results, peer, msgId, topMsgId,
    } = update;
    const apiPoll = poll && buildPoll(poll);
    const pollResults = buildPollResults(results);
    const webPages = buildWebPagesFromPoll(poll, results);

    sendApiUpdate({
      '@type': 'updateMessagePoll',
      pollId: pollId.toString(),
      pollUpdate: omitUndefined({ summary: apiPoll, results: pollResults }),
      webPages,
    });

    if (peer && msgId && results.hasUnreadVotes && !results.min) {
      sendApiUpdate({
        '@type': 'updateMessagePollUnread',
        chatId: getApiChatIdFromMtpPeer(peer),
        messageId: msgId,
        threadId: topMsgId || MAIN_THREAD_ID,
        pollId: pollId.toString(),
      });
    }
  } else if (update instanceof GramJs.UpdateMessagePollVote) {
    sendApiUpdate({
      '@type': 'updateMessagePollVote',
      pollId: String(update.pollId),
      peerId: getApiChatIdFromMtpPeer(update.peer),
      options: update.options.map(serializeBytes),
    });
  } else if (update instanceof GramJs.UpdateChannelMessageViews) {
    sendApiUpdate({
      '@type': 'updateMessage',
      chatId: buildApiPeerId(update.channelId, 'channel'),
      id: update.id,
      message: { viewsCount: update.views },
    });
  } else if (update instanceof GramJs.UpdateChannelMessageForwards) {
    sendApiUpdate({
      '@type': 'updateMessage',
      chatId: buildApiPeerId(update.channelId, 'channel'),
      id: update.id,
      message: { forwardsCount: update.forwards },
    });

    // Chats
  } else if (update instanceof GramJs.UpdateReadHistoryInbox) {
    sendApiUpdate({
      '@type': 'updateThreadReadState',
      chatId: getApiChatIdFromMtpPeer(update.peer),
      threadId: update.topMsgId || MAIN_THREAD_ID,
      readState: {
        lastReadInboxMessageId: update.maxId,
        unreadCount: update.stillUnreadCount,
        hasUnreadMark: undefined,
      },
    });
  } else if (update instanceof GramJs.UpdateReadHistoryOutbox) {
    sendApiUpdate({
      '@type': 'updateThreadReadState',
      chatId: getApiChatIdFromMtpPeer(update.peer),
      threadId: MAIN_THREAD_ID,
      readState: {
        lastReadOutboxMessageId: update.maxId,
      },
    });
  } else if (update instanceof GramJs.UpdateReadChannelInbox) {
    sendApiUpdate({
      '@type': 'updateThreadReadState',
      chatId: buildApiPeerId(update.channelId, 'channel'),
      threadId: MAIN_THREAD_ID,
      readState: {
        lastReadInboxMessageId: update.maxId,
        unreadCount: update.stillUnreadCount,
        hasUnreadMark: undefined,
      },
    });
  } else if (update instanceof GramJs.UpdateReadChannelOutbox) {
    sendApiUpdate({
      '@type': 'updateThreadReadState',
      chatId: buildApiPeerId(update.channelId, 'channel'),
      threadId: MAIN_THREAD_ID,
      readState: {
        lastReadOutboxMessageId: update.maxId,
      },
    });
  } else if (update instanceof GramJs.UpdateReadChannelDiscussionInbox) {
    sendApiUpdate({
      '@type': 'updateThreadReadState',
      chatId: buildApiPeerId(update.channelId, 'channel'),
      threadId: update.topMsgId,
      readState: {
        lastReadInboxMessageId: update.readMaxId,
      },
    });
  } else if (update instanceof GramJs.UpdateReadChannelDiscussionOutbox) {
    sendApiUpdate({
      '@type': 'updateThreadReadState',
      chatId: buildApiPeerId(update.channelId, 'channel'),
      threadId: update.topMsgId,
      readState: {
        lastReadOutboxMessageId: update.readMaxId,
      },
    });
  } else if (
    update instanceof GramJs.UpdateDialogPinned
    && isChatDialogPeer(update.peer)
  ) {
    sendApiUpdate({
      '@type': 'updateChatPinned',
      id: getApiChatIdFromDialogPeer(update.peer),
      isPinned: update.pinned || false,
    });
  } else if (update instanceof GramJs.UpdatePinnedDialogs) {
    const ids = update.order?.filter(isChatDialogPeer).map(getApiChatIdFromDialogPeer);

    sendApiUpdate({
      '@type': 'updatePinnedChatIds',
      ids,
      folderId: update.folderId || undefined,
    });
  } else if (
    update instanceof GramJs.UpdateSavedDialogPinned
    && update.peer instanceof GramJs.DialogPeer
  ) {
    sendApiUpdate({
      '@type': 'updateSavedDialogPinned',
      id: getApiChatIdFromMtpPeer(update.peer.peer),
      isPinned: update.pinned || false,
    });
  } else if (update instanceof GramJs.UpdatePinnedSavedDialogs) {
    const ids = update.order
      ? update.order
        .filter((dp): dp is GramJs.DialogPeer => dp instanceof GramJs.DialogPeer)
        .map((dp) => getApiChatIdFromMtpPeer(dp.peer))
      : [];

    sendApiUpdate({
      '@type': 'updatePinnedSavedDialogIds',
      ids,
    });
  } else if (update instanceof GramJs.UpdateFolderPeers) {
    update.folderPeers.forEach((folderPeer) => {
      const { folderId, peer } = folderPeer;

      sendApiUpdate({
        '@type': 'updateChatListType',
        id: getApiChatIdFromMtpPeer(peer),
        folderId,
      });
    });
  } else if (update instanceof GramJs.UpdateDialogFilter) {
    const { id, filter } = update;
    const folder = isChatFolder(filter) ? buildApiChatFolder(filter) : undefined;

    sendApiUpdate({
      '@type': 'updateChatFolder',
      id,
      folder,
    });
  } else if (update instanceof GramJs.UpdateDialogFilterOrder) {
    sendApiUpdate({
      '@type': 'updateChatFoldersOrder',
      orderedIds: update.order,
    });
  } else if (update instanceof GramJs.UpdateChatParticipants) {
    const replacedMembers = buildChatMembers(update.participants);

    sendApiUpdate({
      '@type': 'updateChatMembers',
      id: buildApiPeerId(update.participants.chatId, 'chat'),
      replacedMembers,
    });
  } else if (update instanceof GramJs.UpdateChatParticipantAdd) {
    const addedMember = buildChatMember(
      pick(update, ['userId', 'inviterId', 'date']) as GramJs.ChatParticipant,
    );

    sendApiUpdate({
      '@type': 'updateChatMembers',
      id: buildApiPeerId(update.chatId, 'chat'),
      addedMember,
    });
  } else if (update instanceof GramJs.UpdateChatParticipantDelete) {
    sendApiUpdate({
      '@type': 'updateChatMembers',
      id: buildApiPeerId(update.chatId, 'chat'),
      deletedMemberId: buildApiPeerId(update.userId, 'user'),
    });
  } else if (update instanceof GramJs.UpdateChatParticipantRank) {
    sendApiUpdate({
      '@type': 'updateChatParticipantRank',
      id: buildApiPeerId(update.chatId, 'chat'),
      userId: buildApiPeerId(update.userId, 'user'),
      rank: update.rank,
    });
  } else if (
    update instanceof GramJs.UpdatePinnedMessages
    || update instanceof GramJs.UpdatePinnedChannelMessages
  ) {
    const chatId = update instanceof GramJs.UpdatePinnedMessages
      ? getApiChatIdFromMtpPeer(update.peer)
      : buildApiPeerId(update.channelId, 'channel');

    sendApiUpdate({
      '@type': 'updatePinnedIds',
      chatId,
      messageIds: update.messages,
      isPinned: update.pinned,
    });
  } else if (
    update instanceof GramJs.UpdateUserTyping
    || update instanceof GramJs.UpdateChatUserTyping
  ) {
    const chatId = update instanceof GramJs.UpdateUserTyping
      ? buildApiPeerId(update.userId, 'user')
      : buildApiPeerId(update.chatId, 'chat');
    const peerId = update instanceof GramJs.UpdateUserTyping
      ? buildApiPeerId(update.userId, 'user')
      : getApiChatIdFromMtpPeer(update.fromId);

    const threadId = update instanceof GramJs.UpdateUserTyping ? update.topMsgId : undefined;

    if (update.action instanceof GramJs.SendMessageEmojiInteraction) {
      sendApiUpdate({
        '@type': 'updateStartEmojiInteraction',
        id: chatId,
        emoji: update.action.emoticon,
        messageId: update.action.msgId,
        interaction: buildApiEmojiInteraction(JSON.parse(update.action.interaction.data)),
      });
    } else if (update.action instanceof GramJs.SendMessageTextDraftAction) {
      sendApiUpdate({
        '@type': 'updateChatTypingDraft',
        chatId,
        id: update.action.randomId.toString(),
        threadId,
        text: buildApiFormattedText(update.action.text),
      });
    } else if (update.action instanceof GramJs.SendMessageRichMessageDraftAction) {
      const richMessage = buildApiRichMessage(update.action.richMessage);
      if (!richMessage) {
        return;
      }

      sendApiUpdate({
        '@type': 'updateChatTypingDraft',
        chatId,
        id: update.action.randomId.toString(),
        threadId,
        richMessage,
      });
    } else {
      sendApiUpdate({
        '@type': 'updateChatTypingStatus',
        id: chatId,
        peerId,
        threadId,
        typingStatus: buildChatTypingStatus(update),
      });
    }
  } else if (update instanceof GramJs.UpdateChannelUserTyping) {
    const id = buildApiPeerId(update.channelId, 'channel');
    const peerId = getApiChatIdFromMtpPeer(update.fromId);

    sendApiUpdate({
      '@type': 'updateChatTypingStatus',
      id,
      peerId,
      threadId: update.topMsgId,
      typingStatus: buildChatTypingStatus(update),
    });
  } else if (update instanceof GramJs.UpdateChannel) {
    const { _entities } = update;
    if (!_entities) {
      return;
    }

    const channel = _entities.find((e): e is GramJs.Channel | GramJs.ChannelForbidden => (
      e instanceof GramJs.Channel || e instanceof GramJs.ChannelForbidden
    ));

    if (channel instanceof GramJs.Channel) {
      const chat = buildApiChatFromPreview(channel);
      if (chat) {
        sendApiUpdate({
          '@type': 'updateChat',
          id: chat.id,
          chat,
        });

        sendApiUpdate({
          '@type': chat.isNotJoined ? 'updateChatLeave' : 'updateChatJoin',
          id: buildApiPeerId(update.channelId, 'channel'),
        });
      }
    } else if (channel instanceof GramJs.ChannelForbidden) {
      const chatId = buildApiPeerId(update.channelId, 'channel');

      sendApiUpdate({
        '@type': 'updateChat',
        id: chatId,
        chat: {
          isRestricted: true,
        },
      });

      sendApiUpdate({
        '@type': 'updateChatLeave',
        id: chatId,
      });
    } else if (_entities.length === 0) {
      // The link to the discussion group may have been changed.
      // No corresponding update available at this moment https://core.telegram.org/type/Updates
      sendApiUpdate({
        '@type': 'resetMessages',
        id: buildApiPeerId(update.channelId, 'channel'),
      });
    }
  } else if (
    update instanceof GramJs.UpdateDialogUnreadMark
    && update.peer instanceof GramJs.DialogPeer
  ) {
    sendApiUpdate({
      '@type': 'updateThreadReadState',
      chatId: getApiChatIdFromMtpPeer(update.peer.peer),
      threadId: MAIN_THREAD_ID,
      readState: {
        hasUnreadMark: update.unread,
      },
    });
  } else if (update instanceof GramJs.UpdateChatDefaultBannedRights) {
    sendApiUpdate({
      '@type': 'updateChat',
      id: getApiChatIdFromMtpPeer(update.peer),
      chat: {
        defaultBannedRights: omitVirtualClassFields(update.defaultBannedRights),
      },
    });

    // Users
  } else if (update instanceof GramJs.UpdateUserStatus) {
    sendApiUpdate({
      '@type': 'updateUserStatus',
      userId: buildApiPeerId(update.userId, 'user'),
      status: buildApiUserStatus(update.status),
    });
  } else if (update instanceof GramJs.UpdateUser) {
    sendApiUpdate({
      '@type': 'updateRequestUserUpdate',
      id: buildApiPeerId(update.userId, 'user'),
    });
  } else if (update instanceof GramJs.UpdateUserEmojiStatus) {
    const emojiStatus = buildApiEmojiStatus(update.emojiStatus);
    sendApiUpdate({
      '@type': 'updateUserEmojiStatus',
      userId: buildApiPeerId(update.userId, 'user'),
      emojiStatus,
    });
  } else if (update instanceof GramJs.UpdateUserName) {
    const apiUserId = buildApiPeerId(update.userId, 'user');
    const updatedUser = localDb.users[apiUserId];

    const user = updatedUser?.mutualContact && !updatedUser.self
      ? pick(update, [])
      : pick(update, ['firstName', 'lastName']);

    const usernames = buildApiUsernames(update);

    sendApiUpdate({
      '@type': 'updateUser',
      id: apiUserId,
      user: {
        ...user,
        usernames,
      },
    });
  } else if (update instanceof GramJs.UpdateUserPhone) {
    const { userId, phone } = update;

    sendApiUpdate({
      '@type': 'updateUser',
      id: buildApiPeerId(userId, 'user'),
      user: { phoneNumber: phone },
    });
  } else if (update instanceof GramJs.UpdatePeerSettings) {
    const { peer, settings } = update;
    const peerId = getApiChatIdFromMtpPeer(peer);
    const apiSettings = buildApiPeerSettings(settings);
    sendApiUpdate({
      '@type': 'updatePeerSettings',
      id: peerId,
      settings: apiSettings,
    });
  } else if (update instanceof GramJs.UpdatePeerHistoryTTL) {
    const { peer, ttlPeriod } = update;
    sendApiUpdate({
      '@type': 'updatePeerHistoryTtl',
      id: getApiChatIdFromMtpPeer(peer),
      ttlPeriod,
    });
  } else if (update instanceof GramJs.UpdateNotifySettings) {
    const {
      notifySettings,
      peer: notifyPeer,
    } = update;
    const className = notifyPeer.className;
    const settings = buildApiPeerNotifySettings(notifySettings);

    if (notifyPeer instanceof GramJs.NotifyPeer || notifyPeer instanceof GramJs.NotifyCommunity) {
      const peerId = notifyPeer instanceof GramJs.NotifyCommunity
        ? buildApiPeerId(notifyPeer.communityId, 'channel')
        : getApiChatIdFromMtpPeer(notifyPeer.peer);
      if (settings.mutedUntil) {
        scheduleMutedChatUpdate(peerId, settings.mutedUntil, sendApiUpdate);
      }
      sendApiUpdate({
        '@type': 'updateChatNotifySettings',
        chatId: peerId,
        settings,
      });
      return;
    }

    if (notifyPeer instanceof GramJs.NotifyForumTopic) {
      const peerId = getApiChatIdFromMtpPeer(notifyPeer.peer);
      if (settings.mutedUntil) {
        scheduleMutedTopicUpdate(peerId, notifyPeer.topMsgId, settings.mutedUntil, sendApiUpdate);
      }
      sendApiUpdate({
        '@type': 'updateTopicNotifySettings',
        chatId: peerId,
        topicId: notifyPeer.topMsgId,
        settings,
      });
      return;
    }

    const peerType = className === 'NotifyUsers'
      ? 'users'
      : (className === 'NotifyChats'
        ? 'groups'
        : (className === 'NotifyBroadcasts'
          ? 'channels'
          : undefined
        )
      );

    if (!peerType) {
      return;
    }

    sendApiUpdate({
      '@type': 'updateDefaultNotifySettings',
      peerType,
      settings,
    });
  } else if (update instanceof GramJs.UpdatePeerBlocked) {
    sendApiUpdate({
      '@type': 'updatePeerBlocked',
      id: getApiChatIdFromMtpPeer(update.peerId),
      isBlocked: update.blocked,
      isBlockedFromStories: update.blockedMyStoriesFrom,
    });
  } else if (update instanceof GramJs.UpdatePrivacy) {
    const key = buildPrivacyKey(update.key);
    if (key) {
      sendApiUpdate({
        '@type': 'updatePrivacy',
        key,
        rules: buildPrivacyRules(update.rules),
      });
    }

    // Misc
  } else if (update instanceof GramJs.UpdateDraftMessage) {
    sendApiUpdate({
      '@type': 'draftMessage',
      chatId: getApiChatIdFromMtpPeer(update.peer),
      threadId: update.topMsgId,
      draft: buildMessageDraft(update.draft),
    });
  } else if (update instanceof GramJs.UpdateContactsReset) {
    sendApiUpdate({ '@type': 'updateResetContactList' });
  } else if (update instanceof GramJs.UpdateFavedStickers) {
    sendApiUpdate({ '@type': 'updateFavoriteStickers' });
  } else if (update instanceof GramJs.UpdateRecentStickers) {
    sendApiUpdate({ '@type': 'updateRecentStickers' });
  } else if (update instanceof GramJs.UpdateRecentReactions) {
    sendApiUpdate({ '@type': 'updateRecentReactions' });
  } else if (update instanceof GramJs.UpdateSavedReactionTags) {
    sendApiUpdate({ '@type': 'updateSavedReactionTags' });
  } else if (update instanceof GramJs.UpdateMoveStickerSetToTop) {
    if (!update.masks) {
      sendApiUpdate({
        '@type': 'updateMoveStickerSetToTop',
        isCustomEmoji: update.emojis,
        id: update.stickerset.toString(),
      });
    }
  } else if (update instanceof GramJs.UpdateStickerSets) {
    sendApiUpdate({ '@type': 'updateStickerSets' });
  } else if (update instanceof GramJs.UpdateStickerSetsOrder) {
    if (!update.masks) {
      sendApiUpdate({
        '@type': 'updateStickerSetsOrder',
        order: update.order.map((n) => n.toString()),
        isCustomEmoji: update.emojis,
      });
    }
  } else if (update instanceof GramJs.UpdateNewStickerSet) {
    if (update.stickerset instanceof GramJs.messages.StickerSet) {
      const stickerSet = buildStickerSet(update.stickerset.set);
      sendApiUpdate({
        '@type': 'updateStickerSet',
        id: stickerSet.id,
        stickerSet,
      });
    }
  } else if (update instanceof GramJs.UpdateSavedGifs) {
    sendApiUpdate({ '@type': 'updateSavedGifs' });
  } else if (update instanceof GramJs.UpdateGroupCall) {
    sendApiUpdate({
      '@type': 'updateGroupCall',
      call: buildApiGroupCall(update.call),
    });
  } else if (update instanceof GramJs.UpdateGroupCallConnection) {
    sendApiUpdate({
      '@type': 'updateGroupCallConnection',
      data: JSON.parse(update.params.data) as GroupCallConnectionData,
      presentation: Boolean(update.presentation),
    });
  } else if (update instanceof GramJs.UpdateGroupCallParticipants) {
    const groupCallId = getGroupCallId(update.call);
    if (groupCallId) {
      sendApiUpdate({
        '@type': 'updateGroupCallParticipants',
        groupCallId,
        participants: update.participants.map(buildApiGroupCallParticipant),
      });
    }
  } else if (update instanceof GramJs.UpdatePendingJoinRequests) {
    sendApiUpdate({
      '@type': 'updatePendingJoinRequests',
      chatId: getApiChatIdFromMtpPeer(update.peer),
      recentRequesterIds: update.recentRequesters.map((id) => buildApiPeerId(id, 'user')),
      requestsPending: update.requestsPending,
    });
  } else if (update instanceof GramJs.UpdatePhoneCall) {
    sendApiUpdate({
      '@type': 'updatePhoneCall',
      call: buildPhoneCall(update.phoneCall),
    });
  } else if (update instanceof GramJs.UpdatePhoneCallSignalingData) {
    sendApiUpdate({
      '@type': 'updatePhoneCallSignalingData',
      callId: update.phoneCallId.toString(),
      data: Array.from(update.data),
    });
  } else if (update instanceof GramJs.UpdateWebViewResultSent) {
    const { queryId } = update;

    sendApiUpdate({
      '@type': 'updateWebViewResultSent',
      queryId: queryId.toString(),
    });
  } else if (update instanceof GramJs.UpdateJoinChatWebViewDecision) {
    sendApiUpdate({
      '@type': 'updateJoinChatWebViewDecision',
      peerId: getApiChatIdFromMtpPeer(update.peer),
      queryId: update.queryId.toString(),
      result: buildApiJoinChatBotResult(update.result),
    });
  } else if (update instanceof GramJs.UpdateWebPage || update instanceof GramJs.UpdateChannelWebPage) {
    const webPage = buildWebPage(update.webpage);
    if (webPage) {
      sendApiUpdate({
        '@type': 'updateWebPage',
        webPage,
      });
    }
  } else if (update instanceof GramJs.UpdateBotMenuButton) {
    const {
      botId,
      button,
    } = update;

    const id = buildApiPeerId(botId, 'user');

    sendApiUpdate({
      '@type': 'updateBotMenuButton',
      botId: id,
      button: buildApiBotMenuButton(button),
    });
  } else if (update instanceof GramJs.UpdateBotCommands) {
    const {
      peer,
      botId,
      commands,
    } = update;

    const id = buildApiPeerId(botId, 'user');
    const commandsArray = commands.map((command) => buildApiBotCommand(id, command));
    sendApiUpdate({
      '@type': 'updateBotCommands',
      peerId: getApiChatIdFromMtpPeer(peer),
      botId: id,
      commands: commandsArray.length ? commandsArray : undefined,
    });
  } else if (update instanceof GramJs.UpdateTranscribedAudio) {
    sendApiUpdate({
      '@type': 'updateTranscribedAudio',
      transcriptionId: update.transcriptionId.toString(),
      text: update.text,
      isPending: update.pending,
    });
  } else if (update instanceof GramJs.UpdateConfig) {
    sendApiUpdate({ '@type': 'updateConfig' });
  } else if (update instanceof GramJs.UpdateAiComposeTones) {
    sendApiUpdate({ '@type': 'updateAiComposeTones' });
  } else if (update instanceof GramJs.UpdatePinnedForumTopic) {
    sendApiUpdate({
      '@type': 'updatePinnedTopic',
      chatId: getApiChatIdFromMtpPeer(update.peer),
      topicId: update.topicId,
      isPinned: Boolean(update.pinned),
    });
  } else if (update instanceof GramJs.UpdatePinnedForumTopics) {
    sendApiUpdate({
      '@type': 'updatePinnedTopicsOrder',
      chatId: getApiChatIdFromMtpPeer(update.peer),
      order: update.order || [],
    });
  } else if (update instanceof GramJs.UpdateRecentEmojiStatuses) {
    sendApiUpdate({ '@type': 'updateRecentEmojiStatuses' });
  } else if (update instanceof GramJs.UpdateStory) {
    const { story } = update;
    const peerId = getApiChatIdFromMtpPeer(update.peer);
    const apiStory = buildApiStory(peerId, story) as ApiStory | ApiStorySkipped;
    addStoryToLocalDb(story, peerId); // Add after building to prevent repair info overwrite

    if (story instanceof GramJs.StoryItemDeleted) {
      sendApiUpdate({
        '@type': 'deleteStory',
        peerId,
        storyId: story.id,
      });
    } else {
      sendApiUpdate({
        '@type': 'updateStory',
        peerId,
        story: apiStory,
      });
    }
  } else if (update instanceof GramJs.UpdateReadStories) {
    sendApiUpdate({
      '@type': 'updateReadStories',
      peerId: getApiChatIdFromMtpPeer(update.peer),
      lastReadId: update.maxId,
    });
  } else if (update instanceof GramJs.UpdateSentStoryReaction) {
    const reaction = buildApiReaction(update.reaction);
    sendApiUpdate({
      '@type': 'updateSentStoryReaction',
      peerId: getApiChatIdFromMtpPeer(update.peer),
      storyId: update.storyId,
      reaction,
    });
  } else if (update instanceof GramJs.UpdateStoriesStealthMode) {
    sendApiUpdate({
      '@type': 'updateStealthMode',
      stealthMode: buildApiStealthMode(update.stealthMode),
    });
  } else if (update instanceof GramJs.UpdateAttachMenuBots) {
    sendApiUpdate({
      '@type': 'updateAttachMenuBots',
    });
  } else if (update instanceof GramJs.UpdateNewAuthorization) {
    sendApiUpdate({
      '@type': 'updateNewAuthorization',
      hash: update.hash.toString(),
      date: update.date,
      device: update.device,
      location: update.location,
      isUnconfirmed: update.unconfirmed,
    });
  } else if (update instanceof GramJs.UpdateChannelViewForumAsMessages) {
    sendApiUpdate({
      '@type': 'updateViewForumAsMessages',
      chatId: buildApiPeerId(update.channelId, 'channel'),
      isEnabled: update.enabled ? true : undefined,
    });
  } else if (update instanceof GramJs.UpdateStarsBalance) {
    const balance = buildApiCurrencyAmount(update.balance);
    if (!balance) {
      return;
    }
    sendApiUpdate({
      '@type': 'updateStarsBalance',
      balance,
    });
  } else if (update instanceof GramJs.UpdateStarGiftAuctionState) {
    const state = buildApiTypeStarGiftAuctionState(update.state);
    if (!state) {
      return;
    }
    sendApiUpdate({
      '@type': 'updateStarGiftAuctionState',
      giftId: update.giftId.toString(),
      state,
    });
  } else if (update instanceof GramJs.UpdateStarGiftAuctionUserState) {
    sendApiUpdate({
      '@type': 'updateStarGiftAuctionUserState',
      giftId: update.giftId.toString(),
      userState: buildApiStarGiftAuctionUserState(update.userState),
    });
  } else if (update instanceof GramJs.UpdateStarGiftCraftFail) {
    sendApiUpdate({
      '@type': 'updateStarGiftCraftFail',
    });
  } else if (update instanceof GramJs.UpdatePaidReactionPrivacy) {
    sendApiUpdate({
      '@type': 'updatePaidReactionPrivacy',
      private: buildApiPaidReactionPrivacy(update.private),
    });
  } else if (update instanceof GramJs.UpdateLangPackTooLong) {
    sendApiUpdate({
      '@type': 'updateLangPackTooLong',
      langCode: update.langCode,
    });
  } else if (update instanceof GramJs.UpdateLangPack) {
    const { strings, keysToRemove } = buildLangStrings(update.difference.strings);
    sendApiUpdate({
      '@type': 'updateLangPack',
      version: update.difference.version,
      strings,
      keysToRemove,
    });
  } else if (update instanceof LocalUpdatePremiumFloodWait) { // Local updates
    sendApiUpdate({
      '@type': 'updatePremiumFloodWait',
      isUpload: update.isUpload,
    });
  } else if (update instanceof LocalUpdatePts || update instanceof LocalUpdateChannelPts) {
    // Do nothing, handled on the manager side
  } else if (update instanceof GramJs.UpdateMessageID || update instanceof GramJs.UpdateShortSentMessage) {
    // Do nothing, handled when sending the message
  } else if (DEBUG) {
    const params = typeof update === 'object' && 'className' in update ? update.className : update;
    log('UNEXPECTED UPDATE', params);
  }
}

function isChatDialogPeer(
  dialogPeer: GramJs.TypeDialogPeer,
): dialogPeer is GramJs.DialogPeer | GramJs.DialogPeerCommunity {
