interface TwoFaParams {
  isCheckPassword?: boolean;
  currentPassword?: string;
  newPassword?: string;
  hint?: string;
  email?: string;
  emailCodeCallback?: (length: number) => Promise<string>;
  onEmailCodeError?: (err: Error) => void;
}

async function updateTwoFaSettings(
  client: TelegramClient,
  {
    isCheckPassword,
    currentPassword,
    newPassword,
    hint = '',
    email,
    emailCodeCallback,
    onEmailCodeError,
  }: TwoFaParams,
) {
  if (!newPassword && !currentPassword) {
    throw new Error('Neither `currentPassword` nor `newPassword` is present');
  }

  if (email && !(emailCodeCallback && onEmailCodeError)) {
    throw new Error('`email` present without `emailCodeCallback` and `onEmailCodeError`');
  }

  const pwd = await client.invoke(new Api.account.GetPassword());

  const newAlgo = pwd.newAlgo;

  if (newAlgo instanceof Api.PasswordKdfAlgoUnknown) {
    throw new Error('Password algorithm is unknown');
  }

  newAlgo.salt1 = concat(newAlgo.salt1, generateRandomBytes(32));
  if (!pwd.hasPassword && currentPassword) {
    currentPassword = undefined;
  }

  const password = currentPassword ? await computeCheck(pwd, currentPassword) : new Api.InputCheckPasswordEmpty();

  if (isCheckPassword) {
    await client.invoke(new Api.auth.CheckPassword({ password }));
    return;
  }

  try {
    await client.invoke(new Api.account.UpdatePasswordSettings({
      password,
      newSettings: new Api.account.PasswordInputSettings({
        newAlgo,
        newPasswordHash: newPassword ? await computeDigest(newAlgo, newPassword) : new Uint8Array(0),
        hint,
        email,
        // not explained what it does and it seems to always be set to empty in tdesktop
        newSecureSettings: undefined,
      }),
    }));
  } catch (e) {
    if (e instanceof EmailUnconfirmedError) {
      while (true) {
        try {
          const code = await emailCodeCallback!(e.codeLength);

          if (!code) {
            throw new Error('Code is empty', { cause: e });
          }

          await client.invoke(new Api.account.ConfirmPasswordEmail({ code }));
          break;
        } catch (err: any) {
          onEmailCodeError!(err);
        }
      }
    } else {
      throw e;
    }
  }
}

async function getTmpPassword(client: TelegramClient, currentPassword: string, ttl = 60) {
  const pwd = await client.invoke(new Api.account.GetPassword());

  if (!pwd) {
    return undefined;
  }

  const inputPassword = await computeCheck(pwd, currentPassword);
  const result = await client.invoke(new Api.account.GetTmpPassword({
    password: inputPassword,
    period: ttl,
  }));

  return result;
}

async function getCurrentPassword(
  client: TelegramClient,
  currentPassword?: string,
): Promise<PasswordResult> {
  const pwd = await client.invoke(new Api.account.GetPassword());

  if (!pwd) {
    return undefined;
  }

  return currentPassword ? await computeCheck(pwd, currentPassword) : new Api.InputCheckPasswordEmpty();
}

function useScrollToActiveTab(
  containerRef: ElementRef<HTMLDivElement>,
  activeTab: number,
) {
  useEffect(() => {
    const container = containerRef.current;
    if (!container) return;

    const { scrollWidth, offsetWidth, scrollLeft } = container;
    if (scrollWidth <= offsetWidth) return;

    const activeTabElement = container.childNodes[activeTab] as HTMLElement | undefined;
    if (!activeTabElement) return;

    const { offsetLeft, offsetWidth: tabWidth } = activeTabElement;
    const newLeft = offsetLeft - (offsetWidth / 2) + (tabWidth / 2);

    if (Math.abs(newLeft - scrollLeft) < TAB_SCROLL_THRESHOLD_PX) return;

    animateHorizontalScroll(container, newLeft, SCROLL_DURATION);
  }, [activeTab, containerRef]);
}

async function init() {
  if (await checkIsNativeRecorderUsable()) {
    return undefined;
  }

  return initFallback();
}

async function start(onPeak: (peak: number) => void): Promise<ActiveRecording> {
  return (await checkIsNativeRecorderUsable()) ? startNative(onPeak) : startFallback(onPeak);
}

function initFallback() {
  fallbackInitPromise ??= (async () => {
    try {
      const { default: OpusRecorder } = await import('opus-recorder');
      const encoderPath = (await import('opus-recorder/dist/encoderWorker.min.js?url')).default;
      opusMediaRecorder = new OpusRecorder({ encoderPath, reuseWorker: true });
    } catch (err) {
      // Drop failed initialization so the next attempt can retry
      fallbackInitPromise = undefined;
      throw err;
    }
  })();

  return fallbackInitPromise;
}

async function startNative(onPeak: (peak: number) => void): Promise<ActiveRecording> {
  const recorder = new NativeVoiceRecorder();
  const analyser = new WaveformAnalyser();
  analyser.onPeak = onPeak;
  recorder.onSamples = (samples) => analyser.pushSamples(samples);

  await recorder.start();

  const timekeeper = createTimekeeper();

  return {
    stop: async (shouldSkipMinTime?: boolean) => {
      if (!shouldSkipMinTime) {
        await waitForMinRecordingTime(timekeeper.getElapsedMs());
      }
      const ogg = await recorder.stop();
      if (!ogg.length) {
        throw new Error('Voice recording produced no data');
      }
      return {
        blob: new Blob([ogg.buffer as ArrayBuffer], BLOB_PARAMS),
        duration: Math.max(1, Math.round(timekeeper.getElapsedMs() / 1000)),
        waveform: Array.from(analyser.finish()),
      };
    },
    pause: async () => {
      if (timekeeper.getIsPaused()) return;
      timekeeper.pause();
      await recorder.pause();
    },
    resume: () => {
      if (!timekeeper.getIsPaused()) return;
      timekeeper.resume();
      recorder.resume();
    },
    getSnapshot: () => recorder.getSnapshot(),
    getElapsedMs: timekeeper.getElapsedMs,
    getProfilePeaks: () => analyser.getCurrentPeaks(),
  };
}

async function startFallback(onPeak: (peak: number) => void): Promise<ActiveRecording> {
  await initFallback();
  await opusMediaRecorder.start();

  const analyser = new WaveformAnalyser();
  analyser.onPeak = onPeak;

  const chunks: Uint8Array<ArrayBuffer>[] = [];
  opusMediaRecorder.ondataavailable = (typedArray) => {
    chunks.push(typedArray);
  };

  const timekeeper = createTimekeeper();

  const source = opusMediaRecorder.sourceNode;
  const scriptProcessor = source.context.createScriptProcessor(FALLBACK_TAP_BUFFER_SIZE, 1, 1);
  scriptProcessor.onaudioprocess = (e) => {
    if (timekeeper.getIsPaused()) return;
    analyser.pushSamples(e.inputBuffer.getChannelData(0));
  };
  source.connect(scriptProcessor);
  scriptProcessor.connect(source.context.destination);

  function releaseTap() {
    scriptProcessor.onaudioprocess = undefined as unknown as typeof scriptProcessor.onaudioprocess;
    try {
      source.disconnect(scriptProcessor);
    } catch (err) {
      // Already disconnected
    }
    scriptProcessor.disconnect();
  }

  return {
    stop: (shouldSkipMinTime?: boolean) => new Promise<Result>((resolve, reject) => {
      opusMediaRecorder.onstop = () => {
        resolve({
          blob: new Blob(chunks, BLOB_PARAMS),
          duration: Math.max(1, Math.round(timekeeper.getElapsedMs() / 1000)),
          waveform: Array.from(analyser.finish()),
        });
      };
      opusMediaRecorder.onerror = reject;

      const delay = shouldSkipMinTime ? Promise.resolve() : waitForMinRecordingTime(timekeeper.getElapsedMs());
      void delay.then(() => {
        opusMediaRecorder.stop();
        releaseTap();
      });
    }),
    pause: () => {
      if (timekeeper.getIsPaused()) return Promise.resolve();
      timekeeper.pause();
      opusMediaRecorder.pause();
      return Promise.resolve();
    },
    resume: () => {
      if (!timekeeper.getIsPaused()) return;
      timekeeper.resume();
      opusMediaRecorder.resume();
    },
    getElapsedMs: timekeeper.getElapsedMs,
    getProfilePeaks: () => analyser.getCurrentPeaks(),
  };
}

function releaseTap() {
    scriptProcessor.onaudioprocess = undefined as unknown as typeof scriptProcessor.onaudioprocess;
    try {
      source.disconnect(scriptProcessor);
    } catch (err) {
      // Already disconnected
    }
    scriptProcessor.disconnect();
  }

function createTimekeeper() {
  const startedAt = Date.now();
  let intervalStartedAt = startedAt;
  let accumulatedMs = 0;
  let isPaused = false;

  return {
    pause: () => {
      accumulatedMs += Date.now() - intervalStartedAt;
      isPaused = true;
    },
    resume: () => {
      intervalStartedAt = Date.now();
      isPaused = false;
    },
    getElapsedMs: () => (isPaused ? accumulatedMs : accumulatedMs + (Date.now() - intervalStartedAt)),
    getIsPaused: () => isPaused,
  };
}

function waitForMinRecordingTime(elapsedMs: number) {
  const delay = Math.max(0, MIN_RECORDING_TIME - elapsedMs);
  return new Promise<void>((resolve) => {
    setTimeout(resolve, delay);
  });
}

interface CancellableCallback {
  (
    ...args: any[]
  ): void;

  isCanceled?: boolean;
}

interface OriginMessageEvent {
  data: OriginMessageData;
}

interface WorkerMessageEvent {
  data: WorkerMessageData;
}

interface RequestState {
  messageId: string;
  resolve: AnyToVoidFunction;
  reject: AnyToVoidFunction;
  callback: AnyToVoidFunction;
}

class ConnectorClass<T extends InputRequestTypes> {
  private requestStates = new Map<string, RequestState>();

  private requestStatesByCallback = new Map<AnyToVoidFunction, RequestState>();

  private pendingPayloads: OriginPayload[] = [];

  private pendingTransferables: Transferable[] = [];

  constructor(
    public target: Worker,
    private onUpdate?: (update: ApiUpdate) => void,
    private channel?: string,
  ) {
  }

  public destroy() {
  }

  init(...args: any[]) {
    this.postMessageOnTickEnd({
      type: 'init',
      args,
    });
  }

  request(messageData: RequestTypes<T>) {
    const { requestStates, requestStatesByCallback } = this;
    const { transferables, ...restMessageData } = messageData;

    const messageId = generateUniqueId();
    const payload: CallMethodPayload = {
      type: 'callMethod',
      messageId,
      ...restMessageData,
    };

    const requestState = { messageId } as RequestState;

    // Re-wrap type because of `postMessage`
    const promise = new Promise<any>((resolve, reject) => {
      Object.assign(requestState, { resolve, reject });
    });

    if (typeof payload.args[payload.args.length - 1] === 'function') {
      payload.withCallback = true;

      const callback = payload.args.pop() as AnyToVoidFunction;
      requestState.callback = callback;
      requestStatesByCallback.set(callback, requestState);
    }

    requestStates.set(messageId, requestState);
    promise
      .catch(() => undefined)
      .finally(() => {
        requestStates.delete(messageId);

        if (requestState.callback) {
          requestStatesByCallback.delete(requestState.callback);
        }
      });

    this.postMessageOnTickEnd(payload, transferables);

    return promise;
  }

  cancelCallback(progressCallback: CancellableCallback) {
    progressCallback.isCanceled = true;

    const { messageId } = this.requestStatesByCallback.get(progressCallback) || {};
    if (!messageId) {
      return;
    }

    this.postMessageOnTickEnd({
      type: 'cancelProgress',
      messageId,
    });
  }

  onMessage(data: WorkerMessageData) {
    const { requestStates, channel } = this;
    if (data.channel !== channel) {
      return;
    }

    data.payloads.forEach((payload) => {
      if (payload.type === 'update' && this.onUpdate) {
        this.onUpdate(payload.update);
      }
      if (payload.type === 'methodResponse') {
        const requestState = requestStates.get(payload.messageId);
        if (requestState) {
          if (payload.error) {
            requestState.reject(new Error(payload.error.message));
          } else {
            requestState.resolve(payload.response);
          }
        }
      } else if (payload.type === 'methodCallback') {
        const requestState = requestStates.get(payload.messageId);
        requestState?.callback?.(...payload.callbackArgs);
      } else if (payload.type === 'unhandledError') {
        throw new Error(payload.error?.message);
      }
    });
  }

  private postMessageOnTickEnd(payload: OriginPayload, transferables?: Transferable[]) {
    this.pendingPayloads.push(payload);

    if (transferables) {
      this.pendingTransferables.push(...transferables);
    }

    this.postMessagesOnTickEnd();
  }

  private postMessagesOnTickEnd = throttleWithTickEnd(() => {
    const { channel } = this;
    const payloads = this.pendingPayloads;
    const transferables = this.pendingTransferables;

    this.pendingPayloads = [];
    this.pendingTransferables = [];

    this.target.postMessage({ channel, payloads }, transferables);
  });
}

