function createConnector<T extends InputRequestTypes>(
  worker: Worker,
  onUpdate?: (update: ApiUpdate) => void,
  channel?: string,
) {
  const connector = new ConnectorClass<T>(worker, onUpdate, channel);

  function handleMessage({ data }: WorkerMessageEvent) {
    connector.onMessage(data);
  }

  worker.addEventListener('message', handleMessage);

  connector.destroy = () => {
    worker.removeEventListener('message', handleMessage);
  };

  return connector;
}

function handleMessage({ data }: WorkerMessageEvent) {
    connector.onMessage(data);
  }

function handleChange(e: React.ChangeEvent<HTMLInputElement>) {
    onChange(e.currentTarget.value);
    updateScrollableHint(e.currentTarget);
  }

function handleKeyDown(e: React.KeyboardEvent<HTMLInputElement>) {
    if (!value && onDeleteEmpty && (e.key === 'Backspace' || e.key === 'Delete')) {
      e.preventDefault();
      e.stopPropagation();
      onDeleteEmpty();
      return;
    }

    if (e.key !== 'Enter' || !canSubmit) {
      return;
    }

    e.preventDefault();
    e.stopPropagation();
    onSubmit();
  }

