function convertToVirtualClass(value: any): any {
  if (value instanceof Uint8Array) return value;
  if (typeof value === 'object' && Object.keys(value).length === 1 && Object.keys(value)[0] === 'value') {
    return BigInt(value.value);
  }

  if (Array.isArray(value)) {
    return value.map(convertToVirtualClass);
  }

  if (typeof value !== 'object' || !('CONSTRUCTOR_ID' in value)) {
    return value;
  }
  const path = value.className.split('.');
  const VirtualClass = path.reduce((acc: any, field: string) => {
    return acc[field];
  }, GramJs);

  const valueOmited = omitVirtualClassFields(value);
  const valueConverted = Object.keys(valueOmited).reduce((acc, key) => {
    acc[key] = convertToVirtualClass(valueOmited[key]);
    return acc;
  }, {} as Record<string, any>);

  return new VirtualClass(valueConverted);
}

function createLocalDbInitial(initial?: LocalDb): LocalDb {
  return [
    'localMessages', 'chats', 'users', 'messages', 'documents', 'stickerSets', 'photos', 'webDocuments', 'stories',
    'commonBoxState', 'channelPtsById',
  ]
    .reduce((acc: Record<string, any>, key) => {
      const value = initial?.[key as keyof LocalDb] ?? {};
      const convertedValue = Object.keys(value).reduce((acc2, key2) => {
        if (key === 'commonBoxState' || key === 'channelPtsById') {
          const typedValue = value as Record<string, number>;
          acc2[key2] = typedValue[key2];
          return acc2;
        }

        acc2[key2] = convertToVirtualClass(value[key2]);
        return acc2;
      }, {} as Record<string, any>);

      acc[key] = createProxy(key, convertedValue);
      return acc;
    }, {} as LocalDb) as LocalDb;
}

function broadcastLocalDbUpdateFull() {
  if (!channel) return;

  channel.postMessage({
    type: 'localDbUpdateFull',
    localDb: Object.keys(localDb).reduce((acc: Record<string, any>, key) => {
      acc[key] = { ...localDb[key as keyof LocalDb] };
      return acc;
    }, {} as Record<string, any>),
  });
}

function updateFullLocalDb(initial: LocalDb) {
  Object.assign(localDb, createLocalDbInitial(initial));
}

function clearLocalDb() {
  Object.assign(localDb, createLocalDbInitial());
}

function focusEditableElement(element: HTMLElement, force?: boolean, forcePlaceCaretAtEnd?: boolean) {
  if (!force && element === document.activeElement) {
    return;
  }

  const selection = window.getSelection()!;
  const range = document.createRange();
  const lastChild = element.lastChild || element;

  if (!IS_TOUCH_ENV && !forcePlaceCaretAtEnd && (!lastChild || !lastChild.nodeValue)) {
    element.focus();
    return;
  }

  range.selectNodeContents(forcePlaceCaretAtEnd ? element : lastChild);
  // `false` means collapse to the end rather than the start
  range.collapse(false);
  selection.removeAllRanges();
  selection.addRange(range);
}

function useLongPress({
  onClick, onStart, onEnd, threshold = DEFAULT_THRESHOLD,
}: {
  onStart?: NoneToVoidFunction;
  onClick?: (event: React.MouseEvent | React.TouchEvent) => void;
  onEnd?: NoneToVoidFunction;
  threshold?: number;
}) {
  const isLongPressActiveRef = useRef(false);
  const isPressedRef = useRef(false);
  const timerIdRef = useRef<number | undefined>(undefined);

  const start = useLastCallback((e: React.MouseEvent | React.TouchEvent) => {
    const canProcessEvent = ('button' in e && e.button === 0) || ('touches' in e && e.touches.length > 0);
    if (isPressedRef.current || !canProcessEvent) {
      return;
    }

    isPressedRef.current = true;
    timerIdRef.current = window.setTimeout(() => {
      onStart?.();
      isLongPressActiveRef.current = true;
    }, threshold);
  });

  const end = useLastCallback((e: React.MouseEvent | React.TouchEvent) => {
    if (!isPressedRef.current) return;

    if (isLongPressActiveRef.current) {
      onEnd?.();
    } else {
      onClick?.(e);
    }

    cancel();
  });

  const cancel = useLastCallback(() => {
    isLongPressActiveRef.current = false;
    isPressedRef.current = false;
    window.clearTimeout(timerIdRef.current);
  });

  useUnmountCleanup(() => {
    window.clearTimeout(timerIdRef.current);
  });

  return {
    onMouseDown: start,
    onMouseUp: end,
    onMouseLeave: end,
    onTouchStart: start,
    onTouchEnd: end,
  };
}

function extractInstantViewEmbedUrl(html: string) {
  try {
    const parser = new DOMParser();
    const parsedDocument = parser.parseFromString(html, TYPE_HTML);
    const canonicalLink = parsedDocument.querySelector<HTMLLinkElement>(CANONICAL_LINK_SELECTOR);
    const href = canonicalLink?.getAttribute('href')?.trim();

    return href ? normalizeEmbedUrl(href) : undefined;
  } catch (err) {
    return undefined;
  }
}

function normalizeEmbedUrl(href: string) {
  try {
    const url = new URL(href);

    return ALLOWED_EMBED_URL_PROTOCOLS.has(url.protocol) ? url.href : undefined;
  } catch (err) {
    return undefined;
  }
}

function updateSharedState<T extends GlobalState>(
  global: T, update: Partial<SharedState>,
): T {
  return {
    ...global,
    sharedState: {
      ...global.sharedState,
      ...update,
    },
  };
}

