    stickerset: buildInputStickerSet(stickerSetId, accessHash),
    archived: false,
  }));

  if (result) {
    sendApiUpdate({
      '@type': 'updateStickerSet',
      id: stickerSetId,
      stickerSet: { installedDate: Date.now() },
    });
  }
}

async function uninstallStickerSet({ stickerSetId, accessHash }: { stickerSetId: string; accessHash: string }) {
  const result = await invokeRequest(new GramJs.messages.UninstallStickerSet({
    stickerset: buildInputStickerSet(stickerSetId, accessHash),
  }));

  if (result) {
    sendApiUpdate({
      '@type': 'updateStickerSet',
      id: stickerSetId,
      stickerSet: { installedDate: undefined },
    });
  }
}

async function searchGifs({
  query,
  offset = DEFAULT_PRIMITIVES.STRING,
  username = DEFAULT_GIF_SEARCH_BOT_USERNAME,
}: { query: string; offset?: string; username?: string }) {
  if (!inputGifBot) {
    const resolvedPeer = await invokeRequest(new GramJs.contacts.ResolveUsername({
      username,
    }));
    if (!resolvedPeer || !(resolvedPeer.users[0] instanceof GramJs.User)) {
      return undefined;
    }

    inputGifBot = new GramJs.InputUser({
      userId: (resolvedPeer.peer as GramJs.PeerUser).userId,
      accessHash: resolvedPeer.users[0].accessHash!,
    });
  }

  const result = await invokeRequest(new GramJs.messages.GetInlineBotResults({
    bot: inputGifBot,
    peer: new GramJs.InputPeerEmpty(),
    query,
    offset,
  }));
  if (!result) {
    return undefined;
  }

  const documents = result.results
    .map((foundGif) => {
      if (foundGif instanceof GramJs.BotInlineMediaResult) {
        return foundGif.document;
      }

      return undefined;
    })
    .filter(Boolean);

  return {
    nextOffset: result.nextOffset,
    gifs: processGifResult(documents),
  };
}

async function fetchStickersForEmoji({
  emoji, hash,
}: { emoji: string; hash?: string }) {
  const result = await invokeRequest(new GramJs.messages.GetStickers({
    emoticon: emoji,
    hash: hash ? BigInt(hash) : DEFAULT_PRIMITIVES.BIGINT,
  }));

  if (!result || result instanceof GramJs.messages.StickersNotModified) {
    return undefined;
  }

  return {
    stickers: processStickerResult(result.stickers),
    hash: String(result.hash),
  };
}

async function fetchEmojiKeywords({
  language,
  fromVersion = DEFAULT_PRIMITIVES.INT,
}: {
  language: string;
  fromVersion?: number;
}) {
  const result = await invokeRequest(new GramJs.messages.GetEmojiKeywordsDifference({
    langCode: language,
    fromVersion,
  }));

  if (!result) {
    return undefined;
  }

  return {
    language: result.langCode,
    version: result.version,
    keywords: result.keywords.reduce((acc, emojiKeyword) => {
      acc[emojiKeyword.keyword] = emojiKeyword.emoticons;

      return acc;
    }, {} as Record<string, string[]>),
  };
}

async function fetchEmojiGroups({ hash = DEFAULT_PRIMITIVES.INT }: { hash?: number }) {
  const result = await invokeRequest(new GramJs.messages.GetEmojiGroups({ hash }));

  if (!result || result instanceof GramJs.messages.EmojiGroupsNotModified) {
    return undefined;
  }

  return {
    hash: result.hash,
    groups: compact(result.groups.map(buildApiEmojiGroup)),
  };
}

async function searchCustomEmojiByEmoticons({ emoticons }: { emoticons: string[] }) {
  const result = await invokeRequest(new GramJs.messages.SearchCustomEmoji({
    emoticon: emoticons.join(''),
    hash: DEFAULT_PRIMITIVES.BIGINT,
  }));

  if (!result || result instanceof GramJs.EmojiListNotModified) {
    return undefined;
  }

  return {
    documentIds: result.documentId.map(String),
  };
}

async function fetchRecentEmojiStatuses(hash?: string) {
  const result = await invokeRequest(new GramJs.account.GetRecentEmojiStatuses({
    hash: hash ? BigInt(hash) : DEFAULT_PRIMITIVES.BIGINT,
  }));

  if (!result || result instanceof GramJs.account.EmojiStatusesNotModified) {
    return undefined;
  }

  const documentIds = result.statuses
    .slice(0, RECENT_STATUS_LIMIT)
    .map(buildApiEmojiStatus)
    .filter(Boolean)
    .map(({ documentId }) => documentId);
  const emojiStatuses = await fetchCustomEmoji({ documentId: documentIds });

  return {
    hash: String(result.hash),
    emojiStatuses,
  };
}

function processGifResult(gifs: GramJs.TypeDocument[]) {
  return gifs
    .map((document) => {
      if (document instanceof GramJs.Document) {
        const gif = buildVideoFromDocument(document);
        if (gif) {
          localDb.documents[String(document.id)] = document;

          return gif;
        }
      }

      return undefined;
    })
    .filter(Boolean);
}

function recordWithMediaRecorder(
  videoTrack: MediaStreamTrack, audioTrack: MediaStreamTrack | undefined,
): VideoRecorderEngine {
  const stream = new MediaStream(audioTrack ? [videoTrack, audioTrack] : [videoTrack]);

  const mimeType = MIME_CANDIDATES.find((type) => MediaRecorder.isTypeSupported(type));
  const mediaRecorder = new MediaRecorder(stream, {
    mimeType,
    videoBitsPerSecond: ROUND_VIDEO_BITRATE,
    audioBitsPerSecond: ROUND_AUDIO_BITRATE,
  });

  // When no candidate is supported the browser picks the container itself — the actual
  // type is only reflected in `mediaRecorder.mimeType` after construction
  const getBaseMimeType = () => (mimeType || mediaRecorder.mimeType || 'video/mp4').split(';')[0];
  const chunks: Blob[] = [];
  mediaRecorder.ondataavailable = (e) => {
    if (e.data.size) chunks.push(e.data);
  };
  mediaRecorder.onerror = (e) => {
    // eslint-disable-next-line no-console
    console.error('Round video recording error', e);
  };
  mediaRecorder.start();

  return {
    finalize: () => new Promise<Blob>((resolve, reject) => {
      mediaRecorder.onstop = () => resolve(new Blob(chunks, { type: getBaseMimeType() }));
      mediaRecorder.onerror = reject;

      try {
        mediaRecorder.stop();
      } catch (err) {
        reject(err);
      }
    }),
    cancel: () => {
      if (mediaRecorder.state !== 'inactive') {
        mediaRecorder.stop();
      }
    },
    pause: () => {
      if (mediaRecorder.state === 'recording') {
        mediaRecorder.pause();
      }
    },
    resume: () => {
      if (mediaRecorder.state === 'paused') {
        mediaRecorder.resume();
      }
    },
  };
}

function createSnapshotRecorder(
  videoTrack: MediaStreamTrack, audioTrack: MediaStreamTrack | undefined,
): SnapshotRecorder | undefined {
  const mimeType = SNAPSHOT_MIME_CANDIDATES.find((type) => MediaRecorder.isTypeSupported(type));
  if (!mimeType) {
    return undefined;
  }

  const stream = new MediaStream(audioTrack ? [videoTrack, audioTrack] : [videoTrack]);
  let recorder: MediaRecorder;
  try {
    recorder = new MediaRecorder(stream, {
      mimeType,
      videoBitsPerSecond: ROUND_VIDEO_BITRATE,
      audioBitsPerSecond: ROUND_AUDIO_BITRATE,
    });
  } catch (err) {
    return undefined;
  }

  const chunks: Blob[] = [];
  recorder.ondataavailable = (e) => {
    if (e.data.size) chunks.push(e.data);
  };
  recorder.start(SNAPSHOT_TIMESLICE_MS);

  // Force out the buffered tail so the snapshot taken right after covers the whole recording.
  // Resolution requires at least one delivered `dataavailable` followed by a macrotask of
  // silence (the pending event set is finite once paused); the long timeout only covers
  // the event never arriving
  const flushAndPause = () => new Promise<void>((resolve) => {
    if (recorder.state !== 'recording') {
      resolve();
      return;
    }

    recorder.pause();

    let settleTimeout: number | undefined;
    const finish = () => {
      clearTimeout(settleTimeout);
      clearTimeout(fallbackTimeout);
      recorder.removeEventListener('dataavailable', handleData);
      resolve();
    };
    function handleData() {
      clearTimeout(fallbackTimeout);
      clearTimeout(settleTimeout);
      settleTimeout = window.setTimeout(finish, 0);
    }
    recorder.addEventListener('dataavailable', handleData);
    const fallbackTimeout = window.setTimeout(finish, FLUSH_FALLBACK_TIMEOUT_MS);

    try {
      recorder.requestData();
    } catch (err) {
      finish();
    }
  });

  return {
    flushAndPause,
    resume: () => {
      if (recorder.state === 'paused') {
        recorder.resume();
      }
    },
    finish: () => {
      try {
        if (recorder.state !== 'inactive') {
          recorder.stop();
        }
      } catch (err) {
        // Already stopped
      }
    },
    getBlob: () => new Blob(chunks, { type: 'video/webm' }),
  };
}

function handleData() {
      clearTimeout(fallbackTimeout);
      clearTimeout(settleTimeout);
      settleTimeout = window.setTimeout(finish, 0);
    }

function createMockedUser(id: string, mockData: MockTypes): Api.User {
  const user = mockData.users.find((u) => u.id === id);

  if (!user) throw Error('No such user ' + id);

  const {
    firstName = 'John',
    lastName = 'Doe',
    accessHash = 1n,
    ...rest
  } = user;

  return new Api.User({
    ...rest,
    id: BigInt(id),
    firstName,
    lastName,
    accessHash,
  });
}

interface SignalState<T> {
  value: T;
  effects: CallbackManager;
}

function isSignal(obj: unknown): obj is Signal {
  return typeof obj === 'function' && SIGNAL_MARK in obj;
}

function createSignal<T>(defaultValue?: T) {
  const state: SignalState<typeof defaultValue> = {
    value: defaultValue,
    effects: createCallbackManager(),
  };

  function subscribe(effect: NoneToVoidFunction) {
    const unsubscribe = state.effects.addCallback(effect);

    if (!unsubscribesByEffect.has(effect)) {
      unsubscribesByEffect.set(effect, new Set([unsubscribe]));
    } else {
      unsubscribesByEffect.get(effect)!.add(unsubscribe);
    }

    return () => {
      unsubscribe();

      const unsubscribes = unsubscribesByEffect.get(effect)!;
      unsubscribes.delete(unsubscribe);
      if (!unsubscribes.size) {
        unsubscribesByEffect.delete(effect);
      }
    };
  }

  function once(effect: NoneToVoidFunction) {
    const unsub = subscribe(() => {
      unsub();
      effect();
    });

    return unsub;
  }

  function getter() {
    return state.value;
  }

  function setter(newValue: T) {
    if (state.value === newValue) {
      return;
    }

    state.value = newValue;
    state.effects.runCallbacks();
  }

  const signal = Object.assign(getter as Signal<T>, {
    [SIGNAL_MARK]: SIGNAL_MARK,
    subscribe,
    once,
  });

  return [signal, setter] as const;
}

function subscribe(effect: NoneToVoidFunction) {
    const unsubscribe = state.effects.addCallback(effect);

    if (!unsubscribesByEffect.has(effect)) {
      unsubscribesByEffect.set(effect, new Set([unsubscribe]));
    } else {
      unsubscribesByEffect.get(effect)!.add(unsubscribe);
    }

    return () => {
      unsubscribe();

      const unsubscribes = unsubscribesByEffect.get(effect)!;
      unsubscribes.delete(unsubscribe);
      if (!unsubscribes.size) {
        unsubscribesByEffect.delete(effect);
      }
    };
  }

function once(effect: NoneToVoidFunction) {
    const unsub = subscribe(() => {
      unsub();
      effect();
    });

    return unsub;
  }

function getter() {
    return state.value;
  }

function setter(newValue: T) {
    if (state.value === newValue) {
      return;
    }

    state.value = newValue;
    state.effects.runCallbacks();
  }

function cleanupEffect(effect: NoneToVoidFunction) {
  unsubscribesByEffect.get(effect)?.forEach((unsubscribe) => {
    unsubscribe();
  });
  unsubscribesByEffect.delete(effect);
}

function sortChatIds(
  chatIds: string[],
  shouldPrioritizeVerified = false,
  priorityIds?: string[],
  currentUserId?: string,
) {
  // Avoid calling sort on every global change
  const global = getGlobal();

  return orderBy(chatIds, (id) => {
    if (id === currentUserId) {
      return Infinity;
    }

    const chat = selectChat(global, id);
    if (!chat) {
      return 0;
    }

    let priority = 0;

    const lastMessage = selectChatLastMessage(global, id);
    if (lastMessage) {
      priority += lastMessage.date;
    }

    if (shouldPrioritizeVerified && chat.isVerified) {
      priority += VERIFIED_PRIORITY_BASE; // ~100 years in seconds
    }

    if (priorityIds && priorityIds.includes(id)) {
      priority = Date.now() + PINNED_PRIORITY_BASE + (priorityIds.length - priorityIds.indexOf(id));
    }

    return priority;
  }, 'desc');
}

function useStyleObserver(
  ref: ElementRef<HTMLElement>,
  property: string,
  debounce = UPDATE_DEBOUNCE,
  isDisabled?: boolean,
) {
  const [value, setValue] = useState<string | undefined>();

  const updateValue = useLastCallback(() => {
    if (!ref.current || isDisabled) {
      setValue(undefined);
      return;
    }

    const computedValue = getComputedStyle(ref.current).getPropertyValue(property).trim();
    setValue(computedValue);
  });

  // Element does not receive `transitionend` event if parent has `display: none`.
  // We will receive `resize` event when parent is shown again.
  useResizeObserver(ref, updateValue, isDisabled);

  useLayoutEffect(() => {
    const el = ref.current;
    if (!el || isDisabled) {
      return undefined;
    }

    el.style.setProperty('transition', `${debounce}ms ${property} linear`, 'important');

    return () => {
      el.style.removeProperty('transition');
    };
  }, [debounce, isDisabled, property, ref]);

  useEffect(() => {
    const el = ref.current;
    if (!el) {
      return undefined;
    }

    updateValue();

    if (isDisabled) {
      return undefined;
    }

    function handleTransitionEnd(e: TransitionEvent) {
      if (e.propertyName !== property) return;
      updateValue();
    }

    el.addEventListener('transitionend', handleTransitionEnd);

    return () => {
      el.removeEventListener('transitionend', handleTransitionEnd);
    };
  }, [isDisabled, property, ref, updateValue]);

  return value;
}

function handleTransitionEnd(e: TransitionEvent) {
      if (e.propertyName !== property) return;
      updateValue();
    }

interface Params {
  size: number;
  noLoop?: boolean;
  quality?: number;
  isLowPriority?: boolean;
  coords?: { x: number; y: number };
  fitzModifier?: EmojiFitzModifier;
}

class TLottie {
  // Config

  private views = new Map<string, {
    canvas: HTMLCanvasElement;
    ctx: CanvasRenderingContext2D;
    isLoaded?: boolean;
    isPaused?: boolean;
    isSharedCanvas?: boolean;
    coords?: Params['coords'];
    onLoad?: NoneToVoidFunction;
    onFrame?: FrameCallback;
  }>();

  private imgSize!: number;

  private msPerFrame = 1000 / 60;

  private reduceFactor = 1;

  private cacheModulo!: number;

  private workerIndex!: number;

  private frames: Frame[] = [];

  private frameGeneration = 0;

  private dataGeneration = 0;

  private framesCount?: number;

  // State

  private isAnimating = false;

  private isWaiting = true;

  private isEnded = false;

  private isDestroyed = false;

  private isRendererInited = false;

  private approxFrameIndex = 0;

  private prevFrameIndex = -1;

  private stopFrameIndex? = 0;

  private speed = 1;

  private direction: 1 | -1 = 1;

  private lastRenderAt?: number;

  private requestedSeekToEnd = false;

  static init(...args: ConstructorParameters<typeof TLottie>) {
    const [
      , canvas,
      renderId,
      params,
      viewId = generateUniqueId(),,
      onLoad,,,
      onFrame,
    ] = args;
    let instance = instancesByRenderId.get(renderId);

    if (!instance) {
      instance = new TLottie(...args);
      instancesByRenderId.set(renderId, instance);
    } else {
      instance.addView(viewId, canvas, onLoad, onFrame, params?.coords);
    }

    return instance;
  }

  constructor(
    private tgsUrl: string,
    container: HTMLDivElement | HTMLCanvasElement,
    private renderId: string,
    private params: Params,
    viewId: string = generateUniqueId(),
    private customColor?: Color,
    onLoad?: NoneToVoidFunction,
    private onEnded?: (isDestroyed?: boolean) => void,
    private onLoop?: () => void,
    onFrame?: FrameCallback,
  ) {
    this.addView(viewId, container, onLoad, onFrame, params.coords);
    this.initConfig();
    this.initRenderer();
  }

  public removeView(viewId: string) {
    const {
      canvas, ctx, isSharedCanvas, coords,
    } = this.views.get(viewId)!;

    if (isSharedCanvas) {
      ctx.clearRect(coords!.x, coords!.y, this.imgSize, this.imgSize);
    } else {
      canvas.remove();
    }

    this.views.delete(viewId);

    if (!this.views.size) {
      this.destroy();
    }
  }

  isPlaying() {
    return this.isAnimating || this.isWaiting;
  }

  play(forceRestart = false, viewId?: string) {
    if (viewId) {
      this.views.get(viewId)!.isPaused = false;
    }

    if (this.isEnded && forceRestart) {
      this.approxFrameIndex = Math.floor(0);
    }

    this.stopFrameIndex = undefined;
    this.direction = 1;
    this.doPlay();
  }

  pause(viewId?: string) {
    this.lastRenderAt = undefined;

    if (viewId) {
      this.views.get(viewId)!.isPaused = true;

      const areAllContainersPaused = Array.from(this.views.values()).every(({ isPaused }) => isPaused);
      if (!areAllContainersPaused) {
        return;
      }
    }

    if (this.isWaiting) {
      this.stopFrameIndex = this.approxFrameIndex;
    } else {
      this.isAnimating = false;
    }

    if (!this.params.isLowPriority) {
      this.frames = this.frames.map((frame, i) => {
        if (i === this.prevFrameIndex) {
          return frame;
        } else {
          if (frame && frame !== WAITING) {
            frame.close();
          }

          return undefined;
        }
      });
    }
  }

  playSegment([startFrameIndex, stopFrameIndex]: [number, number], forceRestart = false, viewId?: string) {
    if (viewId) {
      this.views.get(viewId)!.isPaused = false;
    }

    const frameIndex = Math.round(this.approxFrameIndex);
    this.stopFrameIndex = Math.floor(stopFrameIndex / this.reduceFactor);
    if (frameIndex !== stopFrameIndex || forceRestart) {
      this.approxFrameIndex = Math.floor(startFrameIndex / this.reduceFactor);
    }
    this.direction = startFrameIndex < stopFrameIndex ? 1 : -1;

    this.doPlay();
  }

  seekToEnd() {
    this.requestedSeekToEnd = true;
    this.doPlay();
  }

  setSpeed(speed: number) {
    this.speed = speed;
  }

  setNoLoop(noLoop?: boolean) {
    this.params.noLoop = noLoop;
  }

  async setSharedCanvasCoords(viewId: string, newCoords: Params['coords']) {
    const containerInfo = this.views.get(viewId)!;
    const {
      canvas, ctx,
    } = containerInfo;

    const isCanvasDirty = !canvas.dataset.isJustCleaned || canvas.dataset.isJustCleaned === 'false';

    if (!isCanvasDirty) {
      await PENDING_CANVAS_RESIZES.get(canvas);
    }

    let [canvasWidth, canvasHeight] = [canvas.width, canvas.height];

    if (isCanvasDirty) {
      const sizeFactor = this.calcSizeFactor();
      ([canvasWidth, canvasHeight] = ensureCanvasSize(canvas, sizeFactor));
      ctx.clearRect(0, 0, canvasWidth, canvasHeight);
      canvas.dataset.isJustCleaned = 'true';
      requestMeasure(() => {
        canvas.dataset.isJustCleaned = 'false';
      });
    }

    containerInfo.coords = {
      x: Math.round((newCoords?.x || 0) * canvasWidth),
      y: Math.round((newCoords?.y || 0) * canvasHeight),
    };

    const frame = this.getFrame(this.prevFrameIndex) || this.getFrame(Math.round(this.approxFrameIndex));

    if (frame && frame !== WAITING) {
      ctx.drawImage(frame, containerInfo.coords.x, containerInfo.coords.y);
    }
  }

  private addView(
    viewId: string,
    container: HTMLDivElement | HTMLCanvasElement,
    onLoad?: NoneToVoidFunction,
    onFrame?: FrameCallback,
    coords?: Params['coords'],
  ) {
    const sizeFactor = this.calcSizeFactor();

    let imgSize: number;

    if (container instanceof HTMLDivElement) {
      if (!(container.parentNode instanceof HTMLElement)) {
        throw new Error('[TLottie] Container is not mounted');
      }

      const { size } = this.params;

      imgSize = Math.round(size * sizeFactor);

      if (!this.imgSize) {
        this.imgSize = imgSize;
      }

      const canvas = document.createElement('canvas');
      const ctx = canvas.getContext('2d')!;

      canvas.classList.add(CANVAS_CLASS);

      canvas.style.width = `${size}px`;
      canvas.style.height = `${size}px`;

      canvas.width = imgSize;
      canvas.height = imgSize;

      this.views.set(viewId, {
        canvas, ctx, onLoad, onFrame,
      });

      requestMutation(() => {
        if (this.views.has(viewId)) {
          container.appendChild(canvas);
        }
      });
    } else {
      if (!container.isConnected) {
        throw new Error('[TLottie] Shared canvas is not mounted');
      }

      const canvas = container;
      const ctx = canvas.getContext('2d')!;

      imgSize = Math.round(this.params.size * sizeFactor);

      if (!this.imgSize) {
        this.imgSize = imgSize;
      }

      const [canvasWidth, canvasHeight] = ensureCanvasSize(canvas, sizeFactor);

      this.views.set(viewId, {
        canvas,
        ctx,
        isSharedCanvas: true,
        coords: {
          x: Math.round(coords!.x * canvasWidth),
          y: Math.round(coords!.y * canvasHeight),
        },
        onLoad,
        onFrame,
      });
    }

    if (this.isRendererInited) {
      this.doPlay();
    }
  }

  private calcSizeFactor() {
    const {
      size,
      isLowPriority,
      // Reduced quality only looks acceptable on big enough images
      quality = isLowPriority && (!size || size > LOW_PRIORITY_QUALITY_SIZE_THRESHOLD)
        ? LOW_PRIORITY_QUALITY : HIGH_PRIORITY_QUALITY,
    } = this.params;

    // Reduced quality only looks acceptable on high DPR screens
    return Math.max(window.devicePixelRatio * quality, 1);
  }

  private destroy() {
    this.isDestroyed = true;
    this.pause();
    this.clearFrames();
    this.destroyRenderer();

    instancesByRenderId.delete(this.renderId);
  }

  private clearFrames() {
    this.frameGeneration += 1;

    this.frames.forEach((frame) => {
      if (frame && frame !== WAITING) {
        frame.close();
      }
    });

    this.frames = [];
    this.prevFrameIndex = -1;
  }

  private initConfig() {
    const { isLowPriority } = this.params;

    this.cacheModulo = isLowPriority ? LOW_PRIORITY_CACHE_MODULO : HIGH_PRIORITY_CACHE_MODULO;
  }

  setColor(newColor: Color | undefined) {
    this.customColor = newColor;
  }

  private initRenderer() {
    this.workerIndex = cycleRestrict(MAX_WORKERS, ++lastWorkerIndex);
    const { dataGeneration } = this;

    void workers[this.workerIndex].request({
      name: 'tlottie:init',
      args: [
        this.renderId,
        this.tgsUrl,
        this.imgSize,
        this.params.isLowPriority || false,
        this.customColor?.to('srgb').coords.map(convertSrgbChannel) as [number, number, number] | undefined,
        this.params.fitzModifier,
        this.onRendererInit.bind(this, dataGeneration),
      ],
    }).then((isSuccess) => {
      if (!isSuccess) {
        this.onRendererUnavailable(dataGeneration);
      }
    }, this.onRendererError.bind(this, dataGeneration));
  }

  private destroyRenderer() {
    workers[this.workerIndex].request({
      name: 'tlottie:destroy',
      args: [this.renderId],
    });
  }

  private onRendererInit(dataGeneration: number, reduceFactor: number, msPerFrame: number, framesCount: number) {
    if (dataGeneration !== this.dataGeneration) {
      return;
    }

    this.isRendererInited = true;
    this.reduceFactor = reduceFactor;
    this.msPerFrame = msPerFrame;
    this.framesCount = framesCount;

    if (this.isWaiting) {
      this.doPlay();
    }
  }

  changeData(tgsUrl: string, fitzModifier?: EmojiFitzModifier) {
    this.pause();
    this.clearFrames();
    const dataGeneration = ++this.dataGeneration;

    this.framesCount = undefined;
    this.isRendererInited = false;
    this.approxFrameIndex = 0;
    this.stopFrameIndex = 0;
    this.direction = 1;
    this.requestedSeekToEnd = false;
    this.tgsUrl = tgsUrl;
    this.params.fitzModifier = fitzModifier;
    this.initConfig();

    void workers[this.workerIndex].request({
      name: 'tlottie:changeData',
      args: [
        this.renderId,
        this.tgsUrl,
        this.params.isLowPriority || false,
        this.params.fitzModifier,
        this.onChangeData.bind(this, dataGeneration),
      ],
    }).then((isSuccess) => {
      if (!isSuccess) {
        this.onRendererUnavailable(dataGeneration);
      }
    }, this.onRendererError.bind(this, dataGeneration));
  }

  private onChangeData(dataGeneration: number, reduceFactor: number, msPerFrame: number, framesCount: number) {
    if (dataGeneration !== this.dataGeneration) {
      return;
    }

    this.isRendererInited = true;
    this.reduceFactor = reduceFactor;
    this.msPerFrame = msPerFrame;
    this.framesCount = framesCount;
    const lastFrameIndex = framesCount - 1;
    this.approxFrameIndex = Math.min(this.approxFrameIndex, lastFrameIndex);
    if (this.stopFrameIndex !== undefined) {
      this.stopFrameIndex = Math.min(this.stopFrameIndex, lastFrameIndex);
    }
    this.isWaiting = false;
    this.isAnimating = false;

    this.doPlay();
  }

  private onRendererError(dataGeneration: number, err: Error) {
    if (dataGeneration !== this.dataGeneration || this.isDestroyed) {
      return;
    }

    this.markRendererUnavailable();
    handleError(err);
  }

  private onRendererUnavailable(dataGeneration: number) {
    if (dataGeneration !== this.dataGeneration || this.isDestroyed) {
      return;
    }

    this.markRendererUnavailable();
  }

  private markRendererUnavailable() {
    this.isRendererInited = false;
    this.isWaiting = false;
    this.isAnimating = false;
  }

  private doPlay() {
    if (!this.framesCount) {
      return;
    }

    if (this.isDestroyed) {
      return;
    }

    if (this.requestedSeekToEnd) {
      this.approxFrameIndex = this.framesCount - 1;
      this.stopFrameIndex = undefined;
      this.requestedSeekToEnd = false;
    }

    if (this.isAnimating) {
      return;
    }

    if (!this.isWaiting) {
      this.lastRenderAt = undefined;
    }

    this.isEnded = false;
    this.isAnimating = true;
    this.isWaiting = false;

    animate(() => {
      if (this.isDestroyed) {
        return false;
      }

      // Paused from outside
      if (!this.isAnimating) {
        const areAllLoaded = Array.from(this.views.values()).every(({ isLoaded }) => isLoaded);
        if (areAllLoaded) {
          return false;
        }
      }

      const frameIndex = Math.round(this.approxFrameIndex);
      const frame = this.getFrame(frameIndex);
      if (!frame || frame === WAITING) {
        if (!frame) {
          this.requestFrame(frameIndex);
        }

        this.isAnimating = false;
        this.isWaiting = true;
        return false;
      }

      if (this.cacheModulo && frameIndex % this.cacheModulo === 0) {
        this.cleanupPrevFrame(frameIndex);
      }

      if (frameIndex !== this.prevFrameIndex) {
        this.views.forEach((containerData) => {
          const {
            ctx, isLoaded, isPaused, coords: { x, y } = {}, onLoad, onFrame,
          } = containerData;

          if (!isLoaded || !isPaused) {
            ctx.clearRect(x || 0, y || 0, this.imgSize, this.imgSize);
            ctx.drawImage(frame, x || 0, y || 0);
            onFrame?.(frameIndex);
          }

          if (!isLoaded) {
            containerData.isLoaded = true;
            onLoad?.();
          }
        });

        this.prevFrameIndex = frameIndex;
      }

      const now = Date.now();
      const currentSpeed = this.lastRenderAt ? this.msPerFrame / (now - this.lastRenderAt) : 1;
      const delta = (this.direction * this.speed) / currentSpeed;
      const expectedNextFrameIndex = Math.round(this.approxFrameIndex + delta);

      this.lastRenderAt = now;

      // Forward animation finished
      if (delta > 0 && (frameIndex === this.framesCount! - 1 || expectedNextFrameIndex > this.framesCount! - 1)) {
        if (this.params.noLoop) {
          this.isAnimating = false;
          this.isEnded = true;
          this.onEnded?.();
          return false;
        }
        this.onLoop?.();

        this.approxFrameIndex = 0;

        // Backward animation finished
      } else if (delta < 0 && (frameIndex === 0 || expectedNextFrameIndex < 0)) {
        if (this.params.noLoop) {
          this.isAnimating = false;
          this.isEnded = true;
          this.onEnded?.();
          return false;
        }
        this.onLoop?.();

        this.approxFrameIndex = this.framesCount! - 1;

        // Stop frame reached
      } else if (
        this.stopFrameIndex !== undefined
        && (frameIndex === this.stopFrameIndex
          || (
            (delta > 0 && expectedNextFrameIndex > this.stopFrameIndex)
            || (delta < 0 && expectedNextFrameIndex < this.stopFrameIndex)
          ))
      ) {
        this.stopFrameIndex = undefined;
        this.isAnimating = false;
        return false;

        // Preparing next frame
      } else {
        this.approxFrameIndex += delta;
      }

      const nextFrameIndex = Math.round(this.approxFrameIndex);

      if (!this.getFrame(nextFrameIndex)) {
        this.requestFrame(nextFrameIndex);
        this.isWaiting = true;
        this.isAnimating = false;
        return false;
      }

      return true;
    }, requestMutation);
  }

  private getFrame(frameIndex: number) {
    return this.frames[frameIndex];
  }

  private requestFrame(frameIndex: number) {
    const { frameGeneration } = this;
    this.frames[frameIndex] = WAITING;

    workers[this.workerIndex].request({
      name: 'tlottie:renderFrames',
      args: [this.renderId, frameIndex, this.onFrameLoad.bind(this, frameGeneration)],
    });
  }

  private cleanupPrevFrame(frameIndex: number) {
    if (this.framesCount! < 3) {
      return;
    }

    const prevFrameIndex = cycleRestrict(this.framesCount!, frameIndex - 1);
    this.frames[prevFrameIndex] = undefined;
  }

  private onFrameLoad(frameGeneration: number, frameIndex: number, imageBitmap: ImageBitmap) {
    if (frameGeneration !== this.frameGeneration || this.frames[frameIndex] !== WAITING) {
      imageBitmap.close();
      return;
    }

    this.frames[frameIndex] = imageBitmap;

    if (this.isWaiting) {
      this.doPlay();
    }
  }
}

static init(...args: ConstructorParameters<typeof TLottie>) {
    const [
      , canvas,
      renderId,
      params,
      viewId = generateUniqueId(),,
      onLoad,,,
      onFrame,
    ] = args;
    let instance = instancesByRenderId.get(renderId);

    if (!instance) {
      instance = new TLottie(...args);
      instancesByRenderId.set(renderId, instance);
    } else {
      instance.addView(viewId, canvas, onLoad, onFrame, params?.coords);
    }

    return instance;
  }

constructor(
    private tgsUrl: string,
    container: HTMLDivElement | HTMLCanvasElement,
    private renderId: string,
    private params: Params,
    viewId: string = generateUniqueId(),
    private customColor?: Color,
    onLoad?: NoneToVoidFunction,
    private onEnded?: (isDestroyed?: boolean) => void,
    private onLoop?: () => void,
    onFrame?: FrameCallback,
  ) {
    this.addView(viewId, container, onLoad, onFrame, params.coords);
    this.initConfig();
    this.initRenderer();
  }

public removeView(viewId: string) {
    const {
      canvas, ctx, isSharedCanvas, coords,
    } = this.views.get(viewId)!;

    if (isSharedCanvas) {
      ctx.clearRect(coords!.x, coords!.y, this.imgSize, this.imgSize);
    } else {
      canvas.remove();
    }

    this.views.delete(viewId);

    if (!this.views.size) {
      this.destroy();
    }
  }

isPlaying() {
    return this.isAnimating || this.isWaiting;
  }

play(forceRestart = false, viewId?: string) {
    if (viewId) {
      this.views.get(viewId)!.isPaused = false;
    }

    if (this.isEnded && forceRestart) {
      this.approxFrameIndex = Math.floor(0);
    }

    this.stopFrameIndex = undefined;
    this.direction = 1;
    this.doPlay();
  }

pause(viewId?: string) {
    this.lastRenderAt = undefined;

    if (viewId) {
      this.views.get(viewId)!.isPaused = true;

      const areAllContainersPaused = Array.from(this.views.values()).every(({ isPaused }) => isPaused);
      if (!areAllContainersPaused) {
        return;
      }
    }

    if (this.isWaiting) {
      this.stopFrameIndex = this.approxFrameIndex;
    } else {
      this.isAnimating = false;
    }

    if (!this.params.isLowPriority) {
      this.frames = this.frames.map((frame, i) => {
        if (i === this.prevFrameIndex) {
          return frame;
        } else {
          if (frame && frame !== WAITING) {
            frame.close();
          }

          return undefined;
        }
      });
    }
  }

playSegment([startFrameIndex, stopFrameIndex]: [number, number], forceRestart = false, viewId?: string) {
    if (viewId) {
      this.views.get(viewId)!.isPaused = false;
    }

    const frameIndex = Math.round(this.approxFrameIndex);
    this.stopFrameIndex = Math.floor(stopFrameIndex / this.reduceFactor);
    if (frameIndex !== stopFrameIndex || forceRestart) {
      this.approxFrameIndex = Math.floor(startFrameIndex / this.reduceFactor);
    }
    this.direction = startFrameIndex < stopFrameIndex ? 1 : -1;

    this.doPlay();
  }

seekToEnd() {
    this.requestedSeekToEnd = true;
    this.doPlay();
  }

setSpeed(speed: number) {
    this.speed = speed;
  }

setNoLoop(noLoop?: boolean) {
    this.params.noLoop = noLoop;
  }

async setSharedCanvasCoords(viewId: string, newCoords: Params['coords']) {
    const containerInfo = this.views.get(viewId)!;
    const {
      canvas, ctx,
    } = containerInfo;

    const isCanvasDirty = !canvas.dataset.isJustCleaned || canvas.dataset.isJustCleaned === 'false';

    if (!isCanvasDirty) {
      await PENDING_CANVAS_RESIZES.get(canvas);
    }

    let [canvasWidth, canvasHeight] = [canvas.width, canvas.height];

    if (isCanvasDirty) {
      const sizeFactor = this.calcSizeFactor();
      ([canvasWidth, canvasHeight] = ensureCanvasSize(canvas, sizeFactor));
      ctx.clearRect(0, 0, canvasWidth, canvasHeight);
      canvas.dataset.isJustCleaned = 'true';
      requestMeasure(() => {
        canvas.dataset.isJustCleaned = 'false';
      });
    }

    containerInfo.coords = {
      x: Math.round((newCoords?.x || 0) * canvasWidth),
      y: Math.round((newCoords?.y || 0) * canvasHeight),
    };

    const frame = this.getFrame(this.prevFrameIndex) || this.getFrame(Math.round(this.approxFrameIndex));

    if (frame && frame !== WAITING) {
      ctx.drawImage(frame, containerInfo.coords.x, containerInfo.coords.y);
    }
  }

private addView(
    viewId: string,
    container: HTMLDivElement | HTMLCanvasElement,
    onLoad?: NoneToVoidFunction,
    onFrame?: FrameCallback,
    coords?: Params['coords'],
  ) {
    const sizeFactor = this.calcSizeFactor();

    let imgSize: number;

    if (container instanceof HTMLDivElement) {
      if (!(container.parentNode instanceof HTMLElement)) {
        throw new Error('[TLottie] Container is not mounted');
      }

      const { size } = this.params;

      imgSize = Math.round(size * sizeFactor);

      if (!this.imgSize) {
        this.imgSize = imgSize;
      }

      const canvas = document.createElement('canvas');
      const ctx = canvas.getContext('2d')!;

      canvas.classList.add(CANVAS_CLASS);

      canvas.style.width = `${size}px`;
      canvas.style.height = `${size}px`;

      canvas.width = imgSize;
      canvas.height = imgSize;

      this.views.set(viewId, {
        canvas, ctx, onLoad, onFrame,
      });

      requestMutation(() => {
        if (this.views.has(viewId)) {
          container.appendChild(canvas);
        }
      });
    } else {
      if (!container.isConnected) {
        throw new Error('[TLottie] Shared canvas is not mounted');
      }

      const canvas = container;
      const ctx = canvas.getContext('2d')!;

      imgSize = Math.round(this.params.size * sizeFactor);

      if (!this.imgSize) {
        this.imgSize = imgSize;
      }

      const [canvasWidth, canvasHeight] = ensureCanvasSize(canvas, sizeFactor);

      this.views.set(viewId, {
        canvas,
        ctx,
        isSharedCanvas: true,
        coords: {
          x: Math.round(coords!.x * canvasWidth),
          y: Math.round(coords!.y * canvasHeight),
        },
        onLoad,
        onFrame,
      });
    }

    if (this.isRendererInited) {
      this.doPlay();
    }
  }

private calcSizeFactor() {
    const {
      size,
      isLowPriority,
      // Reduced quality only looks acceptable on big enough images
      quality = isLowPriority && (!size || size > LOW_PRIORITY_QUALITY_SIZE_THRESHOLD)
        ? LOW_PRIORITY_QUALITY : HIGH_PRIORITY_QUALITY,
    } = this.params;

    // Reduced quality only looks acceptable on high DPR screens
    return Math.max(window.devicePixelRatio * quality, 1);
  }

private destroy() {
    this.isDestroyed = true;
    this.pause();
    this.clearFrames();
    this.destroyRenderer();

    instancesByRenderId.delete(this.renderId);
  }

private clearFrames() {
    this.frameGeneration += 1;

    this.frames.forEach((frame) => {
      if (frame && frame !== WAITING) {
        frame.close();
      }
    });

    this.frames = [];
    this.prevFrameIndex = -1;
  }

private initConfig() {
    const { isLowPriority } = this.params;

    this.cacheModulo = isLowPriority ? LOW_PRIORITY_CACHE_MODULO : HIGH_PRIORITY_CACHE_MODULO;
  }

setColor(newColor: Color | undefined) {
    this.customColor = newColor;
  }

private initRenderer() {
    this.workerIndex = cycleRestrict(MAX_WORKERS, ++lastWorkerIndex);
    const { dataGeneration } = this;

    void workers[this.workerIndex].request({
      name: 'tlottie:init',
      args: [
        this.renderId,
        this.tgsUrl,
        this.imgSize,
        this.params.isLowPriority || false,
        this.customColor?.to('srgb').coords.map(convertSrgbChannel) as [number, number, number] | undefined,
        this.params.fitzModifier,
        this.onRendererInit.bind(this, dataGeneration),
      ],
    }).then((isSuccess) => {
      if (!isSuccess) {
        this.onRendererUnavailable(dataGeneration);
      }
    }, this.onRendererError.bind(this, dataGeneration));
  }

private destroyRenderer() {
    workers[this.workerIndex].request({
      name: 'tlottie:destroy',
      args: [this.renderId],
    });
  }

private onRendererInit(dataGeneration: number, reduceFactor: number, msPerFrame: number, framesCount: number) {
    if (dataGeneration !== this.dataGeneration) {
      return;
    }

    this.isRendererInited = true;
    this.reduceFactor = reduceFactor;
    this.msPerFrame = msPerFrame;
    this.framesCount = framesCount;

    if (this.isWaiting) {
      this.doPlay();
    }
  }

changeData(tgsUrl: string, fitzModifier?: EmojiFitzModifier) {
    this.pause();
    this.clearFrames();
    const dataGeneration = ++this.dataGeneration;

    this.framesCount = undefined;
    this.isRendererInited = false;
    this.approxFrameIndex = 0;
    this.stopFrameIndex = 0;
    this.direction = 1;
    this.requestedSeekToEnd = false;
    this.tgsUrl = tgsUrl;
    this.params.fitzModifier = fitzModifier;
    this.initConfig();

    void workers[this.workerIndex].request({
      name: 'tlottie:changeData',
      args: [
        this.renderId,
        this.tgsUrl,
        this.params.isLowPriority || false,
        this.params.fitzModifier,
        this.onChangeData.bind(this, dataGeneration),
      ],
    }).then((isSuccess) => {
      if (!isSuccess) {
        this.onRendererUnavailable(dataGeneration);
      }
    }, this.onRendererError.bind(this, dataGeneration));
  }

private onChangeData(dataGeneration: number, reduceFactor: number, msPerFrame: number, framesCount: number) {
    if (dataGeneration !== this.dataGeneration) {
      return;
    }

    this.isRendererInited = true;
    this.reduceFactor = reduceFactor;
    this.msPerFrame = msPerFrame;
    this.framesCount = framesCount;
    const lastFrameIndex = framesCount - 1;
    this.approxFrameIndex = Math.min(this.approxFrameIndex, lastFrameIndex);
    if (this.stopFrameIndex !== undefined) {
      this.stopFrameIndex = Math.min(this.stopFrameIndex, lastFrameIndex);
    }
    this.isWaiting = false;
    this.isAnimating = false;

    this.doPlay();
  }

private onRendererError(dataGeneration: number, err: Error) {
    if (dataGeneration !== this.dataGeneration || this.isDestroyed) {
      return;
    }

    this.markRendererUnavailable();
    handleError(err);
  }

private onRendererUnavailable(dataGeneration: number) {
    if (dataGeneration !== this.dataGeneration || this.isDestroyed) {
      return;
    }

    this.markRendererUnavailable();
  }

private markRendererUnavailable() {
    this.isRendererInited = false;
    this.isWaiting = false;
    this.isAnimating = false;
  }

private doPlay() {
    if (!this.framesCount) {
      return;
    }

    if (this.isDestroyed) {
      return;
    }

    if (this.requestedSeekToEnd) {
      this.approxFrameIndex = this.framesCount - 1;
      this.stopFrameIndex = undefined;
      this.requestedSeekToEnd = false;
    }

    if (this.isAnimating) {
      return;
    }

    if (!this.isWaiting) {
      this.lastRenderAt = undefined;
    }

    this.isEnded = false;
    this.isAnimating = true;
    this.isWaiting = false;

    animate(() => {
      if (this.isDestroyed) {
        return false;
      }

      // Paused from outside
      if (!this.isAnimating) {
        const areAllLoaded = Array.from(this.views.values()).every(({ isLoaded }) => isLoaded);
        if (areAllLoaded) {
          return false;
        }
      }

      const frameIndex = Math.round(this.approxFrameIndex);
      const frame = this.getFrame(frameIndex);
      if (!frame || frame === WAITING) {
        if (!frame) {
          this.requestFrame(frameIndex);
        }

        this.isAnimating = false;
        this.isWaiting = true;
        return false;
      }

      if (this.cacheModulo && frameIndex % this.cacheModulo === 0) {
        this.cleanupPrevFrame(frameIndex);
      }

      if (frameIndex !== this.prevFrameIndex) {
        this.views.forEach((containerData) => {
          const {
            ctx, isLoaded, isPaused, coords: { x, y } = {}, onLoad, onFrame,
          } = containerData;

          if (!isLoaded || !isPaused) {
            ctx.clearRect(x || 0, y || 0, this.imgSize, this.imgSize);
            ctx.drawImage(frame, x || 0, y || 0);
            onFrame?.(frameIndex);
          }

          if (!isLoaded) {
            containerData.isLoaded = true;
            onLoad?.();
          }
        });

        this.prevFrameIndex = frameIndex;
      }

      const now = Date.now();
      const currentSpeed = this.lastRenderAt ? this.msPerFrame / (now - this.lastRenderAt) : 1;
      const delta = (this.direction * this.speed) / currentSpeed;
      const expectedNextFrameIndex = Math.round(this.approxFrameIndex + delta);

      this.lastRenderAt = now;

      // Forward animation finished
      if (delta > 0 && (frameIndex === this.framesCount! - 1 || expectedNextFrameIndex > this.framesCount! - 1)) {
        if (this.params.noLoop) {
          this.isAnimating = false;
          this.isEnded = true;
          this.onEnded?.();
          return false;
        }
        this.onLoop?.();

        this.approxFrameIndex = 0;

        // Backward animation finished
      } else if (delta < 0 && (frameIndex === 0 || expectedNextFrameIndex < 0)) {
        if (this.params.noLoop) {
          this.isAnimating = false;
          this.isEnded = true;
          this.onEnded?.();
          return false;
        }
        this.onLoop?.();

        this.approxFrameIndex = this.framesCount! - 1;

        // Stop frame reached
      } else if (
        this.stopFrameIndex !== undefined
        && (frameIndex === this.stopFrameIndex
          || (
            (delta > 0 && expectedNextFrameIndex > this.stopFrameIndex)
            || (delta < 0 && expectedNextFrameIndex < this.stopFrameIndex)
          ))
      ) {
        this.stopFrameIndex = undefined;
        this.isAnimating = false;
        return false;

        // Preparing next frame
      } else {
        this.approxFrameIndex += delta;
      }

      const nextFrameIndex = Math.round(this.approxFrameIndex);

      if (!this.getFrame(nextFrameIndex)) {
        this.requestFrame(nextFrameIndex);
        this.isWaiting = true;
        this.isAnimating = false;
        return false;
      }

      return true;
    }, requestMutation);
  }

private getFrame(frameIndex: number) {
    return this.frames[frameIndex];
  }

private requestFrame(frameIndex: number) {
    const { frameGeneration } = this;
    this.frames[frameIndex] = WAITING;

    workers[this.workerIndex].request({
      name: 'tlottie:renderFrames',
      args: [this.renderId, frameIndex, this.onFrameLoad.bind(this, frameGeneration)],
    });
  }

private cleanupPrevFrame(frameIndex: number) {
    if (this.framesCount! < 3) {
      return;
    }

    const prevFrameIndex = cycleRestrict(this.framesCount!, frameIndex - 1);
    this.frames[prevFrameIndex] = undefined;
  }

private onFrameLoad(frameGeneration: number, frameIndex: number, imageBitmap: ImageBitmap) {
    if (frameGeneration !== this.frameGeneration || this.frames[frameIndex] !== WAITING) {
      imageBitmap.close();
      return;
    }

    this.frames[frameIndex] = imageBitmap;

    if (this.isWaiting) {
      this.doPlay();
    }
  }

function ensureCanvasSize(canvas: HTMLCanvasElement, sizeFactor: number) {
  const expectedWidth = Math.round(canvas.offsetWidth * sizeFactor);
  const expectedHeight = Math.round(canvas.offsetHeight * sizeFactor);

  if (canvas.width !== expectedWidth || canvas.height !== expectedHeight) {
    const deferred = new Deferred<void>();
    PENDING_CANVAS_RESIZES.set(canvas, deferred.promise);
    requestMutation(() => {
      canvas.width = expectedWidth;
      canvas.height = expectedHeight;
      deferred.resolve();
    });
  }

  return [expectedWidth, expectedHeight];
}

function _raiseCastFail(entity: any, target: string) {
  throw new Error(`Cannot cast ${entity.className} to any kind of ${target}`);
}

function getInputPeer(
  entity: Entity, allowSelf = true, checkHash = true,
): Api.TypeInputPeer {
  if (entity instanceof Api.User) {
    if (entity.self && allowSelf) {
      return new Api.InputPeerSelf();
    } else if (entity.accessHash !== undefined || !checkHash) {
      return new Api.InputPeerUser({
        userId: entity.id,
        accessHash: entity.accessHash!,
      });
    } else {
      throw new Error('User without accessHash or min info cannot be input');
    }
  }
  if (entity instanceof Api.Chat || entity instanceof Api.ChatEmpty
    || entity instanceof Api.ChatForbidden) {
    return new Api.InputPeerChat({ chatId: entity.id });
  }
  if (entity instanceof Api.Channel) {
    if (entity.accessHash !== undefined || !checkHash) {
      return new Api.InputPeerChannel({
        channelId: entity.id,
        accessHash: entity.accessHash!,
      });
    } else {
      throw new TypeError('Channel without accessHash or min info cannot be input');
    }
  }
  if (entity instanceof Api.ChannelForbidden) {
    // "channelForbidden are never min", and since their hash is
    // also not optional, we assume that this truly is the case.
    return new Api.InputPeerChannel({
      channelId: entity.id,
      accessHash: entity.accessHash,
    });
  }
  // Communities are addressed through the channel input peer
  if (entity instanceof Api.Community || entity instanceof Api.CommunityForbidden) {
    if (entity.accessHash !== undefined || !checkHash) {
      return new Api.InputPeerChannel({
        channelId: entity.id,
        accessHash: entity.accessHash!,
      });
    } else {
      throw new TypeError('Community without accessHash or min info cannot be input');
    }
  }

  if (entity instanceof Api.UserEmpty) {
    return new Api.InputPeerEmpty();
  }

  _raiseCastFail(entity, 'InputPeer');
  return new Api.InputPeerEmpty();
}

function strippedPhotoToJpg(stripped: Uint8Array): Uint8Array {
  // Note: Changes here should update _stripped_real_length
  if (stripped.length < 3 || stripped[0] !== 1) {
    return stripped;
  }
  const header = new Uint8Array(JPEG_HEADER);
  header[164] = stripped[1];
  header[166] = stripped[2];
  return concat(header, stripped.slice(3), JPEG_FOOTER);
}

function getDownloadPartSize(fileSize: number) {
  if (fileSize <= 65536) { // 64KB
    return 64;
  }
  if (fileSize <= 104857600) { // 100MB
    return 128;
  }
  if (fileSize <= 786432000) { // 750MB
    return 256;
  }
  if (fileSize <= 2097152000) { // 2000MB
    return 512;
  }
  if (fileSize <= 4194304000) { // 4000MB
    return 1024;
  }

  throw new Error('File size too large');
}

function getUploadPartSize(fileSize: number) {
  if (fileSize <= 104857600) { // 100MB
    return 128;
  }
  if (fileSize <= 786432000) { // 750MB
    return 256;
  }
  if (fileSize <= 2097152000) { // 2000MB
    return 512;
  }
  if (fileSize <= 4194304000) { // 4000MB
    return 512;
  }

  throw new Error('File size too large');
}

function getDisplayName(entity: Entity) {
  if (entity instanceof Api.User) {
    if (entity.lastName && entity.firstName) {
      return `${entity.firstName} ${entity.lastName}`;
    } else if (entity.firstName) {
      return entity.firstName;
    } else if (entity.lastName) {
      return entity.lastName;
    } else {
      return '';
    }
  } else if (entity instanceof Api.Chat || entity instanceof Api.Channel) {
    return entity.title;
  }
  return '';
}

