  };
}

function buildApiTypeStarGiftAuctionState(
  state: GramJs.TypeStarGiftAuctionState,
): ApiTypeStarGiftAuctionState | undefined {
  if (state instanceof GramJs.StarGiftAuctionStateNotModified) {
    return undefined;
  }

  if (state instanceof GramJs.StarGiftAuctionStateFinished) {
    const {
      startDate, endDate, averagePrice, listedCount, fragmentListedCount, fragmentListedUrl,
    } = state;

    return {
      type: 'finished',
      startDate,
      endDate,
      averagePrice: toJSNumber(averagePrice),
      listedCount,
      fragmentListedCount,
      fragmentListedUrl,
    };
  }

  const {
    version, startDate, endDate, minBidAmount, bidLevels, topBidders,
    nextRoundAt, lastGiftNum, giftsLeft, currentRound, totalRounds,
  } = state;

  return {
    type: 'active',
    version,
    startDate,
    endDate,
    minBidAmount: toJSNumber(minBidAmount),
    bidLevels: bidLevels.map(buildApiAuctionBidLevel),
    topBidders: topBidders.map((id) => buildApiPeerId(id, 'user')),
    nextRoundAt,
    lastGiftNum,
    giftsLeft,
    currentRound,
    totalRounds,
  };
}

function buildApiStarGiftAuctionUserState(
  userState: GramJs.StarGiftAuctionUserState,
): ApiStarGiftAuctionUserState {
  const {
    returned, bidAmount, bidDate, minBidAmount, bidPeer, acquiredCount,
  } = userState;

  return {
    isReturned: returned || undefined,
    bidAmount: bidAmount !== undefined ? toJSNumber(bidAmount) : undefined,
    bidDate,
    minBidAmount: minBidAmount !== undefined ? toJSNumber(minBidAmount) : undefined,
    bidPeerId: bidPeer && getApiChatIdFromMtpPeer(bidPeer),
    acquiredCount,
  };
}

function buildApiStarGiftAuctionState(
  result: GramJs.payments.StarGiftAuctionState | GramJs.StarGiftActiveAuctionState,
): ApiStarGiftAuctionState | undefined {
  const gift = buildApiStarGift(result.gift);
  if (gift.type !== 'starGift') return undefined;

  const state = buildApiTypeStarGiftAuctionState(result.state);
  if (!state) return undefined;

  return {
    gift,
    state,
    userState: buildApiStarGiftAuctionUserState(result.userState),
    timeout: 'timeout' in result ? result.timeout : undefined,
  };
}

function buildApiStarGiftAuctionAcquiredGift(
  result: GramJs.StarGiftAuctionAcquiredGift,
): ApiStarGiftAuctionAcquiredGift {
  return {
    peerId: getApiChatIdFromMtpPeer(result.peer),
    date: result.date,
    bidAmount: toJSNumber(result.bidAmount),
    round: result.round,
    position: result.pos,
    message: result.message ? buildApiFormattedText(result.message) : undefined,
    giftNumber: result.giftNum,
    isNameHidden: result.nameHidden || undefined,
  };
}

function createMockedTypeInputPeer(id: string, mockData: MockTypes): Api.TypeInputPeer {
  const user = mockData.users.find((u) => u.id === id);
  if (user) {
    return new Api.InputPeerUser({
      userId: BigInt(id),
      accessHash: 1n,
    });
  }

  const chat = mockData.chats.find((c) => c.id === id);
  if (chat) {
    return new Api.InputPeerChat({
      chatId: BigInt(id),
    });
  }

  const channel = mockData.channels.find((c) => c.id === id);
  if (channel) {
    return new Api.InputPeerChannel({
      channelId: -BigInt(id) - CHANNEL_ID_BASE,
      accessHash: 1n,
    });
  }

  throw Error('No such peer ' + id);
}

function updateStickerSets<T extends GlobalState>(
  global: T,
  category: 'added' | 'featured',
  hash: string,
  sets: ApiStickerSet[],
): T {
  const updatedSets = sets.map((stickerSet) => {
    const existing = global.stickers.setsById[stickerSet.id];
    if (!existing) {
      return stickerSet;
    }

    return {
      ...existing,
      ...stickerSet,
    };
  });

  const regularSetIds = sets.map((set) => set.id);

  return {
    ...global,
    stickers: {
      ...global.stickers,
      setsById: {
        ...global.stickers.setsById,
        ...buildCollectionByKey(updatedSets, 'id'),
      },
      [category]: {
        ...global.stickers[category],
        hash,
        setIds: [
          ...(global.stickers[category].setIds || []),
          ...regularSetIds,
        ],
      },
    },
  };
}

function updateCustomEmojiSets<T extends GlobalState>(
  global: T,
  hash: string,
  sets: ApiStickerSet[],
): T {
  const updatedSets = sets.map((stickerSet) => {
    const existing = global.stickers.setsById[stickerSet.id];
    if (!existing) {
      return stickerSet;
    }

    return {
      ...existing,
      ...stickerSet,
    };
  });

  const customEmojis = sets.map((set) => set.stickers).flat().filter(Boolean);
  const addedSetIds = sets.map((set) => set.id);

  return {
    ...global,
    stickers: {
      ...global.stickers,
      setsById: {
        ...global.stickers.setsById,
        ...buildCollectionByKey(updatedSets, 'id'),
      },
    },
    customEmojis: {
      ...global.customEmojis,
      added: {
        ...global.customEmojis.added,
        hash,
        setIds: [
          ...(global.customEmojis.added.setIds || []),
          ...addedSetIds,
        ],
      },
      byId: {
        ...global.customEmojis.byId,
        ...buildCollectionByKey(customEmojis, 'id'),
      },
    },
  };
}

function updateStickerSet<T extends GlobalState>(
  global: T, stickerSetId: string, update: Partial<ApiStickerSet>,
): T {
  const currentStickerSet = global.stickers.setsById[stickerSetId] || {};
  const isCustomEmoji = update.isEmoji || currentStickerSet.isEmoji;
  const addedSets = (isCustomEmoji ? global.customEmojis.added.setIds : global.stickers.added.setIds) || [];
  let setIds: string[] = addedSets;
  if (update.installedDate && !update.isArchived && addedSets && !addedSets.includes(stickerSetId)) {
    setIds = [stickerSetId, ...setIds];
  }

  if (!update.installedDate && addedSets?.includes(stickerSetId)) {
    setIds = setIds.filter((id) => id !== stickerSetId);
  }

  const customEmojiById = isCustomEmoji && update.stickers && buildCollectionByKey(update.stickers, 'id');

  return {
    ...global,
    stickers: {
      ...global.stickers,
      added: {
        ...global.stickers.added,
        ...(!isCustomEmoji && { setIds }),
      },
      setsById: {
        ...global.stickers.setsById,
        [stickerSetId]: {
          ...currentStickerSet,
          ...update,
        },
      },
    },
    customEmojis: {
      ...global.customEmojis,
      byId: {
        ...global.customEmojis.byId,
        ...customEmojiById,
      },
      added: {
        ...global.customEmojis.added,
        ...(isCustomEmoji && { setIds }),
      },
    },
  };
}

function replaceAnimatedEmojis<T extends GlobalState>(global: T, stickerSet: ApiStickerSet): T {
