function getEntityTypeById(peerId: string) {
  const n = BigInt(peerId);
  if (n > 0n) {
    return 'user';
  }

  if (n < -CHANNEL_ID_BASE) {
    return 'channel';
  }

  return 'chat';
}

function buildPeer(chatOrUserId: string): GramJs.TypePeer {
  const type = getEntityTypeById(chatOrUserId);

  if (type === 'user') {
    return new GramJs.PeerUser({
      userId: buildMtpPeerId(chatOrUserId, 'user'),
    });
  } else if (type === 'channel') {
    return new GramJs.PeerChannel({
      channelId: buildMtpPeerId(chatOrUserId, 'channel'),
    });
  } else {
    return new GramJs.PeerChat({
      chatId: buildMtpPeerId(chatOrUserId, 'chat'),
    });
  }
}

function buildInputPeer(chatOrUserId: string, accessHash?: string): GramJs.TypeInputPeer {
  const type = getEntityTypeById(chatOrUserId);

  if (type === 'user') {
    return new GramJs.InputPeerUser({
      userId: buildMtpPeerId(chatOrUserId, 'user'),
      accessHash: BigInt(accessHash!),
    });
  } else if (type === 'channel') {
    return new GramJs.InputPeerChannel({
      channelId: buildMtpPeerId(chatOrUserId, 'channel'),
      accessHash: BigInt(accessHash!),
    });
  } else {
    return new GramJs.InputPeerChat({
      chatId: buildMtpPeerId(chatOrUserId, 'chat'),
    });
  }
}

function buildInputUser(userId: string, accessHash?: string): GramJs.TypeInputUser {
  if (!accessHash) {
    return new GramJs.InputUserEmpty();
  }

  return new GramJs.InputUser({
    userId: buildMtpPeerId(userId, 'user'),
    accessHash: BigInt(accessHash),
  });
}

function buildInputChannel(channelId: string, accessHash?: string): GramJs.TypeInputChannel {
  if (!accessHash) {
    return new GramJs.InputChannelEmpty();
  }

  return new GramJs.InputChannel({
    channelId: buildMtpPeerId(channelId, 'channel'),
    accessHash: BigInt(accessHash),
  });
}

function buildInputChat(chatId: string) {
  return BigInt(chatId.slice(1));
}

function buildInputPaidReactionPrivacy(isPrivate?: boolean, peerId?: string): GramJs.TypePaidReactionPrivacy {
  if (isPrivate) return new GramJs.PaidReactionPrivacyAnonymous();
  if (peerId) {
    const peer = buildInputPeerFromLocalDb(peerId);
    if (peer) {
      return new GramJs.PaidReactionPrivacyPeer({
        peer,
      });
    }
  }
  return new GramJs.PaidReactionPrivacyDefault();
}

function buildInputPeerFromLocalDb(chatOrUserId: string): GramJs.TypeInputPeer | undefined {
  const type = getEntityTypeById(chatOrUserId);
  let accessHash: bigint | undefined;

  if (type === 'user') {
    accessHash = localDb.users[chatOrUserId]?.accessHash;
    if (!accessHash) {
      return undefined;
    }
  } else if (type === 'channel') {
    accessHash = (localDb.chats[chatOrUserId] as GramJs.Channel)?.accessHash;
    if (!accessHash) {
      return undefined;
    }
  }

  return buildInputPeer(chatOrUserId, String(accessHash));
}

function buildInputUserFromLocalDb(userId: string): GramJs.TypeInputUser | undefined {
  const accessHash = localDb.users[userId]?.accessHash;
  if (!accessHash) {
    return undefined;
  }

  return buildInputUser(userId, String(accessHash));
}

function buildInputChannelFromLocalDb(channelId: string): GramJs.TypeInputChannel | undefined {
  const channel = localDb.chats[channelId];

  if (!channel || !(channel instanceof GramJs.Channel)) {
    return undefined;
  }

  return buildInputChannel(channelId, String(channel.accessHash));
}

function buildInputStickerSet(id: string, accessHash: string) {
  return new GramJs.InputStickerSetID({
    id: BigInt(id),
    accessHash: BigInt(accessHash),
  });
}

function buildInputStickerSetShortName(shortName: string) {
