function buildMtpPeerId(id: string, type: 'user' | 'chat' | 'channel') {
  const n = BigInt(id);
  if (type === 'user') {
    return n;
  }

  if (type === 'channel') {
    return -n - CHANNEL_ID_BASE;
  }

  return n * -1n;
}

