function convertCurrencyFromBaseUnit(amount: number, currency: string) {
  return amount / 10 ** getCurrencyExp(currency);
}

function convertCurrencyToBaseUnit(amount: number, currency: string) {
  return amount * 10 ** getCurrencyExp(currency);
}

function convertTonFromNanos(nanos: number): number {
  return convertCurrencyFromBaseUnit(nanos, TON_CURRENCY_CODE);
}

function convertTonToNanos(ton: number): number {
  return convertCurrencyToBaseUnit(ton, TON_CURRENCY_CODE);
}

function formatCurrency(
  lang: LangFn,
  totalPrice: number,
  currency: string,
  options?: {
    shouldOmitFractions?: boolean;
    iconClassName?: string;
    asFontIcon?: boolean;
  },
): TeactNode {
  const price = convertCurrencyFromBaseUnit(totalPrice, currency);

  if (currency === STARS_CURRENCY_CODE) {
    return formatStarsAsIcon(lang, price, { asFont: options?.asFontIcon, className: options?.iconClassName });
  }

  if (currency === TON_CURRENCY_CODE) {
    return formatTonAsIcon(lang, price, { className: options?.iconClassName, isMono: options?.asFontIcon });
  }

  return formatCurrencyAsString(totalPrice, currency, lang.code, options);
}

function convertTonToUsd(amount: number, usdRate: number, isInNanos: boolean = false): number {
  const tonInRegularUnits = isInNanos ? convertTonFromNanos(amount) : amount;
  return tonInRegularUnits * usdRate * 100;
}

function formatCurrencyAsString(
  totalPrice: number,
  currency: string,
  locale: string = FALLBACK_LANG_CODE,
  options?: {
    shouldOmitFractions?: boolean;
  },
) {
  const price = convertCurrencyFromBaseUnit(totalPrice, currency);

  if ((options?.shouldOmitFractions || currency === STARS_CURRENCY_CODE) && Number.isInteger(price)) {
    return new Intl.NumberFormat(locale, {
      style: 'currency',
      currency,
      minimumFractionDigits: 0,
      maximumFractionDigits: 0,
    }).format(price);
  }

  if (currency === TON_CURRENCY_CODE) {
    return new Intl.NumberFormat(locale, {
      style: 'currency',
      currency,
      minimumFractionDigits: 0,
      maximumFractionDigits: 10,
    }).format(price);
  }

  return new Intl.NumberFormat(locale, {
    style: 'currency',
    currency,
  }).format(price);
}

function getCurrencyExp(currency: string) {
  if (currency === TON_CURRENCY_CODE) {
    return 9;
  }
  if (currency === 'CLF') {
    return 4;
  }
  if (['BHD', 'IQD', 'JOD', 'KWD', 'LYD', 'OMR', 'TND'].includes(currency)) {
    return 3;
  }
  if ([
    'BIF', 'BYR', 'CLP', 'CVE', 'DJF', 'GNF', 'ISK', 'JPY', 'KMF', 'KRW', 'MGA', 'PYG', 'RWF', 'UGX', 'UYI',
    'VND', 'VUV', 'XAF', 'XOF', 'XPF', STARS_CURRENCY_CODE,
  ].includes(currency)) {
    return 0;
  }
  if (currency === 'MRO') {
    return 1;
  }
  return 2;
}

function resolveErrorKey(errorMessage: string) {
  return ERROR_KEYS[errorMessage] || ERROR_KEYS[errorMessage.replace(/_\d+$/, '')];
}

function resolveMessageApiChatId(mtpMessage: GramJs.TypeMessage) {
  if (!(mtpMessage instanceof GramJs.Message || mtpMessage instanceof GramJs.MessageService)) {
    return undefined;
  }

  return getApiChatIdFromMtpPeer(mtpMessage.peerId);
}

function isChatFolder(
  filter?: GramJs.TypeDialogFilter,
): filter is GramJs.DialogFilter | GramJs.DialogFilterChatlist {
  return filter instanceof GramJs.DialogFilter || filter instanceof GramJs.DialogFilterChatlist;
}

function serializeBytes(value: Uint8Array) {
  let result = '';
  for (let i = 0; i < value.length; i += SERIALIZE_BYTES_CHUNK_SIZE) {
    result += String.fromCharCode(...value.subarray(i, i + SERIALIZE_BYTES_CHUNK_SIZE));
  }
  return result;
}

function deserializeBytes(value: string) {
  return Uint8Array.from(value, (char) => char.charCodeAt(0));
}

function log(suffix: keyof typeof LOG_SUFFIX, ...data: any) {
  /* eslint-disable @stylistic/max-len */
  /* eslint-disable no-console */
  const func = suffix === 'UNEXPECTED RESPONSE' ? console.error
    : suffix === 'INVOKE ERROR' || suffix === 'UNEXPECTED UPDATE' ? console.warn : console.log;
  /* eslint-enable no-console */
  func(
    `%cGramJS%c${suffix}`,
    `color: ${LOG_PREFIX_COLOR}; background: ${LOG_BACKGROUND}; padding: 0.25rem; border-radius: 0.25rem;`,
    `color: ${LOG_SUFFIX[suffix]}; background: ${LOG_BACKGROUND}; padding: 0.25rem; border-radius: 0.25rem; margin-left: 0.25rem;`,
    ...data,
  );
  /* eslint-enable @stylistic/max-len */
}

function isResponseUpdate<T extends GramJs.AnyRequest>(result: T['__response']): result is GramJs.TypeUpdate {
  return result instanceof GramJs.UpdatesTooLong || result instanceof GramJs.UpdateShortMessage
    || result instanceof GramJs.UpdateShortChatMessage || result instanceof GramJs.UpdateShort
    || result instanceof GramJs.UpdatesCombined || result instanceof GramJs.Updates
    || result instanceof GramJs.UpdateShortSentMessage;
}

function checkErrorType(error: unknown): error is Error {
  if (!(error instanceof Error)) {
    // eslint-disable-next-line no-console
    if (DEBUG) console.warn('Unexpected error type', error);
    return false;
  }

  return true;
}

function buildApiError(error: Error): Pick<ApiError, 'message' | 'code' | 'hasErrorKey'> {
  if (error instanceof errors.RPCError) {
    return {
      message: error.errorMessage,
      code: error.code,
      hasErrorKey: true,
    };
  }

  return {
    message: error.message,
  };
}

function wrapError<T extends Error>(error: T): WrappedError<T> {
  let messageKey: RegularLangFnParameters | undefined;

  const errorMessage = error instanceof errors.RPCError ? error.errorMessage : undefined;

  if (error instanceof errors.FloodWaitError) {
    messageKey = {
      key: 'ErrorFloodTime',
      variables: { time: formatWait(error.seconds) },
    };
  } else if (error instanceof errors.PasswordFreshError) {
    messageKey = {
      key: 'ErrorPasswordFresh',
      variables: { time: formatWait(error.seconds) },
    };
  } else if (error instanceof errors.SessionFreshError) {
    messageKey = {
      key: 'ErrorSessionFresh',
      variables: { time: formatWait(error.seconds) },
    };
  } else if (error instanceof errors.RPCError) {
    const key = resolveErrorKey(error.errorMessage);
    if (key) {
      messageKey = {
        key,
      };
    }
  }

  if (!messageKey) {
    if (error.message) {
      messageKey = {
        key: 'ErrorUnexpectedMessage',
        variables: { error: error.message },
      };
    } else {
      messageKey = {
        key: 'ErrorUnexpected',
      };
    }
  }

  return {
    messageKey,
    errorMessage,
    error,
  };
}

function formatWait(seconds: number): RegularLangFnParameters {
  if (seconds < MINUTE) {
    return {
      key: 'Seconds',
      variables: { count: seconds },
      options: { pluralValue: seconds },
    };
  }

  if (seconds < HOUR) {
    const minutes = getMinutes(seconds);
    return {
      key: 'Minutes',
      variables: { count: minutes },
      options: { pluralValue: minutes },
    };
  }

  if (seconds < DAY) {
    const hours = getHours(seconds);
    return {
      key: 'Hours',
      variables: { count: hours },
      options: { pluralValue: hours },
    };
  }

  const days = getDays(seconds);

  return {
    key: 'Days',
    variables: { count: days },
    options: { pluralValue: days },
  };
}

function compatTest() {
  var hasPromise = typeof Promise !== 'undefined';
  var hasWebSockets = typeof WebSocket !== 'undefined';
  var hasWebCrypto = window.crypto && typeof window.crypto.subtle !== 'undefined';
  var hasObjectFromEntries = typeof Object.fromEntries !== 'undefined';
  var hasResizeObserver = typeof window.ResizeObserver !== 'undefined';
  var hasCssSupports = window.CSS && typeof window.CSS.supports === 'function';
  var hasIntl = typeof window.Intl !== 'undefined';
  var hasDisplayNames = hasIntl && typeof Intl.DisplayNames !== 'undefined';
  var hasPluralRules = hasIntl && typeof Intl.PluralRules !== 'undefined';
  var hasNumberFormat = hasIntl && typeof Intl.NumberFormat !== 'undefined';
  var hasWebLocks = typeof navigator.locks !== 'undefined';
  var hasBigInt = typeof BigInt !== 'undefined';
  var hasBroadcastChannel = typeof BroadcastChannel !== 'undefined';
  var hasArrayAt = typeof new Array(0).at !== 'undefined';
  var hasDecompressionStream = typeof DecompressionStream !== 'undefined';

  var isCompatible = hasPromise && hasWebSockets && hasWebCrypto && hasObjectFromEntries && hasResizeObserver
    && hasCssSupports && hasDisplayNames && hasPluralRules && hasNumberFormat && hasWebLocks && hasBigInt && hasBroadcastChannel
    && hasArrayAt && hasDecompressionStream;

  if (isCompatible || (window.localStorage && window.localStorage.getItem('tt-ignore-compat'))) {
    window.isCompatTestPassed = true;
    return;
  }

  if (window.console && console.warn) {
    console.warn('Compatibility test report:');
    console.warn('Promise', hasPromise);
    console.warn('WebSocket', hasWebSockets);
    console.warn('WebCrypto', hasWebCrypto);
    console.warn('Object.fromEntries', hasObjectFromEntries);
    console.warn('ResizeObserver', hasResizeObserver);
    console.warn('CSS.supports', hasCssSupports);
    console.warn('Intl.DisplayNames', hasDisplayNames);
    console.warn('Intl.PluralRules', hasPluralRules);
    console.warn('Intl.NumberFormat', hasNumberFormat);
    console.warn('WebLocks', hasWebLocks);
    console.warn('BigInt', hasBigInt);
    console.warn('BroadcastChannel', hasBroadcastChannel);
    console.warn('Array.at', hasArrayAt);
    console.warn('DecompressionStream', hasDecompressionStream);
  }

  // Hardcoded page because server forbids iframe embedding
  document.title = 'Unsupported Browser';
  document.body.setAttribute('style', 'height: 100%; margin: 0; font-family: Arial, Helvetica, sans-serif;');
  document.body.innerHTML = '<table style="width:100%;height:100%;border-collapse:collapse"><tr><td style="vertical-align:middle;text-align:center"><div style="display:inline-block"><img src=./unsupported.png><h3>Your browser is not supported</h3><p>Please, update it or use our <a href="http://telegram.org/dl" target="_blank">native clients</a>.</p><a id="ignore" href="#">I\'m Feeling Lucky</a></div></table>';

  if (!window.ignore) return;
  if (!window.ignore.addEventListener) {
    window.ignore.style.display = 'none';
    return;
  }

  window.ignore.addEventListener('click', function() {
    window.localStorage.setItem('tt-ignore-compat', '1');
    window.location.reload();
  });
}

