function useWindowSize() {
  const { width: initialWidth, height: initialHeight } = windowSize.get();
  const [width, setWidth] = useState(initialWidth);
  const [height, setHeight] = useState(initialHeight);
  const [isResizing, setIsResizing] = useState(false);
  const setIsResizingDebounced = useDebouncedCallback(setIsResizing, [setIsResizing], THROTTLE, true);

  useEffect(() => {
    const throttledSetIsResizing = throttle(() => {
      setIsResizing(true);
    }, THROTTLE, true);

    const throttledSetSize = throttle(() => {
      const { width: newWidth, height: newHeight } = windowSize.get();
      setWidth(newWidth);
      setHeight(newHeight);
      setIsResizingDebounced(false);
    }, THROTTLE, false);

    const handleResize = () => {
      throttledSetIsResizing();
      throttledSetSize();
    };

    window.addEventListener('resize', handleResize);

    return () => {
      window.removeEventListener('resize', handleResize);
    };
  }, [setIsResizingDebounced]);

  return useMemo(() => ({ width, height, isResizing }), [height, isResizing, width]);
}

function getTabsNaturalTop(container: HTMLElement): number {
  const profileInfo = container.querySelector<HTMLElement>('.profile-info');
  return profileInfo ? profileInfo.offsetHeight : 0;
}

function useProfileState({
  containerRef,
  tabType,
  profileState,
  onProfileStateChange,
  forceScrollProfileTab = false,
  allowAutoScrollToTabs = false,
  handleStopAutoScrollToTabs,
}: {
  containerRef: ElementRef<HTMLDivElement>;
  tabType: ProfileTabType;
  profileState: ProfileState;
  forceScrollProfileTab?: boolean;
  allowAutoScrollToTabs?: boolean;
  onProfileStateChange: (state: ProfileState) => void;
  handleStopAutoScrollToTabs: NoneToVoidFunction;
}) {
  // Scroll to tabs if needed
  useEffectWithPrevDeps(([prevTabType]) => {
    if ((prevTabType && prevTabType !== tabType && allowAutoScrollToTabs) || (tabType && forceScrollProfileTab)) {
      const container = containerRef.current!;
      const tabsEl = container.querySelector<HTMLDivElement>('.shared-media-tabs')!;
      handleStopAutoScrollToTabs();
      if (container.scrollTop < getTabsNaturalTop(container)) {
        onProfileStateChange(getStateFromTabType(tabType));
        isScrollingProgrammatically = true;
        animateScroll({
          container,
          element: tabsEl,
          position: 'start',
          forceDuration: TRANSITION_DURATION,
        });
        setTimeout(() => {
          isScrollingProgrammatically = false;
        }, PROGRAMMATIC_SCROLL_TIMEOUT_MS);
      }
    }
  }, [
    tabType, onProfileStateChange, containerRef, forceScrollProfileTab,
    allowAutoScrollToTabs, handleStopAutoScrollToTabs,
  ]);

  // Scroll to top
  useEffectWithPrevDeps(([prevProfileState]) => {
    if (profileState !== ProfileState.Profile || profileState === prevProfileState) {
      return;
    }

    const container = containerRef.current;
    if (!container) {
      return;
    }

    const tabsEl = container.querySelector<HTMLDivElement>('.shared-media-tabs');
    if (!tabsEl || getTabsNaturalTop(container) > container.scrollTop) {
      return;
    }

    isScrollingProgrammatically = true;

    animateScroll({
      container,
      element: container.firstElementChild as HTMLElement,
      position: 'start',
      maxDistance: container.offsetHeight * 2,
    });

    setTimeout(() => {
      isScrollingProgrammatically = false;
    }, PROGRAMMATIC_SCROLL_TIMEOUT_MS);
  }, [profileState, containerRef]);

  const determineProfileState = useLastCallback(() => {
    const container = containerRef.current;
    if (!container) {
      return;
    }

    if (!container.querySelector('.shared-media-tabs')) {
      return;
    }

    let state: ProfileState = ProfileState.Profile;
    if (Math.ceil(container.scrollTop) >= getTabsNaturalTop(container)) {
      state = getStateFromTabType(tabType);
    }

    if (state !== profileState) {
      onProfileStateChange(state);
    }
  });

  // Determine profile state when switching tabs
  useEffect(() => {
    if (isScrollingProgrammatically) {
      return;
    }

    determineProfileState();
  }, [determineProfileState, tabType]);

  // Determine profile state when scrolling
  const handleScroll = useLastCallback(() => {
    if (isScrollingProgrammatically) {
      return;
    }

    runThrottledForScroll(determineProfileState);
  });

  return { handleScroll };
}

function getStateFromTabType(tabType: ProfileTabType) {
  switch (tabType) {
    case 'members':
      return ProfileState.MemberList;
    case 'gifts':
      return ProfileState.GiftList;
    case 'stories':
      return ProfileState.StoryList;
    case 'dialogs':
      return ProfileState.SavedDialogs;
    default:
      return ProfileState.SharedMedia;
  }
}

function isMtpPeerUser(peer: TypePeerOrInput): peer is GramJs.PeerUser {
  return peer.hasOwnProperty('userId');
}

function isMtpPeerChat(peer: TypePeerOrInput): peer is GramJs.PeerChat {
  return peer.hasOwnProperty('chatId');
}

function isMtpPeerChannel(peer: TypePeerOrInput): peer is GramJs.PeerChannel {
  return peer.hasOwnProperty('channelId');
}

function buildApiPeerId(id: bigint, type: 'user' | 'chat' | 'channel') {
  if (type === 'user') {
    return id.toString();
  }

  if (type === 'channel') {
    return ((id + CHANNEL_ID_BASE) * -1n).toString();
  }

  return (id * -1n).toString();
}

function getApiChatIdFromMtpPeer(peer: TypePeerOrInput) {
  if (isMtpPeerUser(peer)) {
    return buildApiPeerId(peer.userId, 'user');
  } else if (isMtpPeerChat(peer)) {
    return buildApiPeerId(peer.chatId, 'chat');
  } else {
    return buildApiPeerId((peer as GramJs.InputPeerChannel).channelId, 'channel');
  }
}

function buildApiPeerColor(peerColor: GramJs.TypePeerColor): ApiTypePeerColor | undefined {
  if (peerColor instanceof GramJs.PeerColor) {
    const { color, backgroundEmojiId } = peerColor;
    return {
      type: 'regular',
      color,
      backgroundEmojiId: backgroundEmojiId?.toString(),
    };
  }

  if (peerColor instanceof GramJs.PeerColorCollectible) {
    const {
      collectibleId, giftEmojiId, backgroundEmojiId, accentColor, colors, darkAccentColor, darkColors,
    } = peerColor;
    return {
      type: 'collectible',
      giftEmojiId: giftEmojiId.toString(),
      collectibleId: collectibleId.toString(),
      backgroundEmojiId: backgroundEmojiId.toString(),
      accentColor: int2hex(accentColor),
      colors: colors.map((color) => int2hex(color)),
      darkAccentColor: darkAccentColor ? int2hex(darkAccentColor) : undefined,
      darkColors: darkColors?.map((color) => int2hex(color)),
    };
  }

  return undefined;
}

function buildApiPeerColorSet(colorSet: GramJs.help.PeerColorSet) {
  return colorSet.colors.map((color) => int2hex(color));
}

function buildApiPeerProfileColorSet(colorSet: GramJs.help.PeerColorProfileSet): ApiPeerProfileColorSet {
  return {
    paletteColors: colorSet.paletteColors.map((color) => int2hex(color)),
    bgColors: colorSet.bgColors.map((color) => int2hex(color)),
    storyColors: colorSet.storyColors.map((color) => int2hex(color)),
  };
}

function buildApiPeerColors(wrapper: GramJs.help.TypePeerColors): ApiPeerColors['general'] | undefined {
  if (!(wrapper instanceof GramJs.help.PeerColors)) return undefined;

  return buildCollectionByCallback(wrapper.colors, (color) => {
