function normalizeMessageCopyJson(node: TiptapJsonContent): TiptapJsonContent {
  if (node.type === 'emoji') {
    return {
      type: 'text',
      text: String(node.attrs?.emoji || node.attrs?.alt || '\u{FFFC}'),
      marks: node.marks,
    };
  }

  return {
    ...node,
    content: node.content?.map(normalizeMessageCopyJson),
  };
}

