async function processPhoneCallSignalingData(queued: QueuedPhoneCallSignalingData) {
  const { data } = queued;
  let global = getGlobal();
  if (global.phoneCall?.id !== queued.callId) {
    return;
  }

  let message;
  try {
    message = await callApi('decodePhoneCallData', { data });
  } catch (err) {
    logPhoneCallDebug('Failed to decode phone call signaling data', {
      error: err instanceof Error ? err.message : String(err),
      isSctp: isSctpSignalingData(data),
      length: data.length,
    });
    return;
  }

  global = getGlobal();
  const activeCall = global.phoneCall;
  if (activeCall?.id !== queued.callId) {
    return;
  }

  let packetCount = 0;
  if (activeCall) {
    try {
      const packets = await callApi('drainPhoneCallSignalingData');
      packetCount = packets?.length || 0;
      if (packets) {
        for (const packetData of packets) {
          await callApi('sendSignalingData', { data: packetData, call: activeCall });
        }
      }
    } catch (err) {
      logPhoneCallDebug('Failed to drain phone call signaling data', {
        error: err instanceof Error ? err.message : String(err),
        isSctp: isSctpSignalingData(data),
        length: data.length,
      });
    }
  }

  if (Array.isArray(message)) {
    for (const item of message) {
      await processSignalingMessage(item);
    }
  } else if (message) {
    await processSignalingMessage(message);
  } else if (!packetCount && !isSctpSignalingData(data)) {
    logPhoneCallDebug('Failed to decode phone call signaling data', {
      length: data.length,
    });
  }
}

function logPhoneCallDebug<Data extends object>(message: string, data: Data) {
  if (!DEBUG_CALLS) return;

  logDebugMessage('warn', `[PhoneCall] ${message}`, data);
}

function isSctpSignalingData(data: number[]) {
  return data.length >= 12
    && data[0] === 0x13
    && data[1] === 0x88
    && data[2] === 0x13
    && data[3] === 0x88;
}

pub(crate) fn update_window_title<R: Runtime>(
  window: Window<R>,
  title: String,
  traffic_position: LogicalPosition<f64>,
) {
  use cocoa::{appkit::NSWindow, base::nil, foundation::NSString};

  unsafe {
    let window_handle = UnsafeWindowHandle(window.ns_window().unwrap());

    let window2 = window.clone();
    let _ = window.run_on_main_thread(move || {
      let win_title = NSString::alloc(nil).init_str(&title);
      let handle = window_handle;
      NSWindow::setTitle_(handle.0 as cocoa::base::id, win_title);
      position_traffic_lights(
        UnsafeWindowHandle(window2.ns_window().expect("Failed to create window handle")),
        traffic_position,
      );
    });
  }
}

fn position_traffic_lights(ns_window_handle: UnsafeWindowHandle, position: LogicalPosition<f64>) {
  use cocoa::appkit::{NSView, NSWindow, NSWindowButton};
  use cocoa::foundation::NSRect;

  let x = position.x;
  let y = position.y;

  let ns_window = ns_window_handle.0 as cocoa::base::id;
  #[allow(unexpected_cfgs)]
  unsafe {
    let close = ns_window.standardWindowButton_(NSWindowButton::NSWindowCloseButton);
    let miniaturize = ns_window.standardWindowButton_(NSWindowButton::NSWindowMiniaturizeButton);
    let zoom = ns_window.standardWindowButton_(NSWindowButton::NSWindowZoomButton);

    let title_bar_container_view = close.superview().superview();

    let close_rect: NSRect = msg_send![close, frame];
    let button_height = close_rect.size.height;

    let title_bar_frame_height = button_height + y;
    let mut title_bar_rect = NSView::frame(title_bar_container_view);
    title_bar_rect.size.height = title_bar_frame_height;
    title_bar_rect.origin.y = NSView::frame(ns_window).size.height - title_bar_frame_height;
    let _: () = msg_send![title_bar_container_view, setFrame: title_bar_rect];

    let window_buttons = vec![close, miniaturize, zoom];
    let space_between = NSView::frame(miniaturize).origin.x - NSView::frame(close).origin.x;

    for (i, button) in window_buttons.into_iter().enumerate() {
      let mut rect: NSRect = NSView::frame(button);
      rect.origin.x = x + (i as f64 * space_between);
      button.setFrameOrigin(rect.origin);
    }
  }
}

struct WindowState<R: Runtime> {
  window: Window<R>,
  // Store desired position of traffic lights to avoid capturing external env in callbacks
  traffic_position: LogicalPosition<f64>,
}

pub fn setup_traffic_light_positioner<R: Runtime>(
  window: &Window<R>,
  traffic_position: LogicalPosition<f64>,
) {
  use cocoa::appkit::NSWindow;
  use cocoa::base::{BOOL, id};
  use cocoa::delegate;
  use cocoa::foundation::NSUInteger;
  use objc::runtime::{Object, Sel};
  use rand::distr::{Alphanumeric, Distribution};
  use std::ffi::c_void;

  position_traffic_lights(
    UnsafeWindowHandle(window.ns_window().expect("Failed to create window handle")),
    traffic_position,
  );

  // Ensure they stay in place while resizing the window.
  fn with_window_state<R: Runtime, F: FnOnce(&mut WindowState<R>) -> T, T>(this: &Object, func: F) {
    let ptr = unsafe {
      let x: *mut c_void = *this.get_ivar("app_box");
      &mut *(x as *mut WindowState<R>)
    };
    func(ptr);
  }

  #[allow(unexpected_cfgs)]
  unsafe {
    let ns_win = window
      .ns_window()
      .expect("NS Window should exist to mount traffic light delegate.") as id;

    let current_delegate: id = ns_win.delegate();

    extern "C" fn on_window_should_close(this: &Object, _cmd: Sel, sender: id) -> BOOL {
      unsafe {
        let super_del: id = *this.get_ivar("super_delegate");
        msg_send![super_del, windowShouldClose: sender]
      }
    }
    extern "C" fn on_window_will_close(this: &Object, _cmd: Sel, notification: id) {
      unsafe {
        let super_del: id = *this.get_ivar("super_delegate");
        let _: () = msg_send![super_del, windowWillClose: notification];
      }
    }
    extern "C" fn on_window_did_resize<R: Runtime>(this: &Object, _cmd: Sel, notification: id) {
      unsafe {
        with_window_state(&*this, |state: &mut WindowState<R>| {
          let position = if let Ok(states) = crate::window::WINDOW_STATES.lock() {
            if let Some(ws) = states.get(state.window.label()) {
              if ws.is_overlay {
                if ws.is_mobile {
                  *crate::TRAFFIC_LIGHT_POSITION_OVERLAY_MOBILE
                } else {
                  *crate::TRAFFIC_LIGHT_POSITION_OVERLAY
                }
              } else {
                crate::TRAFFIC_LIGHT_POSITION_DEFAULT
              }
            } else {
              state.traffic_position
            }
          } else {
            state.traffic_position
          };

          let id = state
            .window
            .ns_window()
            .expect("NS window should exist on state to handle resize") as id;

          position_traffic_lights(
            UnsafeWindowHandle(id as *mut c_void),
            position,
          );
        });

        let super_del: id = *this.get_ivar("super_delegate");
        let _: () = msg_send![super_del, windowDidResize: notification];
      }
    }
    extern "C" fn on_window_did_move(this: &Object, _cmd: Sel, notification: id) {
      unsafe {
        let super_del: id = *this.get_ivar("super_delegate");
        let _: () = msg_send![super_del, windowDidMove: notification];
      }
    }
    extern "C" fn on_window_did_change_backing_properties(
      this: &Object,
      _cmd: Sel,
      notification: id,
    ) {
      unsafe {
        let super_del: id = *this.get_ivar("super_delegate");
        let _: () = msg_send![super_del, windowDidChangeBackingProperties: notification];
      }
    }
    extern "C" fn on_window_did_become_key(this: &Object, _cmd: Sel, notification: id) {
      unsafe {
        let super_del: id = *this.get_ivar("super_delegate");
        let _: () = msg_send![super_del, windowDidBecomeKey: notification];
      }
    }
    extern "C" fn on_window_did_resign_key(this: &Object, _cmd: Sel, notification: id) {
      unsafe {
        let super_del: id = *this.get_ivar("super_delegate");
        let _: () = msg_send![super_del, windowDidResignKey: notification];
      }
    }
    extern "C" fn on_dragging_entered(this: &Object, _cmd: Sel, notification: id) -> BOOL {
      unsafe {
        let super_del: id = *this.get_ivar("super_delegate");
        msg_send![super_del, draggingEntered: notification]
      }
    }
    extern "C" fn on_prepare_for_drag_operation(
      this: &Object,
      _cmd: Sel,
      notification: id,
    ) -> BOOL {
      unsafe {
        let super_del: id = *this.get_ivar("super_delegate");
        msg_send![super_del, prepareForDragOperation: notification]
      }
    }
    extern "C" fn on_perform_drag_operation(this: &Object, _cmd: Sel, sender: id) -> BOOL {
      unsafe {
        let super_del: id = *this.get_ivar("super_delegate");
        msg_send![super_del, performDragOperation: sender]
      }
    }
    extern "C" fn on_conclude_drag_operation(this: &Object, _cmd: Sel, notification: id) {
      unsafe {
        let super_del: id = *this.get_ivar("super_delegate");
        let _: () = msg_send![super_del, concludeDragOperation: notification];
      }
    }
    extern "C" fn on_dragging_exited(this: &Object, _cmd: Sel, notification: id) {
      unsafe {
        let super_del: id = *this.get_ivar("super_delegate");
        let _: () = msg_send![super_del, draggingExited: notification];
      }
    }
    extern "C" fn on_window_will_use_full_screen_presentation_options(
      this: &Object,
      _cmd: Sel,
      window: id,
      proposed_options: NSUInteger,
    ) -> NSUInteger {
      unsafe {
        let super_del: id = *this.get_ivar("super_delegate");
        msg_send![super_del, window: window willUseFullScreenPresentationOptions: proposed_options]
      }
    }
    extern "C" fn on_window_did_enter_full_screen<R: Runtime>(
      this: &Object,
      _cmd: Sel,
      notification: id,
    ) {
      unsafe {
        with_window_state(&*this, |state: &mut WindowState<R>| {
          state
            .window
            .emit("did-enter-fullscreen", ())
            .expect("Failed to emit event");
        });

        let super_del: id = *this.get_ivar("super_delegate");
        let _: () = msg_send![super_del, windowDidEnterFullScreen: notification];
      }
    }
    extern "C" fn on_window_will_enter_full_screen<R: Runtime>(
      this: &Object,
      _cmd: Sel,
      notification: id,
    ) {
      unsafe {
        with_window_state(&*this, |state: &mut WindowState<R>| {
          state
            .window
            .emit("will-enter-fullscreen", ())
            .expect("Failed to emit event");
        });

