function initEventStreams(runtime: TgPluginRuntime) {
  disposeEventStreams();
  // Baseline the active chat so the first emission happens only on a real change.
  lastChatId = runtime.getActiveChatId();

  streamUnsubscribers = [
    runtime.subscribeApiUpdates((update) => {
      // This handler runs in the same `'apiUpdate'` dispatch as the native
      // reducers and may run before them, so payloads are mapped from the
      // update object, never from store reads.
      switch (update['@type']) {
        case 'newMessage':
          emitPluginEvent('message:new', {
            chatId: update.chatId,
            messageId: update.id,
            message: update.message,
          });
          break;
        case 'updateMessage':
          emitPluginEvent('message:edited', {
            chatId: update.chatId,
            messageId: update.id,
            // The source update carries only the updated fields, so `message` is partial.
            message: update.message,
          });
          break;
        case 'deleteMessages':
          emitPluginEvent('message:deleted', {
            chatId: update.chatId,
            messageIds: update.ids,
          });
          break;
      }
    }),
    runtime.subscribeToStoreChanges(() => {
      // Store-change notifications are throttled to tick end and deferred
      // during heavy animations, so `chat:opened` can lag the navigation.
      const chatId = runtime.getActiveChatId();
      if (chatId === lastChatId) return;

      lastChatId = chatId;
      emitPluginEvent('chat:opened', { chatId });
    }),
  ];
}

function disposeEventStreams() {
  for (const unsubscribe of streamUnsubscribers) {
    unsubscribe();
  }
  streamUnsubscribers = [];
}

function emitPluginEvent<Event extends TgEventName>(name: Event, payload: TgEventPayloads[Event]) {
  const handlers = handlersByEvent.get(name);
  if (!handlers) return;

  // Copy: a handler may unsubscribe (itself or others) during dispatch.
  for (const entry of [...handlers]) {
    entry.run(payload);
  }
}

function subscribePluginEvent<Event extends TgEventName>(
  event: Event,
  handler: (payload: TgEventPayloads[Event]) => void,
  context: PluginContext,
): () => void {
  const wrapped = context.wrap(handler);
  // Handlers are stored type-erased; the event/handler pairing is checked at this boundary.
  const entry: EventHandlerEntry = {
    pluginName: context.pluginName,
    run: (payload) => wrapped(payload as TgEventPayloads[Event]),
  };

  getOrCreateHandlers(event).add(entry);

  return () => {
    handlersByEvent.get(event)?.delete(entry);
  };
}

function removePluginEventHandlers(pluginName: string) {
  for (const handlers of handlersByEvent.values()) {
    for (const entry of handlers) {
      if (entry.pluginName === pluginName) {
        handlers.delete(entry);
      }
    }
  }
}

function countPluginEventHandlers(): number {
  let total = 0;
  for (const handlers of handlersByEvent.values()) {
    total += handlers.size;
  }
  return total;
}

function getOrCreateHandlers(event: TgEventName): Set<EventHandlerEntry> {
  let handlers = handlersByEvent.get(event);
  if (!handlers) {
    handlers = new Set();
    handlersByEvent.set(event, handlers);
  }
  return handlers;
}

function getPlatform() {
  const { userAgent, platform } = window.navigator;

  const iosPlatforms = ['iPhone', 'iPad', 'iPod'];
  if (
    iosPlatforms.indexOf(platform) !== -1
    // For new IPads with M1 chip and IPadOS platform returns "MacIntel"
    || (platform === 'MacIntel' && ('maxTouchPoints' in navigator && navigator.maxTouchPoints > 2))
  ) return 'iOS';

  const macosPlatforms = ['Macintosh', 'MacIntel', 'MacPPC', 'Mac68K'];
  if (macosPlatforms.indexOf(platform) !== -1) return 'macOS';

  const windowsPlatforms = ['Win32', 'Win64', 'Windows', 'WinCE'];
  if (windowsPlatforms.indexOf(platform) !== -1) return 'Windows';

  if (/Android/.test(userAgent)) return 'Android';

  if (/Linux/.test(platform)) return 'Linux';

  return undefined;
}

function isLastEmojiVersionSupported() {
  const ALLOWABLE_CALCULATION_ERROR_SIZE = 5;
  const inlineEl = document.createElement('span');
  inlineEl.classList.add('emoji-test-element');
  document.body.appendChild(inlineEl);

  inlineEl.innerText = '🧑‍🩰'; // Emoji from 17.0 version
  const newEmojiWidth = inlineEl.offsetWidth;
  inlineEl.innerText = '❤️'; // Emoji from 1.0 version
  const legacyEmojiWidth = inlineEl.offsetWidth;

  document.body.removeChild(inlineEl);

  return Math.abs(newEmojiWidth - legacyEmojiWidth) < ALLOWABLE_CALCULATION_ERROR_SIZE;
}

function checkSvgFilterCalcSupport() {
  const SVG_FILTER_CALC_TEST_VALUE = 'calc(100% - 1px)';

  const svg = document.createElementNS(SVG_NAMESPACE, 'svg');
  const filter = document.createElementNS(SVG_NAMESPACE, 'filter');
  const testPrimitive = document.createElementNS(SVG_NAMESPACE, 'feFlood');

  svg.setAttribute('width', '0');
  svg.setAttribute('height', '0');
  testPrimitive.setAttribute('y', SVG_FILTER_CALC_TEST_VALUE);
  filter.appendChild(testPrimitive);
  svg.appendChild(filter);

  try {
    document.body.appendChild(svg);
    return testPrimitive.y.baseVal.valueAsString === SVG_FILTER_CALC_TEST_VALUE;
  } catch {
    return false;
  } finally {
    svg.remove();
  }
}

