function useTauriEvent<T>(name: string, callback: (event: Event<T>) => void) {
  return useEffect(() => {
    if (!IS_TAURI) {
      return undefined;
    }

    let removeListener: VoidFunction | undefined;

    const setUpListener = async () => {
      const { listen } = await import('@tauri-apps/api/event');
      removeListener = await listen<T>(name, (event) => {
        callback(event);
      });
    };

    setUpListener().catch((error) => {
      // eslint-disable-next-line no-console
      console.error(`Could not set up window event listener. ${error}`);
    });

    return () => {
      removeListener?.();
    };
  }, [name, callback]);
}

function bytesToDataUri(bytes: Uint8Array, shouldOmitPrefix = false, mimeType: string = 'image/jpeg') {
  const prefix = shouldOmitPrefix ? '' : `data:${mimeType};base64,`;

  return `${prefix}${btoa(String.fromCharCode(...bytes))}`;
}

function omitVirtualClassFields<T extends GramJs.VirtualClass<T> & { flags?: unknown }>(
