function requestMeasure(cb: NoneToVoidFunction) {
  pendingMeasureTasks.push(cb);
  runUpdatePassOnRaf();
}

function requestMutation(cb: NoneToVoidFunction) {
  pendingMutationTasks.push(cb);
  runUpdatePassOnRaf();
}

function requestNextMutation(cb: () => (NoneToVoidFunction | void)) {
  requestMeasure(() => {
    requestMutation(cb);
  });
}

function requestForcedReflow(cb: () => (NoneToVoidFunction | void)) {
