function throttleWithRafFallback<F extends AnyToVoidFunction>(fn: F) {
  return throttleWith((throttledFn: NoneToVoidFunction) => {
    fastRaf(throttledFn, true);
  }, fn);
}

function getStripeError(error: {
  code: string;
  message: string;
  param?: string;
}) {
  const { message: description, code, param } = error;
  const { field, message } = param ? STRIPE_ERRORS[param] : STRIPE_ERRORS[code];

  return { field, message, description };
