function usePopupLimit(sequentialLimit: number, resetAfter: number) {
  const [unlockPopupsAt, setUnlockPopupsAt] = useState(0);
  const sequentialCallsRef = useRef(0);
  const lastClosedDateRef = useRef(0);

  const handlePopupOpened = useLastCallback(() => {
    const now = Date.now();

    if (now - lastClosedDateRef.current > resetAfter) {
      sequentialCallsRef.current = 0;
    }

    sequentialCallsRef.current += 1;

    if (sequentialCallsRef.current >= sequentialLimit) {
      setUnlockPopupsAt(now + resetAfter);
    }
  });

  const handlePopupClosed = useLastCallback(() => {
    if (unlockPopupsAt < Date.now()) { // Prevent confused user from extending lock time
      lastClosedDateRef.current = Date.now();
    }
  });

  return {
    unlockPopupsAt,
    handlePopupOpened,
    handlePopupClosed,
  };
}

function resetStorage() {
  if (resetStoragePromise) return resetStoragePromise;

  clearStoredSession(ACCOUNT_SLOT);
  const hasAccounts = Boolean(Object.values(getAccountsInfo()).length);
  const clearSharedStatePromise = hasAccounts ? Promise.resolve() : removeSharedStateFromCache();

  resetStoragePromise = Promise.all([
    clearEncryptedSession(),
    removeGlobalFromCache(),
    clearSharedStatePromise,
  ]).then(() => hasAccounts).finally(() => {
    resetStoragePromise = undefined;
  });

  return resetStoragePromise;
}

function createWorkerInterface(api: ApiConfig, channel?: string) {
  let pendingPayloads: WorkerPayload[] = [];
  let pendingTransferables: Transferable[] = [];

  const sendToOriginOnTickEnd = throttleWithTickEnd(() => {
    const data = { channel, payloads: pendingPayloads };
    const transferables = pendingTransferables;

    pendingPayloads = [];
    pendingTransferables = [];

    if (transferables.length) {
      postMessage(data, transferables);
    } else {
      postMessage(data);
    }
  });

  function sendToOrigin(payload: WorkerPayload, transferables?: Transferable[]) {
    pendingPayloads.push(payload);

    if (transferables) {
      pendingTransferables.push(...transferables);
    }

    sendToOriginOnTickEnd();
  }

  handleErrors(sendToOrigin);

  messageHandlers.addCallback((message: OriginMessageEvent) => {
    if (message.data?.channel === channel) {
      onMessage(api, message.data, sendToOrigin);
    }
  });
}

function sendToOrigin(payload: WorkerPayload, transferables?: Transferable[]) {
    pendingPayloads.push(payload);

    if (transferables) {
      pendingTransferables.push(...transferables);
    }

    sendToOriginOnTickEnd();
  }

function onMessage(
  api: ApiConfig,
  data: OriginMessageData,
  sendToOrigin: SendToOrigin,
  onUpdate?: (update: ApiUpdate) => void,
) {
  if (!onUpdate) {
    onUpdate = (update: ApiUpdate) => {
      sendToOrigin({
        type: 'update',
        update,
      });
    };
  }

  data.payloads.forEach(async (payload) => {
    switch (payload.type) {
      case 'init': {
        const { args } = payload;
        if (typeof api === 'function') {
          await api('init', onUpdate, ...args);
        } else {
          await api.init?.(onUpdate, ...args);
        }

        break;
      }

      case 'callMethod': {
        const {
          messageId, name, args, withCallback,
        } = payload;

        try {
          if (typeof api !== 'function' && !api[name]) return;

          if (messageId && withCallback) {
            const callback = (...callbackArgs: any[]) => {
              const lastArg = callbackArgs[callbackArgs.length - 1];

              sendToOrigin({
                type: 'methodCallback',
                messageId,
                callbackArgs,
              }, isTransferable(lastArg) ? [lastArg] : undefined);
            };

            callbackState.set(messageId, callback);

            args.push(callback as never);
          }

          const response = typeof api === 'function'
            ? await api(name, ...args)
            : await api[name](...args);
          const { arrayBuffer } = (typeof response === 'object' && 'arrayBuffer' in response && response) || {};
          if (messageId) {
            sendToOrigin(
              {
                type: 'methodResponse',
                messageId,
                response,
              },
              arrayBuffer ? [arrayBuffer] : undefined,
            );
          }
        } catch (error: any) {
          if (DEBUG) {
            // eslint-disable-next-line no-console
            console.error(error);
          }

          if (messageId) {
            sendToOrigin({
              type: 'methodResponse',
              messageId,
              error: { message: error.message },
            });
          }
        }

        if (messageId) {
          callbackState.delete(messageId);
        }

        break;
      }

      case 'cancelProgress': {
        const callback = callbackState.get(payload.messageId);
        if (callback) {
          callback.isCanceled = true;
        }

        break;
      }
    }
  });
}

function isTransferable(obj: any) {
  return obj instanceof ArrayBuffer || obj instanceof ImageBitmap;
}

function handleErrors(sendToOrigin: SendToOrigin) {
  self.onerror = (e) => {
    // eslint-disable-next-line no-console
    console.error(e);
    sendToOrigin({ type: 'unhandledError', error: { message: e.error.message || 'Uncaught exception in worker' } });
  };

  self.addEventListener('unhandledrejection', (e) => {
    // eslint-disable-next-line no-console
    console.error(e);
    sendToOrigin({ type: 'unhandledError', error: { message: e.reason.message || 'Uncaught rejection in worker' } });
  });
}

function createCallbackManager<T extends AnyToVoidFunction = AnyToVoidFunction>() {
  const callbacks = new Set<T>();

  function addCallback(cb: T) {
    callbacks.add(cb);

    return () => {
      removeCallback(cb);
    };
  }

  function removeCallback(cb: T) {
    callbacks.delete(cb);
  }

  function runCallbacks(...args: Parameters<T>) {
    callbacks.forEach((callback) => {
      callback(...args);
    });
  }

  function hasCallbacks() {
    return Boolean(callbacks.size);
  }

  return {
    runCallbacks,
    addCallback,
    removeCallback,
    hasCallbacks,
  };
}

