function useStoryProps(
  story?: ApiTypeStory, isCurrentUserPremium = false, isDropdownMenuOpen = false,
) {
  const isLoadedStory = story && 'content' in story;
  const isDeletedStory = story && 'isDeleted' in story;
  const hasText = isLoadedStory ? hasMessageText(story) : false;
  const hasForwardInfo = isLoadedStory && Boolean(story.forwardInfo);

  let thumbnail: string | undefined;
  if (isLoadedStory) {
    if (story.content.photo?.thumbnail) {
      thumbnail = story.content.photo.thumbnail.dataUri;
    }
    if (story.content.video?.thumbnail?.dataUri) {
      thumbnail = story.content.video.thumbnail.dataUri;
    }
  }

  const previewHash = isLoadedStory ? getStoryMediaHash(story) : undefined;
  const previewBlobUrl = useMedia(previewHash);
  const isVideo = Boolean(isLoadedStory && story.content.video);
  const noSound = isLoadedStory && story.content.video?.noSound;
  const fullMediaHash = isLoadedStory ? getStoryMediaHash(story, 'full') : undefined;
  const fullMediaData = useMedia(fullMediaHash, !story, isVideo ? ApiMediaFormat.Progressive : ApiMediaFormat.BlobUrl);
  const altMediaHash = isVideo && isLoadedStory ? getStoryMediaHash(story, 'full', true) : undefined;
  const altMediaData = useMedia(altMediaHash, !story, ApiMediaFormat.Progressive);

  const hasFullData = Boolean(fullMediaData || altMediaData);
  const bestImageData = isVideo ? previewBlobUrl : fullMediaData || previewBlobUrl;
  const hasThumb = !previewBlobUrl && !hasFullData;

  const canDownload = isCurrentUserPremium && isLoadedStory && !story.noForwards;
  const downloadHash = isLoadedStory ? getStoryMediaHash(story, 'download') : undefined;
  const downloadMediaData = useMedia(downloadHash, !canDownload && !isDropdownMenuOpen);

  return {
    isLoadedStory,
    isDeletedStory,
    hasText,
    hasForwardInfo,
    thumbnail,
    previewHash,
    previewBlobUrl,
    isVideo,
    noSound,
    fullMediaHash,
    fullMediaData,
    altMediaHash,
    altMediaData,
    hasFullData,
    bestImageData,
    hasThumb,
    canDownload,
    downloadMediaData,
  };
}

async function copyTextToClipboardFromPromise(
  getContentPromise: Promise<string | ClipboardTextContent | undefined>,
  onSuccess?: NoneToVoidFunction,
  onFailure?: NoneToVoidFunction,
  textFormat?: ClipboardTextFormat,
) {
  const contentPromise = getContentPromise.then((content) => {
    if (!content) throw new Error('EMPTY_CLIPBOARD_CONTENT');
    return typeof content === 'string'
      ? { plainText: content, html: content, markdown: content }
      : content;
  });
  try {
    if (!CLIPBOARD_ITEM_SUPPORTED || !navigator.clipboard.write) throw new Error('CLIPBOARD_ITEM_UNSUPPORTED');

    if (textFormat) {
      const plainTextPromise = contentPromise.then((content) => content[textFormat]);
      await navigator.clipboard.write([buildPlainTextClipboardItem(plainTextPromise)]);
    } else {
      const canWriteMarkdown = !ClipboardItem.supports || ClipboardItem.supports('text/markdown');
      await navigator.clipboard.write([buildTextClipboardItem(contentPromise, canWriteMarkdown)]);
    }
  } catch {
    try {
      const content = await contentPromise;
      if (!textFormat && CLIPBOARD_ITEM_SUPPORTED) {
        try {
          await navigator.clipboard.write([buildTextClipboardItem(content)]);
          onSuccess?.();
          return;
        } catch {
          // Fall through to the synchronous plain-text fallback
        }
      }
      if (!copyTextToClipboard(textFormat ? content[textFormat] : content.plainText)) {
        throw new Error('CLIPBOARD_WRITE_FAILED');
      }
    } catch {
      onFailure?.();
      return;
    }
  }

  onSuccess?.();
}

function buildPlainTextClipboardItem(content: string | Promise<string>) {
  return new ClipboardItem({
    'text/plain': buildPlainTextClipboardBlob(content),
  });
}

function buildTextClipboardItem(
  content: ClipboardTextContent | Promise<ClipboardTextContent>,
  withMarkdown = false,
) {
  const data: Record<string, Blob | Promise<Blob>> = {
    'text/plain': buildClipboardBlob(content, 'plainText', 'text/plain'),
    'text/html': buildClipboardBlob(content, 'html', 'text/html'),
  };
  if (withMarkdown) {
    data['text/markdown'] = buildClipboardBlob(content, 'markdown', 'text/markdown');
  }

  return new ClipboardItem(data);
}

function buildClipboardBlob(
  content: ClipboardTextContent | Promise<ClipboardTextContent>,
  key: keyof ClipboardTextContent,
  type: string,
): Blob | Promise<Blob> {
  if (content instanceof Promise) return content.then((value) => buildClipboardBlob(value, key, type));
  const value = content[key];
  if (!content.plainText) throw new Error('EMPTY_CLIPBOARD_CONTENT');
  return new Blob([value], { type });
}

function buildPlainTextClipboardBlob(content: string | Promise<string>): Blob | Promise<Blob> {
  if (content instanceof Promise) return content.then(buildPlainTextClipboardBlob);
  if (!content) throw new Error('EMPTY_CLIPBOARD_CONTENT');
  return new Blob([content], { type: 'text/plain' });
}

async function copyBlobToClipboard(pngBlob: Blob | null) {
  if (!pngBlob || !CLIPBOARD_ITEM_SUPPORTED) {
    return;
  }

  try {
    await window.navigator.clipboard.write?.([
      new ClipboardItem({
        [pngBlob.type]: pngBlob,
      }),
    ]);
  } catch (error) {
    if (DEBUG) {
      // eslint-disable-next-line no-console
      console.error(error);
    }
  }
}

