async function resolveMediaDuration(media: HTMLVideoElement) {
  await new Promise<void>((resolve, reject) => {
    media.onloadedmetadata = () => resolve();
    media.onerror = () => reject(new Error('Failed to load recording snapshot'));
  });

  if (Number.isFinite(media.duration)) return;

  await new Promise<void>((resolve) => {
    const timeoutId = setTimeout(() => finish(), PLAYBACK_DURATION_TIMEOUT_MS);
    function finish() {
      clearTimeout(timeoutId);
      media.removeEventListener('durationchange', handleDurationChange);
      media.currentTime = 0;
      resolve();
    }
    function handleDurationChange() {
      if (Number.isFinite(media.duration)) {
        finish();
      }
    }
    media.addEventListener('durationchange', handleDurationChange);
    media.currentTime = Number.MAX_SAFE_INTEGER;
  });
}

function finish() {
      clearTimeout(timeoutId);
      media.removeEventListener('durationchange', handleDurationChange);
      media.currentTime = 0;
      resolve();
    }

function handleDurationChange() {
      if (Number.isFinite(media.duration)) {
        finish();
      }
    }

async function createWatermarkCanvas() {
  const canvas = document.createElement('canvas');
  canvas.width = ROUND_VIDEO_RECORDING_SIZE;
  canvas.height = ROUND_VIDEO_RECORDING_SIZE;
  const ctx = canvas.getContext('2d')!;

  ctx.fillStyle = `rgba(255, 255, 255, ${WATERMARK_ALPHA})`;
  const planeScale = WATERMARK_PLANE_SIZE / WATERMARK_PLANE_VIEWBOX;
  ctx.save();
  ctx.translate(WATERMARK_PLANE_CENTER_X, WATERMARK_PLANE_CENTER_Y);
  ctx.scale(planeScale, planeScale);
  ctx.translate(-WATERMARK_PLANE_VIEWBOX / 2, -WATERMARK_PLANE_VIEWBOX / 2);
  ctx.fill(new Path2D(WATERMARK_PLANE_PATH));
  ctx.restore();

  const arcRadius = WATERMARK_TEXT_ARC_RADIUS;
  const startOffset = arcRadius * (Math.PI - WATERMARK_TEXT_CENTER_ANGLE);
  const arcPath = `M ${CANVAS_RADIUS - arcRadius} ${CANVAS_RADIUS}`
    + ` A ${arcRadius} ${arcRadius} 0 0 0 ${CANVAS_RADIUS + arcRadius} ${CANVAS_RADIUS}`;
  const svg = `<svg xmlns="http://www.w3.org/2000/svg"`
    + ` width="${ROUND_VIDEO_RECORDING_SIZE}" height="${ROUND_VIDEO_RECORDING_SIZE}">`
    + `<path id="arc" fill="none" d="${arcPath}"/>`
    + `<text fill="rgba(255,255,255,${WATERMARK_ALPHA})" font-family="Roboto, Arial, sans-serif"`
    + ` font-size="${WATERMARK_FONT_PX}" font-weight="600" letter-spacing="${WATERMARK_LETTER_SPACING}"`
    + ` text-anchor="middle"><textPath href="#arc" startOffset="${startOffset}">${WATERMARK_TEXT}</textPath>`
    + '</text></svg>';

  try {
    const img = new Image();
    await new Promise<void>((resolve, reject) => {
      img.onload = () => resolve();
      img.onerror = () => reject(new Error('Failed to rasterize watermark text'));
      img.src = `data:image/svg+xml;charset=utf-8,${encodeURIComponent(svg)}`;
    });
    ctx.drawImage(img, 0, 0);
  } catch (err) {
    // No curved text if the SVG fails to rasterize — the plane glyph alone is enough
  }

  return canvas;
}

async function waitForVisibleFrame(videoEl: HTMLVideoElement) {
  const sampleCanvas = document.createElement('canvas');
  sampleCanvas.width = SAMPLE_SIZE;
  sampleCanvas.height = SAMPLE_SIZE;
  const sampleCtx = sampleCanvas.getContext('2d', { willReadFrequently: true });
  if (!sampleCtx) return;

  const liveDeadline = Date.now() + VISIBLE_FRAME_TIMEOUT_MS;
  const sampledValuesCount = SAMPLE_SIZE * SAMPLE_SIZE * 3;
  let previousData: Uint8ClampedArray | undefined;
  let previousMean: number | undefined;
  let settleDeadline: number | undefined;
  let isLive = false;
  let settledFrames = 0;

  await new Promise<void>((resolve) => {
    const check = () => {
      // The warm-up (black frames) and the exposure ramp each get their own budget — a shared one would run
      // out during the ramp on a cold camera start and bake the brightness pumping into the clip
      const now = Date.now();
      if (isLive ? now >= settleDeadline! : now >= liveDeadline) {
        resolve();
        return;
      }

      if (videoEl.videoWidth) {
        sampleCtx.drawImage(videoEl, 0, 0, SAMPLE_SIZE, SAMPLE_SIZE);
        const { data } = sampleCtx.getImageData(0, 0, SAMPLE_SIZE, SAMPLE_SIZE);
        let sum = 0;
        let changeSum = 0;
        for (let i = 0; i < data.length; i += 4) {
          sum += data[i] + data[i + 1] + data[i + 2];
          if (previousData) {
            changeSum += Math.abs(data[i] - previousData[i])
              + Math.abs(data[i + 1] - previousData[i + 1])
              + Math.abs(data[i + 2] - previousData[i + 2]);
          }
        }

        const mean = sum / sampledValuesCount;
        const isBrightEnough = mean > MIN_VISIBLE_LUMINANCE;
        const hasChanged = previousData && changeSum / sampledValuesCount > MIN_FRAME_CHANGE;
        if (!isLive && (isBrightEnough || hasChanged)) {
          isLive = true;
          settleDeadline = Date.now() + EXPOSURE_SETTLE_TIMEOUT_MS;
        }

        if (isLive && previousMean !== undefined) {
          if (Math.abs(mean - previousMean) < EXPOSURE_SETTLE_MAX_DELTA) {
            settledFrames++;
            if (settledFrames >= EXPOSURE_SETTLE_FRAMES) {
              resolve();
              return;
            }
          } else {
            settledFrames = 0;
          }
        }

        previousMean = mean;
        previousData = data;
      }

      requestAnimationFrame(check);
    };
    check();
  });
}

function isOpenedFromMediaViewer() {
  return Boolean(document.getElementById('MediaViewer')?.querySelector(MEDIA_VIEWER_SLIDE_SELECTOR));
}

function isTextBox(target: EventTarget | null) {
  if (!target || !(target instanceof HTMLElement)) return false;
  const element = target;
  const tagName = element.tagName.toLowerCase();
  if (tagName === 'textarea') return true;
  if (tagName !== 'input') return false;
  const type = element.getAttribute('type');
  if (!type) return false;
  const inputTypes = [
    'text', 'password', 'number', 'email', 'tel', 'url',
    'search', 'date', 'datetime', 'datetime-local', 'time', 'month', 'week',
  ];
  return inputTypes.indexOf(type.toLowerCase()) > -1;
}

function preventDefaultForScrollKeys(e: KeyboardEvent) {
  if (IGNORED_KEYS[e.key] && !isTextBox(e.target)) {
    e.preventDefault();
  }
}

function disableScrolling(el?: HTMLElement | null, _excludedClosestSelector?: string) {
  scrollLockEl = el;
  excludedClosestSelector = _excludedClosestSelector;
  // Disable scrolling in Chrome
  document.addEventListener('wheel', preventDefault, { passive: false });
  document.addEventListener('touchmove', preventDefault, { passive: false });
  document.onkeydown = preventDefaultForScrollKeys;

  return enableScrolling;
}

function enableScrolling() {
  scrollLockEl = undefined;
  excludedClosestSelector = undefined;
  document.removeEventListener('wheel', preventDefault); // Enable scrolling in Chrome
  document.removeEventListener('touchmove', preventDefault);
  // eslint-disable-next-line no-null/no-null
  document.onkeydown = null;
}

function buildInputPasskeyCredential(
  credentialJson: RegistrationResponseJSON | AuthenticationResponseJSON,
): GramJs.TypeInputPasskeyCredential {
  let response: GramJs.TypeInputPasskeyResponse;
  const clientData = base64UrlToString(credentialJson.response.clientDataJSON);
  if ('attestationObject' in credentialJson.response) {
    response = new GramJs.InputPasskeyResponseRegister({
      clientData: new GramJs.DataJSON({ data: clientData }),
      attestationData: base64UrlToBuffer(credentialJson.response.attestationObject),
    });
  } else {
    const userHandle = base64UrlToString(credentialJson.response.userHandle!);

    response = new GramJs.InputPasskeyResponseLogin({
      clientData: new GramJs.DataJSON({ data: clientData }),
      authenticatorData: base64UrlToBuffer(credentialJson.response.authenticatorData),
      signature: base64UrlToBuffer(credentialJson.response.signature),
      userHandle,
    });
  }

  return new GramJs.InputPasskeyCredentialPublicKey({
    id: credentialJson.id,
    rawId: credentialJson.rawId,
    response,
  });
}

function useAttachmentModal({
  attachments,
  fileSizeLimit,
  setAttachments,
  chatId,
  canAttachFiles,
  canSendAudios,
  canSendVideos,
  canSendPhotos,
  canSendDocuments,
  editedMessage,
  shouldSendInHighQuality,
}: {
  attachments: ApiAttachment[];
  fileSizeLimit: number;
  setAttachments: (attachments: ApiAttachment[]) => void;
  chatId: string;
  canAttachFiles: boolean;
  canSendAudios?: boolean;
  canSendVideos?: boolean;
  canSendPhotos?: boolean;
  canSendDocuments?: boolean;
  editedMessage: ApiMessage | undefined;
  shouldSendInHighQuality?: boolean;
}) {
  const lang = useLang();
  const { openLimitReachedModal, showAllowedMessageTypesNotification, showNotification } = getActions();
  const [shouldForceAsFile, setShouldForceAsFile] = useState<boolean>(false);
  const [shouldForceCompression, setShouldForceCompression] = useState<boolean>(false);

  const handleClearAttachments = useLastCallback(() => {
    setAttachments(MEMO_EMPTY_ARRAY);
  });

  const handleSetAttachments = useLastCallback(
    (newValue: ApiAttachment[] | ((current: ApiAttachment[]) => ApiAttachment[])) => {
      const newAttachments = typeof newValue === 'function' ? newValue(attachments) : newValue;
      if (!newAttachments.length) {
        handleClearAttachments();
        return;
      }

      if (!canAttachFiles) {
        return;
      }

      if (newAttachments.some((attachment) => {
        const type = getAttachmentMediaType(attachment);

        return (type === 'audio' && !canSendAudios && !canSendDocuments)
          || (type === 'video' && !canSendVideos && !canSendDocuments)
          || (type === 'photo' && !canSendPhotos && !canSendDocuments)
          || (type === 'file' && !canSendDocuments);
      })) {
        showAllowedMessageTypesNotification({ chatId });
      } else if (newAttachments.some(({ size }) => size > fileSizeLimit)) {
        openLimitReachedModal({
          limit: 'uploadMaxFileparts',
        });
      } else {
        setAttachments(newAttachments);
        const shouldForce = newAttachments.some((attachment) => {
          const type = getAttachmentMediaType(attachment);

          return (type === 'audio' && !canSendAudios)
            || (type === 'video' && !canSendVideos)
            || (type === 'photo' && !canSendPhotos);
        });

        setShouldForceAsFile(Boolean(shouldForce && canSendDocuments));
        setShouldForceCompression(!canSendDocuments);
      }
    },
  );

  const handleAppendFiles = useLastCallback(async (files: File[], isSpoiler?: boolean) => {
    if (!canAttachFiles) {
      return;
    }

    if (editedMessage) {
      if (editedMessage.groupedId && files[0].type === GIF_MIME_TYPE) {
        showNotification({ message: lang('MediaReplaceInvalidError', undefined, { pluralValue: 1 }) });
        return;
      }

      const newAttachment = await buildAttachment(files[0].name, files[0]);
      const canReplace = editedMessage && canReplaceMessageMedia(editedMessage, newAttachment);

      if (editedMessage?.groupedId) {
        if (canReplace) {
          handleSetAttachments([newAttachment]);
        } else {
          showNotification({ message: lang('MediaReplaceInvalidError', undefined, { pluralValue: files.length }) });
        }
      } else {
        handleSetAttachments([newAttachment]);
      }
    } else {
      const newAttachments = await Promise.all(files.map((file) => (
        buildAttachment(file.name, file,
          { shouldSendAsSpoiler: isSpoiler || undefined, shouldSendInHighQuality })
      )));
      handleSetAttachments([...attachments, ...newAttachments]);
    }
  });

  const handleFileSelect = useLastCallback(async (files: File[]) => {
    if (!canAttachFiles) {
      return;
    }

    if (editedMessage) {
      if (editedMessage.groupedId && files[0].type === GIF_MIME_TYPE) {
        showNotification({ message: lang('MediaReplaceInvalidError', undefined, { pluralValue: 1 }) });
        return;
      }

      const newAttachment = await buildAttachment(files[0].name, files[0]);
      const canReplace = editedMessage && canReplaceMessageMedia(editedMessage, newAttachment);

      if (editedMessage?.groupedId) {
        if (canReplace) {
          handleSetAttachments([newAttachment]);
        } else {
          showNotification({ message: lang('MediaReplaceInvalidError', undefined, { pluralValue: files.length }) });
        }
      } else {
        handleSetAttachments([newAttachment]);
      }
    } else {
      const newAttachments = await Promise.all(files.map((file) =>
        buildAttachment(file.name, file, { shouldSendInHighQuality })));
      handleSetAttachments(newAttachments);
    }
  });

  const handleUpdateAttachmentsQuality = useLastCallback(async () => {
    const newAttachments = await Promise.all(attachments.map(async (attachment) => {
      if (!attachment.blob) return attachment;
      return buildAttachment(attachment.filename, attachment.blob, { shouldSendInHighQuality });
    }));
    handleSetAttachments(newAttachments);
  });

  useEffect(() => {
    handleUpdateAttachmentsQuality();
  }, [shouldSendInHighQuality]);

  return {
    handleAppendFiles,
    handleFileSelect,
    handleClearAttachments,
    handleSetAttachments,
    shouldForceCompression,
    shouldForceAsFile,
  };
}

function getFallbackPaneState() {
  return FALLBACK_PANE_STATE;
}

function setMaskHeight(middleColumn: HTMLElement, height: number, withGlide?: boolean) {
  setExtraStyles(middleColumn, {
    '--middle-header-panes-mask-height': `${height}px`,
    '--middle-header-panes-transition': withGlide ? 'var(--mask-glide-transition)' : '0s',
  });
}

function filterOwnPaneStates(states: PaneState[], cacheKey: string): PaneState[] {
  return states.map((state) => (
    !state.key || cacheKey === state.key || cacheKey.startsWith(`${state.key}_`)
      ? state : FALLBACK_PANE_STATE
  ));
}

function settle(isForced?: boolean) {
      if (isChatClosingRef.current) return;
      if (isHiddenRef.current) return;
      const transition = transitionRef.current!;
      const currentKey = transition.key;

      const stateArray = filterOwnPaneStates(
        paneStateGettersRef.current.map((getState) => getState()), transition.key,
      );

      const isSettling = !transition.isSettled;

      const openCount = stateArray.filter((s) => s.height > 0).length;
      const totalHeight = stateArray.reduce((acc, state) => acc + state.height, 0);
      const ownReportCount = stateArray.filter((state) => state.key !== undefined).length;
      const hasPendingPanes = stateArray.some((state) => state.isPending);

      const isRealizingPreload = transition.expectedHeight > 0;
      if (isRealizingPreload && totalHeight >= transition.expectedHeight) {
        transition.expectedHeight = 0;
      }

      const middleColumn = document.getElementById('MiddleColumn');
      if (!middleColumn) return;

      const isFirstPaneAppear = prevOpenCountRef.current === 0 && openCount > 0;

      const container = ref.current;
      const isIslandHidden = Boolean(container?.classList.contains(styles.rootHidden));
      const didRealizePreload = isRealizingPreload && transition.expectedHeight === 0;
      const isAwaitingPreloadedRows = transition.expectedHeight > 0 && hasPendingPanes;
      const shouldConcludeSettle = isSettling
        && (Boolean(isForced) || (ownReportCount >= expectedReportCountRef.current && !isAwaitingPreloadedRows));
      const shouldSkipPlacement = totalHeight === 0
        || (isSettling && !shouldConcludeSettle && isIslandHidden && !didRealizePreload);
      if (!shouldSkipPlacement) {
        const isMorph = transition.isMorph;
        commitInMutatePhase(() => {
          if (transitionRef.current !== transition) return;
          const noTransition = !isMorph && (isSettling || isFirstPaneAppear || isRealizingPreload
            || performance.now() < suppressRowAnimationsUntilRef.current);
          applyAnimationState({
            list: stateArray, noTransition, snapEntrancesOnly: isMorph, gapPx: 0,
          });
        });
      }

      if (didRealizePreload && container && isIslandHidden) {
        transition.hasCommitted = true;
        commitInMutatePhase(() => {
          if (transitionRef.current !== transition) return;
          applyAnimationState({ list: stateArray, noTransition: true, gapPx: 0 });
          setExtraStyles(container, { '--island-height-transition': '0s', height: `${totalHeight}px` });
          setMaskHeight(middleColumn, totalHeight);
          toggleIslandHiddenInstantly(container, styles.rootHidden, false);
        });
      }

      if (isRealizingPreload && transition.expectedHeight > 0 && !shouldConcludeSettle) return;

      if (isSettling && !shouldConcludeSettle) return;

      if (shouldConcludeSettle) {
        transition.isSettled = true;
        transition.isMorph = false;
        transition.expectedHeight = 0;
      }

      const reserveDelta = totalHeight - appliedReserveRef.current;
      if (!reserveDelta && !shouldConcludeSettle) return;

      const isInstantReveal = isRealizingPreload || !transition.hasCommitted;
      transition.hasCommitted = true;
      prevOpenCountRef.current = openCount;
      appliedReserveRef.current = totalHeight;
      panesHeightCache.set(currentKey, totalHeight);

      transition.generation += 1;
      const generation = transition.generation;
      const isCanceled = () => transitionRef.current!.generation !== generation;
      updateTopReserveWithScrollCompensation(middleColumn, reserveDelta, () => {
        if (isCanceled()) return;
        setExtraStyles(middleColumn, {
          '--middle-header-panes-height': `${totalHeight}px`,
        });

        if (container) {
          transitionIslandVisual({
            container,
            toHeight: totalHeight,
            shouldGlide: !isInstantReveal,
            hiddenClassName: styles.rootHidden,
            suppressRowAnimationsUntilRef,
            noFade: isInstantReveal,
            isCanceled,
          });
        }

        if (isInstantReveal) {
          setMaskHeight(middleColumn, totalHeight);
        } else {
          requestNextMutation(() => {
            if (isCanceled()) return;
            setMaskHeight(middleColumn, totalHeight, true);
          });
        }
      }, container && [container]);
    }

function createUtilSlice(context: PluginContext, runtime: TgPluginRuntime): TgPluginApi['util'] {
  const reporter = runtime.createPluginReporter(context.pluginName);

  return {
    // The reporter prefixes every line with the plugin name, so plugin logs
    // are distinguishable in the shared console.
    log: (...args) => {
      const message = args.map(formatLogArg).join(' ');
      reporter.log(message);
    },
    getLocalizedString: (key, variables) => {
      try {
        return runtime.getLocalizedString(key, variables);
      } catch (error) {
        // The raw key is the most useful fallback a caller can render
        reporter.logError('util.getLocalizedString', error);
        return key;
      }
    },
  };
}

function formatLogArg(arg: unknown): string {
  if (typeof arg === 'string') return arg;
  try {
    return JSON.stringify(arg) ?? String(arg);
  } catch (err) {
    // JSON serialization throws on BigInt and cyclic values (e.g. a DOM node)
    return String(arg);
  }
}

interface StateProps {
  isOpen: boolean;
  peerId: string;
  storyId?: number;
  story?: ApiTypeStory;
  origin?: StoryViewerOrigin;
  shouldSkipHistoryAnimations?: boolean;
  withAnimation?: boolean;
  isPrivacyModalOpen?: boolean;
}

function StoryViewer({
  isOpen,
  peerId,
  storyId,
  story,
  origin,
  shouldSkipHistoryAnimations,
  withAnimation,
  isPrivacyModalOpen,
}: StateProps) {
  const { closeStoryViewer, closeStoryPrivacyEditor, reportStory } = getActions();

  const lang = useOldLang();
  const [storyToDelete, setStoryToDelete] = useState<ApiTypeStory | undefined>(undefined);
  const [isDeleteModalOpen, openDeleteModal, closeDeleteModal] = useFlag(false);

  const { bestImageData, thumbnail } = useStoryProps(story);
  const slideSizes = useSlideSizes();
  const isPrevOpen = usePreviousDeprecated(isOpen);
  const prevBestImageData = usePreviousDeprecated(bestImageData);
  const prevPeerId = usePreviousDeprecated(peerId);
  const prevOrigin = usePreviousDeprecated(origin);
  const isGhostAnimation = Boolean(withAnimation && !shouldSkipHistoryAnimations);

  useEffect(() => {
    if (!isOpen) {
      setStoryToDelete(undefined);
      closeDeleteModal();
    }
  }, [isOpen]);

  useEffect(() => {
    if (!isOpen) {
      return undefined;
    }

    disableDirectTextInput();
    const stopPriorityPlayback = dispatchPriorityPlaybackEvent();

    return () => {
      enableDirectTextInput();
      stopPriorityPlayback();
    };
  }, [isOpen]);

  const handleClose = useCallback(() => {
    closeStoryViewer();
  }, [closeStoryViewer]);

  const handleOpenDeleteModal = useLastCallback((s: ApiTypeStory) => {
    setStoryToDelete(s);
    openDeleteModal();
  });

  const handleCloseDeleteModal = useLastCallback(() => {
    closeDeleteModal();
    setStoryToDelete(undefined);
  });

  const openMessageReport = useLastCallback(() => {
    if (!storyId) return;
    reportStory({ storyId, peerId });
  });

  useEffect(() => (isOpen ? captureEscKeyListener(() => {
    handleClose();
  }) : undefined), [handleClose, isOpen]);

  useEffect(() => {
    if (isGhostAnimation && !isPrevOpen && isOpen && peerId && thumbnail && origin !== undefined) {
      beginHeavyAnimation(ANIMATION_DURATION + ANIMATION_END_DELAY);
      animateOpening(peerId, origin, thumbnail, bestImageData, slideSizes.activeSlide);
    }
    if (isGhostAnimation && isPrevOpen && !isOpen && prevPeerId && prevBestImageData && prevOrigin !== undefined) {
      beginHeavyAnimation(ANIMATION_DURATION + ANIMATION_END_DELAY);
      animateClosing(prevPeerId, prevOrigin, prevBestImageData);
    }
  }, [
    isGhostAnimation,
    bestImageData,
    prevBestImageData,
    isOpen,
    isPrevOpen,
    slideSizes.activeSlide,
    thumbnail,
    peerId,
    prevPeerId,
    origin,
    prevOrigin,
  ]);

  return (
    <ShowTransition
      id="StoryViewer"
      className={styles.root}
      isOpen={isOpen}
      shouldAnimateFirstRender
      noCloseTransition={shouldSkipHistoryAnimations}
    >
      <div className={styles.backdrop} onClick={handleClose} />
      <Button
        className={styles.close}
        round
        size="tiny"
        color="translucent-white"
        ariaLabel={lang('Close')}
        onClick={handleClose}
        iconName="close"
      />

      <StorySlides
        isOpen={isOpen}
        isDeleteModalOpen={isDeleteModalOpen}
        onReport={openMessageReport}
        onClose={handleClose}
        onDelete={handleOpenDeleteModal}
      />

      <StoryDeleteConfirmModal
        isOpen={isDeleteModalOpen}
        story={storyToDelete}
        onClose={handleCloseDeleteModal}
      />
      <StoryViewModal />
      <StorySettings isOpen={isPrivacyModalOpen} onClose={closeStoryPrivacyEditor} />
    </ShowTransition>
  );
}

