async function parseAudioMetadata(url: string): Promise<AudioMetadata> {
  const { parseBlob, selectCover } = await import('music-metadata');
  const blob = await fetchBlob(url);
  const metadata = await parseBlob(blob);
  const { common: { title, artist, picture }, format: { duration } } = metadata;

  const cover = selectCover(picture);
  const coverBlob = cover ? new Blob([cover.data as Uint8Array<ArrayBuffer>], { type: cover.format }) : undefined;
  const coverUrl = coverBlob ? URL.createObjectURL(coverBlob) : undefined;

  return {
    title,
    performer: artist,
    duration,
    coverUrl,
  };
}

function useIsTopmostBalanceBarModal(
  ref: { current?: HTMLElement },
  isActive?: boolean,
) {
  const [isTopmost, setIsTopmost] = useState(true);

  useEffect(() => {
    if (!isActive) return undefined;

    const updateIsTopmost = () => {
      setIsTopmost(checkIsTopmostBalanceBarModal(ref.current));
    };

    updateIsTopmost();

    const unsubscribe = balanceBarCallbacks.addCallback(updateIsTopmost);
    balanceBarCallbacks.runCallbacks();

    return () => {
      unsubscribe();
      balanceBarCallbacks.runCallbacks();
    };
  }, [isActive, ref]);

  return isTopmost;
}

function checkIsTopmostBalanceBarModal(element?: HTMLElement) {
  if (!element) return true;

  const parentModal = element.closest(BALANCE_BAR_MODAL_SELECTOR);
  if (!parentModal) return true;

  const allBalanceBarModals = document.querySelectorAll(BALANCE_BAR_MODAL_SELECTOR);
  if (allBalanceBarModals.length <= 1) {
    return true;
  }

  let topmostModal: Element | undefined;
  let highestZIndex = -Infinity;

  allBalanceBarModals.forEach((modal) => {
    const zIndex = parseInt(getComputedStyle(modal).zIndex, 10) || 0;
    if (zIndex >= highestZIndex) {
      highestZIndex = zIndex;
      topmostModal = modal;
    }
  });

  return parentModal === topmostModal;
}

function useClickable<T extends HTMLElement>(
  onPress?: (e: React.MouseEvent<T>) => void,
  {
    disabled,
    role = 'button',
    withA11y = true,
    tabIndex = 0,
  }: UseClickableOptions = {},
): ClickableProps<T> {
  const shouldHandleSyntheticClickRef = useRef(false);
  const withListeners = Boolean(onPress) && !disabled;

  const handlePress = useLastCallback((e: React.MouseEvent<T>) => {
    const nativeEvent = e.nativeEvent as (MouseEvent & { pointerId?: number }) | undefined;
    const isSyntheticClick = e.detail === 0 || nativeEvent?.pointerId === -1; // Some mouse clicks produce two events

    if (isSyntheticClick && !shouldHandleSyntheticClickRef.current) return;

    shouldHandleSyntheticClickRef.current = false;
    onPress?.(e);
  });

  const handleKeyDown = useLastCallback((e: React.KeyboardEvent<T>) => {
    if (e.key === 'Enter' && ROLES_WITH_ENTER_ACTIVATION.has(role)) {
      e.preventDefault();
      shouldHandleSyntheticClickRef.current = true;
      e.currentTarget.click();
      return;
    }

    if (e.key === ' ' && ROLES_WITH_SPACE_ACTIVATION.has(role)) {
      e.preventDefault();
    }
  });

  const handleKeyUp = useLastCallback((e: React.KeyboardEvent<T>) => {
    if (e.key !== ' ' || !ROLES_WITH_SPACE_ACTIVATION.has(role)) return;

    e.preventDefault();
    shouldHandleSyntheticClickRef.current = true;
    e.currentTarget.click();
  });

  return {
    onClick: withListeners ? handlePress : undefined,
    onKeyDown: withListeners ? handleKeyDown : undefined,
    onKeyUp: withListeners ? handleKeyUp : undefined,
    role: onPress && withA11y ? role : undefined,
    tabIndex: onPress && withA11y ? (disabled ? -1 : tabIndex) : undefined,
    'aria-disabled': onPress && withA11y && disabled ? true : undefined,
  };
}

function useMessageObservers({
  type,
  containerRef,
  memoFirstUnreadIdRef,
  chatId,
  threadId,
  isQuickPreview,
  onIntersectPinnedMessage,
}: {
  containerRef: ElementRef<HTMLDivElement>;
  memoFirstUnreadIdRef: { current: number | undefined };
  chatId: string;
  threadId: ThreadId;
  type: MessageListType;
  isQuickPreview?: boolean;
  onIntersectPinnedMessage: OnIntersectPinnedMessage | undefined;
}) {
  const {
    markMessageListRead, markMentionsRead, markPollVotesRead, animateUnreadReaction,
    scheduleForViewsIncrement,
  } = getActions();

  const { isMobile } = useAppLayout();
  const INTERSECTION_MARGIN_FOR_LOADING = isMobile ? 300 : 500;

  const visibleViewportIdsRef = useRef<number[]>([]);
  useEffect(() => {
    visibleViewportIdsRef.current = [];
  }, [threadId, chatId, type]);

  // Note: Targets bottom marker, not the message itself
  const {
    observe: observeIntersectionForReading, freeze: freezeForReading, unfreeze: unfreezeForReading,
  } = useIntersectionObserver({
    rootRef: containerRef,
    throttleMs: INTERSECTION_THROTTLE_FOR_READING,
    threshold: 0,
    // `memoFirstUnreadIdRef` is set after the first render, firing callback before that can skip some entries, like the last message
    shouldSkipFirst: true,
  }, (entries) => {
    if (type !== 'thread' || isBackgroundModeActive()) {
      return;
    }

    let maxId = 0;
    const mentionIds: number[] = [];
    const pollVoteIds: number[] = [];
    const reactionIds: number[] = [];
    const scheduledToUpdateViews: number[] = [];

    const currentVisibleViewportIds = visibleViewportIdsRef.current;
    const hiddenViewportIds = new Set<number>();
    const newVisibleViewportIds: number[] = [];

    entries.forEach((entry) => {
      const { isIntersecting, target } = entry;

      const { dataset } = target as HTMLDivElement;
      const messageId = Number(dataset.lastMessageId || dataset.messageId);
      const shouldUpdateViews = dataset.shouldUpdateViews === 'true';
      const albumMainId = dataset.albumMainId ? Number(dataset.albumMainId) : undefined;

      if (!Number.isInteger(messageId)) {
        return;
      }

      if (!isIntersecting) {
        hiddenViewportIds.add(messageId);
        return;
      }

      newVisibleViewportIds.push(messageId);

      if (messageId > maxId) {
        maxId = messageId;
      }

      if (dataset.hasUnreadMention) {
        mentionIds.push(messageId);
      }

      if (dataset.hasUnreadPollVote) {
        pollVoteIds.push(messageId);
      }

      if (dataset.hasUnreadReaction) {
        reactionIds.push(messageId);
      }

      if (shouldUpdateViews) {
        scheduledToUpdateViews.push(albumMainId || messageId);
      }
    });

    visibleViewportIdsRef.current = unique(currentVisibleViewportIds.concat(newVisibleViewportIds))
      .filter((id) => !hiddenViewportIds.has(id))
      .sort((a, b) => a - b);

    if (!isQuickPreview) {
      if (memoFirstUnreadIdRef.current && maxId && maxId >= memoFirstUnreadIdRef.current) {
        markMessageListRead({ maxId });
      }

      if (mentionIds.length) {
        markMentionsRead({ chatId, messageIds: mentionIds });
      }

      if (pollVoteIds.length) {
        markPollVotesRead({ chatId, messageIds: pollVoteIds });
      }

      if (scheduledToUpdateViews.length) {
        scheduleForViewsIncrement({ chatId, ids: scheduledToUpdateViews });
      }
    }

    if (reactionIds.length) {
      animateUnreadReaction({ chatId, messageIds: reactionIds });
    }

    if (visibleViewportIdsRef.current.length) {
      onIntersectPinnedMessage?.({ firstViewportId: visibleViewportIdsRef.current[0] });
    }
  });

  useBackgroundMode(freezeForReading, unfreezeForReading);

  const {
    observe: observeIntersectionForLoading,
  } = useIntersectionObserver({
    rootRef: containerRef,
    throttleMs: INTERSECTION_THROTTLE_FOR_MEDIA,
    margin: INTERSECTION_MARGIN_FOR_LOADING,
  });

  const { observe: observeIntersectionForPlaying } = useIntersectionObserver({
    rootRef: containerRef,
    throttleMs: INTERSECTION_THROTTLE_FOR_MEDIA,
  });

  const onMessageUnmount = useLastCallback((messageId: number) => {
    visibleViewportIdsRef.current = visibleViewportIdsRef.current.filter((id) => id !== messageId);
  });

  return {
    observeIntersectionForReading,
    observeIntersectionForLoading,
    observeIntersectionForPlaying,
    onMessageUnmount,
  };
}

function isIpRevealingMedia({ mimeType, extension }: { mimeType?: string; extension: string }) {
  const normalizedMimeType = mimeType?.split(';')[0].trim().toLowerCase();
  const normalizedMimeSubtype = normalizedMimeType?.split('/').pop()?.trim();
  const normalizedExtension = extension.trim().toLowerCase();

  if (normalizedMimeType && UNSAFE_MIME_TYPES.has(normalizedMimeType)) {
    return true;
  }

  if (normalizedMimeSubtype && UNSAFE_MIME_SUBTYPES.has(normalizedMimeSubtype)) {
    return true;
  }

  if (UNSAFE_EXTENSIONS.has(normalizedExtension)) {
    return true;
  }

  return false;
}

function getCountryCodeByIso(phoneCodeList: ApiCountryCode[], iso: string) {
  return phoneCodeList.find((country) => country.iso2 === iso);
}

function getCountryFromPhoneNumber(phoneCodeList: ApiCountryCode[], input = '') {
  let phoneNumber = input.replace(/[^\d+]+/g, '');
  if (phoneNumber.startsWith('+')) {
    phoneNumber = phoneNumber.substr(1);
  }

  const possibleCountries = phoneCodeList
    .filter((country) => phoneNumber.startsWith(country.countryCode));
  const codesWithPrefix: { code: string; country: ApiCountryCode }[] = possibleCountries
    .map((country) => (country.prefixes || ['']).map((prefix) => {
      return {
        code: `${country.countryCode}${prefix}`,
        country,
      };
    }))
    .flat();

  const bestMatches = codesWithPrefix
    .filter(({ code }) => phoneNumber.startsWith(code))
    .sort((a, b) => a.code.length - b.code.length);

  return bestMatches[bestMatches.length - 1]?.country;
}

function formatPhoneNumber(input: string, country?: ApiCountryCode) {
  if (!input) {
    return '';
  }

  let phoneNumber = input.replace(/[^\d]+/g, '');
  if (country) {
    phoneNumber = phoneNumber.substr(country.countryCode.length);
  } else if (input.startsWith('+')) {
    return input;
  }
  const pattern = getBestPattern(phoneNumber, country?.patterns);

  const result: string[] = []; // Result character array
  let j = 0; // Position inside pattern
  for (let i = 0; i < phoneNumber.length; i++) {
    while (pattern[j] !== PATTERN_PLACEHOLDER && j < pattern.length) {
      result.push(pattern[j]);
      if (pattern[j] === phoneNumber[i]) { // If pattern contains digits, move input position too
        i++;
        if (i === phoneNumber.length) break; // But don't overdo it, or it will insert full pattern unexpectedly
      }
      j++;
    }

    result.push(phoneNumber[i]); // For placeholder characters, setting current input digit
    j++;
  }

  return result.join('');
}

function getBestPattern(numberWithoutCode: string, patterns?: string[]) {
  if (!patterns || patterns.length === 0) return DEFAULT_PATTERN;
  if (patterns.length === 1) return patterns[0];

  const defaultPattern = patterns.find((pattern) => pattern.startsWith(PATTERN_PLACEHOLDER)) || DEFAULT_PATTERN;

  const bestMatches = patterns.filter((pattern) => {
    const stripped = pattern.replace(/[^\dX]+/g, '');
    if (stripped.startsWith(PATTERN_PLACEHOLDER)) return false; // Don't consider default number format here
    for (let i = 0; i < numberWithoutCode.length; i++) {
      if (i > stripped.length - 1 || (stripped[i] !== PATTERN_PLACEHOLDER && stripped[i] !== numberWithoutCode[i])) {
        return false;
      }
    }
    return true;
  });

  // Playing it safe: if not sure, use default for that region
  return bestMatches.length === 1 ? bestMatches[0] : defaultPattern;
}

function formatPhoneNumberWithCode(phoneCodeList: ApiCountryCode[], phoneNumber: string) {
  if (!phoneNumber) {
    return '';
  }

  const numberWithPlus = phoneNumber.startsWith('+') ? phoneNumber : `+${phoneNumber}`;
  const country = getCountryFromPhoneNumber(phoneCodeList, numberWithPlus);
  if (!country) {
    return numberWithPlus;
  }
  return `+${country.countryCode} ${formatPhoneNumber(numberWithPlus, country)}`;
}

function MessageStatistics({
  chatId,
  isActive,
  statistics,
  dcId,
  messageId,
}: OwnProps & StateProps) {
  const lang = useLang();
  const oldLang = useOldLang();
  const containerRef = useRef<HTMLDivElement>();
  const [isReady, setIsReady] = useState(false);
  const loadedChartsRef = useRef<Set<string>>(new Set());
  const errorChartsRef = useRef<Set<string>>(new Set());

  const { loadMessageStatistics, loadMessagePublicForwards, loadStatisticsAsyncGraph } = getActions();
  const forceUpdate = useForceUpdate();

  useEffect(() => {
    if (messageId) {
      loadMessageStatistics({ chatId, messageId });
    }
  }, [chatId, loadMessageStatistics, messageId]);

  useEffect(() => {
    if (!isActive || messageId) {
      loadedChartsRef.current.clear();
      errorChartsRef.current.clear();
      setIsReady(false);
    }
  }, [isActive, messageId]);

  // Load async graphs
  useEffect(() => {
    if (!statistics) {
      return;
    }

    GRAPHS.forEach((name) => {
      const graph = statistics[name];
      if (!isGraph(graph)) {
        return;
      }
      const isAsync = graph.graphType === 'async';

      if (isAsync) {
        loadStatisticsAsyncGraph({ name, chatId, token: graph.token });
      }
    });
  }, [chatId, statistics, loadStatisticsAsyncGraph]);

  useEffect(() => {
    (async () => {
      const LovelyChart = await ensureLovelyChart();

      if (!isReady) {
        setIsReady(true);
        return;
      }

      if (!statistics || !containerRef.current) {
        return;
      }

      GRAPHS.forEach((name, index: number) => {
        const graph = statistics[name];
        if (!isGraph(graph)) {
          return;
        }
        const isAsync = graph.graphType === 'async';
        const isError = graph.graphType === 'error';

        if (isAsync || loadedChartsRef.current.has(name)) {
          return;
        }

        if (isError) {
          loadedChartsRef.current.add(name);
          errorChartsRef.current.add(name);

          return;
        }

        const { zoomToken } = graph;

        new LovelyChart(containerRef.current!.children[index] as HTMLElement, {
          ...graph,
          title: oldLang((GRAPH_TITLES as Record<string, string>)[name]),
          onZoom: zoomToken
            ? (x: number) => callApi('fetchStatisticsAsyncGraph', { token: zoomToken, x, dcId })
            : undefined,
          zoomOutLabel: zoomToken ? oldLang('Graph.ZoomOut') : undefined,
        });

        loadedChartsRef.current.add(name);
      });

      forceUpdate();
    })();
  }, [
    isReady, statistics, oldLang, chatId, messageId, loadStatisticsAsyncGraph, dcId, forceUpdate,
  ]);

  const handleLoadMore = useLastCallback(({ direction }: { direction: LoadMoreDirection }) => {
    if (direction === LoadMoreDirection.Backwards && messageId) {
      loadMessagePublicForwards({ chatId, messageId });
    }
