function getAmplitude(array: Uint8Array, scale = 3) {
  if (!array) return 0;

  const { length } = array;
  let total = 0;
  for (let i = 0; i < length; i++) {
    total += array[i] * array[i];
  }
  const rms = Math.sqrt(total / length) / 255;

  return Math.min(1, rms * scale);
}

