function removeRelatedAddress(candidate: string) {
  const parts = candidate.split(' ');

  const raddrIndex = parts.indexOf('raddr');
  if (raddrIndex !== -1) {
    parts.splice(raddrIndex, 2);
  }

  const rportIndex = parts.indexOf('rport');
  if (rportIndex !== -1) {
    parts.splice(rportIndex, 2);
  }

  return parts.join(' ');
}

