  Object.entries(currentReadMetricsToReport).forEach(([chatId, metrics]) => {
    if (!metrics.length) return;

    const chat = selectChat(global, chatId);
    if (!chat) return;

    void callApi('reportMessageReadMetrics', { chat, metrics });
  });
}

function countSortedIds(ids: number[], from: number, to: number) {
  // If ids are outside viewport, we cannot get correct count
  if (ids.length === 0 || from < ids[0] || to > ids[ids.length - 1]) return undefined;

  let count = 0;

  for (let i = 0, l = ids.length; i < l; i++) {
    if (ids[i] >= from && ids[i] <= to) {
      count++;
    }

    if (ids[i] >= to) {
      break;
    }
  }

  return count;
}

function splitAttachmentsByType(attachments: ApiAttachment[]) {
  return attachments.reduce((acc, attachment, index, arr) => {
    if (index === 0) {
      acc.push([attachment]);
      return acc;
    }

    const type = getAttachmentType(attachment);
    const previousType = getAttachmentType(arr[index - 1]);
    if (type === previousType) {
      acc[acc.length - 1].push(attachment);
    } else {
      acc.push([attachment]);
    }

    return acc;
  }, [] as ApiAttachment[][]);
}

function getAttachmentType(attachment: ApiAttachment) {
  const {
    shouldSendAsFile, mimeType,
  } = attachment;
  if (SUPPORTED_AUDIO_CONTENT_TYPES.has(mimeType)) return 'audio';
  if (shouldSendAsFile) return 'file';
  if (mimeType === GIF_MIME_TYPE) return 'gif';
  if (SUPPORTED_PHOTO_CONTENT_TYPES.has(mimeType) || SUPPORTED_VIDEO_CONTENT_TYPES.has(mimeType)) return 'media';
  if (attachment.voice) return 'voice';
  return 'file';
}

function deepMerge<T extends object>(value1: T, value2: DiffObject<T>): T {
  if (value1 === value2) {
    return value2 as unknown as T;
  }

  if (!isLiteralObject(value2)) {
    return value2;
  }

  if (!isLiteralObject(value1)) {
    return reduceDiff(value2) as T;
  }

  if ('__deleteAllChildren' in value2) {
    return {} as T;
  }

  const allKeys = unique(Object.keys(value1).concat(Object.keys(value2)));

  return allKeys.reduce((acc: AnyLiteral, key) => {
    const oldValue = (value1 as AnyLiteral)[key];

    if (!value2.hasOwnProperty(key)) {
      acc[key] = oldValue;
    } else {
      const newValue = value2[key];

      if (!newValue?.__delete) {
        acc[key] = deepMerge(oldValue, newValue);
      }
    }

    return acc;
  }, {}) as T;
}

function reduceDiff(diff: AnyLiteral) {
  if (diff.__deleteAllChildren) {
    return {};
  }

  return Object.entries(diff).reduce((acc: AnyLiteral, [key, value]) => {
    if (!value?.__delete) {
      acc[key] = isLiteralObject(value) ? reduceDiff(value) : value;
    }

    return acc;
  }, {});
}

