function isRichEditorBlockquoteActive(
  editor: Editor,
  range: EditorRange,
  isRichInputExpanded: boolean,
) {
  return shouldRemoveSelectedBlockquote(editor.state.doc, range, isRichInputExpanded);
}

function getSelectedNodes(doc: ProseMirrorNode, range: EditorRange, nodeTypeName: string) {
  const nodes: SelectedNode[] = [];
  doc.nodesBetween(range.from, range.to, (node, position) => {
    if (node.type.name === nodeTypeName) {
      nodes.push({ node, position });
    }
  });
  return nodes;
}

function expandSelectedTextblockEdges(doc: ProseMirrorNode, range: EditorRange): EditorRange {
  const $from = doc.resolve(range.from);
  const $to = doc.resolve(range.to);
  return {
    from: $from.parentOffset ? range.from : $from.before($from.depth),
    to: $to.parentOffset < $to.parent.content.size ? range.to : $to.after($to.depth),
  };
}

function unwrapSelectedCodeBlocks(transaction: Transaction, codeBlocks: SelectedNode[]) {
  const { schema } = transaction.doc.type;
  codeBlocks.reverse().forEach(({ node, position }) => {
    const paragraphs = node.textContent.split(BLOCK_SEPARATOR).map((line) => (
      schema.nodes[PARAGRAPH_NODE_TYPE].create(undefined, line ? schema.text(line) : undefined)
    ));
    transaction.replaceWith(position, position + node.nodeSize, Fragment.fromArray(paragraphs));
  });
}

function shouldRemoveSelectedBlockquote(
  doc: ProseMirrorNode,
  range: EditorRange,
  isRichInputExpanded: boolean,
) {
  const blockquotes = getSelectedNodes(doc, range, BLOCKQUOTE_NODE_TYPE);
  if (!isRichInputExpanded && blockquotes.length) {
    return true;
  }
  if (blockquotes.some(({ node, position }) => isNodeFullySelected(node, position, range))) {
    return true;
  }

  const positions = [range.from, Math.max(range.from, range.to - 1)];
  const ancestorDepth = Math.min(...positions.map((position) => (
    getPositionAncestorTypeDepth(doc, position, BLOCKQUOTE_NODE_TYPE)
  )));
  return ancestorDepth > (isRichInputExpanded ? 1 : 0);
}

function isNodeFullySelected(node: ProseMirrorNode, position: number, range: EditorRange) {
  let start: number | undefined;
  let end: number | undefined;
  node.descendants((child, childPosition) => {
    if (child.isText) {
      start ??= position + 1 + childPosition;
      end = position + 1 + childPosition + child.nodeSize;
    }
    return !child.isText;
  });
  return start !== undefined && range.from <= start && range.to >= end!;
}

function getPositionAncestorTypeDepth(doc: ProseMirrorNode, position: number, nodeTypeName: string) {
  const $position = doc.resolve(position);
  let count = 0;
  for (let depth = $position.depth; depth > 0; depth--) {
    if ($position.node(depth).type.name === nodeTypeName) {
      count++;
    }
  }
  return count;
}

function splitSelectionBoundaries(transaction: Transaction, range: EditorRange) {
  const end = transaction.mapping.map(range.to, -1);
  if (canSplitTextblock(transaction, end)) {
    transaction.split(end);
  }
  const start = transaction.mapping.map(range.from, 1);
  if (canSplitTextblock(transaction, start)) {
    transaction.split(start);
  }
  return {
    from: transaction.mapping.map(range.from, 1),
    to: transaction.mapping.map(range.to, -1),
  };
}

function canSplitTextblock(transaction: Transaction, position: number) {
  const $position = transaction.doc.resolve(position);
  return $position.parent.isTextblock
    && $position.parentOffset > 0
    && $position.parentOffset < $position.parent.content.size
    && canSplit(transaction.doc, position);
}

function wrapSelectionInBlockquote(transaction: Transaction, range: EditorRange) {
  const nodeRange = transaction.doc.resolve(range.from).blockRange(transaction.doc.resolve(range.to));
  const wrapping = nodeRange && findWrapping(
    nodeRange,
    transaction.doc.type.schema.nodes[BLOCKQUOTE_NODE_TYPE],
  );
  if (nodeRange && wrapping) {
    transaction.wrap(nodeRange, wrapping);
  }
}

function removeSelectedBlockquotes(transaction: Transaction, range: EditorRange) {
  const blockquotes = getSelectedNodes(transaction.doc, range, BLOCKQUOTE_NODE_TYPE)
    .map(({ node, position }) => ({
      from: position,
      to: position + node.nodeSize,
    }));
  blockquotes.filter((blockquote) => !blockquotes.some((candidate) => (
    candidate.from > blockquote.from && candidate.to < blockquote.to
  ))).reverse().forEach(({ from }) => {
    unwrapRichEditorQuote(transaction, from);
  });
}

function restoreMappedSelection(transaction: Transaction, range: EditorRange) {
  if (!transaction.docChanged) {
    return;
  }

  const from = Math.min(transaction.mapping.map(range.from, 1), transaction.doc.content.size);
  const to = Math.min(transaction.mapping.map(range.to, -1), transaction.doc.content.size);
  transaction.setSelection(TextSelection.between(
    transaction.doc.resolve(Math.min(from, to)),
    transaction.doc.resolve(Math.max(from, to)),
  ));
}

parseMarkdown(token, helpers) {
    return parseRichMarkdownNode(token, helpers, false, 'mention', buildMentionMarkdownAttrs, true);
  }

addAttributes() {
    return {
      userId: {
        default: undefined,
        parseHTML: (element: HTMLElement) => element.dataset.userId,
      },
      username: {
        default: undefined,
        parseHTML: (element: HTMLElement) => element.dataset.username,
      },
      label: {
        default: undefined,
        parseHTML: (element: HTMLElement) => element.dataset.label,
      },
    };
  }

parseHTML() {
    return [
      {
        tag: 'a[href^="tg://user?id="]',
        priority: 101,
        getAttrs: (element) => buildMentionNameAttrs(element),
      },
      { tag: 'span[data-rich-text-type="mention"]' },
      { tag: 'span[data-rich-text-type="mention-name"]' },
    ];
  }

renderHTML({ HTMLAttributes }) {
    return ['a', {
      href: HTMLAttributes.userId
        ? `tg://user?id=${HTMLAttributes.userId}`
        : `${TME_LINK_PREFIX}${HTMLAttributes.username}`,
    }, 0];
  }

renderMarkdown(node, helpers) {
    const label = escapeRichMarkdownLabel(helpers.renderChildren(node));
    if (node.attrs?.userId) {
      return `[${label}](tg://user?id=${node.attrs.userId})`;
    }

    return node.attrs?.username ? `[${label}](${TME_LINK_PREFIX}${node.attrs.username})` : label;
  }

addNodeView() {
    return TeactNodeViewRenderer(EditableMention, {
      as: 'span',
      className: styles.mention,
      contentDOMElementTag: 'span',
      contentDOMClassName: styles.mentionContentDom,
      selectedOnTextSelection: true,
    });
  }

addKeyboardShortcuts() {
    return {
      ArrowLeft: () => moveCursorOutsideMention(this.editor, this.name, 'backward'),
      ArrowRight: () => moveCursorOutsideMention(this.editor, this.name, 'forward'),
      Backspace: () => deleteMentionCharacter(this.editor, this.name, 'backward'),
      Delete: () => deleteMentionCharacter(this.editor, this.name, 'forward'),
    };
  }

addInputRules() {
    return [buildRichMarkdownNodeInputRule(this.type, buildMentionMarkdownAttrs, true)];
  }

function buildMentionMarkdownAttrs(markdown: RichMarkdownLink) {
  if (markdown.isImage || !markdown.label.trim()) {
    return undefined;
  }

  const attrs = buildMentionNameAttrs(markdown.href);

  return attrs ? { ...attrs, label: markdown.label } : undefined;
}

function EditableMention({ node, contentDOMElement }: TeactNodeViewComponentProps) {
  const peer = getMentionPeer(node.attrs);
  const isEmpty = !node.textContent;
  const hasUserReference = Boolean(node.attrs.userId || node.attrs.username);
  const isReadOnly = hasUserReference && !peer;

  useMentionChrome(contentDOMElement, isEmpty);

  return (
    <>
      {peer && (
        <span className={styles.mentionAvatar} contentEditable={false}>
          <Avatar size={MENTION_AVATAR_SIZE} peer={peer} />
        </span>
      )}
      <NodeViewContent as="span" className={styles.mentionContent} contentEditable={isReadOnly ? false : undefined} />
    </>
  );
}

function useMentionChrome(contentDOMElement: HTMLElement | undefined, isEmpty: boolean) {
  useEffect(() => {
    const mentionElement = getMentionElement(contentDOMElement);
    if (!mentionElement) {
      return undefined;
    }

    requestMutation(() => {
      mentionElement.classList.toggle(styles.mentionEmpty, isEmpty);
    });

    return () => {
      requestMutation(() => {
        mentionElement.classList.remove(styles.mentionEmpty);
      });
    };
  }, [contentDOMElement, isEmpty]);
}

function getMentionElement(contentDOMElement: HTMLElement | undefined) {
  return contentDOMElement?.closest<HTMLElement>(`.${styles.mention}`);
}

function getMentionPeer(attrs: AnyLiteral): ApiPeer | undefined {
  const userId = typeof attrs.userId === 'string' ? attrs.userId : undefined;
  if (userId) {
    return selectPeer(getGlobal(), userId);
  }

  const username = typeof attrs.username === 'string' ? attrs.username.toLowerCase() : undefined;
  if (!username) {
    return undefined;
  }

  return selectPeerByUsername(getGlobal(), username);
}

function buildMentionNameAttrs(element: HTMLElement | string) {
  const href = element instanceof HTMLElement ? element.getAttribute('href') : element;
  if (!href) {
    return false;
  }

  let url: URL;
  try {
    url = new URL(href);
  } catch {
    return false;
  }

  if (url.protocol !== 'tg:' || url.host !== 'user') {
    return false;
  }

  const userId = url.searchParams.get('id') || undefined;
  const user = userId ? selectUser(getGlobal(), userId) : undefined;
  return user?.accessHash ? { userId } : false;
}

function moveCursorOutsideMention(editor: Editor, typeName: string, direction: 'backward' | 'forward') {
  const { state, view } = editor;
  const { selection } = state;
  if (!selection.empty) {
    return false;
  }

  const mentionRange = getSelectedMentionRange(selection.$from, typeName);
  if (!mentionRange) {
    return false;
  }

  const targetPosition = direction === 'backward' ? mentionRange.before : mentionRange.after;
  const isAtBoundary = direction === 'backward'
    ? selection.$from.pos <= mentionRange.contentStart
    : selection.$from.pos >= mentionRange.contentEnd;

  if (!isAtBoundary) {
    return false;
  }

  view.dispatch(state.tr.setSelection(TextSelection.create(state.doc, targetPosition)));
  return true;
}

function deleteMentionCharacter(editor: Editor, typeName: string, direction: 'backward' | 'forward') {
  const { state, view } = editor;
  const { selection } = state;
  if (!selection.empty) {
    return false;
  }

  const mentionRange = getSelectedMentionRange(selection.$from, typeName);
  if (!mentionRange) {
    return false;
  }

  const from = direction === 'backward' ? selection.$from.pos - 1 : selection.$from.pos;
  const to = from + 1;
  if (from < mentionRange.contentStart || to > mentionRange.contentEnd) {
    return false;
  }

  const transaction = state.tr.delete(from, to);
  view.dispatch(transaction.setSelection(TextSelection.create(transaction.doc, from)));
  return true;
}

function getSelectedMentionRange($position: TextSelection['$from'], typeName: string) {
  for (let depth = $position.depth; depth > 0; depth--) {
    const node = $position.node(depth);
    if (node.type.name !== typeName) {
      continue;
    }

    const before = $position.before(depth);
    const after = before + node.nodeSize;

    return {
      before,
      after,
      contentStart: before + 1,
      contentEnd: after - 1,
    };
  }

  return undefined;
}

function useTopOverscroll({
  containerRef,
  isOverscrolled,
  isDisabled,
  onOverscroll,
  onReset,
}: {
  containerRef: ElementRef<HTMLDivElement>;
  isOverscrolled?: boolean;
  onOverscroll?: AnyToVoidFunction;
  onReset?: AnyToVoidFunction;
  isDisabled?: boolean;
},
) {
  const [getState, setState] = useSignal<State>('normal');
  const activeScrollRef = useRef<ActiveScrollContext>({ ...initialActiveScrollContext });
  const transitionTimeoutRef = useRef<number | undefined>();
  const touchStartYRef = useRef<number | undefined>();

  const triggerOverscroll = useLastCallback(() => {
    clearTimeout(transitionTimeoutRef.current);
    setState('overscroll');
    onOverscroll?.();
  });

  const triggerReset = useLastCallback(() => {
    setState('animating');
    transitionTimeoutRef.current = window.setTimeout(() => {
      setState('normal');
    }, TRANSITION_DURATION);
    onReset?.();
  });

  const scheduleResetActiveScroll = useLastCallback((timeout: number) => {
    clearTimeout(activeScrollRef.current.timeout);
    activeScrollRef.current.timeout = window.setTimeout(() => {
      activeScrollRef.current = { ...initialActiveScrollContext };
    }, timeout);
  });

  const handleWheel = useLastCallback((e: WheelEvent) => {
    const container = containerRef.current;
    if (!container || e.defaultPrevented) {
      return;
    }

    const { deltaY } = e;
    const { scrollTop } = container;
    const state = getState();

    const activeScroll = activeScrollRef.current;
    const lastAverageDelta = activeScroll.lastAverageDelta;

    const isStarting = activeScroll.lastDeltas.at(-1) === 0
      || (activeScroll.resetStartTopAt && Date.now() >= activeScroll.resetStartTopAt);
    if (scrollTop === 0 && isStarting) {
      activeScroll.isStartedAtTop = true;
      activeScroll.resetStartTopAt = undefined;
    }

    const lastDeltas = activeScrollRef.current.lastDeltas.slice(); // Copy
    lastDeltas.push(deltaY);
    if (lastDeltas.length > LAST_DELTA_COUNT) {
      lastDeltas.shift();
    }
    activeScrollRef.current.lastDeltas = lastDeltas;
    const currentAverageDelta = lastDeltas.reduce((a, b) => a + b, 0) / lastDeltas.length;
    activeScrollRef.current.lastAverageDelta = currentAverageDelta;

    const isNewInput = Math.abs(currentAverageDelta) - Math.abs(lastAverageDelta) > NEW_INPUT_DELTA_THRESHOLD;

    scheduleResetActiveScroll(ACTIVE_SCROLL_RESET_TIMEOUT);

    // If we're at the top and scrolling up
    if (scrollTop === 0 && deltaY < 0 && state !== 'overscroll') {
      if (!activeScroll.resetStartTopAt) {
        // Schedule delta reset, so we would respond to new input with `isStartedAtTop` flag set
        activeScroll.resetStartTopAt = Date.now() + ACTIVE_SCROLL_RESET_TIMEOUT;
      }

      // Only trigger overscroll on new input, ignore momentum events
      if (isNewInput && activeScroll.isStartedAtTop) {
        triggerOverscroll();
      }
      return;
    }

    // Ignore scroll events during collapse animation
    if (state === 'animating' && deltaY > 0) {
      stopEvent(e);
      return;
    }

    // If we're overscrolled, any down wheel event should reset
    if (state === 'overscroll' && deltaY > 0) {
      triggerReset();
      stopEvent(e);
      return;
    }
  });

  const handleTouchStart = useLastCallback((e: TouchEvent) => {
    const container = containerRef.current;
    if (!container || e.touches.length !== 1) return;

    const { scrollTop } = container;
    const state = getState();

    // Register touch start position when at top or in overscroll state
    if (scrollTop === 0 || state === 'overscroll') {
      touchStartYRef.current = e.touches[0].clientY;
    }
  });

  const handleTouchMove = useLastCallback((e: TouchEvent) => {
    const container = containerRef.current;
    const startY = touchStartYRef.current;
    if (!container || startY === undefined || e.touches.length !== 1) return;

    const { scrollTop } = container;
    const state = getState();
    const currentY = e.touches[0].clientY;
    const deltaY = currentY - startY;

    if (state === 'animating') {
      return;
    }

    // If we're at the top and dragging down by more than trigger distance
    if (scrollTop === 0 && deltaY > DRAG_TRIGGER_DISTANCE && state !== 'overscroll') {
      triggerOverscroll();
      touchStartYRef.current = undefined; // Reset to prevent multiple triggers
      return;
    }

    // If we're overscrolled and dragging up by more than trigger distance, reset
    if (state === 'overscroll' && deltaY < -DRAG_TRIGGER_DISTANCE) {
      triggerReset();
      touchStartYRef.current = undefined; // Reset to prevent multiple triggers
      return;
    }
  });

  const handleTouchEnd = useLastCallback(() => {
    touchStartYRef.current = undefined;
  });

  useEffect(() => {
    const container = containerRef.current;
    if (isDisabled || !container) return;
    requestMutation(() => {
      container.classList.add(OVERSCROLL_CONTAINER_CLASS);
    });

    return () => {
      requestMutation(() => {
        container.classList.remove(OVERSCROLL_CONTAINER_CLASS);
      });
    };
  }, [containerRef, isDisabled]);

  useEffect(() => {
    const container = containerRef.current;
    if (isDisabled || !container) return;
    requestMutation(() => {
      container.classList.toggle(NO_TOUCH_CONTAINER_CLASS, getState() !== 'normal');
    });

    return () => {
      requestMutation(() => {
        container.classList.remove(NO_TOUCH_CONTAINER_CLASS);
      });
    };
  }, [containerRef, isDisabled, getState]);

  useEffectWithPrevDeps(([prevIsOverscrolled]) => {
    if (prevIsOverscrolled === isOverscrolled) return;
    if (!isOverscrolled && getState() === 'animating') {
      return; // We're animating towards this state
    }

    setState(isOverscrolled ? 'overscroll' : 'normal');
  }, [isOverscrolled, getState, setState]);

  useEffect(() => {
    const container = containerRef.current;
    if (isDisabled || !container) {
      return undefined;
    }

    container.addEventListener('wheel', handleWheel, { passive: getState() === 'normal' });
    container.addEventListener('touchstart', handleTouchStart, { passive: true });
    container.addEventListener('touchmove', handleTouchMove, { passive: true });
    container.addEventListener('touchend', handleTouchEnd, { passive: true });
    container.addEventListener('touchcancel', handleTouchEnd, { passive: true });

    return () => {
      container.removeEventListener('wheel', handleWheel);
      container.removeEventListener('touchstart', handleTouchStart);
      container.removeEventListener('touchmove', handleTouchMove);
      container.removeEventListener('touchend', handleTouchEnd);
      container.removeEventListener('touchcancel', handleTouchEnd);

      const activeScroll = activeScrollRef.current;
      if (activeScroll?.timeout) clearTimeout(activeScroll.timeout);
    };
  }, [containerRef, handleWheel, handleTouchStart, handleTouchMove, handleTouchEnd, getState, isDisabled]);
}

