interface AnimationInstance {
  isCancelled: boolean;
}

function animateSingle(tick: TickFunction, schedulerFn: Scheduler, instance?: AnimationInstance) {
  if (!instance) {
    if (currentInstance && !currentInstance.isCancelled) {
      currentInstance.isCancelled = true;
    }

    instance = { isCancelled: false };
    currentInstance = instance;
  }

  if (!instance.isCancelled && tick()) {
    schedulerFn(() => {
      animateSingle(tick, schedulerFn, instance);
    });
  }
}

function cancelSingleAnimation() {
  const dumbScheduler = (cb: AnyFunction) => cb;
  const dumbCb = () => undefined;

  animateSingle(dumbCb, dumbScheduler);
}

function animate(tick: TickFunction, schedulerFn: Scheduler) {
  schedulerFn(() => {
    if (tick()) {
      animate(tick, schedulerFn);
    }
  });
}

function animateInstantly(tick: TickFunction, schedulerFn: Scheduler) {
  if (tick()) {
    schedulerFn(() => {
      animateInstantly(tick, schedulerFn);
    });
  }
}

function animateNumber<T extends number | number[]>({
  timing = timingFunctions.linear,
  onUpdate,
  duration,
  onEnd,
  from,
  to,
}: AnimateNumberProps<T>) {
  const t0 = Date.now();

  let isCanceled = false;

  animateInstantly(() => {
    if (isCanceled) return false;

    const t1 = Date.now();
    const t = Math.min((t1 - t0) / duration, 1);

    const progress = timing(t);
    if (typeof from === 'number' && typeof to === 'number') {
      onUpdate((from + ((to - from) * progress)) as T);
    } else if (Array.isArray(from) && Array.isArray(to)) {
      const result = from.map((f, i) => f + ((to[i] - f) * progress));
      onUpdate(result as T);
    }

    if (t === 1) {
      onEnd?.();
    }

    return t < 1;
  }, requestMeasure);

  return () => {
    isCanceled = true;
    onEnd?.(true);
  };
}

