function isBase64Url(base64Url: string) {
  return RE_BASE64_URL.test(base64Url);
}

function base64UrlToBase64(base64Url: string): string {
  const base64Encoded = base64Url.replace(/-/g, '+').replace(/_/g, '/');
  const padding = base64Url.length % 4 === 0 ? '' : '='.repeat(4 - (base64Url.length % 4));
  const base64WithPadding = base64Encoded + padding;
  return base64WithPadding;
}

function base64UrlToBuffer(base64Url: string): Uint8Array<ArrayBuffer> {
  const base64 = base64UrlToBase64(base64Url);
  return bufferFromBase64(base64);
}

function base64UrlToString(base64Url: string): string {
  const buffer = base64UrlToBuffer(base64Url);
  return bufferToUtf8(buffer);
}

function pathBytesToSvg(bytes: Uint8Array, width: number, height: number) {
  return TEMPLATE
    .replace('{{path}}', buildSvgPath(bytes))
    .replace('{{width}}', String(width))
    .replace('{{height}}', String(height));
}

function buildSvgPath(bytes: Uint8Array) {
  let path = 'M';

  const len = bytes.length;
  for (let i = 0; i < len; i++) {
    const num = bytes[i];
    if (num >= 128 + 64) {
      path += LOOKUP[num - 128 - 64];
    } else {
      if (num >= 128) {
        path += ',';
      } else if (num >= 64) {
        path += '-';
      }
      path += String(num & 63);
    }
  }

  path += 'z';

  return path;
}

