function usePrevious<T>(current: T) {
  const prevRef = useRef<T>();
  const lastRef = useRef<T>();

  if (lastRef.current !== current) {
    prevRef.current = lastRef.current;
  }

  lastRef.current = current;

  return prevRef.current;
}

