}

function getStickerMediaHash(sticker: ApiSticker, target: SizeTarget) {
  const base = `document${sticker.id}`;

  switch (target) {
    case 'micro':
    case 'pictogram':
      if (!sticker.previewPhotoSizes?.some((size) => size.type === 's')) {
        return getStickerMediaHash(sticker, 'preview');
      }
      return `${base}?size=s`;
    case 'preview':
      return `${base}?size=m`;
    case 'download':
      return `${base}?download`;
    case 'inline':
    default:
      return base;
  }
}

function getMediaHash(media: DownloadableMedia, target: SizeTarget) {
  switch (media.mediaType) {
    case 'photo':
      return getPhotoMediaHash(media, target);
    case 'video':
      return getVideoMediaHash(media, target);
    case 'document':
      return getDocumentMediaHash(media, target);
    case 'audio':
      return getAudioMediaHash(media, target);
    case 'voice':
      return getVoiceMediaHash(media, target);
    case 'sticker':
      return getStickerMediaHash(media, target);
    case 'webDocument':
      return getWebDocumentHash(media);
    default:
      return undefined;
  }
}

function getGamePreviewPhotoHash(game: ApiGame) {
  const { photo } = game;

  if (photo) {
    return `photo${photo.id}?size=x`;
  }

  return undefined;
}

function getGamePreviewVideoHash(game: ApiGame) {
  const { document } = game;

  if (document) {
    return `document${document.id}`;
  }

  return undefined;
}

function appendProgressiveQueryParameters(
  media: Pick<ApiAudio | ApiVideo | ApiDocument, 'mimeType' | 'size'>, base: string,
) {
  if (IS_PROGRESSIVE_SUPPORTED && IS_SAFARI) {
    const [path, query = ''] = base.split('?');
    const params = new URLSearchParams(query);
    params.append('fileSize', media.size.toString());
    params.append('mimeType', media.mimeType);

    return `${path}?${params.toString()}`;
  }

  return base;
}

function getAudioHasCover(media: ApiAudio) {
  return media.thumbnailSizes && media.thumbnailSizes.length > 0;
}

function getMediaFormat(
  media: DownloadableMedia, target: SizeTarget,
): ApiMediaFormat {
  const isDocument = media.mediaType === 'document';
  const hasInnerVideo = isDocument && media.innerMediaType === 'video';
  const isVideo = media.mediaType === 'video' || hasInnerVideo;
  const isAudio = media.mediaType === 'audio';
  const isVoice = media.mediaType === 'voice';

  const size = getMediaFileSize(media) || 0; // Media types that do not have `size` are smaller than `MAX_BUFFER_SIZE`

  if (target === 'download') {
    if (IS_PROGRESSIVE_SUPPORTED && size > MAX_BUFFER_SIZE && !IS_OPFS_SUPPORTED) {
      return ApiMediaFormat.DownloadUrl;
    }
    return ApiMediaFormat.BlobUrl;
  }

  if (isVideo && IS_PROGRESSIVE_SUPPORTED && (
    target === 'full' || target === 'inline'
  )) {
    return ApiMediaFormat.Progressive;
  }

  if (isAudio || isVoice) {
    // Safari versions that support Opus are not working with streaming
    if (isVoice && (IS_SAFARI || !IS_OPUS_SUPPORTED)) {
      return ApiMediaFormat.BlobUrl;
    }

    return ApiMediaFormat.Progressive;
  }

  return ApiMediaFormat.BlobUrl;
}

function getMediaFileSize(media: DownloadableMedia) {
  return 'size' in media ? media.size : undefined;
}

function hasMediaLocalBlobUrl(media: ApiPhoto | ApiVideo | ApiDocument) {
  if ('blobUrl' in media) {
    return Boolean(media.blobUrl);
  }

  if ('previewBlobUrl' in media) {
    return Boolean(media.previewBlobUrl);
  }

  return false;
}

function getPhotoFullDimensions(photo: Pick<ApiPhoto, 'sizes' | 'thumbnail'>): ApiDimensions | undefined {
  return (
    photo.sizes.find((size) => size.type === 'w')
    || photo.sizes.find((size) => size.type === 'y')
    || getPhotoInlineDimensions(photo)
  );
}

function getMediaDimensions(
  media: ApiPhoto | ApiVideo | ApiMediaExtendedPreview | ApiWebDocument,
): ApiDimensions & { isFallback?: true } {
  let dimensions: ApiDimensions | undefined;

  if (media.mediaType === 'photo') {
    dimensions = media.sizes.reduce<ApiDimensions | undefined>((largest, size) => {
      if (!areMediaDimensionsValid(size)) return largest;
      if (!largest || size.width * size.height > largest.width * largest.height) return size;
      return largest;
    }, undefined) || media.thumbnail;
  } else if (media.mediaType === 'webDocument') {
    dimensions = media.dimensions;
  } else {
    dimensions = areMediaDimensionsValid(media)
      ? { width: media.width, height: media.height }
      : media.thumbnail;
  }

  if (dimensions && areMediaDimensionsValid(dimensions)) {
    return dimensions;
  }

  return {
    ...FALLBACK_MEDIA_DIMENSIONS,
    isFallback: true,
  };
}

function areMediaDimensionsValid(
  dimensions: { width?: number; height?: number },
): dimensions is ApiDimensions {
  const { width, height } = dimensions;
  return typeof width === 'number' && typeof height === 'number'
    && Number.isFinite(width) && Number.isFinite(height) && width > 0 && height > 0;
}

function getPhotoInlineDimensions(photo: Pick<ApiPhoto, 'sizes' | 'thumbnail'>): ApiDimensions | undefined {
  return (
    photo.sizes.find((size) => size.type === 'x')
    || photo.sizes.find((size) => size.type === 'm')
    || photo.sizes.find((size) => size.type === 's')
    || photo.thumbnail
  );
}

function getVideoDimensions(video: ApiVideo): ApiDimensions | undefined {
  if (video.width && video.height) {
    return video as ApiDimensions;
  }

  return undefined;
}

function getMediaTransferState(
  progress?: number, isLoadNeeded = false, isUploading = false,
) {
  const isTransferring = isUploading || isLoadNeeded;
  const transferProgress = progress || 0;

  return {
    isUploading, isTransferring, transferProgress,
  };
}

function getMediaSearchType(media: DownloadableMedia):
  Extract<ApiMessageSearchType, 'gif' | 'media' | 'documents' | 'audio' | 'voice'> | undefined {
  if (media.mediaType === 'video') {
    if (media.isRound) return 'voice';
    return media.isGif ? 'gif' : 'media';
  }

  if (media.mediaType === 'audio') {
    return 'audio';
  }

  if (media.mediaType === 'voice') {
    return 'voice';
  }

  if (media.mediaType === 'document') {
    return 'documents';
  }

  if (media.mediaType === 'photo') {
    return 'media';
  }

  return undefined;
}

function getMessageContentIds(
  messages: Record<number, ApiMessage>, messageIds: number[], contentType: ApiMessageSearchType,
) {
  let validator: (message: ApiMessage) => unknown;

  switch (contentType) {
    case 'media':
      validator = (message: ApiMessage) => {
        const video = getMessageVideo(message);
        return getMessagePhoto(message) || (video && !video.isRound && !video.isGif);
      };
      break;

    case 'documents':
      validator = getMessageDocument;
      break;

    case 'gif':
      validator = (message: ApiMessage) => {
        const video = getMessageVideo(message);
        return video?.isGif;
      };
      break;

    case 'links':
      validator = (message: ApiMessage) => getMessageWebPage(message) || matchLinkInMessageText(message);
      break;

    case 'audio':
      validator = getMessageAudio;
      break;

    case 'voice':
      validator = (message: ApiMessage) => {
        const video = getMessageVideo(message);
        return getMessageVoice(message) || (video && video.isRound);
      };
      break;

    default:
      return [] as Array<number>;
  }

  return messageIds.reduce((result, messageId) => {
    if (messages[messageId] && validator(messages[messageId])) {
      result.push(messageId);
    }

    return result;
  }, [] as Array<number>);
}

function isMediaLoadableInViewer(newMessage: ApiMessage) {
  if (!newMessage.content) return false;
  if (newMessage.content.photo) return true;
  if (newMessage.content.video && !newMessage.content.video.isRound && !newMessage.content.video.isGif) return true;
  return false;
}

function getMediaFilename(media: DownloadableMedia) {
  if ('fileName' in media && media.fileName) {
    return media.fileName;
  }

  if (media.mediaType === 'sticker') {
    const extension = media.isLottie ? 'tgs' : media.isVideo ? 'webm' : 'webp';
    return `${media.id}.${extension}`;
  }

  if (media.mediaType === 'photo') {
    return `${media.id}.${media.isVideo ? 'mp4' : 'jpg'}`;
  }

  if (media.mediaType === 'voice') {
    return `${media.id}.${IS_OPUS_SUPPORTED ? 'ogg' : 'wav'}`;
  }

  if ('id' in media && media.id) {
    return media.id;
  }

  return `${media.mediaType}-${Math.random().toString(36).slice(4)}`;
}

function getIsDownloading(activeDownloads: ActiveDownloads, media: DownloadableMedia) {
  const hash = getMediaHash(media, 'download');
  if (!hash) return false;
  return Boolean(activeDownloads[hash]);
}

function getMessageMediaHash(
  message: MediaContainer,
  statefulMedia: StatefulMediaContent,
  target: SizeTarget,
) {
  const {
    video, sticker, audio, voice, document,
  } = message.content;
  const { webPage } = statefulMedia;

  const messagePhoto = getMessagePhoto(message) || getWebPagePhoto(webPage);
  const actionPhoto = getMessageActionPhoto(message);
  const messageVideo = video || getWebPageVideo(webPage);
  const messageDocument = document || getWebPageDocument(webPage);
  const messageAudio = audio || getWebPageAudio(webPage);

  if (messageVideo) {
    return getVideoMediaHash(messageVideo, target);
  }

  if (messagePhoto || actionPhoto) {
    return getPhotoMediaHash(messagePhoto || actionPhoto!, target, Boolean(actionPhoto));
  }

  if (messageDocument) {
    return getDocumentMediaHash(messageDocument, target);
  }

  if (sticker) {
    return getStickerMediaHash(sticker, target);
  }

  if (messageAudio) {
    return getAudioMediaHash(messageAudio, target);
  }

  if (voice) {
    return getVoiceMediaHash(voice, target);
  }

  return undefined;
}

function getAllMessageMediaHashes(
  message: MediaContainer,
  statefulMedia: StatefulMediaContent,
) {
  const targets: SizeTarget[] = ['micro', 'pictogram', 'inline', 'preview', 'full', 'download'];
  const hashes = new Set<string>();

  targets.forEach((target) => {
    const hash = getMessageMediaHash(message, statefulMedia, target);
    if (hash) {
      hashes.add(hash);
    }
  });

  return Array.from(hashes);
}

function canReplaceMessageMedia(
  message: MediaContainer, attachment: ApiAttachment,
) {
  const isPhotoOrVideo = Boolean(getMessagePhoto(message) || getMessageVideo(message));
  const isFile = Boolean(getMessageAudio(message)
    || getMessageVoice(message) || getMessageDocument(message));

  const fileType = getAttachmentMediaType(attachment);

  return (
    (isPhotoOrVideo && (fileType === 'photo' || fileType === 'video'))
    || (isFile && (fileType === 'audio' || fileType === 'file'))
  );
}

async function saveWallpaperBlob(slug: string, blob: Blob) {
  try {
    await MAIN_IDB_STORE.set(buildWallpaperStoreKey(slug), blob);
    return true;
  } catch (err) {
    // eslint-disable-next-line no-console
    console.warn(err);
    return false;
  }
}

async function cacheWallpaperMedia(wallpaper: ApiWallpaper, mediaUrl: string) {
  const rawBlob = await fetchBlob(mediaUrl);
  const blob = wallpaper.isPattern ? await decodeWallpaperPatternBlob(rawBlob) : rawBlob;
  return saveWallpaperBlob(wallpaper.slug, blob);
}

async function clearWallpaperBlobs() {
  await Promise.all([
    cacheApi.clearShared(CUSTOM_BG_CACHE_NAME),
    cacheApi.clearAccountScopes(CUSTOM_BG_CACHE_NAME),
  ]);

  try {
    const keys = await MAIN_IDB_STORE.keys();
    const wallpaperKeys = keys.filter(
      (key): key is string => typeof key === 'string' && key.startsWith(WALLPAPER_STORE_KEY_PREFIX),
    );
    await MAIN_IDB_STORE.delMany(wallpaperKeys);
  } catch (err) {
    // eslint-disable-next-line no-console
    console.warn(err);
  }
}

async function migrateLegacyWallpaperBlobs(
  themes: Partial<Record<ThemeKey, IThemeSettings>>,
) {
  const migratedSlugs = new Set<string>();

  for (const theme of THEME_KEYS) {
    const slug = themes[theme]?.background;
    if (!isBlobWallpaper(slug) || migratedSlugs.has(slug)) continue;

    migratedSlugs.add(slug);
    if (await loadStoredWallpaperBlob(slug)) continue;

    const legacyBlob = await cacheApi.fetchShared(CUSTOM_BG_CACHE_NAME, slug, cacheApi.Type.Blob)
      || await cacheApi.fetchFromCurrentAccountScope(CUSTOM_BG_CACHE_NAME, slug, cacheApi.Type.Blob)
      || await cacheApi.fetchFromCurrentAccountScope(CUSTOM_BG_CACHE_NAME, theme, cacheApi.Type.Blob);
    if (legacyBlob) {
      await saveWallpaperBlob(slug, legacyBlob);
    }
  }
}

function updateSelectedWallpaperBlobs(
  selectedBackgrounds: string[],
  previousBackground: string | undefined,
  getSelectedBackgrounds: () => string[],
) {
  selectedBackgrounds.forEach(cancelBlobCleanup);

  if (!isBlobWallpaper(previousBackground) || selectedBackgrounds.includes(previousBackground)) return;

  removeWallpaperBlobIfUnused(previousBackground, getSelectedBackgrounds);
}

function removeWallpaperBlobIfUnused(
  background: string,
  getSelectedBackgrounds: () => string[],
) {
  if (!isBlobWallpaper(background)) return;

  cancelBlobCleanup(background);
  const timeout = window.setTimeout(() => {
    blobCleanupTimeouts.delete(background);
    if (!getSelectedBackgrounds().includes(background)) {
      void removeWallpaperBlob(background);
    }
  }, BLOB_CLEANUP_DELAY_MS);
  blobCleanupTimeouts.set(background, timeout);
}

async function prefetchWallpaperUrl(background?: string) {
  if (!isBlobWallpaper(background)) return;

  try {
    await getOrCreateWallpaperUrlEntry(background).promise;
  } catch {
    // The background hook retries the lookup and resets missing wallpaper settings
  }
}

function getResolvedWallpaperUrl(slug: string) {
  return wallpaperUrlEntries.get(slug)?.url;
}

function acquireWallpaperUrl(slug: string): WallpaperUrlHandle {
  const entry = getOrCreateWallpaperUrlEntry(slug);
  entry.refCount += 1;
  if (entry.revokeTimeout !== undefined) {
    clearTimeout(entry.revokeTimeout);
    entry.revokeTimeout = undefined;
  }

  let isReleased = false;
  return {
    promise: entry.promise,
    release() {
      if (isReleased) return;
      isReleased = true;
      releaseWallpaperUrlEntry(slug, entry);
    },
  };
}

release() {
      if (isReleased) return;
      isReleased = true;
      releaseWallpaperUrlEntry(slug, entry);
    }

function getOrCreateWallpaperUrlEntry(slug: string) {
  const existing = wallpaperUrlEntries.get(slug);
  if (existing) return existing;

  const entry: WallpaperUrlEntry = {
    promise: loadWallpaperUrl(slug),
    refCount: 0,
  };
  entry.promise.then((url) => {
    entry.url = url;
  }, () => {
    if (wallpaperUrlEntries.get(slug) === entry) {
      wallpaperUrlEntries.delete(slug);
    }
  });
  wallpaperUrlEntries.set(slug, entry);
  return entry;
}

async function loadWallpaperUrl(slug: string) {
  const blob = await loadWallpaperBlob(slug);
  const url = URL.createObjectURL(blob);

  try {
    await preloadImage(url);
  } catch (err) {
    URL.revokeObjectURL(url);
    throw err;
  }

  return url;
}

async function loadWallpaperBlob(slug: string): Promise<Blob> {
  const storedBlob = await loadStoredWallpaperBlob(slug);
  if (storedBlob) return storedBlob;

  const legacyBlob = await cacheApi.fetchShared(CUSTOM_BG_CACHE_NAME, slug, cacheApi.Type.Blob)
    || await cacheApi.fetchFromAccountScopes(CUSTOM_BG_CACHE_NAME, slug, cacheApi.Type.Blob);
  if (!legacyBlob) {
    throw new Error('CUSTOM_BG_MISSING');
  }

  await saveWallpaperBlob(slug, legacyBlob);
  return legacyBlob;
}

async function loadStoredWallpaperBlob(slug: string) {
  try {
    return await MAIN_IDB_STORE.get<Blob>(buildWallpaperStoreKey(slug));
  } catch (err) {
    // eslint-disable-next-line no-console
    console.warn(err);
    return undefined;
  }
}

async function removeWallpaperBlob(slug: string) {
  await Promise.all([
    cacheApi.removeShared(CUSTOM_BG_CACHE_NAME, slug),
    cacheApi.removeFromAccountScopes(CUSTOM_BG_CACHE_NAME, slug),
  ]);

  try {
    await MAIN_IDB_STORE.del(buildWallpaperStoreKey(slug));
  } catch (err) {
    // eslint-disable-next-line no-console
    console.warn(err);
  }
}

function releaseWallpaperUrlEntry(slug: string, entry: WallpaperUrlEntry) {
  entry.refCount -= 1;
  if (entry.refCount > 0) return;

  entry.revokeTimeout = window.setTimeout(() => {
    if (wallpaperUrlEntries.get(slug) === entry) {
      wallpaperUrlEntries.delete(slug);
    }
    entry.promise.then((url) => URL.revokeObjectURL(url)).catch(() => undefined);
  }, URL_REVOKE_DELAY_MS);
}

function cancelBlobCleanup(slug: string) {
  const timeout = blobCleanupTimeouts.get(slug);
  if (timeout === undefined) return;

  clearTimeout(timeout);
  blobCleanupTimeouts.delete(slug);
}

function buildWallpaperStoreKey(slug: string) {
  return `${WALLPAPER_STORE_KEY_PREFIX}${slug}`;
}

function isBlobWallpaper(background?: string): background is string {
  return Boolean(background && !background.startsWith('#'));
}

