function createSeededRandom(seed: number) {
  let value = seed >>> 0;

  return () => {
    value = (value * 1664525 + 1013904223) >>> 0;
    return value / 0x100000000;
  };
}

function generateRandomDates(count: number, now: Date) {
  const random = createSeededRandom(RANDOM_SEED);
  const dates: Date[] = [];

  for (let i = 0; i < count; i++) {
    const bucket = random();
    let offsetMs: number;

    if (bucket < 0.45) {
      offsetMs = -Math.floor(random() * DAY_IN_MS);
    } else if (bucket < 0.8) {
      offsetMs = -Math.floor(random() * 7 * DAY_IN_MS);
    } else if (bucket < 0.97) {
      offsetMs = -Math.floor((7 + random() * 358) * DAY_IN_MS);
    } else {
      offsetMs = Math.floor(random() * 2 * DAY_IN_MS);
    }

    dates.push(new Date(now.getTime() + offsetMs));
  }

  return dates;
}

function getDayStart(date: Date) {
  const result = new Date(date);
  result.setHours(0, 0, 0, 0);
  return result;
}

function formatPastTimeShortWithNewCore(lang: NewLangFn, date: Date) {
  const time = formatDateTime(lang, date, { time: 'short' });

  const today = getDayStart(new Date());
  if (date >= today) {
    return time;
  }

  const weekAgo = new Date(today);
  weekAgo.setDate(today.getDate() - 7);
  if (date >= weekAgo) {
    return formatDateTime(lang, date, { weekday: 'short' });
  }

  return formatDateTime(lang, date, {
    date: 'short',
    includeYear: date.getFullYear() === today.getFullYear() ? false : undefined,
  });
}

function createBenchmarkCases(oldLang: OldLangFn, lang: NewLangFn): BenchmarkCase[] {
  return [
    {
      name: 'time short',
      oldFormatter: (date) => oldFormatTime(oldLang, date),
      newFormatter: (date) => formatDateTime(lang, date, { time: 'short' }),
    },
    {
      name: 'past time short',
      oldFormatter: (date) => oldFormatPastTimeShort(oldLang, date),
      newFormatter: (date) => formatPastTimeShortWithNewCore(lang, date),
    },
    {
      name: 'date short',
      oldFormatter: (date) => oldFormatDateToString(date, oldLang.code, false, 'short'),
      newFormatter: (date) => formatDateTime(lang, date, { date: 'short' }),
    },
    {
      name: 'date + time short',
      oldFormatter: (date) => oldFormatDateTimeToString(date, oldLang.code, true, oldLang.timeFormat),
      newFormatter: (date) => formatDateTime(lang, date, { date: 'short', time: 'short' }),
    },
  ];
}

function measureFormatting(dates: Date[], formatter: BenchmarkFormatter): Measurement {
  let checksum = 0;
  let sample = '';

  const start = performance.now();
  for (let i = 0; i < dates.length; i++) {
    const value = formatter(dates[i]);

    if (!sample) {
      sample = value;
    }

    checksum = ((checksum * 33) + value.length + value.charCodeAt(0)) >>> 0;
  }
  const totalMs = performance.now() - start;

  return {
    totalMs,
    perCallMs: totalMs / dates.length,
    checksum,
    sample,
  };
}

function warmUp(dates: Date[], formatter: BenchmarkFormatter) {
  const warmUpCount = Math.min(250, dates.length);

  for (let i = 0; i < warmUpCount; i++) {
    formatter(dates[i]);
  }
}

function summarizeDates(dates: Date[]) {
  const today = getDayStart(new Date()).getTime();
  const weekAgo = today - (7 * DAY_IN_MS);

  let todayCount = 0;
  let lastWeekCount = 0;
  let olderCount = 0;
  let futureCount = 0;

  for (let i = 0; i < dates.length; i++) {
    const timestamp = dates[i].getTime();

    if (timestamp >= today) {
      if (timestamp >= Date.now()) {
        futureCount++;
      } else {
        todayCount++;
      }
      continue;
    }

    if (timestamp >= weekAgo) {
      lastWeekCount++;
      continue;
    }

    olderCount++;
  }

  return {
    today: todayCount,
    lastWeek: lastWeekCount,
    older: olderCount,
    future: futureCount,
  };
}

function logBenchmarkResults(
  lang: NewLangFn,
  oldLang: OldLangFn,
  now: Date,
  dates: Date[],
  results: BenchmarkResult[],
) {
  const formattedResults = Object.fromEntries(results.map((result) => {
    return [result.name, {
      old: {
        totalMs: Number(result.old.totalMs.toFixed(2)),
        perCallMs: Number(result.old.perCallMs.toFixed(8)),
        checksum: result.old.checksum,
        sample: result.old.sample,
      },
      new: {
        totalMs: Number(result.new.totalMs.toFixed(2)),
        perCallMs: Number(result.new.perCallMs.toFixed(8)),
        checksum: result.new.checksum,
        sample: result.new.sample,
      },
      newVsOld: Number((result.new.totalMs / result.old.totalMs).toFixed(2)),
    }];
  }));
  const label = [
    '[TestDateFormatPerf]',
    `lang=${lang.code}`,
    `oldLang=${oldLang.code}`,
    `timeFormat=${lang.timeFormat}`,
    `N=${BENCHMARK_COUNT}`,
  ].join(' ');

  // eslint-disable-next-line no-console
  console.group(label);
  // eslint-disable-next-line no-console
  console.log('dataset', {
    seed: RANDOM_SEED,
    generatedAt: now.toISOString(),
    distribution: summarizeDates(dates),
  });
  // eslint-disable-next-line no-console
  console.log('results', formattedResults);
  // eslint-disable-next-line no-console
  console.groupEnd();
}

function fetch<T extends ApiMediaFormat>(
  url: string,
  mediaFormat: T,
  isHtmlAllowed = false,
  onProgress?: ApiOnProgress,
  callbackUniqueId?: string,
): Promise<ApiPreparedMedia> {
  if (mediaFormat === ApiMediaFormat.Progressive) {
    return (
      IS_PROGRESSIVE_SUPPORTED
        ? Promise.resolve(getProgressiveUrl(url))
        : fetch(url, ApiMediaFormat.BlobUrl, isHtmlAllowed, onProgress, callbackUniqueId)
    );
  }

  if (mediaFormat === ApiMediaFormat.DownloadUrl) {
    return (
      IS_PROGRESSIVE_SUPPORTED
        ? Promise.resolve(getDownloadUrl(url))
        : fetch(url, ApiMediaFormat.BlobUrl, isHtmlAllowed, onProgress, callbackUniqueId)
    );
  }

  if (!fetchPromises.has(url)) {
    const promise = fetchFromCacheOrRemote(url, mediaFormat, isHtmlAllowed)
      .catch((err) => {
        if (DEBUG) {
          // eslint-disable-next-line no-console
          console.warn(err);
        }

        return undefined;
      })
      .finally(() => {
        fetchPromises.delete(url);
        progressCallbacks.delete(url);
        cancellableCallbacks.delete(url);
      });

    fetchPromises.set(url, promise);
  }

  if (onProgress && callbackUniqueId) {
    let activeCallbacks = progressCallbacks.get(url);
    if (!activeCallbacks) {
      activeCallbacks = new Map<string, ApiOnProgress>();
      progressCallbacks.set(url, activeCallbacks);
    }
    activeCallbacks.set(callbackUniqueId, onProgress);
  }

  return fetchPromises.get(url) as Promise<ApiPreparedMedia>;
}

function getFromMemory(url: string) {
  return memoryCache.get(url) as ApiPreparedMedia;
}

function cancelProgress(progressCallback: ApiOnProgress) {
  progressCallbacks.forEach((map, url) => {
    map.forEach((callback) => {
      if (callback === progressCallback) {
        const parentCallback = cancellableCallbacks.get(url);
        if (!parentCallback) return;

        cancelApiProgress(parentCallback);
        cancellableCallbacks.delete(url);
        progressCallbacks.delete(url);
        return;
      }
    });
  });
}

function removeCallback(url: string, callbackUniqueId: string) {
  const callbacks = progressCallbacks.get(url);
  if (!callbacks) return;
  callbacks.delete(callbackUniqueId);
}

