function createTestUtilSlice() {
  const capturedLogs: string[] = [];
  const capturedErrors: CapturedError[] = [];

  const runtime: TgPluginRuntime = {
    isPluginEnabled: () => true,
    setPluginEnabled: () => {},
    createPluginReporter: (pluginName) => ({
      // Prefixing like the production reporter proves the slice logs through
      // a reporter bound to the plugin's name
      log: (message) => capturedLogs.push(`${pluginName}: ${message}`),
      logError: (action, error) => capturedErrors.push({ action, error }),
      wrap: (callback) => callback,
    }),
    // Event streams are not exercised by the facade slices
    subscribeApiUpdates: () => () => {},
    subscribeToStoreChanges: () => {},
    getActions: () => {
      throw new Error('the util slice never dispatches actions');
    },
    getCurrentTabId: () => 0,
    mainThreadId: 0,
    getActiveMessageList: () => undefined,
    getActiveChatId: () => {
      throw new Error('the util slice never reads the store');
    },
    getCurrentUserId: () => {
      throw new Error('the util slice never reads the store');
    },
    getChat: () => {
      throw new Error('the util slice never reads the store');
    },
    getLocalizedString: (key, variables) => `translated:${key}:${JSON.stringify(variables ?? {})}`,
    showNotification: () => {
      throw new Error('the util slice never shows notifications');
    },
  };

  const context = createPluginContext(TEST_PLUGIN_NAME, runtime.createPluginReporter(TEST_PLUGIN_NAME));

  return {
    runtime,
    util: createUtilSlice(context, runtime),
    capturedErrors,
    capturedLogs,
  };
}

function createMockedDialogFilter(id: number, mockData: MockTypes) {
  const dialogFilter = mockData.dialogFilters.find((f) => f.id === id);

  if (!dialogFilter) throw Error('No such dialog filter ' + id);

  const {
    includePeerIds = [],
    pinnedPeerIds = [],
    excludePeerIds = [],
    ...rest
  } = dialogFilter;

  return new Api.DialogFilter({
    ...rest,
    id,
    includePeers: includePeerIds.map((peer) => createMockedTypeInputPeer(peer, mockData)),
    pinnedPeers: pinnedPeerIds.map((peer) => createMockedTypeInputPeer(peer, mockData)),
    excludePeers: excludePeerIds.map((peer) => createMockedTypeInputPeer(peer, mockData)),
  });
}

function useEnsureStory(
  peerId?: string,
  storyId?: number,
  story?: ApiTypeStory,
) {
  const { loadPeerStoriesByIds } = getActions();

  const loadStoryThrottled = useMemo(() => {
    const throttled = throttle(loadPeerStoriesByIds, THROTTLE_THRESHOLD_MS, true);
    return () => {
      throttled({ peerId: peerId!, storyIds: [storyId!] });
    };
  }, [storyId, peerId]);

  useEffect(() => {
    const shouldLoadStory = !story || !('content' in story || 'isDeleted' in story);
    if (peerId && storyId && shouldLoadStory) {
      loadStoryThrottled();
    }
  }, [loadStoryThrottled, story, storyId, peerId]);
}

function useDetectChatLanguage(
  message: ApiMessage, detectedLanguage?: string, isDisabled?: boolean, getIsReady?: Signal<boolean>,
) {
  useEffect(() => {
    if (isDisabled || (getIsReady && !getIsReady())) return;

    const isTranslatable = Boolean(message.content.text?.text.length);
    processMessageMetadata({
      chatId: message.chatId,
      id: message.id,
      isTranslatable,
      detectedLanguage,
    });
  }, [message, detectedLanguage, isDisabled, getIsReady]);
}

function processMessageMetadata({
  chatId, id, isTranslatable, detectedLanguage,
}: {
  chatId: string;
  id: number;
  isTranslatable: boolean;
  detectedLanguage?: string;
}) {
  const chatStats = CHAT_STATS.get(chatId) || new LimitedMap<number, MessageMetadata>(MESSAGES_LIMIT);

  const previousMetadata = chatStats.get(id);
  if (previousMetadata && previousMetadata.detectedLanguage === detectedLanguage
    && previousMetadata.isTranslatable === isTranslatable
  ) {
    return;
  }

  chatStats.set(id, {
    id,
    isTranslatable,
    detectedLanguage,
  });

  CHAT_STATS.set(chatId, chatStats);

  throttledMakeChatDecision(chatId);
}

function makeChatDecision(chatId: string) {
  const { updateChatDetectedLanguage } = getActions();
  const chatStats = CHAT_STATS.get(chatId);
  if (!chatStats) {
    return;
  }

  const messagesChecked = chatStats.size;
  if (messagesChecked < MIN_MESSAGES_CHECKED) {
    return;
  }

  let translatableCount = 0;
  let detectableCount = 0;
  const languageOccurrences = new Map<string, number>();

  for (const metadata of chatStats.values()) {
    if (metadata.isTranslatable) {
      translatableCount++;
    }

    if (metadata.detectedLanguage) {
      detectableCount++;
    }

    const language = metadata.detectedLanguage;
    if (language) {
      const occurrences = languageOccurrences.get(language) || 0;
      languageOccurrences.set(language, occurrences + 1);
    }
  }

  const translatableRatio = translatableCount / messagesChecked;
  const detectableRatio = detectableCount / translatableCount;

  if (translatableRatio < MIN_TRANSLATABLE_RATIO || detectableRatio < MIN_DETECTABLE_RATIO) {
    return;
  }

  const mostFrequentLanguage = Array.from(languageOccurrences.entries())
    .sort(([, a], [, b]) => b - a)[0][0];

  updateChatDetectedLanguage({
    chatId,
    detectedLanguage: mostFrequentLanguage,
  });
}

async function fetchMessages({
  chat,
  threadId,
  offsetId,
  isSavedDialog,
  addOffset,
  limit,
}: {
  chat: ApiChat;
  threadId?: ThreadId;
  offsetId?: number;
  isSavedDialog?: boolean;
  addOffset?: number;
  limit: number;
}) {
  const RequestClass = threadId === MAIN_THREAD_ID
    ? GramJs.messages.GetHistory : isSavedDialog
      ? GramJs.messages.GetSavedHistory : GramJs.messages.GetReplies;
  const isChannel = getEntityTypeById(chat.id) === 'channel';
  let result;

  try {
    result = await invokeRequest(new RequestClass({
      hash: DEFAULT_PRIMITIVES.BIGINT,
      maxId: DEFAULT_PRIMITIVES.INT,
      minId: DEFAULT_PRIMITIVES.INT,
      offsetDate: DEFAULT_PRIMITIVES.INT,
      peer: buildInputPeer(chat.id, chat.accessHash),
      ...(threadId !== MAIN_THREAD_ID && !isSavedDialog && {
        msgId: Number(threadId),
      }),
      // Workaround for local message IDs overflowing some internal range check
      offsetId: offsetId ? Math.min(offsetId, MAX_INT_32) : DEFAULT_PRIMITIVES.INT,
      addOffset: addOffset ?? DEFAULT_PRIMITIVES.INT,
      limit,
    }), {
      shouldThrow: true,
      abortControllerChatId: chat.id,
      abortControllerThreadId: threadId,
    });
  } catch (err: any) {
    if (err.errorMessage === 'CHANNEL_PRIVATE') {
      sendApiUpdate({
        '@type': 'updateChat',
        id: chat.id,
        chat: {
          isRestricted: true,
        },
      });
    }
  }

  if (
    !result
    || result instanceof GramJs.messages.MessagesNotModified
    || !result.messages
  ) {
    return undefined;
  }

  if (isChannel && 'pts' in result) {
    updateChannelState(chat.id, result.pts);
  }

  const messages = result.messages.map(buildApiMessage).filter(Boolean);
  const users = result.users.map(buildApiUser).filter(Boolean);
  const chats = result.chats.map((c) => buildApiChatFromPreview(c)).filter(Boolean);
  const count = 'count' in result ? result.count : messages.length;
  const topics = result.topics.map(buildApiTopicWithState).filter(Boolean);

  return {
    messages,
    users,
    chats,
    count,
    topics,
  };
}

async function fetchMessage({ chat, messageId }: { chat: ApiChat; messageId: number }) {
  const isChannel = getEntityTypeById(chat.id) === 'channel';

  let result;
  try {
    result = await invokeRequest(
      isChannel
        ? new GramJs.channels.GetMessages({
          channel: buildInputChannel(chat.id, chat.accessHash),
          id: [new GramJs.InputMessageID({ id: messageId })],
        })
        : new GramJs.messages.GetMessages({
          id: [new GramJs.InputMessageID({ id: messageId })],
        }),
      {
        shouldThrow: true,
        abortControllerChatId: chat.id,
      },
    );
  } catch (err: any) {
    const { message, code } = buildApiError(err);

    // When fetching messages for the bot @replies, there may be situations when the user was banned
    // in the comment group or this group was deleted
    if (message !== 'CHANNEL_PRIVATE') {
      sendApiUpdate({
        '@type': 'error',
        error: {
          message,
          code,
          isSlowMode: false,
          hasErrorKey: true,
        },
      });
    }
  }

  if (!result || result instanceof GramJs.messages.MessagesNotModified) {
    return undefined;
  }

  if (isChannel && 'pts' in result) {
    updateChannelState(chat.id, result.pts);
  }

  const mtpMessage = result.messages[0];
  if (!mtpMessage) {
    return undefined;
  }

  if (mtpMessage instanceof GramJs.MessageEmpty) {
    return MESSAGE_DELETED;
  }

  processMessageAndUpdateThreadInfo(mtpMessage);
  const message = buildApiMessage(mtpMessage);

  if (!message) {
    return undefined;
  }

  return { message };
}

