function ControlText({
  htmlFor,
  className,
  baseClassName,
  children,
}: ControlTextProps & { baseClassName: string }) {
  const control = useControlContext();
  const interactive = useInteractiveContext();
  const resolvedHtmlFor = htmlFor ?? control?.id;
  const shouldRenderLabel = !interactive?.isLabel && resolvedHtmlFor;

  if (shouldRenderLabel) {
    return (
      <label
        htmlFor={resolvedHtmlFor}
        className={buildClassName(baseClassName, className)}
        dir="auto"
      >
        {children}
      </label>
    );
  }

  return (
    <span
      className={buildClassName(baseClassName, className)}
      dir="auto"
    >
      {children}
    </span>
  );
}

function launchMediaWorkers() {
  if (IS_TEST) return [];
  if (!instances) {
    instances = new Array(MAX_WORKERS).fill(undefined).map(
      () => {
        const worker = new Worker(new URL('../lib/mediaWorker/index.worker.ts', import.meta.url), { type: 'module' });
        const connector = createConnector<MediaWorkerApi>(worker, undefined, 'media');
        return { worker, connector };
      },
    );
  }

  return instances;
}

function requestMediaWorker(payload: Parameters<Connector<MediaWorkerApi>['request']>[0], index: number) {
  return launchMediaWorkers()[index].connector.request(payload);
}

parseMarkdown(token, helpers) {
