function SpeedingDiamond({ className, onMouseMove }: OwnProps) {
  const [speed, setSpeed] = useState(MIN_SPEED);

  const handleMouseMove = useLastCallback(() => {
    if (slowdownTimeout) {
      clearTimeout(slowdownTimeout);
      slowdownTimeout = undefined;
    }

    slowdownTimeout = window.setTimeout(() => {
      const startAt = Date.now();

      isAnimating = true;

      animateSingle(() => {
        if (!isAnimating) return false;

        const t = Math.min((Date.now() - startAt) / SLOWDOWN_DURATION, 1);
        const newSpeed = (MAX_SPEED - MIN_SPEED) * (1 - transition(t));

        setSpeed(newSpeed);

        isAnimating = t < 1 && newSpeed > 1;

        return isAnimating;
      }, requestMutation, ANIMATION_INSTANCE);
    }, SLOWDOWN_DELAY);

    isAnimating = false;
    setSpeed(MAX_SPEED);
    onMouseMove();
  });

  return (
    <div className={buildClassName(styles.root, className)}>
      <div
        className={styles.diamond}
        onMouseMove={handleMouseMove}
      >
        <AnimatedIconWithPreview
          speed={speed}
          size={130}
          tgsUrl={LOCAL_TGS_URLS.Diamond}
          previewUrl={diamondPreviewUrl}
          nonInteractive
          noLoop={false}
        />
      </div>
    </div>
  );
}

function transition(t: number) {
  return 1 - ((1 - t) ** 2);
}

function useOffscreenCanvasBlur(
  thumbData?: string, // data URI or blob URL
  isDisabled = false,
) {
  const canvasRef = useRef<HTMLCanvasElement>();
  const workerIndex = useMemo(() => cycleRestrict(MAX_WORKERS, ++lastWorkerIndex), []);
  const offscreenRef = useRef<OffscreenCanvas>();

  const blurThumb = useLastCallback(async (canvas: HTMLCanvasElement, uri: string) => {
    const image = await preloadImage(uri);
    if (!image) {
      return;
    }

    requestMutation(() => {
      canvas.width = image.width;
      canvas.height = image.height;

      offscreenRef.current = canvas.transferControlToOffscreen();

      const radius = Math.ceil(Math.min(image.width, image.height) * RADIUS_RATIO);

      requestMediaWorker({
        name: 'offscreen-canvas:blurThumb',
        args: [offscreenRef.current, uri, radius],
        transferables: [offscreenRef.current],
      }, workerIndex);
    });
  });

  useLayoutEffect(() => {
    if (!thumbData || isDisabled || offscreenRef.current) return;

    const canvas = canvasRef.current;
    if (!canvas) return;

    blurThumb(canvas, thumbData);
  }, [blurThumb, isDisabled, thumbData]);

  return canvasRef;
}

