function useOrderDiff(orderedIds: (string | number)[] | undefined, topOffset: number, key?: string) {
  const orderById = useMemo(() => {
    if (!orderedIds) {
      return undefined;
    }

    return orderedIds.reduce((acc, id, i) => {
      acc[id] = i;
      return acc;
    }, {} as Record<string, number>);
  }, [orderedIds]);

  const prevOrderById = usePreviousDeprecated(orderById);
  const prevChatId = usePreviousDeprecated(key);
  const prevTopOffset = usePreviousDeprecated(topOffset);
  const isInitialRenderRef = useRef(true);

  useEffect(() => {
    requestNextMutation(() => {
      isInitialRenderRef.current = false;
    });
  }, []);

  const orderDiffByIdRef = useRef<Record<string | number, number>>(EMPTY_ORDER_DIFF);
  const forceUpdate = useForceUpdate();

  const onReorderAnimationEnd = useLastCallback(() => {
    if (orderDiffByIdRef.current === EMPTY_ORDER_DIFF) return;

    orderDiffByIdRef.current = EMPTY_ORDER_DIFF;
    forceUpdate();
  });

  const shiftDiff = prevTopOffset !== undefined ? topOffset - prevTopOffset : 0;

  useSyncEffect(() => {
    if (!orderById || !prevOrderById || key !== prevChatId || prevOrderById === orderById) {
      orderDiffByIdRef.current = EMPTY_ORDER_DIFF;
      return;
    }

    const diff = mapValues(orderById, (order, id) => {
      return prevOrderById[id] !== undefined ? order - prevOrderById[id] : -Infinity;
    });

    const hasChanges = Object.values(diff).some((value) => value !== 0);
    orderDiffByIdRef.current = hasChanges ? diff : EMPTY_ORDER_DIFF;
  }, [key, orderById, prevChatId, prevOrderById, topOffset]);

  const getAnimationType = useChatAnimationType(
    orderDiffByIdRef.current,
    isInitialRenderRef.current,
    Boolean(shiftDiff),
  );

  return {
    orderDiffById: orderDiffByIdRef.current,
    shiftDiff,
    getAnimationType,
    onReorderAnimationEnd,
  };
}

function download(url: string, filename: string) {
  pendingDownloads.push({ url, filename });
  if (!planned) {
    planned = true;
    setTimeout(async () => {
      await processQueue();
      planned = false;
    }, BATCH_INTERVAL);
  }
}

async function processQueue() {
  let count = 0;
  for (const pendingDownload of pendingDownloads) {
    downloadOne(pendingDownload);
    count++;
    if (count === LIMIT_PER_BATCH) {
      await pause(BATCH_INTERVAL);
      count = 0;
    }
  }
  pendingDownloads = [];
}

function downloadOne({ url, filename }: PendingDownload) {
  const link = document.createElement('a');
  link.href = url;
  link.target = '_blank';
  link.rel = 'noopener noreferrer';
  link.download = filename;
  try {
    link.click();
  } catch (err) {
    // eslint-disable-next-line no-console
    console.error(err); // Suppress redundant "Blob loading failed" error popup on IOS
  }
}

class ObfuscatedIO {
  header?: Uint8Array = undefined;

  private connection: PromisedWebSockets | HttpStream;

  private _encrypt: CTR;

  private _decrypt: CTR;

  constructor(connection: ConnectionTCPObfuscated) {
    this.connection = connection.socket;
    const res = this.initHeader(connection.PacketCodecClass);
    this.header = res.random;

    this._encrypt = res.encryptor;
    this._decrypt = res.decryptor;
  }

  initHeader(packetCodec: typeof AbridgedPacketCodec) {
    // Prevent the random prefix from being detected as another accepted transport
    // https://core.telegram.org/mtproto/mtproto-transports#transport-obfuscation
    let random;

    while (true) {
      random = generateRandomBytes(64);
      const firstInt = random.slice(0, 4);
      const hasForbiddenPrefix = FORBIDDEN_OBFUSCATED_PREFIXES.some(
        (prefix) => buffersEqual(prefix, firstInt),
      );
      if (
        random[0] !== 0xef
        && !hasForbiddenPrefix
        && !buffersEqual(random.slice(4, 8), ZERO_INT)
      ) {
        break;
      }
    }

    const randomReversed = random.slice(8, 56).reverse();
    // Encryption has "continuous buffer" enabled
    const encryptKey = random.slice(8, 40);
    const encryptIv = random.slice(40, 56);
    const decryptKey = randomReversed.slice(0, 32);
    const decryptIv = randomReversed.slice(32, 48);
    const encryptor = new CTR(encryptKey, encryptIv);
    const decryptor = new CTR(decryptKey, decryptIv);

    random = concat(
      random.slice(0, 56), packetCodec.obfuscateTag, random.slice(60),
    );
    random = concat(
      random.slice(0, 56), encryptor.encrypt(random).slice(56, 64), random.slice(64),
    );
    return {
      random,
      encryptor,
      decryptor,
    };
  }

  async read(n: number) {
    const data = await this.connection.readExactly(n);
    return this._decrypt.encrypt(data);
  }

  write(data: Uint8Array) {
    this.connection.write(this._encrypt.encrypt(data));
  }
}

