function buildApiMessageEntity(entity: GramJs.TypeMessageEntity): ApiMessageEntity {
  const {
    className: type, offset, length,
  } = entity;

  if (entity instanceof GramJs.MessageEntityMentionName) {
    return {
      type: ApiMessageEntityTypes.MentionName,
      offset,
      length,
      userId: buildApiPeerId(entity.userId, 'user'),
    };
  }

  if (entity instanceof GramJs.MessageEntityTextUrl) {
    return {
      type: ApiMessageEntityTypes.TextUrl,
      offset,
      length,
      url: entity.url,
    };
  }

  if (entity instanceof GramJs.MessageEntityPre) {
    return {
      type: ApiMessageEntityTypes.Pre,
      offset,
      length,
      language: entity.language,
    };
  }

  if (entity instanceof GramJs.MessageEntityCustomEmoji) {
    return {
      type: ApiMessageEntityTypes.CustomEmoji,
      offset,
      length,
      documentId: entity.documentId.toString(),
    };
  }

  if (entity instanceof GramJs.MessageEntityBlockquote) {
    return {
      type: ApiMessageEntityTypes.Blockquote,
      canCollapse: entity.collapsed,
      offset,
      length,
    };
  }

  if (entity instanceof GramJs.MessageEntityFormattedDate) {
    return {
      type: ApiMessageEntityTypes.FormattedDate,
      offset,
      length,
      date: entity.date,
      relative: entity.relative,
      shortTime: entity.shortTime,
      longTime: entity.longTime,
      shortDate: entity.shortDate,
      longDate: entity.longDate,
      dayOfWeek: entity.dayOfWeek,
    };
  }

  if (entity instanceof GramJs.MessageEntityDiffInsert) {
    return {
      type: ApiMessageEntityTypes.DiffInsert,
      offset,
      length,
    };
  }

  if (entity instanceof GramJs.MessageEntityDiffReplace) {
    return {
      type: ApiMessageEntityTypes.DiffReplace,
      offset,
      length,
      oldText: entity.oldText,
    };
  }

  if (entity instanceof GramJs.MessageEntityDiffDelete) {
    return {
      type: ApiMessageEntityTypes.DiffDelete,
      offset,
      length,
    };
  }

  return {
    type: type as `${ApiMessageEntityDefault['type']}`,
    offset,
    length,
  };
}

