  });
}

function buildCsp(appEnv: string) {
  return `
  default-src 'self';
  connect-src 'self' wss://*.web.telegram.org blob: http: https: ${appEnv === 'development' ? 'wss: ipc:' : ''};
  script-src 'self' 'wasm-unsafe-eval'
