function computeEmojiIndex(bytes: Uint8Array) {
  return ((BigInt(bytes[0]) & 0x7Fn) << 56n)
    | ((BigInt(bytes[1]) << 48n))
    | ((BigInt(bytes[2]) << 40n))
    | ((BigInt(bytes[3]) << 32n))
    | ((BigInt(bytes[4]) << 24n))
    | ((BigInt(bytes[5]) << 16n))
    | ((BigInt(bytes[6]) << 8n))
    | ((BigInt(bytes[7])));
}

async function generateEmojiFingerprint(
  authKey: Uint8Array, gA: Uint8Array, emojiData: Uint16Array, emojiOffsets: number[],
) {
  const hash = await sha256(concat(new Uint8Array(authKey), new Uint8Array(gA)));
  const result = [];
  const emojiCount = emojiOffsets.length - 1;
  const kPartSize = 8;
  for (let partOffset = 0; partOffset !== hash.byteLength; partOffset += kPartSize) {
    const value = computeEmojiIndex(hash.subarray(partOffset, partOffset + kPartSize));
    const index = Number(value % BigInt(emojiCount));
    const offset = emojiOffsets[index];
    const size = emojiOffsets[index + 1] - offset;
    result.push(String.fromCharCode(...emojiData.subarray(offset, offset + size)));
  }
  return result.join('');
}

async function validateGAHash(gA: Uint8Array, expectedHash: number[]) {
  if (expectedHash.length !== SHA256_HASH_BYTES) {
    throw new SecurityError('Invalid phone call gA hash');
  }

  const actualHash = await sha256(gA);
  if (!compareBuffersConstantTime(actualHash, Uint8Array.from(expectedHash))) {
    throw new SecurityError('Phone call gA hash mismatch');
  }
}

function createPhoneCallState({
  isOutgoing,
  shouldUseSctp = true,
}: {
  isOutgoing: boolean;
  shouldUseSctp?: boolean;
}) {
  currentPhoneCallState = new PhoneCallState(isOutgoing, shouldUseSctp);
}

function setPhoneCallSctpEnabled(shouldUseSctp: boolean) {
  currentPhoneCallState?.setShouldUseSctp(shouldUseSctp);
}

function destroyPhoneCallState() {
  currentPhoneCallState?.destroy();
  currentPhoneCallState = undefined;
}

function encodePhoneCallData({ data }: PhoneCallDataParams): ReturnTypeOf<'encode'> {
  return currentPhoneCallState!.encode(data);
}

async function decodePhoneCallData({ data }: DecodePhoneCallDataParams) {
  if (!currentPhoneCallState) {
    return undefined;
  }
  const result = await currentPhoneCallState.decode(data);
  return result;
}

function drainPhoneCallSignalingData() {
  return currentPhoneCallState?.drainSignalingData() || [];
}

function confirmPhoneCall(params: ConfirmCallParams): ReturnTypeOf<'confirmCall'> {
  return currentPhoneCallState!.confirmCall(params);
}

function verifyPhoneCallKeyFingerprint(
  params: VerifyKeyFingerprintParams,
): ReturnTypeOf<'verifyKeyFingerprint'> {
  return currentPhoneCallState!.verifyKeyFingerprint(params);
}

function acceptPhoneCall(params: DhConfig): ReturnTypeOf<'acceptCall'> {
  return currentPhoneCallState!.acceptCall(params);
}

function requestPhoneCall(params: DhConfig): ReturnTypeOf<'requestCall'> {
  return currentPhoneCallState!.requestCall(params);
}

function getEmojiOnlyCountForMessage(content: MediaContent, groupedId?: string): number | undefined {
  if (!content.text) return undefined;
  return (
    !groupedId
    && Object.keys(content).length === 1 // Only text is present
    && !content.text.entities?.some((entity) => entity.type !== ApiMessageEntityTypes.CustomEmoji)
    && parseEmojiOnlyString(content.text.text)
  ) || undefined;
}

function getRichMessageText(value?: ApiInputRichMessage) {
  return value?.blocks.length ? getRichMessagePreviewText(value) : EMPTY_TEXT;
}

function hasEditorCollapsedSelection(editor?: Editor) {
  return Boolean(editor?.state.selection.empty);
}

function insertEditorContent(
  editor: Editor | undefined,
  content: RichEditorInsertContent | RichEditorInsertContent[],
  shouldPrepend = false,
) {
  if (!editor) {
    return;
  }

  const tiptapContent = buildTiptapContent(content);
  if (!tiptapContent) {
    return;
  }

  if (shouldPrepend) {
    editor.chain().focus('start').insertContent(tiptapContent).run();
    return;
  }

  editor.chain().focus().insertContent(tiptapContent).run();
}

function replaceEditorRange(
  editor: Editor | undefined,
  range: { from: number; to: number },
  content: RichEditorInsertContent | RichEditorInsertContent[],
) {
  if (!editor) {
    return;
  }

  const tiptapContent = buildTiptapContent(content);
  if (!tiptapContent) {
    return;
  }

  const replaceRange = buildEditorReplaceRange(editor, range);

  editor.chain()
    .focus()
    .deleteRange(replaceRange)
    .insertContent(tiptapContent)
    .run();
}

function deleteEditorCharacterBeforeSelection(editor: Editor | undefined) {
  if (!editor) {
    return;
  }

  const { $from, from, to } = editor.state.selection;
  if (from !== to) {
    editor.chain().focus().deleteSelection().run();
    return;
  }

  if (from <= 1) {
    return;
  }

  const previousNode = $from.nodeBefore;
  const deleteLength = previousNode?.text
    ? getPreviousGraphemeLength(previousNode.text)
    : previousNode?.nodeSize || 1;

  editor.chain().focus().deleteRange({ from: from - deleteLength, to: from }).run();
}

function buildMentionContent(
  userId: string | undefined,
  username: string | undefined,
  text: string,
): TiptapJsonContent {
  return {
    type: 'mention',
    attrs: {
      userId,
      username,
      label: text,
    },
    content: text ? [{
      type: 'text',
      text,
    }] : undefined,
  };
}

function buildEditorReplaceRange(editor: Editor, range: { from: number; to: number }) {
  let replaceRange = range;
  const { doc } = editor.state;
  const from = Math.max(0, range.from - 1);
  const to = Math.min(doc.content.size, range.to + 1);

  doc.nodesBetween(from, to, (node, pos) => {
    if (node.type.name !== 'mention') {
      return;
    }

    const nodeTo = pos + node.nodeSize;
    if (range.from >= pos && range.to <= nodeTo) {
      replaceRange = { from: pos, to: nodeTo };
      return false;
    }

    return undefined;
  });

  return replaceRange;
}

function buildCustomEmojiTiptapNode(emoji: ApiSticker): TiptapJsonContent {
  const className = buildClassName(
    'custom-emoji',
    'emoji',
    'emoji-small',
    'placeholder',
    emoji.shouldUseTextColor && 'colorable',
  );

  return {
    type: 'customEmoji',
    attrs: {
      className,
      alt: emoji.emoji || EMPTY_TEXT,
      documentId: emoji.id,
      src: placeholderSrc,
    },
