}

function buildTiptapContentFromFormattedText(text: ApiFormattedText) {
  const richMessage = buildRichMessageFromFormatted(text);
  const content = buildTiptapJsonFromRichMessage(richMessage).content || [];
  const block = content[0];
  if (content.length === 1 && block.type === 'paragraph') {
    return block.content || [];
  }

  return content;
}

function buildTiptapContent(content: RichEditorInsertContent | RichEditorInsertContent[]) {
  const result = (Array.isArray(content) ? content : [content]).flatMap(buildTiptapContentPart);

  return result.length ? result : undefined;
}

function buildTiptapContentPart(content: RichEditorInsertContent): TiptapJsonContent[] {
  switch (content.type) {
    case 'text':
      return content.text ? [{ type: 'text', text: content.text }] : [];
    case 'formattedText':
      return content.text.text ? buildTiptapContentFromFormattedText(content.text) : [];
    case 'customEmoji':
      return [buildCustomEmojiTiptapNode(content.emoji)];
    case 'mention':
      return [buildMentionContent(content.userId, content.username, content.text)];
    default:
      return [];
  }
}

function getPreviousGraphemeLength(text: string) {
  const previousGrapheme = GRAPHEME_SEGMENTER?.segment(text).containing(text.length - 1);

  return previousGrapheme?.segment.length || Array.from(text).at(-1)!.length;
}

function useTopicContextActions({
  topic,
  unreadCount,
  chat,
  isChatMuted,
  wasOpened,
  canDelete,
  handleDelete,
  handleMute,
  handleUnmute,
}: {
  topic: ApiTopic;
  chat: ApiChat;
  unreadCount?: number;
  isChatMuted?: boolean;
  wasOpened?: boolean;
  canDelete?: boolean;
  handleDelete?: NoneToVoidFunction;
  handleMute?: NoneToVoidFunction;
  handleUnmute?: NoneToVoidFunction;
}) {
  const lang = useLang();
  const oldLang = useOldLang();

  const preparedActions = useMemo(() => {
    const {
      isPinned, notifySettings, isClosed, id: topicId,
    } = topic;

    const chatId = chat.id;

    const {
      editTopic,
      toggleTopicPinned,
      markTopicRead,
      openChatInNewTab,
      openQuickPreview,
    } = getActions();

    const canToggleClosed = getCanManageTopic(chat, topic) && !chat.isBotForum;
    const canTogglePinned = getHasAdminRight(chat, 'manageTopics');

    const actionOpenInNewTab = IS_OPEN_IN_NEW_TAB_SUPPORTED && {
      title: IS_TAURI ? lang('ChatListOpenInNewWindow') : lang('ChatListOpenInNewTab'),
      icon: 'open-in-new-tab',
      handler: () => {
        openChatInNewTab({ chatId: chat.id, threadId: topicId });
      },
    };

    const actionQuickPreview = {
      title: lang('QuickPreview'),
      icon: 'eye-outline',
      handler: () => {
        openQuickPreview({ id: chatId, threadId: topicId });
      },
    };

    const actionUnreadMark = unreadCount || !wasOpened
      ? {
        title: oldLang('MarkAsRead'),
        icon: 'readchats',
        handler: () => {
          markTopicRead({ chatId, topicId });
        },
      }
      : undefined;

    const actionPin = canTogglePinned ? (isPinned
      ? {
        title: oldLang('UnpinFromTop'),
        icon: 'unpin',
        handler: () => toggleTopicPinned({ chatId, topicId, isPinned: false }),
      }
      : {
        title: oldLang('PinToTop'),
        icon: 'pin',
        handler: () => toggleTopicPinned({ chatId, topicId, isPinned: true }),
      }) : undefined;

    const actionMute = ((isChatMuted && notifySettings.mutedUntil === undefined) || notifySettings.mutedUntil)
      ? {
        title: oldLang('ChatList.Unmute'),
        icon: 'unmute',
        handler: handleUnmute,
      }
      : {
        title: `${oldLang('ChatList.Mute')}...`,
        icon: 'mute',
        handler: handleMute,
      };

    const actionCloseTopic = canToggleClosed ? (isClosed
      ? {
        title: oldLang('lng_forum_topic_reopen'),
        icon: 'reopen-topic',
        handler: () => editTopic({ chatId, topicId, isClosed: false }),
      }
      : {
        title: oldLang('lng_forum_topic_close'),
        icon: 'close-topic',
        handler: () => editTopic({ chatId, topicId, isClosed: true }),
      }) : undefined;

    const actionDelete = canDelete ? {
      title: oldLang('lng_forum_topic_delete'),
      icon: 'delete',
      destructive: true,
      handler: handleDelete,
    } : undefined;

    return compact([
      actionOpenInNewTab,
      actionQuickPreview,
      actionPin,
      actionUnreadMark,
      actionMute,
      actionCloseTopic,
      actionDelete,
    ]) as MenuItemContextAction[];
  }, [
    chat, topic, unreadCount, wasOpened, isChatMuted, canDelete,
    handleDelete, handleMute, handleUnmute, lang, oldLang,
  ]);

  return preparedActions;
}

