function createMockedReplies(chatId: string, id: number, mockData: MockTypes) {
  const msg = mockData.messages[chatId].find((message) => message.id === id);

  if (!msg) throw Error(`No such message ${id}`);

  const {
    replies,
  } = msg;

  if (!replies) throw Error(`No replies on message ${id}`);

  return new Api.MessageReplies({
    comments: true,
    replies: replies.replies,
    repliesPts: 1,
    channelId: -2n - CHANNEL_ID_BASE,
    // recentRepliers?: Api.TypePeer[];
  });
}

function createUiSlice(context: PluginContext, runtime: TgPluginRuntime): TgPluginApi['ui'] {
  const { pluginName, wrap, onTeardown } = context;

  onTeardown(() => {
    clearMessageContextMenuItems(pluginName);
    clearChatContextMenuItems(pluginName);
    clearMainMenuItems(pluginName);
    clearComposerButtons(pluginName);
  });

  return {
    addMessageContextMenuItem: (item: TgMessageContextMenuItem) => {
      registerMessageContextMenuItem(pluginName, {
        ...item,
        onClick: wrap(item.onClick),
      });
    },
    addChatContextMenuItem: (item: TgChatContextMenuItem) => {
      registerChatContextMenuItem(pluginName, {
        ...item,
        onClick: wrap(item.onClick),
      });
    },
    addMainMenuItem: (item: TgMainMenuItem) => {
      registerMainMenuItem(pluginName, {
        ...item,
        onClick: wrap(item.onClick),
      });
    },
    addComposerButton: (item: TgComposerButton) => {
      registerComposerButton(pluginName, {
        ...item,
        onClick: wrap(item.onClick),
      });
    },
    showNotification: (notification: TgUiNotification) => {
      // The runtime service can throw (e.g. a malformed payload); contain it like a callback
      wrap(() => runtime.showNotification(notification))();
    },
  };
}

function initializeSoundsForSafari() {
  initializeSounds();

  return Promise.all(Object.values(sounds).map((sound) => {
    const prevSrc = sound.src;
    sound.src = silentSound;
    sound.muted = true;
    sound.volume = 0.0001;
    return sound.play()
      .then(() => {
        sound.pause();
        sound.volume = 1;
        sound.currentTime = 0;
        sound.muted = false;

        requestNextMutation(() => {
          sound.src = prevSrc;
        });
      });
  }));
}

function initializeSounds() {
  if (sounds) {
    return;
  }
  const joinAudio = new Audio('./voicechat_join.mp3');
  const connectingAudio = new Audio('./voicechat_connecting.mp3');
  connectingAudio.loop = true;
  const leaveAudio = new Audio('./voicechat_leave.mp3');
  const allowTalkAudio = new Audio('./voicechat_onallowtalk.mp3');
  const busyAudio = new Audio('./call_busy.mp3');
  const connectAudio = new Audio('./call_connect.mp3');
  const endAudio = new Audio('./call_end.mp3');
  const incomingAudio = new Audio('./call_incoming.mp3');
  incomingAudio.loop = true;
  const ringingAudio = new Audio('./call_ringing.mp3');
  ringingAudio.loop = true;

  sounds = {
    join: joinAudio,
    allowTalk: allowTalkAudio,
    leave: leaveAudio,
    connecting: connectingAudio,
    incoming: incomingAudio,
    end: endAudio,
    connect: connectAudio,
    busy: busyAudio,
    ringing: ringingAudio,
  };
}

async function fetchGroupCall<T extends GlobalState>(global: T, groupCall: Partial<ApiGroupCall>) {
  if (selectIsCurrentUserFrozen(global)) return undefined;
  const result = await callApi('getGroupCall', {
    call: groupCall,
  });

  if (!result) return undefined;

  global = getGlobal();

  const existingGroupCall = selectGroupCall(global, groupCall.id!);

  global = updateGroupCall(
    global,
    groupCall.id!,
    omit(result.groupCall, ['connectionState']),
    undefined,
    existingGroupCall?.isLoaded ? undefined : result.groupCall.participantsCount,
  );

  setGlobal(global);

  return result.groupCall;
}

