function checkNavigatorUserMediaPermissions<T extends GlobalState>(
  global: T,
  actions: RequiredGlobalActions, isVideo?: boolean,
  ...[tabId = getCurrentTabId()]: TabArgs<T>
) {
  if (isVideo) {
    navigator.mediaDevices.getUserMedia({ video: true })
      .then((stream) => {
        if (stream.getVideoTracks().length === 0) {
          actions.showNotification({
            message: langProvider.oldTranslate('Call.Camera.Error'),
            tabId,
          });
        } else {
          stream.getTracks().forEach((track) => track.stop());
          checkMicrophonePermission(global, actions, tabId);
        }
      })
      .catch(() => {
        actions.showNotification({
          message: langProvider.oldTranslate('Call.Camera.Error'),
          tabId,
        });
      });
  } else {
    checkMicrophonePermission(global, actions, tabId);
  }
}

function checkMicrophonePermission<T extends GlobalState>(
  global: T, actions: RequiredGlobalActions, ...[tabId = getCurrentTabId()]: TabArgs<T>
) {
  navigator.mediaDevices.getUserMedia({ audio: true })
    .then((stream) => {
      if (stream.getAudioTracks().length === 0) {
        actions.showNotification({
          message: langProvider.oldTranslate('RequestAcces.Error.HaveNotAccess.Call'),
          tabId,
        });
      } else {
        stream.getTracks().forEach((track) => track.stop());
      }
    })
    .catch(() => {
      actions.showNotification({
        message: langProvider.oldTranslate('RequestAcces.Error.HaveNotAccess.Call'),
        tabId,
      });
    });
}

function useChatAnimationType<T extends number | string>(
  orderDiffById: Record<T, number>,
  isInitialRender: boolean,
  isShifted?: boolean,
) {
  return useMemo(() => {
    if (isInitialRender) {
      return () => ChatAnimationTypes.None;
    }

    const orderDiffs = Object.values<number>(orderDiffById);
    const numberOfUp = orderDiffs.filter((diff) => diff < 0).length;
    const numberOfDown = orderDiffs.filter((diff) => diff > 0).length;

    return (chatId: T): ChatAnimationTypes => {
      const orderDiff = orderDiffById[chatId];
      if (!orderDiff) {
        if (isShifted) {
          return ChatAnimationTypes.Shift;
        }
        return ChatAnimationTypes.None;
      }

      if (
        orderDiff === Infinity
        || orderDiff === -Infinity
        || (numberOfUp <= numberOfDown && orderDiff < 0)
        || (numberOfDown < numberOfUp && orderDiff > 0)
      ) {
        return ChatAnimationTypes.Opacity;
      }

      return ChatAnimationTypes.Move;
    };
  }, [orderDiffById, isShifted, isInitialRender]);
}

