}

function createCommentBody({ baselineStatsPath, currentStatsPath, reportUrl }: CreateCommentOptions) {
  const currentStats = readStats(currentStatsPath);
  const baselineStats = readStats(baselineStatsPath);

  if (!currentStats) {
    return [
      COMMENT_MARKER,
      '**Bundle stats diff with master**',
      '',
      `Current stats file was not found at \`${currentStatsPath}\`.`,
    ].join('\n');
  }

  const currentAnalysis = analyzeStats(currentStats);

  if (!baselineStats) {
    const entryRows = getCurrentEntryRows(currentAnalysis.entries);
    const bundleRows = getCurrentBundleRows(currentAnalysis.bundles);
    const fileTypeRows = getCurrentFileTypeRows(currentAnalysis.fileTypes);
    const lines = [
      COMMENT_MARKER,
      '**Bundle stats diff with master**',
      '',
      `Master baseline stats were not found at \`${baselineStatsPath}\`.`,
      `Current total bundle size: ${formatSize(currentAnalysis.totalSize)}`,
      '',
      '**📦 File type**',
      ...fileTypeRows.map(renderCurrentSizeLine),
      '',
      '**🚪 Entry point**',
      ...entryRows.map(renderCurrentSizeLine),
      '',
      '**🧩 Bundle**',
      ...bundleRows.map(renderCurrentSizeLine),
    ];
    return lines.join('\n');
  }

  const baselineAnalysis = analyzeStats(baselineStats);
  const entryRows = getEntryRows(baselineAnalysis.entries, currentAnalysis.entries);
  const bundleRows = getBundleRows(baselineAnalysis.bundles, currentAnalysis.bundles);
  const fileTypeRows = getFileTypeRows(baselineAnalysis.fileTypes, currentAnalysis.fileTypes);
  const totalRow = createDiffRow('📊 Total bundle', baselineAnalysis.totalSize, currentAnalysis.totalSize);

  const lines = [
    COMMENT_MARKER,
    '**Bundle stats diff with master**',
    '',
    renderDiffLine(totalRow),
  ];
  addDiffSection(lines, '**📦 File type**', fileTypeRows);
  addDiffSection(lines, '**🚪 Entry point**', entryRows);
  addDiffSection(lines, '**🧩 Bundle**', bundleRows);
  addReportLine(lines, reportUrl);
  return lines.join('\n');
}

function createPendingCommentBody() {
  return [
    COMMENT_MARKER,
    '**Bundle stats diff with master**',
    '',
    [
      '> [!NOTE]',
      '> Bundle size measuring is in progress.',
      '> This comment will be updated with the latest results when the build finishes.',
    ].join('\n'),
  ].join('\n');
}

function readStats(filepath: string): BundleStats | undefined {
  if (!existsSync(filepath)) return undefined;
  return JSON.parse(readFileSync(filepath, 'utf8')) as BundleStats;
}

function analyzeStats(stats: BundleStats) {
  const entries = new Map<string, EntryStats>();
  const bundles = createManualBundleStatsMap();
  const fileTypes = createFileTypeStatsMap();
  const chunkFiles = new Set(stats.chunks?.flatMap(({ files = [] }) => files) || []);
  const initialFiles = new Set(
    stats.chunks
      ?.filter(({ entry, initial }) => entry || initial)
      .flatMap(({ files = [] }) => files) || [],
  );

  let totalSize = ZERO_SIZE;
  let mainSize = ZERO_SIZE;

  stats.assets?.forEach(({ name, size }) => {
    if (isIgnoredAsset(name)) return;

    totalSize += size;
    addFileTypeSize(fileTypes, name, size);
    addManualBundleSize(bundles, name, size);

    const workerEntry = getWorkerEntry(name, chunkFiles);
    if (workerEntry) {
      const previousSize = entries.get(workerEntry.key)?.size || ZERO_SIZE;
      entries.set(workerEntry.key, {
        ...workerEntry,
        size: previousSize + size,
      });
      return;
    }

    if (initialFiles.has(name) || getStableAssetName(name) === 'index.css') {
      mainSize += size;
    }
  });

  entries.set(MAIN_ENTRY_KEY, {
    key: MAIN_ENTRY_KEY,
    label: MAIN_ENTRY_LABEL,
    size: mainSize,
  });

  return { entries, bundles, fileTypes, totalSize };
}

function getEntryRows(baselineEntries: Map<string, EntryStats>, currentEntries: Map<string, EntryStats>) {
  const keys = [...new Set([...baselineEntries.keys(), ...currentEntries.keys()])];

  return keys
    .map((key) => {
      const currentEntry = currentEntries.get(key);
      const baselineEntry = baselineEntries.get(key);
      const label = currentEntry?.label || baselineEntry?.label || key;
      return createDiffRow(label, baselineEntry?.size, currentEntry?.size);
    })
    .sort(compareEntryRows);
}

function getCurrentEntryRows(entries: Map<string, EntryStats>) {
  return [...entries.values()].sort(compareCurrentEntryRows);
}

function getBundleRows(
  baselineBundles: Map<BundleKey, ManualBundleStats>,
  currentBundles: Map<BundleKey, ManualBundleStats>,
) {
  return MANUAL_BUNDLES.map(({ key, label }) => {
    const currentBundle = currentBundles.get(key);
    const baselineBundle = baselineBundles.get(key);
    const bundleLabel = currentBundle?.label || baselineBundle?.label || label;
    return createDiffRow(bundleLabel, baselineBundle?.size, currentBundle?.size);
  });
}

function getCurrentBundleRows(bundles: Map<BundleKey, ManualBundleStats>) {
  return MANUAL_BUNDLES.map(({ key }) => bundles.get(key)!);
}

function getFileTypeRows(
  baselineFileTypes: Map<FileTypeKey, FileTypeStats>,
  currentFileTypes: Map<FileTypeKey, FileTypeStats>,
) {
  return FILE_TYPES.map(({ key, label }) => {
    const currentFileType = currentFileTypes.get(key);
    const baselineFileType = baselineFileTypes.get(key);
    const fileTypeLabel = currentFileType?.label || baselineFileType?.label || label;
    return createDiffRow(fileTypeLabel, baselineFileType?.size, currentFileType?.size);
  });
}

function getCurrentFileTypeRows(fileTypes: Map<FileTypeKey, FileTypeStats>) {
  return FILE_TYPES.map(({ key }) => fileTypes.get(key)!);
}

function createDiffRow(label: string, before = ZERO_SIZE, after = ZERO_SIZE): DiffRow {
  const diff = after - before;
  const percent = before ? (diff / before) * 100 : undefined;
  const status = getDiffStatus(percent, diff);

  return {
    label,
    before,
    after,
    diff,
    percent,
    status,
    diffText: formatDiff(diff),
    percentText: formatPercent(percent, diff),
  };
}

function compareEntryRows(a: DiffRow, b: DiffRow) {
  const aIndex = ENTRY_ORDER.indexOf(getEntryKey(a.label));
  const bIndex = ENTRY_ORDER.indexOf(getEntryKey(b.label));

  if (aIndex !== -1 || bIndex !== -1) {
    return normalizeEntryOrder(aIndex) - normalizeEntryOrder(bIndex);
  }

  return a.label.localeCompare(b.label);
}

function compareCurrentEntryRows(a: EntryStats, b: EntryStats) {
  const aIndex = ENTRY_ORDER.indexOf(a.key);
  const bIndex = ENTRY_ORDER.indexOf(b.key);

  if (aIndex !== -1 || bIndex !== -1) {
    return normalizeEntryOrder(aIndex) - normalizeEntryOrder(bIndex);
  }

  return a.label.localeCompare(b.label);
}

function getEntryKey(label: string) {
  return label
    .replace(/^\S+\s+/, '')
    .toLowerCase()
    .replaceAll(' ', '-');
}

function normalizeEntryOrder(index: number) {
  return index === -1 ? Number.MAX_SAFE_INTEGER : index;
}

function renderDiffLine(row: DiffRow) {
  return `${row.label} (${formatSize(row.after)}): ${row.status} ${row.diffText} (${row.percentText})`;
}

function renderCurrentSizeLine(row: SizeStats) {
  return `${row.label} (${formatSize(row.size)})`;
}

function addDiffSection(lines: string[], title: string, rows: DiffRow[]) {
  const changedRows = rows.filter(isChangedDiffRow);
  if (!changedRows.length) return;

  lines.push('', title, ...changedRows.map(renderDiffLine));
}

function isChangedDiffRow(row: DiffRow) {
  return row.diff !== ZERO_SIZE;
}

function createManualBundleStatsMap(): Map<BundleKey, ManualBundleStats> {
  return new Map(MANUAL_BUNDLES.map((bundle) => [bundle.key, createManualBundleStats(bundle)]));
}

function addManualBundleSize(bundles: Map<BundleKey, ManualBundleStats>, name: string, size: number) {
  const bundleKey = getManualBundleKey(name);
  if (!bundleKey) return;

  const bundle = bundles.get(bundleKey)!;
  bundles.set(bundleKey, {
    ...bundle,
    size: bundle.size + size,
  });
}

function getManualBundleKey(name: string): BundleKey | undefined {
  if (!MANUAL_BUNDLE_ASSET_EXTENSIONS.some((extension) => name.endsWith(extension))) return undefined;

  const stableBaseName = getStableAssetBaseName(name);
  const bundle = MANUAL_BUNDLES.find(({ key }) => key === stableBaseName);
  return bundle?.key;
}

function createManualBundleStats({ key, label }: BundleDefinition): ManualBundleStats {
  return {
    key,
    label,
    size: ZERO_SIZE,
  };
}

function createFileTypeStatsMap(): Map<FileTypeKey, FileTypeStats> {
  return new Map(FILE_TYPES.map((fileType) => [fileType.key, createFileTypeStats(fileType)]));
}

function addFileTypeSize(fileTypes: Map<FileTypeKey, FileTypeStats>, name: string, size: number) {
  const fileType = getFileTypeStats(name);
  const previousSize = fileTypes.get(fileType.key)?.size || ZERO_SIZE;
  fileTypes.set(fileType.key, {
    ...fileType,
    size: previousSize + size,
  });
}

function getFileTypeStats(name: string): FileTypeStats {
  const fileType = FILE_TYPES.find(({ extensions }) => (
    extensions?.some((extension) => name.endsWith(extension))
  )) || OTHER_FILE_TYPE;
  return createFileTypeStats(fileType);
}

function createFileTypeStats({ key, label }: (typeof FILE_TYPES)[number]): FileTypeStats {
  return {
    key,
    label,
    size: ZERO_SIZE,
  };
}

function getWorkerEntry(name: string, chunkFiles: Set<string>) {
  if (/^service\.worker-[\w-]+\.js$/.test(name)) {
    return { key: 'service-worker', label: '🛠️ Service worker' };
  }

  if (chunkFiles.has(name) && !isWorkerAssetName(name)) return undefined;

  if (/^worker-[\w-]+\.js$/.test(name)) {
    return { key: 'gramjs-worker', label: '⚙️ GramJS worker' };
  }

  if (/^fasttext\.worker-[\w-]+\.js$/.test(name)) {
    return { key: 'fasttext-worker', label: '🌐 FastText worker' };
  }

  if (/^index\.worker-[\w-]+\.js$/.test(name)) {
    return { key: 'media-worker', label: '🎞️ Media worker' };
  }

  if (/^sharedState\.worker-[\w-]+\.js$/.test(name)) {
    return { key: 'shared-state-worker', label: '🔄 Shared state worker' };
  }

  return undefined;
}

function isWorkerAssetName(name: string) {
  return /^(?:worker|fasttext\.worker|index\.worker|sharedState\.worker)-[\w-]+\.js$/.test(name);
}

function isIgnoredAsset(name: string) {
  return name.endsWith('.map') || name.startsWith('bundle-stats/');
}

function getStableAssetName(name: string) {
  return name
    .replace(/\.[\w-]{6,}(?=\.[^.]+$)/, '')
    .replace(/-[\w-]{6,}(?=\.[^.]+$)/, '');
}

function getStableAssetBaseName(name: string) {
  return getStableAssetName(name).split('/').pop()!.replace(/\.[^.]+$/, '');
}

function getDiffStatus(percent: number | undefined, diff: number) {
  if (diff < ZERO_SIZE) return DIFF_STATUS_GOOD;
  if (percent === undefined && diff > ZERO_SIZE) return DIFF_STATUS_WARN;
  if (percent !== undefined && percent > REGRESSION_WARNING_PERCENT) return DIFF_STATUS_WARN;
  return DIFF_STATUS_NEUTRAL;
}

function formatSize(size: number) {
  const absoluteSize = Math.abs(size);

  if (absoluteSize >= BYTES_PER_MB) {
    return `${formatNumber(absoluteSize / BYTES_PER_MB)}MB`;
  }

  if (absoluteSize >= BYTES_PER_KB) {
    return `${formatNumber(absoluteSize / BYTES_PER_KB)}KB`;
  }

  return `${absoluteSize}B`;
}

function formatDiff(diff: number) {
  const sign = diff > ZERO_SIZE ? '+' : (diff < ZERO_SIZE ? '-' : '');
  return `${sign}${formatSize(diff)}`;
}

function formatPercent(percent: number | undefined, diff: number) {
  if (percent === undefined) {
    if (diff === ZERO_SIZE) return '0%';
    return 'new';
  }

  const sign = percent > ZERO_SIZE ? '+' : '';
  return `${sign}${formatNumber(percent)}%`;
}

function formatNumber(value: number) {
  return value.toLocaleString('en-US', {
    maximumFractionDigits: 2,
    minimumFractionDigits: 0,
  });
}

function addReportLine(lines: string[], reportUrl: string) {
  if (!reportUrl) return;
  lines.push('', `Detailed comparison report: [open HTML artifact](${reportUrl})`);
}

async function upsertComment({
  github,
  context,
  core,
  body,
}: CreateBundleStatsCommentOptions & { body: string }) {
  const { owner, repo } = context.repo;
  const issueNumber = Number(process.env.PR_NUMBER || context.issue.number);
  if (!issueNumber) {
    throw new Error('Cannot create bundle stats comment without a PR number');
  }

  const { data: comments } = await github.rest.issues.listComments({
    owner,
    repo,
    issue_number: issueNumber,
    per_page: 100,
  });
  const previousComment = comments.find(({ body: commentBody = '' }) => commentBody.includes(COMMENT_MARKER));

  if (previousComment) {
    await github.rest.issues.updateComment({
      owner,
      repo,
      comment_id: previousComment.id,
      body,
    });
    core.info(`Updated bundle stats comment ${previousComment.id}.`);
    return;
  }

  const { data: comment } = await github.rest.issues.createComment({
    owner,
    repo,
    issue_number: issueNumber,
    body,
  });
  core.info(`Created bundle stats comment ${comment.id}.`);
}

function useSignalEffect(effect: NoneToVoidFunction, dependencies: readonly any[]) {
  // This runs before all effects
  const prevDepsRef = useRef<readonly unknown[]>();
  const subscribedEffectRef = useRef<NoneToVoidFunction>();

  const prevDeps = prevDepsRef.current;
  const hasChanged = !prevDeps
    || dependencies.length !== prevDeps.length
    || dependencies.some((dep, i) => dep !== prevDeps[i]);

  if (hasChanged) {
    if (subscribedEffectRef.current) {
      cleanupEffect(subscribedEffectRef.current);
    }

    subscribedEffectRef.current = effect;
    prevDepsRef.current = dependencies;

    dependencies.forEach((dependency) => {
      if (isSignal(dependency)) {
        dependency.subscribe(effect);
      }
    });

    const currentEffect = effect;
    requestMeasure(() => {
      if (subscribedEffectRef.current !== currentEffect) return;
      currentEffect();
    });
  }

  useUnmountCleanup(() => {
    if (subscribedEffectRef.current) {
      cleanupEffect(subscribedEffectRef.current);
    }
  });
}

function updatePasscodeSettings<T extends GlobalState>(
  global: T,
  update: GlobalState['passcode'],
): T {
  return {
    ...global,
    passcode: {
      ...global.passcode,
      ...update,
    },
  };
}

function clearPasscodeSettings<T extends GlobalState>(global: T): T {
  return {
    ...global,
    passcode: {},
  };
}

function clearGlobalForLockScreen<T extends GlobalState>(global: T, withTabState = true): T {
  return {
    ...INITIAL_GLOBAL_STATE,
    passcode: global.passcode,
    settings: INITIAL_GLOBAL_STATE.settings,
    sharedState: clearSharedStateForLockScreen(global.sharedState),
    ...(withTabState && {
      byTabId: Object.values(global.byTabId).reduce((acc, { id: tabId, isMasterTab }) => {
        acc[tabId] = { ...INITIAL_TAB_STATE, isMasterTab, id: tabId };
        return acc;
      }, {} as Record<number, TabState>),
    }),
  } as T;
}

function clearSharedStateForLockScreen(sharedState: SharedState): SharedState {
  const {
    theme,
    themes,
    shouldUseSystemTheme,
    animationLevel,
    language,
  } = sharedState.settings;

  return {
    ...INITIAL_SHARED_STATE,
    settings: {
      ...INITIAL_SHARED_STATE.settings,
      theme,
      themes,
      shouldUseSystemTheme,
      animationLevel,
      language,
    },
  };
}

function usePinnedMessage(
  chatId?: string, threadId?: ThreadId, pinnedIds?: number[],
) {
  const [getPinnedIndexByKey, setPinnedIndexByKey] = useSignal<Record<string, number>>({});
  const [getLoadingPinnedId, setLoadingPinnedId] = useSignal<number | undefined>();
  const key = chatId ? `${chatId}_${threadId}` : undefined;
  const getCurrentPinnedIndex = useDerivedSignal(
    () => (getPinnedIndexByKey()[key!] ?? 0),
    [getPinnedIndexByKey, key],
  );

  // Reset when switching chat
  useEffect(() => {
    setLoadingPinnedId(undefined);
  }, [
    chatId, threadId, setPinnedIndexByKey, setLoadingPinnedId,
  ]);

  useEffect(() => {
    if (!key) return;
    const currentPinnedIndex = getPinnedIndexByKey()[key];
    const pinnedLength = pinnedIds?.length || 0;
    if (currentPinnedIndex >= pinnedLength) {
      setPinnedIndexByKey({
        ...getPinnedIndexByKey(),
        [key]: clampIndex(pinnedLength - 1),
      });
    }
  }, [getPinnedIndexByKey, key, pinnedIds?.length, setPinnedIndexByKey]);

  const handleIntersectPinnedMessage: OnIntersectPinnedMessage = useLastCallback(({
    firstViewportId,
    shouldCancelWaiting,
  }) => {
    if (!chatId || !threadId || !key || !pinnedIds?.length) return;

    if (shouldCancelWaiting) {
      setLoadingPinnedId(undefined);
      return;
    }

    const loadingPinnedId = getLoadingPinnedId();
    if (loadingPinnedId) {
      const newPinnedIndex = pinnedIds.indexOf(loadingPinnedId);
      setPinnedIndexByKey({
        ...getPinnedIndexByKey(),
        [key]: clampIndex(newPinnedIndex),
      });
      setLoadingPinnedId(undefined);

      // We're still scrolling, prevent updating the index
      if (loadingPinnedId < (firstViewportId || 0)) {
        return;
      }
    }

    let newIndex = pinnedIds.findIndex((id) => id < (firstViewportId || 0));
    if (newIndex === -1) {
      newIndex = 0; // Pinned are sorted from newest to oldest
    }

    setPinnedIndexByKey({
      ...getPinnedIndexByKey(),
      [key]: clampIndex(newIndex),
    });
  });

  const handleFocusPinnedMessage = useLastCallback((messageId: number) => {
    // Focusing on a post in comments
    if (!chatId || !threadId || !pinnedIds?.length) {
      return;
    }

    const global = getGlobal();
    const listedIds = selectListedIds(global, chatId, threadId);
    const isMessageLoaded = listedIds?.includes(messageId)
      || selectOutlyingListByMessageId(global, chatId, threadId, messageId);

    const currentIndex = pinnedIds.indexOf(messageId);
    const newIndex = cycleRestrict(pinnedIds.length, currentIndex + 1);

    if (isMessageLoaded) {
      setPinnedIndexByKey({
        ...getPinnedIndexByKey(),
        [key!]: newIndex,
      });
    } else {
      setLoadingPinnedId(pinnedIds[newIndex]);
    }
  });

  return {
    handleIntersectPinnedMessage,
    handleFocusPinnedMessage,
    getCurrentPinnedIndex,
    getLoadingPinnedId,
  };
}

function clampIndex(id: number) {
  return Math.max(0, id);
}

interface MoveOffsets {
  dragOffsetX: number;
  dragOffsetY: number;
}

interface CaptureOptions {
  onCapture?: (e: MouseEvent | TouchEvent | WheelEvent) => void;
  onRelease?: (e: MouseEvent | TouchEvent | WheelEvent) => void;
  onDrag?: (
    e: MouseEvent | TouchEvent | WheelEvent,
    captureEvent: MouseEvent | TouchEvent | WheelEvent,
    offsets: MoveOffsets,
    cancelDrag?: (x: boolean, y: boolean) => void,
  ) => void;
  onSwipe?: (e: Event, direction: SwipeDirection, offsets: MoveOffsets) => boolean;
  onZoom?: (e: TouchEvent | WheelEvent, params: {
    // Absolute zoom level
    zoom?: number;
    // Relative zoom factor
    zoomFactor?: number;

    // center coordinate of the initial pinch
    initialCenterX: number;
    initialCenterY: number;

    // offset of the pinch center (current from initial)
    dragOffsetX: number;
    dragOffsetY: number;

    // center coordinate of the current pinch
    currentCenterX: number;
    currentCenterY: number;
  }) => void;
  onClick?: (e: MouseEvent | TouchEvent) => void;
  onDoubleClick?: (e: MouseEvent | RealTouchEvent | WheelEvent, params: { centerX: number; centerY: number }) => void;
  excludedClosestSelector?: string;
  includedClosestSelector?: string;
  selectorToPreventScroll?: string;
  withNativeDrag?: boolean;
  maxZoom?: number;
  minZoom?: number;
  doubleTapZoom?: number;
  initialZoom?: number;
  isNotPassive?: boolean;
  withCursor?: boolean;
  swipeThreshold?: number;
  withWheelDrag?: boolean;
}

interface RealTouchEvent extends TouchEvent {
  pageX?: number;
  pageY?: number;
}

function getDistance(a: Touch, b?: Touch) {
  if (!b) return 0;
  return Math.hypot((b.pageX - a.pageX), (b.pageY - a.pageY));
}

function getTouchCenter(a: Touch, b: Touch) {
  return {
    x: (a.pageX + b.pageX) / 2,
    y: (a.pageY + b.pageY) / 2,
  };
}

function captureEvents(element: HTMLElement, options: CaptureOptions) {
  let captureEvent: MouseEvent | RealTouchEvent | WheelEvent | undefined;
  let hasMoved = false;
  let hasSwiped = false;
  let isZooming = false;
  let initialDistance = 0;
  let wheelZoom = options.initialZoom ?? 1;
  let initialDragOffset = {
    x: 0,
    y: 0,
  };
  let isDragCanceled = {
    x: false,
    y: false,
  };
  const currentWindowSize = windowSize.get();
  let initialTouchCenter = {
    x: currentWindowSize.width / 2,
    y: currentWindowSize.height / 2,
  };
  let initialSwipeAxis: TSwipeAxis | undefined;
  const minZoom = options.minZoom ?? 1;
  const maxZoom = options.maxZoom ?? 4;

  let isNearEdge = false;

  function onCapture(e: MouseEvent | RealTouchEvent) {
    const target = e.target as HTMLElement;
    const {
      excludedClosestSelector,
      includedClosestSelector,
      withNativeDrag,
      withCursor,
      onDrag,
    } = options;

    if (element !== target && !element.contains(target)) {
      return;
    }

    if (target.tagName === 'INPUT' || target.tagName === 'TEXTAREA') {
      return;
    }

    if (
      (excludedClosestSelector && (target.matches(excludedClosestSelector) || target.closest(excludedClosestSelector)))
      || (
        includedClosestSelector && !(target.matches(includedClosestSelector) || target.closest(includedClosestSelector))
      )
    ) {
      return;
    }

    captureEvent = e;

    if (e.type === 'mousedown') {
      if (!withNativeDrag && onDrag) {
        e.preventDefault();
      }

      document.addEventListener('mousemove', onMove);
      document.addEventListener('mouseup', onRelease);
    } else if (e.type === 'touchstart') {
      if (IS_IOS) {
        const x = (e as RealTouchEvent).touches[0].pageX;
        isNearEdge = x <= IOS_SCREEN_EDGE_THRESHOLD || x >= windowSize.get().width - IOS_SCREEN_EDGE_THRESHOLD;
      }

      // We need to always listen on `touchstart` target:
      // https://stackoverflow.com/questions/33298828/touch-move-event-dont-fire-after-touch-start-target-is-removed
      target.addEventListener('touchmove', onMove, { passive: true });
      target.addEventListener('touchend', onRelease, { passive: true });
      target.addEventListener('touchcancel', onRelease, { passive: true });

      if ('touches' in e) {
        if (e.pageX === undefined) {
          e.pageX = e.touches[0].pageX;
        }

        if (e.pageY === undefined) {
          e.pageY = e.touches[0].pageY;
        }

        if (e.touches.length === 2) {
          initialDistance = getDistance(e.touches[0], e.touches[1]);
          initialTouchCenter = getTouchCenter(e.touches[0], e.touches[1]);
        }
      }
    }

    if (withCursor) {
      document.body.classList.add('cursor-grabbing');
    }

    options.onCapture?.(e);
  }

  function onRelease(e?: MouseEvent | TouchEvent) {
    if (captureEvent) {
      if (options.withCursor) {
        document.body.classList.remove('cursor-grabbing');
      }

      document.removeEventListener('mouseup', onRelease);
      document.removeEventListener('mousemove', onMove);
      (captureEvent.target as HTMLElement).removeEventListener('touchcancel', onRelease);
      (captureEvent.target as HTMLElement).removeEventListener('touchend', onRelease);
      (captureEvent.target as HTMLElement).removeEventListener('touchmove', onMove);

      if (IS_IOS && options.selectorToPreventScroll) {
        Array.from(document.querySelectorAll<HTMLElement>(options.selectorToPreventScroll))
          .forEach((scrollable) => {
            scrollable.style.overflow = '';
          });
      }

      if (e) {
        if (hasMoved) {
          if (options.onRelease) {
            options.onRelease(e);
          }
        } else if (e.type === 'mouseup') {
          if (options.onDoubleClick && Date.now() - lastClickTime < 300) {
            options.onDoubleClick(e, {
              centerX: captureEvent.pageX!,
              centerY: captureEvent.pageY!,
            });
          } else if (options.onClick && (!('button' in e) || e.button === 0)) {
            options.onClick(e);
          }
          lastClickTime = Date.now();
        }
      }
    }

    hasMoved = false;
    hasSwiped = false;
    isZooming = false;
    initialDistance = 0;
    wheelZoom = clamp(wheelZoom, minZoom, maxZoom);
    initialSwipeAxis = undefined;
    initialDragOffset = {
      x: 0,
      y: 0,
    };
    isDragCanceled = {
      x: false,
      y: false,
    };
    const newWindowSize = windowSize.get();
    initialTouchCenter = {
      x: newWindowSize.width / 2,
      y: newWindowSize.height / 2,
    };
    captureEvent = undefined;
    isNearEdge = false;
  }

  function onMove(e: MouseEvent | RealTouchEvent) {
    if (captureEvent) {
      if (e.type === 'touchmove' && ('touches' in e)) {
        if (e.pageX === undefined) {
          e.pageX = e.touches[0].pageX;
        }

        if (e.pageY === undefined) {
          e.pageY = e.touches[0].pageY;
        }

        if (options.onZoom && initialDistance > 0 && e.touches.length === 2) {
          const endDistance = getDistance(e.touches[0], e.touches[1]);
          const touchCenter = getTouchCenter(e.touches[0], e.touches[1]);
          const dragOffsetX = touchCenter.x - initialTouchCenter.x;
          const dragOffsetY = touchCenter.y - initialTouchCenter.y;
          const zoomFactor = endDistance / initialDistance;
          options.onZoom(e, {
            zoomFactor,
            initialCenterX: initialTouchCenter.x,
            initialCenterY: initialTouchCenter.y,
            dragOffsetX,
            dragOffsetY,
            currentCenterX: touchCenter.x,
            currentCenterY: touchCenter.y,
          });
          if (zoomFactor !== 1) hasMoved = true;
        }
      }

