function createTestApiSlice({
  activeMessageList,
  chatIds = ['10'],
}: {
  activeMessageList?: MessageList;
  chatIds?: string[];
} = {}) {
  const actionCalls: ActionCall[] = [];
  const capturedErrors: CapturedError[] = [];

  const record = (name: keyof TgPluginActions) => (payload: unknown) => {
    actionCalls.push({ name, payload });
  };

  const actions: TgPluginActions = {
    deleteMessages: record('deleteMessages'),
    editMessage: record('editMessage'),
    openChat: record('openChat'),
    sendMessage: record('sendMessage'),
    setEditingId: record('setEditingId'),
    toggleReaction: record('toggleReaction'),
  };

  const runtime: TgPluginRuntime = {
    isPluginEnabled: () => true,
    setPluginEnabled: () => {},
    createPluginReporter: (pluginName) => ({
      log: () => {},
      logError: (action, error) => capturedErrors.push({ action, error }),
      wrap: (callback) => callback,
    }),
    // Event streams are not exercised by the facade slices
    subscribeApiUpdates: () => () => {},
    subscribeToStoreChanges: () => {},
    getActions: () => actions,
    getCurrentTabId: () => TEST_TAB_ID,
    mainThreadId: TEST_MAIN_THREAD_ID,
    getActiveMessageList: () => activeMessageList,
    getActiveChatId: () => activeMessageList?.chatId,
    getCurrentUserId: () => '100',
    getChat: (chatId) => (chatIds.includes(chatId) ? ({ id: chatId } as ApiChat) : undefined),
    getLocalizedString: (key) => `translated:${key}`,
    showNotification: () => {
      throw new Error('the api slice never shows notifications');
    },
  };

  const context = createPluginContext(TEST_PLUGIN_NAME, runtime.createPluginReporter(TEST_PLUGIN_NAME));

  return {
    actions,
    api: createApiSlice(context, runtime),
    actionCalls,
    capturedErrors,
  };
}

function getRepeatPeriodSeconds(mode?: RepeatedMessageMode) {
  if (!mode || mode === 'never') return undefined;

  return MODE_TO_SECONDS[mode];
}

function getRepeatModeFromSeconds(seconds?: number) {
  if (!seconds) return undefined;

  return (Object.keys(MODE_TO_SECONDS) as ActualRepeatedMessageMode[])
    .find((mode) => MODE_TO_SECONDS[mode] === seconds);
}

function getRepeatPeriodText(seconds: number | undefined, lang: LangFn) {
  if (!seconds) return undefined;

  const mode = getRepeatModeFromSeconds(seconds);
  if (!mode) return undefined;

  switch (mode) {
    case 'everyminute':
      return lang('MessageRepeatPeriodEveryMinutes', { count: 1 }, { pluralValue: 1 });
    case 'every5minutes':
      return lang('MessageRepeatPeriodEveryMinutes', { count: 5 }, { pluralValue: 5 });
    case 'daily':
      return lang('MessageRepeatPeriodDaily');
    case 'weekly':
      return lang('MessageRepeatPeriodWeekly');
    case 'biweekly':
      return lang('MessageRepeatPeriodBiweekly');
    case 'monthly':
      return lang('MessageRepeatPeriodMonthly');
    case 'every3months':
      return lang('MessageRepeatPeriodEveryMonths', { count: 3 }, { pluralValue: 3 });
    case 'every6months':
      return lang('MessageRepeatPeriodEveryMonths', { count: 6 }, { pluralValue: 6 });
    case 'yearly':
      return lang('MessageRepeatPeriodYearly');
    default:
      return undefined;
  }
}

function getScheduleRepeatModeText(mode: RepeatedMessageMode, lang: LangFn) {
  switch (mode) {
    case 'never':
      return lang('ScheduleRepeatNever');
    case 'everyminute':
      return lang('ScheduleRepeatEveryMinutes', { count: 1 }, { pluralValue: 1 });
    case 'every5minutes':
      return lang('ScheduleRepeatEveryMinutes', { count: 5 }, { pluralValue: 5 });
    case 'daily':
      return lang('ScheduleRepeatDaily');
    case 'weekly':
      return lang('ScheduleRepeatWeekly');
    case 'biweekly':
      return lang('ScheduleRepeatBiweekly');
    case 'monthly':
      return lang('ScheduleRepeatMonthly');
    case 'every3months':
      return lang('ScheduleRepeatEveryMonths', { count: 3 }, { pluralValue: 3 });
    case 'every6months':
      return lang('ScheduleRepeatEveryMonths', { count: 6 }, { pluralValue: 6 });
    case 'yearly':
      return lang('ScheduleRepeatYearly');
    default:
      return lang('ScheduleRepeatNever');
  }
}

