function selectChatFilters(state: FoldersState, mode: 'included' | 'excluded', selectTemp?: boolean) {
  let selectedChatIds: string[];
  let selectedChatTypes: FolderChatType['key'][];

  if (mode === 'included') {
    const {
      includedChatIds,
      ...includeFilters
    } = selectTemp
      ? state.includeFilters || {}
      : pick(
        state.folder,
        INCLUDE_FILTER_FIELDS,
      );

    selectedChatIds = includedChatIds || [];
    selectedChatTypes = (Object.keys(includeFilters) as Array<keyof typeof includeFilters>)
      .filter((key) => Boolean(includeFilters[key]));
  } else {
    const {
      excludedChatIds,
      ...excludeFilters
    } = selectTemp
      ? state.excludeFilters || {}
      : pick(
        state.folder,
        EXCLUDE_FILTER_FIELDS,
      );

    selectedChatIds = excludedChatIds || [];
    selectedChatTypes = (Object.keys(excludeFilters) as Array<keyof typeof excludeFilters>)
      .filter((key) => Boolean(excludeFilters[key]));
  }

  const global = getGlobal();
  const existingSelectedChatIds = selectedChatIds.filter((id) => selectChat(global, id));

  return {
    selectedChatIds: existingSelectedChatIds,
    selectedChatTypes,
  };
}

function getSuggestedFolderName(includeFilters?: FolderIncludeFilters) {
  if (includeFilters) {
    const {
      includedChatIds,
      ...filters
    } = includeFilters;

    if (
      Object.values(filters).filter(Boolean).length > 1
      || (includedChatIds?.length)
    ) {
      return '';
    }

    if (filters.bots) {
      return 'Bots';
    } else if (filters.groups) {
      return 'Groups';
    } else if (filters.channels) {
      return 'Channels';
    } else if (filters.contacts) {
      return 'Contacts';
    } else if (filters.nonContacts) {
      return 'Non-Contacts';
    }
  }

  return '';
}

function getClosestEntry(arr: number[], value: number): number {
  return arr.reduce((prev, curr) => {
    return Math.abs(curr - value) < Math.abs(prev - value) ? curr : prev;
  });
}

function useBlur(dataUri?: string, isDisabled = false, delay?: number) {
  const blurredRef = useRef<string | undefined>(dataUri ? cache.get(dataUri) : undefined);
  const timeoutRef = useRef<number>();
  const forceUpdate = useForceUpdate();

  if (timeoutRef.current && isDisabled) {
    // eslint-disable-next-line @eslint-react/purity
    clearTimeout(timeoutRef.current);
    timeoutRef.current = undefined;
  }

  useEffect(() => {
    if (!dataUri || blurredRef.current || isDisabled) {
      return;
    }

    const img = new Image();

    img.onload = () => {
      const canvas = imgToCanvas(img);
      fastBlur(canvas.getContext('2d'), 0, 0, canvas.width, canvas.height, RADIUS, ITERATIONS);
      const blurredDataUri = canvas.toDataURL();

      blurredRef.current = blurredDataUri;
      forceUpdate();

      if (cache.size >= MAX_CACHE_SIZE) {
        cache.clear();
      }
      cache.set(dataUri, blurredDataUri);
    };

    if (delay) {
      timeoutRef.current = window.setTimeout(() => {
        img.src = dataUri;
      }, delay);
    } else {
      img.src = dataUri;
    }
  }, [dataUri, delay, forceUpdate, isDisabled]);

  return blurredRef.current;
}

