function hasFormattedDateFormat(options: FormattedDateEntityOptions) {
  return Object.values(options).some(Boolean);
}

function getFormattedDateFormatString(options: FormattedDateEntityOptions) {
  return [
    options.relative && 'r',
    options.dayOfWeek && 'w',
    options.shortDate && 'd',
    options.longDate && 'D',
    options.shortTime && 't',
    options.longTime && 'T',
  ].filter(Boolean).join('');
}

