class TeactNodeView extends NodeView<TeactNodeViewComponent, Editor, TeactNodeViewOptions> {
  public mount() {
    const element = document.createElement(this.options.as);
    if (this.options.className) {
      element.className = this.options.className;
    }

    if (!this.node.isLeaf && !this.node.isAtom) {
      const contentDOMElement = document.createElement(this.options.contentDOMElementTag);
      contentDOMElement.dataset.nodeViewContent = '';
      if (this.options.contentDOMClassName) {
        contentDOMElement.className = this.options.contentDOMClassName;
      }
      contentDOMElements.set(this, contentDOMElement);
    }

    selectedStates.set(this, this.isSelected());
    renderers.set(this, new TeactRenderer(TeactNodeViewRoot, {
      element,
      props: this.buildRootProps(),
    }));

    const handleSelectionUpdate = () => {
      this.updateSelection();
    };
    selectionUpdateHandlers.set(this, handleSelectionUpdate);
    this.editor.on('selectionUpdate', handleSelectionUpdate);

    const { shouldUpdateOnTransaction, trackNodeViewPosition } = this.options;
    if (trackNodeViewPosition || shouldUpdateOnTransaction) {
      const handleTransaction = (event: EditorEvents['transaction']) => {
        if (trackNodeViewPosition || shouldUpdateOnTransaction?.(event)) {
          this.updateRenderer();
        }
      };
      transactionHandlers.set(this, handleTransaction);
      this.editor.on('transaction', handleTransaction);
    }
  }

  public get dom(): HTMLElement {
    return renderers.get(this)!.element;
  }

  public get contentDOM(): NodeView<TeactNodeViewComponent, Editor, TeactNodeViewOptions>['contentDOM'] {
    return contentDOMElements.get(this) || super.contentDOM;
  }

  public update(
    node: ProseMirrorNode,
    decorations: readonly Decoration[],
    innerDecorations: DecorationSource,
  ) {
    if (node.type !== this.node.type) {
      return false;
    }

    this.node = node;
    this.decorations = decorations;
    this.innerDecorations = innerDecorations;
    const isSelectionUpdated = this.updateSelection(true);
    if (!isSelectionUpdated) {
      this.updateRenderer();
    }

    return true;
  }

  public selectNode() {
    this.setIsSelected(true);
  }

  public deselectNode() {
    this.setIsSelected(false);
  }

  public destroy() {
    const handleSelectionUpdate = selectionUpdateHandlers.get(this);
    if (handleSelectionUpdate) {
      this.editor.off('selectionUpdate', handleSelectionUpdate);
    }
    selectionUpdateHandlers.delete(this);

    const handleTransaction = transactionHandlers.get(this);
    if (handleTransaction) {
      this.editor.off('transaction', handleTransaction);
      transactionHandlers.delete(this);
    }

    renderers.get(this)?.destroy();
    renderers.delete(this);
    contentDOMElements.delete(this);
    selectedStates.delete(this);
  }

  private buildRootProps(): TeactNodeViewRootProps {
    const contentDOMElement = contentDOMElements.get(this);

    return {
      Component: this.component,
      componentProps: {
        editor: this.editor,
        node: this.node,
        decorations: this.decorations as NodeViewProps['decorations'],
        innerDecorations: this.innerDecorations,
        view: this.view,
        getPos: this.getPos,
        extension: this.extension,
        HTMLAttributes: this.HTMLAttributes,
        selected: selectedStates.get(this) || false,
        updateAttributes: this.updateAttributes.bind(this),
        deleteNode: this.deleteNode.bind(this),
        contentDOMElement,
      },
      contentDOMElement,
    };
  }

  private updateRenderer() {
    requestMutation(() => {
      renderers.get(this)?.updateProps(this.buildRootProps());
    });
  }

  private updateSelection(force?: boolean) {
    const isSelected = this.isSelected();
    if (!force && selectedStates.get(this) === isSelected) {
      return false;
    }

    return this.setIsSelected(isSelected);
  }

  private setIsSelected(isSelected: boolean) {
    if (selectedStates.get(this) === isSelected) {
      return false;
    }

    selectedStates.set(this, isSelected);
    this.updateRenderer();
    return true;
  }

  private isSelected() {
    const pos = this.getPos();
    if (typeof pos !== 'number') {
      return false;
    }

    return isNodeViewSelected({
      selection: this.editor.state.selection,
      pos,
      nodeSize: this.node.nodeSize,
      selectedOnTextSelection: this.options.selectedOnTextSelection,
    });
  }
}

public mount() {
    const element = document.createElement(this.options.as);
    if (this.options.className) {
      element.className = this.options.className;
    }

    if (!this.node.isLeaf && !this.node.isAtom) {
      const contentDOMElement = document.createElement(this.options.contentDOMElementTag);
      contentDOMElement.dataset.nodeViewContent = '';
      if (this.options.contentDOMClassName) {
        contentDOMElement.className = this.options.contentDOMClassName;
      }
      contentDOMElements.set(this, contentDOMElement);
    }

    selectedStates.set(this, this.isSelected());
    renderers.set(this, new TeactRenderer(TeactNodeViewRoot, {
      element,
      props: this.buildRootProps(),
    }));

    const handleSelectionUpdate = () => {
      this.updateSelection();
    };
    selectionUpdateHandlers.set(this, handleSelectionUpdate);
    this.editor.on('selectionUpdate', handleSelectionUpdate);

    const { shouldUpdateOnTransaction, trackNodeViewPosition } = this.options;
    if (trackNodeViewPosition || shouldUpdateOnTransaction) {
      const handleTransaction = (event: EditorEvents['transaction']) => {
        if (trackNodeViewPosition || shouldUpdateOnTransaction?.(event)) {
          this.updateRenderer();
        }
      };
      transactionHandlers.set(this, handleTransaction);
      this.editor.on('transaction', handleTransaction);
    }
  }

public get dom(): HTMLElement {
    return renderers.get(this)!.element;
  }

public get contentDOM(): NodeView<TeactNodeViewComponent, Editor, TeactNodeViewOptions>['contentDOM'] {
    return contentDOMElements.get(this) || super.contentDOM;
  }

public update(
    node: ProseMirrorNode,
    decorations: readonly Decoration[],
    innerDecorations: DecorationSource,
  ) {
    if (node.type !== this.node.type) {
      return false;
    }

    this.node = node;
    this.decorations = decorations;
    this.innerDecorations = innerDecorations;
    const isSelectionUpdated = this.updateSelection(true);
    if (!isSelectionUpdated) {
      this.updateRenderer();
    }

    return true;
  }

public selectNode() {
    this.setIsSelected(true);
  }

public deselectNode() {
    this.setIsSelected(false);
  }

public destroy() {
    const handleSelectionUpdate = selectionUpdateHandlers.get(this);
    if (handleSelectionUpdate) {
      this.editor.off('selectionUpdate', handleSelectionUpdate);
    }
    selectionUpdateHandlers.delete(this);

    const handleTransaction = transactionHandlers.get(this);
    if (handleTransaction) {
      this.editor.off('transaction', handleTransaction);
      transactionHandlers.delete(this);
    }

    renderers.get(this)?.destroy();
    renderers.delete(this);
    contentDOMElements.delete(this);
    selectedStates.delete(this);
  }

private buildRootProps(): TeactNodeViewRootProps {
    const contentDOMElement = contentDOMElements.get(this);

    return {
      Component: this.component,
      componentProps: {
        editor: this.editor,
        node: this.node,
        decorations: this.decorations as NodeViewProps['decorations'],
        innerDecorations: this.innerDecorations,
        view: this.view,
        getPos: this.getPos,
        extension: this.extension,
        HTMLAttributes: this.HTMLAttributes,
        selected: selectedStates.get(this) || false,
        updateAttributes: this.updateAttributes.bind(this),
        deleteNode: this.deleteNode.bind(this),
        contentDOMElement,
      },
      contentDOMElement,
    };
  }

private updateRenderer() {
    requestMutation(() => {
      renderers.get(this)?.updateProps(this.buildRootProps());
    });
  }

private updateSelection(force?: boolean) {
    const isSelected = this.isSelected();
    if (!force && selectedStates.get(this) === isSelected) {
      return false;
    }

    return this.setIsSelected(isSelected);
  }

private setIsSelected(isSelected: boolean) {
    if (selectedStates.get(this) === isSelected) {
      return false;
    }

    selectedStates.set(this, isSelected);
    this.updateRenderer();
    return true;
  }

private isSelected() {
    const pos = this.getPos();
    if (typeof pos !== 'number') {
      return false;
    }

    return isNodeViewSelected({
      selection: this.editor.state.selection,
      pos,
      nodeSize: this.node.nodeSize,
      selectedOnTextSelection: this.options.selectedOnTextSelection,
    });
  }

function TeactNodeViewRenderer(
  Component: TeactNodeViewComponent,
  options: TeactNodeViewRendererOptions = {},
): NodeViewRenderer {
  const resolvedOptions = buildResolvedOptions(options);

  return (props: NodeViewRendererProps) => {
    return new TeactNodeView(Component, props, resolvedOptions);
  };
}

function buildResolvedOptions(options: TeactNodeViewRendererOptions): Partial<TeactNodeViewOptions> {
  const resolvedOptions: Partial<TeactNodeViewOptions> = {
    as: options.as || DEFAULT_NODE_VIEW_ELEMENT_TAG,
    className: options.className,
    contentDOMElementTag: options.contentDOMElementTag || DEFAULT_CONTENT_DOM_ELEMENT_TAG,
    contentDOMClassName: options.contentDOMClassName,
    selectedOnTextSelection: options.selectedOnTextSelection,
    shouldUpdateOnTransaction: options.shouldUpdateOnTransaction,
    trackNodeViewPosition: options.trackNodeViewPosition,
  };

  if (options.stopEvent !== undefined) {
    resolvedOptions.stopEvent = options.stopEvent;
  }

  if (options.ignoreMutation !== undefined) {
    resolvedOptions.ignoreMutation = options.ignoreMutation;
  }

  return resolvedOptions;
}

function useInnerHandlers({
  lang,
  selectMessage,
  message,
  webPage,
  chatId,
  threadId,
  isInDocumentGroup,
  asForwarded,
  isScheduled,
  album,
  senderPeer,
  botSender,
  guestFromSender,
  messageTopic,
  isTranslatingChat,
  story,
  isReplyPrivate,
  isRepliesChat,
  isSavedMessages,
  lastPlaybackTimestamp,
}: {
  lang: OldLangFn;
  selectMessage: (e: React.MouseEvent<HTMLDivElement, MouseEvent>, groupedId?: string) => void;
  message: ApiMessage;
  webPage?: ApiWebPage;
  chatId: string;
  threadId: ThreadId;
  isInDocumentGroup: boolean;
  asForwarded?: boolean;
  isScheduled?: boolean;
  album?: IAlbum;
  avatarPeer?: ApiPeer;
  senderPeer?: ApiPeer;
  botSender?: ApiPeer;
  guestFromSender?: ApiPeer;
  messageTopic?: ApiTopic;
  isTranslatingChat?: boolean;
  story?: ApiStory;
  isReplyPrivate?: boolean;
  isRepliesChat?: boolean;
  isSavedMessages?: boolean;
  lastPlaybackTimestamp?: number;
}) {
  const {
    openChat, openChatWithDraft, showNotification, focusMessage, openMediaViewer, openAudioPlayer,
    markMessagesRead, cancelUploadMedia, openForwardMenu,
    openChatLanguageModal, openThread, openStoryViewer, searchChatMediaMessages,
  } = getActions();

  const {
    id: messageId, forwardInfo, groupedId, content: { paidMedia, video },
  } = message;

  const {
    replyToMsgId, replyToPeerId, replyToTopId, isQuote, quoteText, quoteOffset,
  } = getMessageReplyInfo(message) || {};

  const handleSenderClick = useLastCallback(() => {
    if (!senderPeer) {
      showNotification({ message: lang('HidAccount') });

      return;
    }

    if (asForwarded && forwardInfo?.channelPostId) {
      focusMessage({ chatId: senderPeer.id, messageId: forwardInfo.channelPostId });
    } else {
      openChat({ id: senderPeer.id });
    }
  });

  const handleViaBotClick = useLastCallback(() => {
    const username = botSender && getMainUsername(botSender);
    if (!username) {
      return;
    }

    openChatWithDraft({
      chatId,
      threadId,
      text: {
        text: `@${username} `,
      },
    });
  });

  const handleGuestForClick = useLastCallback(() => {
    if (!guestFromSender) {
      return;
    }

    openChat({ id: guestFromSender.id });
  });

  const handleReplyClick = useLastCallback((): void => {
    if (!replyToMsgId || isReplyPrivate) {
      showNotification({
        message: isQuote ? lang('QuotePrivate') : lang('ReplyPrivate'),
      });
      return;
    }

    if (isRepliesChat && replyToPeerId && replyToTopId) {
      openThread({
        isComments: true,
        originChannelId: replyToPeerId,
        originMessageId: replyToTopId,
        focusMessageId: replyToMsgId,
      });
      return;
    }

    focusMessage({
      chatId: replyToPeerId || chatId,
      threadId: isRepliesChat ? replyToTopId : threadId, // Open comments from Replies bot, otherwise, keep current thread
      messageId: replyToMsgId,
      replyMessageId: replyToPeerId ? undefined : messageId,
      noForumTopicPanel: !replyToPeerId, // Open topic panel for cross-chat replies
      ...(isQuote && { quote: quoteText?.text, quoteOffset }),
    });
  });

  const handleDocumentClick = useLastCallback((): void => {
    openMediaViewer({
      chatId,
      threadId,
      messageId,
      origin: message.isEphemeral
        ? MediaViewerOrigin.Ephemeral
        : isScheduled ? MediaViewerOrigin.ScheduledInline : MediaViewerOrigin.Inline,
    });
  });

  const openMediaViewerWithPhotoOrVideo = useLastCallback((withDynamicLoading: boolean): void => {
    if (paidMedia && !paidMedia.isBought) return;
    if (withDynamicLoading && !message.isEphemeral) {
      searchChatMediaMessages({ chatId, threadId, currentMediaMessageId: messageId });
    }

    const parsedLink = webPage?.url && tryParseDeepLink(webPage.url);

    const videoContent = video || getWebPageVideo(webPage);
    const webpageTimestamp = parsedLink && 'timestamp' in parsedLink ? parsedLink.timestamp : undefined;

    openMediaViewer({
      chatId,
      threadId,
      messageId,
      origin: message.isEphemeral
        ? MediaViewerOrigin.Ephemeral
        : isScheduled ? MediaViewerOrigin.ScheduledInline : MediaViewerOrigin.Inline,
      timestamp: lastPlaybackTimestamp || videoContent?.timestamp || webpageTimestamp,
      withDynamicLoading: message.isEphemeral ? false : withDynamicLoading,
    });
  });
  const handlePhotoMediaClick = useLastCallback((): void => {
    const withDynamicLoading = !message.isEphemeral && !isScheduled && !paidMedia;
    openMediaViewerWithPhotoOrVideo(withDynamicLoading);
  });
  const handleVideoMediaClick = useLastCallback(() => {
    const isGif = message.content?.video?.isGif;
    const withDynamicLoading = !message.isEphemeral && !isGif && !isScheduled && !paidMedia;
    openMediaViewerWithPhotoOrVideo(withDynamicLoading);
  });

  const handleMediaClick = useLastCallback((): void => {
    const photo = getMessagePhoto(message) || getWebPagePhoto(webPage);
    if (photo) {
      handlePhotoMediaClick();
    }

    handleVideoMediaClick();
  });

  const handleAudioPlay = useLastCallback((): void => {
    openAudioPlayer({ chatId, threadId, messageId });
  });

  const handleAlbumMediaClick = useLastCallback((albumMessageId: number, albumIndex?: number): void => {
    if (paidMedia && !paidMedia.isBought) return;

    searchChatMediaMessages({ chatId, threadId, currentMediaMessageId: messageId });
    openMediaViewer({
      chatId,
      threadId,
      messageId: albumMessageId,
      mediaIndex: albumIndex,
      origin: isScheduled ? MediaViewerOrigin.ScheduledAlbum : MediaViewerOrigin.Album,
      withDynamicLoading: !paidMedia,
    });
  });

  const handleReadMedia = useLastCallback((): void => {
    if (message.isEphemeral) return;
    markMessagesRead({ chatId, messageIds: [messageId] });
  });

  const handleCancelUpload = useLastCallback(() => {
    cancelUploadMedia({ chatId, messageId });
  });

  const handleGroupForward = useLastCallback(() => {
    openForwardMenu({ fromChatId: chatId, groupedId });
  });

  const handleForward = useLastCallback(() => {
    if (album && album.messages) {
      const messageIds = album.messages.map(({ id }) => id);
      openForwardMenu({ fromChatId: chatId, messageIds });
    } else {
      openForwardMenu({ fromChatId: chatId, messageIds: [messageId] });
    }
  });

  const handleFocus = useLastCallback(() => {
    focusMessage({
      chatId, threadId: MAIN_THREAD_ID, messageId,
    });
  });

  const handleFocusForwarded = useLastCallback(() => {
    const originalChatId = (isSavedMessages && forwardInfo!.savedFromPeerId) || forwardInfo!.fromChatId!;

    if (isInDocumentGroup) {
      focusMessage({
        chatId: originalChatId, groupedId, groupedChatId: chatId, messageId: forwardInfo!.fromMessageId!,
      });
      return;
    }

    if (replyToPeerId && replyToTopId) {
      if (isRepliesChat) {
        openThread({
          isComments: true,
          originChannelId: replyToPeerId,
          originMessageId: replyToTopId,
          focusMessageId: forwardInfo!.fromMessageId!,
        });
      } else {
        focusMessage({
          chatId: replyToPeerId,
          threadId: replyToTopId,
          messageId: forwardInfo!.fromMessageId!,
        });
      }
    } else {
      focusMessage({
        chatId: originalChatId, messageId: forwardInfo!.fromMessageId!,
      });
    }
  });

  const selectWithGroupedId = useLastCallback((e: React.MouseEvent<HTMLDivElement>) => {
    e.stopPropagation();

    selectMessage(e, groupedId);
  });

  const handleTranslationClick = useLastCallback((e: React.MouseEvent<HTMLDivElement>) => {
    e.stopPropagation();

    openChatLanguageModal({ chatId, messageId: !isTranslatingChat ? messageId : undefined });
  });

  const handleOpenThread = useLastCallback(() => {
    openThread({
      chatId: message.chatId,
      threadId: message.id,
    });
  });

  const handleTopicChipClick = useLastCallback(() => {
    if (!messageTopic) return;
    focusMessage({
      chatId: replyToPeerId || chatId,
      threadId: messageTopic.id,
      messageId,
    });
  });

  const handleStoryClick = useLastCallback(() => {
    if (!story) return;
    openStoryViewer({
      peerId: story.peerId,
      storyId: story.id,
      isSingleStory: true,
    });
  });

  return {
    handleSenderClick,
    handleViaBotClick,
    handleGuestForClick,
    handleReplyClick,
    handleDocumentClick,
    handleMediaClick,
    handleAudioPlay,
    handleAlbumMediaClick,
    handlePhotoMediaClick,
    handleVideoMediaClick,
    handleMetaClick: selectWithGroupedId,
    handleTranslationClick,
    handleOpenThread,
    handleReadMedia,
    handleCancelUpload,
    handleGroupForward,
    handleForward,
    handleFocus,
    handleFocusForwarded,
    handleDocumentGroupSelectAll: selectWithGroupedId,
    handleTopicChipClick,
    handleStoryClick,
  };
}

