    description,
    gif,
    photo,
    menuButton: buildApiBotMenuButton(menuButton),
    privacyPolicyUrl,
    commands: commandsArray?.length ? commandsArray : undefined,
    hasPreviewMedia: hasPreviewMedias,
    appSettings: appSettings && buildBotAppSettings(appSettings),
