function getTypingDraftEntries<T extends GlobalState>(
  global: T,
  chatId: string,
  threadId: ThreadId,
) {
  const typingDraftStore = selectThreadLocalStateParam(global, chatId, threadId, 'typingDraftIdByRandomId');
  const typingDraftEntries = Object.entries(typingDraftStore || {}).reduce((result, [randomId, messageId]) => {
    const message = selectChatMessage(global, chatId, messageId);
    if (!message?.isTypingDraft) {
      return result;
    }

    result.push({ randomId, message });
    return result;
  }, [] as TypingDraftEntry[]);

  return typingDraftEntries;
}

function removeTypingDraftEntries<T extends GlobalState>(
  global: T,
  chatId: string,
  threadId: ThreadId,
  typingDraftEntries: TypingDraftEntry[],
) {
  if (!typingDraftEntries.length) {
    return global;
  }

  const typingDraftStore = selectThreadLocalStateParam(global, chatId, threadId, 'typingDraftIdByRandomId') || {};
  const randomIds = typingDraftEntries.map(({ randomId }) => randomId);
  const nextTypingDraftStore = omit(typingDraftStore, randomIds);
  const messageIdsToDelete = randomIds.reduce((result, randomId) => {
    const messageId = typingDraftStore[randomId];
    const message = messageId ? selectChatMessage(global, chatId, messageId) : undefined;
    if (!message?.isTypingDraft) {
      return result;
    }

    result.push(messageId);
    return result;
  }, [] as number[]);

  global = replaceThreadLocalStateParam(
    global,
    chatId,
    threadId,
    'typingDraftIdByRandomId',
    Object.keys(nextTypingDraftStore).length ? nextTypingDraftStore : undefined,
  );

  if (messageIdsToDelete.length) {
    global = deleteChatMessages(global, chatId, messageIdsToDelete);
  }

  return global;
}

function shouldBumpGuestBotTopPeer<T extends GlobalState>(global: T, message: ApiMessage) {
  const { guestChatViaId, senderId } = message;
  if (message.isOutgoing || message.content.action || guestChatViaId !== global.currentUserId || !senderId) {
    return false;
  }

  const sender = selectUser(global, senderId);
  return Boolean(sender?.isGuestChatBot);
}

function shouldBumpInlineBotTopPeer(message: ApiMessage) {
  return Boolean(message.isOutgoing && !message.content.action && message.viaBotId);
}

function shouldBumpCorrespondentTopPeer<T extends GlobalState>(global: T, chatId: string) {
  const user = selectUser(global, chatId);
  return Boolean(user && !user.isSelf && !isUserBot(user) && !isDeletedUser(user));
}

function addWebPages<T extends GlobalState>(
  global: T,
  webPages?: ApiWebPage[],
) {
  if (!webPages?.length) {
    return global;
  }

  const addedWebPageIds = new Set<string>();

  webPages.forEach((page) => {
    if (addedWebPageIds.has(page.id)) {
      return;
    }

    global = replaceWebPage(global, page.id, page);
    addedWebPageIds.add(page.id);
  });

  return global;
}

function updateReactions<T extends GlobalState>(
  global: T,
  actions: RequiredGlobalActions,
  {
    chatId, id, threadId, reactions,
  }: {
    chatId: string;
    id: number;
    threadId?: ThreadId;
    reactions: ApiReactions;
  },
): T {
  const chat = selectChat(global, chatId);
  const message = selectChatMessage(global, chatId, id);

  if (!chat || !message) {
    // Simplified logic to update counter only
    const hasUnread = checkIfHasUnreadReactions(global, reactions);
    if (hasUnread) {
      global = addUnreadReactions({ global, chatId, ids: [id] });
    } else {
      // Reload unread reactions to update counter
      actions.loadUnreadReactions({ chatId, threadId });
    }
    return global;
  }

  const currentReactions = message?.reactions;

  // `updateMessageReactions` happens with an interval, so we try to avoid redundant global state updates
  if (currentReactions && areDeepEqual(reactions, currentReactions)) {
    return global;
  }

  const localPaidReaction = currentReactions?.results.find((r) => r.localAmount);
  // Save local count on update, but reset if we sent reaction
  if (localPaidReaction?.localAmount) {
    const { localIsPrivate: isPrivate, localAmount, localPeerId } = localPaidReaction;
    reactions.results = addPaidReaction(reactions.results, localAmount, isPrivate, localPeerId);
  }

  global = updateChatMessage(global, chatId, id, { reactions });

  if (!message.isOutgoing) {
    return global;
  }

  const { reaction, isOwn, isUnread } = reactions.recentReactions?.[0] ?? {};
  const reactionEffectsEnabled = selectPerformanceSettingsValue(global, 'reactionEffects');
  if (reactionEffectsEnabled && message && reaction && isUnread && !isOwn) {
    const messageKey = getMessageKey(message);
    // Start reaction only in master tab
    actions.startActiveReaction({ containerId: messageKey, reaction, tabId: getCurrentTabId() });
  }

  const hasUnreadReactionsForMessageInChat = message.reactions && checkIfHasUnreadReactions(global, message.reactions);
  const hasUnreadReactionsInNewReactions = checkIfHasUnreadReactions(global, reactions);

  // Only notify about added reactions, not removed ones
  if (hasUnreadReactionsInNewReactions && !hasUnreadReactionsForMessageInChat) {
    global = addUnreadReactions({ global, chatId, ids: [id] });

    const newMessage = selectChatMessage(global, chatId, id);

    if (!chat || !newMessage) return global;

    onTickEnd(() => {
      notifyAboutMessage({
        chat,
        message: newMessage,
        isReaction: true,
      });
    });
  }

  if (!hasUnreadReactionsInNewReactions && hasUnreadReactionsForMessageInChat) {
    global = removeUnreadReactions({ global, chatId, ids: [id] });
  }

  return global;
}

function updateWithLocalMedia(
  global: RequiredGlobalState,
  chatId: string,
  id: number,
  isNew: boolean,
  messageUpdate: Partial<ApiMessage>,
  isScheduled = false,
) {
  const currentMessage = isScheduled
    ? selectScheduledMessage(global, chatId, id)
    : selectChatMessage(global, chatId, id);

  if (!currentMessage && !isNew) return global;

  // Preserve locally uploaded media.
  if (currentMessage && messageUpdate.content && !isLocalMessageId(id)) {
    const {
      photo, video, document,
    } = getMessageContent(currentMessage);

    if (photo && messageUpdate.content.photo) {
      messageUpdate.content.photo.blobUrl ??= photo.blobUrl;
      messageUpdate.content.photo.thumbnail ??= photo.thumbnail;
    } else if (video && messageUpdate.content.video) {
      messageUpdate.content.video.blobUrl ??= video.blobUrl;
    } else if (document && messageUpdate.content.document) {
      messageUpdate.content.document.previewBlobUrl ??= document.previewBlobUrl;
    }
  }

  const newMessage = currentMessage ? { ...currentMessage, ...messageUpdate } : messageUpdate;

  return isScheduled
    ? updateScheduledMessage(global, chatId, id, newMessage)
    : updateChatMessage(global, chatId, id, newMessage);
}

function updateListedAndViewportIds<T extends GlobalState>(
  global: T, message: ApiMessage,
) {
  const { id, chatId } = message;

  const savedDialogId = selectSavedDialogIdFromMessage(global, message);
  const threadId = savedDialogId || selectThreadIdFromMessage(global, message);
  const threadInfo = selectThreadInfo(global, chatId, threadId);

  const mainThreadReadState = selectThreadReadState(global, chatId, MAIN_THREAD_ID);
  const isUnreadChatNotLoaded = mainThreadReadState?.unreadCount && !selectListedIds(global, chatId, MAIN_THREAD_ID);

  if (threadId) {
    global = updateListedIds(global, chatId, threadId, [id]);

    Object.values(global.byTabId).forEach(({ id: tabId }) => {
      if (selectIsViewportNewest(global, chatId, threadId, tabId)) {
        // Always keep the first unread message in the viewport list
        const firstUnreadId = selectFirstUnreadId(global, chatId, threadId);
        const candidateGlobal = addViewportId(global, chatId, threadId, id, tabId);
        const newViewportIds = selectViewportIds(candidateGlobal, chatId, threadId, tabId);

        if (!firstUnreadId || newViewportIds!.includes(firstUnreadId)) {
          global = candidateGlobal;
        }
      }
    });

    if (threadInfo) {
      global = updateThreadInfoLastMessageId(global, chatId, threadId, message.id);

      if (!isMessageLocal(message) && !isActionMessage(message)) {
        const newCount = (threadInfo.messagesCount || 0) + 1;
        global = updateThreadInfoMessagesCount(global, chatId, threadId, newCount);
      }
    }
  }

  if (isUnreadChatNotLoaded) {
    return global;
  }

  global = updateListedIds(global, chatId, MAIN_THREAD_ID, [id]);

  Object.values(global.byTabId).forEach(({ id: tabId }) => {
    if (selectIsViewportNewest(global, chatId, MAIN_THREAD_ID, tabId)) {
      // Always keep the first unread message in the viewport list
      const firstUnreadId = selectFirstUnreadId(global, chatId, MAIN_THREAD_ID);
      const candidateGlobal = addViewportId(global, chatId, MAIN_THREAD_ID, id, tabId);
      const newViewportIds = selectViewportIds(candidateGlobal, chatId, MAIN_THREAD_ID, tabId);

      if (!firstUnreadId || newViewportIds!.includes(firstUnreadId)) {
        global = candidateGlobal;
      }
    }
  });

  return global;
}

function updateChatLastMessage<T extends GlobalState>(
  global: T,
  chatId: string,
  message: ApiMessage,
  force = false,
) {
  const currentLastMessageId = selectChatLastMessageId(global, chatId);

  const threadId = selectThreadIdFromMessage(global, message);
  global = updateThreadInfoLastMessageId(global, chatId, threadId, message.id);

  const savedDialogId = selectSavedDialogIdFromMessage(global, message);
  if (savedDialogId) {
    global = updateChatLastMessageId(global, savedDialogId, message.id, 'saved');
  }

  if (currentLastMessageId && !force) {
    const isSameOrNewer = (
      currentLastMessageId === message.id || currentLastMessageId === message.previousLocalId
    ) || message.id > currentLastMessageId;

    if (!isSameOrNewer) {
      return global;
    }
  }

  global = updateChatLastMessageId(global, chatId, message.id);

  return global;
}

function findLastMessage<T extends GlobalState>(global: T, chatId: string, threadId: ThreadId = MAIN_THREAD_ID) {
  const byId = selectChatMessages(global, chatId);
  const listedIds = selectListedIds(global, chatId, threadId);

  if (!byId || !listedIds) {
    return undefined;
  }

  let i = listedIds.length;
  while (i--) {
    const message = byId[listedIds[i]];
    if (message && !message.isDeleting) {
      return message;
    }
  }

  return undefined;
}

function deleteParticipantHistory<T extends GlobalState>(
  global: T,
  chatId: string,
  peerId: string,
  actions: RequiredGlobalActions,
) {
  const byId = selectChatMessages(global, chatId);

  const messageIds = Object.values(byId).filter((message) => {
    return message.senderId === peerId;
  }).map((message) => message.id);

  if (!messageIds.length) {
    return;
  }

  deleteMessages(global, chatId, messageIds, actions);
}

function deleteThread<T extends GlobalState>(
  global: T,
  chatId: string,
  threadId: ThreadId,
  actions: RequiredGlobalActions,
) {
  const byId = selectChatMessages(global, chatId);
  if (!byId) {
    return;
  }

  const messageIds = Object.values(byId).filter((message) => {
    const messageThreadId = selectThreadIdFromMessage(global, message);
    return messageThreadId === threadId;
  }).map((message) => message.id);

  if (!messageIds.length) {
    return;
  }

  deleteMessages(global, chatId, messageIds, actions);
}

function deleteMessages<T extends GlobalState>(
  global: T, chatId: string | undefined, ids: number[], actions: RequiredGlobalActions,
) {
  // Channel update

  if (chatId) {
    const chat = selectChat(global, chatId);
    if (!chat) return;

    const threadIdsToUpdate = new Set<ThreadId>();
    threadIdsToUpdate.add(MAIN_THREAD_ID);

    ids.forEach((id) => {
      global = updateChatMessage(global, chatId, id, {
        isDeleting: true,
      });

      if (selectTopic(global, chatId, id)) {
        global = deleteTopic(global, chatId, id);
      }

      const message = selectChatMessage(global, chatId, id);
      if (!message) {
        return;
      }

      if (message.content.action?.type === 'chatEditPhoto' && message.content.action.photo) {
        global = deletePeerPhoto(global, chatId, message.content.action.photo.id, true);
      }

      const threadId = selectThreadIdFromMessage(global, message);
      if (threadId) {
        threadIdsToUpdate.add(threadId);
      }
    });

    actions.requestChatUpdate({ chatId });

    const idsSet = new Set(ids);

    threadIdsToUpdate.forEach((threadId) => {
      if (chat.isForum && threadId !== MAIN_THREAD_ID) {
        // Refresh unread count
        actions.loadTopicById({ chatId, topicId: Number(threadId) });
      }

      const threadInfo = selectThreadInfo(global, chatId, threadId);
      if (!threadInfo?.lastMessageId || !idsSet.has(threadInfo.lastMessageId)) return;

      const newLastMessage = findLastMessage(global, chatId, threadId);

      if (!newLastMessage) {
        return;
      }

      if (threadId === MAIN_THREAD_ID) {
        global = updateChatLastMessage(global, chatId, newLastMessage, true);
      }

      global = updateThreadInfoLastMessageId(global, chatId, threadId, newLastMessage.id);
    });

    setGlobal(global);

    const isAnimatingAsSnap = selectCanAnimateSnapEffect(global);

    setTimeout(() => {
      global = getGlobal();
      // Prevent local deletion of sent messages in case of desync
      const stillDeletedIds = ids.filter((id) => selectChatMessage(global, chatId, id)?.isDeleting);
      global = deleteChatMessages(global, chatId, stillDeletedIds);
      setGlobal(global);
    }, isAnimatingAsSnap ? SNAP_ANIMATION_DELAY : ANIMATION_DELAY);

    return;
  }

  // Common box update

  const chatIdsToUpdate: string[] = [];

  ids.forEach((id) => {
    const commonBoxChatId = selectCommonBoxChatId(global, id);
    if (commonBoxChatId) {
      chatIdsToUpdate.push(commonBoxChatId);

      global = updateChatMessage(global, commonBoxChatId, id, {
        isDeleting: true,
      });

      const newLastMessage = findLastMessage(global, commonBoxChatId);
      if (newLastMessage) {
        global = updateChatLastMessage(global, commonBoxChatId, newLastMessage, true);
      }

      const message = selectChatMessage(global, commonBoxChatId, id);
      if (selectIsChatWithSelf(global, commonBoxChatId) && message) {
        const threadId = selectThreadIdFromMessage(global, message);
        if (getIsSavedDialog(commonBoxChatId, threadId, global.currentUserId)) {
          const newLastSavedDialogMessage = findLastMessage(global, commonBoxChatId, threadId);
          actions.requestSavedDialogUpdate({ chatId: String(threadId) });
          if (newLastSavedDialogMessage) {
            global = updateChatLastMessageId(global, commonBoxChatId, newLastSavedDialogMessage.id, 'saved');
          }
        }
      }

      if (message?.content.action?.type === 'chatEditPhoto' && message.content.action.photo) {
        global = deletePeerPhoto(global, commonBoxChatId, message.content.action.photo.id, true);
      }

      const isAnimatingAsSnap = selectCanAnimateSnapEffect(global);

      setTimeout(() => {
        global = getGlobal();
        global = deleteChatMessages(global, commonBoxChatId, [id]);
        setGlobal(global);
      }, isAnimatingAsSnap ? SNAP_ANIMATION_DELAY : ANIMATION_DELAY);
    }
  });

  setGlobal(global);

  unique(chatIdsToUpdate).forEach((id) => {
    actions.requestChatUpdate({ chatId: id });
  });
}

function deleteEphemeralMessagesWithAnimation<T extends GlobalState>(
  global: T, chatId: string, ids: number[],
) {
  const messages = ids
    .map((id) => selectEphemeralMessage(global, chatId, id))
    .filter(Boolean);
  if (!messages.length) return;

  messages.forEach((message) => {
    global = updateEphemeralMessage(global, {
      ...message,
      isDeleting: true,
    });
  });
  setGlobal(global);

  const isAnimatingAsSnap = selectCanAnimateSnapEffect(global);
  setTimeout(() => {
    global = getGlobal();
    const stillDeletingIds = messages
      .map(({ id }) => id)
      .filter((id) => selectEphemeralMessage(global, chatId, id)?.isDeleting);
    global = deleteEphemeralMessages(global, chatId, stillDeletingIds);
    setGlobal(global);
    scheduleEphemeralExpiration(global);
  }, isAnimatingAsSnap ? SNAP_ANIMATION_DELAY : ANIMATION_DELAY);
}

function isEphemeralMessageInCurrentThread<T extends GlobalState>(
  global: T,
  tabId: number,
  message: ApiMessage,
) {
  const currentMessageList = selectCurrentMessageList(global, tabId);
  if (!currentMessageList
    || currentMessageList.chatId !== message.chatId
    || currentMessageList.type !== 'thread') {
    return false;
  }

  const currentThreadId = Number(currentMessageList.threadId);
  return currentThreadId === MAIN_THREAD_ID
    ? message.ephemeralTopMsgId === undefined
    : message.ephemeralTopMsgId === currentThreadId;
}

function deleteScheduledMessages<T extends GlobalState>(
  chatId: string, ids: number[], actions: RequiredGlobalActions, global: T,
) {
  ids.forEach((id) => {
    global = updateScheduledMessage(global, chatId, id, {
      isDeleting: true,
    });
  });

  setGlobal(global);

  const isAnimatingAsSnap = selectCanAnimateSnapEffect(global);

  setTimeout(() => {
    global = getGlobal();
    global = deleteChatScheduledMessages(global, chatId, ids);
    setGlobal(global);
  }, isAnimatingAsSnap ? SNAP_ANIMATION_DELAY : ANIMATION_DELAY);
}

async function doAuthentication(
  sender: MTProtoPlainSender,
  log: any,
  dcId: number,
  isTestServer?: boolean,
) {
  // Step 1 sending: PQ Request, endianness doesn't matter since it's random
  let bytes = generateRandomBytes(16);

  const nonce = readBigIntFromBuffer(bytes, false, true);
  const resPQ = await sender.send(new Api.ReqPqMulti({ nonce }));
  log.debug('Starting authKey generation step 1');

  if (!(resPQ instanceof Api.ResPQ)) {
    throw new SecurityError(`Step 1 answer was ${resPQ}`);
  }
  if (resPQ.nonce !== nonce) {
    throw new SecurityError('Step 1 invalid nonce from server');
  }
  // Limit unauthenticated factorization to the protocol's canonical 63-bit `pq`
  // https://core.telegram.org/mtproto/auth_key#dh-exchange-initiation
  if (
    resPQ.pq.length === 0
    || resPQ.pq.length > MAX_PQ_BYTES
    || resPQ.pq[0] === 0
  ) {
    throw new SecurityError('Step 1 invalid pq encoding');
  }
  const pq = readBigIntFromBuffer(resPQ.pq, false);
  if (pq > MAX_PQ || pq < 15n || pq % 2n === 0n) {
    throw new SecurityError('Step 1 invalid pq value');
  }
  let targetFingerprint;
  let targetKey;
  for (const fingerprint of resPQ.serverPublicKeyFingerprints) {
    targetKey = SERVER_KEYS.get(fingerprint);
    if (targetKey !== undefined) {
      targetFingerprint = fingerprint;
      break;
    }
  }
  if (targetFingerprint === undefined || targetKey === undefined) {
    throw new SecurityError(
      'Step 2 could not find a valid key for fingerprints',
    );
  }
  log.debug('Finished authKey generation step 1');
  // Step 2 sending: DH Exchange
  const { p, q } = Factorizator.factorize(pq);

  const pBuffer = getByteArray(p);
  const qBuffer = getByteArray(q);

  bytes = generateRandomBytes(32);
  const newNonce = readBigIntFromBuffer(bytes, true, true);
  const pqInnerData = new Api.PQInnerDataDc({
    pq: getByteArray(pq), // unsigned
    p: pBuffer,
    q: qBuffer,
    nonce: resPQ.nonce,
    serverNonce: resPQ.serverNonce,
    newNonce,
    dc: buildAuthDcId(dcId, isTestServer),
  }).getBytes();
  if (pqInnerData.length > 144) {
    throw new SecurityError('Step 1 invalid nonce from server');
  }
  // Value should be padded to be made 192 exactly
  const padding = generateRandomBytes(192 - pqInnerData.length);
  const dataWithPadding = concat(pqInnerData, padding);
  const dataPadReversed = copy(dataWithPadding).reverse();

  let encryptedData;
  for (let i = 0; i < RETRIES; i++) {
    const tempKey = generateRandomBytes(32);
    const shaDigestKeyWithData = await sha256(concat(tempKey, dataWithPadding));
    const dataWithHash = concat(dataPadReversed, shaDigestKeyWithData);

    const ige = new IGE(tempKey, new Uint8Array(32));
    const aesEncrypted = ige.encryptIge(dataWithHash);
    const tempKeyXor = bufferXor(tempKey, await sha256(aesEncrypted));

    const keyAesEncrypted = concat(tempKeyXor, aesEncrypted);
    const keyAesEncryptedInt = readBigIntFromBuffer(keyAesEncrypted, false, false);
    if (keyAesEncryptedInt >= targetKey.n) {
      log.debug('Aes key greater than RSA. retrying');
      continue;
    }
    const encryptedDataBuffer = modExp(keyAesEncryptedInt, BigInt(targetKey.e), targetKey.n);
    encryptedData = readBufferFromBigInt(encryptedDataBuffer, 256, false, false);

    break;
  }
  if (encryptedData === undefined) {
    throw new SecurityError(
      'Step 2 could create a secure encrypted key',
    );
  }
  log.debug('Step 2 : Generated a secure aes encrypted data');

  const serverDhParams = await sender.send(
    new Api.ReqDHParams({
      nonce: resPQ.nonce,
      serverNonce: resPQ.serverNonce,
      p: pBuffer,
      q: qBuffer,
      publicKeyFingerprint: targetFingerprint,
      encryptedData,
    }),
  );

  if (
    !(
      serverDhParams instanceof Api.ServerDHParamsOk
      || serverDhParams instanceof Api.ServerDHParamsFail
    )
  ) {
    throw new Error(`Step 2.1 answer was ${serverDhParams}`);
  }
  if (serverDhParams.nonce !== resPQ.nonce) {
    throw new SecurityError('Step 2 invalid nonce from server');
  }

  if (serverDhParams.serverNonce !== resPQ.serverNonce) {
    throw new SecurityError('Step 2 invalid server nonce from server');
  }

  if (serverDhParams instanceof Api.ServerDHParamsFail) {
    const newNonceHash = (
      await sha1(toSignedLittleBuffer(newNonce, 32))
    ).slice(4, 20);
    const expectedNewNonceHash = readBigIntFromBuffer(newNonceHash, true, true);
    if (serverDhParams.newNonceHash !== expectedNewNonceHash) {
      throw new SecurityError('Step 2 invalid DH fail nonce from server');
    }
    throw new SecurityError('Step 2 server rejected DH parameters');
  }
  log.debug('Finished authKey generation step 2');
  log.debug('Starting authKey generation step 3');

  // Step 3 sending: Complete DH Exchange
  const { key, iv } = await generateKeyDataFromNonce(
    resPQ.serverNonce,
    newNonce,
  );
  if (serverDhParams.encryptedAnswer.length % 16 !== 0) {
    // See PR#453
    throw new SecurityError('Step 3 AES block size mismatch');
  }
  const ige = new IGE(key, iv);
  const plainTextAnswer = ige.decryptIge(serverDhParams.encryptedAnswer);
  const reader = new BinaryReader(plainTextAnswer);
  const hash = reader.read(20); // hash sum
  const serverDhInner = reader.tgReadObject();
  if (!(serverDhInner instanceof Api.ServerDHInnerData)) {
    throw new Error(`Step 3 answer was ${serverDhInner}`);
  }
  const paddingLength = plainTextAnswer.length - reader.tellPosition();
  if (paddingLength < 0 || paddingLength > 15) {
    throw new SecurityError('Step 3 invalid encrypted answer padding');
  }
  const sha1Answer = await sha1(serverDhInner.getBytes());
  if (!compareBuffersConstantTime(hash, sha1Answer)) {
    throw new SecurityError('Step 3 Invalid hash answer');
  }

  if (serverDhInner.nonce !== resPQ.nonce) {
    throw new SecurityError('Step 3 Invalid nonce in encrypted answer');
  }
  if (serverDhInner.serverNonce !== resPQ.serverNonce) {
    throw new SecurityError(
      'Step 3 Invalid server nonce in encrypted answer',
    );
  }
  const dhPrime = validateDhParameters(
    serverDhInner.dhPrime,
    serverDhInner.g,
  );
  const ga = readBigIntFromBuffer(serverDhInner.gA, false, false);
  const timeOffset = serverDhInner.serverTime - Math.floor(Date.now() / 1000);
  validateDhPublicValue(ga, dhPrime, 'g_a');
  let retryId = 0n;

  // A retry uses a fresh `b` and identifies the preceding failed key
  // https://core.telegram.org/mtproto/auth_key#dh-key-exchange-complete
  for (let attempt = 0; attempt < MAX_DH_GEN_ATTEMPTS; attempt++) {
    const b = generateDhPrivateExponent(dhPrime);
    const gb = modExp(BigInt(serverDhInner.g), b, dhPrime);
    const gab = modExp(ga, b, dhPrime);
    validateDhPublicValue(gb, dhPrime, 'g_b');

    const clientDhInner = new Api.ClientDHInnerData({
      nonce: resPQ.nonce,
      serverNonce: resPQ.serverNonce,
      retryId,
      gB: readBufferFromBigInt(gb, DH_PRIME_BYTES, false),
    }).getBytes();
    const clientDhEncrypted = ige.encryptIge(
      concat(await sha1(clientDhInner), clientDhInner),
    );
    const dhGen = await sender.send(
      new Api.SetClientDHParams({
        nonce: resPQ.nonce,
        serverNonce: resPQ.serverNonce,
        encryptedData: clientDhEncrypted,
      }),
    );
    if (
      !(
        dhGen instanceof Api.DhGenOk
        || dhGen instanceof Api.DhGenRetry
        || dhGen instanceof Api.DhGenFail
      )
    ) {
      throw new Error(`Step 3.1 answer was ${dhGen}`);
    }
    if (dhGen.nonce !== resPQ.nonce) {
      throw new SecurityError(
        `Step 3 invalid ${dhGen.className} nonce from server`,
      );
    }
    if (dhGen.serverNonce !== resPQ.serverNonce) {
      throw new SecurityError(
        `Step 3 invalid ${dhGen.className} server nonce from server`,
      );
    }

    const authKeyBytes = readBufferFromBigInt(gab, DH_PRIME_BYTES, false);
    const authKeyHash = await sha1(authKeyBytes);
    const authKey = new AuthKey(authKeyBytes, authKeyHash);
    let nonceNumber: number;
    let dhHash: bigint;
    if (dhGen instanceof Api.DhGenOk) {
      nonceNumber = 1;
      dhHash = dhGen.newNonceHash1;
    } else if (dhGen instanceof Api.DhGenRetry) {
      nonceNumber = 2;
      dhHash = dhGen.newNonceHash2;
    } else {
      nonceNumber = 3;
      dhHash = dhGen.newNonceHash3;
    }
    if (dhHash !== await authKey.calcNewNonceHash(newNonce, nonceNumber)) {
      throw new SecurityError('Step 3 invalid new nonce hash');
    }

    if (dhGen instanceof Api.DhGenOk) {
      // https://core.telegram.org/mtproto/auth_key#dh-key-exchange-complete
      const serverSalt = readBigIntFromBuffer(bufferXor(
        toSignedLittleBuffer(newNonce, 32).slice(0, 8),
        toSignedLittleBuffer(resPQ.serverNonce, 16).slice(0, 8),
      ), true, true);
      log.debug('Finished authKey generation step 3');
      return { authKey, timeOffset, serverSalt };
    }
    if (dhGen instanceof Api.DhGenFail) {
      throw new SecurityError('Step 3 server rejected DH key');
    }

    retryId = readBigIntFromBuffer(authKeyHash.slice(0, 8), true, true);
  }

  throw new SecurityError('Step 3 DH retry limit exceeded');
}

function buildAuthDcId(dcId: number, isTestServer?: boolean) {
  return isTestServer ? dcId + 10000 : dcId;
}

function getSearchResultKey(message: ApiMessage): SearchResultKey {
  const { chatId, id } = message;

  return `${chatId}_${id}`;
}

function parseSearchResultKey(key: SearchResultKey) {
  const [chatId, messageId] = key.split('_');

  return [chatId, Number(messageId)] as const;
}

async function initGlobal(force: boolean = false, prevGlobal?: GlobalState) {
  prevGlobal = prevGlobal || getGlobal();
  if (!force && 'byTabId' in prevGlobal) {
    return;
  }

  const initial = cloneDeep(INITIAL_GLOBAL_STATE);
  const cache = await loadCache(initial);
  let global = cache || initial;
  if (IS_MOCKED_CLIENT) global.auth.state = 'authorizationStateReady';

  const { hasPasscode, isScreenLocked } = global.passcode;
  if (hasPasscode && !isScreenLocked) {
    global = updatePasscodeSettings(global, {
      isScreenLocked: true,
    });

    clearStoredSession();
  }

  if (force) {
    global.byTabId = prevGlobal.byTabId;
  }

  if (!cache) { // Try loading shared state separately
    const storedSharedState = await loadCachedSharedState();
    if (storedSharedState) {
      global.sharedState = storedSharedState;
    }
  }

  setGlobal(global);
}

interface CanvasRects {
  colorRect: {
    left: number;
    top: number;
    width: number;
    height: number;
  };
  hueRect: {
    left: number;
    width: number;
  };
}

function updateRects() {
      const colorBounds = colorPickerRef.current!.getBoundingClientRect();
      const hueBounds = huePickerRef.current!.getBoundingClientRect();

      rectsRef.current = {
        colorRect: {
          left: colorBounds.left + window.scrollX,
          top: colorBounds.top + window.scrollY,
          width: colorBounds.width,
          height: colorBounds.height,
        },
        hueRect: {
          left: hueBounds.left + window.scrollX,
          width: hueBounds.width,
        },
      };

      return rectsRef.current;
    }

function handleColorDrag(e: MouseEvent | RealTouchEvent) {
      const rects = updateRects();
      const { colorRect } = rects;
      const colorPosition = [
        Math.min(Math.max(0, e.pageX! - colorRect.left), colorRect.width - 1),
        Math.min(Math.max(0, e.pageY! - colorRect.top), colorRect.height - 1),
      ];

      const { huePosition } = buildPositionsFromColor(colorRef.current, rects);

      setColor(buildColorFromPositions({ colorPosition, huePosition }, rects));
      markIsDragging();

      return true;
    }

function handleHueDrag(e: MouseEvent | RealTouchEvent) {
      const rects = updateRects();
      const { colorPosition } = buildPositionsFromColor(colorRef.current, rects);
      const huePosition = Math.min(Math.max(0, e.pageX! - rects.hueRect.left), rects.hueRect.width - 1);

      setColor(buildColorFromPositions({ colorPosition, huePosition }, rects));
      markIsDragging();

      return true;
    }

function useLangString(key: RegularLangKey, langCode?: string) {
  const [value, setValue] = useState<string | undefined>(undefined);

  const fetchLangString = useLastCallback(async () => {
    if (!langCode) return undefined;

    const result = await callApi('fetchLangStrings', {
      langCode,
      langPack: LANG_PACK,
      keys: [key],
    });
    const langString = result?.strings[key];
    if (!langString || typeof langString !== 'string') return undefined;
    return langString;
  });

  useEffect(() => {
    fetchLangString().then(setValue);
  }, [key, langCode]);

  return value;
}

function handleScrollerRef(element?: HTMLDivElement) {
