function callApiLocal<T extends keyof Methods>(
  fnName: T, ...args: MethodArgs<T>
): EnsurePromise<MethodResponse<T>> {
  if (!isInited) {
    if (NO_QUEUE_BEFORE_INIT.has(fnName)) {
      return Promise.resolve(undefined) as EnsurePromise<MethodResponse<T>>;
    }

    const deferred = new Deferred();
    localApiRequestsQueue.push({ fnName, args, deferred });

    return deferred.promise as EnsurePromise<MethodResponse<T>>;
  }

  const promise = makeRequest({
    type: 'callMethod',
    name: fnName,
    args,
  });

  // Some TypeScript magic to make sure `VirtualClass` is never returned from any method
  if (DEBUG) {
    (async () => {
      try {
        type ForbiddenTypes =
          Api.VirtualClass<any>
          | (Api.VirtualClass<any> | undefined)[];
        type ForbiddenResponses =
          ForbiddenTypes
          | (AnyLiteral & Record<string, ForbiddenTypes>);

        // Unwrap all chained promises
        const response = await promise;
        // Make sure responses do not include `VirtualClass` instances
        const allowedResponse: Exclude<typeof response, ForbiddenResponses> = response;
        // Suppress "unused variable" constraint
        void allowedResponse;
      } catch (err) {
        // Do noting
      }
    })();
  }

  return promise as EnsurePromise<MethodResponse<T>>;
}

function callApi<T extends keyof Methods>(fnName: T, ...args: MethodArgs<T>): EnsurePromise<MethodResponse<T>> {
  if (!isInited && isMasterTab) {
    if (NO_QUEUE_BEFORE_INIT.has(fnName)) {
      return Promise.resolve(undefined) as EnsurePromise<MethodResponse<T>>;
    }

    const deferred = new Deferred();
    apiRequestsQueue.push({ fnName, args, deferred });

    return deferred.promise as EnsurePromise<MethodResponse<T>>;
  }

  const promise = isMasterTab ? makeRequest({
    type: 'callMethod',
    name: fnName,
    args,
  }) : makeRequestToMaster({
    name: fnName,
    args,
  });

  // Some TypeScript magic to make sure `VirtualClass` is never returned from any method
  if (DEBUG) {
    (async () => {
      try {
        type ForbiddenTypes =
          Api.VirtualClass<any>
          | (Api.VirtualClass<any> | undefined)[];
        type ForbiddenResponses =
          ForbiddenTypes
          | (AnyLiteral & Record<string, ForbiddenTypes>);

        // Unwrap all chained promises
        const response = await promise;
        // Make sure responses do not include `VirtualClass` instances
        const allowedResponse: Exclude<typeof response, ForbiddenResponses> = response;
        // Suppress "unused variable" constraint
        void allowedResponse;
      } catch (err) {
        // Do noting
      }
    })();
  }

  return promise as EnsurePromise<MethodResponse<T>>;
}

function cancelApiProgress(progressCallback: ApiOnProgress) {
  progressCallback.isCanceled = true;

  const { messageId } = requestStatesByCallback.get(progressCallback) || {};
  if (!messageId) {
    return;
  }

  if (isMasterTab) {
    cancelApiProgressMaster(messageId);
  } else {
    channel.postMessage({
      type: 'cancelApiProgress',
      token: getCurrentTabId(),
      messageId,
    });
  }
}

function cancelApiProgressMaster(messageId: string) {
  postMessageOnTickEnd({
    type: 'cancelProgress',
    messageId,
  });
}

function subscribeToWorker(onUpdate: OnApiUpdate) {
  worker?.addEventListener('message', ({ data }: WorkerMessageEvent) => {
    data?.payloads.forEach((payload) => {
      if (payload.type === 'updates') {
        let DEBUG_startAt: number | undefined;
        if (DEBUG) {
          DEBUG_startAt = performance.now();
        }

        payload.updates.forEach(onUpdate);

        if (DEBUG) {
          const duration = performance.now() - DEBUG_startAt!;
          if (duration > 5) {
            // eslint-disable-next-line no-console
            console.warn(`[API] Slow updates processing: ${payload.updates.length} updates in ${duration} ms`);
          }
        }
      } else if (payload.type === 'methodResponse') {
        handleMethodResponse(payload);
      } else if (payload.type === 'methodCallback') {
        handleMethodCallback(payload);
      } else if (payload.type === 'unhandledError') {
        const message = payload.error?.message;
        if (message && IGNORE_UNHANDLED_ERRORS.has(message)) return;
        throw new Error(message);
      } else if (payload.type === 'sendBeacon') {
        navigator.sendBeacon(payload.url, payload.data);
      } else if (payload.type === 'debugLog') {
        logDebugMessage(payload.level, ...payload.args);
      }
    });
  });
}

function handleMethodResponse(data: {
  messageId: string;
  response?: ThenArg<MethodResponse<keyof Methods>>;
  error?: Pick<ApiError, 'message' | 'code' | 'hasErrorKey'>;
}) {
  const requestState = requestStates.get(data.messageId);
  if (requestState) {
    if (data.error) {
      requestState.reject(data.error);
    } else {
      requestState.resolve(data.response);
    }
  }
}

function handleMethodCallback(data: {
  messageId: string;
  callbackArgs: any[];
}) {
  requestStates.get(data.messageId)?.callback?.(...data.callbackArgs);
}

function makeRequestToMaster(message: {
  messageId?: string;
  name: keyof Methods;
  args: MethodArgs<keyof Methods>;
  withCallback?: boolean;
}) {
  const messageId = generateUniqueId();
  const payload = {
    messageId,
    ...message,
  };

  const requestState = { messageId } as RequestState;

  // Re-wrap type because of `postMessage`
  const promise = new Promise<MethodResponse<keyof Methods>>((resolve, reject) => {
    Object.assign(requestState, { resolve, reject });
  });

  if ('args' in payload && 'name' in payload && typeof payload.args[1] === 'function') {
    payload.withCallback = true;

    const callback = payload.args.pop() as AnyToVoidFunction;
    requestState.callback = callback;
    requestStatesByCallback.set(callback, requestState);
  }

  requestStates.set(messageId, requestState);

  promise
    .catch(() => undefined)
    .finally(() => {
      requestStates.delete(messageId);

      if (requestState.callback) {
        requestStatesByCallback.delete(requestState.callback);
      }
    });

  callApiOnMasterTab(payload);

  return promise;
}

function makeRequest(message: OriginPayload) {
  const messageId = generateUniqueId();
  const payload: OriginPayload = {
    messageId,
    ...message,
  };

  const requestState = { messageId } as RequestState;

  // Re-wrap type because of `postMessage`
  const promise = new Promise<MethodResponse<keyof Methods>>((resolve, reject) => {
    Object.assign(requestState, { resolve, reject });
  });

  if ('args' in payload && 'name' in payload && typeof payload.args[1] === 'function') {
    payload.withCallback = true;

    const callback = payload.args.pop() as AnyToVoidFunction;
    requestState.callback = callback;
    requestStatesByCallback.set(callback, requestState);
  }

  requestState.DEBUG_payload = payload;

  requestStates.set(messageId, requestState);

  promise
    .catch(() => undefined)
    .finally(() => {
      requestStates.delete(messageId);

      if (requestState.callback) {
        requestStatesByCallback.delete(requestState.callback);
      }
    });

  postMessageOnTickEnd(payload);

  return promise;
}

function setupHealthCheck() {
  window.addEventListener('focus', () => {
    void ensureWorkerPing();
    // Sometimes a single check is not enough
    setTimeout(() => ensureWorkerPing(), 1000);
  });
}

async function ensureWorkerPing() {
  let isResolved = false;

  try {
    await Promise.race([
      makeRequest({ type: 'ping' }),
      pause(HEALTH_CHECK_TIMEOUT)
        .then(() => (isResolved ? undefined : Promise.reject(new Error('HEALTH_CHECK_TIMEOUT')))),
    ]);
  } catch (err) {
    // eslint-disable-next-line no-console
    console.error(err);

    if (Date.now() - startedAt >= HEALTH_CHECK_MIN_DELAY) {
      worker?.terminate();
      worker = undefined;
      updateCallback({ '@type': 'requestReconnectApi' });
    }
  } finally {
    isResolved = true;
  }
}

function decodeWaveform(encoded5bit: Uint8Array) {
  const bitsCount = encoded5bit.length * 8;
  const valuesCount = Math.floor(bitsCount / 5);
  if (!valuesCount) {
    return [];
  }

  // Read each 5 bit of encoded5bit as 0-31 unsigned char.
  // We count the index of the byte in which the desired 5-bit sequence starts.
  // And then we read a uint16 starting from that byte to guarantee to get all of those 5 bits.
  //
  // BUT! if it is the last byte we have, we're not allowed to read a uint16 starting with it.
  // Because it will be an overflow (we'll access one byte after the available memory).
  // We see, that only the last 5 bits could start in the last available byte and be problematic.
  // So we read in a general way all the entries in a general way except the last one.
  const result = Array(valuesCount);
  const bitsData = encoded5bit;
  for (let i = 0, l = valuesCount - 1; i !== l; ++i) {
    const byteIndex = Math.floor((i * 5) / 8);
    const bitShift = Math.floor((i * 5) % 8);
    const value = bitsData[byteIndex] + (bitsData[byteIndex + 1] << 8);
    result[i] = ((value >> bitShift) & 0x1F);
  }
  const lastByteIndex = Math.floor(((valuesCount - 1) * 5) / 8);
  const lastBitShift = Math.floor(((valuesCount - 1) * 5) % 8);
  const lastValue = bitsData[lastByteIndex] + (bitsData[lastByteIndex + 1] << 8);
  result[valuesCount - 1] = (lastValue >> lastBitShift) & 0x1F;

  return result;
}

function interpolateArray(data: number[], fitCount: number) {
  let peak = 0;
  const newData = new Array<number>(fitCount);
  const springFactor = data.length / fitCount;
  const leftFiller = data[0];
  const rightFiller = data[data.length - 1];
  for (let i = 0; i < fitCount; i++) {
    const idx = Math.floor(i * springFactor);
    const val = ((data[idx - 1] ?? leftFiller) + (data[idx] ?? leftFiller) + (data[idx + 1] ?? rightFiller)) / 3;
    newData[i] = val;
    if (peak < val) {
      peak = val;
    }
  }
  return { data: newData, peak };
}

function requestCodeBlockHighlightRefresh() {
  runLanguageLoadCallbacks();
}

async function highlightCode(text: string, language: string) {
  const lowLang = language.toLowerCase();
  const langCode = getCodeLanguageName(lowLang);
  if (!langCode) return undefined;

  const result = await ensureCodeLanguage(langCode);
  if (!result) return undefined;
  const tree = lowlight.highlight(langCode, text);
  return treeToElements(tree);
}

async function ensureCodeLanguage(language: string) {
  if (lowlight.registered(language)) {
    return true;
  }

  const langCode = getCodeLanguageName(language);
  if (!langCode) {
    return false;
  }

  if (languagePromises.has(langCode)) {
    await languagePromises.get(langCode);
    return true;
  }

  const languagePromise = THIRD_PARTY_LANGUAGES.includes(langCode)
    ? loadThirdPartyLanguage(langCode) : loadFirstPartyLanguage(langCode);
  if (!languagePromise) return false;

  const syntax = await languagePromise;
  lowlight.register(langCode, syntax.default);
  if (langCode === '1c') {
    lowlight.registerAlias('1c', '1с'); // Allow cyrillic
  }
  notifyLanguageLoad();
  return true;
}

function notifyLanguageLoad() {
  runLanguageLoadCallbacks();
}

function loadFirstPartyLanguage(langCode: string) {
  const loadLanguageModule = LANGUAGE_MODULES[`../../node_modules/highlight.js/es/languages/${langCode}.js`];
  if (!loadLanguageModule) return undefined;

  const languagePromise = loadLanguageModule();
  languagePromises.set(langCode, languagePromise);
  return languagePromise;
}

function loadThirdPartyLanguage(langCode: string) {
  if (langCode === 'typelanguage') {
    const langPromise = import('../lib/hljs-tl/typelanguage');
    languagePromises.set(langCode, langPromise);
    return langPromise;
  }
  return undefined;
}

function treeToElements(tree: Element | Root): TeactNode {
  const children = tree.children.map((child) => {
    if (child.type === 'text') {
      return child.value;
    }
    if (child.type === 'element') {
      return treeToElements(child);
    }
    return undefined;
  }).filter(Boolean);

  if (tree.type === 'root') {
    return Teact.createElement('code', { className: 'hljs custom-scroll-x' }, children) as unknown as TeactNode;
  }

  const name = tree.tagName;
  const classNameArray = tree.properties?.className as string[];
  const className = classNameArray?.join(' ');

  return Teact.createElement(name, { className }, children) as unknown as TeactNode;
}

function addMessageToLocalDb(message: GramJs.TypeMessage | GramJs.TypeSponsoredMessage) {
  if (message instanceof GramJs.Message) {
    if (message.media) addMediaToLocalDb(message.media, message);

    if (message.replyTo instanceof GramJs.MessageReplyHeader && message.replyTo.replyMedia) {
      addMediaToLocalDb(message.replyTo.replyMedia, message);
    }
  }

  if (message instanceof GramJs.MessageService && 'photo' in message.action) {
    const photo = addMessageRepairInfo(message.action.photo, message);
    addPhotoToLocalDb(photo);
  }

  if (message instanceof GramJs.SponsoredMessage && message.photo) {
    addPhotoToLocalDb(message.photo);
  }
}

function addWebPageMediaToLocalDb(webPage: GramJs.TypeWebPage) {
  if (webPage instanceof GramJs.WebPage) {
    if (webPage.document) {
      const document = addWebPageRepairInfo(webPage.document, webPage);
      addDocumentToLocalDb(document);
    }
    if (webPage.photo) {
      const photo = addWebPageRepairInfo(webPage.photo, webPage);
      addPhotoToLocalDb(photo);
    }
  }
}

function addMediaToLocalDb(media: GramJs.TypeMessageMedia, context?: MediaRepairContext) {
  if (media instanceof GramJs.MessageMediaDocument && media.document) {
    const document = addMessageRepairInfo(media.document, context);
    addDocumentToLocalDb(document);

    if (media.altDocuments) {
      for (const altDocument of media.altDocuments) {
        const doc = addMessageRepairInfo(altDocument, context);
        addDocumentToLocalDb(doc);
      }
    }
  }

  if (media instanceof GramJs.MessageMediaGame) {
    if (media.game.document) {
      const document = addMessageRepairInfo(media.game.document, context);
      addDocumentToLocalDb(document);
    }

    const photo = addMessageRepairInfo(media.game.photo, context);
    addPhotoToLocalDb(photo);
  }

  if (media instanceof GramJs.MessageMediaPhoto && media.photo) {
    const photo = addMessageRepairInfo(media.photo, context);
    addPhotoToLocalDb(photo);
  }

  if (media instanceof GramJs.MessageMediaInvoice) {
    if (media.photo) {
      const photo = addMessageRepairInfo(media.photo, context);
      addWebDocumentToLocalDb(photo);
    }

    if (media.extendedMedia instanceof GramJs.MessageExtendedMedia) {
      addMediaToLocalDb(media.extendedMedia.media, context);
    }
  }

  if (media instanceof GramJs.MessageMediaPaidMedia) {
    media.extendedMedia.forEach((extendedMedia) => {
      if (extendedMedia instanceof GramJs.MessageExtendedMedia) {
        addMediaToLocalDb(extendedMedia.media, context);
      }
    });
  }

  if (media instanceof GramJs.MessageMediaPoll) {
    if (media.attachedMedia) {
      addMediaToLocalDb(media.attachedMedia, context);
    }
  }
}

function addStoryToLocalDb(story: GramJs.TypeStoryItem, peerId: string) {
  if (!(story instanceof GramJs.StoryItem)) {
    return;
  }

  if (story.media instanceof GramJs.MessageMediaPhoto && story.media.photo) {
    const photo = addStoryRepairInfo(story.media.photo, peerId, story);
    addPhotoToLocalDb(photo);
  }

  if (story.media instanceof GramJs.MessageMediaDocument) {
    if (story.media.document instanceof GramJs.Document) {
      const doc = addStoryRepairInfo(story.media.document, peerId, story);
      addDocumentToLocalDb(doc);
    }

    if (story.media.altDocuments) {
      for (const altDocument of story.media.altDocuments) {
        const doc = addStoryRepairInfo(altDocument, peerId, story);
        addDocumentToLocalDb(doc);
      }
    }
  }
}

function addPhotoToLocalDb(photo: GramJs.TypePhoto) {
  if (photo instanceof GramJs.Photo) {
    localDb.photos[String(photo.id)] = photo;
  }
}

function addDocumentToLocalDb(document: GramJs.TypeDocument & RepairInfo) {
  if (document instanceof GramJs.Document) {
    const id = String(document.id);
    const current = localDb.documents[id];
    if (current && document.accessHash === current.accessHash && document.fileReference === current.fileReference
      && !document.localRepairInfo
    ) {
      return;
    }
    localDb.documents[id] = document;
  }
}

function addStoryRepairInfo<T extends GramJs.TypeDocument | GramJs.TypeWebDocument | GramJs.TypePhoto>(
  media: T, peerId: string, story: GramJs.TypeStoryItem,
): T & RepairInfo {
  if (!(media instanceof GramJs.Document || media instanceof GramJs.Photo)) return media;
  const repairableMedia = media as T & RepairInfo;
  repairableMedia.localRepairInfo = {
    type: 'story',
    peerId,
    id: story.id,
  };
  return repairableMedia;
}

function addMessageRepairInfo<T extends GramJs.TypeDocument | GramJs.TypeWebDocument | GramJs.TypePhoto>(
  media: T, context?: MediaRepairContext,
): T & RepairInfo {
  if (!context?.peerId) return media;
  if (!(media instanceof GramJs.Document || media instanceof GramJs.Photo || media instanceof GramJs.WebDocument)) {
    return media;
  }

  const repairableMedia = media as T & RepairInfo;
  repairableMedia.localRepairInfo = {
    type: 'message',
    peerId: getApiChatIdFromMtpPeer(context.peerId),
    id: context.id,
  };
  return repairableMedia;
}

function addSavedMusicRepairInfo<T extends GramJs.TypeDocument>(
  media: T, peerId: string,
): T & RepairInfo {
  if (!(media instanceof GramJs.Document)) return media;

  const repairableMedia = media as T & RepairInfo;
  repairableMedia.localRepairInfo = {
    type: 'savedMusic',
    peerId,
  };
  return repairableMedia;
}

function addWebPageRepairInfo<T extends GramJs.TypeDocument | GramJs.TypeWebDocument | GramJs.TypePhoto>(
  media: T, webPage?: GramJs.TypeWebPage,
): T & RepairInfo {
  if (!(webPage instanceof GramJs.WebPage)) return media;
  if (!(media instanceof GramJs.Document || media instanceof GramJs.Photo || media instanceof GramJs.WebDocument)) {
    return media;
  }

  const repairableMedia = media as T & RepairInfo;
  repairableMedia.localRepairInfo = {
    type: 'webPage',
    url: webPage.url,
  };
  return repairableMedia;
}

function addChatToLocalDb(
  chat: GramJs.Chat | GramJs.Channel | GramJs.Community,
) {
  const id = buildApiPeerId(chat.id, chat instanceof GramJs.Chat ? 'chat' : 'channel');
  const storedChat = localDb.chats[id];

  const isStoredMin = storedChat && 'min' in storedChat && storedChat.min;
  const isChatMin = 'min' in chat && chat.min;
  if (storedChat && !isStoredMin && isChatMin) return;

  localDb.chats[id] = chat;
}

function addUserToLocalDb(user: GramJs.TypeUser) {
  if (user instanceof GramJs.UserEmpty) return;
  const id = buildApiPeerId(user.id, 'user');
  const storedUser = localDb.users[id];

  if (user.photo instanceof GramJs.Photo) {
    addPhotoToLocalDb(user.photo);
  }

  if (storedUser && !storedUser.min && user.min) return;

  localDb.users[id] = user;
}

function addWebDocumentToLocalDb(webDocument: GramJs.TypeWebDocument) {
  localDb.webDocuments[webDocument.url] = webDocument;
}

function getUnreadIdsKey<TKey extends UnreadCountKey>(unreadCountKey: TKey) {
  return unreadIdsKeyByCountKey[unreadCountKey];
}

function replaceThreadUnreadIds<T extends GlobalState, TKey extends UnreadCountKey>(
  global: T,
  chatId: string,
  threadId: ThreadId,
  unreadCountKey: TKey,
  messageIds: number[] | undefined,
) {
  return replaceThreadReadStateParam(global, chatId, threadId, getUnreadIdsKey(unreadCountKey), messageIds);
}

function replaceThreadUnreadCount<T extends GlobalState, TKey extends UnreadCountKey>(
  global: T,
  chatId: string,
  threadId: ThreadId,
  unreadCountKey: TKey,
  count: number | undefined,
) {
  return replaceThreadReadStateParam(global, chatId, threadId, unreadCountKey, count);
}

function selectThreadUnreadIds<TKey extends UnreadCountKey>(
  readState: ThreadReadState | undefined,
  unreadCountKey: TKey,
) {
  return readState?.[getUnreadIdsKey(unreadCountKey)];
}

function addUnreadCount<T extends GlobalState, TKey extends UnreadCountKey>({
  global,
  chatId,
  messageIds,
  totalCount,
  unreadCountKey,
}: AddUnreadCountArgs<T, TKey>): T {
  const messageIdsByThreadId = groupMessageIdsByThreadId(global, chatId, messageIds, false);

  for (const threadId in messageIdsByThreadId) {
    const threadMessageIds = messageIdsByThreadId[threadId];
    if (totalCount !== undefined) {
      global = replaceThreadUnreadIds(global, chatId, threadId, unreadCountKey, threadMessageIds);
      global = replaceThreadUnreadCount(global, chatId, threadId, unreadCountKey, totalCount);
      continue;
    }

    const readState = selectThreadReadState(global, chatId, threadId);
    const previousIds = selectThreadUnreadIds(readState, unreadCountKey) || [];
    const updatedIds = unique([...previousIds, ...threadMessageIds]).sort((a, b) => b - a);

    global = replaceThreadUnreadIds(global, chatId, threadId, unreadCountKey, updatedIds);

    const delta = updatedIds.length - previousIds.length;
    if (delta > 0) {
      global = replaceThreadUnreadCount(
        global,
        chatId,
        threadId,
        unreadCountKey,
        (readState?.[unreadCountKey] || 0) + delta,
      );
    }
  }

  return global;
}

function removeUnreadCount<T extends GlobalState, TKey extends UnreadCountKey>({
  global,
  chatId,
  messageIds,
  unreadCountKey,
}: RemoveUnreadCountArgs<T, TKey>): T {
  const messageIdsByThreadId = groupMessageIdsByThreadId(global, chatId, messageIds, false);

  for (const threadId in messageIdsByThreadId) {
    const threadMessageIds = messageIdsByThreadId[threadId];
    const threadMessageIdSet = new Set(threadMessageIds);
    const readState = selectThreadReadState(global, chatId, threadId);
    const previousIds = selectThreadUnreadIds(readState, unreadCountKey) || [];
    const updatedIds = previousIds.filter((id) => !threadMessageIdSet.has(id));

    global = replaceThreadUnreadIds(global, chatId, threadId, unreadCountKey, updatedIds);

    const previousCount = readState?.[unreadCountKey];
    const delta = previousIds.length - updatedIds.length;

    if (delta > 0 && previousCount) {
      global = replaceThreadUnreadCount(
        global,
        chatId,
        threadId,
        unreadCountKey,
        Math.max(previousCount - delta, 0),
      );
    }
  }

  return global;
}

function updateUnreadCounters<T extends GlobalState, TKey extends UnreadCountKey>({
  global,
  chatId,
  threadId,
  messages,
  topics,
  totalCount,
  unreadCountKey,
}: UpdateUnreadCountersArgs<T, TKey>): T {
  const messagesById = buildCollectionByKey(messages, 'id');

  global = addChatMessagesById(global, chatId, messagesById);
  topics.forEach((topicState) => {
    global = updateTopicWithState(global, chatId, topicState);
  });

  const messageIds = Object.keys(messagesById).map(Number).sort((a, b) => b - a);
  global = replaceThreadUnreadIds(global, chatId, threadId, unreadCountKey, messageIds);
  global = replaceThreadUnreadCount(global, chatId, threadId, unreadCountKey, totalCount);

  return global;
}

async function createState() {
  const authKeyBytes = Uint8Array.from({ length: AUTH_KEY_LENGTH }, (_, index) => index);
  const authKey = new AuthKey();
  await authKey.setKey(authKeyBytes);

  return {
    authKey,
    authKeyBytes,
    state: new MTProtoState(authKey),
  };
}

async function buildEncryptedPacket(
  state: MTProtoState,
  authKey: AuthKey,
  authKeyBytes: Uint8Array,
  options: EncryptedPacketOptions = {},
) {
  const body = options.body ?? TRUE_BODY;
  const msgId = options.msgId ?? buildMessageId(Math.floor(Date.now() / 1000));
  const seqNo = options.seqNo ?? 1;
  const sessionId = options.sessionId ?? state['id'];
  const declaredBodyLength = options.declaredBodyLength ?? body.length;
  const paddingLength = options.paddingLength ?? 12;
  const plaintext = concat(
    toSignedLittleBuffer(SERVER_SALT, 8),
    toSignedLittleBuffer(sessionId, 8),
    toSignedLittleBuffer(msgId, 8),
    encodeInt32(seqNo),
    encodeInt32(declaredBodyLength),
    body,
    new Uint8Array(paddingLength),
  );
  if (plaintext.length % 16 !== 0) {
    throw new Error('Test packet plaintext must be AES-aligned');
  }

  const msgKeyLarge = await sha256(concat(authKeyBytes.slice(96, 128), plaintext));
  const msgKey = msgKeyLarge.slice(8, 24);
  const { iv, key } = await state._calcKey(authKeyBytes, msgKey, false);
  const encryptedData = new IGE(key, iv).encryptIge(plaintext);

  return concat(
    readBufferFromBigInt(authKey.keyId!, 8),
    msgKey,
    encryptedData,
  );
}

function buildMessageId(timestamp: number, parity = SERVER_MSG_ID_PARITY) {
  return (BigInt(timestamp) << 32n) | parity;
}

function buildContainerReader(innerMessage: Uint8Array) {
  return new BinaryReader(concat(encodeInt32(1), innerMessage));
}

function buildInnerMessage(
  body: Uint8Array,
  declaredBodyLength = body.length,
  msgId = buildMessageId(Math.floor(Date.now() / 1000)),
  seqNo = 1,
) {
  return concat(
    toSignedLittleBuffer(msgId, 8),
    encodeInt32(seqNo),
    encodeInt32(declaredBodyLength),
    body,
  );
}

function encodeInt32(value: number) {
  const buffer = new Uint8Array(4);
  writeInt32LE(buffer, value);
  return buffer;
}

function encodeUint32(value: number) {
  const buffer = new Uint8Array(4);
  writeUint32LE(buffer, value);
  return buffer;
}

