function logDebugMessage(level: DebugLevel, ...args: any[]) {
  DEBUG_LOGS.push({
    level,
    args,
    date: new Date(),
  });
  ORIGINAL_FUNCTIONS[level](...args);
}

function initDebugConsole() {
  DEBUG_LOGS = [];
  DEBUG_LEVELS.forEach((level) => {
    // @ts-ignore
    console[level] = (...args: any[]) => {
      logDebugMessage(level, ...args);
    };
  });
}

function disableDebugConsole() {
  DEBUG_LEVELS.forEach((level) => {
    // @ts-ignore
    console[level] = ORIGINAL_FUNCTIONS[level];
  });
  DEBUG_LOGS = [];
}

function getDebugLogs() {
  return JSON.stringify(DEBUG_LOGS, (key, value) => (typeof value === 'bigint'
    ? value.toString()
    : value));
}

function formatCardExpiry(input: string) {
  input = input.replace(/[^\d]/g, '').slice(0, 4);
  const parts = input.match(/.{1,2}/g);
  if (parts?.[0] && Number(parts[0]) > 12) {
    parts[0] = '12';
  }
  if (parts?.[0] && parts[0].length === 2 && !parts[1]) {
    parts[1] = '';
  }
  return parts ? parts.join('/') : '';
}

function formatCardNumber(input: string) {
  input = input.replace(/[^\d]/g, '');
  const parts = input.match(/.{1,4}/g);
  return parts ? parts.join(' ') : '';
}

function useProfileViewportIds({
  loadMoreMembers,
  loadCommonChats,
  searchMessages,
  loadStories,
  loadStoriesArchive,
  loadMoreGifts,
  loadSavedMusic,
  tabType,
  mediaSearchType,
  groupChatMembers,
  commonChatIds,
  usersById,
  userStatusesById,
  chatsById,
  chatMessages,
  foundIds,
  threadId,
  storyIds,
  giftIds,
  playlistIds,
  pinnedStoryIds,
  archiveStoryIds,
  similarChannels,
  similarBots,
}: {
  loadMoreMembers: AnyToVoidFunction;
  loadCommonChats: AnyToVoidFunction;
  searchMessages: AnyToVoidFunction;
  loadStories: AnyToVoidFunction;
  loadStoriesArchive: AnyToVoidFunction;
  loadMoreGifts: AnyToVoidFunction;
  loadSavedMusic: AnyToVoidFunction;
  tabType: ProfileTabType;
  mediaSearchType?: SharedMediaType;
  groupChatMembers?: ApiChatMember[];
  commonChatIds?: string[];
  usersById?: Record<string, ApiUser>;
  userStatusesById?: Record<string, ApiUserStatus>;
  chatsById?: Record<string, ApiChat>;
  chatMessages?: Record<number, ApiMessage>;
  foundIds?: number[];
  threadId?: ThreadId;
  storyIds?: number[];
  giftIds?: string[];
  playlistIds?: string[];
  pinnedStoryIds?: number[];
  archiveStoryIds?: number[];
  similarChannels?: string[];
  similarBots?: string[];
}) {
  const resultType = mediaSearchType && SHARED_MEDIA_TYPES.includes(tabType as SharedMediaType)
    ? mediaSearchType : tabType;

  const memberIds = useMemo(() => {
    if (!groupChatMembers || !usersById || !userStatusesById) {
      return undefined;
    }

    return sortUserIds(
      groupChatMembers.map(({ userId }) => userId),
      usersById,
      userStatusesById,
    );
  }, [groupChatMembers, usersById, userStatusesById]);

  const chatIds = useMemo(() => {
    if (!commonChatIds || !chatsById) {
      return undefined;
    }

    return sortChatIds(commonChatIds, true);
  }, [chatsById, commonChatIds]);

  const [memberViewportIds, getMoreMembers, noProfileInfoForMembers] = useInfiniteScrollForLoadableItems(
    loadMoreMembers, memberIds,
  );

  const [mediaViewportIds, getMoreMedia, noProfileInfoForMedia] = useInfiniteScrollForSharedMedia(
    'media', resultType, searchMessages, chatMessages, foundIds, threadId,
  );

  const [gifViewportIds, getMoreGifs, noProfileInfoForGifs] = useInfiniteScrollForSharedMedia(
    'gif', resultType, searchMessages, chatMessages, foundIds, threadId,
  );

  const [documentViewportIds, getMoreDocuments, noProfileInfoForDocuments] = useInfiniteScrollForSharedMedia(
    'documents', resultType, searchMessages, chatMessages, foundIds, threadId,
  );

  const [linkViewportIds, getMoreLinks, noProfileInfoForLinks] = useInfiniteScrollForSharedMedia(
    'links', resultType, searchMessages, chatMessages, foundIds, threadId,
  );

  const [audioViewportIds, getMoreAudio, noProfileInfoForAudio] = useInfiniteScrollForSharedMedia(
    'audio', resultType, searchMessages, chatMessages, foundIds, threadId,
  );

  const [voiceViewportIds, getMoreVoices, noProfileInfoForVoices] = useInfiniteScrollForSharedMedia(
    'voice', resultType, searchMessages, chatMessages, foundIds, threadId,
  );

  const [commonChatViewportIds, getMoreCommonChats, noProfileInfoForCommonChats] = useInfiniteScrollForLoadableItems(
    loadCommonChats, chatIds,
  );

  const [savedMusicViewportIds, getMoreSavedMusic, noProfileInfoForSavedMusic] = useInfiniteScrollForLoadableItems(
    loadSavedMusic, playlistIds,
  );

  const sortedStoryIds = useMemo(() => {
    if (!storyIds?.length) return storyIds;
    const pinnedStoryIdsSet = new Set(pinnedStoryIds);
    return storyIds.slice().sort((a, b) => {
      const aIsPinned = pinnedStoryIdsSet.has(a);
      const bIsPinned = pinnedStoryIdsSet.has(b);
      if (aIsPinned && !bIsPinned) return -1;
      if (!aIsPinned && bIsPinned) return 1;
      return b - a;
    });
  }, [storyIds, pinnedStoryIds]);

  const [storyViewportIds, getMoreStories, noProfileInfoForStories] = useInfiniteScrollForLoadableItems(
    loadStories, sortedStoryIds,
  );

  const [
    archiveStoryViewportIds,
    getMoreStoriesArchive,
    noProfileInfoForStoriesArchive,
  ] = useInfiniteScrollForLoadableItems(
    loadStoriesArchive, archiveStoryIds,
  );

  let viewportIds: number[] | string[] | undefined;
  let getMore: AnyToVoidFunction | undefined;
  let noProfileInfo = false;

  switch (resultType) {
    case 'members':
      viewportIds = memberViewportIds;
      getMore = getMoreMembers;
      noProfileInfo = noProfileInfoForMembers;
      break;
    case 'commonChats':
      viewportIds = commonChatViewportIds;
      getMore = getMoreCommonChats;
      noProfileInfo = noProfileInfoForCommonChats;
      break;
    case 'media':
      viewportIds = mediaViewportIds;
      getMore = getMoreMedia;
      noProfileInfo = noProfileInfoForMedia;
      break;
    case 'gif':
      viewportIds = gifViewportIds;
      getMore = getMoreGifs;
      noProfileInfo = noProfileInfoForGifs;
      break;
    case 'documents':
      viewportIds = documentViewportIds;
      getMore = getMoreDocuments;
      noProfileInfo = noProfileInfoForDocuments;
      break;
    case 'links':
      viewportIds = linkViewportIds;
      getMore = getMoreLinks;
      noProfileInfo = noProfileInfoForLinks;
      break;
    case 'audio':
      viewportIds = audioViewportIds;
      getMore = getMoreAudio;
      noProfileInfo = noProfileInfoForAudio;
      break;
    case 'voice':
      viewportIds = voiceViewportIds;
      getMore = getMoreVoices;
      noProfileInfo = noProfileInfoForVoices;
      break;
    case 'playlist':
      viewportIds = savedMusicViewportIds;
      getMore = getMoreSavedMusic;
      noProfileInfo = noProfileInfoForSavedMusic;
      break;
    case 'stories':
      viewportIds = storyViewportIds;
      getMore = getMoreStories;
      noProfileInfo = noProfileInfoForStories;
      break;
    case 'storiesArchive':
      viewportIds = archiveStoryViewportIds;
      getMore = getMoreStoriesArchive;
      noProfileInfo = noProfileInfoForStoriesArchive;
      break;
    case 'similarChannels':
      viewportIds = similarChannels;
      break;
    case 'similarBots':
      viewportIds = similarBots;
      break;
    case 'gifts':
      viewportIds = giftIds;
      getMore = loadMoreGifts;
      break;
    case 'dialogs':
      noProfileInfo = true;
      break;
  }

  return [resultType, viewportIds, getMore, noProfileInfo] as const;
}

function useInfiniteScrollForLoadableItems<ListId extends string | number>(
  handleLoadMore?: AnyToVoidFunction,
  itemIds?: ListId[],
) {
  const [viewportIds, getMore] = useInfiniteScroll(
    handleLoadMore,
    itemIds,
    undefined,
    itemIds?.length || MEMBERS_SLICE,
  );

  const isOnTop = !viewportIds || !itemIds || viewportIds[0] === itemIds[0];

  return [viewportIds, getMore, !isOnTop] as const;
}

function useInfiniteScrollForSharedMedia(
  forSharedMediaType: SharedMediaType,
  currentResultType?: ProfileTabType,
  handleLoadMore?: AnyToVoidFunction,
  chatMessages?: Record<number, ApiMessage>,
  foundIds?: number[],
  threadId?: ThreadId,
) {
  const messageIdsRef = useRef<number[]>();

  useSyncEffect(() => {
    messageIdsRef.current = undefined;
  }, [threadId]);

  useSyncEffect(() => {
    if (currentResultType === forSharedMediaType && chatMessages && foundIds) {
      messageIdsRef.current = getMessageContentIds(
        chatMessages,
        foundIds,
        forSharedMediaType,
      );
    }
  }, [chatMessages, foundIds, currentResultType, forSharedMediaType]);

  const msgLen = messageIdsRef.current?.length ?? 0;
  const listSlice = forSharedMediaType === 'media'
    ? Math.max(SHARED_MEDIA_SLICE, msgLen)
    : Math.max(MESSAGE_SEARCH_SLICE, msgLen);

  const [viewportIds, getMore] = useInfiniteScroll(
    handleLoadMore,
    messageIdsRef.current,
    undefined,
    listSlice,
  );

  const isOnTop = !viewportIds || !messageIdsRef.current || viewportIds[0] === messageIdsRef.current[0];

  return [viewportIds, getMore, !isOnTop] as const;
}

class MessagePacker {
  private _state: MTProtoState;

  public _pendingStates: RequestState[];

  private _queue: (RequestState | undefined)[];

  private _ready: Promise<unknown>;

  setReady: ((value?: any) => void) | undefined;

  private _log: Logger;

  constructor(state: MTProtoState, logger: Logger) {
    this._state = state;
    this._queue = [];
    this._pendingStates = [];
    this._ready = new Promise((resolve) => {
      this.setReady = resolve;
    });
    this._log = logger;
  }

  values() {
    return this._queue;
  }

  clear() {
    this._queue = [];
    this.append(undefined);
  }

  append(state?: RequestState, setReady = true, atStart = false) {
    // We need to check if there is already a `USE_INVOKE_AFTER_WITH` request
    if (state && USE_INVOKE_AFTER_WITH.has(state.request.className)) {
      if (atStart) {
        // Assign `after` for the previously first `USE_INVOKE_AFTER_WITH` request
        for (let i = 0; i < this._queue.length; i++) {
          if (USE_INVOKE_AFTER_WITH.has(this._queue[i]?.request.className)) {
            this._queue[i]!.after = state;
            break;
          }
        }
      } else {
        // Assign after for the previous `USE_INVOKE_AFTER_WITH` request
        for (let i = this._queue.length - 1; i >= 0; i--) {
          if (USE_INVOKE_AFTER_WITH.has(this._queue[i]?.request.className)) {
            state.after = this._queue[i];
            break;
          }
        }
      }
    }

    if (atStart) {
      this._queue.unshift(state);
    } else {
      this._queue.push(state);
    }

    if (setReady) {
      this.setReady?.(true);
    }

    // 1658238041=MsgsAck, we don't care about MsgsAck here because they never resolve anyway.
    if (state && state.request.CONSTRUCTOR_ID !== 1658238041) {
      this._pendingStates.push(state);
      state.promise
      // Using finally causes triggering `unhandledrejection` event
        ?.catch(() => {
        })
        .finally(() => {
          this._pendingStates = this._pendingStates.filter((s) => s !== state);
        });
    }
  }

  prepend(states: RequestState[]) {
    states.reverse().forEach((state) => {
      this.append(state, false, true);
    });

    this.setReady?.(true);
  }

  extend(states: RequestState[]) {
    states.forEach((state) => {
      this.append(state, false);
    });
    this.setReady?.(true);
  }

  getBeacon(state: RequestState) {
    const buffer = new BinaryWriter(new Uint8Array(0));
    const size = state.data.length + TLMessage.SIZE_OVERHEAD;
    if (size <= MessageContainer.MAXIMUM_SIZE) {
      let afterId;
      if (state.after) {
        afterId = state.after.msgId;
      }
      const { msgId, seqNo } = this._state.writeDataAsMessage(
        buffer, state.data, state.isContentRelated, afterId,
      );
      state.msgId = msgId;
      state.seqNo = seqNo;
      this._log.debug(`Assigned msgId = ${state.msgId.toString()} to ${state.request.className
      || state.request.constructor.name}`);

      return buffer.getValue();
    }
    this._log.warn(`Message payload for ${state.request.className
    || state.request.constructor.name} is too long ${state.data.length} and cannot be sent`);
    state.reject?.(new Error('Request Payload is too big'));

    return undefined;
  }

  async wait() {
    if (!this._queue.length) {
      this._ready = new Promise((resolve) => {
        this.setReady = resolve;
      });
      await this._ready;
    }
  }

  get() {
    if (!this._queue[this._queue.length - 1]) {
      this._queue = this._queue.filter(Boolean);
      return undefined;
    }
    let data;
    let buffer = new BinaryWriter(new Uint8Array(0));

    const batch = [];
    let size = 0;

    while (this._queue.length && batch.length <= MessageContainer.MAXIMUM_LENGTH) {
      const state = this._queue.shift();
      if (!state) {
        continue;
      }

      if (state.abortSignal?.aborted) {
        state.reject?.(new Error('Request aborted'));
        continue;
      }

      state.containerId = undefined;
      state.containerSeqNo = undefined;
      size += state.data.length + TLMessage.SIZE_OVERHEAD;
      if (size <= MessageContainer.MAXIMUM_SIZE) {
        let afterId;
        if (state.after) {
          afterId = state.after.msgId;
        }
        const { msgId, seqNo } = this._state.writeDataAsMessage(
          buffer, state.data, state.isContentRelated, afterId,
        );
        state.msgId = msgId;
        state.seqNo = seqNo;
        this._log.debug(`Assigned msgId = ${state.msgId.toString()} to ${state.request.className
        || state.request.constructor.name}`);
        batch.push(state);
        continue;
      }

      if (batch.length) {
        this._queue.unshift(state);
        break;
      }

      this._log.warn(`Message payload for ${state.request.className
      || state.request.constructor.name} is too long ${state.data.length} and cannot be sent`);
      state.reject?.(new Error('Request Payload is too big'));
      size = 0;
    }
    if (!batch.length) {
      return undefined;
    }
    if (batch.length > 1) {
      const b = new Uint8Array(8);
      writeUint32LE(b, MessageContainer.CONSTRUCTOR_ID);
      writeInt32LE(b, batch.length, 4);
      data = concat(b, buffer.getValue());
      buffer = new BinaryWriter(new Uint8Array(0));
      const { msgId: containerId, seqNo: containerSeqNo } = this._state.writeDataAsMessage(
        buffer, data, false,
      );
      for (const s of batch) {
        s.containerId = containerId;
        s.containerSeqNo = containerSeqNo;
      }
    }

    data = buffer.getValue();
    return {
      batch,
      data,
    };
  }
}

