function animateOpening(
  userId: string,
  origin: StoryViewerOrigin,
  thumb: string,
  bestImageData: string | undefined,
  dimensions: IDimensions,
) {
  const { mediaEl: fromImage } = getNodes(origin, userId);
  if (!fromImage) {
    return;
  }
  const { width: windowWidth, height: windowHeight } = windowSize.get();
  let { width: toWidth, height: toHeight } = dimensions;

  const isMobile = windowWidth <= MOBILE_WIDTH;

  if (isMobile) {
    toWidth = windowWidth - 2 * MOBILE_OFFSET;
    toHeight = windowHeight - OFFSET_BOTTOM - 2 * MOBILE_OFFSET;

    const safeAreaBottom = getComputedStyle(document.documentElement).getPropertyValue('--safe-area-bottom');
    if (safeAreaBottom) {
      toHeight -= parseFloat(safeAreaBottom);
    }
  }

  const toLeft = isMobile ? MOBILE_OFFSET : (windowWidth - toWidth) / 2;
  const toTop = isMobile ? MOBILE_OFFSET : (windowHeight - (toHeight + OFFSET_BOTTOM)) / 2;

  const {
    top: fromTop, left: fromLeft, width: fromWidth, height: fromHeight,
  } = fromImage.getBoundingClientRect();

  const fromTranslateX = (fromLeft + fromWidth / 2) - (toLeft + toWidth / 2);
  const fromTranslateY = (fromTop + fromHeight / 2) - (toTop + toHeight / 2);
  const fromScaleX = fromWidth / toWidth;
  const fromScaleY = fromHeight / toHeight;

  requestMutation(() => {
    const ghost = createGhost(bestImageData || thumb, !bestImageData);
    applyStyles(ghost, {
      top: `${toTop}px`,
      left: `${toLeft}px`,
      width: `${toWidth}px`,
      height: `${toHeight}px`,
      transform: `translate3d(${fromTranslateX}px, ${fromTranslateY}px, 0) scale(${fromScaleX}, ${fromScaleY})`,
    });

    const container = document.getElementById('StoryViewer')!;
    container.appendChild(ghost);
    document.body.classList.add('ghost-animating');

    requestMutation(() => {
      applyStyles(ghost, {
        transform: '',
      });

      setTimeout(() => {
        requestMutation(() => {
          if (container.contains(ghost)) {
            container.removeChild(ghost);
          }
          document.body.classList.remove('ghost-animating');
        });
      }, ANIMATION_DURATION + ANIMATION_END_DELAY);
    });
  });
}

function animateClosing(
  userId: string,
  origin: StoryViewerOrigin,
  bestImageData: string,
) {
  const { mediaEl: toImage } = getNodes(origin, userId);

  const fromImage = document.getElementById('StoryViewer')!.querySelector<HTMLImageElement>(
    `.${styles.mobileSlide} .${styles.media}, .${styles.activeSlide} .${styles.media}`,
  );
  if (!fromImage || !toImage) {
    return;
  }
  const {
    top: fromTop, left: fromLeft, width: fromWidth, height: fromHeight,
  } = fromImage.getBoundingClientRect();
  const {
    top: toTop, left: toLeft, width: toWidth, height: toHeight,
  } = toImage.getBoundingClientRect();

  const toTranslateX = (toLeft + toWidth / 2) - (fromLeft + fromWidth / 2);
  const toTranslateY = (toTop + toHeight / 2) - (fromTop + fromHeight / 2);
  const toScaleX = toWidth / fromWidth;
  const toScaleY = toHeight / fromHeight;

  requestMutation(() => {
    const ghost = createGhost(bestImageData);
    applyStyles(ghost, {
      top: `${fromTop}px`,
      left: `${fromLeft}px`,
      width: `${fromWidth}px`,
      height: `${fromHeight}px`,
    });

    const ghost2 = createGhost(toImage.src, undefined, true);
    const ghost2Top = (fromTop + fromHeight / 2) - fromWidth / 2;
    applyStyles(ghost2, {
      top: `${ghost2Top}px`,
      left: `${fromLeft}px`,
      width: `${fromWidth}px`,
      height: `${fromWidth}px`,
    });

    const container = document.getElementById('StoryViewer')!;
    container.appendChild(ghost);
    document.body.appendChild(ghost2);
    document.body.classList.add('ghost-animating');

    requestMutation(() => {
      applyStyles(ghost, {
        transform: `translate3d(${toTranslateX}px, ${toTranslateY}px, 0) scale(${toScaleX}, ${toScaleY})`,
      });

      applyStyles(ghost2, {
        transform: `translate3d(${toTranslateX}px, ${toTranslateY}px, 0) scale(${toScaleX})`,
        opacity: '1',
      });

      setTimeout(() => {
        requestMutation(() => {
          if (container.contains(ghost)) {
            container.removeChild(ghost);
          }

          if (document.body.contains(ghost2)) {
            document.body.removeChild(ghost2);
          }

          document.body.classList.remove('ghost-animating');
        });
      }, ANIMATION_DURATION + ANIMATION_END_DELAY);
    });
  });
}

function createGhost(source: string, hasBlur = false, isGhost2 = false) {
  const ghost = document.createElement('div');
  ghost.classList.add(!isGhost2 ? styles.ghost : styles.ghost2);

  const img = new Image();
  img.draggable = false;
  img.oncontextmenu = stopEvent;
  img.classList.add(styles.ghostImage);

  if (hasBlur) {
    const canvas = document.createElement('canvas');
    canvas.classList.add(styles.thumbnail);
    img.onload = () => {
      const ctx = canvas.getContext('2d', { alpha: false })!;
      const {
        width,
        height,
      } = img;

      requestMutation(() => {
        canvas.width = width;
        canvas.height = height;

        if (IS_CANVAS_FILTER_SUPPORTED) {
          ctx.filter = `blur(${RADIUS}px)`;
        }

        ctx.drawImage(img, -RADIUS * 2, -RADIUS * 2, width + RADIUS * 4, height + RADIUS * 4);

        if (!IS_CANVAS_FILTER_SUPPORTED) {
          fastBlur(ctx, 0, 0, width, height, RADIUS, ITERATIONS);
        }
      });
    };
    img.src = source;
    ghost.appendChild(canvas);
  } else {
    img.src = source;
    ghost.appendChild(img);
  }

  return ghost;
}

function getNodes(origin: StoryViewerOrigin, userId: string) {
  let containerSelector;
  const mediaSelector = `#${getPeerStoryHtmlId(userId)}`;

  switch (origin) {
    case StoryViewerOrigin.StoryRibbon:
      containerSelector = `#LeftColumn .${storyRibbonStyles.root}`;
      break;
    case StoryViewerOrigin.MiddleHeaderAvatar:
      containerSelector = '.MiddleHeader .Transition_slide-active .ChatInfo';
      break;
    case StoryViewerOrigin.ChatList:
      containerSelector = '#LeftColumn .chat-list';
      break;
    case StoryViewerOrigin.SearchResult:
      containerSelector = '#LeftColumn .LeftSearch--container';
      break;
  }

  const container = document.querySelector<HTMLElement>(containerSelector)!;
  const mediaEls = container && container.querySelectorAll<HTMLImageElement>(`${mediaSelector} img`);

  return {
    container,
    mediaEl: mediaEls?.[0],
  };
}

interface ImportedBundles {
  [Bundles.Auth]: typeof import('../bundles/auth');
  [Bundles.Main]: typeof import('../bundles/main');
  [Bundles.Extra]: typeof import('../bundles/extra');
  [Bundles.Calls]: typeof import('../bundles/calls');
  [Bundles.Stars]: typeof import('../bundles/stars');
  [Bundles.Editor]: typeof import('../bundles/editor');
}

async function loadBundle<B extends Bundles>(bundleName: B) {
  if (!LOAD_PROMISES[bundleName]) {
    switch (bundleName) {
      case Bundles.Auth:
        LOAD_PROMISES[Bundles.Auth] = import('../bundles/auth');
        break;
      case Bundles.Main:
        if (DEBUG) {
          // eslint-disable-next-line no-console
          console.log('>>> START LOAD MAIN BUNDLE');
        }

        LOAD_PROMISES[Bundles.Main] = import('../bundles/main');
        break;
      case Bundles.Extra:
        LOAD_PROMISES[Bundles.Extra] = import('../bundles/extra');
        break;
      case Bundles.Calls:
        LOAD_PROMISES[Bundles.Calls] = import('../bundles/calls');
        break;
      case Bundles.Stars:
        LOAD_PROMISES[Bundles.Stars] = import('../bundles/stars');
        break;
      case Bundles.Editor:
        LOAD_PROMISES[Bundles.Editor] = import('../bundles/editor');
        break;
    }

    (LOAD_PROMISES[bundleName]!).then(runCallbacks);
  }

  const bundle = (await LOAD_PROMISES[bundleName]) as unknown as ImportedBundles[B];

  if (!MEMORY_CACHE[bundleName]) {
    MEMORY_CACHE[bundleName] = bundle;
  }

  return bundle;
}

async function loadModule<B extends Bundles>(bundleName: B) {
  await loadBundle(bundleName);
}

function getModuleFromMemory<B extends Bundles, M extends BundleModules<B>>(
  bundleName: B, moduleName: M,
): ImportedBundles[B][M] | undefined {
  const bundle = MEMORY_CACHE[bundleName] as ImportedBundles[B];

  if (!bundle) {
    return undefined;
  }

  return bundle[moduleName];
}

class AuthKey {
  _key?: Uint8Array<ArrayBuffer>;

  _hash?: Uint8Array<ArrayBuffer>;

  private auxHash?: bigint;

  keyId?: bigint;

  constructor(value?: Uint8Array<ArrayBuffer>, hash?: Uint8Array<ArrayBuffer>) {
    if (!hash || !value) {
      return;
    }
    this._key = value;
    this._hash = hash;
    const reader = new BinaryReader(hash);
    this.auxHash = reader.readLong(false);
    reader.read(4);
    this.keyId = reader.readLong(false);
  }

  async setKey(value?: Uint8Array<ArrayBuffer> | AuthKey) {
    if (!value) {
      this._key = undefined;
      this.auxHash = undefined;
      this.keyId = undefined;
      this._hash = undefined;
      return;
    }
    if (value instanceof AuthKey) {
      this._key = value._key;
      this.auxHash = value.auxHash;
      this.keyId = value.keyId;
      this._hash = value._hash;
      return;
    }
    this._key = value;
    this._hash = await sha1(this._key);
    const reader = new BinaryReader(this._hash);
    this.auxHash = reader.readLong(false);
    reader.read(4);
    this.keyId = reader.readLong(false);
  }

  async waitForKey() {
    while (this.keyId === undefined) {
      await sleep(20);
    }
  }

  getKey() {
    return this._key;
  }

  // TODO : This doesn't really fit here, it's only used in authentication

  /**
     * Calculates the new nonce hash based on the current class fields' values
     * @param newNonce
     * @param number
     * @returns {bigint}
     */
  async calcNewNonceHash(
    newNonce: bigint,
    number: number,
  ): Promise<bigint> {
    if (this.auxHash === undefined) {
      throw new Error('Auth key not set');
    }

    const nonce = toSignedLittleBuffer(newNonce, 32);
    const n = new Uint8Array([number]);
    const data = concat(nonce, n, readBufferFromBigInt(this.auxHash, 8, true));

    // Calculates the message key from the given data
    const shaData = (await sha1(data)).slice(4, 20);
    return readBigIntFromBuffer(shaData, true, true);
  }

  equals(other: AuthKey) {
    const otherKey = other.getKey();
    return (
      other instanceof this.constructor
      && this._key
      && otherKey instanceof Uint8Array
      && buffersEqual(otherKey, this._key)
    );
  }
}

