    return convertToLittle(this.ige.encrypt(plainText));
  }

interface LangFnOptionsRegular {
  withNodes?: never;
  withMarkdown?: never;
  pluralValue?: never;
}

interface AdvancedLangFnOptionsRegular {
  withNodes: true;
  withMarkdown?: boolean;
  pluralValue?: never;
  renderTextFilters?: TextFilter[];
  specialReplacement?: Record<string, TeactNode>;
}

function isDeletedLangString(string: LangPackStringValue): string is LangPackStringValueDeleted {
  return typeof string === 'object' && 'isDeleted' in string;
}

function isRegularLangString(string: LangPackStringValue): string is LangPackStringValueRegular {
  return typeof string === 'string';
}

function isPluralLangString(string: LangPackStringValue): string is LangPackStringValuePlural {
  return !isRegularLangString(string) && !isDeletedLangString(string);
}

function isLangFnParam(object: unknown): object is LangFnParameters {
  return Boolean(object) && typeof object === 'object' && 'key' in object! && !('type' in object);
}

function areAdvancedLangFnOptions(
  params: LangFnOptions | AdvancedLangFnOptions,
): params is AdvancedLangFnOptions {
  return 'withNodes' in params && Boolean(params.withNodes);
}

function buildQrPreviewSnapshot(
  wallpaper: QrWallpaperSnapshot, avatar?: HTMLElement, username?: HTMLElement,
): QrPreviewSnapshot {
  return {
    wallpaper,
    username: getUsernameSnapshot(username),
    avatar: getAvatarSnapshot(avatar),
  };
}

async function generateQrCodeCard({
  snapshot, link, gradient,
}: QrCodeCardParams) {
  const blob = await renderQrCodeCard(snapshot, link, gradient);
  if (!blob) {
    throw new Error('QR_PREVIEW_RENDER_FAILED');
  }

  return blob;
}

function logQrRenderError(error: unknown) {
  // eslint-disable-next-line no-console
  console.error('[QrCodeModal] export render failed', formatQrRenderError(error));
}

async function renderQrCodeCard(
  snapshot: QrPreviewSnapshot, url: string, gradient: QrGradientStops,
) {
  const canvas = document.createElement('canvas');
  const ctx = canvas.getContext('2d');
  if (!ctx) {
    return undefined;
  }

  canvas.width = EXPORT_WIDTH * EXPORT_SCALE;
  canvas.height = EXPORT_HEIGHT * EXPORT_SCALE;
  ctx.setTransform(EXPORT_SCALE, 0, 0, EXPORT_SCALE, 0, 0);

  await drawWallpaper(ctx, snapshot.wallpaper, EXPORT_WIDTH, EXPORT_HEIGHT);
  drawCardLayout(ctx, snapshot.username);
  await drawAvatar(ctx, snapshot.avatar);
  await drawQr(ctx, url, gradient);

  const blob = await canvasToBlob(canvas);

  return blob;
}

function getUsernameSnapshot(username?: HTMLElement): UsernameSnapshot | undefined {
  const text = username?.textContent;
  if (!username || !text) return undefined;

  const style = getComputedStyle(username);
  return {
    text,
    style: {
      backgroundImage: style.backgroundImage,
      color: style.color,
      fontFamily: style.fontFamily,
      fontSize: style.fontSize,
      fontWeight: style.fontWeight,
      letterSpacing: style.letterSpacing,
      lineHeight: style.lineHeight,
    },
  };
}

function getAvatarSnapshot(avatar?: HTMLElement): AvatarSnapshot | undefined {
  if (!avatar) return undefined;

  const imageEl = avatar.querySelector<HTMLImageElement>('img');
  const inner = avatar.firstElementChild as HTMLElement | undefined;
  const backgroundStyle = inner ? getComputedStyle(inner) : getComputedStyle(avatar);
  const textStyle = getComputedStyle(avatar);
  const text = avatar.textContent?.trim();

  return {
    backgroundColor: backgroundStyle.backgroundColor,
    backgroundImage: backgroundStyle.backgroundImage,
    color: textStyle.color,
    fontFamily: textStyle.fontFamily,
    fontSize: textStyle.fontSize,
    fontWeight: textStyle.fontWeight,
    size: avatar.offsetWidth,
    imageSrc: imageEl?.src,
    text,
  };
}

async function drawWallpaper(
  ctx: CanvasRenderingContext2D,
  snapshot: QrWallpaperSnapshot,
  width: number,
  height: number,
) {
  const { model, resourceUrl, fallbackColor } = snapshot;
  ctx.fillStyle = model.baseColor || fallbackColor;
  ctx.fillRect(0, 0, width, height);

  if (model.isImage && resourceUrl) {
    await drawBackgroundImage(ctx, resourceUrl, model.isBlurred, width, height);
  }

  const gradientCanvas = !model.isImage && model.colors.length >= 2
    ? createGradientCanvas(model)
    : undefined;
  const patternUrl = model.isDefault ? defaultPatternUrl : resourceUrl;
  const patternOpacity = Math.abs(model.patternIntensity || 0) / 100;

  if (gradientCanvas && !model.isMaskedPattern) {
    ctx.drawImage(gradientCanvas, 0, 0, width, height);
  }

  if (model.isPattern && patternUrl) {
    if (model.isMaskedPattern && gradientCanvas) {
      await drawMaskedPattern(ctx, patternUrl, gradientCanvas, patternOpacity, width, height);
    } else {
      await drawOverlayPattern(ctx, patternUrl, patternOpacity, width, height);
    }
  }
}

async function drawBackgroundImage(
  ctx: CanvasRenderingContext2D,
  imageUrl: string,
  isBlurred: boolean,
  width: number,
  height: number,
) {
  const image = await loadImage(imageUrl).catch(() => undefined);
  if (!image) return;

  ctx.save();
  ctx.translate(width / 2, height / 2);
  ctx.scale(WALLPAPER_IMAGE_SCALE, WALLPAPER_IMAGE_SCALE);
  ctx.translate(-width / 2, -height / 2);
  if (isBlurred) ctx.filter = `blur(${WALLPAPER_BLUR_PX}px)`;
  drawImageCover(ctx, image, 0, 0, width, height);
  ctx.restore();
}

function createGradientCanvas(model: WallpaperRenderModel) {
  const canvas = document.createElement('canvas');
  renderStaticGradient(canvas, model.colors, model.backgroundRotation);
  return canvas;
}

async function drawMaskedPattern(
  ctx: CanvasRenderingContext2D,
  patternUrl: string,
  gradientCanvas: HTMLCanvasElement,
  opacity: number,
  width: number,
  height: number,
) {
  const maskImage = await loadImage(patternUrl).catch(() => undefined);
  if (!maskImage) return;
  const patternCanvas = createMaskedPatternCanvas(maskImage, gradientCanvas, width, height);
  if (!patternCanvas) return;

  ctx.save();
  ctx.globalAlpha = opacity;
  ctx.drawImage(patternCanvas, 0, 0, width, height);
  ctx.restore();
}

async function drawOverlayPattern(
  ctx: CanvasRenderingContext2D,
  patternUrl: string,
  opacity: number,
  width: number,
  height: number,
) {
  const image = await loadImage(patternUrl).catch(() => undefined);
  if (!image) return;

  const patternCanvas = createPatternCanvas(image, width, height);
  if (!patternCanvas) return;

  ctx.save();
  ctx.globalAlpha = opacity;
  ctx.globalCompositeOperation = 'soft-light';
  ctx.drawImage(patternCanvas, 0, 0, width, height);
  ctx.restore();
}

function createPatternCanvas(image: HTMLImageElement, width: number, height: number) {
  const patternCanvas = document.createElement('canvas');
  const patternCtx = patternCanvas.getContext('2d');
  if (!patternCtx) return undefined;

  const bitmapWidth = width * EXPORT_SCALE;
  const bitmapHeight = height * EXPORT_SCALE;
  patternCanvas.width = bitmapWidth;
  patternCanvas.height = bitmapHeight;

  if (!fillScaledPattern(patternCtx, image, bitmapWidth, bitmapHeight)) return undefined;

  return patternCanvas;
}

function createMaskedPatternCanvas(
  image: HTMLImageElement,
  gradientImage: CanvasImageSource,
  width: number,
  height: number,
) {
  const patternCanvas = document.createElement('canvas');
  const patternCtx = patternCanvas.getContext('2d');
  if (!patternCtx) return undefined;

  const bitmapWidth = width * EXPORT_SCALE;
  const bitmapHeight = height * EXPORT_SCALE;
  patternCanvas.width = bitmapWidth;
  patternCanvas.height = bitmapHeight;

  patternCtx.drawImage(gradientImage, 0, 0, bitmapWidth, bitmapHeight);

  patternCtx.globalCompositeOperation = 'destination-in';
  if (!fillScaledPattern(patternCtx, image, bitmapWidth, bitmapHeight)) return undefined;

  return patternCanvas;
}

function fillScaledPattern(ctx: CanvasRenderingContext2D, image: HTMLImageElement, width: number, height: number) {
  const pattern = createScaledPattern(ctx, image, PATTERN_SIZE * EXPORT_SCALE);
  if (!pattern) return false;

  ctx.fillStyle = pattern;
  ctx.fillRect(0, 0, width, height);
  return true;
}

function createScaledPattern(ctx: CanvasRenderingContext2D, image: HTMLImageElement, patternSize = PATTERN_SIZE) {
  const sourceWidth = image.naturalWidth || image.width;
  const sourceHeight = image.naturalHeight || image.height;
  const patternHeight = sourceWidth && sourceHeight
    ? Math.max(1, Math.round(patternSize * (sourceHeight / sourceWidth)))
    : patternSize;
  const patternCanvas = document.createElement('canvas');
  patternCanvas.width = patternSize;
  patternCanvas.height = patternHeight;

  const patternCtx = patternCanvas.getContext('2d')!;
  patternCtx.drawImage(image, 0, 0, patternSize, patternHeight);

  return ctx.createPattern(patternCanvas, 'repeat');
}

function drawCardLayout(ctx: CanvasRenderingContext2D, username: UsernameSnapshot | undefined) {
  drawCard(ctx);
  drawUsername(ctx, username);
}

function drawCard(ctx: CanvasRenderingContext2D) {
  ctx.save();
  ctx.fillStyle = WHITE_COLOR;
  addRoundRect(ctx, EXPORT_CARD_X, EXPORT_CARD_Y, EXPORT_CARD_WIDTH, EXPORT_CARD_HEIGHT, EXPORT_CARD_RADIUS);
  ctx.fill();
  ctx.restore();
}

function drawUsername(ctx: CanvasRenderingContext2D, username: UsernameSnapshot | undefined) {
  if (!username) return;

  const { text, style } = username;
  const qrInsetX = (EXPORT_CARD_WIDTH - EXPORT_QR_SIZE) / 2;
  const maxWidth = EXPORT_CARD_WIDTH - Math.floor(qrInsetX * 1.2);
  const fontSize = getFittedFontSize(ctx, text, style, maxWidth);
  const fittedText = getFittedText(ctx, text, maxWidth);
  const textWidth = Math.min(ctx.measureText(fittedText).width, maxWidth);

  ctx.save();
  ctx.font = `${style.fontWeight} ${fontSize}px ${style.fontFamily}`;
  ctx.textAlign = 'center';
  ctx.textBaseline = 'top';
  ctx.fillStyle = getUsernameFillStyle(
    ctx,
    style,
    EXPORT_WIDTH / 2 - textWidth / 2,
    EXPORT_WIDTH / 2 + textWidth / 2,
    fontSize,
  );
  ctx.fillText(fittedText, EXPORT_WIDTH / 2, EXPORT_USERNAME_Y);
  ctx.restore();
}

function getUsernameFillStyle(
  ctx: CanvasRenderingContext2D,
  style: UsernameStyleSnapshot,
  x1: number,
  x2: number,
  fontSize: number,
) {
  const colors = getCssColors(style.backgroundImage);
  const firstColor = colors[0];
  const lastColor = colors[colors.length - 1];
  if (firstColor && lastColor) {
    const gradient = ctx.createLinearGradient(
      x1,
      EXPORT_USERNAME_Y,
      x2,
      EXPORT_USERNAME_Y + fontSize,
    );
    gradient.addColorStop(0, firstColor);
    gradient.addColorStop(1, lastColor);
    return gradient;
  }

  return style.color || FALLBACK_ACCENT_COLOR;
}

async function drawAvatar(ctx: CanvasRenderingContext2D, avatar: AvatarSnapshot | undefined) {
  if (!avatar) return;
  const rect = new DOMRect(
    EXPORT_AVATAR_X - EXPORT_AVATAR_RADIUS,
    EXPORT_AVATAR_Y - EXPORT_AVATAR_RADIUS,
    EXPORT_AVATAR_SIZE,
    EXPORT_AVATAR_SIZE,
  );

  ctx.save();
  ctx.fillStyle = WHITE_COLOR;
  ctx.beginPath();
  ctx.arc(EXPORT_AVATAR_X, EXPORT_AVATAR_Y, EXPORT_AVATAR_RADIUS + AVATAR_RING_WIDTH, 0, Math.PI * 2);
  ctx.fill();
  ctx.restore();

  ctx.save();
  ctx.beginPath();
  ctx.arc(EXPORT_AVATAR_X, EXPORT_AVATAR_Y, EXPORT_AVATAR_RADIUS, 0, Math.PI * 2);
  ctx.clip();

  if (avatar.imageSrc) {
    const image = await loadImage(avatar.imageSrc).catch(() => undefined);
    if (image) {
      drawImageCover(ctx, image, rect.x, rect.y, rect.width, rect.height);
    } else {
      drawAvatarFallback(ctx, avatar, rect);
    }
  } else {
    drawAvatarFallback(ctx, avatar, rect);
  }

  ctx.restore();
}

function drawAvatarFallback(ctx: CanvasRenderingContext2D, avatar: AvatarSnapshot, rect: DOMRect) {
  const colors = getCssColors(avatar.backgroundImage);
  const firstColor = colors[0];
  const lastColor = colors[colors.length - 1];
  if (firstColor && lastColor) {
    const gradient = ctx.createLinearGradient(rect.x, rect.y, rect.x, rect.y + rect.height);
    gradient.addColorStop(0, firstColor);
    gradient.addColorStop(1, lastColor);
    ctx.fillStyle = gradient;
  } else {
    ctx.fillStyle = avatar.backgroundColor || FALLBACK_ACCENT_COLOR;
  }
  ctx.fillRect(rect.x, rect.y, rect.width, rect.height);

  const text = avatar.text;
  if (!text) return;

  const fontSize = getScaledAvatarFontSize(avatar, rect.width);
  ctx.fillStyle = avatar.color || WHITE_COLOR;
  ctx.font = `${avatar.fontWeight} ${fontSize}px ${avatar.fontFamily}`;
  ctx.textAlign = 'center';
  ctx.textBaseline = 'middle';
  ctx.fillText(text, rect.x + rect.width / 2, rect.y + rect.height / 2);
}

async function drawQr(
  ctx: CanvasRenderingContext2D,
  url: string,
  gradient: QrGradientStops,
) {
  const qrLogoUrl = createQrLogoUrl(gradient);

  try {
    const exportQrCode = await createStyledQrCode({
      size: EXPORT_QR_SIZE * EXPORT_SCALE,
      gradient,
      image: qrLogoUrl,
    });
    exportQrCode.update({ data: url });
    const qrBlob = await exportQrCode.getRawData('png');
    if (!qrBlob) {
      throw new Error('QR_RASTERIZATION_FAILED');
    }

    const qrUrl = URL.createObjectURL(qrBlob);
    try {
      const image = await loadImage(qrUrl);
      ctx.drawImage(image, EXPORT_QR_X, EXPORT_QR_Y, EXPORT_QR_SIZE, EXPORT_QR_SIZE);
    } finally {
      URL.revokeObjectURL(qrUrl);
    }
  } finally {
    URL.revokeObjectURL(qrLogoUrl);
  }
}

function createQrLogoUrl(gradient: QrGradientStops) {
  const logoSvgElement = jsxToHtml(
    <svg xmlns="http://www.w3.org/2000/svg" viewBox={`0 0 ${QR_LOGO_SIZE} ${QR_LOGO_SIZE}`}>
      <defs>
        <linearGradient
          id="qrLogoGradient"
          x1="0"
          y1="0"
          x2={QR_LOGO_SIZE}
          y2={QR_LOGO_SIZE}
          gradientUnits="userSpaceOnUse"
        >
          <stop offset="0" style={`stop-color: ${gradient.from}`} />
          <stop offset="1" style={`stop-color: ${gradient.to}`} />
        </linearGradient>
      </defs>
      <path fillRule="evenodd" clipRule="evenodd" fill="url(#qrLogoGradient)" d={QR_LOGO_PATH} />
    </svg>,
  )[0];

  return URL.createObjectURL(new Blob([logoSvgElement.outerHTML], { type: SVG_MIME_TYPE }));
}

function getFittedFontSize(
  ctx: CanvasRenderingContext2D, text: string, style: UsernameStyleSnapshot, maxWidth: number,
) {
  let fontSize = parseFloat(style.fontSize || '0');
  while (fontSize > USERNAME_MIN_FONT_SIZE) {
    ctx.font = `${style.fontWeight} ${fontSize}px ${style.fontFamily}`;
    if (ctx.measureText(text).width <= maxWidth) {
      return fontSize;
    }
    fontSize -= 1;
  }
  ctx.font = `${style.fontWeight} ${USERNAME_MIN_FONT_SIZE}px ${style.fontFamily}`;
  return USERNAME_MIN_FONT_SIZE;
}

function getScaledAvatarFontSize(avatar: AvatarSnapshot, exportSize: number) {
  const fontSize = parseFloat(avatar.fontSize || '0');
  if (!Number.isFinite(fontSize)) {
    return exportSize / AVATAR_FONT_SIZE_RATIO_FALLBACK;
  }

  if (!avatar.size) {
    return fontSize;
  }

  return fontSize * (exportSize / avatar.size);
}

function getFittedText(ctx: CanvasRenderingContext2D, text: string, maxWidth: number) {
  if (ctx.measureText(text).width <= maxWidth) {
    return text;
  }

  const ellipsis = '...';
  let result = text;
  while (result && ctx.measureText(`${result}${ellipsis}`).width > maxWidth) {
    result = result.slice(0, -1);
  }
  return `${result}${ellipsis}`;
}

function drawImageCover(
  ctx: CanvasRenderingContext2D,
  image: HTMLImageElement | HTMLCanvasElement,
  x: number,
  y: number,
  width: number,
  height: number,
) {
  const sourceWidth = 'naturalWidth' in image ? image.naturalWidth : image.width;
  const sourceHeight = 'naturalHeight' in image ? image.naturalHeight : image.height;
  const sourceRatio = sourceWidth / sourceHeight;
  const targetRatio = width / height;
  let sourceX = 0;
  let sourceY = 0;
  let cropWidth = sourceWidth;
  let cropHeight = sourceHeight;

  if (sourceRatio > targetRatio) {
    cropWidth = sourceHeight * targetRatio;
    sourceX = (sourceWidth - cropWidth) / 2;
  } else if (sourceRatio < targetRatio) {
    cropHeight = sourceWidth / targetRatio;
    sourceY = (sourceHeight - cropHeight) / 2;
  }

  ctx.drawImage(image, sourceX, sourceY, cropWidth, cropHeight, x, y, width, height);
}

function addRoundRect(
  ctx: CanvasRenderingContext2D, x: number, y: number, width: number, height: number, radius: number,
) {
  const normalizedRadius = Math.min(radius, width / 2, height / 2);
  ctx.beginPath();
  ctx.moveTo(x + normalizedRadius, y);
  ctx.lineTo(x + width - normalizedRadius, y);
  ctx.quadraticCurveTo(x + width, y, x + width, y + normalizedRadius);
  ctx.lineTo(x + width, y + height - normalizedRadius);
  ctx.quadraticCurveTo(x + width, y + height, x + width - normalizedRadius, y + height);
  ctx.lineTo(x + normalizedRadius, y + height);
  ctx.quadraticCurveTo(x, y + height, x, y + height - normalizedRadius);
  ctx.lineTo(x, y + normalizedRadius);
  ctx.quadraticCurveTo(x, y, x + normalizedRadius, y);
  ctx.closePath();
}

function getCssColors(value: string) {
  return value.match(/rgba?\([^)]+\)|#[0-9a-fA-F]{3,8}/g) || [];
}

function loadImage(src: string) {
  return new Promise<HTMLImageElement>((resolve, reject) => {
    const image = new Image();
    image.crossOrigin = 'anonymous';
    image.onload = () => resolve(image);
    image.onerror = reject;
    image.src = src;
  });
}

function canvasToBlob(canvas: HTMLCanvasElement) {
  return new Promise<Blob | undefined>((resolve, reject) => {
    try {
      canvas.toBlob((blob) => resolve(blob || undefined), QR_CODE_CARD_MIME_TYPE);
    } catch (err) {
      reject(err);
    }
  });
}

function formatQrRenderError(error: unknown) {
  return error instanceof Error ? {
    name: error.name,
    message: error.message,
    stack: error.stack,
  } : error;
}

function useDebouncedMemo<R, D extends unknown[]>(
  resolverFn: () => R, ms: number, dependencies: D,
): R | undefined {
  const [value, setValue] = useState<R>();
  const { isFrozen, updateWhenUnfrozen } = useHeavyAnimationFreeze();
  const runDebounced = useRunDebounced(ms, true);

  useSyncEffect(() => {
    if (isFrozen) {
      updateWhenUnfrozen();
      return;
    }

    runDebounced(() => {
      setValue(resolverFn());
    });
  // eslint-disable-next-line react-hooks-static-deps/exhaustive-deps
  }, [...dependencies, isFrozen]);

  return value;
}

function useHeavyAnimationFreeze() {
  const isPendingRef = useRef(false);

  const updateWhenUnfrozen = useCallback(() => {
    isPendingRef.current = true;
  }, []);

  const forceUpdate = useForceUpdate();
  const handleUnfreeze = useCallback(() => {
    if (!isPendingRef.current) {
      return;
    }

    isPendingRef.current = false;
    forceUpdate();
  }, [forceUpdate]);
  useHeavyAnimation(noop, handleUnfreeze);

  return {
    isFrozen: getIsHeavyAnimating(),
    updateWhenUnfrozen,
  };
}

function getMessageIdsForSelectedText(range: Range) {
  const selectedFragments = range.cloneContents();

  const shouldIncludeLastMessage = range.endOffset > 0
    && hasParentWithClassName(range.endContainer, MESSAGE_CONTENT_CLASS_NAME);
  if (selectedFragments.childElementCount === 0) {
    return undefined;
  }

  const messageIds = Array.from(selectedFragments.children)
    .reduce((result, node) => {
      if (node.nodeType === ELEMENT_NODE && node.classList.contains('message-date-group')) {
        return Array.from(node.querySelectorAll('.Message'))
          .reduce((acc, messageEl) => acc.concat(Number((messageEl as HTMLElement).dataset.messageId)), result);
      } else if (node.nodeType === ELEMENT_NODE && node.classList.contains('Message')) {
        return result.concat(Number((node as HTMLElement).dataset.messageId));
      }

      return result;
    }, [] as number[]);

  // Cleanup a document fragment because it is playing media content in the background
  while (selectedFragments.firstChild) {
    selectedFragments.removeChild(selectedFragments.firstChild);
  }

  if (!shouldIncludeLastMessage) {
    messageIds.pop();
  }

  return messageIds;
}

function hasParentWithClassName(element: Node, className: string): boolean {
  if (element.nodeType === ELEMENT_NODE && (element as HTMLElement).classList.contains(className)) {
    return true;
  }

  return element.parentNode ? hasParentWithClassName(element.parentNode, className) : false;
}

function updateTopPeerCategory<T extends GlobalState>(
  global: T,
  category: ApiTopPeerCategory,
  categoryState: NonNullable<GlobalState['topPeerCategories'][ApiTopPeerCategory]>,
): T {
  return {
    ...global,
    topPeerCategories: {
      ...global.topPeerCategories,
      [category]: categoryState,
    },
  };
}

function getMessageSummaryText(
  lang: LangFn,
  message: ApiMessage,
  statefulContent: StatefulMediaContent | undefined,
  noEmoji = false,
  truncateLength = TRUNCATED_SUMMARY_LENGTH,
  isExtended = false,
) {
  const emoji = !noEmoji && getMessageSummaryEmoji(message);
  const emojiWithSpace = emoji ? `${emoji} ` : '';
  const text = trimText(getMessageTextWithSpoilers(lang, message, statefulContent, truncateLength), truncateLength);
  const description = getMessageSummaryDescription(lang, message, statefulContent, text, isExtended);
  const descriptionText = getSummaryDescriptionText(message, statefulContent, description, truncateLength);

  return `${emojiWithSpace}${descriptionText}`;
}

function getMessageTextWithSpoilers(
  lang: LangFn,
  message: ApiMessage,
  statefulContent: StatefulMediaContent | undefined,
  truncateLength?: number,
) {
  const transcription = getMessageTranscription(message);

  const richMessageText = message.content.richMessage
    ? getRichMessagePreviewText(message.content.richMessage, truncateLength)
    : undefined;
  const textWithoutTranscription = richMessageText
    || getMessageTextWithFallback(lang, statefulContent?.story || message)?.text;
  if (!textWithoutTranscription) {
    return transcription;
  }

  const { entities } = message.content.text || {};
  if (richMessageText || !entities?.length) {
    return transcription ? `${transcription}\n${textWithoutTranscription}` : textWithoutTranscription;
  }

  const text = entities.reduce((accText, {
    type,
    offset,
    length,
  }) => {
    if (type !== ApiMessageEntityTypes.Spoiler) {
      return accText;
    }

    const spoiler = generateBrailleSpoiler(length);

    return `${accText.slice(0, offset)}${spoiler}${accText.slice(offset + length)}`;
  }, textWithoutTranscription);

  return transcription ? `${transcription}\n${text}` : text;
}

function getMessageSummaryEmoji(message: ApiMessage) {
  const {
    photo,
    video,
    audio,
    voice,
    document,
    sticker,
    pollId,
    paidMedia,
    todo,
  } = message.content;

  if (message.groupedId || photo || paidMedia) {
    return '🖼';
  }

  if (video) {
    return '📹';
  }

  if (sticker) {
    return sticker.emoji;
  }

  if (audio) {
    return '🎧';
  }

  if (voice) {
    return '🎤';
  }

  if (document) {
    return '📎';
  }

  if (pollId) {
    return '📊';
  }

  if (todo) {
    return '📝';
  }

  return undefined;
}

function getMediaContentTypeDescription(
  lang: LangFn, content: MediaContent, statefulContent: StatefulMediaContent | undefined,
) {
  return getSummaryDescription(lang, content, statefulContent);
}

function getMessageSummaryDescription(
  lang: LangFn,
  message: ApiMessage,
  statefulContent: StatefulMediaContent | undefined,
  truncatedText?: string | TeactNode,
  isExtended = false,
) {
  return getSummaryDescription(lang, message.content, statefulContent, message, truncatedText, isExtended);
}

function getSummaryDescription(
  lang: LangFn,
  mediaContent: MediaContent,
  statefulContent: StatefulMediaContent | undefined,
  message?: ApiMessage,
  truncatedText?: string | TeactNode,
  isExtended = false,
) {
  const {
    text,
    photo,
    video,
    audio,
    voice,
    document,
    sticker,
    contact,
    invoice,
    location,
    game,
    storyData,
    giveaway,
    giveawayResults,
    paidMedia,
    todo,
    dice,
    richMessage,
  } = mediaContent;
  const { poll } = statefulContent || {};

  let hasUsedTruncatedText = false;
  let summary: TeactNode | undefined;

  const boughtExtendedMedia = paidMedia?.isBought && paidMedia.extendedMedia;
  const previewExtendedMedia = paidMedia && !paidMedia.isBought
    ? paidMedia.extendedMedia as ApiMediaExtendedPreview[] : undefined;

  const isPaidMediaAlbum = paidMedia && paidMedia.extendedMedia.length > 1;
  const isPaidMediaSingleVideo = !isPaidMediaAlbum
    && (boughtExtendedMedia?.[0].video || previewExtendedMedia?.[0].duration);
  const isPaidMediaSinglePhoto = !isPaidMediaAlbum && !isPaidMediaSingleVideo;

  if (message?.groupedId || isPaidMediaAlbum) {
    hasUsedTruncatedText = true;
    summary = truncatedText || lang('Album');
  }

  if (photo || isPaidMediaSinglePhoto) {
    hasUsedTruncatedText = true;
    summary = truncatedText || lang('AttachPhoto');
  }

  if (video || isPaidMediaSingleVideo) {
    hasUsedTruncatedText = true;
    summary = truncatedText || lang(video?.isGif ? 'AttachGif' : 'AttachVideo');
  }

  if (sticker) {
    summary = lang('AttachSticker').trim();
  }

  if (audio) {
    summary = getMessageAudioCaption(mediaContent) || lang('AttachMusic');
  }

  if (voice) {
    hasUsedTruncatedText = true;
    summary = truncatedText || lang('AttachAudio');
  }

  if (document) {
    hasUsedTruncatedText = !isExtended;
    summary = isExtended ? document.fileName : (truncatedText || document.fileName);
  }

  if (contact) {
    summary = lang('AttachContact');
  }

  if (poll) {
    summary = renderTextWithEntities({
      text: poll.summary.question.text,
      entities: poll.summary.question.entities,
      asPreview: true,
    });
  }

  if (invoice) {
    summary = invoice.extendedMedia ? invoice.title : lang('AttachInvoice', { description: invoice.description });
  }

  if (text) {
    if (isExtended && summary && !hasUsedTruncatedText) {
      (summary as string) += `\n${truncatedText as string}`;
    } else {
      summary = truncatedText as string;
    }
  }

  if (location?.mediaType === 'geo' || location?.mediaType === 'venue') {
    summary = lang('AttachLocation');
  }

  if (location?.mediaType === 'geoLive') {
    summary = lang('AttachLiveLocation');
  }

  if (game) {
    summary = `🎮 ${game.title}`;
  }

  if (giveaway) {
    summary = lang('AttachGiveaway');
  }

  if (giveawayResults) {
    summary = lang('AttachGiveawayResults');
  }

  if (storyData) {
    summary = truncatedText || lang('AttachStory');
  }

  if (todo) {
    summary = renderTextWithEntities({
      text: todo.todo.title.text,
      entities: todo.todo.title.entities,
      asPreview: true,
    });
  }

  if (dice) {
    summary = dice.emoticon;
  }

  if (richMessage) {
    summary = truncatedText as string;
  }

  return summary || lang('MessageUnsupported');
}

function generateBrailleSpoiler(length: number) {
  return new Array(length)
    .fill(undefined)
    .map(() => SPOILER_CHARS[Math.floor(Math.random() * SPOILER_CHARS.length)])
    .join('');
}

function getMessageAudioCaption(mediaContent: MediaContent) {
  const {
    audio,
    text,
  } = mediaContent;

  return (audio && [audio.title, audio.performer].filter(Boolean)
    .join(' — ')) || (text?.text);
}

function getSummaryDescriptionText(
  message: ApiMessage,
  statefulContent: StatefulMediaContent | undefined,
  description: TeactNode,
  truncateLength: number,
): string {
  const { todo } = message.content;
  const { poll } = statefulContent || {};

  if (todo) {
    return trimText(getFormattedTextWithSpoilers(todo.todo.title), truncateLength);
  }

  if (poll) {
    return trimText(getFormattedTextWithSpoilers(poll.summary.question), truncateLength);
  }

  if (Array.isArray(description)) {
    return description.map((part) => {
      return getSummaryDescriptionText(message, statefulContent, part, truncateLength);
    }).join('');
  }

  return typeof description === 'string' || typeof description === 'number' ? String(description) : '';
}

function getFormattedTextWithSpoilers(formattedText: ApiFormattedText) {
  const { text, entities } = formattedText;

  if (!entities?.length) {
    return text;
  }

  return entities.reduce((accText, {
    type,
    offset,
    length,
  }) => {
    if (type !== ApiMessageEntityTypes.Spoiler) {
      return accText;
    }

    const spoiler = generateBrailleSpoiler(length);

    return `${accText.slice(0, offset)}${spoiler}${accText.slice(offset + length)}`;
  }, text);
}

function buildMessageContent(
  mtpMessage: UniversalMessage | GramJs.UpdateServiceNotification,
) {
  let content: MediaContent = {};

  if (mtpMessage.media) {
    const repairContext = 'peerId' in mtpMessage ? mtpMessage : undefined;
    content = {
      ...buildMessageMediaContent(mtpMessage.media, repairContext),
    };
  }

  const richMessage = 'richMessage' in mtpMessage && mtpMessage.richMessage
    ? buildApiRichMessage(mtpMessage.richMessage, 'peerId' in mtpMessage ? mtpMessage : undefined)
    : undefined;
  if (richMessage) {
    content = {
      ...content,
      richMessage,
    };
  }

  const hasUnsupportedMedia = mtpMessage.media instanceof GramJs.MessageMediaUnsupported;

  if (!richMessage && mtpMessage.message && !hasUnsupportedMedia
    && !content.sticker && !content.todo && !content.contact && !content.video?.isRound) {
    const text = buildMessageTextContent(mtpMessage.message, mtpMessage.entities);
    const textWithTimestamps = addTimestampEntities(text);
    content = {
      ...content,
      text: textWithTimestamps,
    };
  }

  return content;
}

function buildApiRichMessage(
  richMessage: GramJs.RichMessage,
  context?: MediaRepairContext,
): ApiRichMessage | undefined {
  if (!(richMessage instanceof GramJs.RichMessage)) {
    return undefined;
  }

  const {
    blocks, photos, documents, rtl, part,
  } = richMessage;
  const pageMediaContext = buildApiPageMediaContext(photos, documents, { message: context });

  return {
    blocks: blocks.map((block) => buildApiPageBlock(block, pageMediaContext)),
    isRtl: rtl,
    isPart: part,
    partCutoff: part ? blocks.length : undefined,
  };
}

function buildMessageTextContent(
  message: string,
  entities?: GramJs.TypeMessageEntity[],
): ApiFormattedText {
  return {
    text: message,
    ...(entities && { entities: entities.map(buildApiMessageEntity) }),
  };
}

function buildMessageMediaContent(
  media: GramJs.TypeMessageMedia, context?: MediaRepairContext,
): MediaContent | undefined {
  addMediaToLocalDb(media, context);

  const ttlSeconds = 'ttlSeconds' in media ? media.ttlSeconds : undefined;

  const isExpiredVoice = isExpiredVoiceMessage(media);
  if (isExpiredVoice) {
    return {
      action: {
        mediaType: 'action',
        type: 'expired',
        isVoice: true,
      },
    };
  }
  const isExpiredRoundVideo = isExpiredRoundVideoMessage(media);
  if (isExpiredRoundVideo) {
    return {
      action: {
        mediaType: 'action',
        type: 'expired',
        isRoundVideo: true,
      },
    };
  }

  const voice = buildVoice(media);
  if (voice) return { voice, ttlSeconds };

  if ('round' in media && media.round) {
    const video = buildVideo(media);
    if (video) return { video, ttlSeconds };
  }

  // Other disappearing media types are not supported
  if (ttlSeconds !== undefined) {
    return undefined;
  }

  if (media instanceof GramJs.MessageMediaInvoice && media.extendedMedia instanceof GramJs.MessageExtendedMedia) {
    return buildMessageMediaContent(media.extendedMedia.media, context);
  }

  const sticker = buildSticker(media);
  if (sticker) return { sticker };

  const photo = buildPhoto(media);
  if (photo) return { photo };

  const video = buildVideo(media);
  if (video) return { video };

  const audio = buildAudio(media);
  if (audio) return { audio };

  const document = buildDocumentFromMedia(media);
  if (document) return { document };

  const contact = buildContact(media);
  if (contact) return { contact };

  const pollId = buildPollIdFromMedia(media);
  if (pollId) return { pollId };

  const todo = buildTodoFromMedia(media);
  if (todo) return { todo };

  const webPage = buildMessageWebPageFromMedia(media);
  if (webPage) return { webPage };

  const invoice = buildInvoiceFromMedia(media);
  if (invoice) return { invoice };

  const location = buildLocationFromMedia(media);
  if (location) return { location };

  const game = buildGameFromMedia(media);
  if (game) return { game };

  const dice = buildDiceFromMedia(media);
  if (dice) return { dice };

  const storyData = buildMessageStoryData(media);
  if (storyData) return { storyData };

  const giveaway = buildGiveawayFromMedia(media);
  if (giveaway) return { giveaway };

  const giveawayResults = buildGiveawayResultsFromMedia(media);
  if (giveawayResults) return { giveawayResults };

  const paidMedia = buildPaidMedia(media);
  if (paidMedia) return { paidMedia };

  return undefined;
}

function buildSticker(media: GramJs.TypeMessageMedia): ApiSticker | undefined {
  if (
    !(media instanceof GramJs.MessageMediaDocument)
    || !media.document
    || !(media.document instanceof GramJs.Document)
  ) {
    return undefined;
  }

  return buildStickerFromDocument(media.document, media.nopremium);
}

function buildPhoto(media: GramJs.TypeMessageMedia): ApiPhoto | undefined {
  if (!(media instanceof GramJs.MessageMediaPhoto) || !media.photo || !(media.photo instanceof GramJs.Photo)) {
    return undefined;
  }

  return buildApiPhoto(media.photo, media.spoiler);
}

function buildVideoFromDocument(document: GramJs.Document, altDocuments?: GramJs.TypeDocument[], params?: {
  isSpoiler?: boolean;
  timestamp?: number;
}): ApiVideo | undefined {
  return buildApiVideoFromDocument(document, altDocuments, params);
}

function buildAudioFromDocument(document: GramJs.Document): ApiAudio | undefined {
  return buildApiAudioFromDocument(document, true);
}

function buildVideo(media: GramJs.TypeMessageMedia): ApiVideo | undefined {
  if (
    !(media instanceof GramJs.MessageMediaDocument)
    || !(media.document instanceof GramJs.Document)
    || !media.document.mimeType.startsWith('video')
  ) {
    return undefined;
  }

  return buildVideoFromDocument(
    media.document,
    media.altDocuments,
    { isSpoiler: media.spoiler, timestamp: media.videoTimestamp },
  );
}

function buildAudio(media: GramJs.TypeMessageMedia): ApiAudio | undefined {
  if (
    !(media instanceof GramJs.MessageMediaDocument)
    || !media.document
    || !(media.document instanceof GramJs.Document)
  ) {
    return undefined;
  }

  return buildApiAudioFromDocument(media.document);
}

function isExpiredVoiceMessage(media: GramJs.TypeMessageMedia): boolean {
  if (!(media instanceof GramJs.MessageMediaDocument)) {
    return false;
  }
  return Boolean(!media.document && media.voice);
}

function isExpiredRoundVideoMessage(media: GramJs.TypeMessageMedia): boolean {
  if (!(media instanceof GramJs.MessageMediaDocument)) {
    return false;
  }
  return Boolean(!media.document && media.round);
}

function buildVoice(media: GramJs.TypeMessageMedia): ApiVoice | undefined {
  if (
    !(media instanceof GramJs.MessageMediaDocument)
    || !media.document
    || !(media.document instanceof GramJs.Document)
  ) {
    return undefined;
  }

  return buildApiVoiceFromDocument(media.document);
}

function buildDocumentFromMedia(media: GramJs.TypeMessageMedia) {
  if (!(media instanceof GramJs.MessageMediaDocument) || !media.document) {
    return undefined;
  }

  return buildApiDocument(media.document);
}

function buildContact(media: GramJs.TypeMessageMedia): ApiContact | undefined {
  if (!(media instanceof GramJs.MessageMediaContact)) {
    return undefined;
  }

  const {
    firstName, lastName, phoneNumber, userId,
  } = media;

  return {
    mediaType: 'contact',
    firstName,
    lastName,
    phoneNumber,
    userId: buildApiPeerId(userId, 'user'),
  };
}

function buildPollIdFromMedia(media: GramJs.TypeMessageMedia): string | undefined {
  if (!(media instanceof GramJs.MessageMediaPoll)) {
    return undefined;
  }

  return media.poll.id.toString();
}

function buildMessagePollFromMedia(media: GramJs.TypeMessageMedia): ApiMessagePoll | undefined {
  if (!(media instanceof GramJs.MessageMediaPoll)) {
    return undefined;
  }

  return buildMessagePoll(media);
}

function buildWebPagesFromMedia(media: GramJs.TypeMessageMedia): ApiWebPage[] | undefined {
  const webPages: ApiWebPage[] = [];

  addWebPageFromMedia(webPages, media);

  if (media instanceof GramJs.MessageMediaPoll) {
    if (media.attachedMedia) {
      addWebPageFromMedia(webPages, media.attachedMedia);
    }
    addWebPagesFromPoll(webPages, media.poll, media.results);
  }

  return webPages.length ? webPages : undefined;
}

function buildWebPagesFromPoll(
  poll?: GramJs.Poll,
  pollResults?: GramJs.PollResults,
): ApiWebPage[] | undefined {
  const webPages: ApiWebPage[] = [];

  addWebPagesFromPoll(webPages, poll, pollResults);

  return webPages.length ? webPages : undefined;
}

function buildTodoFromMedia(media: GramJs.TypeMessageMedia): ApiMediaTodo | undefined {
  if (!(media instanceof GramJs.MessageMediaToDo)) {
    return undefined;
  }

  return buildTodo(media.todo, media.completions);
}

function buildInvoiceFromMedia(media: GramJs.TypeMessageMedia): ApiMediaInvoice | undefined {
  if (!(media instanceof GramJs.MessageMediaInvoice)) {
    return undefined;
  }

  return buildMediaInvoice(media);
}

function buildLocationFromMedia(media: GramJs.TypeMessageMedia): ApiLocation | undefined {
  if (media instanceof GramJs.MessageMediaGeo) {
    return buildGeo(media);
  }

  if (media instanceof GramJs.MessageMediaVenue) {
    return buildVenue(media);
  }

  if (media instanceof GramJs.MessageMediaGeoLive) {
    return buildGeoLive(media);
  }

  return undefined;
}

function buildGeo(media: GramJs.MessageMediaGeo): ApiLocation | undefined {
  const point = buildGeoPoint(media.geo);
  return point && { mediaType: 'geo', geo: point };
}

function buildVenue(media: GramJs.MessageMediaVenue): ApiLocation | undefined {
  const {
    geo, title, provider, address, venueId, venueType,
  } = media;
  const point = buildGeoPoint(geo);
  return point && {
    mediaType: 'venue',
    geo: point,
    title,
    provider,
    address,
    venueId,
    venueType,
  };
}

function buildGeoLive(media: GramJs.MessageMediaGeoLive): ApiLocation | undefined {
  const { geo, period, heading } = media;
  const point = buildGeoPoint(geo);
  return point && {
    mediaType: 'geoLive',
    geo: point,
    period,
    heading,
  };
}

function buildGeoPoint(geo: GramJs.TypeGeoPoint): ApiLocation['geo'] | undefined {
  if (geo instanceof GramJs.GeoPointEmpty) return undefined;
  const {
    long, lat, accuracyRadius, accessHash,
  } = geo;
  return {
    long,
    lat,
    accessHash: accessHash.toString(),
    accuracyRadius,
  };
}

function buildGameFromMedia(media: GramJs.TypeMessageMedia): ApiGame | undefined {
  if (!(media instanceof GramJs.MessageMediaGame)) {
    return undefined;
  }

  return buildGame(media);
}

function buildGame(media: GramJs.MessageMediaGame): ApiGame | undefined {
  const {
    id, accessHash, shortName, title, description, photo: apiPhoto, document: apiDocument,
  } = media.game;

  const photo = apiPhoto instanceof GramJs.Photo ? buildApiPhoto(apiPhoto) : undefined;
  const document = apiDocument instanceof GramJs.Document ? buildApiDocument(apiDocument) : undefined;

  return {
    mediaType: 'game',
    id: id.toString(),
    accessHash: accessHash.toString(),
    shortName,
    title,
    description,
    photo,
    document,
  };
}

function buildDiceFromMedia(media: GramJs.TypeMessageMedia): ApiDice | undefined {
  if (!(media instanceof GramJs.MessageMediaDice)) {
    return undefined;
  }

  return buildDice(media);
}

function buildDice(media: GramJs.MessageMediaDice): ApiDice | undefined {
  const { value, emoticon } = media;
  return {
    mediaType: 'dice',
    value,
    emoticon,
  };
}

function buildGiveawayFromMedia(media: GramJs.TypeMessageMedia): ApiGiveaway | undefined {
  if (!(media instanceof GramJs.MessageMediaGiveaway)) {
    return undefined;
  }

  return buildGiveaway(media);
}

function buildGiveaway(media: GramJs.MessageMediaGiveaway): ApiGiveaway | undefined {
  const {
    channels, months, stars, quantity, untilDate, countriesIso2, onlyNewSubscribers, prizeDescription,
  } = media;

  const channelIds = channels.map((channel) => buildApiPeerId(channel, 'channel'));

  return {
    mediaType: 'giveaway',
    channelIds,
    months,
    stars: toJSNumber(stars),
    quantity,
    untilDate,
    countries: countriesIso2,
    isOnlyForNewSubscribers: onlyNewSubscribers,
    prizeDescription,
  };
}

function buildGiveawayResultsFromMedia(media: GramJs.TypeMessageMedia): ApiGiveawayResults | undefined {
  if (!(media instanceof GramJs.MessageMediaGiveawayResults)) {
    return undefined;
  }

  return buildGiveawayResults(media);
}

function buildGiveawayResults(media: GramJs.MessageMediaGiveawayResults): ApiGiveawayResults | undefined {
  const {
    months, untilDate, onlyNewSubscribers, launchMsgId, unclaimedCount, winners, winnersCount,
    additionalPeersCount, prizeDescription, refunded, channelId,
  } = media;

  const winnerIds = winners.map((winner) => buildApiPeerId(winner, 'user'));

  return {
    mediaType: 'giveawayResults',
    months,
    untilDate,
    isOnlyForNewSubscribers: onlyNewSubscribers,
    launchMessageId: launchMsgId,
    channelId: buildApiPeerId(channelId, 'channel'),
    unclaimedCount,
    additionalPeersCount,
    isRefunded: refunded,
    prizeDescription,
    winnerIds,
    winnersCount,
  };
}

function buildMessageStoryData(media: GramJs.TypeMessageMedia): ApiMessageStoryData | undefined {
  if (!(media instanceof GramJs.MessageMediaStory)) {
    return undefined;
  }

  const peerId = getApiChatIdFromMtpPeer(media.peer);

  return {
    mediaType: 'storyData',
    id: media.id,
    peerId,
    ...(media.viaMention && { isMention: true }),
  };
}

function buildMessagePoll(media: GramJs.MessageMediaPoll): ApiMessagePoll {
  const { poll, results, attachedMedia } = media;

  return {
    mediaType: 'poll',
    summary: buildPoll(poll),
    results: buildPollResults(results),
    attachedMedia: attachedMedia ? buildMessageMediaContent(attachedMedia) : undefined,
  };
}

function buildPollAnswer(answer: GramJs.TypePollAnswer): ApiPollAnswer | undefined {
  if (!(answer instanceof GramJs.PollAnswer)) return undefined;
  const { text, option, media, addedBy, date } = answer;

  return {
    text: buildApiFormattedText(text),
    option: serializeBytes(option),
    media: media ? buildMessageMediaContent(media) : undefined,
    addedByPeerId: addedBy ? getApiChatIdFromMtpPeer(addedBy) : undefined,
    date,
  };
}

function buildPoll(poll: GramJs.Poll): ApiPoll {
  const {
    id, closed, publicVoters, multipleChoice, quiz, closePeriod, closeDate, answers, question, creator,
    hideResultsUntilClose, revotingDisabled, shuffleAnswers, openAnswers, subscribersOnly, countriesIso2, hash,
  } = poll;
  const apiAnswers = answers.map(buildPollAnswer).filter(Boolean);

  return {
    id: id.toString(),
    isClosed: closed,
    isPublic: publicVoters,
    isMultipleChoice: multipleChoice,
    isQuiz: quiz,
    closePeriod,
    closeDate,
    isCreator: creator,
    shouldHideResultsUntilClose: hideResultsUntilClose,
    isRevoteDisabled: revotingDisabled,
    shouldShuffleAnswers: shuffleAnswers,
    isRestrictedToSubscribers: subscribersOnly,
    allowedCountryCodes: countriesIso2,
    question: buildApiFormattedText(question),
    answers: apiAnswers,
    hash: hash.toString(),
    canAddAnswers: openAnswers,
  };
}

function addWebPagesFromPoll(
  webPages: ApiWebPage[],
  poll?: GramJs.Poll,
  pollResults?: GramJs.PollResults,
) {
  poll?.answers.forEach((answer) => {
    if (!(answer instanceof GramJs.PollAnswer) || !answer.media) {
      return;
    }

    addWebPageFromMedia(webPages, answer.media);
  });

  if (pollResults?.solutionMedia) {
    addWebPageFromMedia(webPages, pollResults.solutionMedia);
  }
}

function addWebPageFromMedia(webPages: ApiWebPage[], media: GramJs.TypeMessageMedia) {
  const webPage = buildWebPageFromMedia(media);
  if (!webPage) return;

  webPages.push(webPage);
}

function buildTodoItem(item: GramJs.TodoItem): ApiTodoItem {
  return {
    id: item.id,
    title: buildApiFormattedText(item.title),
  };
}

function buildTodo(todo: GramJs.TodoList, completions?: GramJs.TodoCompletion[]): ApiMediaTodo {
  const { title, list: items } = todo;

  const todoItems = items.map(buildTodoItem);

  const todoCompletions = completions?.map((completion) => ({
    itemId: completion.id,
    completedBy: getApiChatIdFromMtpPeer(completion.completedBy),
    completedAt: completion.date,
  }));

  return {
    mediaType: 'todo',
    todo: {
      title: buildApiFormattedText(title),
      items: todoItems,
      othersCanAppend: todo.othersCanAppend,
      othersCanComplete: todo.othersCanComplete,
    },
    completions: todoCompletions,
  };
}

function buildMediaInvoice(media: GramJs.MessageMediaInvoice): ApiMediaInvoice {
  const {
    description, title, photo, test, totalAmount, currency, receiptMsgId, extendedMedia,
  } = media;

  const preview = extendedMedia instanceof GramJs.MessageExtendedMediaPreview
    ? buildApiMessageExtendedMediaPreview(extendedMedia) : undefined;

  return {
    mediaType: 'invoice',
    title,
    description,
    photo: buildApiWebDocument(photo),
    receiptMessageId: receiptMsgId,
    amount: toJSNumber(totalAmount),
    currency,
    isTest: test,
    extendedMedia: preview,
  };
}

function buildPollResults(pollResults: GramJs.PollResults): ApiPollResults {
  const {
    results: rawResults, totalVoters, recentVoters, solution, solutionEntities: entities, min, solutionMedia,
  } = pollResults;
  const results = rawResults?.map(({
    option, chosen, correct, voters, recentVoters: recentAnswerVoters,
  }) => ({
    isChosen: chosen,
    isCorrect: correct,
    option: serializeBytes(option),
    votersCount: voters ?? 0,
    recentVoterIds: recentAnswerVoters?.map((peer) => getApiChatIdFromMtpPeer(peer)),
  }));

  if (solutionMedia) {
    addMediaToLocalDb(solutionMedia);
  }

  return {
    isMin: min,
    totalVoters,
    recentVoterIds: recentVoters?.map((peer) => getApiChatIdFromMtpPeer(peer)),
    resultByOption: results && buildCollectionByKey(results, 'option'),
    solution,
    solutionEntities: entities?.map(buildApiMessageEntity),
    solutionMedia: solutionMedia ? buildMessageMediaContent(solutionMedia) : undefined,
  };
}

function buildMessageWebPageFromMedia(media: GramJs.TypeMessageMedia): ApiMessageWebPage | undefined {
  if (!(media instanceof GramJs.MessageMediaWebPage) || media.webpage instanceof GramJs.WebPageNotModified) {
    return undefined;
  }
  const {
    webpage, forceLargeMedia, forceSmallMedia, safe,
  } = media;

  return {
    id: webpage.id.toString(),
    isSafe: safe,
    mediaSize: forceSmallMedia ? 'small' : forceLargeMedia ? 'large' : undefined,
  };
}

function buildWebPageFromMedia(media: GramJs.TypeMessageMedia): ApiWebPage | undefined {
  if (!(media instanceof GramJs.MessageMediaWebPage)) {
    return undefined;
  }
  const {
    webpage,
  } = media;

  return buildWebPage(webpage);
}

function buildWebPage(webPage: GramJs.TypeWebPage): ApiWebPage | undefined {
  addWebPageMediaToLocalDb(webPage);

  if (webPage instanceof GramJs.WebPageEmpty) {
    return {
      mediaType: 'webpage',
      webpageType: 'empty',
      id: webPage.id.toString(),
      url: webPage.url,
    };
  }

  if (webPage instanceof GramJs.WebPagePending) {
    return {
      mediaType: 'webpage',
      webpageType: 'pending',
      id: webPage.id.toString(),
      url: webPage.url,
    };
  }

  if (webPage instanceof GramJs.WebPage) {
    const {
      id, photo, document, attributes, cachedPage,
    } = webPage;

    const video = document instanceof GramJs.Document ? buildVideoFromDocument(document) : undefined;
    const audio = document instanceof GramJs.Document ? buildAudioFromDocument(document) : undefined;

    let story: ApiWebPageStoryData | undefined;
    let gift: ApiStarGiftUnique | undefined;
    let auction: ApiWebPageAuctionData | undefined;
    let stickers: ApiWebPageStickerData | undefined;
    const attributeStory = attributes
      ?.find((a): a is GramJs.WebPageAttributeStory => a instanceof GramJs.WebPageAttributeStory);
    const attributeGift = attributes
      ?.find((a): a is GramJs.WebPageAttributeUniqueStarGift => a instanceof GramJs.WebPageAttributeUniqueStarGift);
    const attributeAuction = attributes
      ?.find((a): a is GramJs.WebPageAttributeStarGiftAuction => (
        a instanceof GramJs.WebPageAttributeStarGiftAuction
      ));
    if (attributeStory) {
      const peerId = getApiChatIdFromMtpPeer(attributeStory.peer);
      story = {
        id: attributeStory.id,
        peerId,
      };

      if (attributeStory.story instanceof GramJs.StoryItem) {
        addStoryToLocalDb(attributeStory.story, peerId);
      }
    }
    if (attributeGift) {
      const starGift = buildApiStarGift(attributeGift.gift);
      gift = starGift.type === 'starGiftUnique' ? starGift : undefined;
    }
    if (attributeAuction) {
      const starGift = buildApiStarGift(attributeAuction.gift);
      if (starGift.type === 'starGift') {
        auction = {
          gift: starGift,
          endDate: attributeAuction.endDate,
        };
      }
    }
    const attributeStickers = attributes?.find((a): a is GramJs.WebPageAttributeStickerSet => (
      a instanceof GramJs.WebPageAttributeStickerSet
    ));
    if (attributeStickers) {
      stickers = {
        documents: processStickerResult(attributeStickers.stickers),
        isEmoji: attributeStickers.emojis,
        isWithTextColor: attributeStickers.textColor,
      };
    }

    const attributeAiTone = attributes?.find((a): a is GramJs.WebPageAttributeAiComposeTone => (
      a instanceof GramJs.WebPageAttributeAiComposeTone
    ));

    return {
      mediaType: 'webpage',
      webpageType: 'full',
      id: id.toString(),
      ...pick(webPage, [
        'url',
        'displayUrl',
        'type',
        'siteName',
        'title',
        'description',
        'duration',
        'hash',
        'hasLargeMedia',
      ]),
      photo: photo instanceof GramJs.Photo ? buildApiPhoto(photo) : undefined,
      document: !video && !audio && document ? buildApiDocument(document) : undefined,
      video,
      audio,
      story,
      gift,
      auction,
      stickers,
      cachedPage: cachedPage instanceof GramJs.Page ? buildApiInstantViewPage(cachedPage, webPage) : undefined,
      aiComposeToneEmojiId: attributeAiTone?.emojiId.toString(),
    };
  }

  return undefined;
}

function buildPaidMedia(media: GramJs.TypeMessageMedia): ApiPaidMedia | undefined {
  if (!(media instanceof GramJs.MessageMediaPaidMedia)) {
    return undefined;
  }

  const { starsAmount, extendedMedia } = media;

  const isBought = extendedMedia[0] instanceof GramJs.MessageExtendedMedia;

  if (isBought) {
    return {
      mediaType: 'paidMedia',
      starsAmount: toJSNumber(starsAmount),
      isBought,
      extendedMedia: buildBoughtMediaContent(extendedMedia)!,
    };
  }

  return {
    mediaType: 'paidMedia',
    starsAmount: toJSNumber(starsAmount),
    extendedMedia: extendedMedia
      .filter((paidMedia): paidMedia is GramJs.MessageExtendedMediaPreview => (
        paidMedia instanceof GramJs.MessageExtendedMediaPreview
      ))
      .map((paidMedia) => buildApiMessageExtendedMediaPreview(paidMedia)),
  };
}

function buildApiMessageExtendedMediaPreview(
  preview: GramJs.MessageExtendedMediaPreview,
): ApiMediaExtendedPreview {
  const {
    w, h, thumb, videoDuration,
  } = preview;

  return {
    mediaType: 'extendedMediaPreview',
    width: w,
    height: h,
    duration: videoDuration,
    thumbnail: thumb ? buildApiThumbnailFromStripped([thumb]) : undefined,
  };
}

function buildApiWebDocument(document?: GramJs.TypeWebDocument): ApiWebDocument | undefined {
  if (!document) return undefined;

  const {
    url, size, mimeType,
  } = document;
  const accessHash = document instanceof GramJs.WebDocument ? document.accessHash.toString() : undefined;
  const sizeAttr = document.attributes.find((attr): attr is GramJs.DocumentAttributeImageSize => (
    attr instanceof GramJs.DocumentAttributeImageSize
  ));
  const dimensions = sizeAttr && { width: sizeAttr.w, height: sizeAttr.h };

  return {
    mediaType: 'webDocument',
    url,
    accessHash,
    size,
    mimeType,
    dimensions,
  };
}

function buildBoughtMediaContent(
  media: GramJs.TypeMessageExtendedMedia[],
): BoughtPaidMedia[] | undefined {
  const boughtMedia = media
    .filter((m): m is GramJs.MessageExtendedMedia => m instanceof GramJs.MessageExtendedMedia)
    .map((m) => buildMessageMediaContent(m.media))
    .filter(Boolean);

  if (!boughtMedia.length) {
    return undefined;
  }

  return boughtMedia;
}

