  isInProfile?: boolean;
  isEdited?: boolean;
  isForCloseFriends?: boolean;
  isForContacts?: boolean;
  isForSelectedContacts?: boolean;
  isPublic?: boolean;
  isOut?: true;
  noForwards?: boolean;
  views?: ApiStoryViews;
  visibility?: ApiPrivacySettings;
  sentReaction?: ApiReaction;
