async function readFallbackStrings(): Promise<CachedLangData> {
  const file = await import('../../assets/localization/fallback.strings?raw');
  return buildFallbackStrings(file.default);
}

function buildFallbackStrings(fileData: string): CachedLangData {
  const rawStrings = readStrings(fileData);

  const strings: LangPack['strings'] = {};

  Object.entries(rawStrings).forEach(([key, value]) => {
    const [clearKey, pluralSuffix] = key.split('_');

    if (!pluralSuffix) {
      strings[clearKey] = value;
      return;
    }

    const knownValue = (strings[clearKey] || {}) as LangPackStringValuePlural;
    knownValue[pluralSuffix as keyof LangPackStringValuePlural] = value;
    strings[clearKey] = knownValue;
  });

  const langPack: LangPack = {
    langCode: FALLBACK_LANG_CODE,
    version: FALLBACK_VERSION,
    strings,
  };

  const stringsCount = Object.keys(strings).length;

  const language: ApiLanguage = {
    langCode: FALLBACK_LANG_CODE,
    name: 'English',
    nativeName: 'English',
    pluralCode: FALLBACK_LANG_CODE,
    stringsCount,
    translatedCount: stringsCount,
    translationsUrl: FALLBACK_TRANSLATE_URL,
  };

  return {
    langPack,
    language,
  };
}

function usePeerColor({
  peer,
  color,
  noUserColors,
  shouldReset,
  theme,
}: {
  peer?: ApiPeer | CustomPeer;
  color?: ApiTypePeerColor;
  noUserColors?: boolean;
  shouldReset?: boolean;
  theme: ThemeKey;
}): PeerColorProperties {
  const propertiesRef = useRef<PeerColorAttributes>({});
  const realPeer = peer && !('isCustomPeer' in peer) ? peer : undefined;

  useSyncEffect(() => {
    if (!peer) {
      if (!shouldReset) {
        propertiesRef.current = {};
        return;
      }

      propertiesRef.current = {
        className: noUserColors ? getPeerColorCountClass(1) : getPeerColorClass(0),
      };
      return;
    }

    if ('isCustomPeer' in peer) {
      if (peer.peerColorId === undefined) {
        propertiesRef.current = {};
        return;
      }

      propertiesRef.current = { className: `peer-color-${peer.peerColorId}`, style: undefined };
      return;
    }

    const peerColor = color || peer.color;
    const isCollectible = peerColor?.type === 'collectible';
    const colorCount = peer ? getPeerColorCount(peer)
      : isCollectible ? getPeerColorCollectibleColorCount(peerColor) : 1;
    const colorCountClass = getPeerColorCountClass(colorCount);
    const key = (isCollectible || !peerColor?.color) ? getPeerColorKey(peer) : peerColor.color;

    if (noUserColors) {
      propertiesRef.current = { className: colorCountClass };
      return;
    }

    if (peerColor?.type === 'collectible' && !noUserColors) {
      const accentColor = theme === 'dark' && peerColor.darkAccentColor
        ? peerColor.darkAccentColor : peerColor.accentColor;
      const colors = theme === 'dark' && peerColor.darkColors ? peerColor.darkColors : peerColor.colors;
      const gradient = generatePeerColorGradient(colors);
      const { bg, bgActive } = generateColorVariations(accentColor);
      propertiesRef.current = {
        className: colorCountClass,
        style: buildStyle(
          `--bar-gradient: ${gradient}`,
          `--accent-color: ${accentColor}`,
          `--accent-background-color: ${bg}`,
          `--accent-background-active-color: ${bgActive}`,
        ),
      };
      return;
    }

    const className = (noUserColors || key === undefined) ? colorCountClass : getPeerColorClass(key);
    propertiesRef.current = { className, style: undefined };
  }, [noUserColors, shouldReset, theme, color, peer]);

  return {
    style: propertiesRef.current.style,
    className: propertiesRef.current.className,
    backgroundEmojiId: realPeer?.color?.backgroundEmojiId,
    giftEmojiId: realPeer?.color?.type === 'collectible' ? realPeer.color.giftEmojiId : undefined,
  };
}

function getPeerColorClass(colorIndex: number) {
  return `peer-color-${colorIndex}`;
}

function getPeerColorCountClass(colorCount: number) {
  return `peer-color-count-${colorCount}`;
}

function getVisibilityValue(setting?: ApiPrivacySettings) {
    if (!setting) return oldLang('Loading');

    const { visibility, shouldAllowPremium, botsPrivacy } = setting;

    const isAllowBots = botsPrivacy === 'allow';
    const isVisibilityEverybody = visibility === 'everybody';
    const shouldShowBotsString = isAllowBots && !isVisibilityEverybody;

    const blockCount = setting.blockChatIds.length + setting.blockUserIds.length;
    const allowCount = setting.allowChatIds.length + setting.allowUserIds.length;
    const total = [];
    if (blockCount) total.push(`-${blockCount}`);
    if (allowCount && !isVisibilityEverybody) total.push(`+${allowCount}`);

    const botPrivacyString = shouldShowBotsString ? lang('PrivacyValueBots') : '';
    const totalString = lang.conjunction(total);

    const exceptionString = [botPrivacyString, totalString].filter(Boolean).join(' ');
    if (shouldShowBotsString && !isVisibilityEverybody) return exceptionString;

    if (shouldAllowPremium) {
      return oldLang(exceptionString ? 'ContactsAndPremium' : 'PrivacyPremium');
    }

    switch (visibility) {
      case 'everybody':
        return `${oldLang('P2PEverybody')} ${exceptionString}`;

      case 'contacts':
        return `${oldLang('P2PContacts')} ${exceptionString}`;

      case 'nobody':
        return `${oldLang('P2PNobody')} ${exceptionString}`;
    }

    return undefined;
  }

