function withCache<T extends AnyFunction>(fn: T) {
  return (...args: Parameters<T>): ReturnType<T> => {
    let fnCache = cache.get(fn);
    const cacheKey = args.map(String).join('_');

    if (fnCache) {
      const cached = fnCache.get(cacheKey);
      if (cached) {
        return cached;
      }
    } else {
      fnCache = new Map();
      cache.set(fn, fnCache);
    }

    const newValue = fn(...args);

    fnCache.set(cacheKey, newValue);

    return newValue;
  };
}

function prepareTauriConfig() {
  const config = {
    build: {
      frontendDist: process.env.BASE_URL,
      devUrl: null,
    },
    bundle: {
      windows: {},
    },
    identifier: 'org.telegram.TelegramAir',
  };

  if (process.env.WITH_UPDATER === 'true') {
    config.plugins = {
      updater: {
        dialog: false,
        // The endpoint is the `latest.json` asset of the latest GitHub Release;
        // the Gist URL stays as a fallback for legacy manifests.
        endpoints: [process.env.UPDATER_ENDPOINT || process.env.UPDATER_GIST_URL],
        pubkey: process.env.UPDATER_PUBLIC_KEY,
      },
    };

    config.bundle.createUpdaterArtifacts = true;
  }

  if (process.env.KEYPAIR_ALIAS) {
    // eslint-disable-next-line @stylistic/max-len
    config.bundle.windows.signCommand = `smctl.exe sign --keypair-alias=${process.env.KEYPAIR_ALIAS} --simple --input %1`;
