function buildCustomEmojiHtml(emoji: ApiSticker) {
  const className = buildClassName(
    'custom-emoji',
    'emoji',
    'emoji-small',
    'placeholder',
    emoji.shouldUseTextColor && 'colorable',
  );

  return buildCustomEmojiElementHtml(className, emoji.emoji, emoji.id);
