function getCustomEmojiSize(maxEmojisInLine?: number): number | undefined {
  if (!maxEmojisInLine) return undefined;

  // Should be the same as in _message-content.scss
  if (maxEmojisInLine > EMOJI_SIZES) return 2.25 * REM;
  if (maxEmojisInLine === 1) return 7 * REM;
  return Math.min(7.5 - (maxEmojisInLine * 0.75), 5.625) * REM;
}

function buildCustomEmojiElementHtml(
  className: string,
  alt: string | undefined,
  documentId: string,
) {
  const img = document.createElement('img');

  img.setAttribute('class', className);
  img.setAttribute('draggable', 'false');
  img.setAttribute('alt', alt || '');
  img.setAttribute('data-document-id', documentId);
  img.setAttribute('src', placeholderSrc);

  return img.outerHTML;
}

function parseInlineBotQuery(text?: string) {
  const match = text?.match(/^@([a-z0-9_]{1,32})[\u00A0\u0020]+(.*)$/is);
  return match ? { username: match[1], query: match[2] } : undefined;
}

function buildSuggestionRenderer(
  surface: RichEditorTooltipSurface,
  getController: GetTooltipController,
) {
  return {
    onStart: (props: RichEditorTooltipSuggestion) => getController()?.updateSuggestion(surface, props),
    onUpdate: (props: RichEditorTooltipSuggestion) => getController()?.updateSuggestion(surface, props),
    onExit: () => getController()?.removeSuggestion(surface),
    onKeyDown: ({ event }: { event: KeyboardEvent }) => (
      getController()?.handleSuggestionKeyDown(surface, event) || false
    ),
  };
}

function hasUnsuitableContext($position: ResolvedPos) {
  for (let depth = $position.depth; depth > 0; depth--) {
    const node = $position.node(depth);
    if (isUnsuitableNode(node.type.name) || node.type.spec.code) {
      return true;
    }
  }

  return false;
}

function isUnsuitableNode(typeName: string) {
  return typeName === 'codeBlock'
    || typeName === 'mathBlock'
    || typeName === 'mathInline'
    || typeName === 'mention'
    || typeName === 'customEmoji';
}

function buildBlockMatch($position: ResolvedPos, text: string, query: string) {
  return {
    range: { from: $position.pos - text.length, to: $position.pos },
    query,
    text,
  };
}

function getSolePlainTextAtCaret($position: ResolvedPos) {
  if (
    $position.depth !== 1
    || !$position.parent.isTextblock
    || $position.parentOffset !== $position.parent.content.size
    || $position.node(0).childCount !== 1
    || hasUnsuitableContext($position)
  ) {
    return undefined;
  }

  let isPlainText = true;
  $position.parent.forEach((node) => {
    isPlainText &&= node.isText && !node.marks.length;
  });
  return isPlainText ? $position.parent.textContent : undefined;
}

function animateHorizontalScroll(container: HTMLElement, left: number, duration = DEFAULT_DURATION) {
  if (!selectCanAnimateInterface(getGlobal())) {
    duration = 0;
  }

  const isRtl = container.getAttribute('dir') === 'rtl';
  const {
    scrollLeft, offsetWidth: containerWidth, scrollWidth, dataset: { scrollId },
  } = container;

  let path = left - scrollLeft;

  if (path < 0) {
    const remainingPath = -scrollLeft * (isRtl ? -1 : 1);
    path = Math.max(path, remainingPath);
  } else if (path > 0) {
    const remainingPath = scrollWidth - (scrollLeft + containerWidth);
    path = Math.min(path, remainingPath);
  }

  if (path === 0) {
    return Promise.resolve();
  }

  if (scrollId && stopById.has(scrollId)) {
    stopById.get(scrollId)!();
  }

  const target = scrollLeft + path;

  return new Promise<void>((resolve) => {
    requestMutation(() => {
      if (duration === 0) {
        container.scrollLeft = target;
        resolve();
        return;
      }

      let isStopped = false;
      const id = Math.random().toString();
      container.dataset.scrollId = id;
      stopById.set(id, () => {
        isStopped = true;
      });

      container.style.scrollSnapType = 'none';

      const startAt = Date.now();

      function cleanup() {
        container.style.scrollSnapType = '';
        delete container.dataset.scrollId;
        stopById.delete(id);
      }

      animate(() => {
        if (isStopped) {
          cleanup();
          return false;
        }

        const t = Math.min((Date.now() - startAt) / duration, 1);

        const currentPath = path * (1 - transition(t));
        container.scrollLeft = Math.round(target - currentPath);

        if (t >= 1) {
          cleanup();
          resolve();
        }

        return t < 1;
      }, requestMutation);
    });
  });
}

function cleanup() {
        container.style.scrollSnapType = '';
        delete container.dataset.scrollId;
        stopById.delete(id);
      }

function transition(t: number) {
  return 1 - ((1 - t) ** 3.5);
}

