function canRenderCompactMediaPreview(
  media?: MediaContent,
  attachment?: ApiAttachment,
) {
  const photo = media?.photo;
  const document = media?.document;
  const previewUrl = getPreviewUrl(photo, document, media?.video, attachment);
  const video = media?.video || attachment?.gif;
  const shouldRenderPreviewAsVideo = shouldUseVideoPreview(video, previewUrl);
  const previewVideoUrl = shouldRenderPreviewAsVideo
    ? (media?.video?.blobUrl || attachment?.blobUrl)
    : undefined;
  const previewHash = getPreviewHash(photo, document, video, shouldRenderPreviewAsVideo);

  return Boolean(
    previewUrl
    || previewVideoUrl
    || previewHash
    || getThumbDataUri(photo, document, media?.video, attachment),
  );
}

function getEphemeralMessageId(id: number) {
  return MAX_EPHEMERAL_MESSAGE_ID - (id >>> 0);
}

function getMtpEphemeralMessageId(id: number) {
  return (MAX_EPHEMERAL_MESSAGE_ID - id) | 0;
}

function getMessageKey(message: ApiMessage | ApiSponsoredMessage): MessageKey {
  const {
    chatId,
  } = message;

  if ('randomId' in message) {
    return buildMessageKey(chatId, Number(message.randomId));
  }
  return buildMessageKey(chatId, message.previousLocalId || message.id);
}

function getMessageServerKey(message: ApiMessage): MessageKey | undefined {
  if (isLocalMessageId(message.id)) {
    return undefined;
  }
  const { chatId, id } = message;
  return buildMessageKey(chatId, id);
}

function buildMessageKey(chatId: string, msgId: number): MessageKey {
  return `msg${chatId}-${msgId}`;
}

function parseMessageKey(key: MessageKey) {
  const match = key.match(/^msg(-?\d+)-(\d+)/)!;

  return { chatId: match[1], messageId: Number(match[2]) };
}

function isLocalMessageId(id: number) {
  return !Number.isInteger(id);
}

