function animateOpening(isArchived?: boolean) {
  cancelDelayedCallbacks();

  const {
    container, toggler, leftMainHeader, ribbonPeers, toggleAvatars,
  } = getHTMLElements(isArchived);

  if (!toggler || !toggleAvatars || !ribbonPeers || !container || !leftMainHeader) {
    return;
  }

  const containerRect = container.getBoundingClientRect();
  const { bottom: headerBottom, right: headerRight } = leftMainHeader.getBoundingClientRect();
  const toTop = headerBottom + RIBBON_OFFSET - containerRect.top;

  // Toggle avatars are in the reverse order
  const lastToggleAvatar = toggleAvatars[0];
  const firstToggleAvatar = toggleAvatars[toggleAvatars.length - 1];
  const lastId = getPeerId(lastToggleAvatar);

  Array.from(ribbonPeers).reverse().forEach((peer, index, { length }) => {
    const id = getPeerId(peer);
    if (!id) return;
    const isLast = id === lastId;
    let toggleAvatar = selectByPeerId(toggler, id);
    let zIndex = RIBBON_Z_INDEX + index + 1;
    if (!toggleAvatar) {
      const isSelf = index === length - 1;

      // Self story should appear from the first toggle avatar
      toggleAvatar = isSelf ? firstToggleAvatar : lastToggleAvatar;
      zIndex = RIBBON_Z_INDEX;
    }

    if (!toggleAvatar) return;

    let {
      top: fromTop,
      left: fromLeft,
      width: fromWidth,
    } = toggleAvatar.getBoundingClientRect();

    fromTop -= containerRect.top;
    fromLeft -= containerRect.left;

    const peerBounds = peer.getBoundingClientRect();
    const toLeft = peerBounds.left - containerRect.left;
    const toWidth = peerBounds.width;

    if (toLeft > headerRight) {
      return;
    }

    fromLeft -= STROKE_OFFSET;
    fromWidth += 2 * STROKE_OFFSET;

    const fromTranslateX = fromLeft - toLeft;
    const fromTranslateY = fromTop - toTop;
    const fromScale = fromWidth / toWidth;

    fromTop -= STROKE_OFFSET;

    const toTranslateX = toLeft - fromLeft + 2 * STROKE_OFFSET;
    const toTranslateY = toTop - fromTop + STROKE_OFFSET;
    const toScale = toWidth / (fromWidth + 2 * STROKE_OFFSET);

    requestMutation(() => {
      if (!toggleAvatar) return;
      const ghost = createGhost(peer);

      let ghost2: HTMLElement | undefined;

      // If this is a toogle avatar we create a second ghost and do crossfade animation
      if (zIndex > RIBBON_Z_INDEX) {
        ghost2 = createGhost(toggleAvatar);
        if (isLast) {
          ghost2.classList.add(togglerStyles.ghostLast);
        }
      } else {
        // Else we animate only name
        ghost.classList.add(togglerStyles.ghostAnimateName);
      }

      applyStyles(ghost, {
        top: `${toTop}px`,
        left: `${toLeft}px`,
        zIndex: String(zIndex),
        opacity: ghost2 ? '0' : '',
        transform: `translate3d(${fromTranslateX}px, ${fromTranslateY}px, 0) scale(${fromScale})`,
      });

      if (ghost2) {
        applyStyles(ghost2, {
          top: `${fromTop}px`,
          left: `${fromLeft}px`,
          zIndex: String(zIndex),
        });
      }

      container.appendChild(ghost);
      if (ghost2) {
        container.appendChild(ghost2);
      }
      toggleAvatar.classList.add('animating');
      peer.classList.add('animating');

      requestMutation(() => {
        applyStyles(ghost, {
          opacity: '',
          transform: '',
        });

        if (ghost2) {
          applyStyles(ghost2, {
            opacity: '0',
            transform: `translate3d(${toTranslateX}px, ${toTranslateY}px, 0) scale(${toScale})`,
          });
        } else {
          ghost.classList.add(togglerStyles.ghostRevealName);
        }

        const cb = createDelayedCallback(() => {
          requestMutation(() => {
            if (container.contains(ghost)) {
              container.removeChild(ghost);
            }
            if (ghost2 && container.contains(ghost2)) {
              container.removeChild(ghost2);
            }
            toggleAvatar?.classList.remove('animating');
            peer.classList.remove('animating');

            callbacks.delete(cb);
          });
        }, ANIMATION_DURATION + ANIMATION_END_DELAY);

        callbacks.add(cb);
      });
    });
  });
}

function animateClosing(isArchived?: boolean) {
  cancelDelayedCallbacks();

  const {
    container,
    toggler,
    toggleAvatars,
    ribbonPeers,
    leftMainHeader,
  } = getHTMLElements(isArchived);

  if (!toggler || !toggleAvatars || !ribbonPeers || !container || !leftMainHeader) {
    return;
  }
  const containerRect = container.getBoundingClientRect();
  const { right: headerRight } = leftMainHeader.getBoundingClientRect();
  // Toggle avatars are in the reverse order
  const lastToggleAvatar = toggleAvatars[0];
  const firstToggleAvatar = toggleAvatars[toggleAvatars.length - 1];
  const lastId = getPeerId(lastToggleAvatar);

  Array.from(ribbonPeers).reverse().forEach((peer, index, { length }) => {
    const id = getPeerId(peer);
    if (!id) return;
    const isLast = id === lastId;
    let toggleAvatar = selectByPeerId(toggler, id);
    let zIndex = RIBBON_Z_INDEX + index + 1;
    if (!toggleAvatar) {
      const isSelf = index === length - 1;

      // Self story should appear from the first toggle avatar
      toggleAvatar = isSelf ? firstToggleAvatar : lastToggleAvatar;
      zIndex = RIBBON_Z_INDEX;
    }

    if (!toggleAvatar) return;

    const peerBounds = peer.getBoundingClientRect();

    const fromTop = peerBounds.top - containerRect.top;
    const fromLeft = peerBounds.left - containerRect.left;
    const fromWidth = peerBounds.width;

    let {
      left: toLeft,
      width: toWidth,
      top: toTop,
    } = toggleAvatar.getBoundingClientRect();

    toTop -= containerRect.top;
    toLeft -= containerRect.left;

    if (fromLeft > headerRight) {
      return;
    }

    toLeft -= STROKE_OFFSET;
    toWidth += 2 * STROKE_OFFSET;

    const toTranslateX = toLeft - fromLeft;
    const toTranslateY = toTop - fromTop - CANVAS_OFFSET;
    const toScale = toWidth / fromWidth;

    toTop -= STROKE_OFFSET;

    const fromTranslateX = fromLeft - toLeft + 2 * STROKE_OFFSET;
    const fromTranslateY = fromTop - toTop + STROKE_OFFSET;
    const fromScale = fromWidth / (toWidth + 2 * STROKE_OFFSET);

    requestMutation(() => {
      const ghost = createGhost(peer);
      let ghost2: HTMLElement | undefined;

      if (zIndex > RIBBON_Z_INDEX) {
        ghost2 = createGhost(toggleAvatar);
        if (isLast) {
          ghost2.classList.add(togglerStyles.ghostLast);
        }
      } else {
        ghost.classList.add(togglerStyles.ghostAnimateName, togglerStyles.ghostRevealName);
      }

      applyStyles(ghost, {
        top: `${fromTop}px`,
        left: `${fromLeft}px`,
        width: `${fromWidth}px`,
        zIndex: String(zIndex),
      });

      if (ghost2) {
        applyStyles(ghost2, {
          top: `${toTop}px`,
          left: `${toLeft}px`,
          zIndex: String(zIndex),
          opacity: '0',
          transform: `translate3d(${fromTranslateX}px, ${fromTranslateY}px, 0) scale(${fromScale})`,
        });
      }

      peer.classList.add('animating');
      toggleAvatar.classList.add('animating');

      container.appendChild(ghost);
      if (ghost2) {
        container.appendChild(ghost2);
      }

      requestMutation(() => {
        applyStyles(ghost, {
          opacity: ghost2 ? '0' : '',
          transform: `translate3d(${toTranslateX}px, ${toTranslateY}px, 0) scale(${toScale})`,
        });

        if (ghost2) {
          applyStyles(ghost2, {
            opacity: '',
            transform: '',
          });
        } else {
          ghost.classList.remove(togglerStyles.ghostRevealName);
        }

        const cb = createDelayedCallback(() => {
          requestMutation(() => {
            if (container.contains(ghost)) {
              container.removeChild(ghost);
            }
            if (ghost2 && container.contains(ghost2)) {
              container.removeChild(ghost2);
            }
            peer.classList.remove('animating');
            toggleAvatar.classList.remove('animating');
          });

          callbacks.delete(cb);
        }, ANIMATION_DURATION + ANIMATION_END_DELAY);

        callbacks.add(cb);
      });
    });
  });
}

function getHTMLElements(isArchived?: boolean) {
  let container = document.getElementById('LeftColumn');
  if (container && isArchived) {
    container = container.querySelector<HTMLElement>('.ArchivedChats');
  }
  if (!container) return {};
  const toggler = container.querySelector<HTMLElement>('#StoryToggler');
  const ribbon = container.querySelector<HTMLElement>('#StoryRibbon');
  const leftMainHeader = container.querySelector<HTMLElement>('.left-header');
  const ribbonPeers = ribbon?.querySelectorAll<HTMLElement>(`.${ribbonStyles.peer}`);
  const toggleAvatars = toggler?.querySelectorAll<HTMLElement>('.Avatar');
  return {
    container,
    toggler,
    leftMainHeader,
    ribbonPeers,
    toggleAvatars,
  };
}

function createGhost(sourceEl: HTMLElement) {
  const ghost = sourceEl.cloneNode(true) as HTMLElement;
  ghost.classList.add(togglerStyles.ghost);

  // Avoid source animating class being copied to the ghost
  ghost.classList.remove('animating');

  ghost.draggable = false;
  ghost.oncontextmenu = stopEvent;

  const sourceCanvas = sourceEl.querySelector('canvas');
  if (sourceCanvas) {
    const canvas = ghost.querySelector('canvas');
    canvas?.getContext('2d')?.drawImage(sourceCanvas, 0, 0);
  }

  return ghost;
}

function getPeerId(el: HTMLElement) {
  return el?.getAttribute('data-peer-id');
}

function selectByPeerId(el: HTMLElement, id: string) {
  return el?.querySelector<HTMLElement>(`[data-peer-id="${id}"]`);
}

function createDelayedCallback(callback: NoneToVoidFunction, ms: number) {
  const timeout = setTimeout(callback, ms);

  return () => {
    clearTimeout(timeout);
    callback();
  };
}

function cancelDelayedCallbacks() {
  callbacks.forEach((cb) => cb());
  callbacks.clear();
}

interface ViewTransitionController {
  transitionState: TransitionState;
  startViewTransition: (
    types: VTTypes, domUpdateCallback?: TransitionFunction, minimumAnimationLevel?: AnimationLevel,
  ) => PromiseLike<void> | void;
}

function hasActiveViewTransition(): boolean {
  return hasActiveTransition;
}

function useViewTransition(): ViewTransitionController {
  const parametersRef = useRef<ViewTransitionParameters>();
  const [transitionState, setTransitionState] = useState<TransitionState>('idle');

  useEffect(() => {
    if (transitionState !== 'capturing-old') return;
    const { domUpdateCallback, types } = parametersRef.current || {};

    const onHeavyAnimationEnd = beginHeavyAnimation();
    const transition = document.startViewTransition(async () => {
      setTransitionState('capturing-new');
      if (domUpdateCallback) {
        await domUpdateCallback();
      }
      const deferred = new Deferred<void>();
      requestNextMutation(() => {
        deferred.resolve();
      });
      return deferred.promise;
    });

    types?.getTypes().forEach((type) => {
      transition.types?.add(type);
    });

    transition.finished.then(() => {
      onHeavyAnimationEnd();
      setTransitionState('idle');
      requestMutation(() => {
        cleanUp(types);
      });

      hasActiveTransition = false;
    });

    let isReady = false;

    transition.ready.then(() => {
      isReady = true;
      setTransitionState('animating');
    }).catch((e: unknown) => {
      // eslint-disable-next-line no-console
      console.error('View transition error', e, types?.getTypes());
      setTransitionState('skipped');
      requestMutation(() => {
        cleanUp(types);
      });

      hasActiveTransition = false;
    });

    setTimeout(() => {
      if (!isReady) { // Skip transition if it's not prepared in time
        transition.skipTransition();
      }
    }, SKIP_TIMEOUT);
  }, [transitionState]);

  function startViewTransition(
    types: VTTypes,
    updateCallback?: TransitionFunction,
    minimumAnimationLevel: AnimationLevel = ANIMATION_LEVEL_MED,
  ): PromiseLike<void> | void {
    const global = getGlobal();
    const { animationLevel } = selectSharedSettings(global);
    // Fallback: simply run the callback immediately if view transitions aren't supported.
    if (!IS_VIEW_TRANSITION_SUPPORTED || animationLevel < minimumAnimationLevel) {
      updateCallback?.();
      return;
    }

    if (hasActiveTransition) {
      // eslint-disable-next-line no-console
      console.warn('VT skipped because another transition is already active', types.getTypes());
      updateCallback?.();
      return;
    }

    parametersRef.current = {
      domUpdateCallback: updateCallback,
      types,
    };
    setTransitionState('capturing-old');
    requestMutation(() => {
      document.documentElement.classList.add(VT_CLASS_NAME);
      types.getTypes().forEach((type) => {
        document.documentElement.classList.add(`${VT_TYPE_CLASS_PREFIX}${type}`);
      });
    });

    hasActiveTransition = true;
  }

  return {
    transitionState,
    startViewTransition,
  };
}

function startViewTransition(
    types: VTTypes,
    updateCallback?: TransitionFunction,
    minimumAnimationLevel: AnimationLevel = ANIMATION_LEVEL_MED,
  ): PromiseLike<void> | void {
    const global = getGlobal();
    const { animationLevel } = selectSharedSettings(global);
    // Fallback: simply run the callback immediately if view transitions aren't supported.
    if (!IS_VIEW_TRANSITION_SUPPORTED || animationLevel < minimumAnimationLevel) {
      updateCallback?.();
      return;
    }

    if (hasActiveTransition) {
      // eslint-disable-next-line no-console
      console.warn('VT skipped because another transition is already active', types.getTypes());
      updateCallback?.();
      return;
    }

    parametersRef.current = {
      domUpdateCallback: updateCallback,
      types,
    };
    setTransitionState('capturing-old');
    requestMutation(() => {
      document.documentElement.classList.add(VT_CLASS_NAME);
      types.getTypes().forEach((type) => {
        document.documentElement.classList.add(`${VT_TYPE_CLASS_PREFIX}${type}`);
      });
    });

    hasActiveTransition = true;
  }

function cleanUp(types?: VTTypes) {
  types?.getTypes().forEach((type) => {
    document.documentElement.classList.remove(`${VT_TYPE_CLASS_PREFIX}${type}`);
  });
  document.documentElement.classList.remove(VT_CLASS_NAME);
}

class SortedQueue<T> {
  private queue: T[];

  constructor(private comparator: (a: T, b: T) => number) {
    this.queue = [];
  }

  add(item: T): void {
    const index = this.binarySearch(item);
    this.queue.splice(index, 0, item);
  }

  pop(): T | undefined {
    return this.queue.shift();
  }

  get size(): number {
    return this.queue.length;
  }

  clear(): void {
    this.queue = [];
  }

  private binarySearch(item: T): number {
    let left = 0;
    let right = this.queue.length;

    while (left < right) {
      const middle = Math.floor((left + right) / 2);
      const comparison = this.comparator(item, this.queue[middle]);

      if (comparison === 0) {
        return middle;
      } else if (comparison > 0) {
        left = middle + 1;
      } else {
        right = middle;
      }
    }

    return left;
  }
}

