function searchWords(haystack: string, needle: string | string[]) {
  if (!haystack || !needle) {
    return false;
  }

  const needleWords = typeof needle === 'string' ? needle.toLowerCase().split(RE_NOT_LETTER) : needle;
  const haystackLower = haystack.toLowerCase();

  // @optimization
  if (needleWords.length === 1 && !haystackLower.includes(needleWords[0])) {
    return false;
  }

  let haystackWords: string[];

  return needleWords.every((needleWord) => {
    if (!haystackLower.includes(needleWord)) {
      return false;
    }

    if (!haystackWords) {
      haystackWords = haystackLower.split(RE_NOT_LETTER);
    }

    return haystackWords.some((haystackWord) => haystackWord.startsWith(needleWord));
  });
}

function prepareSearchWordsForNeedle(needle: string) {
  const needleWords = needle.toLowerCase().split(RE_NOT_LETTER);

  return (haystack: string) => searchWords(haystack, needleWords);
}

function useSignalRef<T>(getValue: Signal<T>) {
  const ref = useRef<T>(getValue());

  useEffectOnce(() => {
    return getValue.subscribe(() => {
      ref.current = getValue();
    });
  });

  return ref;
}

function getSelectionAsFormattedText(range: Range) {
  const html = getSelectionAsHtml(range).replace(/<br\s*\/?>/gi, '\n');
  const formattedText = parseHtmlAsFormattedText(html, false, true);

  return stripEntitiesForQuote(formattedText);
}

function captureMessageCopyRequest(
  chatId: string,
  threadId: ThreadId,
  messageListType: MessageListType,
): MessageCopyRequest | undefined {
  const selection = window.getSelection();
  if (!selection?.rangeCount || selection.isCollapsed) return undefined;

  const range = selection.getRangeAt(0);
  const startMessageId = getNodeMessageId(range.startContainer);
  const endMessageId = getNodeMessageId(range.endContainer);
  if (!startMessageId || !endMessageId) return undefined;

  if (startMessageId === endMessageId) {
    return {
      type: 'selection',
      chatId,
      threadId,
      messageListType,
      messageId: startMessageId,
      html: getSelectionAsHtml(range),
    };
  }

  const messageIds = getMessageIdsForSelectedText(range);
  return messageIds?.length ? {
    type: 'messages',
    chatId,
    threadId,
    messageListType,
    messageIds,
    withSenderHeaders: true,
  } : undefined;
}

function getSelectionAsHtml(range: Range) {
  const clonedSelection = range.cloneContents();
  selectionContainer.appendChild(clonedSelection);

  const html = wrapHtmlWithSemanticAncestors(range, selectionContainer.innerHTML);
  selectionContainer.innerHTML = '';

  return html
    .replace(/&nbsp;/gi, ' ') // Convert nbsp's to spaces
    .replace(/\u00a0/gi, ' ');
}

function stripEntitiesForQuote(text: ApiFormattedText): ApiFormattedText {
  if (!text.entities) return text;

  const entities = text.entities.filter((entity) => ALLOWED_QUOTE_ENTITIES.has(entity.type as ApiMessageEntityTypes));
  return { ...text, entities: entities.length ? entities : undefined };
}

function getNodeMessageId(node: Node) {
  const element = node.nodeType === Node.ELEMENT_NODE ? node as HTMLElement : node.parentElement;
  const messageElement = element?.closest<HTMLElement>('.Message[data-message-id]');
  const rawMessageId = messageElement?.dataset.messageId;
  return rawMessageId !== undefined ? Number(rawMessageId) : undefined;
}

function wrapHtmlWithSemanticAncestors(range: Range, html: string) {
  const container = range.commonAncestorContainer;
  let currentElement = container.nodeType === Node.ELEMENT_NODE
    ? container as HTMLElement
    : container.parentElement;
  while (
    currentElement
    && !currentElement.classList.contains('text-content')
    && !currentElement.classList.contains('Message')
    && !currentElement.hasAttribute('data-rich-copy-root')
  ) {
    if (isSemanticCopyElement(currentElement)) {
      const wrapper = currentElement.cloneNode(false) as HTMLElement;
      wrapper.innerHTML = html;
      html = wrapper.outerHTML;
    }
    currentElement = currentElement.parentElement;
  }

  return html;
}

function isSemanticCopyElement(element: HTMLElement) {
  return SEMANTIC_COPY_TAGS.has(element.tagName)
    || element.hasAttribute('data-entity-type')
    || element.hasAttribute('data-rich-block-type')
    || element.hasAttribute('data-rich-text-type');
}

interface State<T> {
  clientsCount: number;
  getter: Signal<T>;
  setter: SignalSetter<T>;
}

function useSelectorSignal<T>(selector: Selector<T>): Signal<T> {
  let state = bySelector.get(selector) as State<T> | undefined;
  if (!state) {
    const [getter, setter] = createSignal(selector(currentGlobal));
    state = { clientsCount: 0, getter, setter };
    bySelector.set(selector, state as State<unknown>);
  }

  useSyncEffect(() => {
    const currentState = bySelector.get(selector);
    if (!currentState) {
      return undefined;
    }

    currentState.clientsCount++;

    // Refresh if selector changed
    const currentValue = selector(currentGlobal);
    if (currentValue !== currentState.getter()) {
      currentState.setter(currentValue);
    }

    return () => {
      currentState.clientsCount--;

      if (!currentState.clientsCount) {
        bySelector.delete(selector);
      }
    };
  }, [selector]);

  return state.getter;
}

function useSelector<T>(selector: Selector<T>) {
  const selectorSignal = useSelectorSignal(selector);
  return useDerivedState(selectorSignal, [selectorSignal, selector]);
}

function useSelectorSignalWithEquality<T>(
  selector: Selector<T>,
  equalityFn: EqualityFn<T>,
) {
  const baseSignal = useSelectorSignal(selector);
  // Initialize with current value
  const [signal, setSignal] = useSignal(baseSignal());
  const lastValueRef = useRef(signal());

  useSyncEffect(() => {
    const checkForUpdate = () => {
      const newValue = baseSignal();
      if (!equalityFn(lastValueRef.current, newValue)) {
        lastValueRef.current = newValue;
        setSignal(newValue);
      }
    };

    checkForUpdate();

    return baseSignal.subscribe(checkForUpdate);
  }, [baseSignal, equalityFn, setSignal]);

  return signal;
}

function useSelectorWithEquality<T>(
  selector: Selector<T>,
  equalityFn: EqualityFn<T>,
) {
  const signal = useSelectorSignalWithEquality(selector, equalityFn);
  return useDerivedState(signal);
}

function useShallowSelectorSignal<T extends AnyLiteral | undefined>(selector: Selector<T>) {
  return useSelectorSignalWithEquality(selector, areShallowEqual);
}

function useShallowSelector<T extends AnyLiteral | undefined>(selector: Selector<T>) {
  return useSelectorWithEquality(selector, areShallowEqual);
}

function updateTopicsInfo<T extends GlobalState>(
  global: T, chatId: string, update: Partial<TopicsInfo>,
) {
  const info = global.chats.topicsInfoById[chatId] || { topicsById: {} };

  global = {
    ...global,
    chats: {
      ...global.chats,
      topicsInfoById: {
        ...global.chats.topicsInfoById,
        [chatId]: {
          ...info,
          ...update,
        },
      },
    },
  };

  return global;
}

function updateListedTopicIds<T extends GlobalState>(
  global: T, chatId: string, topicIds: number[],
): T {
  const listedIds = selectTopicsInfo(global, chatId)?.listedTopicIds || [];
  return updateTopicsInfo(global, chatId, {
    listedTopicIds: unique([
      ...listedIds,
      ...topicIds,
    ]),
  });
}

function updateTopic<T extends GlobalState>(
  global: T, chatId: string, topicId: number, update: Partial<ApiTopic>,
): T {
  const chat = selectChat(global, chatId);

  if (!chat) return global;

  const topic = selectTopic(global, chatId, topicId);
  const oldTopics = selectTopics(global, chatId);

  const safeUpdate = update.isMin ? pick(update, SAFE_MIN_PROPERTIES) : update;

  const updatedTopic = {
    ...topic,
    ...safeUpdate,
    notifySettings: safeUpdate.notifySettings || topic?.notifySettings || update.notifySettings,
  } as ApiTopic;

  if (!updatedTopic.id || !updatedTopic.notifySettings) return global;

  global = updateTopicsInfo(global, chatId, {
    topicsById: {
      ...oldTopics,
      [topicId]: updatedTopic,
    },
  });

  global = updateThreadLocalState(global, chatId, updatedTopic.id, {
    firstMessageId: updatedTopic.id,
  });

  return global;
}

function updateTopicWithState<T extends GlobalState>(
  global: T, chatId: string, topicWithState: ApiTopicWithState,
): T {
  const topicId = topicWithState.topic.id;

  global = updateTopic(global, chatId, topicId, topicWithState.topic);
  if (!topicWithState.topic.isMin) {
    global = updateThreadInfo(global, {
      isCommentsInfo: false,
      chatId,
      threadId: topicId,
      lastMessageId: topicWithState.lastMessageId,
    });
  }
  if (topicWithState.readState) {
    global = updateThreadReadState(global, chatId, topicId, topicWithState.readState);
  }

  return global;
}

function deleteTopic<T extends GlobalState>(
  global: T, chatId: string, topicId: number,
) {
  const topics = selectTopics(global, chatId);
  if (!topics) return global;

  global = updateTopicsInfo(global, chatId, {
    topicsById: omit(topics, [topicId]),
  });

  return global;
}

function replacePinnedTopicIds<T extends GlobalState>(
  global: T, chatId: string, pinnedTopicIds: number[],
) {
  return updateTopicsInfo(global, chatId, {
    orderedPinnedTopicIds: pinnedTopicIds,
  });
}

interface GetFullStateEvent {
  type: 'reqGetFullState';
  localState: SharedState;
}

interface UpdateStateEvent {
  type: 'reqUpdateState';
  update: DiffObject<SharedState>;
}

function initSharedState(localState: SharedState) {
  sharedWorker = new SharedWorker(new URL('./sharedState.worker.ts', import.meta.url), {
    name: APP_NAME,
    type: 'module',
  });

  sharedWorker.port.addEventListener('message', onMessage);
  sharedWorker.port.start();

  sendToWorker({ type: 'reqGetFullState', localState });

  addCallback(onGlobalChange);
}

function onGlobalChange() {
  const global = getGlobal();
  if (global.sharedState === lastSharedState) return;
  if (global.sharedState.isInitial) return;

  updateSharedState(global.sharedState);
}

function onMessage(event: MessageEvent<ClientBoundMessageEvent>) {
  const data = event.data;
  switch (data.type) {
    case 'stateUpdate': {
      const state = deepMerge(lastSharedState, data.update);
      updateGlobal(state);
      break;
    }
    case 'fullState':
      synced = true;
      updateGlobal(data.state);
      break;
  }
}

function destroySharedStatePort() {
  if (!sharedWorker) return;
  sharedWorker.port.removeEventListener('message', onMessage);
  sharedWorker.port.close();
  sharedWorker = undefined;
  removeCallback(onGlobalChange);
}

function updateSharedState(update: SharedState) {
  if (!synced) return;
  const diff = deepDiff(lastSharedState, update);
  lastSharedState = update;
  if (typeof diff === 'symbol') return;

  sendToWorker({ type: 'reqUpdateState', update: diff });
}

function sendToWorker(event: WorkerBoundMessageEvent) {
  if (!sharedWorker) {
    throw new Error('Shared worker not initialized');
  }

  scheduledEvents.add(event);
  sendOnTickEnd();
}

function updateGlobal(update: Partial<SharedState>) {
  let global = getGlobal();
  lastSharedState = {
    ...global.sharedState,
    ...update,
  };

  global = {
    ...global,
    sharedState: lastSharedState,
  };
  setGlobal(global);
}

